local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["quest:1450"] = {n="Gryphon Master Talonaxe",s="Falstad Wildhammer vill inte säga vem som en gång flög med en gammal vän i Explorers' League och skickar dig till gryphonmästaren. Gryphon Master Talonaxe väntar inne i Aerie Peaks voljär.",h="Falstad Wildhammer vill inte säga vem som en gång flög med en gammal vän i Explorers' League och skickar dig...",kw={"aerie peak","voljär","brohann caskbelly","explorers' league","falstad wildhammer","gryphon master talonaxe","rhapsody shindigger","uldaman"},sec={{t="Avvisad",b="Falstad Wildhammer har inget tålamod med någon som skickats hit på uppdrag av en gammal medlem i Explorers' League. Falstad vet inte vem den vännen en gång flög med, och det är gryphonmästaren som sköter flygtilldelningarna. Gryphon Master Talonaxe finns inne i Aerie Peaks voljär, och om du dröjer kvar hos Falstad får du riktiga arbetsuppgifter."},{t="Vad Talonaxe minns",b="Talonaxe minns att han skickade en gryphonryttare för att hjälpa Brohann Caskbelly och har länge haft en förkärlek för Explorers' League, eftersom Talonaxes far hjälpte det första utgrävningsteamet att hitta Uldaman. Ryttaren var Rhapsody Shindigger, som Talonaxe då ansåg vara den bästa."}},faq={{q="Varför skickar Falstad Wildhammer dig till Talonaxe?",a="Falstad vet inte vem vännen i Explorers' League flög med och hänvisar till gryphonmästaren, som sköter flygtilldelningarna.",al={"varför söka upp talonaxe","falstad skickar iväg","vem är talonaxe"}},{q="Var finns Gryphon Master Talonaxe?",a="Gryphon Master Talonaxe finns inne i Aerie Peaks voljär.",al={"var finns talonaxe","talonaxes plats","aerie peaks voljär"}}},fp="23,196,9.344.0,23.283.1,49.141.0,41.56.0"}
P.entries["quest:1451"] = {n="Rhapsody Shindigger",s="Gryphon Master Talonaxe berättar om Rhapsody Shindigger, som en gång var den skickligaste flygaren i voljären. Rhapsody började dricka så mycket att hen fick lämna sin tjänst. Talonaxe har hört att Rhapsody nu har ett bryggarläger öster om voljären, i The Hinterlands.",h="Gryphon Master Talonaxe berättar om Rhapsody Shindigger, som en gång var den skickligaste flygaren i voljären.",kw={"aerie peak","voljär","brohann","gryphon master talonaxe","the hinterlands","rhapsody shindigger"},sec={{t="En fallen flygare",b="Talonaxe betonar att alla dvärgar i voljären älskar ett gott öl, men Rhapsody tog till spriten som en grip tar till skyarna. Ingen kunde flyga som Rhapsody, och det tycker Talonaxe är förbaskat synd. Det första tecknet på problem kom när Rhapsody raglade tillbaka från färden med Brohann, och sedan gick det snabbt utför. Till slut fick Rhapsody lämna sin tjänst. Det senaste ryktet säger att ett bryggarläger nu finns öster om Aerie Peak."}},faq={{q="Vem skickar dig för att hitta Rhapsody Shindigger?",a="Gryphon Master Talonaxe vid Aerie Peak Aviary hänvisar dig till Rhapsody.",al={"vem börjar rhapsody shindigger","vem ger rhapsody-uppdraget","var börjar rhapsody"}},{q="Varför fick Rhapsody Shindigger lämna voljären?",a="Rhapsody tog till spriten som en grip tar till skyarna. Det första tecknet på problem kom när Rhapsody raglade tillbaka från en flygtur med Brohann. Sedan gick det snabbt utför, och Talonaxe fick låta Rhapsody gå.",al={"varför fick rhapsody sparken","vad hände med rhapsody","rhapsody shindiggers bakgrund"}},{q="Var är Rhapsody nu?",a="Talonaxe har hört att Rhapsody nu har ett bryggarläger öster om voljären, i The Hinterlands.",al={"var är rhapsody shindigger","rhapsodys lägerplats","hur hittar man rhapsody"}}},fp="19,249,14.431.0,42.72.0,51.211.0,22.94.0"}
P.entries["quest:1452"] = {n="Rhapsody's Kalimdor Kocktail",s="Rhapsody Shindigger, som finns i The Hinterlands, berättar om vad som hände nere i träsket bara om han får något riktigt starkt att dricka. En Kalimdor Kocktail kräver kräsmagar från Roc i Tanaris samt levrar från Groddoc och Ironfur i Feralas.",h="Rhapsody Shindigger, som finns i The Hinterlands, berättar om vad som hände nere i träsket bara om han får...",kw={"brohann","feralas","groddoc-lever","ironfur-lever","kalimdor kocktail","rhapsody shindigger","kräsmage från roc","tanaris"},sec={{t="En stark drink",b="Rhapsody hälsar Brohanns budbärare välkommen med en hicka. De två var med om ett riktigt äventyr, och berättelsen om vad som hände nere i träsket, som var en allt annat än vacker syn, kommer bara fram med något riktigt starkt att dricka. Rhapsody har ett recept i åtanke, Kalimdor Kocktail, och lovar att berätta allt när den är bryggd."},{t="Ingredienser från Kalimdor",b="Kocktailen kräver tre kräsmagar från Roc i Tanaris, tre Groddoc-levrar från Feralas och tre Ironfur-levrar, också från Feralas. Inte ens Rhapsodys finaste malt är stark nog att möta minnet av den ödesdigra flygturen över träsket."}},faq={{q="Vad vill Rhapsody ha till Kalimdor Kocktail?",a="Tre kräsmagar från Roc, tre Groddoc-levrar och tre Ironfur-levrar. Rhapsody vill ha en stark drink innan han berättar om vad som hände i träsket.",al={"varför kocktail","varför kräsmagar från roc","varför levrar"}},{q="Var kommer ingredienserna ifrån?",a="Kräsmagarna från Roc kommer från Tanaris. Groddoc- och Ironfur-levrarna kommer från Feralas.",al={"var hitta kräsmagar","var finns cocktailingredienser","var finns groddoc"}},{q="Vem skickade dig till Rhapsody Shindigger?",a="Brohann, som Rhapsody kallar en galen dåre, skickade dig. Innan dess berättade Gryphon Master Talonaxe var du kunde hitta Rhapsody.",al={"vem skickade mig till rhapsody","föregående uppdrag","brohan"}}},fp="28,231,13.324.0,25.237.0,50.144.0,35.85.0,36.128.0"}
P.entries["quest:1453"] = {n="Reclaimers' Business in Desolace",s="Reclaimers' Business in Desolace är ett Alliance-uppdrag som leder äventyrare från Ironforge till Desolaces karga ödemarker. Roetten Stonehammer ger uppdraget och skickar rekryter över havet till Nijel's Point, där de ska möta Kreldig Ungor och hjälpa Reclaimers att återvinna förlorade skatter och reliker mot betalning.",h="Reclaimers' Business in Desolace är ett Alliance-uppdrag som leder äventyrare från Ironforge till Desolaces...",kw={"centaur","desolace","ironforge","kreldig ungor","nijel's point","reclaimers","roetten stonehammer","stonetalon"},ang={["faction:Alliance"]="Nijel's Point är Alliance främsta tillflyktsort i västra Kalimdor. Den fungerar som en samlingsplats omgiven av fientliga centaurklaner.",["race:Dwarf"]="Dvärgarnas företagsamhet når även Kalimdors mest dystra hörn, vare sig den tar sig uttryck genom Explorers' Guild eller oberoende bärgningsgrupper som Reclaimers."},sec={{t="En kallelse till ödemarken",b="Medan Ironforge sjuder av hantverkare och dvärgarnas angelägenheter förblir avlägsna Kalimdor en otämjd gränsmark. Roetten Stonehammer fungerar som Reclaimers kontakt i staden. Gruppen vill göra vinst på bortglömda ruiner och karga marker. Han rekryterar ivriga äventyrare som passerar genom den stora bergsstaden. Han varnar dem för att Desolace är en fasansfull vidsträckt trakt som översvämmas av stridande centaurklaner, men också full av lönsamma möjligheter för den som vågar ge sig av."},{t="Nijel's Point och Reclaimers",b="Vägen går långt västerut genom Stonetalon Mountains till norra Desolace, där Alliance håller Nijel's Point, en befäst tillflyktsort högt uppe bland klipporna. Där välkomnar Kreldig Ungor nya medarbetare. Reclaimers bygger på en enkel idé: i den krigshärjade världen förlorar folk ständigt arvegods, magiska artefakter och familjeskatter. Med tillräckligt med beslutsamhet och rätt betalning ser Kreldig och hans medarbetare till att dessa förlorade värdesaker återfinns i vildmarken."}},faq={{q="Vem ger uppdraget?",a="Roetten Stonehammer erbjuder uppdraget i Ironforge. Han hänvisar äventyrare som söker hederligt och lönsamt arbete till Kalimdor för att träffa sin medarbetare.",al={"uppdragsgivare","vem startar reclaimers business","roetten stonehammers plats"}},{q="Var ligger Nijel's Point?",a="Nijel's Point ligger bland klipporna i nordöstra Desolace. När du reser söderut från Stonetalon Mountains in i Desolace följer du klipporna österut tills du hittar den fackelupplysta bergsstigen som slingrar sig upp till Alliance-utposten.",al={"hitta nijel's point","hur tar man sig till nijel's point","nijel's points plats"}},{q="Vilka är Reclaimers?",a="Reclaimers är en vinstinriktad verksamhet som leds av dvärgoperatörer som Kreldig Ungor. De är specialiserade på att återvinna förlorade arvegods, sällsynta antikviteter och magiska reliker från farliga delar av världen åt betalande kunder.",al={"vad är reclaimers","reclaimers-fraktionen","reclaimers-bakgrund"}},{q="Vilka faror väntar i Desolace?",a="Desolace är en torr och dyster ödemark som domineras av stridande centaurstammar, odöda kvarlevor och fientligt djurliv. Regionen sätter erfarna resenärer på prov när de beger sig bortom Stonetalon.",al={"faror i desolace","vad finns i desolace"}},{q="Vem är Kreldig Ungor?",a="Kreldig Ungor är en dvärg stationerad vid Nijel's Point i Desolace. Han samordnar bärgningsuppdrag och relikjakter i regionen och värvar dugliga äventyrare som vågar ta sig an ruinerna och centaurlägren.",al={"kreldig ungors bakgrund","vem är kreldig"}},{q="Behöver jag uppdraget för att göra uppdrag i Desolace?",a="Nej, det är ett valfritt vägledande uppdrag. Du kan resa direkt till Nijel's Point på egen hand, men om du talar med Roetten Stonehammer får du bakgrund och vägbeskrivning innan du ger dig av.",al={"behöver jag det här uppdraget","krävs reclaimers business"}}},fx={["7014e979"]={q="Varför skickar Roetten Stonehammer dig till Desolace?",a="Roetten Stonehammer är Reclaimers kontaktperson i Ironforges trygghet. Hans medarbetare vid Nijel's Point befinner sig på farlig mark i Desolace och behöver stadiga, dugliga händer för att sköta uppdrag. Genom att hänvisa kapabla äventyrare som du till Kreldig Ungor ser Roetten till att deras skattletarföretag har folk och går med vinst trots centaurernas fientliga marker.",al={"varför skicka till desolace","roetten stonehammers motiv","varför hjälpa kreldig ungor"}},f82b8baa={q="Varför rekryterar Roetten Stonehammer äventyrare i stället för att åka själv?",a="En bärgningsverksamhet över flera kontinenter kräver lika mycket ögon och öron i storstäderna som muskler ute i fält. Roetten stannar i Ironforge för att leda nya talanger och förmedla möjligheter, medan han överlåter den mödosamma färden genom Stonetalon Mountains och farorna i Desolace åt härdade resenärer som är redo att riskera livet för pengar.",al={"varför behöver roetten mig","varför åker han inte själv","varför rekrytera äventyrare"}}},fp="32,186,23.266.0,32.378.0,21.113.0,23.202.0,23.180.0,31.144.0,21.177.0,44.127.0"}
P.entries["quest:1454"] = {n="The Karnitol Shipwreck",s="Kreldig Ungor berättar om Karnitol, en magiker som på något vis är adlig i Stormwind. Sjöjättar angrep hans skepp i vattnen nordväst om Desolace, och han lämnade kvar en värdefull kista och teleporterade sig därifrån. Kistan och innehållet måste hittas.",h="Kreldig Ungor berättar om Karnitol, en magiker som på något vis är adlig i Stormwind.",kw={"desolace","ethel rethor","karnitol","kreldig ungor","reclaimers","sjöjättar","skeppsbrott","stormwind"},sec={{t="En adelsmans flykt",b="Efter Reclaimers' Business i Desolace berättar Kreldig Ungor om ett första ärende. Det gäller Karnitol, en magiker som på något vis är adlig i Stormwind. Sjöjättar angrep Karnitols skepp i vattnen nordväst om Desolace. Karnitol och hans tjänare försökte bära en av hans dyrbarare kistor i land, men jättarna vällde fram, och han övergav kistan och teleporterade bort sig själv och sina tjänare. Kistan och innehållet måste hittas och sedan återlämnas till Karnitol i Stormwind. Den ligger längs den norra kusten, i området kring Ethel Rethor."},{t="Vad kistan avslöjar",b="Kistan visar inga vattenskador, men locket har brutits upp, och brännmärken runt kanterna visar att eventuella magiska fällor som skyddade den utlöstes för länge sedan."}},faq={{q="Vem är Karnitol?",a="En magiker som på något vis är adlig i Stormwind. Sjöjättar angrep hans skepp i vattnen nordväst om Desolace.",al={"karnitol","vem är karnitol","vem vill ha kistan"}},{q="Vad hände med Karnitols skepp?",a="Sjöjättar angrep det i vattnen nordväst om Desolace. Karnitol och hans tjänare försökte bära en värdefull kista i land, men jättarna vällde fram, så han lämnade kistan och teleporterade bort sig med sina tjänare.",al={"skeppsbrottets historia","varför sjönk skeppet","sjöjätteattack"}},{q="Vem letar efter kistan?",a="Kreldig Ungor, som säger att Karnitol vill att kistan och dess innehåll ska hittas och återlämnas till honom i Stormwind.",al={"vem ger uppdraget","kreldig ungors roll"}},{q="Var ligger kistan?",a="Längs Desolaces norra kust, i området kring Ethel Rethor.",al={"karnitols kistas plats","var är karnitols kista","ethel rethor kista"}}},fp="22,250,16.559.0,20.160.1,16.110.0,33.211.0,29.105.0,25.70.0"}
P.entries["quest:1455"] = {n="The Karnitol Shipwreck",s="Karnitols kista har brutits upp och är helt tom. Långa, djupa repor på sidorna och locket tyder på att varken en människa eller jätte låg bakom, och du återvänder till Kreldig Ungor vid Nijel's Point.",h="Karnitols kista har brutits upp och är helt tom.",kw={"desolace","karnitol","karnitols kista","kreldig ungor","nijel's point","skeppsvrak"},sec={{t="En tom kista",b="Du undersöker vad som bröt upp kistan. Långa, djupa repor löper längs sidorna och locket. De pekar på något som varken var en människa eller jätte, och de ser inte ut att komma från en dolk eller ett svärd. Kistan är helt tom. Det finns inget mer att göra, så du stänger den och gör dig redo att gå, med vetskapen om att Kreldig Ungor kommer att bli besviken."}},faq={{q="Vad finns i Karnitols kista?",a="Ingenting. Kistan är helt tom.",al={"vad fanns i karnitols kista","är karnitols kista tom","kistans innehåll"}},{q="Vad gjorde märkena på kistan?",a="Långa, djupa repor löper längs sidorna och locket. De tyder på att varken en människa eller jätte låg bakom, och de ser inte ut att komma från en dolk eller ett svärd.",al={"vad öppnade kistan","vem tog lasten","klomärken på kistan"}},{q="Vem rapporterar du till?",a="Kreldig Ungor vid Nijel's Point i Desolace.",al={"vem ska jag lämna in detta till","var finns kreldig ungor","vart ska jag gå härnäst"}},{q="Vad hände före detta?",a="Sökandet efter Karnitols kista, som Kreldig Ungor bad dig utföra.",al={"föregående uppdrag","karnitols skeppsvrakskedja"}}},fp="22,218,14.340.0,32.39.0,33.158.0,21.44.0,22.66.0"}
P.entries["quest:1456"] = {n="The Karnitol Shipwreck",s="Kreldig Ungor tror fortfarande att Karnitols tillhörigheter går att hitta. Längre norrut längs samma kust, vid Ranazjar Isle, håller Slitherblade-nagorna till bland nattalveruiner på havets botten, och Kreldig tror att väskan troligast finns där.",h="Kreldig Ungor tror fortfarande att Karnitols tillhörigheter går att hitta.",kw={"desolace","karnitol","kreldig ungor","ranazjar isle","återkravare","väska","havshäxa","slitherblade","tidjägare"},sec={{t="Ruiner i djupet",b="När sökandet efter Karnitols skeppsvrak fortsätter med den andra delen säger Kreldig Ungor att hoppet inte är ute. Längre norrut längs samma kust, nära Ranazjar Isle, ligger sjunkna nattalveruiner på havsbotten, och Slitherblade-nagorna har sitt hem där. Kreldig bedömer att det är den troligaste platsen för Karnitols väska. Du får en Recovery Diver's Potion."},{t="De starkare nagorna",b="Kreldig tror att en spaningsgrupp som tagit sig så långt söderut måste ha varit stark. När Kreldig letar efter Karnitols tillhörigheter skulle han därför börja med de mäktigare nagorna, tidjägarna och havshäxorna."}},faq={{q="Vem ber dig hitta Karnitols väska?",a="Kreldig Ungor i Desolace.",al={"vem ger det här uppdraget","uppdragsgivare karnitols väska","vem är kreldig ungor"}},{q="Var tror Kreldig att tillhörigheterna finns?",a="Bland de sjunkna nattalveruinerna längre norrut längs kusten, nära Ranazjar Isle, där Slitherblade-nagorna har sitt hem.",al={"var finns karnitols väska","väskans plats","var finns slitherblade-nagorna"}},{q="Vilka nagor föreslår Kreldig att du letar efter först?",a="Tidjägarna och havshäxorna, de starkare nagorna. Kreldig resonerar att en spaningsgrupp som tagit sig så långt söderut måste ha varit mäktig.",al={"vem har väskan","vilka nagor har den","tidjägare eller havshäxa"}},{q="Vad kom före detta?",a="Den andra delen av sökandet efter Karnitols skeppsvrak kommer före detta.",al={"karnitols skeppsvrak uppdragskedja","vilket uppdrag kommer före detta"}}},fp="22,245,17.355.0,17.205.0,40.27.0,44.120.0,48.138.0,22.67.0"}
P.entries["quest:1457"] = {n="The Karnitol Shipwreck",s="Kreldig Ungor skickar dig till Ironforge med Karnitols väska, så att du kan lämna över den till Roetten Stonehammer, som betalar dig för arbetet.",h="Kreldig Ungor skickar dig till Ironforge med Karnitols väska, så att du kan lämna över den till Roetten...",kw={"desolace","ironforge","karnitol","karnitols väska","kreldig ungor","reclaimers","roetten stonehammer"},sec={{t="Tillbaka till Ironforge",b="Kreldig Ungor säger åt dig att ta Karnitols saker tillbaka till Roetten Stonehammer i Ironforge, som betalar dig för arbetet. Med ett skratt tillägger Kreldig att Roetten kanske blir så nöjd att du får frågan om att gå med i Reclaimers på heltid. Du bör ta dig tillbaka försiktigt och utan dröjsmål, eftersom Karnitol har dåligt tålamod, även om han är generös."},{t="I Ironforge",b="Roetten Stonehammer godkänner arbetet med Karnitol i Desolace. Själva kistan var förstörd, men allt som fanns i den är här, och Roetten låter Karnitol avgöra saken. Reclaimers förväntas hitta det som gått förlorat, inte se till att det återlämnas i fint och gott skick. Sedan ser Roetten till att du får betalt."}},faq={{q="Vem ska jag lämna Karnitols väska till?",a="Roetten Stonehammer i Ironforge.",al={"var lämnar jag väskan","lämna in karnitol shipwreck","vem får karnitols väska"}},{q="Vem skickar mig tillbaka till Ironforge?",a="Kreldig Ungor, som berömmer dig för arbetet.",al={"vem ger uppdraget","uppdragsgivare karnitol shipwreck del 4"}},{q="Varför är det viktigt att lämna över väskan snabbt?",a="Kreldig säger att Karnitol har dåligt tålamod, även om han är mycket generös.",al={"varför skynda till ironforge","har karnitol tålamod"}},{q="Vem är Roetten Stonehammer?",a="Reclaimers man i Ironforge. Affärerna går strålande för honom, och han överlåter mindre ärenden åt sina underordnade.",al={"roetten stonehammer bakgrund","vem är roetten"}}},fp="22,139,17.359.0,12.346.1,39.34.0,31.50.0,51.70.0,27.111.0"}
P.entries["quest:1458"] = {n="Reagents for Reclaimers Inc.",s="Kreldig Ungor samlar in reagenter åt gnommagikern Leftwitch, som bor i Kharanos, och Reclaimers har ont om folk. Han vill ha klor och horn från Hatefury-satyrerna i öster innan resten av listan kan påbörjas.",h="Kreldig Ungor samlar in reagenter åt gnommagikern Leftwitch, som bor i Kharanos, och Reclaimers har ont om...",kw={"desolace","hatefury","kharanos","kreldig ungor","leftwitch","reclaimers","roetten","sargeron","satyr"},sec={{t="Leftwitchs lista",b="Efter Reclaimers' Business in Desolace har Kreldig Ungor ett nytt jobb: att hämta reagenter åt Leftwitch, gnommagikern som bor i Kharanos. Roetten tycker att det är lätta pengar, eftersom Reclaimers redan är ute i Desolace, och Kreldig säger att han inte bryr sig om att besättningen har ont om folk."},{t="Horn och klor",b="De första sakerna på listan borde vara enkla nog att få tag på. Kreldig vill att du hämtar tio klor och tio horn från Hatefury-satyrerna i öster, som finns i ruinerna av Sargeron rakt öster om Nijel's Point. När han har dem kan resten av listan påbörjas."}},faq={{q="Vem ber om de här reagenserna?",a="Kreldig Ungor samlar in dem åt en gnommagiker vid namn Leftwitch, som bor i Kharanos. Roetten tycker att det är lätta pengar, eftersom Reclaimers redan är ute i Desolace.",al={"vem är leftwitch","uppdragsgivare för reagenter åt reclaimers inc","vem vill ha reagenserna"}},{q="Var finns Hatefury-satyrerna?",a="Hatefury-satyrerna finns i ruinerna av Sargeron, rakt öster om Nijel's Point.",al={"hatefury-satyrernas plats","var finns hatefury-klor","var finns hatefury-horn"}},{q="Vad vill Kreldig ha från satyrerna?",a="Tio Hatefury-klor och tio Hatefury-horn. När du har dem kan ni gå vidare till nästa saker på Leftwitchs lista.",al={"vad behöver jag samla in","föremål i reagenter åt reclaimers inc","satyrdelar som behövs"}},{q="Vad tycker Kreldig om satyrer?",a="Han kallar dem avskyvärda varelser. Han har hört att de på något sätt är knutna till nattalverna, men tvivlar på det. Enligt honom kommer berättelsen från den enda alv som tog med dem in i kriget för några år sedan, och sedan dess har världen blivit farligare och mer skrämmande.",al={"kreldigs satyrhistoria","är satyrer nattalver"}}},fp="28,226,16.302.0,15.247.0,33.171.0,38.82.0,39.124.0,37.271.0"}
P.entries["quest:1459"] = {n="Reagents for Reclaimers Inc.",s="Nästa sak på Leftwitchs lista åt Kreldig Ungor är gift från scorpashi och skinn från åldrade kodo. Kreldig kan inte säga var man hittar något av dem, eftersom han inte känner Desolace väl.",h="Nästa sak på Leftwitchs lista åt Kreldig Ungor är gift från scorpashi och skinn från åldrade kodo.",kw={"skinn från åldrad kodo","desolace","ironforge","kreldig ungor","leftwitch","reclaimers inc","scorpashigift"},sec={{t="Nästa föremål",b="Efter den första delen av Leftwitchs lista går Kreldig Ungor vidare till nästa föremål. De verkar enkla nog, men instruktionerna är exakta. Magikern vill ha gift från scorpashi, vilka som helst duger, och skinn från kodo, men bara från åldrade kodo. Döende och uråldriga kodo duger inte. Kreldig vill ha sju giftflaskor och tre skinn. Magiker, tänker Kreldig, ber om en del märkliga saker."},{t="Okänd mark",b="Kreldig har ingen aning om var kodo och scorpashi strövar omkring. Kreldig känner knappt till området och har inte haft tid att utforska det."}},faq={{q="Vem ber om de här reagenserna?",a="Leftwitch, en magiker vars lista Kreldig Ungor arbetar sig igenom.",al={"vem vill ha reagenser","vem är leftwitch","kreldigs chef"}},{q="Varför behöver Kreldig hjälp med att hitta de här varelserna?",a="Kreldig känner knappt Desolace och har inte haft tid att utforska området, så han kan inte säga var kodo och scorpashi strövar omkring.",al={"varför kan kreldig inte hämta dem","kreldigs lokalkännedom"}},{q="Går det att använda skinn från vilka kodo som helst?",a="Nej. Leftwitchs anvisningar kräver skinn från åldrade kodo; döende och uråldriga räknas inte.",al={"skinn från valfri kodo","skinn från uråldrig kodo","skinn från döende kodo"}},{q="Vad är scorpashi?",a="Det är skorpionerna som finns över hela Desolace. Leftwitch säger att gift från vilka som helst av dem duger.",al={"scorpashigift","var finns scorpashi"}},{q="Var strövar de åldrade kodo omkring?",a="Hjordar följer stigarna, främst i söder och väster, och många hamnar nära Kodo Graveyard.",al={"plats för åldrade kodo","var finns åldrade kodo"}}},fp="28,175,14.378.0,17.123.0,33.63.0,51.117.0,32.88.0,23.96.0,28.104.0"}
P.entries["quest:146"] = {n="Messenger to Darkshire",s="Messenger to Darkshire avslutar den desperata diplomatiska brevväxlingen mellan Lakeshire och Darkshire. Magistrate Solomons vädjan om militär förstärkning avvisas bestämt av Lord Ello Ebonlocke, vilket blottlägger den bittra sanningen att Stormwind har överlämnat båda städerna åt sina öden.",h="Messenger to Darkshire avslutar den desperata diplomatiska brevväxlingen mellan Lakeshire och Darkshire.",kw={"darkshire","ebonlocke","lakeshire","budbärare","night watch","solomon","stormwind"},ang={["faction:Alliance"]="Det här meddelandet blottlägger de djupa sprickorna som sliter sönder det södra riket, där avlägsna bosättningar i Alliansen finner sig övergivna och försvarslösa.",["race:Human"]="För mänskliga resenärer visar brevväxlingen på ett dystert sätt hur isolerade rikets städer har blivit medan det kungliga hovet ser åt ett annat håll."},sec={{t="En desperat begäran avslås",b="Magistrate Solomon från Redridge hoppades att hans gamle kollega i Duskwood kunde avvara trupper, medan de kämpade mot en anstormning av Blackrock-orcher och gnoller. Men Lord Ello Ebonlockes reaktion gränsar till upprördhet. Darkshire håller nätt och jämnt stånd mot de levande döda, glupska bestarna och den förbannade magi som tränger sig på från skogens alla hörn. Ebonlocke säger rakt ut att Night Watch bara finns eftersom Stormwind först övergav Duskwood. Om Darkshire berövades sina försvarare skulle bosättningen falla innan patrullen ens hunnit korsa skogsbrynet."},{t="Ett mönster av övergivenhet",b="När Solomon läser Ebonlockes svar går rikets hårda verklighet upp för honom. Stormwinds armé lämnade Westfall, övergav Darkshire åt sitt öde och har nu ignorerat Lakeshires vädjanden om hjälp. Solomon tvingas konfrontera det som lokala ledare runt om i riket har börjat viska om: det här är inte bara byråkratisk försummelse eller inkompetens, utan misstänkt förräderi döljer sig i själva hjärtat av Stormwind."}},faq={{q="Varför skickar Lord Ebonlocke inte Night Watch för att hjälpa Lakeshire?",a="Darkshire är belägrat från alla håll av odöda, bestar och ondskefull trolldom. Night Watch är en oregelbunden lokal milis som skapades just för att Stormwind drog tillbaka sina garnisoner. Om Ebonlocke skickade sina vakter till Redridge skulle Darkshire översvämmas av fiender innan trupperna ens hann förbi skogsbrynet.",al={"varför vägrar ebonlocke","varför får lakeshire ingen hjälp av night watch","darkshire vägrar hjälpa"}},{q="Vad inser Magistrate Solomon när han läser svaret?",a="Solomon inser att Lakeshires svåra läge är en del av en kris som omfattar hela riket. Armén har dragit sig tillbaka från Westfall och vakterna har helt försvunnit från Darkshire. Därför misstänker Solomon aktivt förräderi bland Stormwinds ledare, snarare än enkel försummelse.",al={"solomons reaktion","vad inser solomon"}},{q="Vem bildade Night Watch?",a="Night Watch sammansattes av de hårt ansatta invånarna och ledarna i Duskwood, under ledning av Lord Ello Ebonlocke, efter att Stormwinds officiella styrkor övergett området åt mörker och förruttnelse.",al={"night watchs ursprung","vem bildade night watch"}},{q="Vart vänder sig Solomon nu för att få hjälp?",a="Darkshire vägrar att hjälpa till och Westfall har tagits över av Defias Brotherhood. Lakeshire står helt ensamt. Solomon tvingas rikta blicken mot hovet i Stormwind för att ta reda på varför kronan vägrar skydda sina avlägsna territorier.",al={"vad gör solomon härnäst","vem mer kan hjälpa lakeshire"}},{q="Drog Stormwind sig officiellt tillbaka från Duskwood och Westfall?",a="Ja. När mörk magi fördärvade Duskwood och oroligheter bröt ut i Westfall drog Stormwinds reguljära styrkor sig tillbaka. Gränsstäderna tvingades då upprätta lokala miliser som Night Watch och People's Militia för att överleva.",al={"varför lämnade stormwind","stormwind övergav städer"}},{q="Vilken relation har Solomon och Ebonlocke?",a="De är sedan länge kollegor och ämbetsmän som styr rikets gränsstäder. Solomon förlitade sig på deras personliga relation när han bad om trupper, men farorna i Duskwood var så allvarliga att det var omöjligt att tillmötesgå hans begäran.",al={"är solomon och ebonlocke vänner","solomon och ellos relation"}}},fx={ec08915e={q="Varför skickar Lord Ebonlocke dig att överlämna brevet i stället för sina egna vakter?",a="Lord Ebonlocke kan inte avvara en enda medlem ur Night Watch. Mörker och fasansfulla varelser belägrar Darkshire, och varje svärd behövs desperat för att hindra staden från att bli översvämmad. Eftersom du kom från Lakeshire som Magistrate Solomons budbärare kostar det inte Darkshire några av dess dyrbara försvarare att skicka dig tillbaka med hans svar.",al={"varför skicka mig","varför skicka inte night watch","varför anlita en äventyrare"}}},fp="22,292,26.542.0,24.418.1,64.301.0,63.257.0,27.189.0,44.245.0,59.213.0,51.234.0"}
P.entries["quest:1462"] = {n="Earth Sapta",s="Earth Sapta är en påfyllningsritual som Seer Ravenfeather erbjuder i Camp Narache. Unga schamaner som genomgår sin invigning för att möta stenens andar behöver denna brygd för att öppna sin inre syn. Om en novis tappar eller spiller ut sin tillredda brygd innan riten är avslutad, tillreder siaren en ny så att prövningen kan fortsätta.",h="Earth Sapta är en påfyllningsritual som Seer Ravenfeather erbjuder i Camp Narache.",kw={"call of earth","camp narache","brygd","earth sapta","elementar","mulgore","seer ravenfeather","schaman"},ang={["class:Shaman"]="Sapta är grunden för din tidiga träning och fungerar som den andliga katalysator som först öppnar dina ögon för de elementära krafter som leder världen.",["faction:Horde"]="Hordens beroende av schamantraditioner får näring på platser som Mulgore, där stammarnas sierskor tålmodigt fostrar nästa generation andliga ledare.",["race:Tauren"]="Att hedra Jordmodern börjar med att lära sig höra landet, och de äldre i Camp Narache är noga med att ingen ungdom stängs ute från den heliga vägen."},sec={{t="En visionär brygd",b="Schamanens väg börjar med att stämma de dödligas sinnen till krafter bortom den fysiska synförmågan. För att uppfatta landets elementandar måste en invigd dricka en kraftfull ritualbrygd som kallas sapta. Earth Sapta är fylld med naturliga essenser knutna till stenens och jordens element. Den lyfter slöjan mellan den fysiska världen och andeplanet och låter en novis möta Mulgore jordelementarer direkt."},{t="En andra chans att se",b="De andliga konsterna kräver disciplin, men erfarna sierskor vet att unga invigda ofta vacklar eller tappar heliga ingredienser när de ger sig ut i vildmarken. Seer Ravenfeather vakar lugnt i Camp Narache och ser till att varje elev som förlorar sin brygd före mötet vid stenmonumentet kan börja om. Med stilla tålamod ger hon novisen ett nytt kärl så att hen kan möta andarna utan avbrott."}},faq={{q="Vad är Earth Sapta?",a="Earth Sapta är en helig örtberedning som bryggs av äldre schamaner. När en invigd dricker den väcker den de inre sinnena och ger den andliga syn som krävs för att uppfatta och möta jordelementarer, vilka annars är osynliga för vanliga ögon.",al={"vad är sapta","jord-sapta-lore","vad gör brygden"}},{q="Varför behöver en invigd en ny Earth Sapta?",a="Elever som genomgår sina prövningar i vildmarken tappar, spiller ibland ut eller dricker sin brygd för tidigt, innan de når den utsedda heliga platsen. Seer Ravenfeather ger dem en ny dos så att deras andliga träning inte avbryts för gott av ett enkelt misstag.",al={"tappat min sapta","varför få en ny sapta","tappat earth sapta"}},{q="Vem är Seer Ravenfeather?",a="Seer Ravenfeather är en taurenisk andlig vägledare som är stationerad i Camp Narache i Mulgore. Hon övervakar unga taureniska schamaners allra första prövningar och vägleder dem genom deras första möte med jordens andar.",al={"vem är ravenfeather","seer ravenfeather-lore","sierska i camp narache"}},{q="Varför måste schamaner dricka sapta för att se elementarer?",a="Nybörjarschamaner har ännu inte finslipat sitt medfödda band till elementen så att de kan uppfatta dem efter behag. Sapta fungerar som en bro och förändrar drickarens andliga varseblivning tills hen lär sig lyssna till och möta elementen med sin egen kraft.",al={"varför behövs en dryck för att se andar","varför dricka sapta"}},{q="Var äger prövningen med Earth Sapta rum?",a="Ritualprövningen utförs i kullarna på Red Cloud Mesa i Mulgore, nära Camp Narache. Noviser bär brygden till ett heligt stenmonument där de lokala jordandarna bor.",al={"var använder jag sapta","call of earth-plats"}},{q="Använder alla schamaner saptas?",a="Både taureniska och orciska schamantraditioner använder saptas under sina första elementinvigningar. Varje element de möter för första gången, som jord, eld och vatten, har sin egen sapta som hjälper till att stämma schamanens sinnen till just det elementplanet.",al={"använder orcher saptas","är saptas bara för tauren"}}},fx={["5f71bc62"]={q="Varför ger Seer Ravenfeather dig ännu en Earth Sapta?",a="Seer Ravenfeather har i uppgift att vägleda unga tauren-aspiranter genom deras elementarprövningar. Utan att dricka Earth Sapta kan en aspirant inte tala med jordens ande eller fullborda sin åkallan. Om du tappar bort eller spiller din dryck ger Ravenfeather dig en ny, så att din heliga färd inte avbryts innan du ens når elementaren.",al={"varför ravenfeather earth sapta","seer ravenfeathers motiv","varför ge sapta igen"}}},fp="11,216,19.332.0,24.259.0,23.237.0,47.168.0,25.185.0,48.182.0,51.169.0,25.192.0"}
P.entries["quest:1463"] = {n="Earth Sapta",s="I Valley of Trials kan en novis som tappar bort Earth Sapta be Canaga Earthcaller om en ny. Ersättningen ger den unga schamanen möjlighet att tala med landets andar och en varning om att vaka noga över heliga brygder.",h="I Valley of Trials kan en novis som tappar bort Earth Sapta be Canaga Earthcaller om en ny.",kw={"call of earth","canaga earthcaller","brygd","durotar","earth sapta","shaman","totem","valley of trials"},ang={["class:Shaman"]="Som schamannovis lär du dig disciplin av att tappa bort saptan: kontakt med elementen kräver stadig koncentration och varsamma händer.",["race:Orc"]="Som orch lär du dig schamanismens uråldriga vägar bland Durotars torra klippor och visar din hängivenhet till förfäderna och jorden under dina fötter.",["race:Troll"]="Som Darkspear-troll lär du dig att balansera traditionell loa-dyrkan med direkt vördnad för elementandar i Valley of Trials."},sec={{t="En andra chans med elementen",b="En borttappad Earth Sapta kan avbryta en novis kontakt med stenens och jordens andar. Den elementära brygden tillreds genom särskilda ritualer och tunnar ut slöjan mellan den fysiska världen och andarna. Om en novis tappar bort eller spiller ut den på vägen genom Durotar tillreder Canaga Earthcaller en ny i god tro, men varnar novisen att vara mer aktsam med heliga gåvor."},{t="Canagas vägledning",b="Canaga Earthcaller vakar över de unga schamaner som kommer ut från The Den i Valley of Trials. Han förstår att unga orcher och troll lätt dras med i kaoset under sina första prövningar, men betonar att elementandar inte ser med blida ögon på vårdslöshet. Att ta emot en andra sapta ger en liten läxa i ödmjukhet: jordens gåvor måste vaktas och respekteras."}},faq={{q="Vad är Earth Sapta?",a="Earth Sapta är en särskilt tillredd ceremoniell brygd för schamannoviser. När de dricker den får de andlig syn och kan uppfatta och tala med elementandar av jord som vanliga ögon inte ser.",al={"vad är sapta","användning av earth sapta","saptans syfte"}},{q="Varför erbjuder Canaga Earthcaller det här uppdraget?",a="Canaga Earthcaller erbjuder en ersättning när en novis tappar bort eller förlägger Earth Sapta innan novisen har fullbordat gemenskapsritualen under prövningarna i Call of Earth. Han ger novisen en ny i god tro, så att hen kan slutföra sin andliga uppgift.",al={"varför ger canaga sapta","jag har tappat bort min earth sapta"}},{q="Var äger ritualen rum?",a="Utbytet äger rum i Valley of Trials, en solstekt kanjon i sydvästra Durotar där unga orcher och troll inleder sina resor mot disciplin och heder.",al={"var finns canaga","earth sapta-plats i valley of trials"}},{q="Ser andarna illa på att man tappar bort saptan?",a="Canaga påminner noviserna om att vårdslös hantering av heliga brygder visar bristande fokus. En sann schaman måste behandla varje elementär gåva med största vördnad.",al={"spelar det någon roll om man tappar bort saptan","lore om att tappa bort saptan"}},{q="Vem kan genomföra denna kommunion?",a="Schamaner som vill stämma sig till sin första elementära totem, Earth Totem, kan tillreda och dricka Earth Sapta.",al={"vem kan få earth sapta","klasser som kan använda sapta"}},{q="Vad händer efter att en lärling dricker saptan?",a="När novisen dricker brygden öppnas hens inre syn, så att hen kan hitta och tala med en lokal uppenbarelse av jordanden, gömd bland klipporna i Valley of Trials.",al={"vad händer när man dricker sapta","efter earth sapta"}}},fp="11,248,33.392.0,17.366.0,23.202.0,45.245.0,34.169.0,47.159.0,33.135.0,48.183.0"}
P.entries["quest:1465"] = {n="Vahlarriel's Search",s="När du fortsätter sökandet i Malems vagn hittar du ett hängsmycke och fotspår som leder söderut. Rök stiger från ett stort fort långt borta. Vahlarriel Demonslayer vid Nijel's Point bör få se hängsmycket och höra tecknet på att Malems kanske lever.",h="När du fortsätter sökandet i Malems vagn hittar du ett hängsmycke och fotspår som leder söderut.",kw={"burning blade","demonjägare","desolace","fästning","malem","nijel's point","hängsmycke","vahlarriel"},sec={{t="Tecken på liv",b="När du söker vidare i vagnen hittar du ett hängsmycke och fotspår som leder söderut. Långt borta stiger rök från ett stort fort. Den kommer från en välskött eld, inte från brinnande byggnader, och dina instinkter säger att om Malems fortfarande lever fördes de åt det hållet."},{t="Besked till Vahlarriel",b="Vahlarriel Demonslayer vid Nijel's Point bör få se Malem Pendant och höra om fotspåren som leder söderut."},{t="Vad lokalbefolkningen säger",b="Vahlarriel är rasande över alltihop. De två Malems varnades för hur farligt Desolace är, och nu är båda försvunna, eller värre. När Vahlarriel hör om spåren mot det närliggande fortet kallar hon det den bästa ledtråden. Enligt lokalbefolkningen är fästningen översvämmad av Burning Blade, orcher som hängivit sig åt demoniska syften. De representerar inte större delen av Horde, men de är onda, och den som ertappas med att spionera på dem dödas på fläcken."}},faq={{q="Vad hittade du i vagnen?",a="Ett hängsmycke och fotspår som leder söderut. I fjärran stiger rök från ett stort fort.",al={"vad finns i kistan","ledtrådar i vagnen","malem pendant"}},{q="Vart leder spåren?",a="Söderut, mot ett stort fort. Röken över det kommer från en välskött eld, inte från brinnande byggnader, vilket tyder på att Malems fördes åt det hållet, om de fortfarande lever.",al={"vart tog fotspåren vägen","var finns fortet","spårens riktning"}},{q="Var finns Vahlarriel Demonslayer?",a="Vahlarriel Demonslayer finns vid Nijel's Point i Desolace. Det är dit hängsmycket och beskedet om spåren ska lämnas.",al={"vahlarriels plats","var lämnar man in malem pendant","vahlarriel demonslayers plats"}}},fp="19,264,13.261.0,19.118.0,19.448.1,31.99.0,25.174.0,40.108.0"}
P.entries["quest:1466"] = {n="Reagents for Reclaimers Inc.",s="Kreldig Ungor har de sista föremålen som Leftwitch vill ha, och han medger att det inte blir trevligt och tar längre tid än de andra. Allt kommer från demoner: hjärnor, vingar och blodflaskor.",h="Kreldig Ungor har de sista föremålen som Leftwitch vill ha, och han medger att det inte blir trevligt och tar...",kw={"desolace","doomwarder-blod","felhundshjärna","kreldig ungor","leftwitch","mannoroc coven","nether-vinge","reclaimers inc"},sec={{t="Det sista på listan",b="Kreldig varnar för att den sista omgången är en dyster historia och tar längre tid att samla in än allt tidigare. Leftwitch vill ha tre sorters delar, tio av varje. Hjärnorna kommer från felhundar: manaätare, magijägare eller leyjägare. Vingarna kommer från nether-maidens, -systrar eller -trollkvinnor. Blodet kommer från doomwarder-kaptener eller -lorder. Kreldig säger att han skulle förstå om du avstod från det här uppdraget."},{t="Demoner i Desolace",b="Kreldig hade inte ens förstått att de här demonerna fanns i Desolace. Enligt det han läst tillhörde Desolace främst centaurerna efter att nattalverna lämnade området för många år sedan, och han undrar hur och varför demonerna slog sig ner här. De håller till nära Mannoroc Coven, i södra Desolace, bortom Kodo Graveyard."}},faq={{q="Vem ber om de här demondelarna?",a="Kreldig Ungor vidarebefordrar Leftwitchs lista, och de här demondelarna är de sista föremålen på den.",al={"vem gav uppdraget","vem vill ha demondelarna","vem är kreldig ungor"}},{q="Vilka varelser har de nödvändiga föremålen?",a="Felhundshjärnor kommer från manaätare, magijägare och leyjägare. Vingarna kommer från nether-maidens, -systrar och -trollkvinnor. Blodet kommer från doomwarder-kaptener och -lorder.",al={"vad släpper felhundshjärnor","var får man tag på nether-vingar","vilka doomwarders har blod"}},{q="Var finns de här demonerna?",a="De samlas nära Mannoroc Coven, längst söderut i Desolace, bortom Kodo Graveyard.",al={"demonernas plats","var ligger mannoroc coven","var strövar demonerna"}},{q="Varför tycker Kreldig att demonerna är överraskande?",a="Han hade läst att centaurerna tog över Desolace när nattalverna lämnade området för många år sedan, så demonernas närvaro förbryllar honom.",al={"varför finns demoner i desolace","centaurernas historia i desolace"}}},fp="28,188,20.389.0,18.291.0,36.92.0,39.177.0,32.92.0,44.116.0"}
P.entries["quest:1467"] = {n="Reagents for Reclaimers Inc.",s="Kreldig Ungor ger dig Leftwitch's package och skickar dig tillbaka till Ironforge. Roetten Stonehammer är den du ska träffa för att få betalt, och Kreldig lovar att tala väl om dig när han kommit hem.",h="Kreldig Ungor ger dig Leftwitch's package och skickar dig tillbaka till Ironforge.",kw={"desolace","ironforge","kreldig ungor","leftwitch's package","reagenser åt reclaimers inc","roetten stonehammer"},sec={{t="Betalning i Ironforge",b="Kreldig säger att din betalning väntar i Ironforge hos Roetten Stonehammer själv. Roetten blir glad över att slippa Leftwitch's package, och det borde räcka att lämna över det för att få det du har rätt till. Kreldig räknar med att stanna i Desolace bara lite längre, och tänker fortfarande tala väl om dig när han kommit hem."},{t="Roettens tack",b="Roetten Stonehammer tar tacksamt emot Leftwitch's package från Desolace och tackar dig för arbetet och för att det gick så snabbt. Din betalning är klar, och Roetten påpekar att en hård arbetsvecka alltid ger bra betalt hos Reclaimers Inc."}},faq={{q="Vem skickar dig tillbaka till Ironforge?",a="Kreldig Ungor skickar dig tillbaka till Ironforge med Leftwitch's package när reagenserna har samlats in.",al={"uppdragsgivare","vem ger uppdraget","vem startar det"}},{q="Vart ska Leftwitch's package?",a="Det ska till Roetten Stonehammer i Ironforge.",al={"var ska jag lämna paketet","paketets destination","vem får paketet"}},{q="Varför bär du paketet till Roetten?",a="Kreldig säger att du får betalt av Roetten själv, så paketet ska till honom i Ironforge.",al={"varför bära paketet","varför besöka roetten"}},{q="Blir Kreldig Ungor kvar i Desolace?",a="Inte särskilt länge till, enligt Kreldig, som fortfarande tänker tala väl om dig när han kommit hem.",al={"lämnar kreldig desolace","vart ska kreldig"}}},fp="28,189,20.296.0,16.225.1,32.99.0,42.44.0,40.90.0,39.95.0"}
P.entries["quest:1469"] = {n="Rhapsody's Tale",s="När Rhapsody Shindigger får sin Kalimdor Kocktail berättar han äntligen om färden genom luften med Brohann Caskbelly. Han lämnar över ett Atal'ai Tablet Fragment och ber att det förs till Brohann i Stormwind.",h="När Rhapsody Shindigger får sin Kalimdor Kocktail berättar han äntligen om färden genom luften med Brohann...",kw={"atal'ai","brohann","caskbelly","fragment","hinterlands","rhapsody","shindigger","stormwind","tavla"},sec={{t="Ett fragment till Brohann",b="Med kocktailen i sig börjar Rhapsody Shindigger äntligen prata. Före färden drack han en hel tunna stout, och Brohann följde efter honom genom skyn. Det enda han har kvar är en trollsouvenir, ett Atal'ai Tablet Fragment, och han vill att det förs till Brohann Caskbelly i Stormwind."},{t="Där färden slutade",b="Rhapsody såg inget tempel från luften. Sedan föll han av sitt riddjur, lite väl berusad, och störtade ner i vattnet. Han drogs ner under ytan och hamnade bland kusliga troll, och simmade snabbt därifrån med en souvenir. Så Brohanns tempel ligger trots allt där nere."}},faq={{q="Vem ska få Atal'ai Tablet Fragment?",a="Rhapsody ber att det förs till Brohann Caskbelly i Stormwind.",al={"vem ska jag ge fragmentet till","var finns brohann","vart ska tavlan"}},{q="Vad minns Rhapsody av färden genom luften med Brohann?",a="Rhapsody drack en hel tunna stout före färden och flög sedan snabbt genom skyn med Brohann efter sig.",al={"varför flög rhapsody","brohann och rhapsody"}},{q="Vad hände före det här steget?",a="Rhapsodys Kalimdor Kocktail kom först. Rhapsody ville inte berätta förrän drycken hade tillretts.",al={"föregående uppdrag","förutsättning för rhapsody's tale"}}},fp="15,209,22.278.0,22.259.1,41.67.0,55.112.0,27.105.0"}
P.entries["quest:147"] = {n="Manhunt",s="Marshal Dughan skickar dig efter en Defias-kurir som kallas the Collector i Elwynn Forest. The Collector håller till i det ockuperade Brackwell Pumpkin Patch och skickar stulet guld från skogens gruvor till Brotherhoods kassakistor.",h="Marshal Dughan skickar dig efter en Defias-kurir som kallas the Collector i Elwynn Forest.",kw={"brackwell pumpkin patch","the collector","defias","goldshire","jakt","marshal dughan","ring","stonemasons guild"},ang={["class:Rogue"]="Som lönnmördare ser du hur the Collectors hemliga arbete speglar det växande nätverket av stråtrövare och ficktjuvar som slår rot i Elwynn Forest.",["faction:Alliance"]="Som medlem i Alliansen hjälper du till att skydda Stormwinds lokala resurser. När du stoppar the Collector stryps ett olagligt flöde av rikets guld som skulle finansiera ett uppror nära huvudstaden.",["race:Human"]="Som människa kanske du känner tyngden i att återbörda Stonemasons ring. Den påminner om de bittra arbetskonflikter som splittrade riket efter att Stormwind återuppbyggdes."},sec={{t="Rättvisa i pumpafältet",b="Marshal Dughan skickar dig till Brackwell Pumpkin Patch när Elwynns gnoller hittas med ett schema för guldtransporter. Defias-banditer och gnoller har tagit över den en gång stillsamma gården. The Collector gömmer sig bland dess igenvuxna vinrankor, lägger beslag på malm från rikets gruvor och ordnar leveranser till det växande upproret."},{t="En hantverkares sigill",b="När the Collector har dödats hittar du hans ring och lämnar den till Marshal Dughan. Marskalken är förbryllad: ringen bär märket från Stormwinds gamla Stonemasons Guild, inte ett vanligt brottslingsemblem. Ringen antyder att stråtrövarna som plågar Elwynn Forest är mer än opportunister. Några var hantverkare som blev bittra och fredlösa efter att Stormwind återuppbyggdes."}},faq={{q="Var hittar jag the Collector?",a="The Collector gömmer sig vid Brackwell Pumpkin Patch i sydöstra Elwynn Forest, strax öster om The Maclure Vineyards och norr om flodgränsen.",al={"the collectors plats","var finns the collector","the collectors tillhåll"}},{q="Varför stjäl the Collector guld från Elwynns gruvor?",a="The Collector samlar in insmugglad malm och utpressningspengar från de koboldinfesterade gruvorna Fargodeep och Jasperlode för att finansiera Defias Brotherhoods hemliga verksamhet runt om i riket.",al={"varför stjäla guld","defias-gruvor","vad gör the collector"}},{q="Vad betyder the Collectors ring?",a="Ringen är en medlemsring från den gamla Stonemasons Guild, vars hantverkare återuppbyggde Stormwind City efter det första kriget. Marshal Dughan kan inte förklara varför en obetydlig tjuv som arbetar med Defias bär en hantverkargillesring, och hoppas att frågan en dag får ett svar.",al={"the collectors ringens historia","stonemasons ring","vad betyder ringen"}},{q="Kommer Marshal Dughan på vem som ligger bakom Brotherhood?",a="Inte genast. Marshal Dughan känner igen hantverkaremblemet på ringen, men kan inte förklara varför en vanlig tjuv bär en hantverkargillets signetring. Den större konspirationen är fortfarande en öppen fråga i Goldshire.",al={"vet dughan","dughans reaktion","marshal dughan stonemasons"}},{q="Vem skickar dig på den här jakten?",a="Marshal Dughan, garnisonsbefälhavaren på Lion's Pride Inn i Goldshire, erbjuder dig uppdraget när du har återfunnit Defias schema för upphämtningar.",al={"vem ger jakten","uppdragsgivare för jakten","marshal dughan-uppdrag"}},{q="Vad hände med familjen Brackwell?",a="Brackwell Pumpkin Patch ligger i ruiner, övergiven av sina ägare och ockuperad av Defias-skurkar, banditer och framryckande Riverpaw-gnoller som stryker omkring i de sydöstra skogarna.",al={"brackwell-historia","vem äger pumpafältet","brackwell-gården"}}},fx={["1901992d"]={q="Varför vill Marshal Dughan att Collector ska stoppas?",a="Guld som rövats från Elwynns gruvor tillhör kungariket Stormwind. Genom att systematiskt föra bort guldet rånar Collector riket och finansierar olaglig verksamhet. Marshal Dughan kan inte låta tjuvar plundra kronans tillgångar obehindrat, särskilt när de stulna mynten tyder på en organiserad konspiration bakom de lokala banditerna.",al={"varför döda collector","marshal dughans motiv i manhunt","varför bryr sig dughan om collector"}},["535c4316"]={q="Vem är Collector, och varför är han vid pumpafältet?",a="Collector är en agent som samarbetar med Defias-tjuvarna för att samla in och transportera olagligt guld från Elwynns gruvor. Han använder det övergivna Brackwell Pumpkin Patch som ett avskilt gömställe och väntar på leveranser enligt upphämtningsschemat innan han smugglar rikets rikedomar ut ur skogen.",al={"vem är collector","varför är collector vid brackwell pumpkin patch","målet i manhunt"}},e23a6feb={q="Varför skickar Marshal Dughan en äventyrare i stället för Stormwinds vakter?",a="Stormwind City Guard och Goldshires garnison är farligt utspridda över Elwynn Forest och upptagna med gnollernas intrång, kobolder i gruvorna och utbredda Defias-banditer. Dughan har helt enkelt inte nog med lediga soldater för att skicka ut en skallgång efter någon vid ett avlägset pumpafält, så han måste förlita sig på kapabla och pålitliga äventyrare.",al={"varför behöver dughan mig","varför skicka äventyrare på manhunt","varför dödar inte vakterna collector"}}},fp="7,224,28.325.0,17.371.1,31.145.0,55.184.0,49.271.1,61.207.1,30.143.0,38.176.0"}
P.entries["quest:1470"] = {n="Piercing the Veil",s="Piercing the Veil är ett inledande prov för häxmästare som Venya Marthand ger i Deathknell. Det prövar en nyväckt häxmästares beslutsamhet genom att be dem samla in dödskallar från närliggande viljelösa skelett. När uppgiften är klar får novisen de kunskaper som krävs för att frammana och binda en imp-tjänare.",h="Piercing the Veil är ett inledande prov för häxmästare som Venya Marthand ger i Deathknell.",kw={"deathknell","imp","piercing the veil","rattlecage skull","tirisfal glades","venya marthand","häxmästare"},ang={["class:Warlock"]="Denna övergångsrit markerar din första verkliga färd in i demonologi och visar den grundläggande lärdomen att kaotisk magi måste böjas för en järnvilja.",["race:Undead"]="Häxmästare bland Forsaken drar nytta av sin kusliga distans till dödligheten för att orädda studera kaotisk och mörk magi i Deathknells skuggor."},sec={{t="En novis första steg",b="Nyväckta häxmästare bland Forsaken inleder sin färd i Deathknell under Venya Marthands ledning. Hon lär dem att sann styrka inte ligger i rå våldskraft, utan i kunskap och exakt behärskning av kaotiska krafter. För att bevisa att de har fokus och förmåga nog att genomborra slöjan mellan världar och kuva varelser från Nether skickas noviserna ut för att skörda dödskallarna från de rastlösa Rattlecage Skeletons som strövar nära Deathknells övergivna smedja."},{t="Att kuva Nether",b="När skelettresterna väl är säkrade anser Venya att novisen är redo att gå bortom enkla mörka besvärjelser. Materialen de hämtat fungerar som en övergångsrit och visar att novisen kan besegra viljelösa odöda och uthärda hantverkets bistra verklighet. I gengäld lär Venya ut ritualerna som krävs för att böja en imp under besvärjarens vilja. Hon varnar för att demonens ringa storlek inte hindrar dess list och eld från att göra den till en farlig bundsförvant."}},faq={{q="Vem ger uppdraget Piercing the Veil?",a="Uppdraget ges av Venya Marthand, häxmästartränaren bland Forsaken i Deathknell i Tirisfal Glades.",al={"vem startar piercing the veil","uppdragsgivare för piercing the veil","venya marthand uppdrag"}},{q="Vad måste du samla in för att slutföra uppdraget?",a="Du måste samla in tre Rattlecage Skulls. De får du genom att besegra Rattlecage Skeletons som strövar nära den förstörda smedjan i Deathknell.",al={"målet för piercing the veil","vad ska jag samla in för piercing the veil","rattlecage skulls"}},{q="Varför vill Venya Marthand ha skelettskallar?",a="Jakten på de viljelösa skeletten prövar novisens kontroll, beslutsamhet och grundläggande magiska förmågor innan Venya anförtror dem farligare demonritualer.",al={"varför rattlecage skulls","syftet med skalluppdraget"}},{q="Vilken kraft eller tjänare lär du dig att frammana?",a="Lektionen förbereder häxmästaren på att frammana och binda en imp, den första demoniska följeslagare som en utövare lär sig att befalla.",al={"belöningsbesvärjelse för piercing the veil","vilken demon får jag","uppdrag för att frammana imp"}},{q="Var finns Rattlecage Skeletons?",a="De strövar i utkanten av Deathknell, särskilt kring den förfallna, övergivna smedjan nordväst om stadens huvudöppning.",al={"rattlecage skeletons plats","var finns skeletten i deathknell","övergiven smedja i deathknell"}},{q="Vem kan ta sig an uppdraget?",a="Endast häxmästare bland Forsaken som har nått rätt nivå av grundläggande träning i Deathknell kan ta sig an uppdraget.",al={"vem kan ta piercing the veil","kan andra klasser göra det här","är det bara för häxmästare"}}},fx={["149b6242"]={q="Vad används Rattlecage Skull till?",a="Venya Marthand använder skallarna som ett prov på din växande förmåga att behärska mörk magi. Häxmästare tror att kunskap och vilja är deras främsta vapen. Att visa att du kan samla in kvarlevor från The Restless Dead bevisar att du har tillräcklig disciplin för att åkalla och binda en imp till din tjänst.",al={"vad används rattlecage-skallar till","varför rattlecage-skallar","rattlecage-skallarnas syfte"}},d722d37c={q="Vilka är Rattlecage-skeletten?",a="Rattlecage-skeletten är viljelösa odöda från Scourge som dröjer sig kvar kring det övergivna smedjan i Deathknell. Liksom stora delar av Tirisfal Glades hemsöks platsen fortfarande av pestens kvarlevor och Lich Kings slagna styrkor. Därför är de lämpliga måltavlor för oerfarna Forsaken-häxmästare som vill pröva sin växande kraft.",al={"vad är rattlecage-skeletten","rattlecage-skeletten i deathknell","varför finns rattlecage-skeletten här"}},d14f3c7d={q="Varför skickar Venya Marthand dig i stället för att sköta det själv?",a="Venya Marthand är din häxmästartränare, inte en legosoldat. Att samla in skallarna är inte ett arbete hon behöver få gjort åt sig, utan en viktig lektion för dig. För att kunna tränga igenom slöjan och böja kaotiska varelser från tomrummet efter din vilja måste du först bevisa din kraft och beslutsamhet på egen hand.",al={"varför jag i piercing the veil","varför ber venya dig hämta skallar","varför kan inte venya marthand hämta dem"}}},fp="17,187,21.343.0,22.253.0,38.76.0,45.94.0,45.155.0,44.107.0,43.138.0,40.84.0"}
P.entries["quest:1471"] = {n="The Binding",s="Binding är den avslutande riten för Forsaken-warlocks som vill behärska en voidwalker. I Magic Quarter i Undercity kräver Carendin Halgar att de invigda åkallar, besegrar och för alltid kuvar en varelse från Void.",h="Binding är den avslutande riten för Forsaken-warlocks som vill behärska en voidwalker.",kw={"carendin halgar","magic quarter","runes of summoning","kuvning","binding","undercity","voidwalker","warlock-uppdrag"},ang={["class:Warlock"]="Den här riten markerar warlockens övergång från småaktiga trick med imps till verklig dominans över väsen som kan uthärda enorma fysiska straff på slagfältet.",["race:Undead"]="För Forsaken är det en naturlig fortsättning på deras motståndskraft och brist på moraliska hämningar kring förbjuden magi att binda en skuggvarelse."},sec={{t="En kuvringsrit",b="Till skillnad från mindre imps, som lätt tvingas in i pakter med mörk magi, avskyr varelser från Void verkligheten och besitter en väldig fysisk styrka. För att få rätten att åkalla en voidwalker måste en blivande warlock i Undercity bevisa att hen kan bemästra den fullständigt. I Magic Quarters skuggiga enklav tillhandahåller Forsaken-mentorn Carendin Halgar de mystiska runor som krävs för att slita en voidwalker från Nether och dra den in i den fysiska världen."},{t="Inom cirkeln",b="Ritualen äger rum i den lysande åkallelsecirkel som ristats in under mentorns upphöjning. När runorna aktiveras materialiseras en obunden voidwalker i raseri. Att kuva den handlar inte om diplomati; åkallaren måste bryta varelsen med ren arkan kraft och obändig vilja. Först när varelsen är fullständigt kuvad avslöjar Carendin den verkliga åkallelseformeln och binder varelsens väsen till utövaren för all framtid."}},faq={{q="Vad är syftet med ritualen?",a="Ritualen prövar en blivande warlocks förmåga att övermanna en varelse från Void. Genom att besegra en obunden voidwalker i strid bevisar åkallaren att hens vilja är stark nog att kontrollera den, vilket gör att Carendin Halgar kan lära hen besvärjelsen för permanent åkallan.",al={"varför utföra binding","vad gör uppdraget binding","belöning för binding"}},{q="Var äger åkallelsen rum?",a="Den äger rum direkt i den lila åkallelsecirkel som ristats in i golvet under Carendin Halgars plattform i Magic Quarter i Undercity.",al={"var åkallar jag en voidwalker","var finns åkallelsecirkeln","återkallelsecirkeln i undercity"}},{q="Vem är Carendin Halgar?",a="Carendin Halgar är den främsta warlock-tränaren i Magic Quarter i Undercity. Han ansvarar för utbildningen och de mörka invigningsriterna för nyuppväckta Forsaken-utövare.",al={"vem är halgar","carendin halgars bakgrund"}},{q="Måste warlocks besegra varje demon de vill åkalla?",a="Warlocks måste hävda sin makt över mäktiga extradimensionella väsen innan de kan befalla dem. Mindre väsen som imps binds med enkla kontrakt och ritualer, men voidwalkers kräver fysisk och magisk övermakt innan de underkastar sig tjänstgöring.",al={"slåss warlocks alltid mot demoner","varför slåss mot voidwalkern"}},{q="Vad händer om en warlock misslyckas med att kuva voidwalkern?",a="En obunden voidwalker kommer obevekligt att slå sönder och förgöra alla i närheten. Som Halgar varnar är det ingenting jämfört med faran att slitas i stycken av den otämjda varelsen i cirkeln om man inte lever upp till hans förväntningar.",al={"vad händer om jag misslyckas med binding","warlockens bakgrund vid misslyckande"}},{q="Vad är en voidwalker?",a="Voidwalkers är skuggvarelser från andra dimensioner som härstammar från Void. De har en enorm fysisk motståndskraft och en medfödd vilja att släcka levande ljus och energi, vilket gör dem till idealiska skydd för utövare av mörk magi.",al={"vad är en voidwalker","voidwalkerns bakgrund"}}},fx={abacfa90={q="Varför vill Carendin Halgar att ritualen genomförs?",a="Carendin Halgar vill odla en mäktig kraft bland Undercitys häxmästare. Genom att tvinga dig att åkalla och helt böja en obunden varelse från tomrummet efter din vilja ser han till att Forsaken-utövare bemästrar verklig underkuvning i stället för att falla offer för de utomjordiska väsen de försöker behärska.",al={"varför carendin halgar i the binding","carendin halgars motiv","varför åkalla en voidwalker"}},["68d93197"]={q="Vad är varelsen du ska åkalla och besegra?",a="Du drar fram en obunden voidwalker direkt från Twisting Nether in i åkallandecirkeln. Voidwalkers är skuggvarelser, formade av ren tomrumsenergi, som är fientliga och avskyr tjänande. De måste besegras med både magi och vapenmakt innan de accepterar en mästares vilja.",al={"vad slåss du mot i the binding","målet i the binding","vem åkallar jag"}},["15849809"]={q="Varför måste du kuva voidwalkern själv i stället för att låta Carendin Halgar göra det?",a="Demonologi kräver personlig dominans. En åkallad demon ger sig bara åt den person som visar den magiska auktoriteten och fysiska styrkan att besegra den. Om Carendin eller stadsvakterna ingrep och kuvade varelsen skulle voidwalkern bindas till deras vilja i stället för din.",al={"varför måste jag slåss mot den","varför hjälper inte carendin","varför jag i uppdraget the binding"}}},fp="11,182,21.365.0,17.383.0,35.213.0,36.142.0,23.171.0,59.255.0,57.203.0,21.231.0"}
P.entries["quest:1472"] = {n="Devourer of Souls",s="Devourer of Souls är ett första steg i en Forsaken-warlocks resa för att kalla fram och binda en succubus. På uppdrag av Carendin Halgar i Temple of the Damned i Undercity måste utövaren tala med hans assistent, Godrick Farsan, för att lära sig locka en sådan varelse från Twisting Nether. Ritualen kräver ett oemotståndligt lockbete: hjärtan från rena och kärleksfulla dödliga.",h="Devourer of Souls är ett första steg i en Forsaken-warlocks resa för att kalla fram och binda en succubus.",kw={"lockbete","carendin halgar","godrick farsan","hearts of the pure","succubus","temple of the damned","undercity"},ang={["class:Warlock"]="Att binda en succubus är en viktig milstolpe i en warlocks utbildning och visar hur man kan utnyttja en demons inneboende laster och begär för att förslava den.",["race:Undead"]="De Forsaken-warlocktränare som verkar i Temple of the Damned saknar moraliska hämningar och behandlar utan vidare levande varelsers renhet och hängivenhet som förbrukningsbara ingredienser i Nether-ritualer."},sec={{t="Lockbete för Nether",b="Carendin Halgar lär ut att en succubus inte bara kan dras över tröskeln på kommando; den måste lockas. Demonen drivs av en omättlig hunger efter att fördärva dygd och förtära dödlig essens, och behöver ett särskilt lockbete. Warlockens strategi bygger på att utnyttja denna enda önskan genom att erbjuda hjärtan från verkligt dygdiga, kärleksfulla män som bete. Halgar hänvisar sina adepter till Godrick Farsan, som vet var sådant sällsynt villebråd kan fångas."},{t="Den blinde assistenten",b="Längre in i Temple of the Damned hjälper Godrick Farsan Carendin med de praktiska förberedelserna för demonisk bindning. Trots att Farsan har förlorat synen hävdar han att hans tillstånd har gett honom en djupare andlig syn, som låter honom uppfatta underliggande andliga strömmar och avlägsna själar med kuslig tydlighet. Han vägleder warlocken till de rena hjärtan som krävs för att locka fram demonen."}},faq={{q="Vad är syftet med det här uppdraget?",a="Det här uppdraget förbinder Carendin Halgars första kallelse med den praktiska jakt som krävs för att binda en succubus. Det skickar warlocken till Godrick Farsan, som beskriver de makabra ingredienser som ritualen kräver.",al={"varför devourer of souls","succubus-uppdrag i undercity","warlock-uppdrag nivå 20"}},{q="Varför behövs rena hjärtan för att kalla fram en succubus?",a="En succubus livnär sig på att fördärva godhet, fresta dödligas hjärtan och sluka dygdiga själar. Carendin Halgar förklarar att demonen inte enkelt kan ta sig in i den här världen utan ett oemotståndligt lockbete, så goda mäns ofördärvade hängivenhet är det perfekta betet för att locka den över.",al={"varför hearts of the pure","succubus-bete lore"}},{q="Vem är Godrick Farsan?",a="Godrick Farsan är en odöd warlock-adept som hjälper Carendin Halgar i Temple of the Damned. Trots att han är fysiskt blind har han mystiska sinnen som låter honom uppfatta andliga sanningar och hitta lämpliga offer i Eastern Kingdoms.",al={"vem är farsan","blind warlock-assistent"}},{q="Var slutförs det här uppdraget?",a="Uppdraget lämnas in direkt i Temple of the Damned i Undercity, bara några steg från Carendin Halgar, där Godrick Farsan står och väntar.",al={"var finns godrick farsan","lämna in devourer of souls"}},{q="Vad händer efter Devourer of Souls?",a="Farsan ger genast uppdraget 'Hearts of the Pure' och skickar warlocken till Wetlands och Greymane Wall i Silverpine Forest för att hämta hjärtana från två dygdiga dödliga.",al={"nästa uppdrag efter devourer of souls","hearts of the pure nästa"}},{q="Kan alla raser utföra den här ritualen?",a="Även om ritualen äger rum i Undercity och lärs ut av Forsaken-utövare kan alla Horde-warlocks som vill binda en succubus genom mentorer i Undercity utföra ritualstegen som Halgar och Farsan lär ut.",al={"vem kan göra devourer of souls","warlock-uppdrag endast för odöda"}}},fx={["99fee797"]={q="Varför vill Carendin Halgar åkalla en succubus?",a="Carendin Halgar övervakar häxmästarnas utveckling i Undercity. En succubus är en varelse av svek, frestelse och illvilja, ett kraftfullt verktyg för att böja fienders vilja och förvandla begär till dödliga svagheter. Carendin vägleder dig genom ritualen så att du kan binda demonen direkt till din vilja. På så vis utökar Forsaken sin mörka arsenal samtidigt som du bevisar att du behärskar Nether.",al={"carendin halgars motiv","varför åkalla succubus med carendin","carendins mål i devourer of souls"}},["2acf7f0a"]={q="Varför skickar Carendin dig i stället för att sköta det själv?",a="Demonisk förslavning kan inte utföras åt en annan magiutövare. En succubus lyder bara den vilja som direkt lockar, binder och kuvar henne. Som mentor vägleder Carendin Halgar dina studier och delar med sig av ritualens grundläggande kunskap, men bara du kan skaffa betet, möta demonen och hävda fullständig kontroll över dess själ.",al={"varför behöver carendin mig","varför jag i devourer of souls","varför häxmästarspelaren en succubus"}}},fp="17,211,18.328.0,19.322.0,34.165.0,52.239.0,22.242.0,30.127.0,35.167.0,35.210.0"}
P.entries["quest:1473"] = {n="Creature of the Void",s="Creature of the Void är en viktig övergångsrit för Forsaken-kriglock, som måste återta en förlorad magisk skrift från Scarlet Crusade. För att lära sig kalla fram och binda en kaotisk voidwalker måste en novis bege sig västerut till Tirisfal Glades och hämta Egalin's Grimoire från fientliga fanatiker.",h="Creature of the Void är en viktig övergångsrit för Forsaken-kriglock, som måste återta en förlorad magisk...",kw={"carendin halgar","egalin","egalin's grimoire","perrine","scarlet crusade","temple of the damned","tirisfal glades","undercity","voidwalker"},ang={["class:Warlock"]="Det här uppdraget markerar övergången från att leka med imps till att kontrollera tunga skuggvarelser i frontlinjen, som kan absorbera enorma mängder fysisk skada.",["faction:Horde"]="De mörka konsterna i Undercity bygger på strikta lärda metoder, som gör farliga krafter från andra plan till tillförlitliga resurser i Hordens gränskrig.",["race:Undead"]="Angreppet mot Scarlet Crusade för att återta mörk kunskap understryker den bittra kampen mellan Forsaken och de levande fanatiker som ockuperar ruinerna i Lordaeron."},sec={{t="En lärares arv",b="I Temple of the Damned mörka nischer i Undercity leder Carendin Halgar utvecklingen av blivande Forsaken-besvärjare. När en akolyt visar sig tillräckligt skicklig för att hantera krafter bortom futtiga imps, leder Halgar dem mot att binda en varelse smidd av ren skugga och kaos: en voidwalker. I stället för att förlita sig på enkel instinkt bygger Forsaken-utövare sina besvärjelser på Egalins noggranna forskning. Egalin var Halgars egen läromästare och skrev först ner ritualerna som krävs för att kuva dessa monstruösa varelser från tomrummet."},{t="Den stulna grimoiren",b="Du kan inte bemästra voidwalkern utan Egalin's Grimoire, som innehåller de exakta metoderna för att kanalisera sådan oberäknelig magi. Men den dyrbara boken stals av en agent från Scarlet Crusade, en fanatiker vid namn Perrine som håller till i ett vakttorn västerut. Perrine och hans korsfarare såg troligen grimoiren som hädisk smuggling att beslagta och gömma undan. Att återta den är avgörande för att Forsaken ska säkra ritualens hemligheter innan de försöker slita upp slöjan."}},faq={{q="Vad är Egalin's Grimoire?",a="Egalin's Grimoire är en magisk handbok skriven av kriglocken Egalin, som undervisade Carendin Halgar. Den beskriver de invecklade kanaliseringsmetoder och besvärjelser som krävs för att bryta igenom till tomrummet och kalla fram en voidwalker under besvärjarens fullständiga kontroll.",al={"egalin's grimoire","vad är boken","vem var egalin"}},{q="Varför stal Scarlet Crusade boken?",a="Scarlet Crusade anser att all demonisk magi och skuggmagi är fördärvad till sin natur. En agent vid namn Perrine kom över grimoiren under en skärmytsling eller infiltration och gömde undan den i ett vakttorn västerut i Tirisfal Glades, till synes ovetande om vilken kraft för att kalla fram varelser den innehöll.",al={"varför tog scarlet crusade den","perrine grimoire","scarlet tower västerut"}},{q="Vem är Carendin Halgar?",a="Carendin Halgar är en mästerlig kriglocktränare som bor i Temple of the Damned i Undercity. Han vägleder nyblivna Forsaken-kriglock och lär dem att respektera oberäkneliga kosmiska krafter och att vara försiktiga, efter egna misstag med besvärjelser.",al={"carendin halgar","kriglocktränare undercity","tränare temple of the damned"}},{q="Vad händer om en kriglock tappar kontrollen över en voidwalker?",a="Voidwalkers är varelser av ren kaos och skugga. Som Carendin Halgar varnar kan varelsen våldsamt slita sin besvärjare i stycken om en novis försöker frammana den utan felfri disciplin och en oböjlig vilja att binda den.",al={"kan en voidwalker döda dig","voidwalker fara","misslyckad besvärjelse"}},{q="Vad händer när grimoiren har återtagits?",a="När Halgar har fått boken studerar han texten och lär dig ritualrunorna. Därefter följer omedelbart 'The Binding', där novisen måste använda en besvärjelsecirkel för att kalla fram en voidwalker och besegra den i närstrid för att hävda sin dominans.",al={"vad händer efter grimoiren","nästa uppdrag","bindningsritual"}},{q="Var ligger Scarlet Crusades utpost?",a="Grimoiren är gömd i ett vakttorn tillhörande Scarlet Crusade, västerut tvärs över Tirisfal Glades. Korsfarare under Perrines befäl vaktar tornet.",al={"var finns perrine","scarlet tower plats","var är boken"}}},fx={["4bce35a3"]={q="Varför vill Carendin Halgar att det här blir gjort?",a="Carendin Halgar ser hur din styrka växer och anser att du är redo att binda en voidwalker. Den farliga konsten kräver exakta ritualer, nedtecknade av hans egen mentor, Egalin. Halgar måste också se till att Scarlet Crusade inte får behålla sådan mörk och mäktig kunskap. Deras fanatiker skulle gärna använda eller förstöra den stulna texten.",al={"halgar motiv","varför återta grimoiren","varför behöver halgar boken"}},b85cee29={q="Vem har Egalin's Grimoire?",a="En agent från Scarlet Crusade vid namn Perrine stal grimoiren och har gömt den i en Scarlet-utpost västerut. Perrine förstår troligen inte den sanna demonologiska kraften i dess dammiga sidor, men zeloterna håller ständig uppsikt där för att bevaka och slå till mot Undercity.",al={"vem stal grimoiren","vem har egalins grimoire","mål för scarlet crusade"}},["9e338ab7"]={q="Varför skickar Carendin Halgar dig i stället för att gå själv?",a="Halgar tjänar som mästerbesvärjare i Temple of the Damned, där han vägleder unga warlocks och övervakar Forsakens mörka hantverk. Än viktigare är att återta grimoiren är ett viktigt prov på din påhittighet och beslutsamhet. En warlock som inte kan återta sina egna verktyg från fanatiska dödliga korsfarare kommer säkert att misslyckas när den försöker kuva en kaotisk varelse från Nether.",al={"varför skicka mig","varför kan inte halgar hämta boken","varför behöver halgar mig"}}},fp="20,212,18.362.0,19.372.0,26.211.0,43.197.0,23.219.0,56.183.0,41.217.1,45.141.0"}
P.entries["quest:1474"] = {n="The Binding",s="The Binding är den sista invigningen på en warlocks väg genom Undercity, där de lär sig att frammana och styra en succubus. Under Carendin Halgars ledning använder utövaren rena hjärtan för att dra en demon från Twisting Nether in i en ritualcirkel och kuva dess vilja genom strid.",h="The Binding är den sista invigningen på en warlocks väg genom Undercity, där de lär sig att frammana och...",kw={"bindningen","carendin halgar","magic quarter","pure hearts","succubus","undercity","warlock"},ang={["class:Warlock"]="Den här riten är ett avgörande steg på din mörka väg och visar att du kan bemästra förföriska mentala krafter och binda listiga avkommor från Nether till din vilja.",["race:Undead"]="Forsaken-utövare ser pragmatiskt på att kuva demoner och använder de mörka redskap som krävs för att säkra sin överlevnad och sitt herravälde i Lordaeron."},sec={{t="Ett prov på viljan",b="I de mörka alkoverna i Magic Quarter finslipar Forsaken-warlocks sin kontroll över demoniska väsen. Att frammana en succubus ses som en viktig övergångsrit. Till skillnad från en voidwalkers råstyrka eller en imps begränsade illvilja använder en succubus förföriska och mentala förtrollningar som kan snärja den som frammanar den. Carendin Halgar kräver att noviser visar att deras sinne och magi är orubbliga innan han litar på dem med permanent herravälde över ett sådant väsen."},{t="Kuvning i cirkeln",b="Med de insamlade Pure Hearts, som samlats från oskyldiga själar i Wetlands och Silverpine Forest, öppnar warlocken en passage till Twisting Nether. Så snart demonen har frammanats i bindningscirkeln går den till angrepp och försöker övermanna eller förtrolla den som frammanat den. Först när warlocken krossar dess fysiska form och kastar dess väsen tillbaka in i tomrummet kan hen hävda fullständig kontroll och vinna kunskapen som krävs för att kalla fram demonen efter behag."}},faq={{q="Vad är syftet med det här uppdraget?",a="Ritualen låter Forsaken-warlocks bevisa sin makt över mäktigare demoner. Genom att frammana och besegra en succubus i Magic Quarter visar warlocken att dess charm inte kan påverka hen och får besvärjelsen som krävs för att frammana och styra en i strid.",al={"varför göra the binding","vad ger the binding för belöning","vad går uppdraget ut på"}},{q="Vem är Carendin Halgar?",a="Carendin Halgar är en warlock-tränare i Magic Quarter i Undercity. Han leder träningen och prövningarna för Forsaken-besvärjare och testar deras mentala uthållighet och mörka konster innan han ger dem farligare frammaningsritualer.",al={"vem ger uppdraget the binding","carendin halgars historia"}},{q="Varför behövdes rena hjärtan för att frammana demonen?",a="Demoner av succubussläktet livnär sig på känslor, renhet och fördärv. Pure Hearts, som samlats in under tidigare uppgifter, fungerar som ett oemotståndligt metafysiskt lockbete och lockar demonen att visa sig direkt i den dödliga världen genom frammaningscirkeln.",al={"varför rena hjärtan","syftet med de rena hjärtana"}},{q="Var äger frammaningen rum?",a="Frammaningen äger rum direkt i Magic Quarter i Undercity, i den särskilda ritualcirkeln nära Carendin Halgar och warlock-mentorerna.",al={"var frambesvärjer jag succubusen","var finns frammaningscirkeln i undercity"}},{q="Varför måste succubusen dödas?",a="Warlocks förhandlar inte med sina tjänare; de kuvar dem. När warlocken krossar demonens form i frammaningscirkeln böjer hen dess ande under sin vilja och ser till att den återvänder som en underdånig träl i stället för en herre.",al={"varför slåss man mot succubusen","varför döda den frammanade succubusen"}},{q="Är succubi farliga för Undercitys warlocks?",a="Ja. Även om Forsaken har stor mental motståndskraft mot rädsla och sömn, varnar Carendin Halgar uttryckligen för att en succubus charm har bundit många starka sinnen. Slarv under ritualen leder till döden eller slaveri.",al={"kan en succubus förtrolla odöda","succubusens farlighet"}}},fx={c35097a2={q="Vad är den frammanade succubusen, och varför är den här?",a="Du kallar en succubus genom tomrummet, direkt till Magic Quarters frammaningscirkel. Succubi är listiga demoner som är skickliga på att förhäxa dödligas sinnen, vilket gör dem till några av de farligaste undersåtarna en warlock kan binda. Den här besten hör inte hemma här. Den har dragits till vår värld enbart av de rena hjärtan du samlade in, så att du kan bryta dess vilja i strid.",al={"vem är den frammanade succubusen","vad slåss jag mot","succubusens mål"}},["8c406b80"]={q="Varför måste du själv frammana och besegra succubusen?",a="Att kuva en demon är ett personligt prov som inte kan delegeras. Carendin Halgar är din mentor, men det krävs att besvärjarens eget sinne och magi krossar demonens försvar för att binda den. Om Halgar eller stadsvakterna ingrep och kuvade succubusen åt dig, skulle demonen aldrig böja sig för din vilja och din auktoritet som warlock skulle förbli ofullständig.",al={"varför kan inte carendin slåss mot succubusen","varför behöver carendin mig","varför jag och succubusen"}}},fp="11,228,14.431.0,25.361.1,34.220.0,23.233.0,48.181.0,36.124.0,39.207.0,44.171.0"}
P.entries["quest:1476"] = {n="Hearts of the Pure",s="Hearts of the Pure är ett kusligt häxmästarprov som Godrick Farsan tilldelar i Undercity på uppdrag av Carendin Halgar. För att förbereda ritualbetet som behövs för att binda en succubus måste en blivande besvärjare spåra upp och slakta två ovanligt rättfärdiga mänskliga män. Deras rena hjärtan är en oemotståndlig frestelse för den demoniska förförerskan som väntar på att bli kallad.",h="Hearts of the Pure är ett kusligt häxmästarprov som Godrick Farsan tilldelar i Undercity på uppdrag av...",kw={"carendin halgar","comar villard","dalin forgewright","godrick farsan","the greymane wall","hearts of the pure","succubus","temple of the damned","thandol span","undercity"},ang={["class:Warlock"]="Denna övergångsrit lär ut att en häxmästare måste lära sig att använda inte bara elände och rädsla som vapen, utan också andras ädelmod, för att binda demoner till sin vilja.",["faction:Alliance"]="Offren är tragiska gestalter bland Alliansen och de mänskliga spillrorna: den ene skyddar svältande flyktingar som Gilneas stängt ute, den andre söker förgäves efter en försvunnen maka i träskmarkerna.",["race:Undead"]="Uppdraget visar Forsakens isande världsbild. De ser utan vidare Lordaerons överlevande och deras bestående dygder som lämplig boskap för rituell slakt."},sec={{t="Bete åt en demon",b="Att binda en succubus kräver förståelse för frestelser som verkar åt båda hållen. Nether-sirenerna jagar begär och fördärv, men inget lockar ut dem ur Twisting Nether lika mycket som ofördärvad dygd som väntar på att korrumperas. Inne i Temple of the Damned delegerar mästerbesvärjaren Carendin Halgar förarbetet till Godrick Farsan, som genomsöker människornas länder efter själar vars godhet förblivit obefläckad och obruten."},{t="Bytet",b="Farsan pekar ut två särskilda dygdemönster. Den första är Dalin Forgewright, en hedervärd man som tar hand om desperata Lordaeron-flyktingar som nekas skydd utanför den förseglade Greymane Wall i södra Silverpine. Den andra är Comar Villard, en trogen make som outtröttligt söker efter sin försvunna hustru i Wetlands förrädiska träskmarker. För en Forsaken-häxmästare gör deras hängivenhet, medkänsla och lojalitet dem till utmärkta offer."},{t="Ett Forsaken-perspektiv",b="Jakten kräver att besvärjaren färdas genom farliga, allianskontrollerade områden och vildmark, och avslutas med att båda männen slaktas. När de blodiga bytena återlämnas till Temple of the Damned konstaterar Carendin Halgar med mörk ironi att en god mans fysiska organ inte verkar skilja sig från kvarlevorna efter vilket lik som helst. Men inom demonologins mörka konster är den andliga renhet som dröjer kvar i deras kött så kraftfull att den kan locka en succubus i fångenskap."}},faq={{q="Varför behöver häxmästare rena hjärtan för att kalla på en succubus?",a="En succubus livnär sig på att korrumpera dödlig oskuld och dygd. För att locka en över Nether och fånga henne i en bindningscirkel behöver Carendin Halgar ett bete som hon inte kan motstå. Hjärtan från genuint rena och osjälviska män utgör en sådan oemotståndlig andlig frestelse.",al={"varför rena hjärtan","succubus-bete i historien","varför döda dalin och comar"}},{q="Vem är Dalin Forgewright?",a="Dalin Forgewright är en hedervärd människa som patrullerar till häst längs de stängda portarna vid Greymane Wall i södra Silverpine Forest. Han har vigt sitt liv åt att ta hand om och skydda Lordaerons fördrivna flyktingar, som avvisades och stängdes ute av kungariket Gilneas.",al={"dalin forgewrights historia","vem är dalin","mannen vid greymane wall"}},{q="Vem är Comar Villard?",a="Comar Villard är en hängiven mänsklig vandrare som letar längs Wetlands norra väg, strax söder om Thandol Span. Till skillnad från vanliga resenärer drivs han helt av sorg och orubblig kärlek och vägrar ge upp sökandet efter sin försvunna hustru.",al={"comar villards historia","vem är comar","mänskligt hjärta i wetlands"}},{q="Vart leder den här uppdragskedjan?",a="När de två hjärtana överlämnas till Carendin Halgar kan han förbereda besvärjelsecirkeln i Temple of the Damned. Detta leder direkt vidare till 'The Binding', där häxmästaren kallar på en succubus och kuvar henne så att hon blir en permanent tjänare.",al={"what comes next","efter hearts of the pure","belöning för succubus-uppdrag"}},{q="Vem ger det här uppdraget?",a="Uppdraget ges av Godrick Farsan, en assistent i Magic Quarter i Undercity, inne i Temple of the Damned. Han visar magiska illusioner av Dalin och Comar för att visa häxmästaren exakt vilka som ska jagas.",al={"vem startar hearts of the pure","godrick farsans uppdrag"}},{q="Varför avfärdar Carendin Halgar hjärtanas utseende?",a="När uppdraget är slutfört konstaterar Carendin med bister likgiltighet att en god mans fysiska hjärta ser nästan likadant ut som vilken annan köttbit som helst. Som odöd utövare av de mörka konsterna betyder fysisk moral föga för honom, utöver dess nytta som magisk ingrediens.",al={"carendins dialog","hjärtats utseende"}}},fx={["4332c870"]={q="Varför vill Godrick Farsan att hjärtana samlas in?",a="Godrick hjälper Carendin Halgar att träna värdiga Forsaken-warlocks. För att frammana och kuva en succubus behöver Halgar sällsynta ledare, närmare bestämt hjärtan från verkligt rena och ädla män vars dygder kan locka en frestelsens demon in i en bindningscirkel. Godrick spårade upp lämpliga mål så att du kunde skörda deras hjärtan och bevisa dina mörka konster.",al={"varför behöver godrick hjärtan","godrick farsans motiv","varför skörda rena hjärtan"}}},fp="18,216,16.318.0,10.396.0,22.377.1,54.241.0,25.241.0,21.191.0,33.188.1,21.219.0,62.196.0"}
P.entries["quest:1478"] = {n="Halgar's Summons",s="Halgar's Summons är en formell order till lovande Forsaken-warlocks som nått en kritisk nivå i sin mörka konst. Mäster Carendin Halgar kräver att de infinner sig i Magic Quarter i Undercity för att inleda krävande avancerad träning. När du svarar på hans kallelse inleds arbetet med att åkalla och binda farliga väsen från Nether.",h="Halgar's Summons är en formell order till lovande Forsaken-warlocks som nått en kritisk nivå i sin mörka...",kw={"ageron kargal","carendin halgar","halgars kallelse","magic quarter","temple of the damned","undercity","voidwalker","warlock"},ang={["class:Warlock"]="Denna övergångsrit förbinder grundläggande träning med verkligt slaveri mellan planen och ställer dig under uppsikt av Undercitys främste mästare i mörka konster.",["race:Undead"]="Forsaken-warlocks jagar skugga och fel med hänsynslös, obunden ambition, och Halgars helgedom visar deras pragmatiska förakt för de levandes försiktighet."},sec={{t="En mästares kallelse",b="När en warlock i närheten av Brill eller Tirisfal-vildmarken visar tillräcklig kontroll över grundläggande felenergier når ryktet Undercitys djupare underjordiska salar. Erfarna utövare som Ageron Kargal håller utkik efter talanger och skickar kallelser till dem som visar verklig potential. Att bli kallad av Carendin Halgar är både ett sällsynt privilegium och ett farligt åtagande. Det visar att enkla imps och obetydliga förbannelser inte längre räcker för utövarens utbildning."},{t="Magic Quarter",b="Halgar leder warlock-riter från de skuggiga delarna av Magic Quarter, nära det olycksbådande altaret som kallas Temple of the Damned. Forsaken-mörkermagiker verkar utan de levandes lättstötthet och moraliska begränsningar, men även de kräver strikt disciplin när de ägnar sig åt åkallan mellan planen. Halgar tolererar varken tvekan eller sentimentalitet. Hans kallelse kräver omedelbar lydnad och full beredskap att möta Twisting Nethers fientliga fasor."}},faq={{q="Vem är Carendin Halgar?",a="Carendin Halgar är den främste warlock-tränaren i Magic Quarter i Undercity. Han leder Forsaken-åkarna i deras mörka utveckling och prövar deras beslutsamhet innan han lär dem att binda mäktiga Nether-varelser.",al={"carendin halgar","mäster halgar","vem är halgar"}},{q="Vem hänvisar mig till Halgar?",a="Ageron Kargal, en etablerad warlock-tränare i Brill, skickar dig vidare efter att ha fått veta att mäster Halgar har intresserat sig personligen för dina framsteg.",al={"vem ger halgars kallelse","ageron kargal","vem ger uppdraget"}},{q="Var hittar jag Carendin Halgar i Undercity?",a="Halgar finns i Magic Quarter i Undercity, nära den mörka plattformen som kallas Temple of the Damned.",al={"halgars plats","var är halgar","halgar i magic quarter"}},{q="Varför är den här kallelsen viktig?",a="Kallelsen markerar övergången från grundläggande besvärjelser till riskfylld demonisk kuvning och inleder särskilt prövningarna som krävs för att binda en Voidwalker i din tjänst.",al={"varför behöver jag uppdraget","uppdragets syfte","vad leder halgars kallelse till"}},{q="Är Halgar villig att lära vem som helst?",a="Halgar riktar särskilt sin uppmärksamhet mot lovande warlocks. Han slösar inte tid på tomt småprat och kräver att varje lärling som förs inför honom har visat sig kunna hantera flyktiga felkonster.",al={"kan vem som helst prata med halgar","halgars krav"}},{q="Vad händer när jag rapporterar till Halgar?",a="När du rapporterar till Halgar prövar han genast din magiska förmåga genom att ge dig uppgifter för att skaffa komponenterna som behövs för att åkalla och binda en skuggvarelse från en annan värld.",al={"what comes next","efter halgars kallelse"}}},fx={["169af240"]={q="Varför skickar Ageron Kargal dig till Carendin Halgar?",a="Ageron Kargal är warlock-mentor i Brill, men din växande skicklighet kräver mer avancerad undervisning än en bylärare kan ge. När en begäran kommer från mäster Carendin Halgar själv om att få träffa dig, hänvisar Ageron dig plikttroget till Undercity. För Ageron stärker det Forsakens mörka konster och hedrar hierarkin bland utövarna i Magic Quarter att hjälpa lovande warlocks vidare.",al={"ageron kargals motiv","varför skicka mig till halgar","varför vill ageron det här"}},be0d43df={q="Varför kallar Carendin Halgar på just dig?",a="Carendin Halgar tar sällan kontakt för att undervisa vilken novis som helst. Du har visat din fallenhet för de mörka konsterna i Tirisfal Glades och nått en avgörande punkt i ditt hantverk, där grundläggande besvärjelser inte längre räcker. Halgar kallar på dig direkt eftersom djupare och mer oberäkneliga krafter kräver personlig handledning av en sann mästare. Det gäller till exempel att nå in i Nether och befalla mäktigare vidunder.",al={"varför behöver halgar mig","varför kallar halgar på mig","varför blir jag inkallad"}}},fp="16,230,17.347.0,17.374.0,23.209.0,25.157.0,46.91.0,30.156.0,34.183.0,39.145.0"}
P.entries["quest:148"] = {n="Supplies from Darkshire",s="Supplies from Darkshire är ett Alliance-uppdrag i Duskwood där eremiten Abercrombie ber förbipasserande resenärer att uträtta ett ärende i Darkshire åt honom. Han påstår att han är för skröplig för att göra den farliga färden genom den hemsökta skogen och söker ett sällsynt material kallat Ghost Hair Thread från Madame Eva.",h="Supplies from Darkshire är ett Alliance-uppdrag i Duskwood där eremiten Abercrombie ber förbipasserande...",kw={"abercrombie","darkshire","duskwood","ghost hair thread","madame eva","supplies from darkshire","the hermit"},ang={["faction:Alliance"]="Alliance-äventyrare som vill hjälpa den hårt ansatta bosättningen Darkshire får ofta springa budärenden åt isolerade eremiter längs de farliga småvägarna.",["profession:Tailoring"]="Vävda föremål bygger oftast på linne eller silke. Därför är Madame Evas hantverk, att spinna eteriskt hår till tråd, en makaber kuriositet för alla skräddare."},sec={{t="En ynklig begäran",b="Eremiten Abercrombie bor isolerad i en stuga norr om Raven Hill Cemetery i västra Duskwood och ser ynklig ut. När resenärer kommer fram beklagar han sin höga ålder och skröpliga kropp och hävdar att han inte skulle överleva färden genom skogen för att köpa varor i Darkshire. Ärendet han ber dig uträtta verkar enkelt: ta dig till torget i byn och tala med Madame Eva för att få en rulle Ghost Hair Thread."},{t="Ett märkligt material",b="När du kommer till Madame Eva visar det sig att Abercrombies önskemål inte alls gäller vanliga sybehör. Madame Eva, den lokala sierskan som spinner märkliga artefakter, har inte Ghost Hair Thread på lager. För att uträtta eremitens ärende måste du få tag på spökhår från Blind Mary, den sorgsna ande som hemsöker en bondgård söder om Darkshire. Den enkla leveransen blir därmed början på en långt mer ondskefull uppgörelse."}},faq={{q="Vem ger uppdraget Supplies from Darkshire?",a="Uppdraget ges av Abercrombie, en eremit som bor i en enslig stuga norr om Raven Hill Cemetery i västra Duskwood.",al={"uppdragsgivare supplies from darkshire","vem startar supplies from darkshire","abercrombies ärende"}},{q="Vem ska jag tala med i Darkshire för att få tag på förnödenheterna?",a="Du måste tala med Madame Eva, som bor i ett hus med utsikt över det centrala torget i Darkshire.",al={"var lämnar man in supplies from darkshire","lämna in supplies from darkshire","madame evas plats"}},{q="Vilket föremål är det Abercrombie letar efter?",a="Abercrombie ber om Ghost Hair Thread, ett ovanligt och makabert material som Madame Eva spinner.",al={"vad vill abercrombie ha","vad är förnödenheterna","abercrombies föremål"}},{q="Har Madame Eva Ghost Hair Thread färdigt?",a="Nej, Madame Eva har inget på lager när du kommer dit. Hon går med på att spinna det åt dig, men bara om du samlar in de spöklika material hon behöver från andar i närheten.",al={"har eva tråd","slutföra supplies from darkshire"}},{q="Vilket uppdrag kommer före Supplies from Darkshire?",a="Förutsättningsuppdraget är The Hermit, som skickar äventyrare från Darkshire för att söka upp Abercrombie i hans ensliga bostad.",al={"förutsättning för supplies from darkshire","uppdrag före supplies from darkshire"}},{q="Vilket uppdrag följer efter Supplies from Darkshire?",a="När du avslutar samtalet med Madame Eva börjar uppdraget Ghost Hair Thread direkt. Du ska ta med en Spectral Comb till spöket Blind Mary och samla in hennes hår.",al={"nästa uppdrag efter supplies from darkshire","uppdrag efter supplies from darkshire"}}},fx={b4c47635={q="Varför behöver Abercrombie förnödenheter från Darkshire?",a="Abercrombie hävdar att han bara är en fattig, skröplig gammal man som lever ute i Duskwoods farliga vildmark och inte kan ta sig den långa, riskfyllda vägen in till staden. Han ber särskilt om Ghost Hair Thread och säger sig behöva vanliga sybehör från Madame Eva för att klara sitt ensamma liv i skogen.",al={"varför förnödenheter från darkshire","varför behöver abercrombie tråd","abercrombie ghost hair thread"}},["2d5a916c"]={q="Varför ber Abercrombie dig hämta tråden i stället för att hämta den själv?",a="Abercrombie vädjar om att han är alldeles för gammal, svag och bräcklig för att våga sig längs de hemsökta, bestbestänkta stigarna mellan sin stuga och Darkshire. Att låta en stark resenär ta sig genom den skuggiga vildmarken åt honom verkar vara hans enda sätt att få tag på det han vill ha från Madame Eva.",al={"varför kan inte abercrombie ta sig till stan","varför jag ska hämta förnödenheter från darkshire","varför hämtar inte abercrombie förnödenheterna själv"}}},fp="23,194,16.332.0,18.314.1,45.97.0,53.83.0,46.78.0,49.139.0,44.78.0,43.135.0"}
P.entries["quest:1480"] = {n="The Corrupter",s="En bit flådd demonhud, tagen från Burning Blade vid Thunder Axe Fortress, luktar ruttet men är förvånansvärt smidig. Röda tecken på något språk täcker ena sidan, och längst ner finns en tydlig symbol som ser ut som en signatur. Maurin Bonesplitter vid Ghost Walker Post kanske kan berätta mer.",h="En bit flådd demonhud, tagen från Burning Blade vid Thunder Axe Fortress, luktar ruttet men är förvånansvärt...",kw={"burning blade","eredun","flådd demonhud","ghost walker post","lord azrethoc","maurin bonesplitter","korrumperaren","thunder axe fortress"},sec={{t="En remsa hud",b="Den trasiga huden stinker av förruttnelse, men går ändå lätt att böja, trots att den verkar torr och skör. När den rullas ut syns röda tecken på ena sidan, ett slags skriftspråk. Längst ner finns en enkel symbol som du tror är en signatur."},{t="Maurins syn",b="Maurin Bonesplitter vid Ghost Walker Post kanske vet mer om huden. Maurin menar att Burning Blade visar hur svaga de är, med dålig magi och liten styrka. All kraft de har kommer från dem de tjänar, inte från någon förståelse för verklig makt och kunskap."},{t="Vad tecknen betyder",b="Maurin känner igen runorna som ett gammalt språk, något likt Eredun men mycket annorlunda i detaljerna. Om Maurin har rätt är huden ett slags kontrakt, och symbolen längst ner är signaturen från en demon, Lord Azrethoc."}},faq={{q="Vad står det på den flådda huden?",a="Röda tecken, ett slags skriftspråk, täcker ena sidan. Längst ner finns en tydlig symbol som ser ut som en signatur. Maurin Bonesplitter vid Ghost Walker Post kanske vet mer.",al={"runor på flådd hud","vad står det på huden","röda tecken på hud"}},{q="Var kommer huden ifrån?",a="Den tas från Burning Blade vid Thunder Axe Fortress i Desolace.",al={"hudens plats","var får man demonhud","hur startar man korrumperaren"}},{q="Vem är Maurin Bonesplitter?",a="Maurin Bonesplitter finns vid Ghost Walker Post i Desolace, och det är dit huden förs.",al={"var finns maurin","maurin bonesplitters plats","vem är maurin"}},{q="Vad tycker Maurin om Burning Blade?",a="Maurin ser dem som svaga, med dålig magi och liten styrka. Enligt Maurin kommer all kraft de har från dem de tjänar.",al={"maurin och burning blade","burning blades kraft"}}},fp="13,308,15.229.0,13.282.0,22.233.1,35.179.0,30.71.0,27.95.0,44.130.0"}
P.entries["quest:1481"] = {n="The Corrupter",s="Maurin Bonesplitter tror att demonherren går att hitta, men först måste alla skydd som hindrar varelsen från att bli skådad brytas. Därför vill Maurin ha skalpen från en Hatefury shadowstalker, som jagas i de gamla ruinerna i nordöstra Desolace.",h="Maurin Bonesplitter tror att demonherren går att hitta, men först måste alla skydd som hindrar varelsen från...",kw={"desolace","hatefury shadowstalker","maurin bonesplitter","sargeron","satyr","skådning","shadowstalker-skalp","the corrupter"},sec={{t="Bryta skydden",b="Maurin Bonesplitter tror att demonherren går att hitta med rätt reagenser. Om herren är så mäktig som Maurin misstänker måste de komma från dödliga varelser, och Maurin är säker på att du antar utmaningen i krigshövdingens namn. Först måste alla skydd som demonen har mot skådning brytas. Därför vill Maurin ha skalpen från en satyr, men bara skalpen från en Hatefury shadowstalker duger. De ska sökas upp i de gamla ruinerna i nordöstra Desolace, nära Sargeron."},{t="Rätt skalp",b="Maurin varnar dig för att ta med fel skalp. Fel reagenser kan leda till dödsfall, eftersom demonherren kan ha reservbesvärjelser som ska döda alla som försöker skåda honom. Maurin tillägger att ödet redan har tillfogat nog med smärta."},{t="När du återvänder",b="Maurin bedömer att skalpen passar för hans besvärjelse. Medan du var borta samlade han in några av de andra reagenser som behövs, och han är nästan redo. Han saknar bara ett fokus, ett föremål som kan frammana demonherrens bild och visa var han befinner sig."}},faq={{q="Vem skickar dig för att hämta skalpen?",a="Maurin Bonesplitter ber om den till en besvärjelse för att hitta demonherren.",al={"uppdragsgivare","vem börjar det här","maurin bonesplitter"}},{q="Varför behöver Maurin särskilt en skalp från en Hatefury shadowstalker?",a="Alla skydd som demonherren har mot skådning måste först brytas. Därför behöver Maurin skalpen från en satyr, och bara skalpen från en Hatefury shadowstalker duger.",al={"varför shadowstalker-skalp","orsak till satyrskalp","varför en satyr"}},{q="Var finns Hatefury shadowstalkers?",a="I de gamla ruinerna i nordöstra Desolace, nära Sargeron.",al={"var finns shadowstalkers","shadowstalker-plats","satyrplats"}},{q="Vilka faror finns med att använda fel reagenser?",a="Maurin varnar för att fel reagenser kan leda till dödsfall. Demonherren kan ha reservbesvärjelser som ska döda alla som försöker skåda honom.",al={"varför rätt skalp","risk med fel reagenser","reservbesvärjelser"}},{q="Var passar det här steget in i sökandet efter demonherren?",a="Det följer efter den första delen av The Corrupter, då du tog med den flådda demonhuden till Maurin.",al={"uppdragskedjans fortsättning","uppdragsordning","vad kommer före det här"}}},fp="13,239,18.495.0,15.256.0,15.221.1,34.68.0,65.155.0,47.56.0,49.147.0,60.93.0"}
P.entries["quest:1482"] = {n="The Corrupter",s="Maurin Bonesplitter vill ha en Oracle Crystal, som nagorna tillverkar åt sina orakel, för att hitta demonherren Azrethoc. Ett vidsträckt korallrev ligger längs kusten åt nordväst. Där bor Slitherblade-nagorna, och de kommer inte att välkomna dig.",h="Maurin Bonesplitter vill ha en Oracle Crystal, som nagorna tillverkar åt sina orakel, för att hitta...",kw={"azrethoc","corrupter","desolace","maurin bonesplitter","nagor","oracle crystal","slitherblade","krigshövding"},sec={{t="En Oracle Crystal",b="Maurin Bonesplitter säger att en Oracle Crystal kan användas för att hitta demonherren Azrethoc, vars signatur fanns på huden du tog med dig. Nagor tillverkar sådana kristaller som deras orakel använder. Längs kusten åt nordväst ligger ett vidsträckt korallrev där nagorna har slagit sig ner nära stranden, och där finns oraklen. Slitherblade där är dödliga och kommer att ta illa upp av ditt intrång, så Maurin uppmanar dig att vara försiktig och snabb."},{t="En gemensam belöning",b="Maurin påpekar att ni båda skulle vinna stort anseende hos krigshövdingen om ni hittade och förstörde Lord Azrethoc. Att samarbeta och skynda sig skulle gynna er båda."}},faq={{q="Varför behöver Maurin Bonesplitter en Oracle Crystal?",a="Han tänker hitta demonherren Azrethoc och ber om en Oracle Crystal för att göra det.",al={"varför oracle crystal","vad är kristallen till för","maurins syfte med kristallen"}},{q="Var hittar man Oracle Crystals?",a="Nagorna tillverkar dem åt sina egna orakel, som finns i det vidsträckta korallrevet nordväst om Maurin, längs kusten.",al={"var hittar man kristallen","oracle crystal plats","var finns slitherblade-oraklen"}},{q="Vilka är Slitherblade?",a="De är nagor som har gjort ett vidsträckt korallrev nära stranden till sitt hem. Maurin kallar dem dödliga och säger att de kommer att ta illa upp av inkräktare.",al={"vad är slitherblade","slitherblade-nagor","vem bor i revet"}},{q="Vem är Azrethoc?",a="Azrethoc är demonherren vars signatur fanns på huden du tog med dig till Maurin. Maurin vill hitta och förgöra honom.",al={"vem är azrethoc","demonherren azrethoc","vilken demon jagar maurin"}},{q="Vad driver Maurin att jaga den här demonen?",a="Maurin säger att ni båda skulle vinna stort anseende hos krigshövdingen om ni hittade och förstörde Lord Azrethoc.",al={"maurins motiv","varför jaga azrethoc","anseende hos krigshövdingen"}}},fp="13,238,17.467.0,14.173.0,52.93.0,36.124.0,25.138.0,16.116.0,41.101.0"}
P.entries["quest:1483"] = {n="Ziz Fizziks",s="Det här uppdraget skickar resande från Ratchet för att undersöka Ziz Fizziks, en missnöjd gobliningenjör som är stationerad på den västra åsen vid Windshear Crag. Ziz tog illa upp när Venture Company anställde en gnomingenjör i hans ställe och hoppade av till Tinkers' Union, där Sputtervalve ställer höga krav.",h="Det här uppdraget skickar resande från Ratchet för att undersöka Ziz Fizziks, en missnöjd gobliningenjör som...",kw={"gerenzo wrenchwhistle","sputtervalve","stonetalon","tinkers' union","venture company","windshear crag","ziz fizziks"},ang={["faction:Horde"]="Hordens äventyrare i Stonetalon Mountains hjälper ofta Tinkers' Union-agenter som Sputtervalve och Ziz att bryta Venture Companys dominans i Windshear Crag.",["profession:Engineering"]="Den hårda fejden mellan Ziz och Gerenzo speglar väl den långvariga och laddade rivaliteten mellan gobliners och gnomers sätt att se på ingenjörskonst."},sec={{t="En fråga om yrkesstolthet",b="Venture Company förlitar sig på hänsynslös exploatering och mekanisk innovation, men för Ziz Fizziks gick företaget för långt när det anställde en gnomingenjör vid namn Gerenzo Wrenchwhistle. Ziz blev djupt förolämpad över att behöva arbeta sida vid sida med en rivaliserande gnom och sökte genast en utväg. Han kontaktade Sputtervalve, en företrädare för Tinkers' Union, och bad om att få flyttas bort från Gerenzos överinseende."},{t="Ur askan i elden",b="Ziz fick en ny tjänst hos Tinkers' Union, men det gav honom inte det bekväma liv han hade väntat sig. Han var stationerad vid den västra kanten av Windshear Crag och upptäckte snart att Sputtervalve är en lika hård slavdrivare som vilken förman som helst på Venture Company. Ändå tycker Ziz att hårt arbete under en krävande goblinchef är långt bättre än att dela verkstad med en gnom."}},faq={{q="Vem är Ziz Fizziks?",a="Ziz Fizziks är en gobliningenjör som tidigare arbetade för Venture Company i Stonetalon Mountains. Han hoppade av till Tinkers' Union efter att hans tidigare arbetsgivare anställt en gnomingenjör.",al={"vem är ziz","ziz fizziks npc","om ziz fizziks"}},{q="Varför lämnade Ziz Fizziks Venture Company?",a="Han gick därifrån i protest efter att Venture Company anställt gnomingenjören Gerenzo Wrenchwhistle. Ziz vägrade arbeta sida vid sida med en rivaliserande gnom och bad Sputtervalve om en ny anställning.",al={"varför slutade ziz","varför lämna venture company","ziz och venture company"}},{q="Var hittar man Ziz Fizziks?",a="Han finns längs den västra kanten av Windshear Crag i Stonetalon Mountains, med utsikt över Venture Companys avverknings- och utgrävningsverksamhet.",al={"ziz fizziks plats","var finns ziz","hitta ziz fizziks"}},{q="Vem är Sputtervalve?",a="Sputtervalve är en goblinagent med koppling till Tinkers' Union, som värvar skickliga ingenjörer från Venture Company och sätter dem i arbete med konkurrerande projekt.",al={"vem är sputtervalve","sputtervalves roll"}},{q="Vem är Gerenzo Wrenchwhistle?",a="Gerenzo är en gnomingenjör som Venture Company tog in till Windshear Crag. Utnämningen gjorde Ziz rasande och ledde till en hård yrkesrivalitet.",al={"gerenzo wrenchwhistle","vem är gnomingenjören"}},{q="Vad är Tinkers' Union?",a="Tinkers' Union är en etablerad goblinorganisation för ingenjörer. De konkurrerar aktivt med rivaler som Venture Company och rekryterar eller lockar tillbaka de främsta talangerna när tillfälle ges.",al={"tinkers' union","goblinernas tinkers' union"}}},fx={["39c75067"]={q="Varför vill Sputtervalve att du ska se till Ziz Fizziks?",a="Venture Company rekryterar regelbundet de bästa goblin-talangerna, men Sputtervalve tog chansen att få tillbaka en ingenjör när Ziz slutade i protest mot att en gnome-rival anställdes. Nu representerar Sputtervalve Tinkers' Union och satte genast Ziz i arbete ute i Windshear Crag. Han vill försäkra sig om att deras nyförvärvade uppfinnare faktiskt levererar resultat och inte går bet ensam i fientligt territorium.",al={"varför se till ziz fizziks","sputtervalves motiv","varför skicka mig till ziz"}}},fp="11,195,30.322.0,21.315.0,19.179.0,46.154.0,31.167.0,20.145.0,29.165.0,27.148.0"}
P.entries["quest:1484"] = {n="The Corrupter",s="Maurin Bonesplitter har funnit demonfursten mycket farligare än väntat. Han är säker på att Takata Steelblade tvivlar på hans förmåga, och att lämna svärdsmannen ovetande om vad som hänt skulle förolämpa Takatas heder. Maurin skickar dig för att tala med Takata, som är i närheten.",h="Maurin Bonesplitter har funnit demonfursten mycket farligare än väntat.",kw={"demonfurste","desolace","kodo graveyard","maurin bonesplitter","svärdsman","takata steelblade","fördärvaren"},sec={{t="En hederssak",b="Maurin Bonesplitter finner varelsen mycket farligare än han hade väntat sig. Takata Steelblade tvivlar säkert på att Maurin kan hantera den, och att inte få veta vad som just hänt skulle förolämpa Takatas heder. Maurin ber dig tala med svärdsmannen och erbjuda dig att dräpa demonen, om Takata tillåter det. Maurin varnar dig för att inte pressa Takata för hårt, eftersom det är bättre om Takata tror att idén är hans egen."},{t="På andra sidan stigen",b="Takata Steelblade är alldeles i närheten, på andra sidan stigen från Maurin, på en klippa med utsikt över Kodo Graveyard."},{t="Takatas svar",b="Takata bevittnade vad som utspelade sig mellan Maurin och demonfursten. Även som en vålnad tycks varelsen ha större makt än Maurin, Takatas trollkarlskamrat, och Takata undrar om Maurin kan besegra den. Om Takata gick dit själv skulle det tjäna krigshövdingen bättre, men hans plikter här är sådana att det skulle vanära klanen att lämna dem för att strida mot ondskan av personlig heder."}},faq={{q="Varför vill Maurin Bonesplitter att Takata Steelblade ska få veta?",a="Maurin finner demonfursten mycket farligare än han väntat sig. Han är säker på att Takata tvivlar på hans förmåga, och att lämna svärdsmannen ovetande om vad som hänt skulle förolämpa Takatas heder.",al={"varför tala med takata","maurin bonesplitters skäl","varför berätta för takata"}},{q="Var befinner sig Takata Steelblade?",a="Alldeles i närheten, på andra sidan stigen från Maurin, på en klippa med utsikt över Kodo Graveyard i Desolace.",al={"takatas plats","var är takata","hitta takata steelblade"}},{q="Varför avråder Maurin från att pressa Takata för hårt?",a="Maurin vill att du erbjuder dig att dräpa demonen, om Takata tillåter det, utan att pressa honom. Det är bättre om Takata tror att idén är hans egen.",al={"varför inte pressa takata","hantera takata","takatas stolthet"}}},fp="13,269,17.424.0,15.112.0,15.395.1,57.190.0,35.98.0,56.141.0"}
P.entries["quest:1485"] = {n="Vile Familiars",s="Nära The Den hotar Vile Familiars varje häxmästare som söker demonernas kraft. Ruzan ber dig bevisa din styrka mot dem och ta med deras huvuden tillbaka. Det här är det enkla men farliga första steget mot att bemästra felmagi under Hordens vakande ögon.",h="Nära The Den hotar Vile Familiars varje häxmästare som söker demonernas kraft.",kw={"burning blade coven","durotar","imp","ruzan","the den","valley of trials","vidriga smådemoner","demonbesvärjare"},ang={["class:Warlock"]="Som häxmästare står du inför ditt första prov för att bevisa att du kan kuva demonisk eld innan du lär dig riten för att frammana en egen imp.",["faction:Horde"]="Som medlem av Horde kan du träna som häxmästare i Durotar, även om de mörka konsterna fortfarande är förvisade till avskilda platser som The Den.",["race:Orc"]="Som orch möter du ditt folks mörka historia varje dag. Du måste bevisa din kontroll och lojalitet i ett samhälle som minns fasorna från felmagi."},sec={{t="En osäker plats i Horden",b="Häxmästare lever på osäker fot i Thralls nya Horde. Demonisk fördärv och blodseder ledde en gång orcherna mot undergången och lämnade djupa sår och misstro efter sig. Felmagi tolereras i Durotar, men dess utövare är varken omtyckta eller välkomna. Många häxmästare lever avskilt och utövar sin magi på skuggiga platser som The Den, långt från nyfikna blickar. Där lär de upp de få noviser som vågar följa deras väg."},{t="Mästerskapsprovet",b="Ruzan ber dig bevisa din styrka innan han lär dig de farliga riterna för att böja en imp efter din vilja. Vile Familiars smyger omkring nära en grotta nordost om The Den och slungar eldklot mot dem som närmar sig. Döda dessa mindre demoner och ta med deras huvuden tillbaka för att visa att du kan besegra de eldfängda varelser du hoppas kunna kontrollera. Först då kan du möta faran i magin du vill behärska."}},faq={{q="Varför skickar Ruzan demonbesvärjare att bekämpa vidriga smådemoner?",a="Ruzan skickar dig att strida mot Vile Familiars så att du får möta en imps eldiga natur och farlighet innan du försöker frammana en. Häxmästare är få och misstrodda, så han ber dig bevisa att du kan besegra sådana varelser innan han lär dig att frammana demoner.",al={"varför döda vidriga smådemoner","ruzans prov","imp-provet"}},{q="Var finns de vidriga smådemonerna?",a="Vile Familiars samlas runt och inne i en grotta nordost om The Den i Valley of Trials, bortom de strövande vildsvinen och skorpionerna. Grottan är ett läger för Burning Blade Coven.",al={"vidriga smådemoners plats","var finns smådemonerna","ruzans grotta"}},{q="Hur ser Horden på demonbesvärjare i Durotar?",a="Häxmästare möts av djup misstänksamhet i hela Horde, eftersom demonisk fördärv en gång lämnade orcherna med djupa sår. Thralls styre tolererar dem och ser deras värde i strid, men många lever fortfarande ensamma.",al={"är demonbesvärjare hatade","demonbesvärjarlore i horden","varför misstro demonbesvärjare"}},{q="Vilken belöning ger provet?",a="När du tar med huvudena från dödade Vile Familiars till Ruzan bevisar du att du har styrkan och disciplinen att befalla demoner. Då kan han lära dig att frammana en imp som tjänare.",al={"vad får jag lära mig","uppdragsbelöning från ruzan","imp-besvärjelse"}},{q="Är de vidriga smådemonerna riktiga demoner?",a="Ja. Vile Familiars är mindre demoniska imps som är knutna till felmagi. De är små men formidabla fiender som slungar eldklot mot sina motståndare.",al={"vad är vidriga smådemoner","är smådemoner imps","smådemonernas demontyp"}},{q="Vem är Ruzan?",a="Ruzan är en orchisk häxmästartränare i The Den i Valley of Trials. Han lär nya orchiska häxmästare att använda felenergi säkert och kontrollera sina frammanade tjänare.",al={"ruzan","vem är ruzan","demonbesvärjare i valley of trials"}}},fx={["2f864f20"]={q="Vad ska Vile Familiar Heads användas till?",a="Ruzan behöver huvudena som fysiskt bevis på att du segrat över varelserna i strid. Eftersom så få noviser väljer warlockens bana vägrar han lära dig den farliga konsten att frammana dem innan du bevisat att du har kraften och viljan att kuva dem.",al={"vad vile familiar head används till","varför samla vile familiar heads","ruzan och vile familiar heads"}},["58d905b2"]={q="Vad gör de vidriga familiarerna i Valley of Trials?",a="De här våldsamma, imp-liknande varelserna håller till kring en grotta nordost om The Den, känd som Burning Blade Coven. De lockas dit av fördärvad magi eller binds av kultister som lurar i närheten. Där utgör de ett livsfarligt prov för unga warlocks som vill testa sin beslutsamhet mot mindre demoniska undersåtar.",al={"varför är familiarerna här","vile familiars i valley of trials","grottan med vile familiars"}},cca9ea14={q="Varför skickar Ruzan dig i stället för att själv ta hand om familiarerna?",a="Det här är ett personligt prov på skicklighet, inte ett uppdrag att försvara allmänheten. Om Ruzan eller Grunts skickade iväg familiarerna skulle du inte lära dig något. En warlock som inte kan övermanna en enkel demon i direkt strid kommer förr eller senare att uppslukas eller förgöras när den försöker frammana en.",al={"varför dödar inte ruzan dem","varför jag och ruzan","varför prövar ruzan mig"}}},fp="14,264,31.411.0,20.399.0,53.245.0,35.186.0,44.203.0,45.161.0,33.137.0,13.155.0"}
P.entries["quest:1486"] = {n="Deviate Hides",s="Deviate Hides är ett uppdrag från Nalpak, en lärjunge till Naralex som håller till ovanför ingången till Wailing Caverns. Medan Naralex ligger fången i en förvriden mardröm försöker Nalpak ta till vara på något användbart från de muterade bestar som uppstått under The Barrens. Genom att samla skinn från dessa avvikande rovdjur hoppas han kunna använda deras märkliga, utomvärldsliga egenskaper i praktiken.",h="Deviate Hides är ett uppdrag från Nalpak, en lärjunge till Naralex som håller till ovanför ingången till...",kw={"the barrens","deviate","deviate hides","emerald nightmare","läderarbete","nalpak","naralex","wailing caverns"},ang={["class:Druid"]="Nalpaks läger vittnar om de överlevande lärjungarnas dystra vaka över ett företag som gått fruktansvärt fel. Därför blir uppgiften att hejda mutationerna i grottorna personlig för andra druider.",["profession:Herbalism"]="Den onormala tillväxt som livnär de avvikande bestarna hänger direkt samman med den korrumperade floran och de underjordiska källor som slingrar sig genom grottsystemet."},sec={{t="Korruptionen tar form",b="När nattalvdruiden Naralex försökte nå de underjordiska källorna under The Barrens för att återge de torra slätterna ett frodigt liv gled hans sinne in i en fruktansvärd mardröm. Den mörka drömmen läckte in i verkligheten och muterade de inhemska djuren i Wailing Caverns till våldsamma avvikande bestar. Rovödlor, krokolisker, huggormar och hasande fasor blev förvridna och aggressiva av den smaragdgröna korruption som läckte från deras drömmande mästare."},{t="En pragmatisk druid",b="Nalpak sitter högt uppe i klippformationen ovanför grottöppningen och ser katastrofen utspela sig med en blandning av bävan och praktisk nyfikenhet. Han förstår att de avvikande varelserna är onda och onaturliga, men tror att deras korrumperade former kan ge unika material. Deras förhårdnade, förvridna hudar är särskilt tåliga och kan komma skickliga läderarbetare till nytta, så att en tragisk mardröm kan ge hållbar utrustning."}},faq={{q="Var hittar jag Nalpak?",a="Nalpak och hans medlärjungar har slagit läger högt uppe i klippformationen som liknar en skalle ovanför ingången till Wailing Caverns. Gå inte rakt in i huvudtunneln. Klättra i stället uppför bergssluttningen bakom grottöppningen och ta dig försiktigt ner på den övre avsats som utgör ögonhålan och vetter mot oasen.",al={"nalpaks plats","var finns nalpak","hur hittar man nalpak","uppdragsgivare deviate hides"}},{q="Vad är avvikande varelser?",a="Avvikande varelser är lokala djur som förvandlats av Emerald Nightmare, vilken läckte ut ur Naralex sovande sinne. Rovödlor, ormar, krokolisker och vindormar från The Barrens har förvridits till mörkare, våldsamma former med märkliga magiska egenskaper och fläckiga, onaturliga hudar.",al={"vad är avvikande varelser","avvikande bestar","varför är djuren muterade i wailing caverns"}},{q="Varför vill Nalpak ha skinnen?",a="Nalpak förstår att bestarna är skapade av ond korruption, men deras hudar har en ovanlig, utomvärldslig styrka. Han tror att läderarbetare kan omvandla mardrömmens smitta till slitstark utrustning genom att studera och bearbeta skinnen.",al={"varför deviate hides","vad ska nalpak ha skinnen till","syftet med deviate hides"}},{q="Kan alla avvikande varelser släppa skinnen?",a="De muterade bestar som strövar genom tunnlarna och de inre delarna av Wailing Caverns bär på dessa skinn. Jägare och läderarbetare får ofta extra hudar när de flår bestarna, utöver dem som går att ta till vara på från kvarlevorna.",al={"vilka fiender släpper deviate hides","vem släpper deviate hide","farma deviate hide"}},{q="Är Nalpak på horden eller alliansens sida?",a="Nalpak är en tauren-druid och en av Naralex lärjungar. Han är neutral och tar emot hjälp från alla dugliga äventyrare, oavsett om de tillhör alliansen eller horden, så länge de vågar sig in i de korrumperade grottorna.",al={"är nalpak med i horden","hör deviate hides till alliansen","kan alliansen göra deviate hides"}},{q="Vad hände med Naralex?",a="Naralex försökte väcka The Barrens underjordiska källor genom att förena sitt medvetande med The Emerald Dream. I stället tog mardrömmen makten över hans sömn, förvandlade grottsystemet till en grogrund för fasor och lämnade honom medvetslös djupt inne i grottorna.",al={"vem är naralex","naralex mardröm","vad hände med druiden i wailing caverns"}}},fx={["58e10be2"]={q="Vad ska Deviate Hide användas till?",a="Deviate-hudar har märkliga, utomvärldsliga egenskaper som uppstått ur mardrömmen som fördärvar grottorna. Varelserna de kommer från är förvridna och fientliga, men Nalpak tror att deras ovanliga skinn kan återanvändas inom läderhantverk för att tillverka slitstarka rustningar och packningar. På så sätt kan något användbart komma ur fördärvet.",al={"vad deviate hide används till","varför samla deviate-hudar","syftet med deviate hide"}}},fp="13,382,24.451.0,17.451.0,24.331.0,27.292.0,33.244.0,40.238.0,49.206.0,25.281.0"}
P.entries["quest:1487"] = {n="Deviate Eradication",s="Deviate Eradication är ett uppdrag som Night Elf-druiden Ebru ger dig ovanför ingången till Wailing Caverns. Medan de andra lärjungarna försöker väcka sin sovande ledare ber Ebru äventyrare att rensa grottorna från muterade avvikardjur, som skapats av hans förvridna vision. Att befria den underjordiska oasen från dessa fasor är ett viktigt steg för att hejda korruptionen som hotar The Barrens.",h="Deviate Eradication är ett uppdrag som Night Elf-druiden Ebru ger dig ovanför ingången till Wailing Caverns.",kw={"the barrens","deviate dreadfang","deviate eradication","deviate ravager","deviate shambler","deviate viper","ebru","naralex","wailing caverns"},ang={["class:Druid"]="Det förvridna ekosystemet i grottorna är en sorglig varning om vad som händer när kontakten med The Emerald Dream får katastrofala följder.",["faction:Horde"]="Eftersom Wailing Caverns ligger mitt i Kalimdors centrala slätter är det viktigt att utrota dessa aggressiva rovdjur för att skydda närliggande bosättningar som The Crossroads.",["race:NightElf"]="För kaldorei-resenärer är det en tung börda att se Naralex ädla vision förvandlas till mardrömsfödda fasor. De känner en plikt att hjälpa sina strandsatta fränder."},sec={{t="En dröm som gick fruktansvärt fel",b="Night Elf-druiden Naralex förde sina anhängare till de underjordiska källorna i The Barrens med en storslagen vision: att nå in i The Emerald Dream och åter göra de uttorkade slätterna till en grönskande, livskraftig skog. I stället blev Naralex fångad i drömmen, och hans sömn förvandlades till en plågsam mardröm. I stället för att läka landet förvrängde kraften som strömmade genom grottorna de inhemska djuren och växterna till monstruösa, aggressiva mutanter som kallas avvikardjur."},{t="Ebrus motstånd",b="Högt uppe i en grotta i klippväggen, med utsikt över grottöppningen, ser Ebru och en handfull överlevande Disciples of Naralex förtvivlat på när deras antal minskar. Några av dem ägnar sina krafter åt att väcka sin fallne mästare, men Ebru inser att en akut kris måste hanteras. Om de snabbt förökande avvikarhuggormarna, avvikarslingrarna, avvikarröjarna och avvikarskräckhuggtänderna lämnas ifred kommer de att sprida sig ut i The Barrens. Därför rekryterar Ebru förbipasserande äventyrare för att ta sig ner i de djupa tunnlarna och utrota de avvikande monstren där de uppstår."}},faq={{q="Var hittar jag Ebru för att påbörja uppdraget?",a="Ebru befinner sig tillsammans med några andra Disciples of Naralex i en avskild grotta högt ovanför huvudingången till Wailing Caverns. Grottan ligger där det ser ut som ögonhålan på högra sidan av den skalleformade klippformationen. För att nå henne måste du vanligtvis klättra runt bergsryggen och försiktigt ta dig ner på den övre avsatsen.",al={"ebrus plats","var finns ebru","hur hittar man ebru","ögongrottan i wailing caverns"}},{q="Vad fick djuren att bli avvikardjur?",a="Varelserna muterades av mörka energier som sipprade ut från The Emerald Dream. När druiden Naralex länkade sitt medvetande till de underjordiska källorna för att åter göra The Barrens grönskande, kapades hans sinne av en mardröm. De läkande energierna förvandlades då till en korrumperande kraft som muterade de lokala djuren till avvikarmonster.",al={"varför är de avvikardjur","avvikardjurens ursprung","vad korrumperade djuren i wc"}},{q="Vilka är Disciples of Naralex?",a="Disciples of Naralex är en krets av druider som följde med Naralex till Wailing Caverns för att hjälpa till att åter göra The Barrens grönskande. Efter att han fångats i mardrömmen blev många vilda eller galna. Endast en liten grupp vid sina sinnens fulla bruk blev kvar och försöker nu ställa katastrofen till rätta.",al={"disciples of naralex","naralex anhängare","vilka är druiderna i wailing caverns"}},{q="Kan både Alliance och Horde ta uppdraget?",a="Ja. Ebru och hans följeslagare är neutrala druider som värnar om naturen och vill hålla mardrömmen i schack. De tar emot hjälp från dugliga kämpar ur både Horde och Alliance.",al={"deviate eradication alliance eller horde","är deviate eradication neutralt"}},{q="Vilka varelser måste du döda åt Ebru?",a="Ebru ber dig jaga fyra särskilda raser av korrumperade djur djupt inne i grottorna: Deviate Ravagers, Deviate Vipers, Deviate Shamblers och Deviate Dreadfangs. Du ska döda sju av varje.",al={"fiender i deviate eradication","mål i deviate eradication","vilka avvikardjur ska dödas"}},{q="Väcker Naralex om jag slutför uppdraget?",a="Nej. Ebrus uppdrag handlar enbart om att bekämpa skadedjuren och begränsa skadorna genom att minska antalet farliga bestar. För att väcka Naralex krävs en särskild ritual långt inne i hans helgedom, i grottans hjärta.",al={"väcker detta naralex","hur väcker man naralex"}}},fx={["62e049f1"]={q="Varför vill Ebru att de avvikande bestarna ska dödas?",a="Medan Naralex andra lärjungar koncentrerar sig på att väcka sin fångade mästare ser Ebru ett omedelbart hot som växer i Wailing Caverns. Naralex vision om att återställa The Barrens till en frodig skog har förvandlats till en mardröm som sprider fördärvade, onaturliga varelser genom tunnlarna. Ebru tror att det inte går att läka landet eller rädda deras ledare förrän de förvridna bestarna har utrotats ur grottorna.",al={"ebrus motiv","varför döda de avvikande bestarna","varför vill ebru ha de avvikande bestarna döda"}},b4bfe70b={q="Vad är de avvikande varelserna i Wailing Caverns?",a="De är traktens djurliv, huggormar, rovfåglar och stapplande växtmonster, som förvridits till monstruösa former av de mörka energierna som läcker ut från Naralex mardröm. Naralex försökte kanalisera The Emerald Dream för att återuppliva det torra The Barrens. Men när hans dröm blev förgiftad muterade det omgivande magiska läckaget djurlivet till aggressiva, onaturliga rovdjur som nu hemsöker grottans djup.",al={"vad är deviate ravagers","avvikande bestar i wailing caverns","fördärvade varelser i wailing caverns"}},ab17f40e={q="Varför kan inte Naralex lärjungar rensa grottorna själva?",a="Lärjungarna är alldeles för få för att anfalla på egen hand. Deras orden har krympt rejält sedan Naralex fastnade i sin mardröm, och de få som är kvar är splittrade mellan att förbereda en ritual för att väcka honom och att försvara sitt lilla fäste. De saknar manskap och stridskraft för att tränga in i grottorna och utrota bestarna utan hjälp utifrån.",al={"varför behöver ebru min hjälp","varför kan lärjungarna inte rensa grottorna","varför behöver naralex lärjungar hjälp"}}},fp="19,393,27.477.0,12.537.0,41.337.0,41.324.0,33.299.0,44.210.0,44.194.0,40.219.0"}
P.entries["quest:1488"] = {n="The Corrupter",s="Takata Steelblade vet inget om Lord Azrethoc, men håller med Maurin om att demonherren måste stoppas, särskilt om Azrethoc försöker vinna inflytande över Burning Blade. Takata litar på att du samlar en grupp mot Azrethoc och hans tjänare, häxmästaren Jugkar Grim'rod.",h="Takata Steelblade vet inget om Lord Azrethoc, men håller med Maurin om att demonherren måste stoppas...",kw={"burning blade","demon","desolace","jugkar grim'rod","lord azrethoc","maurin","takata steelblade","häxmästare"},sec={{t="En grupp i söder",b="Takata har aldrig hört talas om Lord Azrethoc, men håller med Maurin om att demonherren måste stoppas, framför allt om Azrethoc försöker påverka Burning Blade. Du har redan visat att du vill hjälpa krigshövdingen, så Takata litar på att du samlar en grupp och dödar Azrethoc och hans tjänare, häxmästaren Jugkar Grim'rod. Takata säger åt dig att bege dig rakt söderut till Mannoroc Coven, där de båda finns."},{t="Tบางatas oro",b="Takata säger att demonerna i Desolace är ett större hot än någonsin. Varje nyanländ vidrig varelse får utsikterna att någonsin återvända till krigshövdingen att verka allt mörkare, och ibland önskar Takata att kentaurerna vore den enda fienden."},{t="Takatas dom",b="När hotet är undanröjt kallar Takata det en stor seger för alla och säger att utsikterna här är mindre dystra än befarat. Takata talar om de dödade demonerna, om Burning Blades misslyckade försök och om att platsen som kallas hem åter är trygg."}},faq={{q="Vem skickar äventyrare mot Lord Azrethoc?",a="Takata Steelblade, som håller med Maurin och litar på att du samlar en grupp mot demonherren.",al={"vem ger uppdraget the corrupter","uppdragsgivare the corrupter","takata steelblade uppdrag"}},{q="Vem måste besegras?",a="Lord Azrethoc, en demonherre, och Jugkar Grim'rod, häxmästaren som tjänar honom.",al={"vem ska jag döda","målen i the corrupter","azrethoc och jugkar"}},{q="Var finns målen?",a="Takata säger åt dig att bege dig rakt söderut. Båda finns nära Mannoroc Coven, i södra Desolace.",al={"var finns azrethoc","jugkar grim'rod plats","vart ska jag gå i the corrupter"}},{q="Varför utgör Lord Azrethoc en sådan fara?",a="Takata har aldrig hört talas om Azrethoc, men demonherren måste stoppas, särskilt om han försöker påverka Burning Blade.",al={"varför döda azrethoc","vad gör azrethoc","koppling till burning blade"}},{q="Vad kommer före detta i kedjan?",a="Det här steget följer den fjärde delen av kedjan The Corrupter.",al={"förutsättningsuppdrag","föregående uppdrag the corrupter","the corrupter uppdragskedja"}},{q="Vad oroar Takata sig för när det gäller demonerna i Desolace?",a="Takata säger att de är ett större hot än någonsin. Varje nyanländ vidrig varelse får utsikterna att återvända till krigshövdingen att verka allt mörkare, och Takata önskar att kentaurerna vore den enda fienden.",al={"takata bakgrund","varför är takata här","takata steelblades roll"}}},fp="13,279,20.399.0,14.230.0,16.261.1,49.96.0,21.77.0,30.98.0,42.139.0,36.57.0,51.190.0"}
P.entries["quest:1489"] = {n="Hamuul Runetotem",s="Det här uppdraget leder Hordens äventyrare från The Barrens frodiga men oroliga oaser till Thunder Bluffs höga höjder. Tonga Runetotem misstänker en djup andlig fördärvning i Wailing Caverns och skickar dig att söka råd hos ärkedruiden Hamuul Runetotem.",h="Det här uppdraget leder Hordens äventyrare från The Barrens frodiga men oroliga oaser till Thunder Bluffs...",kw={"elder rise","hamuul runetotem","oaser","förorening","the barrens","thunder bluff","tonga runetotem","wailing caverns"},ang={["class:Druid"]="För taurendruider är det en pilgrimsfärd att rapportera till ärkedruiden Hamuul Runetotem, deras mentor som grundade den moderna taurendruidismen utifrån Malfurion Stormrages läror.",["faction:Horde"]="Eftersom The Barrens är en knutpunkt för den unga Horden skyddar en undersökning av den spridande föroreningen försörjningslederna mellan Durotar, Mulgore och utposterna i norr.",["race:Tauren"]="Uppdraget förenar oron över The Barrens, taurenfolkets urgamla jaktmarker, med vägledningen från stamäldste som bor på Mulgore heliga höjder."},sec={{t="En oroande dröm",b="När Tonga Runetotem studerade djurlivet i The Barrens upptäckte han en märklig åkomma som drabbat varelserna nära de frodiga oaserna. De förändrade bestarna bar skal som förorenats av en onaturlig kraft, och Tonga insåg att själva landet är fångat i en feberaktig, orolig dröm. Han är övertygad om att vattnet från de underjordiska Wailing Caverns är rötaens källa och vet att det krävs långt större visdom än en ensam naturkännare besitter för att våga sig in."},{t="Råd på Elder Rise",b="För att förstå hotet i grottorna skickar Tonga dig till Thunder Bluff för att tala med sin släkting, ärkedruiden Hamuul Runetotem. Hamuul är den högst rankade taurendruiden och en vördad andlig ledare i Cenarion Circle i Mulgore. Från sin post på det fridfulla Elder Rise håller Hamuul uppsikt över oroligheter i Kalimdor och bekräftar att mardrömmen som sprider sig genom The Barrens är ett allvarligt hot som kräver Hordens fulla styrka."}},faq={{q="Varför skickar Tonga mig till Hamuul?",a="Tonga upptäckte att oaserna i The Barrens är förorenade av en märklig åkomma som kommer från Wailing Caverns. Eftersom fenomenet liknar en mardröm som håller jorden i sitt grepp skickar han dig till ärkedruiden Hamuul Runetotem på Elder Rise för att få vägledning av en högt uppsatt druid innan någon försöker ta sig in i grottorna.",al={"varför hamuul","varför tala med hamuul","syftet med hamuul-uppdraget"}},{q="Var finns Hamuul Runetotem?",a="Ärkedruiden Hamuul Runetotem finns i Thunder Bluff, taurenfolkets huvudstad i Mulgore. Han står på Elder Rise och blickar ut över slätterna tillsammans med andra druider och schamaner.",al={"hamuuls plats","var finns hamuul","hitta hamuul runetotem"}},{q="Vad är källan till föroreningen som Tonga upptäckte?",a="Föroreningen kommer från de underjordiska källorna i Wailing Caverns. Det märkliga vattnet fördärvar det lokala djurlivet och växtligheten, så att landet verkar vara fångat i en mardröm utan slut.",al={"vad är föroreningen","förorening i oaserna","förorening i wailing caverns"}},{q="Vad händer efter att jag talat med Hamuul?",a="Hamuul välkomnar dig till Thunder Bluff och förbereder dig för prövningarna som väntar. Han varnar för att kampen mot mardrömmen under The Barrens är ett allvarligt uppdrag och hänvisar dig till Nara Wildmane för att förbereda nedstigningen i Wailing Caverns.",al={"nästa uppdrag efter hamuul","vad händer härnäst","uppföljning efter hamuul"}},{q="Vem är Hamuul Runetotem?",a="Ärkedruiden Hamuul Runetotem är taurendruidernas främsta ledare och en nära barndomsvän och rådgivare till överhövding Cairne Bloodhoof. Efter att ha lärt sig vildmarkens vägar efter det tredje kriget vägleder han taurendruider i deras samhörighet med naturen och Cenarion Circle.",al={"vem är hamuul","hamuuls bakgrund","ärkedruiden hamuul"}},{q="Måste jag göra det här uppdraget för att komma in i Wailing Caverns?",a="Du behöver ingen instämning för att gå in i Wailing Caverns, men det här uppdraget länkar samman Hordens berättelse om mysteriet kring The Barrens frodiga oaser med expeditionen inne i grottan.",al={"instämning till wailing caverns","är det här uppdraget obligatoriskt"}}},fx={a40fa735={q="Varför ber Tonga Runetotem en äventyrare att gå till Hamuul?",a="Tonga Runetotem är stationerad vid The Crossroads för att hålla uppsikt över de märkliga och oroande förändringarna som sprider sig genom The Barrens och dess oaser. Eftersom han måste stanna ute i fält och studera det fördärvade djurlivet på nära håll, förlitar han sig på dugliga resenärer som kan föra hans rapporter till ärkedruiden Hamuul Runetotem på Elder Rise i Thunder Bluff och be om vägledning.",al={"varför skicka mig till hamuul","varför kan inte tonga gå till hamuul","varför jag och tonga"}}},fp="16,269,18.485.0,21.447.0,33.311.0,34.200.0,46.204.0,40.241.0,24.284.0,52.200.0"}
P.entries["quest:149"] = {n="Ghost Hair Thread",s="Ghost Hair Thread är ett ärende åt spåkvinnan Madame Eva i Darkshire. För att samla in spökhåret hon behöver för att spinna Ghost Hair Thread skickas resande söderut för att söka upp Blind Mary, en plågad ande som bor i en övergiven bondgård. Med en Spectral Comb kan man samla de nödvändiga hårstråna från hennes spöklika lockar.",h="Ghost Hair Thread är ett ärende åt spåkvinnan Madame Eva i Darkshire.",kw={"blind mary","darkshire","duskwood","bondgård","spöke","ghost hair thread","madame eva","spectral comb"},ang={["class:Priest"]="Att möta en ande som plågats så svårt att hon slitit ut sina egna ögon visar den djupa tragedi och de kvardröjande skuggor som hemsöker Duskwoods rastlösa döda.",["faction:Alliance"]="De tragiska vålnaderna som hemsöker gårdarna kring Darkshire påminner om hur snabbt det välmående Grand Hamlet föll i mörker och isolering.",["profession:Tailoring"]="Att spinna tråd av en andes kroppslösa kvarlevor är en sällsynt ockult teknik, långt från vanliga spinnrockar och vävstolar."},sec={{t="En spåkvinna ber om hjälp",b="Madame Eva i Darkshire behöver särskilda material från en annan värld för att spinna Ghost Hair Thread åt Abercrombie. Vanliga trådar av linne och ull räcker inte till för Duskwoods ritualer. I stället behöver hon eteriska hårstrån som samlats direkt från en ande. För att få tag på denna makabra beståndsdel utan våld ger Eva dig en fin Spectral Comb som kan passera genom dödens slöja och samla lösa spökhår."},{t="Blind Marys sorg",b="Söder om Darkshire, undangömd bland skuggiga kullar, ligger en övergiven gård som hemsöks av den jämrande vålnaden Blind Mary. Anden plågas av självförakt, klagar ständigt över sitt hemska utseende och skriker åt inkräktare att vända bort blicken. I sin förtvivlan över vad hon blivit slet hon ut sina egna ögon. Spectral Comb ger henne en flyktig stunds tröst och får henne att kamma sitt spöklika hår trots sin ändlösa plåga."}},faq={{q="Vem är Blind Mary?",a="Blind Mary är ett sorgset spöke som hemsöker en förfallen bondgård i kullarna söder om Darkshire. Förtvivlan och känslan av att vara ful drev henne till vansinne, och hon slet ut sina egna ögon för att slippa se sig själv igen. Trots att hon inte kan se är hon plågsamt medveten om alla som tittar på henne.",al={"blind marys historia","vem är mary i duskwood","kvinna med spökkam"}},{q="Varför behöver Madame Eva spökhår?",a="Madame Eva behöver hårstrån från ett spöke för att spinna spöktråd. I Duskwoods hemsökta omgivningar räcker vanliga hantverksmaterial ofta inte till. Därför förlitar hon sig på ockulta beståndsdelar för att utföra sina ritualer och skyddsförtrollningar.",al={"varför spökhår","vad används ghost hair thread till","madame evas hårtråd"}},{q="Var finns Blind Marys hus?",a="Hennes förfallna gård ligger i kullarna rakt söder om Darkshire, förbi stadens kyrkogård och omgiven av kringströvande fasor och odöda som hemsöker de mörka skogarna.",al={"var finns blind mary","blind marys plats","bondgård söder om darkshire"}},{q="Hur fungerar Spectral Comb på en ande?",a="Spectral Comb är skapad eller förtrollad för den osynliga världen och kan påverka kroppslösa vålnader. Den glider genom andlig materia på samma sätt som en fysisk kam går genom levande hår och samlar upp tappade hårstrån som behåller sin eteriska form.",al={"hur fungerar spectral comb","spectral combs historia","kamma spökhår"}},{q="Är Blind Mary fientlig mot resande?",a="Nej. Trots sina skrämmande skrik och sin gråt är Blind Mary inte fientlig mot levande besökare. Hennes plåga är helt riktad inåt, även om skogen och byggnaderna i närheten hyser många aggressiva varelser och odöda.",al={"kommer blind mary att anfalla","är blind mary farlig"}},{q="Vad händer när Mary får kammen?",a="När Mary har använt kammen lämnar hon tillbaka den, full av hennes spökhår. Äventyrare måste ta tillbaka kammen till Madame Eva i Darkshire så att hon kan spinna hårstråna till spöktråd.",al={"vad händer efter spökhåret","lämna tillbaka kammen-uppdraget","efter ghost hair thread"}}},fx={["212c26a1"]={q="Varför behöver Madame Eva en äventyrare som besöker Blind Mary?",a="Madame Eva stannar i Darkshire för att hjälpa staden med sina spådomar och ritualer, men för att nå Blind Mary måste man färdas djupt in i de hemsökta kullarna söder om byn. Skogarna runtomkring och Marys gård kryllar av odöda och skuggdjur som vanliga stadsbor inte vågar möta på egen hand.",al={"varför skicka mig","varför går hon inte själv","varför behöver eva mig"}}},fp="17,257,25.264.0,24.318.0,18.273.0,36.184.0,38.139.0,44.185.0,35.179.0,40.165.0"}
P.entries["quest:1490"] = {n="Nara Wildmane",s="Nara Wildmane är en ung tauren-druid i Thunder Bluff som försöker lösa tragedin som utspelar sig djupt inne i Wailing Caverns. Efter att Arch Druid Hamuul Runetotem blickat in i The Emerald Dream och dragit sig undan från den korruption som frodas där skickade han äventyrare till Nara. Hennes starka vilja höll henne kvar tillräckligt länge för att hon skulle bevittna mardrömmen som grep tag i deras folk. Hon är Hordens viktiga kontakt och leder hjältar i kampen för att göra slut på Druids of the Fang.",h="Nara Wildmane är en ung tauren-druid i Thunder Bluff som försöker lösa tragedin som utspelar sig djupt inne i...",kw={"the barrens","druids of the fang","elder rise","emerald dream","hamuul runetotem","nara wildmane","thunder bluff","wailing caverns"},ang={["class:Druid"]="Druider kommer att uppskatta Naras mod när hon tog sig genom de förrädiska, korrumperade delarna av The Emerald Dream, där till och med erfarna mästare som Hamuul tvekade att stanna.",["faction:Horde"]="Naras vaksamhet skyddar Hordens hjärta och hindrar de mörka krafter som förvrider The Barrens från att sprida sig okontrollerat till Mulgore.",["race:Tauren"]="För tauren som nyligen börjat följa druidismens väg under Hamuul står Nara för en ung, orubblig generation som vågar konfrontera onaturlig förruttnelse direkt."},sec={{t="En syn av korruption",b="När märkliga, onaturliga fenomen började sprida sig över The Barrens gav sig Arch Druid Hamuul Runetotem in i The Emerald Dream för att ta reda på orsaken. Där bevittnade han en kult av druider som ursprungligen hade försökt återställa livet i den torra savannen, men som förlorade förståndet till en vidrig besmittelse. Hamuul var gammal och kunde inte länge stå emot mardrömmens angrepp, så han flydde tillbaka till den vakna världen. Hans yngre lärjunge Nara Wildmane vägrade däremot att ge upp så lätt. Hennes brinnande beslutsamhet höll henne kvar i drömvärlden mycket längre, så att hon kunde se den förvandlade kulten med egna ögon."},{t="Möta mardrömmen",b="Hamuul ger Cenarion Circle den övergripande vägledningen i Thunder Bluff, medan Nara Wildmane har den taktiska insikt som krävs för att rensa bort förruttnelsen. Hon har sett de fallna druidernas förvridna ansikten med ormfjäll på nära håll och känner till deras brott och den förödelse de tänker släppa lös över Kalimdor. Hennes beslutsamhet inleder Hordens offensiv mot Wailing Caverns för att utplåna ledarna som övergett sina heliga eder."}},faq={{q="Vem är Nara Wildmane?",a="Nara Wildmane är en ung och livfull tauren-druid som bor på Elder Rise i Thunder Bluff. Hon studerar under Arch Druid Hamuul Runetotem och tvekar inte att möta de fördärvande mardrömmar som hotar naturens balans.",al={"vem är nara","nara wildmanes bakgrund","nara wildmane thunder bluff"}},{q="Varför skickar Hamuul Runetotem resenärer till henne?",a="Hamuul medger att hans höga ålder och sviktande krafter hindrade honom från att stanna länge i den korrumperade dröm där Druids of the Fang håller till. Eftersom Nara är ung och beslutsam stannade hon längre i drömvärlden och samlade in viktiga upplysningar om kultens planer.",al={"varför tala med nara","hamuul till nara","varför skickade hamuul mig hit"}},{q="Vad såg Nara i The Emerald Dream?",a="Nara bevittnade de fallna druiderna som håller till i Wailing Caverns. Hon såg hur deras ansikten förvridits till fjälliga ormgestalter och fick insyn i de mörka planer och brott de tänker genomföra i The Barrens.",al={"vad såg nara","naras drömsyn","fjälliga druider i drömmen"}},{q="Var finns Nara Wildmane?",a="Hon finns i ett druidskt tält högst uppe på Elder Rise i Thunder Bluff, alldeles mittemot Arch Druid Hamuul Runetotem.",al={"var är nara","nara wildmanes plats","hitta nara wildmane"}},{q="Vad händer när jag rapporterat till Nara Wildmane?",a="När du talat med henne instruerar Nara dig att gå in i Wailing Caverns och döda de fredlösa Druids of the Fang. Därmed inleds den större grottuppdragskedjan ”Leaders of the Fang”.",al={"nästa uppdrag efter nara","vad vill nara att jag gör","fortsättning på leaders of the fang"}},{q="Varför är druiderna i Wailing Caverns korrumperade?",a="Under Naralex ledning gick druiderna in i grottorna i hopp om att nå The Emerald Dream och ge The Barrens ett frodigt växtliv. I stället förvandlades Naralex sömn till en fasansfull mardröm som fångade hans anhängare och gjorde dem till de ormlika Druids of the Fang.",al={"kulten i wailing caverns","varför är druids of the fang onda","varför är druiderna i the barrens onda"}}},fx={["2cdff5a8"]={q="Varför ber Hamuul Runetotem dig tala med Nara i stället för att själv gå dit?",a="Arch Druid Hamuul Runetotem tyngs av ålderdom och av påfrestningen det innebär att nå andevärlden. När han gick in i Emerald Dream för att undersöka problemen i Wailing Caverns svek krafterna honom, och han tvingades dra sig tillbaka. Nara Wildmane är ung och viljestark, och stannade kvar i drömmen långt efter att han flytt. Hamuul befinner sig i Thunder Bluff, där han samordnar tauren-druiderna, och har inte råd att använda sin begränsade livskraft till att springa med meddelanden eller möta hotet ensam. Därför litar han på att dugliga resenärer tar reda på vad Nara upptäckte.",al={"varför skickar hamuul mig till nara","varför kan hamuul inte tala med nara","varför skickas en äventyrare till nara"}}},fp="13,481,22.598.0,25.471.1,21.230.0,59.289.0,39.210.0,33.127.0,46.169.0,52.263.0"}
P.entries["quest:1491"] = {n="Smart Drinks",s="Smart Drinks är ett affärsupplägg som goblinhandlaren Mebok Mizzyrix kläckt i Ratchet. Efter att ha misslyckats med att brygga en intelligenshöjande tonic av Sunscale-raptorhorn ber Mebok nu äventyrare att utforska Wailing Caverns och samla ektoplasmrester till hans senaste dryckesrecept.",h="Smart Drinks är ett affärsupplägg som goblinhandlaren Mebok Mizzyrix kläckt i Ratchet.",kw={"the barrens","ektoplasm","mebok mizzyrix","raptorhorn","ratchet","smart drinks","wailing caverns","wailing essence"},ang={["class:Druid"]="Medan druider beger sig in i Wailing Caverns för att rena mardrömmen som förvrider det smaragdgröna drömlandskapet ser Mebok den tragiska ekologiska föroreningen som billig flytande sirap till sin handelsverksamhet.",["faction:Horde"]="Resenärer som tar sig genom The Barrens vägskäl kan tjäna snabba pengar hos Ratchets köpmän, så länge de inte ställer för många frågor om vad köpmännen tänker göra med monsterdelarna de lämnar in.",["profession:Cooking"]="Varje kock ser genast katastrofen för livsmedelssäkerheten som håller på att utspela sig i Ratchet: att låta rå, mardrömsförorenad ektoplasm dra direkt i en drickbar tonic bryter mot alla regler för livsmedelssäkerhet."},sec={{t="Ett recept på katastrof",b="Mebok Mizzyrix håller till i den livliga hamnstaden Ratchet och förkroppsligar goblinernas klassiska filosofi: att förvandla varje märkligt fenomen i trakten till klingande mynt. Han är övertygad om att en intelligenshöjande dryck ska göra honom rik över en natt och trodde först att hemligheten låg i pulveriserade raptorhorn. När den satsen visade sig vara en stor besvikelse riktade han helt enkelt blicken mot en ännu mer tvivelaktig ingrediens: den korrumperande essens som sipprar ut ur närbelägna Wailing Caverns."},{t="Wailing Essence",b="The Barrens har drabbats av oroande ekologiska mutationer, där frodiga oaser plötsligt växer fram och det lokala djurlivet förvandlas till aggressiva fasor. Mizzyrix tror att ett märkligt ämne som han kallar ”Wailing Essence” ligger bakom de plötsliga förändringarna. Han drar slutsatsen att vad som än förändrar biologin så kraftigt måste vara en potent hemlig ingrediens. Därför skickar han legosoldater för att förgöra de rinnande ektoplasmerna djupt inne i grottlabyrinten och tappa deras lysande vätska direkt på dryckesflaskor."}},faq={{q="Vem är Mebok Mizzyrix?",a="Mebok Mizzyrix är en företagsam goblin som håller till i hamnstaden Ratchet. Han bryr sig inte om hälsoregler och är besatt av att skapa en kommersiell ”smart drink” att sälja över hela Kalimdor och bli rik på.",al={"mebok mizzyrix","vem ger smart drinks","smart drinks uppdragsgivare"}},{q="Varför fungerade inte raptorhornen?",a="Mebok trodde först att malda horn från Sunscale-raptorer skulle ge en potent intelligenshöjande blandning. Drycken infriade inte löftet om genialitet, så han tvingades byta till en betydligt farligare aktiv ingrediens.",al={"varför raptorhornen misslyckades","dryck av raptorhorn"}},{q="Vad är Wailing Essence?",a="Wailing Essence är ett ektoplasmämne som droppar från de onaturliga slemvarelserna djupt inne i Wailing Caverns. Mebok tror att det här flyktiga ämnet driver på de märkliga växt- och djurmutationer som sprider sig genom The Barrens.",al={"vad är wailing essence","essens från wailing caverns"}},{q="Var hittar du ektoplasmerna som bär på essensen?",a="Essensen samlas från ektoplasmavarelser, till exempel evolving, devouring och nightmare ectoplasms, som lurar i de underjordiska gångarna i Wailing Caverns, väster om Ratchet.",al={"var finns ektoplasmer","fiender i smart drinks","vem släpper wailing essence"}},{q="Är smart drinken säker att dricka?",a="Med tanke på att essensen skördas från mardrömslika slemvarelser som kopplas till korrumperande mutationer i The Barrens är det huvudlöst att buteljera den som en kommersiell tonic. Mebok följer goblinernas affärsmoral och bryr sig betydligt mer om säljbarhet än om kundernas säkerhet.",al={"är smart drink giftig","fungerar drycken"}},{q="Vad händer när du har slutfört Smart Drinks?",a="Smart Drinks avslutar Meboks pågående dryckesaffär. Han är nöjd med att du har levererat Wailing Essence, belönar dig och lovar att dela framtida vinster när hans tvivelaktiga tonic har gjort honom förmögen.",al={"fortsättning på smart drinks","vad händer efter smart drinks"}}},fx={b3462a0e={q="Varför vill Mebok Mizzyrix ha Wailing Essence?",a="Mebok Mizzyrix är en ambitiös goblin-entreprenör i Ratchet som är fast besluten att bli rik. Hans första försök med rovfågelhorn gav ingen dryck som förbättrade intellektet, så han satsade på en betydligt mer oberäknelig ingrediens. Han tror att de märkliga mutationerna som förvrider Barrens växt- och djurliv kommer från den kraftfulla energin i Wailing Essence. Han tänker brygga in den direkt i sina blandningar och sälja dem som mirakulösa smarta drycker för en enorm personlig vinst.",al={"meboks motiv","varför vill mebok ha smarta drycker","varför tillverka smarta drycker"}},["6730f7d3"]={q="Vad är det för ektoplasmor som bär på essensen?",a="Ektoplasmorna är märkliga, slemartade uppenbarelser som lever djupt inne i Wailing Caverns. När oberäkneliga, fördärvade energier samlas under oasens sprickor stelnar den lokala underjordiska essensen till växande, slukande och mardrömslika spektrala slemvarelser. De tanklösa varelserna suger åt sig grottornas ursprungliga, mutagena vibrationer och koncentrerar den märkliga Wailing Essence i sina skiftande kroppar tills den skördas.",al={"vad är ektoplasmor","ektoplasma i wailing caverns","vem bär på essensen"}}},fp="12,312,21.488.0,19.518.0,22.207.0,33.250.0,24.258.0,54.194.0,35.266.0,41.203.0"}
P.entries["quest:1492"] = {n="Wharfmaster Dizzywig",s="Vid Ratchets brygga väntar en låda med alkemiförnödenheter på att skeppas över havet. Wharfmaster Dizzywig ordnar transporten till Old World med ett skepp på väg till Blackwater Cove.",h="Vid Ratchets brygga väntar en låda med alkemiförnödenheter på att skeppas över havet.",kw={"blackwater cove","hamn","pir","ratchet","secure crate","sjöfrakt","the barrens","wharfmaster dizzywig"},ang={["faction:Horde"]="Som Horde-äventyrare på färd genom The Barrens kan du bära lasten till Ratchet och lära dig om sjörutterna som förbinder Kalimdor med Eastern Kingdoms."},sec={{t="Ett bud till hamnen",b="En låda med elixir och reagenser väntar vid hamnen i The Barrens, på väg till kollegor i Old World. Karavanerna som kunde ha fraktat den har redan gett sig av, så du ombeds ta den säkra försändelsen till Ratchets strandkant. Hamnen erbjuder en rutt över Great Sea mellan Kalimdor och Eastern Kingdoms."},{t="Ratchets hamn",b="Wharfmaster Dizzywig sköter lasten vid Ratchets träbryggor. Han håller reda på försändelser i liggare och fraktsedlar och hittar sedan plats ombord på fartyg som seglar österut över Great Sea. Den här lådan är bokad på ett skepp med Blackwater Cove som destination."}},faq={{q="Vem är Wharfmaster Dizzywig?",a="Wharfmaster Dizzywig är hamnens goblinämbetsman vid Ratchets huvudbrygga. Han hanterar skeppsmanifest, lastrum och överfarter mellan Kalimdor och hamnar på andra sidan havet.",al={"wharfmaster dizzywig","vem är dizzywig","var finns dizzywig"}},{q="Vart ska lådan skickas?",a="Lådan med elixir och reagenser är på väg till Old World med nästa skepp från Ratchet till Blackwater Cove.",al={"vart ska lådan","blackwater cove","lådans destination"}},{q="Var ligger Ratchet?",a="Ratchet ligger på östkusten i The Barrens, i en skyddad vik rakt öster om den centrala vägkorsningen.",al={"ratchets läge","hur hittar jag ratchet"}},{q="Varför skicka frakt via en goblinhamn?",a="Ratchet är en neutral hamn som är öppen för Horde och oberoende handelsmän. De regelbundna rutterna går över Great Sea och undviker militära blockader och politiska stridigheter.",al={"varför ratchet","varför använda en goblinhamn"}},{q="Vad finns i den säkra lådan?",a="Den säkra lådan innehåller färdigberedda elixir, hantverksreagenser och andra alkemivaror åt samarbetspartner i Eastern Kingdoms.",al={"lådans innehåll","vad finns i lådan"}},{q="Vem skickar sändningen till Dizzywig?",a="En alkemist i The Barrens skickade försändelsen efter att ha missat den avgående karavanen. En pålitlig kurir behövs för att nå bryggan före nästa tidvatten.",al={"vem ger uppdraget","uppdragsgivare"}}},fx={["14e5c3eb"]={q="Varför behöver Apothecary Helbrim att lådan levereras till Wharfmaster Dizzywig?",a="Apothecary Helbrim vid Crossroads måste skicka en låda med drycker, reagenser och andra föremål till sina medarbetare i Old World. Han har inte tid att själv ta ner den till hamnen i Ratchet, och den sista karavanen har redan gett sig av. Om han lämnar lådan till dig kan den komma med nästa båt till Blackwater Cove.",al={"varför skicka secure crate","ak'zeloths motiv för dizzywig","varför leverera lådan till ratchet"}},c036c897={q="Varför ber Apothecary Helbrim en äventyrare om hjälp i stället för att sköta leveransen själv?",a="Apothecary Helbrim har inte tid att själv ta sig från Crossroads till kusten. Eftersom den sista karavanen redan har gett sig av kan han inte förlita sig på vanliga transporter. Att anlita en resenär är hans enda säkra sätt att få lådan till hamnen innan skeppet seglar med nästa tidvatten.",al={"varför skicka mig till dizzywig","varför kan ak'zeloth inte leverera lådan","varför åker inte ak'zeloth till ratchet"}}},fp="20,180,21.316.0,15.233.0,28.170.0,30.123.0,25.109.0,37.159.0,32.126.0,35.164.0"}
P.entries["quest:1498"] = {n="Path of Defense",s="Vid Far Watch Post förbereder Uzzek unga krigare i Horden på att försvara dem som inte kan försvara sig själva. Han skickar dem till Thunder Ridge för att pröva deras uthållighet mot dess elektriska bestar.",h="Vid Far Watch Post förbereder Uzzek unga krigare i Horden på att försvara dem som inte kan försvara sig...",kw={"the barrens","durotar","far watch post","path of defense","svedda fjäll","åsködlor","thunder ridge","uzzek"},ang={["class:Warrior"]="Som krigare börjar du lära dig försvarsdiciplin: sann stridsstyrka ligger i att skydda dina allierade från förödelse.",["faction:Horde"]="Vid Far Watch Post skyddar Horde-vakter vägen in i The Barrens, så deras motståndskraft är viktig för Hordens säkerhet."},sec={{t="Hordes sköld",b="Vid Far Watch Post lär Uzzek unga krigare att försvar är en del av Hordens plikt. Utposten ligger på gränsen mellan The Barrens och Durotar. Uzzek säger att en krigares högsta uppgift är att stå mellan faran och dem som inte kan försvara sig själva och ta slagen så att Horden kan bestå."},{t="Prövning i Thunder Ridge",b="Uzzek skickar noviserna till Thunder Ridge, norrut över Southfury River i Durotar, för att pröva deras uthållighet och beslutsamhet. Åsködlor och blixtskinn strövar genom ravinen. De nya krigarna måste överleva bestarnas stötar och samla in deras svedda fjäll för att visa att de har styrkan att hålla frontlinjen."}},faq={{q="Vem ger uppdraget Path of Defense?",a="Veteranen Uzzek håller prövningen vid Far Watch Post, som bevakar gränsen mellan Durotar och östra The Barrens.",al={"uppdragsgivare","vem ger path of defense","uzzek plats"}},{q="Var ligger Thunder Ridge?",a="Thunder Ridge ligger i västra Durotar, norr om huvudvägen och på andra sidan bron över Southfury River. Aggressiva åsködlor och blixtskinn strövar genom ravinen.",al={"thunder ridge plats","var finns åsködlor","svedda fjäll plats"}},{q="Varför kräver Uzzek just svedda fjäll?",a="Uzzek ber om svedda fjäll från de stötalstrande bestarna i Thunder Ridge. Att uthärda deras elektriska attacker visar att en krigare har den tålighet och motståndskraft som krävs för att lära sig avancerade försvarstekniker.",al={"varför svedda fjäll","syftet med fjäll"}},{q="Vilken filosofisk lärdom ligger bakom den här prövningen?",a="Uzzek lär ut att det inte bara handlar om att slakta när man är krigare, utan också om att skydda andra. När de nya krigarna överlever bestarnas vrede lär de sig att skydda svagare allierade.",al={"krigarfilosofi","bakgrund till path of defense","bakgrund till försvarsställning"}},{q="Vad händer efter att man har slutfört Path of Defense?",a="När du har visat Uzzek din försvarsförmåga skickar han dig vidare till Thun'grim Firegaze för fortsatt stridsträning.",al={"nästa uppdrag","vad händer efter path of defense","fortsättning"}},{q="Kan personer som inte är krigare genomgå den här prövningen?",a="Nej. Den här riten är för krigare och prövar och lär rekryterna grunderna i vakttjänst och defensiv strid.",al={"är det här bara för krigare","vem kan göra det här uppdraget"}}},fx={["47a57f01"]={q="Vilka varelser skickas du för att jaga i Thunder Ridge?",a="Uzzek skickar dig mot åsködlorna och blixtskin­nen som lever i Thunder Ridge i Durotar. Dessa mäktiga bestar kan utföra sprakande elektriska attacker som slår igenom vanliga försvar. När du möter dem måste du uthärda obevekliga fysiska och elementära angrepp, vilket visar att din uthållighet och beslutsamhet räcker för att skydda Horde.",al={"vad slåss du mot i thunder ridge","mål för path of defense","åsködlor och blixtskinn"}},["3d8ed519"]={q="Varför prövar Uzzek dig i stället för att själv sköta uppgifterna?",a="Uzzek är instruktör vid Far Watch Post. Hans uppgift är att pröva blivande krigare, inte att samla troféer åt sig själv. En krigares främsta uppgift i Horde är att vara en levande sköld för svagare bröder och systrar. Uzzek kan inte bara lära ut försvarstekniker till vem som helst. Du måste själv visa att du kan stå emot hårda slag innan han anser dig värdig hans lärdomar.",al={"varför skicka mig","varför behöver uzzek mig","varför måste jag jaga ödlorna"}}},fp="15,189,23.301.0,16.307.0,36.117.0,31.170.0,49.201.0,51.168.0,49.121.0,38.108.0"}
P.entries["quest:1499"] = {n="Vile Familiars",s="I Valley of Trials skickar Ruzan ut häxmästarinitierade mot vidriga bekanta. När du har dödat dem rapporterar du till Zureetha Fargaze, som övervakar arbetet med att hejda Burning Blade.",h="I Valley of Trials skickar Ruzan ut häxmästarinitierade mot vidriga bekanta.",kw={"burning blade coven","durotar","imps","ruzan","the den","valley of trials","vidriga följeslagare","häxmästaruppdrag","zureetha fargaze"},ang={["class:Warlock"]="Som häxmästare möter du de vidriga bekanta för att bevisa att du kan kuva och oskadliggöra vilda felvarelser utan att falla offer för dem.",["race:Orc"]="Som orch vet du att demoniska bekanta påminner om de mörka pakter som en gång förslavade ditt folk. Att avlägsna dem från Durotars jord är viktigt för ditt folks överlevnad.",["race:Troll"]="Som Darkspear-troll delar du Valley of Trials med andra som ser på demonisk magi med djup misstänksamhet. Du måste visa din lojalitet genom att stå emot kultister som handlar på egen hand."},sec={{t="En fråga om disciplin",b="Krigare och spejare i Valley of Trials lyder direkt under Zureetha Fargaze, som skickar dem för att hejda Burning Blade Coven. Häxmästarinitierade lyder först under Ruzan, deras skuggfulle mentor. Han kräver bevis på att du kan bemästra mindre demoner innan han skickar dig tillbaka för att hjälpa till med hordens försvar. Ditt arbete gagnar både häxmästarna och säkerheten i The Den."},{t="Hotet från orden",b="Zureetha Fargaze håller uppsikt över den norra grottan ovanför Valley of Trials. Vidriga bekanta gömmer sig där inne, de svagaste husdjuren till Burning Blades kultister. Deras närvaro på de heliga träningsplatserna förolämpar orcherna och hotar dalen. När du rapporterar att du lyckats visar du att de som utövar felmagi fortfarande är redo att försvara Durotar mot fördärv."}},faq={{q="Varför skickar Ruzan mig till Zureetha Fargaze i stället för att belöna mig själv?",a="Zureetha Fargaze samordnar försvaret och arbetet med att rensa ut Burning Blade i Valley of Trials. Ruzan prövar din kontroll över mindre felvarelser och skickar dig sedan till Zureetha, så att hon kan erkänna din insats och införliva den i dalens försvar.",al={"varför träffa zureetha","från ruzan till zureetha","varför prata med zureetha"}},{q="Vilka är de vidriga följeslagarna?",a="Vidriga bekanta är mindre demoniska imps och undersåtar bundna till Burning Blade Coven. De tjänar mörkare herrar djupt inne i grottan med utsikt över Valley of Trials.",al={"vad är vidriga följeslagare","vidriga följeslagare bakgrund","burning blades följeslagare"}},{q="Var hittar jag Zureetha Fargaze?",a="Zureetha Fargaze står utomhus nära mitten av The Den i Valley of Trials, en kort promenad upp från träningslägret där Ruzan håller till.",al={"var finns zureetha","zureetha fargazes plats","zureetha karta"}},{q="Varför finns det ett uppdrag med exakt samma namn?",a="De flesta äventyrare får uppdraget Vile Familiars direkt av Zureetha Fargaze och jagar varelserna åt henne. Häxmästare får ett separat uppdrag av Ruzan och rapporterar sedan till Zureetha när de är klara.",al={"två vile familiars-uppdrag","dubbla vile familiars","häxmästares vile familiars"}},{q="Vad gör Burning Blade i Valley of Trials?",a="Burning Blade-kulten verkar i hemliga enklaver runt om i Durotar och försöker underminera Thralls nya hord inifrån. Från en grotta i Valley of Trials ger sig dess medlemmar på oerfarna noviser och sprider demoniskt fördärv under orchernas uppsyn.",al={"burning blade valley of trials","varför finns kultister i the den"}},{q="Utplånar jag kulten genom att döda de här följeslagarna?",a="Nej. De vidriga bekanta är husdjur och spejare åt de mörkare makterna inne i kulten. Att besegra dem är första steget mot att avslöja och rena bort det djupare kultisthotet i dalen.",al={"är burning blade besegrade","är kultisterna borta"}}},fp="14,182,22.356.0,23.358.0,75.258.0,27.166.0,34.148.0,52.194.0,56.268.0,47.188.0"}
P.entries["quest:15"] = {n="Investigate Echo Ridge",s="Marshal McBride skickar rekryter norrut när kobolder samlas vid Echo Ridge Mine. Gruvan förser Northshire Abbey och Stormwinds vakter med malm och råmaterial, och det växande hotet sätter båda i fara.",h="Marshal McBride skickar rekryter norrut när kobolder samlas vid Echo Ridge Mine.",kw={"echo ridge","elwynn","kobold","koboldarbetare","marshal mcbride","gruva","northshire","northshire valley"},ang={["faction:Alliance"]="Kobolder har nått ända fram till Stormwinds andliga hjärta i Northshire, ett tecken på rikets sårbarhet när dess reguljära styrkor är hårt ansträngda.",["profession:Mining"]="Koppar från Echo Ridge Mine är avgörande för smederna i Northshire, så det är viktigt för gruvarbetarnas försörjning att röja de underjordiska tunnlarna.",["race:Human"]="Som ung människa som inleder sin tjänstgöring i Northshire Valley får du tidigt chansen att bevisa ditt värde för riket genom att försvara Echo Ridge mot underjordiska skadedjur."},sec={{t="Ett växande angrepp",b="Efter tidiga skärmytslingar med kringströvande ohyra vid Northshires skogskant rapporterar spejare om ett mer organiserat hot. Kobolder har samlats i stort antal vid Echo Ridge Mine. Marshal McBride skickar dig norrut för att möta arbetarna vid ingången och ta reda på hur djupt de har slagit sig ner."},{t="Hot mot klostrets rikedom",b="Echo Ridge Mine förser brödraskapet i Northshire och Stormwinds vakter där med malm och råmaterial. Kobolder har tagit tunnlarna, stoppat brytningen och satt de lokala försvaren under press. McBride ber dig att döda tio arbetare, men angreppet sträcker sig djupare in i schakten än en patrull ovan jord kan nå."}},faq={{q="Vem skickar mig på det här uppdraget?",a="Marshal McBride, befälhavare för Stormwinds vakter vid Northshire Abbey, skickar dig för att undersöka saken efter att spejare upptäckt kobolder som samlas norrut.",al={"uppdragsgivare","vem ger uppdraget","marshal mcbride"}},{q="Var ligger Echo Ridge Mine?",a="Echo Ridge Mine ligger längst norrut i Northshire Valley, vid foten av kullarna ovanför klostret och dess vingårdar.",al={"echo ridge läge","var ligger gruvan","hitta echo ridge"}},{q="Varför är kobolder farliga för Northshire?",a="Kobolder förökar sig snabbt och svärmar genom underjordiska tunnlar i stora flockar. Deras grepp om Echo Ridge Mine stoppar livsviktig gruvdrift och hotar att övermanna den underbemannade dalen i Northshire.",al={"varför döda kobolder","varför är kobolder ett hot","koboldfara"}},{q="Vad händer när jag har besegrat arbetarna utanför?",a="När du återvänder bekräftas Marshal McBrides värsta farhågor: gruvan är helt översvämmad av kobolder. Han tar genast din hjälp i anspråk för en djupare framstöt i schakten i Skirmish at Echo Ridge.",al={"vad händer härnäst","fortsättningsuppdrag","nästa uppdrag"}},{q="Varför röjer inte Stormwinds armé gruvan själva?",a="Kung Varian Wrynn är försvunnen och resurserna är hårt ansträngda i Elwynn och vid de angränsande gränserna. Garnisonen i Northshire är för liten för att avvara hela patruller åt skadedjursbekämpning. Vakterna förlitar sig på dugliga nya rekryter.",al={"var finns stormwinds vakter","varför använda rekryter","stormwinds garnison"}},{q="Vilka slags kobolder finns vid gruvans ingång?",a="Koboldarbetare arbetar kring gruvans ingång och i de övre gångarna. De gräver tunnlar och samlar stearin till sin underjordiska koloni.",al={"koboldtyper","vilka fiender ska besegras","koboldarbetare"}}},fx={ffd728b0={q="Varför vill Marshal McBride att Echo Ridge Mine undersöks?",a="Marshal McBrides spejare upptäckte att koboldinvasionen är mycket större än Northshires garnison först insåg. Varelserna har lämnat de mindre lägren och slagit sig ner nära Echo Ridge Mine, vilket hotar en viktig lokal resurs. McBride behöver att du decimerar deras främsta led och tar reda på om en ännu större styrka förskansar sig längre in i gruvan, innan dalens försvar blir helt övermannat.",al={"varför rensa echo ridge","mcbrides motiv","varför undersöka echo ridge mine"}}},fp="22,201,23.280.0,28.331.0,29.146.0,37.111.0,40.183.0,48.192.1,57.216.0,56.136.0"}
P.entries["quest:150"] = {n="Murloc Poachers",s="Dockmaster Baren i Lakeshire behöver äventyrare som kan minska de växande murlocskarorna vid Lake Everstill innan de tömmer stadens främsta matförråd. Det som börjar som en praktisk skadedjursjakt väcker en oroande ekologisk fråga: varför slår kustvarelser sig ner så långt inne bland bergen?",h="Dockmaster Baren i Lakeshire behöver äventyrare som kan minska de växande murlocskarorna vid Lake Everstill...",kw={"dockmaster baren","dwarven fishing pole","lake everstill","lakeshire","murloc fin","tjuvfiskare","redridge"},ang={["faction:Alliance"]="Lakeshire är redan hårt ansatt av Blackrock-orcher och gnoller, så Alliansstaden har få försvarare att avvara för att trygga sina livsviktiga matförråd i Lake Everstill.",["race:Human"]="Redridge var en gång en fridfull semesterort för kungariket Stormwind. Att se dess orörda bergsvatten översvämmas av fientliga murlocs visar hur långt ordningen har försämrats."},sec={{t="Ett hot mot stadens förråd",b="Lake Everstill är Lakeshires livsnerv. Sjön mättar bergsstadens invånare och förser marknaden med färsk fisk. När stora murlocstammar började slå sig ner på grundvattnet insåg Dockmaster Baren att staden stod inför en ekologisk kris. De glupska fiskmännen genomsökte vattnet aggressivt och hotade att utrota de lokala fiskbestånden om ingen ingrep."},{t="En märklig flytt inåt landet",b="Murlocs är vanligtvis kustens asätare, så deras stora antal högt uppe i Redridge Mountains är ovanligt. Dockmaster Baren undrar öppet varför de rest så långt från det öppna havet. Oavsett om de drivits inåt landet av rovdjur från havet, flytt från revirstrider eller lockats av Lake Everstills rika vatten, tyder deras förflyttning på större störningar någon annanstans i regionen."}},faq={{q="Vem är Dockmaster Baren?",a="Dockmaster Baren har hand om hamnen och fisket längs Lake Everstills strand vid Lakeshire. Han sköter vattenburna leveranser och anlitar äventyrare för att skydda sjöns tillgångar mot hot från vattnet.",al={"baren","vem ger uppdraget murloc poachers","dockmaster baren"}},{q="Varför finns murlocs i Redridge Mountains?",a="Murlocs håller vanligtvis till vid kuster och i våtmarker, så deras närvaro vid Lake Everstill på hög höjd är ovanlig. Dockmaster Baren tror att stammarna vandrat långt inåt landet för att fly något ännu värre längs kusterna.",al={"varför finns murlocs i lake everstill","murlocs inåt landet redridge","varför fiskmän i sjön"}},{q="Vilket hot utgör murlocs mot Lakeshire?",a="Lakeshire är starkt beroende av Lake Everstill för fiske och handel. Murlocstammarna fiskar snabbt ut vattnet och hotar att svälta ut stadens främsta matförråd och skada den lokala ekonomin.",al={"varför döda murlocs","murlocproblem lakeshire","lake everstill fiskbestånd uttömt"}},{q="Varför samlar Dockmaster Baren in murlocfenor?",a="Baren samlar in åtta murlocfenor som konkret bevis på jakten. Fenorna bekräftar att äventyrarna aktivt minskar beståndet längs stränderna och håller de framryckande stammarna tillbaka.",al={"varför murlocfenor","fenbelöning lakeshire"}},{q="Finns det andra uppdrag som rör murlocs i Lake Everstill?",a="Ja, Dockmaster Baren erbjuder också ett tillhörande uppdrag, Selling Fish, där äventyrarna ska ta med sjöns berömda Spotted Sunfish till honom, antingen fiskade med spö eller tagna från murlocs.",al={"koppling till selling fish-uppdraget","andra murlocuppdrag redridge"}},{q="Vilken belöning ger Dockmaster Baren för att rensa bort tjuvfiskarna?",a="När Dockmaster Baren fått de åtta fenorna belönar han äventyraren med en välgjord Dwarven Fishing Pole för att uppmuntra ansvarsfull förvaltning av sjöns vatten.",al={"belöning för murloc poachers","dwarven fishing pole-uppdrag"}}},fx={["04b19c02"]={q="Varför vill Dockmaster Baren att murlocerna jagas?",a="Baren ansvarar för hamnen och fiskhandeln vid Lake Everstill. De växande murlocflockarna längs stränderna tjuvfiskar aggressivt och hotar att tömma stadens främsta lokala matförråd innan någon hinner stoppa dem.",al={"barens motiv","varför decimera murlocer","varför döda tjuvfiskarna"}},["38e35746"]={q="Vad används Murloc Fin till?",a="Fenorna fungerar som fysiskt bevis på att jakten är utförd. Baren har inget särskilt hantverk eller någon alkemisk användning i åtanke. Att samla in åtta avskurna fenor visar helt enkelt att du har drivit tillbaka tjuvfiskarna som minskar fiskbeståndet i Lake Everstill.",al={"användning för murloc fin","vad används murloc fin till","varför murlocfenor"}},["4daf19f8"]={q="Vilka är murloc-tjuvfiskarna som jagas vid Lake Everstill?",a="Du jagar de framryckande murlocer som samlats kring Lake Everstills östra stränder. Dessa groddjurslika rovdjur håller ovanligt långt från havet och har börjat slå läger och äta upp sjöns sötvattensfiskar.",al={"vilka är tjuvfiskarna","mål för murlocjakten","varför finns murlocer vid lake everstill"}}},fp="15,179,29.323.0,24.382.0,24.202.0,38.209.0,45.160.0,46.132.0,57.152.0,65.135.0"}
P.entries["quest:1501"] = {n="Creature of the Void",s="I Orgrimmar skickar Gan'rul Bloodeye en ung häxmästare för att hämta den stulna Tablet of Verga. De förrädiska Burning Blade-kultisterna tog den till sin grotta i Skull Rock, och dess runor behövs för att frammana en voidwalker.",h="I Orgrimmar skickar Gan'rul Bloodeye en ung häxmästare för att hämta den stulna Tablet of Verga.",kw={"burning blade","cleft of shadow","creature of the void","gan'rul bloodeye","orgrimmar","skull rock","tablet of verga","voidwalker","kriglockaruppdrag"},ang={["class:Warlock"]="Som häxmästare står du inför en grundläggande invigningsrit: att gå från små imps till att behärska en skuggvarelse för frontlinjen.",["faction:Horde"]="Som medlem av Thralls Hord tillhör du ett folk som misstror utövare av felmagi. Mentorer som Gan'rul vägleder dem som studerar de mörka konsterna, så att de använder sina krafter i krigshövdingens tjänst.",["race:Orc"]="Som orc, hemsökt av Skugg rådets historia, kan du finna viss hämnd i att jaga Burning Blade, vars medlemmar fortfarande omfamnar demonisk förödelse."},sec={{t="En vansklig konst",b="Gan'rul Bloodeye tränar Hordens häxmästare i Orgrimmars Cleft of Shadow. Thralls nya rike betraktar felmagi med stor misstänksamhet på grund av orcstammarnas mörka historia. Gan'rul säger att få sanna häxmästare återstår i Horden, men att deras farliga färdigheter är avgörande för dess överlevnad. För att tjäna krigshövdingen måste en lärling lära sig mer än impens kaotiska eld; de måste behärska väsen av ren skugga och uthållighet."},{t="Den stulna tavlan",b="Runorna som behövs för att frammana en voidwalker finns inristade på Tablet of Verga. Burning Blade, en fanatisk skuggkult, stal reliken och gömmer sig i en grotta i Skull Rock, alldeles under krigshövdingens näsa. Gan'rul skickar in dig i kultisternas näste för att återta tavlan och utdela ett blodigt slag mot avfällingarna som drar skam över alla häxmästare."}},faq={{q="Vem är Gan'rul Bloodeye?",a="Gan'rul Bloodeye är en erfaren häxmästarlärare i Orgrimmars Cleft of Shadow. Han har uppsikt över unga häxmästare i Horden och lär dem att tygla mörka krafter och binda utomvärldsliga tjänare utan att falla för korruptionen.",al={"gan'rul","ganrul bloodeye","vem ger uppdraget"}},{q="Vad är Tablet of Verga?",a="Tablet of Verga bär på särskilda maningsrunor som behövs för att kalla en voidwalker från Nether. Burning Blade stal den, och Gan'rul behöver den för att vägleda lärlingen genom ritualen.",al={"tablet of verga","verga-tavlan","vad är tavlan"}},{q="Var ligger Skull Rock?",a="Skull Rock är en skuggig grotta direkt öster om Orgrimmar, längs Durotars karga klippor. Burning Blade-kultister gömmer sig där.",al={"skull rock plats","var ligger skull rock","var hittar man tavlan"}},{q="Varför avskyr Gan'rul Bloodeye Burning Blade?",a="Burning Blade tjänar demoniska herrar och motarbetar Thralls Hord. Gan'rul ser kulten som ett gissel för krigshövdingen och en vårdslös plåga som väcker misstankar mot och drar vanära över alla häxmästare.",al={"burning blade kriglockare","varför hata burning blade"}},{q="Varför behöver kriglockare frammana en voidwalker?",a="Voidwalkers är väsen från Nether som kan uthärda enorma bestraffningar och skydda den som frambesvärjer dem. Att lära sig binda en är ett viktigt steg för en häxmästares överlevnad och förmåga att frammana väsen.",al={"varför voidwalker","voidwalkerns syfte"}},{q="Vad händer när tavlan har återtagits?",a="När Gan'rul fått Tablet of Verga ger han lärlingen de nödvändiga runorna och kallar dem till sig för att slutföra ritualen i ”The Binding”. Där måste häxmästaren fysiskt kuva den frambesvärjda voidwalkern för att behärska den.",al={"nästa uppdrag","what comes next"}}},fx={b65e3db1={q="Varför vill Gan'rul Bloodeye att detta blir gjort?",a="Gan'rul Bloodeye känner pressen av att Horde har så få trollkarlar kvar. Han tror att det är avgörande för Horde och Warchief att lovande lärjungar som du snabbt mognar. När du återtar den stulna Tablet of Verga får du runorna som låter dig frammana en voidwalker, vilket för din utbildning framåt. Du slår också mot Burning Blade-kultisterna som stal den och ständigt drar skam över alla trollkarlar.",al={"gan'ruls motiv","varför skickar gan'rul dig","varför återta tablet of verga"}},["6701b0d8"]={q="Vilka skickas du att möta vid Skull Rock?",a="Du skickas mot Burning Blade-kultisterna som gömmer sig i Skull Rock, strax öster om Orgrimmar. Dessa förrädiska trollkarlar konspirerar mot Horde och stal Tablet of Verga från Gan'rul. De verkar i Durotars skuggor, använder demonisk magi utanför Warchiefs lag och ställer ständigt till problem för den unga nationen.",al={"vem finns vid skull rock","burning blade i skull rock","vem stal tabletten"}},["2e9ce581"]={q="Varför skickar Gan'rul Bloodeye dig i stället för stadsvakterna?",a="Darkfire Enclave verkar i Thralls Orgrimmar med tillspänd tolerans. Om Gan'rul bad stadsvakterna att jaga stulna ockulta artefakter skulle det rikta oönskad uppmärksamhet mot hans hemliga verksamhet. Än viktigare är att prövningarna i Skull Rock behövs för att testa hur din kraft växer. En trollkarl måste visa att han kan stå emot demonisk fördärv innan han får förtroendet att frammana och binda en varelse från Void.",al={"varför skicka en lärling","varför inte skicka vakterna","varför jag, varelse från void"}}},fp="20,207,16.417.0,17.366.0,24.208.0,28.193.0,20.124.0,52.209.0,44.189.0,41.220.1"}
P.entries["quest:1502"] = {n="Thun'grim Firegaze",s="Högt uppe på Thorn Hill lever Thun'grim Firegaze tillbakadraget och håller sig till sin ensliga smedja. Efter sina första lektioner i försvar korsar hordens krigare The Barrens för att söka upp honom och få vapen som passar deras växande skicklighet.",h="Högt uppe på Thorn Hill lever Thun'grim Firegaze tillbakadraget och håller sig till sin ensliga smedja.",kw={"smed","crossroads","forged steel","the barrens","thorn hill","thun'grim firegaze","uzzek","krigarvapen"},ang={["class:Warrior"]="Som ung krigare i Horden skickas du ut i vildmarken för att hitta Thun'grim och förtjäna ett karaktäristiskt smitt vapen som kompletterar din stridsutbildning.",["faction:Horde"]="Horden är beroende av erfarna hantverkare vars kvalitetsstål beväpnar frontsoldaterna som försvarar Kalimdor.",["profession:Blacksmithing"]="Thun'grim följer en ensam orchisk smedtradition och uthärdar isolering och blindhet för att forma het metall till dödliga vapen."},sec={{t="Eremiten på höjden",b="När du visar skicklighet i försvarskonsten under veteraner som Uzzek skickas du iväg för att vässa din stridsförmåga med lämpliga vapen. Vanliga vapenkammare räcker bara en bit för en frontsoldat. Verkligt mästerskap kräver ett personligt vapen från en berömd smed. I The Barrens är Thun'grim Firegaze den smeden, en åldrande orch som har lämnat bosättningslivet bakom sig för att hålla en avlägsen smedja högt ovanför slätterna."},{t="Ett liv vid smedjans eld",b="Thun'grim Firegaze bor högst uppe på Thorn Hill, en karg höjd öster om The Crossroads där vilda rovfåglar och fientliga quilboar strövar omkring. Han tillbringar sina ensliga timmar med att forma metall, långt från stadsmurarnas skydd. Årtionden av att stirra in i smedjans brännande lågor har förstört hans syn, men hans instinkter är fortfarande skarpa. När du klättrar upp och stör hans ensamhet förstår Firegaze varför: en krigare har kommit för att söka smitt stål."}},faq={{q="Vem skickar krigare för att hitta Thun'grim Firegaze?",a="Uzzek, en krigartränare längs vägen nära Far Watch Post i östra The Barrens, skickar iväg dig när du har visat att du behärskar försvarsteknikerna.",al={"vem ger uppdraget","vem startar thun'grim firegaze","uppdragsgivare"}},{q="Var finns Thun'grim Firegaze?",a="Thun'grim bor på en avlägsen lägerplats högst uppe på Thorn Hill, en hög bergsrygg rakt öster om The Crossroads i The Barrens.",al={"thun'grims plats","var finns thun'grim","hitta firegaze"}},{q="Varför bor Thun'grim ensam ute i bergen?",a="Thun'grim har vigt sitt liv åt metallhantverk, långt från stadens distraktioner. Han arbetar ensam vid sitt städ högst uppe på Thorn Hill, trots de farliga bestarna och quilboarerna på de omgivande bergsryggarna.",al={"varför är thun'grim eremit","firegaze eremit"}},{q="Vad hände med Thun'grim Firegazes ögon?",a="Årtionden av oavbrutet arbete över glödande kol och utsatthet för smedjans intensiva hetta har till stor del förstört Thun'grim Firegazes syn.",al={"är thun'grim blind","firegazes ögon"}},{q="Vad händer efter mötet med Thun'grim Firegaze?",a="När du rapporterar till Thun'grim förstår han att du behöver vapen och ber dig samla råmaterial så att han kan smida ett åt dig.",al={"nästa uppdrag","vad händer efter thun'grim","fortsättning på forged steel"}},{q="Kan alla klasser ta det här uppdraget?",a="Nej. Den här vägen är till för horde­krigare som söker specialanpassade vapen.",al={"är det här bara för krigare","vem kan göra thun'grim firegaze"}}},fx={["65de68fe"]={q="Varför skickar Uzzek dig till Thun'grim Firegaze?",a="Uzzek vet att enbart stridsträning inte håller en krigare vid liv utan rätt utrustning. En krigares vapen måste smidas efter högsta standard, och Thun'grim Firegaze är känd i Horde för sitt mästerliga hantverk. Uzzek skickar dig till honom så att du kan förtjäna ett vapen som motsvarar din växande styrka.",al={"varför hitta thun'grim","uzzeks motiv för thun'grim","varför träffa thun'grim firegaze"}}},fp="18,210,23.410.0,24.429.0,46.144.0,36.117.0,47.187.0,43.129.0,44.126.0,30.61.0"}
P.entries["quest:1503"] = {n="Forged Steel",s="Thun'grim Firegaze väntar i östra The Barrens på stålet som stals från hans läger. Han erbjuder sig att smida ett vapen åt krigaren som hämtar tillbaka det.",h="Thun'grim Firegaze väntar i östra The Barrens på stålet som stals från hans läger.",kw={"the barrens","firegaze","smitt stål","järnkista","quilboar","razormane","stålbarren","thun'grim","krigarvapen"},ang={["class:Warrior"]="Som krigare hämtar du tillbaka stulet stål och visar Thun'grim vad du går för innan han smider ett vapen åt dig.",["faction:Horde"]="Som medlem i Horden möter du Razormane-räder mot läger och försörjningslinjer i The Barrens.",["profession:Blacksmithing"]="Som smed ser du varför förädlat stål är viktigt för Horden i Kalimdors hårda gränsland."},sec={{t="En utnyttjad blind fläck",b="Thun'grim Firegaze har en smedja i östra The Barrens, långt från Orgrimmar. År vid ässjan har försvagat hans syn. Quilboar från närbelägna Razormane använde den svagheten för att stjäla en järnkista från hans läger. Några grymtade och förde oväsen på ena sidan för att dra till sig hans blick, medan andra smög in från den andra och bar bort hans Forged Steel Bars."},{t="Värdefull metall, okunniga tjuvar",b="Thun'grim är arg över stölden, men tvivlar på att Razormanes kan använda stålet. Quilboar hantverkar med sten, betar och taggiga rötter, inte förädlad metall. Den tunga kistan står kvar vid en trasig vagn i deras läger, orörd och värdelös för dem. För Thun'grim är stålet materialet han behöver för att smida vapen åt unga krigare i Horden."}},faq={{q="Vem är Thun'grim Firegaze?",a="Thun'grim Firegaze är en orkisk rustningssmed och vapensmed i östra The Barrens. Trots att synen sviker honom fortsätter han arbeta och beväpnar unga krigare i Horden.",al={"thungrim firegaze","vem är smeden","thungrim"}},{q="Varför stal quilboarerna stålet?",a="Razormane-quilboar stal järnkistan från Thun'grims läger under en avledningsmanöver nattetid. De saknar skickligheten att bearbeta det smidda stålet därinne.",al={"varför stjäla metall","varför stal quilboarerna","vad ville razormane ha"}},{q="Var förvaras stålbarren?",a="Forged Steel Bars ligger inlåsta i Stolen Iron Chest nära en trasig vagn på Razormane Grounds, nordväst om Thun'grims läger.",al={"var finns kistan","plats för stulen järnkista","var finns stålbarren"}},{q="Vilket vapen erbjuder Thun'grim i utbyte?",a="Thun'grim erbjuder unga krigare ett val av nysmidda vapen i utbyte mot att de hämtar tillbaka hans stål.",al={"vapen som belöning","vad får jag","belöning i smitt stål"}},{q="Hur lyckades Razormanes lura Thun'grim?",a="Razormanes utnyttjade att Thun'grims syn sviktar. Några rövare grymtade och förde oväsen för att dra till sig hans uppmärksamhet, medan andra smög in i lägret och tog kistan.",al={"hur rånade de honom","hur blev thungrim rånad","distrahera thungrim"}},{q="Varför bor Thun'grim ute i The Barrens i stället för i Orgrimmar?",a="Thun'grim har en enslig utpost i östra The Barrens, där han beväpnar och vägleder krigare på väg från Durotar.",al={"varför är thungrim här","varför läger i the barrens"}}},fx={["46a881ef"]={q="Varför vill Thun'grim Firegaze att stålbarren hämtas tillbaka?",a="Thun'grim är en mästersmed, och fint bearbetad metall som dessa smidda stålbarrer är avgörande för hans hantverk. Att snattande quilboarer stal hans förråd mitt framför näsan på honom sårade hans stolthet. Än värre är att han nu saknar materialet han behöver för att smida vapen. Han tänker inte lämna ifrån sig något av sina smidda vapen förrän hans stulna lager har återställts.",al={"varför återta smitt stål","thun'grims motiv","varför vill thun'grim ha tillbaka stålet"}},["4f2d7c31"]={q="Varför behöver Thun'grim att du hämtar stålet i stället för att gå själv?",a="Thun'grims syn har försämrats kraftigt på äldre dar, en svaghet som Razormane-quilboarerna utnyttjade när de rånade honom. Han ser inte tillräckligt bra för att spåra dem till deras törnbeklädda gömställen eller slåss på jämlika villkor. Därför förlitar han sig på en duglig krigare som du, som kan ta sig in i quilboarernas läger och hämta den stulna kistan.",al={"varför kan inte thun'grim hämta stålet","varför skicka mig till thun'grim","varför behöver thun'grim hjälp"}},["758f9f11"]={q="Vilka är Razormanes som håller stålet?",a="Tjuvarna tillhör quilboarstammen Razormane, vilda svinlika humanoider som hör hemma i Barrens. De är aggressiva och hårdnackat revirhävdande, och håller till i taggiga läger över slätterna. De plundrar ofta resenärer och ensliga läger på förråd, trots att de sällan förstår hur man bearbetar förädlade material som smitt stål.",al={"vilka är razormanes","quilboar nordväst","vem stal järnkistan"}}},fp="12,147,22.341.0,33.328.0,26.156.0,37.144.0,37.133.0,43.104.0,49.167.0,64.117.0"}
P.entries["quest:1504"] = {n="The Binding",s="Binding är den sista invigningsritualen i Orgrimmar för unga hordeiska häxmästare som vill befalla över en voidwalker. Under Gan'rul Bloodeyes ledning ristar den sökande in tecken från Tablet of Verga i Neeru Fireblades kallelsecirkel för att frambesvärja, kuva och för evigt förslava en varelse från Tomrummet.",h="Binding är den sista invigningsritualen i Orgrimmar för unga hordeiska häxmästare som vill befalla över en...",kw={"cleft of shadow","gan'rul bloodeye","glyphs of summoning","neeru fireblade","orgrimmar","tablet of verga","binding","voidwalker","häxmästare"},ang={["class:Warlock"]="Riten markerar en häxmästares upphöjelse från att leka med obetydliga imps till att befalla skuggans fasor vid frontlinjen. Den befäster den skoningslösa filosofin att makt måste erövras och förslavas.",["faction:Horde"]="Thralls Horde vänder sig officiellt bort från det förflutnas demoniska fördärv, men häxmästarmagi tolereras av praktiska skäl under Orgrimmar, under vaksamma ögon.",["race:Orc"]="Orchäxmästare verkar i dolda vrår som Cleft of Shadow och utövar sin mörka konst långt från både hövding Thralls ogillande blick och den schamanistiska pånyttfödelsen."},sec={{t="Underkuva Tomrummet",b="För en häxmästare under invigning som smyger i de mörka gångarna i Cleft of Shadow är det rena barnleken att kalla fram en imp. Att kuva en voidwalker är det första verkliga provet på viljestyrka och magisk dominans. Häxmästare ingår inga artiga pakter och umgås inte med dessa utomvärldsliga fasor. De sliter dem över dimensionerna med råstyrka och binder dem i evig träldom. Gan'rul Bloodeye kräver att den invigde använder tecknen som skrivits av från Tablet of Verga och kallar monstret direkt in i Neeru Fireblades ritualcirkel för att kuva det i envig."},{t="En ständig vaksamhet",b="Att besegra varelsen i fysisk och magisk strid är bara halva kampen. Som Gan'rul Bloodeye varnar accepterar en bunden voidwalker aldrig sin träldom. Den tjänar sin herre som ett tåligt, skuggigt skydd i strid, men spanar ständigt efter stunder då koncentrationen brister. En häxmästare måste hålla ett orubbligt mentalt grepp om sin tjänare, för så fort disciplinen sviktar slukar voidwalkern gärna själen hos den som band den."}},faq={{q="Vilken sorts varelse kallas fram?",a="Den invigde kallar fram en voidwalker, en väldig varelse smidd av ren kosmisk skugga och tomrumsenergier. Till skillnad från imps, som är listiga demoner, är voidwalkers brutala varelser som slitits från Twisting Nether och Tomrummet. Häxmästare använder dem främst för att ta emot förödande fysiska slag.",al={"vad kallas fram","vilken demon","voidwalkerns bakgrund"}},{q="Var äger kallelseritualen rum?",a="Ritualen utförs i Neeru Fireblades tält, som ligger i Cleft of Shadow under Orgrimmar. En särskild kallelsecirkel inristad i marken samlar de dimensionella energier som behövs för att slita voidwalkern ur Nether.",al={"var kallar jag fram den","kallelsecirkelns plats","ritualplats"}},{q="Vad används Tablet of Verga till?",a="Tablet of Verga innehåller de uråldriga, särskilda tecken som krävs för att manifestera en voidwalker och slita den genom verklighetens väv. Den invigde studerar inskriptionerna för att skapa Glyphs of Summoning, som behövs för att upprätta kallelsecirkeln.",al={"tablet of verga","glyphs of summoning"}},{q="Varför måste häxmästaren besegra voidwalkern?",a="Häxmästare kontrollerar varelser från andra plan genom ren dominans. Innan en voidwalker ger upp sin essens och lyder order måste den som kallat fram den bevisa sin mästarkunskap genom att besegra varelsen fysiskt och magiskt och tvinga den till underkastelse.",al={"varför döda voidwalkern","varför slåss mot den","bindningsprocess"}},{q="Vem är Gan'rul Bloodeye?",a="Gan'rul Bloodeye är en senior häxmästartränare i Horden, stationerad i Orgrimmars skuggiga grottor i Cleft of Shadow. Han leder unga hordeiska utövares mörka utbildning och lär dem att förslava mäktigare demoniska varelser.",al={"vem är gan'rul","gan'rul bloodeye"}},{q="Kan man någonsin lita helt på en bunden voidwalker?",a="Aldrig. Som Gan'rul säger väntar även en voidwalker som tjänat i åratal utan motstånd bara på att dess herre ska sänka garden. Bandet kräver ständig vaksamhet, eftersom varelsen hyser evigt agg mot sin fångvaktare.",al={"vänder sig voidwalkern mot mig","är voidwalkern lojal","kan demoner göra uppror"}}},fx={["066e41c9"]={q="Varför vill Gan'rul Bloodeye att detta blir gjort?",a="Gan'rul Bloodeye är instruktör för lovande trollkarlar som samlas i Cleft of Shadow. Han prövar och formar din disciplin genom att få dig att bredda dina kunskaper i mörk magi. För att du ska kunna styra större mängder felmagi i Hordes tjänst måste du bevisa din skicklighet genom att frammana och kuva en tålig voidwalker.",al={"gan'rul bloodeyes motiv","varför frammana voidwalker åt gan'rul","varför vill gan'rul att jag binder en voidwalker"}},["3b87ecbf"]={q="Varför låter Gan'rul Bloodeye dig slåss mot voidwalkern själv?",a="En frammalad undersåte kan bara bindas genom trollkarlens rena viljestyrka och kraft. Varken Gan'rul Bloodeye eller stadsvakterna kan böja demonens ande till din vilja. Du måste besegra den med din egen magiska och fysiska styrka och visa att ditt sinne och din själ är starka nog att hålla den i slaveri.",al={"varför slåss ensam mot voidwalker","varför kan inte gan'rul slåss mot voidwalker","varför jag ska binda voidwalkern"}}},fp="11,326,23.564.0,17.457.0,40.290.0,44.249.0,37.244.0,43.227.0,24.242.0,45.244.0"}
P.entries["quest:1505"] = {n="Veteran Uzzek",s="Veteran Uzzek är ett Horde-uppdrag som skickar lovande unga krigare för att söka upp en erfaren stridsinstruktör. Uzzek är stationerad strax söder om Far Watch Post, mellan Durotar och The Barrens, och lär nya rekryter att verklig krigarkraft kräver disciplinerade studier såväl som styrka.",h="Veteran Uzzek är ett Horde-uppdrag som skickar lovande unga krigare för att söka upp en erfaren...",kw={"the barrens","stridsundervisning","durotar","far watch post","horde","uzzek","veteran uzzek","krigare"},ang={["class:Warrior"]="Unga krigare skickas till Uzzek för att lära sig att råstyrka inte räcker och att sann styrka kommer av att vara en hängiven elev i strid.",["faction:Horde"]="Horde sätter stridsförmåga främst och låter erfarna krigsveteraner vid gränsposter vägleda nästa generation."},sec={{t="Krigarens väg",b="I Hordes kultur är stridsstyrka självklar och vördas över allt annat. Men råstyrka ensam gör ingen mästare. Erfarna befälhavare vet att de främsta krigarna också är ödmjuka elever i sitt hantverk, redo att vässa sina instinkter genom disciplin och studier. De som vill gå vidare från grundträningen får söka upp dem som överlevt krigets prövningar."},{t="Veteranen vid gränsen",b="För att få avancerad stridsvägledning reser unga krigare till de torra gränslanden mellan Durotar och The Barrens. Strax söder om Far Watch Post, den befästa orkgarnison som bevakar den östra gränsen, bor Uzzek. Efter oräkneliga blodiga strider ägnar Uzzek nu sina år åt att vägleda lovande nya rekryter i stridens och den taktiska överlevnadens viktiga konster."}},faq={{q="Vem är Veteran Uzzek?",a="Uzzek är en härdad Horde-veteran som undervisar unga krigare i strid. Efter att ha överlevt otaliga drabbningar för han nu vidare sin hårt förvärvade krigarkunskap från sitt läger nära gränsen mellan Durotar och The Barrens.",al={"vem är uzzek","uzzek i berättelsen","vem är veteranen"}},{q="Var hittar man Uzzek?",a="Uzzek finns söder om Far Watch Post, orkgarnisonen vid gränsen mellan Durotar och The Barrens i öster.",al={"var finns uzzek","uzzek plats","hitta uzzek"}},{q="Vad är Far Watch Post?",a="Far Watch Post är en orkgarnison som markerar The Barrens östra gräns. Den bevakar övergången från Durotar och fungerar som en försvarspost för Horde.",al={"vad är far watch post","far watch posts syfte"}},{q="Varför skickas unga krigare till Uzzek?",a="Blivande krigare söker upp Uzzek för stridsundervisning. Inom Horde är styrka självklar, men verkligt stora krigare måste också behärska disciplin, studier och stridsteknik.",al={"varför besöka uzzek","vad lär uzzek ut","krigarundervisning"}},{q="Vad säger Uzzek när du kommer fram?",a="När du kommer till hans post hälsar Uzzek den unge krigaren varmt välkommen, redo att börja pröva deras hängivenhet och lära dem krigets vägar.",al={"vad händer när man talar med uzzek","lämna in uzzek-uppdraget"}},{q="Hur ser Horde på sina krigare?",a="Horde vördar sina krigare för deras obestridliga styrka och hängivenhet åt strid, men traditionen betonar att verkligt mästerskap kräver disciplin och lärdomar från erfarna veteraner.",al={"vem vördar krigare","hordes krigarkultur"}}},fp="13,283,23.417.0,25.376.0,21.229.0,25.131.0,23.163.0,37.195.0,36.143.0,37.194.0"}
P.entries["quest:1506"] = {n="Gan'rul's Summons",s="Gan'rul's Summons är en brådskande kallelse som Ophek överlämnar till unga horderockare i Razor Hill. Den erfarne ockultisten Gan'rul Bloodeye kräver att de genast infinner sig i Cleft of Shadow för att fortsätta sin träning. Det är första steget mot att bemästra den mörka konsten att åkalla en voidwalker.",h="Gan'rul's Summons är en brådskande kallelse som Ophek överlämnar till unga horderockare i Razor Hill.",kw={"bloodeye","cleft of shadow","gan'rul","ophek","orgrimmar","kallelse","voidwalker","ockultistuppdrag"},ang={["class:Warlock"]="Den här kallelsen markerar att du har lämnat grundläggande impbesvärjelser bakom dig och öppnar vägen till en voidwalkers pålitliga skydd.",["faction:Horde"]="Ockultister har en osäker plats i Thralls nya horde. De tolereras för sin praktiska kraft, men hålls avskilda djupt under Orgrimmar."},sec={{t="En kallelse till skuggorna",b="Nybörjarockare som verkar i Durotar förblir inte obemärkta länge. Så snart en utövare visar tillräcklig skicklighet med sin första imp når ryktet Orgrimmars djupare underjordiska skrymslen. Ophek, som är stationerad ute i Durotar, agerar budbärare åt de erfarna mörka magikerna. Han hejdar ockultister med en brådskande order att släppa allt de håller på med och bege sig till Cleft of Shadow."},{t="Den erfarne ockultisten",b="Gan'rul Bloodeye övervakar träningen av unga orciska ockultister inom horden. Från de dolda grottorna under Orgrimmar håller han en skör balans mellan att vässa dödlig felkraft och att skydda den farliga konsten från krigshövdingens ogillande blick. När Bloodeye kallar en lärling till sin krets betyder det att enkla eldbesvärjelser och imps inte längre räcker. Det är dags att binda en varelse från Twisting Nether."}},faq={{q="Vem är Ophek?",a="Ophek är en bundsförvant till ockultisterna som är stationerade ute i Durotar. Han håller utkik efter lovande utövare och levererar order från erfarna mentorer som Gan'rul Bloodeye.",al={"ophek","vem ger uppdraget","uppdragsgivare"}},{q="Var finns Gan'rul Bloodeye?",a="Gan'rul Bloodeye bor i Cleft of Shadow, det mörka grottsystemet under Orgrimmars klippiga platåer.",al={"var finns gan'rul","gan'ruls plats","hitta gan'rul bloodeye"}},{q="Varför vill Gan'rul Bloodeye träffa mig?",a="Gan'rul anser att du är erfaren nog att gå vidare med dina studier i ockultism och börja de farliga ritualer som krävs för att åkalla och binda en voidwalker.",al={"varför kallelse","vad vill gan'rul","uppdragets anledning"}},{q="Vad händer när jag rapporterar till Gan'rul?",a="När du rapporterar till Gan'rul inleds uppdraget 'Creature of the Void'. Du får hämta de komponenter och den kunskap som behövs för att dra en tomhetsvarelse till Azeroth.",al={"nästa uppdrag","vad händer efter gan'rul's summons"}},{q="Varför håller sig ockultisterna i Cleft of Shadow?",a="Ockultister utövar flyktig felmagi, som Thrall och den traditionella shamanistiska horden ser med djup misstänksamhet på. Cleft of Shadow låter dem utföra ritualer utom allmänhetens insyn.",al={"varför cleft of shadow","varför gömmer sig ockultister","ockultistgrotta orgrimmar"}},{q="Kan alla klasser ta det här uppdraget?",a="Nej. Uppdraget erbjuds enbart till hordeockultister som har nått den tionde träningscirkeln.",al={"är uppdraget bara för ockultister","vem får uppdraget"}}},fx={f5421555={q="Varför skickar Ophek dig till Gan'rul?",a="Ophek fungerar bara som springpojke och budbärare åt Gan'rul Bloodeye. Högt uppsatta häxmästare i Cleft of Shadow strövar inte omkring i Orgrimmar och letar själva efter lärlingar. De skickar underhuggare för att hämta dem de behöver. Ophek vet bättre än att dröja med Gan'ruls kallelse och varnar dig för att det sällan slutar väl att låta en häxmästare vänta.",al={"varför skickar ophek iväg mig","opheks motiv","varför levererar ophek kallelsen"}}},fp="17,290,24.399.0,18.455.0,13.157.0,34.132.0,41.147.0,40.163.0,48.182.0,30.108.0"}
P.entries["quest:1507"] = {n="Devourer of Souls",s="Gan'rul Bloodeye skickar en blivande hordekriglockare för att inleda vägen mot att frammana och behärska en succubus. I Orgrimmars Cleft of Shadow söker kriglockaren råd hos Cazul om hur demonen ska lockas fram och bindas.",h="Gan'rul Bloodeye skickar en blivande hordekriglockare för att inleda vägen mot att frammana och behärska en...",kw={"bindning","cazul","cleft of shadow","gan'rul bloodeye","orgrimmar","succubus","åkallning","häxmästare"},ang={["class:Warlock"]="Som kriglockare tar du ett steg mot att behärska demoner som dominerar och förför sinnen. Ritualen kräver mental beslutsamhet såväl som rå felmagi.",["faction:Horde"]="Som medlem av Horden ser du kriglockare utföra farliga ritualer i Cleft of Shadows fuktiga, avskilda skrymslen. Thralls shamaner och krigare övar offentligt, medan kriglockarna arbetar utom synhåll."},sec={{t="Ett steg in i förföriska skuggor",b="Hordens kriglockare som behärskar mindre demoner som imps och voidwalkers kan därefter söka sig till en succubus. Gan'rul Bloodeye vakar över de mörka konsterna under Orgrimmar och avgör när en kriglockare är redo att kalla hit en från Twisting Nether. En succubus kan vända de svaga mot varandra, så att binda en kräver både finess och styrka."},{t="Cazuls lärdomar",b="En succubus utnyttjar dödligas begär, så råa besvärjelser räcker inte för att kalla hit en. Besvärjaren måste locka den med ett föremål fyllt av ren kärlek och hängivenhet. Gan'rul vill eller kan inte själv tillhandahålla en sådan relik, så han skickar kriglockaren genom Cleft of Shadow till Cazul. Den uråldrige kriglockaren känner till de arkana och demoniska ritualer som behövs för nästa del av ritualen."}},faq={{q="Vad är syftet med det här uppdraget?",a="Det här inleder en blivande hordekriglockares väg mot att lära sig frammana och behärska en succubus. Det för dig i kontakt med mentorer i Cleft of Shadow, som lär dig om demonens natur och hur du lockar fram en från Twisting Nether.",al={"varför göra devourer of souls","start på succubusuppdraget","vad låser uppdraget upp"}},{q="Var hittar jag Cazul?",a="Cazul finns i Cleft of Shadow, en grotta under Orgrimmar där tränare för skurkar och kriglockare övar utom synhåll för Warchief.",al={"cazuls plats","var finns cazul","hitta cazul i orgrimmar"}},{q="Varför behöver en häxmästare ett kärleksföremål för att åkalla en succubus?",a="Succubi livnär sig på dödligas känslor, hängivenhet och svaga vilja. För att locka fram en från Twisting Nether erbjuder besvärjaren ett kraftfullt tecken på äkta hängivenhet och tillgivenhet som bete, för att sedan övermanna och binda demonen.",al={"kärlek som lockbete för succubus","varför kärleksföremål till succubus","succubus åkallningslore"}},{q="Vem är Gan'rul Bloodeye?",a="Gan'rul Bloodeye är en högt uppsatt tränare för Hordens kriglockare i Orgrimmars Cleft of Shadow. Han vägleder dem som utvecklas i konsten att binda allt mäktigare demoniska tjänare.",al={"vem ger devourer of souls","gan'ruls bakgrund","gan'rul bloodeye"}},{q="Vilken nivå krävs för att börja uppdraget?",a="En kriglockare måste nå nivå tjugo innan Gan'rul bedömer att hens magiska skicklighet och mentala styrka räcker. Ritualen innebär att förhandla med en succubus och överleva mötet.",al={"vilken nivå för succubus","devourer of souls nivå","nivåkrav för succubuskedjan"}},{q="Vad händer efter att man talat med Cazul?",a="När du talar med Cazul leder det dig vidare till Blind Cazul. Där söker du upp Zankaja i Orgrimmar, vars partner Dogran inte har återvänt från sin tjänstgöring vid The Crossroads. Sökandet efter ett lämpligt kärlekstecken börjar hos henne.",al={"nästa uppdrag efter devourer of souls","vad händer efter cazul","succubusuppdragets fortsättning"}}},fx={["0f1c8f0b"]={q="Varför vill Gan'rul Bloodeye att du ska åkalla en succuba?",a="Som mentor bland Horde-häxmästarna i Cleft of Shadow ska Gan'rul Bloodeye vägleda dig mot mörk magi med större djup och kraft. Han tror att du har den mentala styrka och list som krävs för att tämja en succuba i stället för att falla för dess lockelse. För honom utökar varje tjänare du lyckas binda inflytandet och den dödliga räckvidden hos er gemensamma demoniska konst.",al={"varför vill gan'rul ha detta","gan'rul bloodeyes motiv","varför åkalla succuba åt gan'rul"}},cde5d57b={q="Varför skickar Gan'rul dig i stället för att själv söka efter lockbetet?",a="En häxmästare kan inte bara tilldelas fullständig makt över en demon. Bindningen måste smidas genom din egen prövning och påhittighet. Gan'rul förväntar sig att du bevisar ditt värde genom att hitta den nödvändiga symbolen för hängivenhet och ensam kuva besten. På så sätt visar du din egen dominans i stället för att förlita dig på någon annans kraft.",al={"varför jag åt gan'rul","varför skicka mig efter succuban","varför kan inte gan'rul göra det"}}},fp="17,205,29.326.0,17.374.0,34.226.0,22.136.0,63.207.0,24.181.0,43.183.0,39.200.1"}
P.entries["quest:1508"] = {n="Blind Cazul",s="I The Cleft of Shadow söker en novis Blind Cazuls hjälp med en succubusritual. Den blinde häxmästaren pekar ut ett föremål laddat med dödlig känsla.",h="I The Cleft of Shadow söker en novis Blind Cazuls hjälp med en succubusritual.",kw={"blind cazul","cazul","cleft of shadow","dogran","orgrimmar","succubus","warlock","zankaja"},ang={["class:Warlock"]="Som häxmästare lär du dig att demonisk besvärjelse bygger på känslomässig resonans såväl som felmagi. En succubus lockas av en kanal laddad med dödlig känsla.",["faction:Horde"]="Som medlem av Horden ser du The Cleft of Shadows mörka konster verka under huvudstaden och beröra vanliga liv på platåerna ovanför."},sec={{t="En fråga om lockelse",b="En succubus svarar på dödlig längtan, sorg och åtrå. För att dra en över slöjan behöver en blivande besvärjare mer än viljestyrka; demonen är känd för att sluka själar. Blind Cazul förstår vad novisen söker och vet var ett lämpligt lockbete finns."},{t="Ögon bland klipporna",b="Trots sin blindhet känner Blind Cazul liven och sorgerna innanför Orgrimmars röda murar. Han skickar novisen till Zankaja, en orchkvinna som bor på klipporna nära vindryttarnas häckningsplats. Hon väntar oroligt på att hennes partner Dogran ska återvända, och hennes förtvivlan kan dra till sig en demons uppmärksamhet."}},faq={{q="Vem är Cazul?",a="Cazul är en blind häxmästare som i tysthet hjälper häxmästarna i The Cleft of Shadow. Han identifierar reagenser och kanaler för demoniska besvärjelser.",al={"blind cazul","vem är cazul"}},{q="Varför skickar Cazul dig till Zankaja?",a="En succubusritual kräver ett föremål präglat av stark dödlig längtan eller kärlek. Zankaja väntar förtvivlad på sin försvunna partner Dogran, och hennes band till honom utgör det känslomässiga lockbete novisen söker.",al={"varför zankaja","vad har zankaja"}},{q="Var i Orgrimmar finns Zankaja?",a="Zankaja bor på Orgrimmars upphöjda klippor, väster om vindryttarnas häckningsplats. Gå över bron från flygtornet och leta i bostäderna i närheten till höger.",al={"zankajas plats","var finns zankaja"}},{q="Vad händer efter att du talat med Zankaja?",a="Zankaja är förtvivlad eftersom hennes partner Dogran har försvunnit. När du har talat med henne söker du efter besked om hans öde i The Barrens och påbörjar arbetet med att hämta en kraftfull kärlekssymbol.",al={"what comes next","nästa steg efter cazul"}},{q="Vilken sorts demon förbereder det här uppdraget dig på att åkalla?",a="Du förbereder dig på att besvärja och kuva en succubus, en demon som använder förförelse och psykisk plåga.",al={"vilket husdjur","demonbelöning"}},{q="Varför måste warlockar utnyttja personliga tragedier i sina ritualer?",a="En succubus dras till starka dödliga känslor, särskilt passion, hängivenhet och hjärtesorg. Häxmästare använder föremål präglade av sorg eller åtrå som andligt bete i besvärjelsens ritual.",al={"warlockens moral","varför använda dogran"}}},fx={a1700788={q="Varför vill Cazul att du ska hitta Zankaja?",a="Cazul är en lärare och äldste i Cleft of Shadows skuggor. När Gan'rul Bloodeye skickar en blivande häxmästare till honom ska Cazul vägleda dig till ingredienserna som krävs för att binda en succuba. Att åkalla en sådan demon kräver ett föremål fyllt av kärlek och stark längtan. Cazul vet att Zankajas sorg och förtvivlan över sin försvunna partner Dogran kan ge dig det känslomässiga fäste du behöver för att locka över en själsförgörare på din sida.",al={"cazuls motiv","varför hjälpa zankaja cazul","varför skickar cazul mig till zankaja"}},fea16628={q="Varför skickar Cazul dig i stället för att själv gå till Zankaja?",a="Det här är en del av din invigning som häxmästare, inte ett vanligt ärende i staden. Cazul är en gammal, blind eremit som bor i Orgrimmars dunkla djup och stilla vägleder nybörjare i mörka riter. Häxmästarträning kräver att du smider dina egna bindningar och själv samlar in komponenterna till dina demoner. Orgrimmars vakter skulle dessutom inte hjälpa till med förbjudna demonritualer, så det är helt och hållet ditt ansvar att följa detta sorgens spår.",al={"varför jag åt cazul","varför skicka spelaren till zankaja","varför behöver cazul mig"}}},fp="11,161,22.258.0,18.286.0,13.143.0,35.199.0,40.163.0,39.185.0,57.102.0,63.181.0"}
P.entries["quest:1509"] = {n="News of Dogran",s="En försvunnen grunt vid namn Dogran får Zankaja att vänta i Orgrimmar. Hans partner har inte hört något på flera dagar, så hon skickar dig för att fråga hans överordnade, Gazrog, vid The Crossroads. För en häxmästare tjänar sökandet också ett ritualsyfte: att binda en succubus.",h="En försvunnen grunt vid namn Dogran får Zankaja att vänta i Orgrimmar.",kw={"the barrens","cazul","the crossroads","dogran","gazrog","nyheter om dogran","quilboar","sukkubus","zankaja"},ang={["class:Warlock"]="Som häxmästare går du från mörka texter i Orgrimmar till att använda dödlig tragedi i ditt försök att göra anspråk på en succubus.",["faction:Horde"]="Som medlem av Horden ser du faran dess grunts möter när de säkrar The Crossroads i Kalimdor mot fientliga hot.",["race:Orc"]="Som orc ser du i Zankajas sorg det personliga priset för Hordens expansion och försvar i Durotar och The Barrens."},sec={{t="En partners förtvivlan",b="Zankaja väntar på Orgrimmars klippor och fruktar för sin partner Dogran. Han skickades till The Crossroads efter en hedersam befordran, men han är försenad och hon har inte hört något på flera dagar. Hon ber dig söka efter nyheter hos hans befälhavare, Gazrog. Hon vet inte att mörka konster ligger bakom sökandet."},{t="Mörka nyheter från The Barrens",b="Gazrog berättar vad som hände Dogran vid The Crossroads, Hordens centrala utpost i The Barrens. Quilboar härjar på slätterna, och Dogran har fallit i deras händer. Han lever fortfarande, men hans tillfångatagande är en dyster sanning som Gazrog tvekar att skicka vidare till Zankaja."},{t="Ett verktyg för att frammana",b="Häxmästarens sökande efter Dogran tjänar också arbetet med att frammana och bemästra en succubus. Bindningsritualen kräver reliker som berörts av äkta känslor. Dograns lidande och band till Zankaja utgör den känslomässiga kanal som ritualen behöver."}},faq={{q="Vem är Dogran?",a="Dogran är en orcisk grunt stationerad i The Barrens, nyligen befordrad till The Crossroads. Han är Zankajas partner, och hon bor i Orgrimmar.",al={"dograns historia","vem är dogran","grunt dogran"}},{q="Varför bryr sig en häxmästare om en försvunnen orcisk vakt?",a="Häxmästarmentorer i The Cleft leder dig till att söka nyheter om Dogran. Bindningsritualen för en succubus kräver reliker som berörts av djupa, dödliga känslor, däribland kärlek, hängivenhet och lidande.",al={"varför häxmästaruppdrag","varför gör häxmästare det här","koppling till sukkubus"}},{q="Var finns Gazrog?",a="Gazrog finns vid The Crossroads i The Barrens, där han hjälper till att organisera Hordens försvar mot lokala hot.",al={"var finns gazrog","gazrogs plats","gazrog vid the crossroads"}},{q="Vad hände med Dogran?",a="Dogran är försenad med att återvända till Zankaja, som inte har hört något från honom på flera dagar. Hon ber dig söka efter nyheter hos Gazrog vid The Crossroads.",al={"är dogran död","var finns dogran","dograns öde"}},{q="Vem ger uppdraget?",a="Zankaja ger den till dig på Orgrimmars klippor, efter att häxmästartränaren Cazul hänvisat dig till henne.",al={"uppdragsgivare","var börjar nyheter om dogran"}},{q="Vad händer härnäst i kedjan?",a="Fortsätt dina efterforskningar i The Barrens för att få veta Dograns öde och föra nyheten vidare.",al={"vad händer härnäst","nästa uppdrag","fortsättning på sukkubuskedjan"}}},fx={["7a20ce20"]={q="Varför vill Zankaja att du ska ta reda på nytt om Dogran?",a="Dogran är Zankajas partner. Han var mycket stolt över sin nyliga befordran och sin placering vid The Crossroads, men The Barrens är betydligt farligare än tryggheten bakom Orgrimmars murar. Han är nu mer än en vecka försenad, och hon har inte fått ett enda livstecken. Sliten mellan fruktan och hopp står hon inte ut med tystnaden längre och behöver någon som kan leta upp hans befälskontakt.",al={"varför vill zankaja ha detta","zankajas motiv","varför leta efter dogran"}}},fp="14,239,16.307.0,27.259.1,26.245.1,14.135.0,50.194.0,24.103.0,24.137.1,21.103.0,29.88.1"}
P.entries["quest:151"] = {n="Poor Old Blanchy",s="Verna Furlbrow väntar vid vägen i Westfall med sin strandsatta familj och svältande märr. Deras vagn gick sönder när de försökte fly, och Old Blanchy blev utmattad. Verna ber dig samla havre från övergivna gårdar i närheten och mata den gamla hästen.",h="Verna Furlbrow väntar vid vägen i Westfall med sin strandsatta familj och svältande märr.",kw={"skördegolem","häst","havre","old blanchy","stackars old blanchy","verna furlbrow","vagn","westfall"},ang={["class:Hunter"]="Som jägare vet du att omsorg om ett utmattat dragdjur hedrar bandet mellan arbetande folk och djuren som troget bär deras bördor.",["faction:Alliance"]="De strandsatta Furlbrow visar hur landsbygdens mänskliga undersåtar försummas medan huvudstaden förlamas av politiskt stillestånd."},sec={{t="En strandsatt familj",b="Verna och Farmer Furlbrow har blivit strandsatta vid Westfalls huvudväg. Banditer och herrelösa mekaniska skördegolem har drivit familjer som deras från sina hem. När familjen Furlbrow försökte föra sina ägodelar i säkerhet gick vagnen sönder och lämnade dem strandsatta ute på öppna fält."},{t="Tröst åt en trogen märr",b="Old Blanchy har plöjt och dragit lass åt familjen Furlbrow i många år. Nu är den milda märren utmattad efter att ha dragit deras överlastade kärra och försvagas snabbt av svälten under förseningen. Verna ber dig leta efter havresäckar på närliggande gårdar som tagits över, där fientliga tröskare och gnollasätare utgör ett hot. Säden kan ge det trogna djuret en ordentlig måltid."}},faq={{q="Vem är Old Blanchy?",a="Old Blanchy är familjen Furlbrows älskade, åldrande arbetshäst. I åratal har hon dragit deras plogar och kärror genom Westfall, och nu är hon utmattad och strandsatt vid vägen efter att deras vagnsaxel gått sönder.",al={"vem är blanchy","vad är old blanchy","blanchys historia"}},{q="Varför har familjen Furlbrows vagn gått sönder?",a="Familjen Furlbrow försökte fly från sin gård med alla sina ägodelar, men vagnen gav vika under påfrestningen. De är strandsatta längs landsvägen, utsatta för banditer och kringströvande bestar.",al={"varför sitter de fast","furlbrows vagn","trasig vagn vid vägen"}},{q="Varifrån kommer havren?",a="Havresäckar ligger utspridda på fälten och i uthusen på Westfalls gårdar som tagits över. De lämnades kvar när gårdsfolket flydde från herrelösa skördemaskiner och banditer.",al={"var finns havre","hitta havre","havresäckar"}},{q="Vilka hot vaktar säden på fälten?",a="Fälten sydväst om vägen hemsöks av herrelösa mekaniska skördevakter och grupper av Riverpaw-gnoller som letar efter mat i övergivna lador.",al={"vad anfaller på gårdarna","faror på gårdarna","skördegolem och havre"}},{q="Varför har familjen inte fört Old Blanchy i säkerhet?",a="Old Blanchy är utmattad och svälter, och kan inte dra eller färdas långt utan näring. Familjen Furlbrow vägrar lämna sin trogna märr eller sina ägodelar bakom sig.",al={"varför stanna vid vagnen","kan hästen gå","varför inte gå till sentinel hill"}},{q="Skickar Stormwind hjälp till bönder som familjen Furlbrow?",a="Stormwinds kungliga hov erbjuder nästan inget skydd eller någon hjälp åt Westfalls gårdsfolk. Landsbygdsborna får till stor del klara sig själva eller förlita sig på det hårt pressade People's Militia.",al={"stormwinds hjälp till westfall","var finns vakterna","alliansens hjälp till westfall"}}},fx={b3f21e2d={q="Varför vill Verna Furlbrow att du ska göra det här?",a="Furlbrows vagn gick oväntat sönder längs vägen och lämnade dem strandsatta långt från målet. Deras trogna gamla häst, Old Blanchy, är helt utmattad efter resan och allt hårt arbete hon har fått utföra. Verna gav henne mat innan de lämnade hemmet, men Blanchy orkar knappt längre. Utan färsk havre kan det utmattade djuret inte återfå styrkan som behövs för att fortsätta.",al={"varför hjälpa blanchy","verna furlbrows motiv","varför behöver blanchy havre"}},c126e1f4={q="Vad ska Handful of Oats användas till?",a="Den här havren är viktig föda som ska hålla Old Blanchy vid liv och ge henne krafterna tillbaka. Furlbrows trogna arbetshäst är helt utmattad efter att ha dragit deras lastade vagn och börjar få slut på mat efter det plötsliga haveriet. Några nävar säd som du hittar på gårdarna i trakten ger henne nytt mod och ny styrka medan familjen tar hand om den trasiga hjulaxeln.",al={"vad ska handful of oats användas till","användning av handful of oats","havrens syfte"}},["3b562f8e"]={q="Varför ber Verna Furlbrow dig att hämta havren i stället för att göra det själv?",a="Furlbrows är hjälplösa resenärer som blivit strandsatta vid vägen bredvid sin förstörda vagn. De är helt oförberedda på farorna på Westfalls fält. De övergivna gårdarna där säckar med säd finns kvar är fulla av fientliga mekaniska skördetröskor och kringströvande rovdjur. Verna och hennes man måste stanna och hålla uppsikt över den skadade vagnen och den utmattade hästen, så den farliga insamlingen får lämnas åt erfarna äventyrare som du.",al={"varför kan inte verna hämta havre","varför ber verna mig","varför behöver furlbrows hjälp"}}},fp="16,257,20.284.0,27.366.0,19.210.0,38.185.0,28.167.0,43.141.0,50.158.0,54.178.0"}
P.entries["quest:1510"] = {n="News of Dogran",s="Det här uppdraget sänder Hordens äventyrare djupt in i Stonetalon Mountains för att kontakta Darkspear-trollet Ken'zigla i Malaka'jin. En skadad grunt från Camp Taurajo vid namn Dogran ligger svårt sårad, och den första kuriren som skickades för att hämta en livräddande örtbrygd kom aldrig tillbaka.",h="Det här uppdraget sänder Hordens äventyrare djupt in i Stonetalon Mountains för att kontakta...",kw={"camp taurajo","dogran","gazrog","ken'zigla","malaka'jin","quilboar","stonetalon"},ang={["class:Warlock"]="Det som verkar vara ett vanligt militärt räddningsuppdrag är i själva verket en avgörande prövning som Cazul och häxmästarna i Orgrimmar har satt upp. Den leder dig mot den känslomässiga resonans som krävs för att binda en succubus.",["faction:Horde"]="Den här delen av resan visar hur sköra försörjningslederna är mellan avlägsna utposter som Camp Taurajo och isolerade läger som Malaka'jin när quilboar och gobliner utgör ett hot."},sec={{t="En vädjan över gränsen",b="Dogran, en grunt från Horden stationerad vid Camp Taurajo i södra The Barrens, skadades svårt under en skärmytsling mot befästa quilboar. Gruntsoldaterna som var med honom lyckades ta sig tillbaka och försökte rädda honom, men hans sår hade blivit så infekterade att de inte vågade flytta honom utan att först lägga om dem. I desperation efter ett kraftfullt botemedel skickade Taurajo bud norrut till The Crossroads i hopp om att få tag på en traditionell läkande brygd som djungeltrollen i Malaka'jin tillredde."},{t="Blodsutgjutelse i Malaka'jin",b="När resenärerna kommer fram till Malaka'jins klippor upptäcker de att hjälpinsatsen kollapsade nästan omedelbart. Den första kuriren som skickades för att hämta medicinen dödades av gobliner innan han hann föra tillbaka brygden. Ken'zigla har fortfarande botemedlet som Dogran behöver, men för att få tag på det måste man hantera de farliga oroligheterna vid gränsen till passen i Stonetalon Mountains."}},faq={{q="Vem är Dogran och varför är han skadad?",a="Dogran är en orc-grunt stationerad vid Camp Taurajo. När han ledde en grupp för att rensa ut fientliga quilboarläger i södra The Barrens fick han brutala sår som blev infekterade. Det gick inte att transportera honom utan omedelbar läkarvård.",al={"vem är dogran","varför är dogran skadad","dograns historia"}},{q="Var ligger Malaka'jin?",a="Malaka'jin är en liten utpost för Darkspear-troll vid den klippiga foten av Stonetalon Mountains, strax bortom The Barrens nordvästra gräns.",al={"malaka'jins läge","var ligger malaka'jin","hitta ken'zigla"}},{q="Vad hände med den första budbäraren som skickades efter brygden?",a="Den första kuriren som skickades från The Crossroads för att hämta Ken'zigla's Draught dödades av gobliner nära Malaka'jin innan han hann föra tillbaka brygden. Ken'zigla säger bara att goblinerna gjorde slut på honom.",al={"första kuriren","vad hände med budbäraren","död kurir"}},{q="Varför bryr sig häxmästartränare om Dograns öde?",a="Häxmästarnoviser skickas för att hjälpa Dogran under förevändningen att uträtta ett ärende åt Blind Cazul och Gazrog, men prövningen leder dem till slut till en artefakt fylld av kärlek och hjärtesorg som behövs för att kalla fram och binda en succubus.",al={"häxmästaruppdragets koppling","succubus dogran","varför gör häxmästarna så här"}},{q="Vem är Ken'zigla?",a="Ken'zigla är en alkemist och örtmedicinare av Darkspear-trollen som bor i bosättningen Malaka'jin i Stonetalon. Hen kan mycket om att brygga kraftfulla brygder av vildmarkens växter.",al={"vem är ken'zigla","ken'zigla stonetalon","ken'zigla"}},{q="Varför kunde Dogran inte föras direkt till en stad?",a="Efter striden mot quilboar hade Dograns sår blivit svårt infekterade. Hans medsoldater var rädda att den skumpiga färden över The Barrens vägar till en större läkare skulle döda honom innan han kom fram.",al={"varför flytta inte dogran","dograns sår","varför lämnade camp taurajo honom"}}},fx={["643120b9"]={q="Varför vill Gazrog att du ska göra det här?",a="Gazrog ansvarar för att samordna försvaret och trupperna i The Barrens. Dogran skadades när han slogs mot quilboar nära Camp Taurajo, och hans variga sår gör det omöjligt att flytta honom utan hjälp. Den första budbäraren till Malaka'jin är försenad, så Gazrog behöver dig för att hämta trollarnas läkande brygd innan Dogran dukar under för sina skador.",al={"gazrogs motiv","varför hjälper gazrog dogran","varför skicka mig till malaka'jin"}},["79033db9"]={q="Varför skickar Gazrog en äventyrare i stället för sina egna grunts?",a="Hordes styrkor i The Barrens är hårt ansatta när de håller tillbaka ständiga räder från quilboar och säkrar lederna till utposterna. Gazrog har redan skickat en budbärare till Stonetalon Mountains fot som inte har återvänt. Därför har han inga soldater över att riskera på ännu ett ärende när en duglig äventyrare står framför honom.",al={"varför jag om dogran-nyheten","varför skickar gazrog ingen vakt","varför behöver gazrog mig"}}},fp="14,211,26.343.0,23.228.1,33.185.0,28.132.0,58.165.0,49.201.1,17.132.0,49.169.0"}
P.entries["quest:1511"] = {n="Ken'zigla's Draught",s="Ken'zigla's Draught är ett brådskande kuriruppdrag i horde-warlockkedjan för att frammana en succubus. Med en kraftfull medicinalbrygd från Malaka'jin i Stonetalon Mountains måste warlocken skynda över Kalimdor till Camp Taurajo för att rädda en agent vid namn Dogran.",h="Ken'zigla's Draught är ett brådskande kuriruppdrag i horde-warlockkedjan för att frammana en succubus.",kw={"the barrens","dogran","brygd","ken'zigla","logmar","stonetalon","succubus","taurajo"},ang={["class:Warlock"]="Den här delen av din resa prövar ditt tålamod och din uppfinningsrikedom. Innan du kan styra en varelse fylld av rå åtrå och förförelse måste du först hela den dödliga som bär bindningens föremål.",["faction:Horde"]="Visar hur den unga Horden sträcker sig över centrala Kalimdor, där isolerade utposter i Stonetalon och The Barrens förlitar sig på resande för att upprätthålla viktiga förbindelser och få fram sjukvård."},sec={{t="En livräddande brygd",b="Bland klipporna i Stonetalon Mountains anade trollapotekaren Ken'zigla att problem var på väg. Eftersom ett tidigare sändebud som skickats för att hämta medicin åt den försvunne spejaren Dogran aldrig kom tillbaka, förberedde Ken'zigla en andra dos av sin kraftfulla återställande brygd. Blandningen är flyktig och stark: en halv dos ger en dödligt sårad soldat kraft att röra sig utan att såren börjar blöda ymnigt, medan resten måste sparas till nästa dag för att fullborda läkningen."},{t="Möte vid Camp Taurajo",b="Warlocken får i uppdrag att ta med brygden ut ur bergen och in i södra The Barrens till Grunt Logmar vid Camp Taurajo. Logmar har viktig information om var Dogran befinner sig, men hans garnison är tömd på folk som skickats ut för att samla förnödenheter. Dogran är fast och blöder i fientligt territorium, och leveransen av brygden till Taurajo är det sista som återstår innan räddningsaktionen kan inledas."}},faq={{q="Vad ska Ken'zigla's Draught göra?",a="Det är en kraftfull medicinalbrygd som Ken'zigla tillverkat för att återuppliva den skadade orchagenten Dogran. Den ges i två doser. Den första halvan ger en sårad krigare tillräcklig styrka för att röra sig utan att dödliga sår börjar blöda igen, medan den andra fullbordar läkningen.",al={"vad är brygden","syftet med kenziglas brygd","varför brygga medicin"}},{q="Vem är Ken'zigla?",a="Ken'zigla är en trollapotekare i Stonetalon Mountains. Han förser hordeagenter i området med specialiserade alkemiska blandningar och brygder.",al={"ken'ziglas historia","vem är ken'zigla"}},{q="Varför väntar Grunt Logmar vid Camp Taurajo?",a="Grunt Logmar är stationerad vid Camp Taurajo i södra The Barrens. Han håller uppsikt över lokala spejare och har den senaste informationen om var Dogran försvann, men saknar grunts för att genomföra en räddning på egen hand.",al={"vem är grunt logmar","logmar taurajo","grunt logmars roll"}},{q="Hur hänger det här uppdraget ihop med att frammana en succubus?",a="För att frammana och binda en succubus behöver horde-warlocks i Orgrimmar Dogran's Pendant, en artefakt genomsyrad av passion och hängivenhet. För att få tag på amuletten måste man hitta Dogran och rädda hans liv med Ken'zigla's Draught.",al={"varför brygd i succubusuppdraget","dogran i succubuskedjan"}},{q="Varför hade den första kuriren inte med sig brygden?",a="Det ursprungliga sändebudet som skickades till Stonetalon slutförde aldrig uppdraget, så Ken'zigla förberedde en reservdos åt nästa äventyrare som letade efter Dogran.",al={"vad hände med första budbäraren","tidigare kurir"}},{q="Vart leder spåret efter Camp Taurajo?",a="När Grunt Logmar har fått brygden pekar han ut var Dograns tillfångatagare finns i södra The Barrens, där den döende spejaren hålls som gisslan.",al={"var är dogran","nästa steg efter logmar"}}},fx={["0e638b4a"]={q="Varför vill Ken'zigla att du ska göra det här?",a="Ken'zigla hade redan förberett den stärkande brygden och väntade sig att ännu en budbärare skulle komma för Dograns räkning. Han är läkekunnig bland trollen i Malaka'jin i Stonetalon Mountains. Att brygga kraftfulla läkemedel är hans yrke, och han vill inte se en skadad krigare gå under när en enkel dryck kan rädda honom.",al={"ken'ziglas motiv","varför brygga drycken","varför hjälper ken'zigla"}},ff24236d={q="Varför behöver Ken'zigla att du levererar brygden?",a="Ken'zigla är en apotekare stationerad i Malaka'jin i Stonetalon Mountains, långt från The Barrens. Det är en lång och farlig färd genom bergen till Camp Taurajo, och han kan inte göra den själv, särskilt inte när Dograns liv hänger på en skör tråd.",al={"varför skicka mig","varför levererar hon inte drycken själv","varför måste spelaren leverera drycken"}}},fp="19,193,18.419.0,26.323.1,40.232.0,17.136.0,44.214.0,52.208.0,47.144.0,43.137.1"}
P.entries["quest:1512"] = {n="Love's Gift",s="I Orgrimmar väntar Gan'rul Bloodeye på ett hängsmycke till succubusritualen. Dogran lämnar ifrån sig ett kärt minne efter att ha hittats och väckts till liv i The Barrens.",h="I Orgrimmar väntar Gan'rul Bloodeye på ett hängsmycke till succubusritualen.",kw={"dirt-caked pendant","gan'rul bloodeye","grunt dogran","love's gift","orgrimmar","succubus","the barrens","zankaja"},ang={["class:Warlock"]="Som häxmästare lär du dig att enbart magisk kraft inte kan binda en demon. En succubus kan fångas genom att vända dess hunger efter dödligas passioner, som kärlek och sorg, mot den.",["faction:Horde"]="Som medlem av Horden ser du Grunt Dogran välja döden i strid framför ett liv som en börda för sina närmaste."},sec={{t="En grunts offer",b="Grunt Dogran hölls fången och torterades av Bristleback quilboar i The Barrens. Ken'zigla's Draught väcker honom till medvetande, men hans kropp kan inte återhämta sig. Han väljer att möta döden i strid i stället för att återvända till sin partner, Zankaja, oförmögen att strida. Dogran lämnar ifrån sig ett smutsigt hängsmycke, en gåva född ur kärlek, och ber att Zankaja aldrig ska få veta vad han gav upp."},{t="Bete åt en demon",b="En häxmästare behöver en talisman laddad med starka, oförfalskade känslor för att frammana och kontrollera en succubus. Dessa demoner livnär sig på dödligas begär och förvrider äkta tillgivenhet till ångest. Dogran's Pendant bär vittne om hans hängivenhet och deras avsked. Ta det till Gan'rul Bloodeye i Orgrimmars dunkla klyftor, där det rengörs och putsas. Dess starka känslokraft kan locka själsfrossaren genom Twisting Nether."}},faq={{q="Varför behöver en häxmästare Dogran's Pendant?",a="Succubi dras till dödligas djupa passioner, som de förvrider och förtär. Dogran's Pendant bär på osjälvisk kärlek och uppoffring, vilket gör det till ett kraftfullt lockbete för en succubus.",al={"varför hängsmycke","succubusbete","varför smutsigt hängsmycke"}},{q="Vem är Grunt Dogran?",a="Grunt Dogran är en krigare i Horden som tillfångatogs och torterades av Bristleback quilboar i södra The Barrens. En alkemisk brygd väcker honom till liv, men skadorna gör att han inte kan leva som en stolt krigare.",al={"vem är dogran","grunt dograns bakgrund"}},{q="Vem är Zankaja?",a="Zankaja är D og rans unga partner, som väntade oroligt på nyheter om honom. Han lämnar ifrån sig hennes minnessak och väljer att söka en krigares död i stället för att belasta henne med att ta hand om honom.",al={"zankajas bakgrund","dograns maka"}},{q="Varför ber Dogran dig att hålla detta hemligt för Zankaja?",a="Dogran vill inte att hans unga partner ska bli bunden till en döende invalid. Han lämnar ifrån sig hennes hängsmycke, medveten om att det inte kommer tillbaka till henne, och ber att hon ska slippa skulden över att få veta hur hans öde beseglades.",al={"varför inte berätta för zankaja","dograns hemlighet"}},{q="Vem rengör hängsmycket, och varför?",a="Gan'rul Bloodeye, häxmästarläraren i Orgrimmar, tar emot hängsmycket och rengör det från smuts. Dess glänsande utseende och känslokraft kan sedan locka den frambesvärjda demonen.",al={"gan'rul bloodeyes roll","varför rengöra hängsmycket"}},{q="Vad händer direkt efter att du har slutfört uppdraget?",a="Gan'rul Bloodeye skickar dig för att bära det renade hängsmycket till kallelsesirkeln under Orgrimmar. Där utför du bindningsritualen och möter succubusen ensam.",al={"what comes next","nästa uppdrag efter love's gift"}}},fx={["528517eb"]={q="Varför skickar Grunt Dogran iväg dig med sitt hängsmycke?",a="Dogran vägrar leva vidare som en invalid bunden till sin unga partner Zankaja. I stället för att återvända hem bruten och tynga henne med sorg eller skuld tänker han söka en ärofull krigares död i strid i stället för att långsamt tyna bort som ett tomt skal. Genom att lämna ifrån sig hängsmycket och skicka iväg dig kan han kapa det bandet och möta sitt slut med heder på sina egna villkor.",al={"varför ger dogran dig hängsmycket","dograns motiv med kärlekens gåva","varför ge bort det smutsiga hängsmycket"}},["6232e4f3"]={q="Varför behöver Dogran att du levererar hängsmycket?",a="Dogran är inte i skick att själv resa till Orgrimmar efter den brutala fångenskap och tortyr han just har utstått hos quilboar från Bristleback. Dessutom tänker han uttryckligen söka en soldats död på slagfältet i stället för att återvända till civilisationen. Du är den enda utomstående han litar på som har nått fram till honom, och därför är du hans enda möjlighet att leverera minnessaken till Gan'rul utan att avslöja hans öde för Zankaja.",al={"varför jag i kärlekens gåva","varför behöver dogran mig","varför kan inte dogran ta hängsmycket"}}},fp="11,153,19.368.1,16.409.0,41.164.0,20.201.0,15.173.1,57.191.1,31.172.0,53.162.1"}
P.entries["quest:1513"] = {n="The Binding",s="Vid Neeru Fireblades cirkel i Orgrimmar ställs en häxmästare inför prövningen att binda en succubus. Dogran's Pendant hämtar demonen från Twisting Nether, där trolldom och vapenmakt måste bryta dess vilja.",h="Vid Neeru Fireblades cirkel i Orgrimmar ställs en häxmästare inför prövningen att binda en succubus.",kw={"bindningen","cleft of shadow","dogran","gan'rul","neeru","orgrimmar","hänge","succubus","warlock","zankaja"},ang={["class:Warlock"]="Som häxmästare bevisar du att din vilja kan kuva Netherns listiga, störande demoner och stå emot deras förföriska faror.",["faction:Horde"]="Som medlem i Horde ser du hur fraktionen i hemlighet tolererar demonutövare i Cleft of Shadow, avskilda från stadens hedersbundna invånare.",["race:Orc"]="Som ork bär du den bittra tyngden av ditt folks förflutna fördärv när du hanterar demoner. Gan'ruls krav på disciplin och kontroll bär på den historien."},sec={{t="En demons ankare",b="Dogran's Pendant binder minnet till besvärjelsen. Den stympade orchen gav upp det, men det hade varit ett minne av hans kärlek till Zankaja, buret genom fångenskap och plågor. Den hängivenheten ger hänget kraft att nå över världarna, överbrygga Twisting Nether och fånga en succubus uppmärksamhet."},{t="Cirkeln i skuggorna",b="Under Orgrimmars klippor håller Neeru Fireblade till i ett tält med en cirkel förberedd för farliga riter. Under Gan'rul Bloodeyes ledning aktiverar du dess runor och möter den framkallade succubus i strid. Att kalla på en demon är bara början; du måste besegra den på egen hand och böja dess ande efter din vilja."},{t="List och viljestyrka",b="Gan'rul Bloodeye varnar för att succubi kan göra farliga trälar. Deras närvaro berusar och frestar sinnena, medan de dränerar oförsiktiga mästares livskraft och ande. Han säger åt dig att minnas Dograns och Zankajas sorg, så att inte stolthet och övermod gör dig sårbar för demonens knep. Bara en oböjlig vilja kan stå emot dess lockelse."}},faq={{q="Vad händer under ritualen?",a="Du för Dogran's Pendant till cirkeln inne i Neeru Fireblades tält i Cleft of Shadow. Dess hängivenhet lockar en succubus från Twisting Nether, och du kämpar mot demonen tills den underkastar sig din vilja.",al={"hur fungerar ritualen","vad gör man i the binding","succubusritual"}},{q="Var äger kallelsen rum?",a="Besvärjelsen äger rum i Neeru Fireblades tält i Cleft of Shadow, under Orgrimmar. En rituell cirkel är inristad i golvet.",al={"var finns cirkeln","kallelsecirkelns plats","var kallar jag fram succubus"}},{q="Vem var Dogran och varför behövs hans hänge?",a="Dogran var en enkel soldat i Horde som tillfångatogs och stympades av quilboar i The Barrens. Hans hänge, ett minne av hans älskade Zankaja, lockar till sig och förankrar en succubus.",al={"vem är dogran","varför dograns hänge","dograns historia"}},{q="Vem är Gan'rul Bloodeye?",a="Gan'rul Bloodeye är en högt uppsatt häxmästartränare i Cleft of Shadow under Orgrimmar. Han handleder blivande häxmästare och vägleder dem genom riter för att kuva demoner.",al={"vem ger uppdraget","vem är gan'rul","gan'rul bloodeyes roll"}},{q="Vilken kraft får en warlock när provet är avklarat?",a="När succubusen kuvas fullbordas en häxmästares träning, och du får kunskapen och runbehärskningen som krävs för att när som helst kalla en succubus i din tjänst.",al={"vilken belöning får warlocks","varför kalla fram succubus","succubusförmåga som husdjur"}},{q="Varför anses det särskilt farligt att kalla en succubus?",a="Succubi charmar dödliga och spelar på deras begär. En övermodig häxmästare riskerar att få sin själ långsamt utsugen, tills demonens list övervinner hans kontroll.",al={"succubusens faror","varför är succubi riskabla","succubuslore"}}},fx={["9ef07cc1"]={q="Varför vill Gan'rul Bloodeye att du ska göra det här?",a="Som mentor för Hordes häxmästare under utbildning måste Gan'rul Bloodeye pröva din vilja och magiska styrka innan han ger dig makt över farliga demoniska tjänare. Genom att be dig åkalla och kuva en succuba med den tragiska kvarlevan av Dograns kärlek lär han dig att akta dig för demoniska knep och högmod. När du har klarat prövningen tänker Gan'rul också återlämna Dograns hängsmycke och berätta nyheten för Zankaja.",al={"gan'rul bloodeyes motiv","varför åkalla succuba åt gan'rul","varför uppdraget the binding"}},["9690a59c"]={q="Varför behöver Gan'rul Bloodeye att du utför åkallelsen i stället för att göra det själv?",a="Den här ritualen är en övergångsrit som bara är avsedd för dig. En häxmästare måste själv kuva en åkallad demon. Ingen lärare eller stadsvakt kan skapa den psykiska dominansen åt dig. Om Gan'rul kuvade varelsen själv skulle du varken få disciplinen eller auktoriteten som krävs för att binda och befalla en egen succuba.",al={"varför jag i the binding","varför kan inte gan'rul åkalla succuban","varför måste jag åkalla den"}},dee6d59e={q="Vem ställs du mot under ritualen?",a="Du ställs mot en åkallad succuba som hämtas genom The Twisting Nether till åkallningscirkeln i Neeru Fireblades tält. Dessa listiga demoniska fresterskor njuter av att manipulera dödligas passioner och sluka själar. Genom att locka demonen med Dograns hängsmycke, ett föremål genomsyrat av dödlig kärlek och tragedi, tvingar du den in i verkligheten för att besegra och kuva den.",al={"målet för the binding","vad slåss man mot i the binding","åkallad succuba"}}},fp="11,205,16.293.1,25.306.0,19.343.1,32.206.0,36.137.0,45.150.1,24.165.0,58.135.0,60.168.0"}
P.entries["quest:1515"] = {n="Dogran's Captivity",s="I Camp Taurajo ställs en häxmästare inför ett avgörande prov i Hordens träning: att rädda en tillfångatagen orcisk krigare. Med Ken'zigla's Draught måste du hitta den svårt misshandlade Grunt Dogran i ett quilboar-läger och ge honom kraft att fly.",h="I Camp Taurajo ställs en häxmästare inför ett avgörande prov i Hordens träning: att rädda en tillfångatagen...",kw={"the barrens","dogran","brygd","ken'zigla","logmar","quilboar","succubus","taurajo","krigslock"},ang={["class:Warlock"]="Som häxmästare står du inför ett avgörande steg mot att förstå dödlig passion och uppoffring, sådant som krävs för att frammana en succubus.",["faction:Horde"]="Som medlem av Horden vet du att quilboarer hotar patruller och utposter i hela centrala The Barrens.",["race:Orc"]="Som orc ser du hur Dogran uthärdar lemlästning och tortyr med den hårda motståndskraft som förväntas av en orcisk grunt."},sec={{t="En ensam räddning",b="Grunt Logmar vid Camp Taurajo vill inte riskera Hordens soldater i en kostsam attack mot de väl befästa quilboarerna. Dograns öde vilar på dig, en blivande häxmästare som bara har Ken'zigla's Draught. Res norrut genom snåren och fientliga läger för att hitta platsen där quilboarerna håller honom fången."},{t="Blodets pris",b="Grunt Dogran ligger svårt misshandlad bland fientliga quilboarer i hyddor norr om Taurajo. Ken'zigla's Draught ger honom tillräckligt med kraft för att linka i säkerhet, men skadorna gör honom permanent lemlästad. Han förlorar en arm och ett ben."}},faq={{q="Var hålls Grunt Dogran fången?",a="Grunt Dogran hålls fången i en liten grupp med två quilboarhyddor, direkt norr om Camp Taurajo i The Barrens.",al={"dograns plats","var är dogran","hitta dogran i the barrens"}},{q="Varför skickar inte Grunt Logmar soldater för att hjälpa till?",a="Grunt Logmar kan inte avvara trupper från försvaret av Camp Taurajo. Han anser att en räddningsaktion i quilboarernas välbevakade område är för farlig och riskerar alltför många soldaters liv.",al={"varför hjälper ingen hordevakt","logmars soldater","förstärkningar till taurajo"}},{q="Vad är Ken'zigla's Draught?",a="Ken'zigla's Draught är en kraftfull, illasmakande stärkande dryck, bryggd för att ge den svårt skadade Dogran nog med styrka att resa sig och fly från quilboarernas fångenskap.",al={"kenziglas brygd","vad är brygden","dograns medicin"}},{q="I vilket skick är Dogran när han hittas?",a="Dogran är nära döden, med omfattande sår efter quilboarernas tortyr. Även efter att ha druckit drycken är hans arm och ben bortom räddning.",al={"dograns skador","lever dogran","dograns arm och ben"}},{q="Hur hänger den här räddningen ihop med att frammana en succubus?",a="Dogran bär en symbol knuten till kärlek och dödlig hängivenhet, känslor och idéer som häxmästare utnyttjar för att frammana och binda en succubus.",al={"varför gör krigslockar så här","koppling till succubusuppdraget","dograns krigslocksuppdrag"}},{q="Vem tillfångatog Dogran?",a="Dogran tillfångatogs av quilboarstammar som lever i snåren norr om Camp Taurajo.",al={"vem tog dogran","dograns fångvaktare","kidnappare i the barrens"}}},fx={b38341a7={q="Varför vill Grunt Logmar att Dogran ska hittas?",a="Grunt Dogran är en av Logmars kamrater och tillfångatogs av quilboar under en patrull i The Barrens. Logmar kan inte avvara Hordes soldater eller riskera ett militärt anfall för att frita honom, men han vill inte överge sin kamrat helt. När Logmar har sett din beslutsamhet att ta dig så här långt låter han dig försöka rädda Dogran på egen hand med Ken'zigla's Draught, så att Dogran får en chans att överleva.",al={"varför hjälpa dogran","grunt logmars motiv","varför rädda dogran"}}},fp="18,210,15.288.0,18.219.1,27.107.0,45.164.0,28.161.0,39.167.1,52.123.1,20.84.0"}
P.entries["quest:1516"] = {n="Call of Earth",s="I Valley of Trials utsätter Canaga Earthcaller unga Horde-schamaner för ett prov i uthållighet och tålamod. De jagar felstalkers för att förbereda en rituell sapta.",h="I Valley of Trials utsätter Canaga Earthcaller unga Horde-schamaner för ett prov i uthållighet och tålamod.",kw={"burning blade","call of earth","canaga earthcaller","earth totem","felstalker","sapta","shamanprov","valley of trials"},ang={["class:Shaman"]="Som schaman inleder du här din formella gemenskap med elementen och lägger grunden för din Earth Totem.",["race:Orc"]="Som orch under Thralls Horde hedrar du gamla klantraditioner från tiden före den demoniska fördärvningen genom att återvända till schamanernas väg.",["race:Troll"]="Som troll följer du Darkspear-stammens häxdoktorer och spiritualister när du tar emot jordandarna, som hjälper ditt folk att bygga ett nytt hem tillsammans med orcherna."},sec={{t="Det första bandet",b="En schaman börjar med att lära sig knyta an till varje element. För orcher och troll börjar den vägen med jord, livets grundval och uthållighetens och tålamodets element. I Valley of Trials vägleder Canaga Earthcaller nya schamaner och lär dem att jorden kräver respekt och ståndaktighet innan den ger skydd."},{t="En renande jakt",b="Kulten Burning Blade frodas i ravinerna norr om Valley of Trials. Dess mörka magi frammanar felstalkers, fördärvade hundar från bortom detta plan. Jakten på dem prövar om en schaman kan försvara landet mot onaturligt förfall. Canaga använder deras hovar för att brygga en Earth Sapta, en helig dryck som öppnar dödligas ögon för elementplanet."}},faq={{q="Vad är syftet med det här provet?",a="Provet inleder en schamans studier av elementens mysterier och prövar tålamod och andlig disciplin inför jordandarna. Det förbereder schamanerna på att tala med andarna och förtjäna en Earth Totem.",al={"varför göra call of earth","vad ger call of earth","syftet med uppdraget"}},{q="Vem är Canaga Earthcaller?",a="Canaga Earthcaller är en trollschamantränare i Valley of Trials i Durotar. Han vägleder unga schamaner bland orcher, troll och besökande tauren mot elementär mästerskap.",al={"vem är canaga","canaga earthcallers bakgrund"}},{q="Varför behöver Canaga felstalkerhovar?",a="Canaga använder felstalkers hovar för att bereda en Earth Sapta, en dryck som låter en dödlig schaman uppfatta och tala med elementandar.",al={"varför felstalkerhovar","hovarnas syfte"}},{q="Var finns felstalkers?",a="Felstalkers hemsöker grottan och de omgivande klipporna norr om träningsplatsen i Valley of Trials, inom Burning Blade Coven.",al={"felstalkers plats","var hittar man felstalkers"}},{q="Kan andra raser i Horde genomgå den här versionen av provet?",a="Ja. Provet är främst avsett för orcher och troll som genomgår Coming of Age i Durotar, men tauren-schamaner som reser från Red Cloud Mesa kan också genomgå det i Valley of Trials.",al={"kan tauren göra detta","är detta bara för orker"}},{q="Vilka dygder står jorden för för en shaman?",a="I schamantraditionen är jorden livets grundval. Den står för stor styrka, uthållighet och evigt tålamod, men kan vara envist nyckfull när den inte respekteras.",al={"jordens dygder","jordens betydelse för shamaner"}}},fx={a9a10a24={q="Varför vill Canaga Earthcaller att du ska göra det här?",a="Canaga vägleder unga shamaner som tar sina första steg på den andliga vägen. Han känner att en tid av strid närmar sig och att du har den uthålliga ande som krävs för att tala med jorden. Innan han kan förbereda den heliga sapta-drycken och dela jordens hemligheter måste han pröva din beslutsamhet, styrka och tålamod mot farliga motståndare för att försäkra sig om att du är redo att lyssna till elementets kallelse.",al={"canaga earthcallers motiv","varför prövar canaga dig","varför canaga earthcaller"}},["3057b25e"]={q="Varför finns felstalkers i Valley of Trials?",a="Dessa demoniska hundar hemsöker dalens norra delar, dit de kallats och bundits av de skuggfyllda trollkarlarna i Burning Blade Coven, som gömt sig i de lokala grottorna. Deras vidriga närvaro vanhelgar marken omkring dem och gör dem till ett omedelbart hot mot unga noviser, men också till ett passande prov på mod och stridsförmåga för en blivande shaman.",al={"varför finns felstalkers här","felstalkers i valley of trials","vad är felstalkers"}},dddcc185={q="Varför måste du möta felstalkers i stället för dalens vakter?",a="Det här är ett personligt andligt prov, inte en vanlig militär insats. En shaman måste själv finna harmoni med elementen genom prövningar och bevisad styrka. Om krigare eller vakter samlade in hovarna skulle det inte bevisa något för jordens envisa andar. De kräver att du möter faran direkt och visar tålamod, uthållighet och förmåga innan de skänker dig sin kraft.",al={"varför jag i call of earth","varför inte skicka vakter efter felstalkers","varför måste jag jaga felstalkers"}}},fp="13,152,14.304.0,16.336.0,34.196.0,26.162.0,39.134.0,34.136.0,58.172.0,50.169.0"}
P.entries["quest:1517"] = {n="Call of Earth",s="Vid Spirit Rock vägleder Canaga Earthcaller unga shamaner genom deras första kontakt med elementen. De dricker en Earth Sapta på helig mark för att se Minor Manifestation of Earth.",h="Vid Spirit Rock vägleder Canaga Earthcaller unga shamaner genom deras första kontakt med elementen.",kw={"call of earth","canaga earthcaller","earth sapta","hidden path","minor manifestation of earth","sapta sight","spirit rock","valley of trials"},ang={["class:Shaman"]="Som shaman tar du ditt första steg mot samklang med elementen. Sann mästargrad börjar med jordens stilla tålamod.",["race:Orc"]="För orcs som återvänder till sina förfäders seder efter generationer av felkorruption är gemenskapen genom Earth Sapta en helig återupptäckt av folkets traditionella band till andarna.",["race:Troll"]="Som Darkspear-troll tar du till dig dessa jordriter för att anpassa dina djupa förfädersband till Durotars hårda, solstekta landskap."},sec={{t="Sapta-dryckens kraft",b="En sapta är en mystisk dryck som bara ett fåtal shamanmästare känner till. Den tillreds med elementarmagi och överbryggar skillnaden mellan dödligas sinnesintryck och det andliga planet. Den skänker Sapta Sight åt dem med stark vilja. Eftersom den knyter drickarens ande direkt till ett element förbjuder traditionen att dricka den utanför vigd, helig mark."},{t="Pilgrimsfärd till Spirit Rock",b="För att få kontakt med jorden lämnar du Valley of Trials och följer Hidden Path upp i Durotars södra bergsklyftor. Spirit Rock ligger vid stigens slut, en upphöjd fristad med utsikt över den karga ödemarken. Drick saptan där, så kan du uppfatta det som vanliga ögon inte ser: en elementarnärvaro bland stenarna."},{t="Jordens tålamod",b="Minor Manifestation of Earth kräver varken blodsutgjutelse eller underkastelse. Den ber dig bara stå ödmjukt inför världen. Eld, vatten och luft bär på stormiga, oberäkneliga och ofta kaotiska andar, medan jorden lär ut stadga. Berg lär ut uthållighet, och slätter lär ut gränslöst tålamod."}},faq={{q="Vad är en Earth Sapta?",a="En Earth Sapta är en dryck som veteraner bland shamanerna brygger för att tillfälligt stämma drickarens ande till jorden. När du dricker den får du den inre syn som krävs för att se och tala med dolda elementarandar.",al={"vad är sapta","betydelsen av earth sapta","vad gör sapta"}},{q="Var ligger Spirit Rock?",a="Spirit Rock ligger i de klippiga bergen sydväst om The Den i Valley of Trials. Följ Hidden Path upp i kullarna söder om dalbottnen för att nå platsen.",al={"var ligger spirit rock","spirit rocks plats","hur hittar man spirit rock"}},{q="Varför måste saptan drickas vid Spirit Rock?",a="Shamantraditionen tillåter att en sapta dricks endast på en utvald helig plats. Heliga platser som Spirit Rock är naturliga tunna gränser mellan de dödligas värld och elementarandarna.",al={"varför dricka vid spirit rock","kan jag dricka sapta var som helst"}},{q="Vem är Minor Manifestation of Earth?",a="Minor Manifestation of Earth är en elementarande som bor vid Spirit Rock. Bara den skärpta varseblivningen från Sapta Sight kan avslöja den. Anden hälsar unga shamaner och prövar deras ödmjukhet, samtidigt som den lär dem de första lärdomarna om elementär balans.",al={"jordens manifestation","vem är jordanden"}},{q="Kan alla shaman i Horde genomgå det här provet?",a="Unga orcher och Darkspear-troll som tränar i Durotar genomgår främst den här riten. Tauren-shamaner som reser hit kan också fullfölja den, även om deras motsvarande rit äger rum på Red Cloud Mesa.",al={"kan tauren göra det här uppdraget","vem kan göra call of earth"}},{q="Hur reagerar jordanden på novisen?",a="Till skillnad från eld- eller luftmanifestationernas oberäkneliga natur välkomnar jordanden dem som närmar sig med ödmjuk respekt och accepterar dem som lärlingar. Den skänker sin välsignelse utan att kräva en styrkeprövning.",al={"vad säger jordanden","är jordanden fientlig"}}},fx={["1aaf4733"]={q="Varför vill Canaga Earthcaller att detta ska göras?",a="Canaga Earthcaller leder dig längs shamanens andliga väg. När du visat dig redo genom att samla de nödvändiga rituella beståndsdelarna kräver han nu att du dricker Earth Sapta vid Spirit Rock. Han vill stärka ditt band till landets elementandar så att din syn kan tränga igenom slöjan och du kan tala direkt med jorden.",al={"canagas motiv","varför skicka mig till spirit rock","varför dricka earth sapta"}},["99304602"]={q="Varför skickar Canaga Earthcaller dig i stället för att gå själv?",a="Den här resan är en helig övergångsrit som varje blivande shaman måste genomföra själv. Earth Sapta binder den som dricker till elementet och ger en synförmåga som ingen ställföreträdare kan uppleva. Canaga har redan denna kontakt. Du måste själv stå ödmjukt inför jorden för att förtjäna dess välsignelse.",al={"varför jag, canaga","varför skicka spelaren till spirit rock","varför måste jag dricka sapta"}}},fp="13,187,22.314.0,25.314.0,21.284.0,23.192.0,29.163.0,46.178.0,40.240.0,42.197.0,48.197.0"}
P.entries["quest:1518"] = {n="Call of Earth",s="I Durotar söker en ung schaman kontakt med en manifestation av jordanden. Den nyinvigde återvänder till Canaga Earthcaller med Rough Quartz och får sin första elementartotem.",h="I Durotar söker en ung schaman kontakt med en manifestation av jordanden.",kw={"call of earth","canaga earthcaller","durotar","earth totem","minor manifestation","rough quartz","schaman","valley of trials"},ang={["class:Shaman"]="Som schaman ger den här riten dig din första totem och låser upp förmågan att förankra dig i elementen och kalla på jorden för hjälp.",["faction:Horde"]="Som medlem av Horden vet du att Kalimdors element är vilda och otämjda. Bandet som hordeschamaner knyter till dem är avgörande för att deras nya bosättningar ska överleva.",["race:Orc"]="Som ork deltar du i återupplivandet av orkisk shamanism i Durotar och vänder tillbaka till elementär balans efter årtionden av demonisk fördärv.",["race:Troll"]="Som troll lär du dig sida vid sida med orkerna i Valley of Trials och anpassar Darkspear witch doctors och spiritisters traditionella kontakt med andevärlden till att omfatta de fyra elementens vägar."},sec={{t="Stenens hjärta",b="En nybörjarschaman söker kontakt med jorden genom tålamod och ödmjukhet, inte rå styrka. Minor Manifestation of Earth ger den nyinvigde en bit Rough Quartz. Den lilla stenen visar att anden har godtagit den nyinvigdes löfte och förblir ett frö till kraft."},{t="Den första av fyra vägar",b="Du klarar prövningen genom att ta med kvartsen till Canaga Earthcaller i Valley of Trials. Canaga formar den till en Earth Totem, fokusen genom vilken du kanaliserar markens orubbliga beskydd och styrka. Riten inleder din väg genom de fyra elementens discipliner och lägger grunden för ett livslångt samförstånd med naturen."}},faq={{q="Vad används Rough Quartz till?",a="Rough Quartz är en gåva från Minor Manifestation of Earth, ett bevis på att du har haft kontakt med anden. Canaga Earthcaller sätter in den i din Earth Totem som dess hjärta och som fokus för dina jordbesvärjelser.",al={"rough quartz","vad gör kvartsen","kvartsens syfte"}},{q="Vem är Canaga Earthcaller?",a="Canaga Earthcaller är en schamantränare i Valley of Trials i Durotar. Han vägleder unga orker och troll genom deras första prövningar, förbereder dem på att få kontakt med elementandar och formar deras första totemer.",al={"canaga","canaga earthcaller","vem är canaga"}},{q="Kan taurer göra det här uppdraget?",a="Ja. Tauren genomför vanligtvis sin jordprövning med sina egna äldste vid Red Cloud Mesa i Mulgore, men alla hordeschamaner som reser till Valley of Trials kan genomgå ritualen med Canaga Earthcaller.",al={"kan taurer göra call of earth i durotar","taurenschaman durotar","taurers call of earth"}},{q="Vad innebär det att få en Earth Totem?",a="Att få en Earth Totem betyder att jordens ande har erkänt dig. Den visar din ställning bland schamaner och ger dig ett fysiskt fokus för jordens välsignelser och skydd.",al={"varför få en earth totem","vad betyder schamanens earth totem"}},{q="Vilka dygder kräver jorden av en schaman?",a="Anden ber den nyinvigde om tålamod, styrka och visdom. Den lär ut att även den minsta sten kan överleva berg genom uthållighet och uppmanar schamaner att respektera marken, så att den i sin tur bär dem.",al={"jordandens lärdomar","vad begär jorden"}},{q="Vart leder schamanens väg efter det här?",a="Jorden är det första av de fyra elementen en schaman måste bemästra. När din träning fortsätter kallas du att söka kontakt med eld-, vatten- och luftandarna.",al={"vilket totem kommer härnäst","efter earth totem","schamanens fyra vägar"}}},fx={["946f939a"]={q="Varför ger Minor Manifestation of Earth dig Rough Quartz?",a="Efter att ha prövat din beslutsamhet och erkänt din kontakt skänker anden dig Rough Quartz som ett påtagligt bevis på ert band. Den vill att du tar den lilla stenen tillbaka till Canaga Earthcaller, så att den kan bli det levande hjärtat i din första totem och knyta jordens uthålliga styrka och tålamod direkt till din andliga utövning.",al={"minor manifestation of earths motiv","varför rough quartz","varför skickar jordmanifestationen mig"}}},fp="13,176,18.275.0,23.357.0,34.212.0,26.226.0,25.206.0,44.187.0,49.217.0,41.164.0"}
P.entries["quest:1519"] = {n="Call of Earth",s="Call of Earth är en helig shamanistisk övergångsrit som prövar en novis tålamod, uthållighet och respekt för naturen. Genom att besvara jordens kallelse och ta emot den elementära sapta-drycken påbörjar sökaren en andlig återfödelse och får direkt gemenskap med allt livs grundval.",h="Call of Earth är en helig shamanistisk övergångsrit som prövar en novis tålamod, uthållighet och respekt för...",kw={"call of earth","jordmodern","element","tålamod","återfödelse","sapta","shaman","uthållighet"},ang={["class:Shaman"]="Denna rit markerar en avgörande tröskel i en shamans träning, där gemenskap med jorden skänker styrka, uthållighet och djup andlig insikt.",["faction:Horde"]="De shamanistiska traditioner som håller ihop horden hämtar kraft från elementen och börjar med jordens stadiga motståndskraft.",["race:Tauren"]="Vördnaden för Jordmodern är central i taurenkulturen, vilket gör detta prov till en högtidlighållning av grundläggande förfäders tro."},sec={{t="Alltings grundval",b="Call of Earth är en formande rit för en shaman som lär sig att få kontakt med världens urkrafter. Jorden anses vara det mest obändiga och visa av alla element och utgör tillvarons fasta grund. Provet visar hur naturen följer målmedvetna kretslopp av nedbrytning och återfödelse, där berg blir till öknar och floder skär ut kanjoner genom otaliga tidsåldrar. För att höra jordens röst måste en novis visa samma orubbliga tålamod."},{t="Sapta och återfödelsen",b="Att besvara denna kallelse ses som en andlig återfödelse som förändrar sökaren för alltid, så att hen inte kan återgå till sin tidigare ovetskap. När novisen har visat sig redo och respektfull inför Jordmoderns lagar får hen en jordbunden sapta-dryck. Detta särskilda elixir öppnar en ny väg till insikt och låter shamanen förstå grundläggande hemligheter om styrka, uthållighet och elementärt skydd."}},faq={{q="Vad är Call of Earth?",a="Call of Earth är ett heligt andligt prov för den som vill bli shaman. Det prövar sökarens tålamod och beredskap att få direkt kontakt med jordelementet och lyssna till dess eviga visdom.",al={"vad är call of earth","jorduppdrag shaman","syftet med call of earth"}},{q="Vad står jordelementet för i shamanistisk tradition?",a="Jorden står för alltings grundval och förkroppsligar styrka, uthållighet och tålamod. Den anses vara det mest obändiga och visa av elementen och lär att allting bryts ner och återföds med tiden.",al={"vad står jorden för","jordelementets historia","jordens betydelse för shamaner"}},{q="Vad är en sapta?",a="En sapta är en elementär dryck som tillreds av en shamanmentor. Att dricka eller ta emot den öppnar en andlig väg och gör sökarens sinnen mottagliga för elementandar, så att hen kan uppfatta och samspela med dem.",al={"vad är en sapta","jordbunden sapta","vad gör en sapta"}},{q="Vem är Jordmodern som nämns i provet?",a="Jordmodern är livets och balansens grundkälla och vördas särskilt av tauren-shamaner. Hon skyddar dem som följer hennes lagar och skänker större visdom till sökare som behandlar landet med respekt.",al={"vem är jordmodern","jordmoderns historia","jordmoderns koppling"}},{q="Vad händer när man besvarar kallelsen?",a="När detta steg är avklarat är sökaren redo för nästa steg på sin väg. Det innebär en andlig återfödelse som gör att en shaman aldrig kan återgå till ovetskap, eftersom jordens nya hemligheter uppenbaras.",al={"vad händer när man slutför det","efter call of earth","call of earth återfödelse"}},{q="Varför krävs tålamod för att få kontakt med jorden?",a="Jorden följer kretslopp av nedbrytning och återfödelse, där berg till slut nöts ner till öknar och floder skär ut kanjoner. En shaman måste behärska tålamod och uthållighet för att stämma in på dessa långlivade rytmer.",al={"varför kräver jorden tålamod","tålamod och jorden"}}},fp="13,291,28.468.0,21.416.0,26.183.0,60.205.0,16.187.0,47.209.0,37.219.0,51.200.0"}
P.entries["quest:152"] = {n="The Coast Isn't Clear",s="Längs Westfalls västra kust möter skeppsbrutna sjömän murlocstammar på stränderna. Captain Grayson vid Westfall Lighthouse ber om hjälp att rensa kusten, så att överlevande tryggt kan nå land.",h="Längs Westfalls västra kust möter skeppsbrutna sjömän murlocstammar på stränderna.",kw={"captain grayson","coastrunner","det stora havet","murloc","oracle","skeppsvrak","tidehunter","westfall lighthouse"},ang={["faction:Alliance"]="När Stormwinds armé saknas i Westfall kämpar People's Militia med att skydda gårdarna inåt landet. Kustförsvaret faller på allierade som Captain Grayson.",["race:Human"]="Som människa vet du att handelsfartyg och fiskare länge har färdats på Westfalls vatten. Den murlockontrollerade stranden är ett bittert tecken på kungarikets förlorade gränsmarker."},sec={{t="En skeppskyrkogård",b="Westfalls västra kust har krävt oräkneliga skepp. Rev, plötsliga stormbyar och vassa klippor krossar fartygen mot grundbankarna. Överlevande kan klamra sig fast vid vrakspillror och kravla i land i hopp om att bli räddade. Men murlocstammar kontrollerar stränderna och visar ingen nåd mot skeppsbrutna."},{t="Den spöklika utkiken",b="Captain Grayson sköter Westfall Lighthouse från en enslig klippa sydväst om fastlandet. Döden har bundit honom till posten, men han håller fortfarande utkik efter förbipasserande skepp och sjömän i nöd. Murlocs gör stranden livsfarlig, från Coastrunners i norr till Tidehunters, Warriors och Oracles i söder. Grayson ber resenärer att rensa kustlinjen."}},faq={{q="Vem är Captain Grayson?",a="Captain Grayson är den spöklika sjökaptenen som hemsöker Westfall Lighthouse. Han känner sig fortfarande bunden att skydda sjömän som färdas genom de farliga vattnen och dem som överlever ett skeppsbrott.",al={"captain grayson","spöke i fyren","fyrvaktare i westfall"}},{q="Varför vill Grayson att murlocerna rensas bort från kusten?",a="Grayson vill att murlocerna rensas bort eftersom skeppsbrutna sjömän ofta spolas i land längs Westfall. Murlocs svärmar över stränderna från norr till söder och dödar överlevande som når land.",al={"varför döda murlocs i westfall","varför kusten inte är säker","varför rensa kusten"}},{q="Var finns de olika murlocerterna?",a="Murloc Coastrunners lever oftast längs norra Westfalls kust. Murloc Warriors, Oracles och Tidehunters samlas i bosättningar och läger på de södra stränderna.",al={"murlocernas platser i westfall","var finns coastrunners","var finns tidehunters"}},{q="Är Captain Grayson fientligt inställd till Alliansen eller Horden?",a="Captain Grayson är neutral. Hans plikt mot sjömän överskrider politiska gränser, och han ber alla dugliga resenärer att hjälpa till att göra kusten säkrare.",al={"är grayson vänligt inställd","grayons fraktion","kan horden göra uppdraget"}},{q="Måste man tända fyren igen först för att klara det här uppdraget?",a="Nej. Captain Grayson ber dig rensa kusten oavsett om du har hjälpt till att tända Westfall Lighthouse igen eller inte.",al={"måste jag göra keeper of the flame först","förutsättning för coast isnt clear"}},{q="Arbetar murlocerna för Defias Brotherhood?",a="Nej. Murlocs agerar på egen hand och attackerar alla som tar sig in på deras jaktmarker längs stranden. Defias Brotherhood verkar i närheten, i Moonbrook-området och de södra vikarna.",al={"är defias allierade med murlocs","kopplingen mellan defias och murlocs"}}},fx={["9a80f3b4"]={q="Vilka murlocs hotar Westfalls kust?",a="Du jagar murlocs som svärmar över Westfalls västra stränder: Coastrunners som stryker längs bränningarna i norr, samt Warriors, Tidehunters och Oracles som håller till längre söderut. Dessa vattenlevande rovdjur har bon bland kustens skeppsvrak, där de ger sig på strandade fartyg och anfaller alla som har oturen att spolas i land.",al={"vilka murlocs dödar jag","vilka är kustens murlocs","murlocmål vid westfalls kust"}},["49634979"]={q="Varför behöver Captain Grayson en äventyrare som kan bekämpa murlocs?",a="Captain Grayson är ett rastlöst spöke bundet till Westfall Lighthouse ensliga klippor. Han kan inte själv patrullera längs kusten, och Stormwinds garnison har lämnat området åt banditerna. Därför förlitar han sig helt på förbipasserande äventyrare som du för att säkra stränderna åt de sjömän som överlevt.",al={"varför dödar inte grayson murlocs","varför behöver grayson mig","varför rensar inte vakterna kusten"}}},fp="21,199,20.266.0,19.360.0,23.182.0,57.176.0,42.168.0,52.135.0,56.111.0,51.176.0"}
P.entries["quest:1520"] = {n="Call of Earth",s="Denna heliga rit knyter en tauren-schaman andligt till jordens element. Genom att dricka en Earth Sapta vid en helig klippa öster om Camp Narache kan de invigda se bortom sina fysiska sinnen och tala direkt med en Minor Manifestation of Earth.",h="Denna heliga rit knyter en tauren-schaman andligt till jordens element.",kw={"call of earth","camp narache","earth sapta","kodo rock","manifestation","mulgore","sapta","seer ravenfeather"},ang={["class:Shaman"]="Denna rit utgör den andliga kärnan i en tauren-schamans band till landet. Den är den nödvändiga vägen till gemenskap med jorden och till att få en Earth Totem.",["race:Tauren"]="Den djupa vördnaden för Earth Mother gör sapta-ritualen till ett av de mest vördnadsfulla kulturella övergångsproven för tauren-andliga utövare på Red Cloud Mesa."},sec={{t="Syftet med sapta",b="En sapta är en omsorgsfullt tillredd ceremoniell dryck, skapad av schamanäldste för att binda en invigd persons dödliga ande direkt till ett urtida element. Den tillreds med förfädernas magi, och bara några få utvalda bland tauren bevarar hemligheterna bakom brygden. När den dricks på en särskilt utvald helig plats vidgar drycken den drickandes sinne och genomborrar slöjan mellan den fysiska världen och andeplanet, så att elementen kan skådas i sin råa form."},{t="Mötet vid Kodo Rock",b="Öster om Camp Narache reser sig Kodo Rock, en väldig stenpelare som tjänar som helig fristad. Här avslöjar sapta den Minor Manifestation of Earth som väntar på pilgrimen. Till skillnad från naturens lynniga, eldiga eller rasande sidor som schamanen möter senare på sin väg, ber jordens ande bara den invigde närma sig i stillsam ödmjukhet. Den skänker bergets uthålliga styrka och slätternas lugna tålamod åt alla som vördar landet."}},faq={{q="Vad är en Earth Sapta?",a="En Earth Sapta är en alkemisk och andlig dryck som bryggs av schamanäldste. Dess magi öppnar den drickandes sinnen, så att en invigd kan se och tala direkt med jordelementens andar.",al={"vad är sapta","vad betyder earth sapta","vad gör drycken"}},{q="Var ligger Kodo Rock?",a="Kodo Rock är en mäktig naturlig stenmonolit, belägen rakt österut över Red Cloud Mesa från Camp Narache.",al={"hitta kodo rock","kodo rocks läge","var ligger helgedomen"}},{q="Vem tillredde Earth Sapta för den här riten?",a="Drycken tillreddes och skänktes av Seer Ravenfeather, en äldre schaman som bor i Camp Narache och ansvarar för utbildningen av unga andliga vägvisare.",al={"vem ger sapta","seer ravenfeathers sapta"}},{q="Varför måste sapta drickas på en helig plats?",a="En sapta är helig till sin natur och farlig om den missbrukas. Enligt tauren-traditionen får den bara drickas i vigda helgedomar, där elementandar naturligt håller till och tryggt kan ta emot den som söker dem.",al={"varför dricka vid kodo rock","kan jag dricka sapta var som helst"}},{q="Vad händer när man dricker drycken vid Kodo Rock?",a="Drycken lyfter den vardagliga slöjan och blottar en Minor Manifestation of Earth. När man talar med varelsen fullbordas bandet mellan schamanen och jordens element.",al={"vad visar sig","minor manifestation of earth dyker upp"}},{q="Vilken lärdom ger jordens ande de invigda?",a="Anden lär ut att jorden kräver ödmjukt tålamod, inte strid. Medan element som eld och luft kan vara kaotiska och våldsamma, ger jorden schamanens själ styrka, uthållighet och en stilla grund.",al={"jordandens lärdom","jordritens betydelse"}}},fx={["52e0a178"]={q="Varför skickar Seer Ravenfeather dig till Kodo Rock?",a="Seer Ravenfeather vägleder dig som en shaman under invigning. Earth Sapta som hon tillredde är laddad med magi som ska öppna dina sinnen för världens andar. Genom att be dig dricka brygden vid den heliga helgedomen på Kodo Rock vill hon binda din ande permanent till jordelementet, så att du kan tala direkt med dess manifestationer och lära dig dess grundläggande visdom.",al={"seer ravenfeathers motiv","varför dricka earth sapta","varför call of earth från ravenfeather"}}},fp="13,142,24.328.0,22.385.0,23.152.0,27.86.0,42.151.0,46.193.0,52.166.0,54.182.0"}
P.entries["quest:1521"] = {n="Call of Earth",s="Den här riten avslutar en ung tauren-schamans första gemenskap med landets andar i Mulgore. Efter att ha druckit Sapta of Earth och talat direkt med en andeuppenbarelse får invigden ett stycke rå sten att ta med hem. Återkomsten till Camp Narache beseglar den unga mystikerns formella band till det första av de fyra elementen.",h="Den här riten avslutar en ung tauren-schamans första gemenskap med landets andar i Mulgore.",kw={"call of earth","camp narache","earth totem","minor manifestation of earth","mulgore","red cloud mesa","rough quartz","seer ravenfeather","taurenschaman"},ang={["class:Shaman"]="Den här riten markerar att du får din allra första totem. Den förankrar din andliga identitet och låser upp förmågan att kasta viktiga jordanknutna skyddsvärn.",["faction:Horde"]="Schamaner är viktiga andliga ankare och rådgivare i den nya horden. De förbinder de dödliga folken med Kalimdors oberäkneliga elementkrafter.",["race:Tauren"]="Taurenkulturen hyser djup vördnad för Earth Mother. Genom detta prov binds en invigd direkt till den levande stenen och jorden i sitt förfäders hemland."},sec={{t="En gåva från berget",b="När den unge schamanen har umgåtts med Minor Manifestation of Earth på klipporna nära Red Cloud Mesa ger anden en enkel Rough Quartz. Stenen ser anspråkslös ut, men symboliserar en elementpakt och själva stenens uthållighet. Anden påminner den unge schamanen om att tålamod och styrka är jordens främsta dygder och lovar att ömsesidig respekt skapar harmoni med landet."},{t="Den första totemen",b="När schamanen återvänder till Camp Narache använder Seer Ravenfeather den skänkta kvartsen för att skapa schamanens allra första Earth Totem. Totemen är mycket mer än en prydnad som visar rang; den blir ett bestående fysiskt och andligt ankare. Genom denna utskurna fokuspunkt kanaliserar invigden jordens grundande och beskyddande magi och tar sitt första verkliga steg längs den fyrdelade elementvägen."}},faq={{q="Vad är Rough Quartz till för?",a="Kvartsen är en gåva direkt från Minor Manifestation of Earth som bevis på gemenskapen. Seer Ravenfeather använder den som andligt hjärta i din nytäljda Earth Totem.",al={"varför behöver jag rough quartz","vad är kvartsen till för","vad används rough quartz till"}},{q="Varför är en Earth Totem så viktig för en schaman?",a="Totemer fungerar som kanaler som schamanen använder för att kanalisera elementkraft. Utan Earth Totem som fokus kan en schaman inte be landets andar att låta besvärjelser och skyddande värn ta form.",al={"varför behöver jag earth totem","vad gör earth totem","earth totems bakgrund"}},{q="Vem är Seer Ravenfeather?",a="Seer Ravenfeather är den andliga vägledaren och schamantränaren som finns vid Camp Narache på Red Cloud Mesa. Hon övervakar unga taurens elementprov och vägleder dem genom deras första visioner och skapandet av deras heliga redskap.",al={"vem är ravenfeather","seer ravenfeathers bakgrund","siaren i camp narache"}},{q="Vilka är de fyra vägarna som Seer Ravenfeather nämner?",a="Hon syftar på de fyra ur elementen som en schaman måste bemästra: jord, eld, vatten och luft. Jorden är grunden och står för uthållighet och orubblighet. Den utgör invigdens första prov.",al={"de fyra vägarna","schamanens fyra element","vilka är vägarna"}},{q="Var äger den här gemenskapen rum?",a="Minor Manifestation of Earth bor bland de karga klipporna som gränsar till Red Cloud Mesa i Mulgore. Dit kommer du bara efter att ha druckit den särskilda Earth Sapta.",al={"var hittar jag jordanden","var finns andeuppenbarelsen","var är anden"}},{q="Genomgår andra schamaner i horden en liknande rit?",a="Ja. Orcher och Darkspear Trolls i Durotar genomgår sin egen version av Call of Earth i Valley of Trials. De söker gemenskap med lokala elementvarelser för att hugga ut sina första totemer.",al={"gör orcher call of earth","trollens call of earth","får alla schamaner earth totem"}}},fx={["43ccddec"]={q="Varför skickar Minor Manifestation of Earth dig tillbaka till Seer Ravenfeather?",a="Elementanden har prövat din beslutsamhet och funnit dig värdig att följa jordens väg. Genom att ge dig en del av sig själv, Rough Quartz, ger den ett påtagligt bevis på er kontakt och ömsesidiga respekt. Den ber dig återvända till Seer Ravenfeather, så att stenen kan bli hjärtat i din första totem och binda jordens andar till din tjänst när du visar tålamod, styrka och visdom.",al={"minor manifestation of earths motiv","varför skicka rough quartz","jordmanifestationens syfte"}}},fp="13,290,24.365.0,15.322.0,40.167.0,47.162.0,25.219.0,51.206.0,37.170.0,48.186.0"}
P.entries["quest:1524"] = {n="Call of Fire",s="I The Barrens börjar en blivande schaman det andra provet på sin jakt efter samhörighet med eld. Kranal Fiss skickar novisen över Southfury River till en avskild bergstopphelgedom i Durotar, med den oslockta Torch of the Dormant Flame.",h="I The Barrens börjar en blivande schaman det andra provet på sin jakt efter samhörighet med eld.",kw={"the barrens","call of fire","durotar","fire totem","kranal fiss","shrine of the dormant flame","southfury river","telf joolam"},ang={["class:Shaman"]="Som schaman söker du Fire Totem genom att kommunicera med Kalimdors elementarkrafter. Den vägen leder dig till avlägsna helgedomar, bortom enkel undervisning.",["faction:Horde"]="Som medlem av Horde delar du schamanernas läror med orcher, tauren och troll. Traditionerna skickar lärjungar från The Barrens slätter till Durotars heliga klippor."},sec={{t="Ett prov på beredskap",b="Kranal Fiss anförtror schamanen Torch of the Dormant Flame. Enbart rå mystisk styrka räcker inte för att möta eldens krav; provet kräver måttfullhet, fokus och respekt. Facklan är både ett rituellt redskap och ett bevis för helgedomens väktare på att bäraren har bedömts redo att försöka klara provet."},{t="Den dolda toppen",b="Helgedomen ligger på andra sidan Southfury River, bland Durotars södra klippor. En väderbiten sten med en inristad eldruna markerar en undanskymd stig som klättrar mot en av områdets högsta toppar. På toppen vakar Telf Joolam, en troll-eremit, över Shrine of the Dormant Flame. Han avvisar nyfikna resenärer och skattjägare och håller den heliga eldskålen undan vanliga blickar tills en sökande anländer med den oslockta facklan."}},faq={{q="Vad är syftet med Torch of the Dormant Flame?",a="Kranal Fiss ger den oslockta facklan som ett tecken på avsikt. Den visar Telf Joolam, helgedomens väktare, att dess bärare är en schamannovis som bedömts redo för provet.",al={"varför bära facklan","vilande lågans fackla","facklans betydelse"}},{q="Vem är Telf Joolam?",a="Telf Joolam är en schamaneremit bland Horde som vakar över Shrine of the Dormant Flame på södra Durotars toppar. Han skyddar eldskålen från dem som inte förstår eller respekterar andarna.",al={"telf joolam","helgedomens väktare","vem är trollet vid helgedomen"}},{q="Var finns den dolda stigen?",a="Den dolda stigen börjar i Durotar, söder om bron över Southfury River. Nära flodstranden, där bergen möter kusten, visar en stående sten märkt med en eldruna den smala stigningen uppför den höga åsen.",al={"den dolda stigens läge","hitta shrine of the dormant flame","stigen uppför berget"}},{q="Varför måste facklan bäras osänd?",a="Facklan bärs oslockt eftersom elden måste väckas och bemästras genom ritual, inte bara tas i anspråk. Dess slumrande låga visar det tillstånd som schamanen måste väcka genom samhörighet.",al={"varför är facklan osänd","ritual med den vilande facklan","varför vilande låga"}},{q="Vad händer när man når Telf Joolam?",a="När Telf Joolam har granskat facklan leder han novisen vidare till hårdare och farligare riter för att väcka dess slumrande låga och bevisa sin behärskning av elementareld.",al={"nästa steg i call of fire","vad händer efter telf joolam"}},{q="Varför hålls helgedomen hemlig för resten av Horde?",a="Helgedomen hålls avskild eftersom elementarkrafter är oberäkneliga och farliga i otränade händer. Schamantraditioner förlägger heliga platser långt från vardagliga bosättningar, så att nyfikna och skattjägare inte stör vilande andar eller framkallar olycka.",al={"varför hemlig helgedom","är helgedomen gömd"}}},fx={["10005cfa"]={q="Varför skickar Kranal Fiss dig till Shrine of the Dormant Flame?",a="Kranal Fiss inser att din ande har den råa styrka som krävs för att tygla eld, men rå kraft räcker inte. Eld är farlig, destruktiv och otämjd. Om han gav dig dess totem i förtid kunde det sluta i katastrof. Som mentor måste han se till att du genomgår de heliga prövningarna i förberedelse och respekt. Han skickar dig till Telf Joolam så att du kan visa disciplin och förtjäna rätten att bära lågan inför elementen själva.",al={"varför vill kranal fiss att detta görs","kranal fiss motiv","varför skickar kranal dig"}},b8cc7d40={q="Varför måste du göra den här resan i stället för någon annan?",a="Den här pilgrimsfärden är ingen enkel springtur eller militär försvarsinsats, utan en djupt personlig andlig övergångsrit. Shrine of the Dormant Flame hålls strikt hemlig för vanliga medlemmar i Horde och för vanliga vakter. Bara en novis som söker kontakt med eldelementen kan bära den slumrande facklan, söka Telf Joolams vägledning och visa sig värdig att använda elementets kraft.",al={"varför jag i call of fire","varför skicka mig till shrine of the dormant flame","varför kan inte vakter gå"}}},fp="12,247,19.309.0,15.436.0,54.167.0,19.206.0,33.228.0,36.181.0,40.159.0,58.254.0"}
P.entries["quest:1525"] = {n="Call of Fire",s="Telf Joolam skickar en shaman genom Durotar och östra The Barrens för att hämta ingredienser till en Fire Sapta. Brygden förbereder en novis på att uppfatta och tala med eldandar.",h="Telf Joolam skickar en shaman genom Durotar och östra The Barrens för att hämta ingredienser till en Fire...",kw={"burning blade","call of fire","dustwind cave","fire sapta","fire tar","razormane","reagent pouch","telf joolam"},ang={["class:Shaman"]="Som shaman ställs du inför en prövning i att balansera motsatta krafter. Lågan kan skänka livskraft och ljus såväl som vrede, när visdom leder den.",["faction:Horde"]="Som hordens försvarare möter du hot vid gränserna: Razormane quilboar som tränger in i The Barrens och Burning Blade-kultister som gömmer sig i Durotar.",["race:Orc"]="Som orc konfronterar du Burning Blade och den trollkarlsmagi som en gång fördärvade ditt folk. Att återta elden som ett naturligt element är en handling som återupprättar kulturen."},sec={{t="Att brygga Fire Sapta",b="En Fire Sapta öppnar shamanens sinnen för den eviga flamman. Liksom brygden för jord låter den en shaman se och tala med andar som är dolda för dödliga. Telf Joolam skickar noviser genom Durotar och in i östra The Barrens för att samla ingredienser knutna till hetta och lågor."},{t="Fiender och element",b="Razormane quilboar-besvärjare i östra The Barrens bär på fire tar, som framställs i deras jordnära ritualer. Burning Blade-kultister bär på den andra nödvändiga ingrediensen i Dustwind Cave, i ravinerna nordost om Razor Hill. Kultisterna använder eld för förstörelse och demoniskt kaos, medan reagenserna i deras pungar har en naturlig koppling till elementet."},{t="Eldens natur",b="Telf Joolam lär ut att eld för med sig mer än förstörelse och undergång. Den ger också värme och ljus och gör skapelse möjlig. En vis shaman förstår hur motsatta krafter ger varandra mening och använder kontrasterande element tillsammans, i stället för att bara svinga eld som ett vapen."}},faq={{q="Vad är Fire Sapta?",a="En Fire Sapta är en rituell brygd gjord på ingredienser med koppling till eld. När en shaman dricker den hamnar ande och syn kortvarigt i samklang med eldens plan, så att dess andar uppenbarar sig och shamanen kan tala med dem.",al={"vad är fire sapta","fire sapta betydelse","varför dricka sapta"}},{q="Var hittar jag Fire Tar?",a="Razormane quilboar-besvärjare bär på fire tar i östra The Barrens, på andra sidan Southfury River från Durotar. Geomancers, Seers, Mystics och Thornweavers bär ofta krukor med den tjocka, lättantändliga blandningen för stammens riter.",al={"var finns fire tar","vem lämnar fire tar","fire tar quilboar"}},{q="Var hittar jag Reagent Pouch?",a="Burning Blade-kultister bär på reagenspungen i Dustwind Cave, ovanför ravinerna nordost om Razor Hill i Durotar. Grottan skiljer sig från Skull Rock, längre norrut nära kusten.",al={"var finns reagent pouch","vilken grotta har reagent pouch","burning blade-påse"}},{q="Varför använder en shaman föremål från häxmästare?",a="Telf Joolam behöver ingredienser mättade med eld till Sapta. Burning Blade-kultister åkallar destruktiva demoniska lågor, och deras trollpungar innehåller kraftfulla reagenser knutna till eld.",al={"varför använda burning blade-reagenser","häxmästarföremål för shaman","häxmästarnas eld"}},{q="Vem är Telf Joolam?",a="Telf Joolam är en ensam trollshaman vars läger ligger på toppen av Durotars klippor, söder om Razor Hill. Han leder eldens prövningar för hordens noviser och vägleder dem i att balansera förstörelse med skapelse.",al={"telf joolams historia","vem är telf joolam"}},{q="Vad händer efter det här uppdraget?",a="När Telf Joolam har gjort Fire Sapta av de insamlade ingredienserna skickar han dig till höjderna på den närliggande slocknade toppen. Du dricker den där, möter elementarande och förtjänar din Fire Totem.",al={"nästa uppdrag call of fire","efter att ha hämtat reagenserna","vad gör man med fire sapta"}}},fx={["8d79977d"]={q="Varför skickar Telf Joolam dig på det här uppdraget?",a="Telf Joolam vägleder dig när du invigs i elementens djupare konster. För att kunna använda eldens kraft och förtjäna din Fire Totem måste du dricka en särskild brygd som kallas fire sapta. Den riktar tillfälligt dina andliga sinnen mot eldens rike. Telf kan inte brygga den ur tomma intet. Han behöver att du hämtar ingredienser som är starkt knutna till lågan, så att han kan tillreda brygden och leda dig in på den eviga lågans väg.",al={"varför vill telf joolam detta","telf joolams syfte","varför hjälpa telf joolam"}},["08a6380d"]={q="Vad ska Fire Tar användas till?",a="Fire Tar är en av två viktiga katalysatorer som Telf Joolam behöver för att brygga fire sapta. Tjäran bärs av de besvärjande quilboarerna i Razormane-stammen i östra Barrens. Den har inneboende flyktiga egenskaper knutna till eldmagi, vilket ger brygden kraften som krävs för att stämma dina sinnen med elementens andar.",al={"varför behöver jag fire tar","fire tars syfte","användning av fire tar"}},["52c07fd8"]={q="Vad ska Reagent Pouch användas till?",a="Reagent Pouch innehåller de flyktiga beståndsdelar som behövs för att färdigställa fire sapta. Telf Joolam ber dig hämta den från Burning Blade-kultister som håller till nordost om Razor Hill, eftersom dessa trollkarlar ofta samlar material med stark koppling till eld för sin egen mörka magi. I stället för att leta över hela landet efter sällsynta, utspridda katalysatorer kan du hitta precis de ingredienser som behövs för att knyta din ande till lågan i kultisternas egna förråd.",al={"varför behövs reagent pouch","reagent pouchs syfte","shamanens användning av reagent pouch"}},["65d894ad"]={q="Vilka är Burning Blade-kultisterna i Durotar?",a="Kultisterna är dödliga agenter för Burning Blade, en skuggfylld kvarleva från de gamla demonkulterna som en gång tjänade Shadow Council. De håller till i dolda grottor ovanför ravinerna nordost om Razor Hill och utövar förbjuden felmagi mitt framför näsan på Horde. De drar kraft ur kaotisk eldsmagi, vilket gör deras Reagent Pouches till utmärkta källor för elementär brygd.",al={"mål för burning blade","vilka är kultisterna","burning blade i durotar"}},f71fa686={q="Varför måste du själv samla ingredienserna i stället för Telf Joolam?",a="Själva resan är en del av ditt andliga prov. En shaman måste visa att hen kan möta faror, konfrontera korrumperad magi och stå fast innan hen får kontakt med elden. Telf Joolam är din mentor och vägledare på den avlägsna toppen, men kontakten med elementet kan inte skänkas till dig. Du måste själv hämta beståndsdelarna som binder dig till lågan.",al={"varför kan inte telf hämta dem","varför jag på eldquesten","varför samlar shamaner ingredienser"}}},fp="12,171,22.277.0,20.343.0,19.286.1,21.207.0,29.223.0,33.186.0,42.181.0,19.206.0,30.204.1"}
P.entries["quest:1526"] = {n="Call of Fire",s="På Durotars bergstoppar ställs en shaman inför prövningen som knyter hen till elden. Telf Joolam leder novisen till att dricka Fire Sapta, möta en Minor Manifestation of Fire och ta dess Glowing Ember för att tända den ceremoniella facklan.",h="På Durotars bergstoppar ställs en shaman inför prövningen som knyter hen till elden.",kw={"brazier of the dormant flame","call of fire","durotar","fire sapta","fire totem","mindre eldföreteelse","shamanprov","shrine of eternal flame","telf joolam"},ang={["class:Shaman"]="Som shaman lär du dig att eld är ombytlig och förgörande, till skillnad från den fasta, obevekliga jorden. Den förtär den som åkallar den utan beslutsamhet, så du behöver fokus och auktoritet för att bemästra den.",["faction:Horde"]="Som shaman i Horde förenas du med orc- och trollshamaner som bestiger Durotars röda klippor för att bevisa sin samhörighet med landets eldandar."},sec={{t="Eldens ögon",b="Eldandar gömmer sig för ovana ögon på Durotars topp. För att se dem dricker du Fire Sapta, en brygd av ingredienser som samlats över The Barrens och längs kusten. Den skärper dina sinnen för det osedda och blottar mindre andar och manifestationer bland bergskammen på toppen."},{t="Mötet med företeelsen",b="En Minor Manifestation of Fire väntar på bergstoppen. När sapta-drycken börjar verka vet anden att du kan se den och väntar på din utmaning. Elden svarar på styrka och beslutsam handling, så du slår till utan dröjsmål. Ju längre striden varar, desto häftigare brinner elementarelden."},{t="Den slumrande lågans fyrfat",b="När manifestationen faller tar du dess kvarvarande hetta som en Glowing Ember. Vid helgedomen på toppen lägger du glöden i Brazier of the Dormant Flame. Den ingraverade metallen förblir sval under Durotars sol och vind tills glöden möter skålen. Då tänds ritualfacklan av en vitglödande låga."}},faq={{q="Vad är syftet med det här provet?",a="Du bevisar din styrka genom att möta en manifestation av eld och fånga dess hetta i en ritualfackla. Prövningen ger dig rätten att skapa en Fire Totem.",al={"varför göra call of fire","innebörden av fire totem-uppdraget","call of fire-provet"}},{q="Varför måste jag dricka Fire Sapta?",a="Du dricker Fire Sapta för att se och beröra eldelementarerna som samlats på bergstoppen, vanligtvis osynliga för dödliga.",al={"vad gör fire sapta","varför sapta","ser inte eldelementaren"}},{q="Var hittar jag den mindre eldföreteelsen?",a="Minor Manifestation of Fire väntar på bergsryggens högsta topp, ovanför Telf Joolams utkiksplats i Durotar, nära Shrine of Eternal Flame.",al={"företeelsens plats","var finns eldelementaren","vart ska jag gå"}},{q="Vem är Telf Joolam?",a="Telf Joolam är en excentrisk shamaneremit som bor högt uppe på en klippig bergsrygg i Durotar. Han vägleder unga Horde-noviser genom farliga och nyckfulla riter för att förstå elden.",al={"telf joolams roll","telf joolams bakgrund","vem är eremiten"}},{q="Varför blir företeelsen starkare under striden?",a="Elden samlar kraft och brinner hetare med tiden. Du slår till beslutsamt, eftersom tvekan låter anden bli starkare.",al={"varför är eldelementaren så stark","företeelsens styrkeökning","snabbt anfall mot eld"}},{q="Vad händer när fyrfatet har tänts?",a="När du tänder fyrfatet flammar den ceremoniella facklan upp. Du bär dess heliga låga nerför berget för att färdigställa din Fire Totem.",al={"vad händer efter dormant flame","nästa call of fire-uppdrag","vart ska jag ta den tända facklan"}}},fx={e554f055={q="Varför skickar Telf Joolam dig på den här prövningen?",a="Telf Joolam är din mentor i elementens vägar och ska vägleda unga shamaner när de söker kontakt med elden. Elden är våldsam, destruktiv och oförutsägbar. Andarna ger dig varken sin kraft eller respekt förrän du visat att du kan möta och tygla deras väsen direkt. Telf skickar dig uppför berget för att härda din ande i strid och förtjäna rätten att bära lågan, inte för att rensa berget från ett hot.",al={"telf joolams motiv","varför vill telf joolam detta","varför göra den här prövningen"}},e534729d={q="Vad ska Glowing Ember användas till?",a="Glowing Ember är den rena elementära rest som samlas in från den besegrade Minor Manifestation of Fire. För att fullborda din rit måste du bära denna glödande kärna till Shrine of Eternal Flame och lägga den i den slumrande eldstaden. När elementandens levande väsen tänder det kalla karet flammar en helig, vitglödgad eld upp. Den tänder i sin tur din Dormant Torch och beseglar ditt band till eldelementet.",al={"användning av glowing ember","varför behöver jag glowing ember","glowing embers syfte"}},["8a082e57"]={q="Vad är Minor Manifestation of Fire, och varför är den här?",a="Minor Manifestation of Fire är en elementande som dröjer sig kvar på bergstoppen nära Shrine of Eternal Flame. Den är bara synlig för dem vars sinnen öppnats av den heliga fire sapta, och förkroppsligar lågans råa, aggressiva natur. Den sitter kvar på klippan som en evig väktare och prövning för blivande shamaner och utmanar alla som vill bemästra elden att kuva dess brinnande vrede.",al={"minor manifestation of fire i historien","vem är manifestationen","varför är eldelementaren här"}}},fp="12,225,17.267.0,29.284.0,32.302.1,34.154.0,38.115.0,47.146.0,19.176.0,58.125.0,38.124.0"}
P.entries["quest:1529"] = {n="Call of Water",s="Call of Water är en initieringsrit som leder blivande shamaner i Horde från Thunder Bluffs höjder till The Barrens östra kust. För att få kontakt med det renande vattenelementet måste en novis söka upp enstöringen Islen Waterseer. Mötet är det första steget på en andlig resa för att förtjäna en Water Totem.",h="Call of Water är en initieringsrit som leder blivande shamaner i Horde från Thunder Bluffs höjder till The...",kw={"the barrens","call of water","islen waterseer","ratchet","shaman","southfury river","thunder bluff","water totem","xanis flameweaver"},ang={["class:Shaman"]="Den här riten markerar övergången från de tidiga elementprövningarna till att bemästra reningens, återställandets och tidvattnets flödande krafter.",["faction:Horde"]="Shamanismen är fortfarande en grundpelare för det nya Horde och knyter samman gamla traditioner bland orc-, troll- och taurenandliga ledare.",["race:Tauren"]="Uppdraget börjar i Thunder Bluff och för unga shu'halo-shamaner från Mulgore skyddade slätter ut i Kalimdors vidsträckta landskap."},sec={{t="En kallelse från bluffen",b="När en blivande shaman har bemästrat den obevekliga jorden och den otämjda elden anses hen till slut redo att studera elementens djupare mysterier. I Thunder Bluff ser tränare som Xanis Flameweaver när en elev har visat tillräcklig disciplin för att närma sig vattnets flödande, renande ande. Resan kräver att man lämnar Mulgore vindpinade platåer bakom sig och färdas österut över The Barrens solstekta slätter."},{t="Eremiten vid kusten",b="Vägen leder till Islen Waterseer, en stillsam mystiker som bor avskilt från de livliga bosättningarna i en enkel fiskarstuga på östkusten, söder om Ratchet och Southfury Rivers mynning. Vid det stora havets rand bedömer Islen resenärernas beredskap genom att se hur elementen dröjer sig kvar omkring dem. När hon ser att stadig jord, frisk vind och eldens värme redan är bundna till den sökandes ande förbereder hon dem på prövningarna som krävs för att förstå vattnets renhet."}},faq={{q="Vem skickar mig på den här resan?",a="Shamantränare i Thunder Bluff, som Xanis Flameweaver, ger dig det här uppdraget när en novis har kommit tillräckligt långt i sin andliga träning för att utföra vattnets riter.",al={"uppdragsgivare","vem startar call of water","var får man call of water i thunder bluff"}},{q="Var finns Islen Waterseer?",a="Islen Waterseer bor i en enslig fiskarstuga på The Barrens östra kust. Hennes bostad ligger vid stranden söder om Ratchet och söder om platsen där Southfury River mynnar ut i havet.",al={"var finns islen waterseer","islen waterseers plats","hitta islen"}},{q="Vad är syftet med Call of Water-prövningen?",a="Prövningen är en viktig övergångsrit för varje shaman som söker kontakt med vattnet. Den prövar novisens förståelse för elementär renhet och leder direkt till att man får en Water Totem.",al={"varför göra call of water","syftet med call of water","shamanuppdrag för water totem"}},{q="Får andra raser i Horde samma instruktioner?",a="Även om tauren vanligtvis får den inledande kallelsen i Thunder Bluff får orc- och trollshamaner i Orgrimmar och Durotar liknande kallelser att söka upp Islen Waterseer vid The Barrens kust.",al={"är det bara för tauren","orc call of water","troll call of water"}},{q="Vilka element måste en shaman bemästra före vattnet?",a="En shaman får kontakt med den stadiga jorden och den förödande men livgivande elden innan hen söker vattnets flödande natur. Som Islen påpekar när du anländer måste jord, vind och eld redan beröra din ande för att vattnet ska visa sin renhet.",al={"förkunskaper","vilka totem först","elementens ordning"}},{q="Vad händer när jag har hittat Islen Waterseer?",a="Samtalet med Islen avslutar den inledande resan från Thunder Bluff. Hon kommer genast att ge dig fler uppgifter runt om i Kalimdor, så att du kan förstå och rena vattenelementet på nära håll.",al={"vad händer sedan","efter att ha hittat islen","call of water del två"}}},fx={["6892158c"]={q="Varför skickar Xanis Flameweaver mig på det här uppdraget?",a="Xanis Flameweaver vägleder dig på din väg som shaman. Han har sett ditt tålamod och hur du bemästrat de första elementen, och inser att din ande nu är redo att möta vattnets prövningar. Hans uppgift är inte att leda dig varje steg på vägen, utan att se när du är redo och visa dig till Islen Waterseer, som besitter den djupare visdom som krävs för att pröva din förståelse av vattnets renhet.",al={"varför skickar xanis mig","xanis flameweavers motiv","varför söka upp islen waterseer"}},["22e527b8"]={q="Varför måste jag själv göra den här resan?",a="En shaman vandrar en djupt personlig väg. Att kommunicera med elementen kräver egen andlig disciplin och bevis på hängivenhet. Det kan inte överlåtas åt vakter eller utföras av dina mentorer i ditt ställe. Som Islen Waterseer påpekar måste du ta varje steg av egen kraft för att visa andarna att du har den inre styrka som krävs för att kommunicera med vatten.",al={"varför måste jag gå själv","varför jag call of water","kan någon annan gå till islen"}}},fp="13,254,24.294.0,23.358.0,29.129.0,33.125.0,47.126.0,51.165.0,48.146.0,43.141.0"}
P.entries["quest:153"] = {n="Red Leather Bandanas",s="Vid Sentinel Hill markerar Red Leather Bandanas kampen mot Defias Brotherhood. Scout Galiaan erbjuder en belöning för de röda tygmasker som laglösa bär, medan People's Militia kämpar för att spåra dem genom Westfall.",h="Vid Sentinel Hill markerar Red Leather Bandanas kampen mot Defias Brotherhood.",kw={"bandanor","defias brotherhood","peoples militia","red leather bandanas","scout galiaan","sentinel hill","westfall"},ang={["class:Rogue"]="Som skurk ser du hur Defias stråtrövare har slutit sig samman under sina karmosinröda masker till en armé vid Stormwinds tröskel.",["faction:Alliance"]="Som allierad till People's Militia hjälper du till att försvara Westfall medan Stormwinds kungliga ledning inte skickar någon hjälp."},sec={{t="Ett tecken på trohet",b="I hela Westfall markerar den röda bandanan Defias Brotherhood. Gänget lockar till sig ficktjuvar, plundrare och förrädare från många samhällsskikt, men medlemmarna samlas under samma karmosinröda tecken. Scout Galiaan och People's Militia vid Sentinel Hill samlar in bandanorna som bevis på att banditer har fallit. Tyget hjälper dem också att följa Defias när deras täckmantlar skiftar genom landsbygden."},{t="Milisens spaningsarbete",b="Stormwind har nekat Westfall ordentligt militärt stöd, så People's Militia förlitar sig på erfarna spanare som Scout Galiaan för att kartlägga Defias verksamhet. Galiaan håller utkik efter laglösa patruller från Sentinel Hill. Äventyrare på genomresa och frivilliga i milisen tar sig an det farliga arbetet med att fälla stråtrövare som har drivit bort hederliga bönder från deras mark."}},faq={{q="Varför bär Defias röda läderbandanor?",a="Den röda läderbandanan visar trohet till Defias Brotherhood och döljer identiteten på tidigare arbetare, tjuvar och laglösa. Den sprider också skräck bland Westfalls kvarvarande bönder.",al={"vad defias röda mask betyder","varför röda masker","defias bandanors bakgrund"}},{q="Vem är Scout Galiaan?",a="Scout Galiaan tjänstgör i People's Militia vid Sentinel Hill. Han följer Defias Brotherhoods rörelser och skiftande täckmantlar genom Westfall och samordnar belöningar för att begränsa den laglösa verksamheten.",al={"scout galiaan","vem ger röda läderbandanor","spanare vid sentinel hill"}},{q="Varför behöver milisen äventyrare som samlar in de här bandanorna?",a="People's Militia är hårt ansträngd och saknar både kungliga soldater och finansiering från Stormwind. Belöningar ger spanare som Galiaan bevis på fallna banditer och låter dem försvaga Defias samtidigt som Sentinel Hill hålls försvarat.",al={"varför samla in bandanor","varför milisen har belöning"}},{q="Var hittar man banditerna som bär de här bandanorna?",a="Defias laglösa strövar omkring i nästan varje hörn av Westfall. De håller till på övergivna bondgårdar, smyger kring vägkorsningarna och slår läger längs Gold Coast och runt Moonbrook-kullarna.",al={"var hittar man defias bandanor","defias platser i westfall"}},{q="Vad händer med bandanorna när du lämnar in dem?",a="Scout Galiaan använder bandanorna som bevis på fallna laglösa. De hjälper honom att följa Defias skiftande täckmantlar och bedöma hur milisens kampanjer påverkar Brotherhoods antal i regionen.",al={"vad galiaan gör med bandanor"}},{q="Är Stormwinds armé inblandad i den här belöningen?",a="Nej. Stormwinds militär har till stor del lämnat Westfall åt sitt öde för att fokusera på andra interna problem. Det lokala försvaret vilar på Gryan Stoutmantle och den frivilliga People's Militia.",al={"stormwinds vakter i westfall","hjälper stormwind sentinel hill"}}},fx={b62187e9={q="Varför vill Scout Galiaan att Defias-bandanas samlas in?",a="Scout Galiaan har följt Defias Brotherhoods skiftande rörelser genom Westfall. Genom att samla in de röda läderbandanas som deras fotsoldater och stråtrövare bär kan han bekräfta gängaktivitet, bedöma styrkan i deras utposter och minska deras antal innan de tar över Sentinel Hill helt.",al={"galiaans motiv med bandanas","varför galiaan vill ha bandanas","varför samla röda läderbandanas"}},["868cbc1b"]={q="Vilka jagar du efter de här bandanas?",a="Du jagar banditer och agenter från Defias Brotherhood som stryker omkring på Westfalls slätter och övergivna gårdar. Scout Galiaan har fått veta att många av gängets medlemmar kan spåras genom de röda läderbandanas de bär. Deras skiftande front har spridit sig över regionen genom räder, stölder och utpressning.",al={"vem har röda bandanas","mål för defias-bandanas","vem släpper röda läderbandanas"}}},fp="20,225,20.390.0,30.354.0,44.189.0,21.194.0,64.216.0,52.170.0,52.188.0,46.166.0"}
P.entries["quest:1530"] = {n="Call of Water",s="Islen Waterseer sänder hordens schamaner söderut genom The Barrens för att söka efter Brine. Där lär de sig vad vatten kan rena och läka.",h="Islen Waterseer sänder hordens schamaner söderut genom The Barrens för att söka efter Brine.",kw={"barrens","brine","call of water","islen waterseer","quilboarer","återfödelse","shaman","water sapta"},ang={["class:Shaman"]="Som schaman är gemenskap med vatten ett viktigt steg i din utveckling. Den förenar jordens styrka och eldens kraft med vattnets läkande förmåga.",["faction:Horde"]="Som medlem av horden färdas du genom Kalimdor för att bemästra elementen och hedra andarna som skänker krigshövdingens schamaner deras livsviktiga magi."},sec={{t="Tidvattnets lärdomar",b="Islen Waterseer lär ut att vatten ger återfödelse. Dess flöde kan forma klippa, skölja bort orenheter och läka kött, men dess läkande kraft beror på renhet. Förorenat vatten för med sig sjukdom i stället för liv. Varje schaman måste förstå denna balans innan de söker gemenskap med vatten."},{t="En eremit i dammet",b="Du färdas långt söderut genom det torra The Barrens för att hitta Brine. Quilboar-räder plågar ödemarken, men Brine lever ensam utan vakter eller rädsla. Hon besitter kunskapen och prövningarna som hjälper dig att knyta dig till vatten."}},faq={{q="Vem är Islen Waterseer?",a="Islen Waterseer är en schamanmästare vid kusten i The Barrens, söder om The Merchant Coast. Hon vägleder hordens schamaner genom prövningarna i gemenskap med vattenandar.",al={"islen","waterseer","vem skickar det här uppdraget"}},{q="Varför bor Brine i södra Barrens, omgiven av quilboarer?",a="Brine lever ensam i den södra ödemarken trots ständiga trakasserier från quilboar. Hon vet att faran verkar dåraktig för utomstående, men håller sina skäl för sig själv och prövar om du har styrkan att hitta henne.",al={"varför bor brine där","brine quilboarer","brines plats"}},{q="Vad används Water Sapta till?",a="En sapta är en ceremoniell blandning som förändrar en schamans sinnesintryck och låter schamanen se och tala med elementandar som är osynliga för dödliga ögon.",al={"sapta","vad används water sapta till","varför hämta water sapta"}},{q="Vilken grundläggande lärdom förmedlar vatten till en shaman?",a="Vatten ger återfödelse, rening och förnyelse. Rent vatten kan läka, men förorenat eller stillastående vatten för med sig förruttnelse och förödelse.",al={"vattnets lärdom","vattnets betydelse som element","vattnets återfödelse"}},{q="Vem kan göra den här resan?",a="Hordens schamaner som har bevisat sin hängivenhet och stämt sig till jord och eld skickas iväg för att genomgå prövningarna i Call of Water.",al={"vem får call of water","är call of water bara för horde"}},{q="Vilka faror väntar på vägen till Brine?",a="Södra The Barrens är farligt. Aggressiva quilboar-stammar försvarar sina taggiga bon, och bestar jagar vandrare långt från tryggheten i Crossroads eller Camp Taurajo.",al={"faror i södra barrens","vägen till brine"}}},fx={c40eecf4={q="Varför skickar Islen Waterseer dig till Brine?",a="Islen Waterseer vill vägleda dig genom de heliga prövningarna i att kommunicera med vatten. Hon lär ut att vatten står för återfödelse och läkande, men också för förödande korruption om det lämnas orent. För att bereda den Water Sapta som behövs för att tränga igenom slöjan och uppfatta elementandar hänvisar hon dig till Brine, som har den praktiska kunskap och de ingredienser som krävs för nästa övergångsrit.",al={"varför skicka mig till brine","islen waterseers motiv","varför söka upp brine"}},d6b5acd2={q="Varför låter Islen Waterseer dig göra den här resan ensam?",a="Att kommunicera med elementen är en djupt personlig andlig resa som varje blivande shaman måste göra själv. Varken vakter eller äldste kan genomgå en förståelseprövning åt dig. Att söka upp Brine genom det fientliga södra Barrens prövar din beslutsamhet, självständighet och hängivenhet till att vinna vattenandarnas gunst.",al={"varför måste jag gå till brine","varför jag call of water","varför skicka spelaren ensam"}}},fp="13,127,19.273.0,21.214.0,23.162.0,56.211.0,39.145.0,50.126.0,31.124.0,38.170.0"}
P.entries["quest:1531"] = {n="Call of Air",s="Vid Grommash Hold skickar Searn Firewarder erfarna schamaner söderut för att söka efter Air Totem. Prate Cloudseer leder dem mot den sista elementpelaren i deras lära.",h="Vid Grommash Hold skickar Searn Firewarder erfarna schamaner söderut för att söka efter Air Totem.",kw={"air totem","call of air","orgrimmar","prate cloudseer","searn firewarder","schamanuppdrag","thousand needles","valley of spirits"},ang={["class:Shaman"]="Air Totem är den avgörande milstolpen i din tidiga schamanresa. Den låter dig kalla på vindandar vid sidan av jord, eld och vatten.",["faction:Horde"]="Schamantraditionen förenar hordens många olika raser. Avlägsna äldste och eremiter runt om i centrala Kalimdor för vidare dess heliga seder."},sec={{t="En vindpust från söder",b="En schaman som har vunnit jordens, eldens och vattnets gunst står nu redo att bemästra luft, det sista av de fyra elementen. I Orgrimmar ser trolltränaren Searn Firewarder när en lärjunge har nått höjden av sin grundläggande träning och är redo för detta sista grundläggande steg. Han skickar schamanen söderut genom The Barrens och vidare ner i Thousand Needles labyrint av raviner."},{t="Molnskådarens eremitage",b="Prate Cloudseer väntar i en högt belägen grotta bland sandstensplatåerna i Thousand Needles. Eremiten lever stillsamt med sin partner, långt från hordens läger. Hon kräver vördnad innan hon avslöjar vindens hemligheter. Bemöt henne med tillbörlig respekt, så delar hon med sig av kunskapen och fokuset som krävs för att frammana Air Totem och fullborda schamanens elementcirkel."}},faq={{q="Vem ger uppdraget?",a="Searn Firewarder, en trolltränare i schamanism vid Grommash Hold, erbjuder detta till kvalificerade schamaner när de har nått rätt erfarenhetsnivå.",al={"uppdragsgivare","var får man call of air","searn firewarder"}},{q="Var hittar jag Prate Cloudseer?",a="Prate Cloudseer bor i Thousand Needles. Ta The Great Lift ner från södra The Barrens och gå österut över ravinens botten för att hitta hennes grotta.",al={"prate cloudseers plats","hitta prate","air totem-npc"}},{q="Vad används Air Totem till?",a="Air Totem är det fjärde och sista elementfokus en schaman får. Det låter en schaman åkalla luftbesvärjelser och lufttotemer med snabbhet, grace och vindbaserade krafter.",al={"air totems syfte","varför göra air totem-uppdraget","vad gör air totem"}},{q="Varför skickar Searn Firewarder dig så långt bort?",a="Att bemästra elementen kräver att man hittar mentorer som ägnar sig åt att tala med särskilda andar. Prate Cloudseer känner vindarna i de skiftande vindbyarna i Thousand Needles raviner och är därför den perfekta guiden till luft.",al={"varför thousand needles","varför prate cloudseer"}},{q="Måste jag slutföra de andra elementtotemuppdragen först?",a="Ja. Schamanträningen följer en strikt ordning genom elementen: jord, sedan eld och vatten, och slutligen luft.",al={"förkunskapskrav","totemernas ordning","kan jag göra air totem först"}},{q="Finns det andra versioner av uppdraget för olika städer?",a="Ja. Schamantränare i andra hordhuvudstäder, däribland Thunder Bluff, ger egna vägbeskrivningar till Prate Cloudseer i Thousand Needles.",al={"air totem i thunder bluff","air totem i undercity"}}},fx={["9e3dc8ab"]={q="Varför skickar Searn Firewarder dig till Prate Cloudseer?",a="Searn Firewarder ser att din andliga utveckling som shaman har kommit så långt att du kan kommunicera med luftens andar. Han kan inte själv skänka dig gemenskap med lufttotemet, eftersom den kunskapen finns hos Prate Cloudseer i Thousand Needles. Som mentor är det hans plikt att vägleda dig till henne, så att du lär dig visa vindens nyckfulla andar den respekt de förtjänar av någon som känner deras vägar väl.",al={"searn firewarders motiv","varför vill searn få det gjort","varför skicka mig till prate cloudseer"}},bc8bd922={q="Varför måste du åka i stället för att göra det själv?",a="En shamans väg är en personlig andlig resa som inte kan genomföras genom ombud. Searn Firewarder behärskar redan elementen och tjänar Horde genom att träna noviser i Orgrimmar. För att förtjäna lufttotemet måste du själv bevisa din ödmjukhet, uthållighet och respekt inför Prate Cloudseer och vindarna hon kommunicerar med.",al={"varför jag call of air","varför måste jag gå till prate","varför går inte searn själv"}}},fp="11,164,23.389.0,25.356.0,22.135.0,33.154.0,31.161.0,47.209.0,57.116.0,60.136.0"}
P.entries["quest:1532"] = {n="Call of Air",s="Call of Air är en viktig milstolpe på en hordeshamans andliga väg och leder hen till att söka gemenskap med vindens oförutsägbara element. Xanis Flameweaver i Thunder Bluff ger uppdraget och skickar erfarna noviser söderut till Thousand Needles för att lära av Prate Cloudseer. När en shaman bemästrar luften får hen den heliga totem som krävs för att kanalisera naturens snabbaste krafter.",h="Call of Air är en viktig milstolpe på en hordeshamans andliga väg och leder hen till att söka gemenskap med...",kw={"air totem","call of air","prate cloudseer","shaman","thousand needles","thunder bluff","xanis flameweaver"},ang={["class:Shaman"]="När du fullbordar din elementuppsättning når du en djupgående vändpunkt och får tillgång till Air Totems snabba strömmar och blixtomspunna krafter.",["faction:Horde"]="Genom att binda Kalimdors vilda vindar i en helig totem stärker hordeshamaner den andliga ryggraden i sin unga allians.",["race:Tauren"]="Från Mulgore höga klippor blickar shu'halo ner och vördar vindarna som heliga budbärare, som bär Jordmoderns viskningar över slätterna."},sec={{t="De viskande vindarna",b="Efter att redan ha stämt sig till jordens stadga, eldens våldsamhet och vattnets läkande djup når shamanen den sista elementpelaren: luft. Xanis Flameweaver, som vägleder utövare från Thunder Bluffs höjder, förklarar att vindarna är långt mer nyckfulla och svårbemästrade än de tidigare elementen. Provet kräver ödmjukhet, fokus och en medfödd respekt för himlens stormiga natur."},{t="En pilgrimsfärd söderut",b="För att stämma sig till vindarna måste shamanen resa söderut, förbi The Barrens vidsträckta slätter, och ta sig ner i Thousand Needles vindskulpterade kanjoner. Där, långt österut, bor eremiten och mystikern Prate Cloudseer. I en avskild grotta vid klippsidan, där kanjonens vinddrag tjuter dag och natt, prövar hon novisens beredskap innan hon skänker Air Totem, redskapet som krävs för att frammana vindbyar, blixtar och snabba vindandar."}},faq={{q="Vem skickar mig på det här uppdraget?",a="Xanis Flameweaver, en shamantränare i Thunder Bluff, erbjuder uppdraget när en novis har fått tillräcklig erfarenhet för att stämma sig till luftens element.",al={"uppdragsgivare","vem inleder call of air","xanis flameweaver"}},{q="Var finns Prate Cloudseer?",a="Prate Cloudseer bor i en skyddad grotta långt österut i Thousand Needles vindpinade kanjon, strax söder om The Barrens.",al={"prate cloudseer plats","var är prate","hitta prate cloudseer"}},{q="Varför söks luftens element sist?",a="Luft är känd för att vara nyckfull, plötslig och svårfångad. Enligt shamantraditionen måste novisen först bemästra jordens grundade stadga, eldens flyktiga hetta och vattnets flöde innan hen försöker förankra vindens vilda, osynliga strömmar.",al={"varför luft sist","shamanens air totem-lore","elementens ordning"}},{q="Vad får jag när jag hittar Prate Cloudseer?",a="Prate Cloudseer ger dig Air Totem, den andliga kanal som låter dig fokusera din elementmagi och kalla på luftandar för att få hjälp.",al={"belöning: air totem","vad ger prate","uppdragsbelöning för call of air"}},{q="Är det här uppdraget bara för taurer?",a="Även om uppdraget börjar i taurerna huvudstad Thunder Bluff kan alla hordeshamaner som stämt sig till de tre första elementen följa vägen till Thousand Needles och hämta sin Air Totem.",al={"kan orcher göra detta","är detta bara för taurer","hordeshamanens luftuppdrag"}},{q="Vad händer när jag har slutfört uppdraget?",a="Prate Cloudseer ger dig din Air Totem när du anländer. Då kan du genast åkalla vindbaserade totemer, och hon erbjuder fortsatt träning och prövningar för att stärka din förbindelse med himlen.",al={"what comes next","efter call of air","prate cloudseers uppdrag"}}},fx={["52df4f2b"]={q="Varför skickar Xanis Flameweaver mig på det här uppdraget?",a="Xanis Flameweaver ser att du har blivit tillräckligt stark på din shamanväg för att söka mästerskap över det mest ombytliga elementet: luft. Som din mentor i Thunder Bluff inser han att Kalimdors brusande vindar kallar på dig. Luft är ökänt svårt att binda och kommunicera med, och Xanis kan inte själv förmedla den sista insikten från de höga klipporna. I stället skickar han dig söderut till Thousand Needles, där Prate Cloudseer kan inviga dig i gemenskapen med luftandarna.",al={"varför xanis skickar mig","xanis flameweavers motiv","syftet med call of air"}}},fp="11,211,20.288.0,18.324.0,27.121.0,33.105.0,38.167.0,47.124.0,34.131.0,40.189.0"}
P.entries["quest:1534"] = {n="Call of Water",s="En schaman reser från The Barrens till The Ruins of Stardust för det sista samlingsprovet på vägen mot att få Call of Water. Brine skickar novisen norrut in i Ashenvale för att hämta rent vatten från dess gamla källa.",h="En schaman reser från The Barrens till The Ruins of Stardust för det sista samlingsprovet på vägen mot att få...",kw={"ashenvale","blå vattenflaska","brine","call of water","islen waterseer","mystral lake","the ruins of stardust","shaman"},ang={["class:Shaman"]="Som schaman korsar du farliga gränser i sökandet efter balans och samlar den sista flytande essens som behövs för att binda Water Totem.",["faction:Horde"]="Som resenär för horden färdas du in i uråldriga kaldoreiska länder, där Warsong Outriders för ett pågående timmerkrig mot fientliga nattalvsväktare.",["race:Tauren"]="Som tauren färdas du från Kalimdors torra hemländer i inlandet till heliga lundar som lever kvar i myter och äldstesånger."},sec={{t="Färden till Twilight Grove",b="Efter att ha hämtat vatten från pölen nedanför Brines hydda i The Barrens och den rena brunnen i Tarren Mill behöver schamanen en sista essens. Brine skickar novisen norrut över de torra slätterna och in i Ashenvale, en uråldrig skog som är helig för nattalverna. The Barrens torra marker övergår i Ashenvales täta trädkronor, där vattnet tar en annan form. En schaman måste förstå denna mångfald för att leva i harmoni med elementet."},{t="The Ruins of Stardust",b="Bortom det skimrande vattnet i Mystral Lake, nära bergspasset mellan Ashenvale och Stonetalon Mountains, ligger The Ruins of Stardust. En uråldrig källa vilar bland stilla vatten och gamla stenar i denna avskilda alvhelgedom. Otämjda element- och naturandar vaktar ruinerna och ogillar inkräktare. Schamanen måste gå varsamt fram för att hämta vatten ur källan."},{t="Den renaste vattendrycken",b="Brine tar emot den fyllda blå vattensäcken efter schamanens pilgrimsfärd genom Kalimdor och Eastern Kingdoms. Hon blandar det rena källvattnet med proverna från vattenhålet i The Barrens och Tarren Mill och bereder sedan en flaska med det renaste vattnet. Denna dryck förbereder schamanen för nästa prov: gemenskap med vattenelementandar genom siaren Islen Waterseer."}},faq={{q="Var ligger The Ruins of Stardust?",a="The Ruins of Stardust ligger i sydvästra Ashenvale. Från The Barrens reser du norrut och följer sedan vägarna västerut förbi Mystral Lake mot Stonetalon Mountains fot.",al={"the ruins of stardusts plats","var ligger stardust","hur tar man sig till the ruins of stardust"}},{q="Varför behöver Brine vatten från en alvruin?",a="En schaman samlar vatten från olika uttryck av elementet för att få kontakt med vattenandarna. Källan i The Ruins of Stardust rymmer uråldrigt, magiskt rent vatten som inte påverkats av The Barrens torra fördärv och fullbordar de tre essenser Brine behöver till sin ritualblandning.",al={"varför vatten från ashenvale","varför the ruins of stardust","varför vatten från stardust"}},{q="Vilka hot finns kring The Ruins of Stardust?",a="Skyddande bestar och naturandar vaktar ruinerna och vattnen i närheten. Territoriella vattenelementaler och bestar som hör hemma i Ashenvale angriper dem som stör lunden.",al={"fiender vid stardust","är stardust farligt","vem vaktar källan"}},{q="Vem är Brine och varför hjälper hon till?",a="Brine är en asketisk orchschaman som bor i en ensam hydda i södra The Barrens. Som en äldre vägvisare som bistår Islen Waterseer prövar hon blivande schamaners tålamod, uthållighet och förståelse för vatten innan hon skänker dem elementets välsignelser.",al={"vem är brine","brines bakgrund","vad har brine för roll"}},{q="Vad händer när jag har fört vattnet till Brine?",a="När Brine får det tredje provet blandar hon vattnen till en dryck av det renaste vattnet. Sedan skickar hon schamanen till Islen Waterseer på östra kusten av The Barrens för en visionär gemenskap med elementalerna.",al={"nästa steg i call of water","vad händer sedan","vart går jag efter brine"}},{q="Är Ashenvale säkert för Horde-shamaner på låg nivå?",a="Ashenvale är omstritt territorium där nattalver och horden drabbar samman. Rutten genom de södra skogarna undviker större nattalvboplatser som Astranaar, men kringströvande vilda djur, aggressiva elementaler och allianspatruller utgör faror för en novis.",al={"är ashenvale farligt","nivå för uppdrag i ashenvale"}}},fx={d600fc8e={q="Varför vill Brine att det här ska göras?",a="Brine vägleder blivande shamaner genom deras vattenprövning. Genom att samla rena prover från avlägsna och heliga platser bevisar du din hängivenhet till att förstå elementet. När du har hämtat vatten från den uråldriga källan vid The Ruins of Stardust kan hon blanda allt vatten du samlat till en ytterst ren brygd. Då fullgör hon sin del av din övergångsrit och förbereder dig på att återvända till Islen Waterseer.",al={"varför hjälper brine","brines motiv i call of water","varför hämta vatten från stardust"}},bc32fa0f={q="Vad används Filled Blue Waterskin till?",a="Skinnet innehåller det rena vattnet från den heliga källan i The Ruins of Stardust i Ashenvale. Det är den tredje och sista komponenten av rent vatten som Brine behöver för att bereda en flaska oblandat vatten till dina shamanprövningar.",al={"vad gör filled blue waterskin","användning av filled blue waterskin","varför fylla filled blue waterskin"}},d1cea88a={q="Varför skickar Brine dig i stället för att själv hämta vattnet?",a="Den här resan är en viktig del av din övergångsrit som shaman. Att söka upp avlägset, heligt vatten prövar din uthållighet, respekt för elementen och hängivenhet. Brine stannar vid sin damm för att förbereda ritualerna, men själva pilgrimsfärden måste du göra med egna händer.",al={"varför måste jag hämta vattnet","varför åker inte brine till ashenvale","varför skickar du mig på call of water"}}},fp="13,218,31.422.0,21.375.0,27.384.1,40.179.0,45.279.0,48.167.0,36.249.0,48.219.1,46.259.0"}
P.entries["quest:1535"] = {n="Call of Water",s="Brine skickar shamaner till The Barrens för att samla vatten till en sapta. Provet börjar med ett vattenprov från den bevakade dammen nedanför hennes kulle, där vatten betyder överlevnad.",h="Brine skickar shamaner till The Barrens för att samla vatten till en sapta.",kw={"the barrens","brine","brun vattensäck","call of water","quilboarer","sapta","vattenhål"},ang={["class:Shaman"]="Som shaman lär du dig att vatten skänker läkedom och återhämtning, men också orsakar konflikter och desperata kamper för överlevnad.",["faction:Horde"]="Som medlem av Horden ställs du inför utmaningen att kontrollera och dela på vattnet i The Barrens, där stammar och bestar ständigt slåss om varje rännil."},sec={{t="En läxa i öknen",b="Brine ber shamanlärlingar att studera vatten i alla dess former innan hon ger dem Water Sapta, som låter dem tala med andarna. I det torra The Barrens är vatten skillnaden mellan överlevnad och svält. Hon ber dem lägga märke till vad vatten möjliggör: skogar frodas där det rinner, öknar torkar ut där det saknas, och levande varelser dödar för att skydda även den anspråkslösaste källa."},{t="Quilboarernas skatt",b="De inhemska quilboarerna vaktar dammen nedanför Brines kulle med stor beslutsamhet. De behandlar varje vattenpöl som en ovärderlig skatt och festar närhelst det regnar. Brine beklagar våldet som deras hamstring orsakar, men deras slutenhet, girighet och splittrade klaner håller hotet i schack. För de andra raserna som överlever på slätterna innebär det en osäker balans."}},faq={{q="Varför ska du hämta vatten åt Brine?",a="Brine behöver prover av rent vatten från olika delar av världen för att brygga en ceremoniell Water Sapta. Drycken vidgar en lärlings sinnen och gör det möjligt att tala med elementära vattenandar.",al={"varför hämta vatten","brines vattenuppdrag","syftet med call of water-uppdrag 3"}},{q="Varför strider man så hårt om vattenhålet nedanför Brine?",a="I det uttorkade The Barrens är vatten den mest dyrbara resursen. De lokala quilboarerna behandlar varje vattenpöl som en helig skatt och slåss våldsamt mot alla som försöker hämta vatten därifrån.",al={"varför vaktar quilboarer vatten","quilboarernas damm","vattenhål i the barrens"}},{q="Vem är Brine?",a="Brine är en orcisk shaman och eremit som bor i en enslig hydda med utsikt över södra The Barrens. Hennes djupa visdom om vatten och elementandar vägleder Hordens shamaner mot samvaro med andarna.",al={"vem är brine","brine i the barrens","brine npc"}},{q="Vad händer när du lämnar tillbaka den fyllda bruna vattensäcken?",a="När du återvänder med ett prov från vattenhålet skickar Brine dig längre bort för att samla orört vatten från helt olika platser, däribland brunnen i Tarren Mill i Hillsbrad Foothills.",al={"vad händer efter call of water","efter vattenhålet","nästa steg hos brine"}},{q="Varför nämner Brine att quilboarerna är splittrade?",a="Brine ser quilboarernas revirhävdande och klanrivaliteter som orsaker till deras elände. Om de enades i stället för att slåss om avlägsna källor skulle de utgöra ett mycket större hot mot resten av The Barrens.",al={"brines kommentar om quilboarerna","varför slåss quilboarerna sinsemellan"}},{q="Vad är en sapta?",a="En sapta är ett mystiskt elixir som shamaner tillreder av insamlade ingredienser och vatten i samklang med elementen. När man dricker den vidgas den andliga synen och blottar elementvarelser som vanligtvis är dolda för dödliga ögon.",al={"vad är sapta","vad betyder water sapta"}}},fx={["6eca6e0d"]={q="Vad används Filled Brown Waterskin till?",a="Filled Brown Waterskin innehåller ett vattenprov från den omstridda dammen nedanför Brines kulle. Brine vill att du hämtar vattnet inte bara som en ingrediens till Water Sapta, utan också som en lärdom i dina shamanprövningar. När du hämtar det får du själv se den våldsamma tillgivenhet och blodsutgjutelse som den knappa, livgivande vätskan väcker bland de lokala quilboar.",al={"syftet med filled brown waterskin","varför filled brown waterskin","filled brown waterskin"}}},fp="13,162,22.399.0,20.344.0,50.195.0,58.172.0,13.182.0,56.196.1,49.200.0,16.202.0"}
P.entries["quest:1536"] = {n="Call of Water",s="Du ger dig av från The Barrens till en ren källa i Tarren Mill, som hålls av Forsaken. Vattnet hjälper Brine att bereda Water Sapta, och dess överlevnad ger en lärdom om hopp.",h="Du ger dig av från The Barrens till en ren källa i Tarren Mill, som hålls av Forsaken.",kw={"barrens","brine","call of water","hillsbrad","sapta","schaman","tarren mill","thrall","vattenskinn"},ang={["class:Shaman"]="Som schaman färdas du långt efter vatten och lär dig att söka harmoni och liv i Eastern Kingdoms bittra landskap.",["faction:Horde"]="Som krigare eller schaman i Horde, född i Kalimdor, besöker du Tarren Mill och möter dina nytillkomna, obekväma allierade Forsaken vid frontlinjen mot Hillsbrads mänskliga försvarare.",["race:Orc"]="Som ork kan du begrunda Thralls arv av överlevnad och styrka, och det höga priset för din frihet."},sec={{t="En mirakulös källa",b="Brine skickar dig över havet till Tarren Mill i Hillsbrad Foothills för att hämta vatten till Water Sapta. Mänskligt motstånd och de nyallierade Forsaken omringar staden, men den lilla brunnen i centrum ger rent källvatten. För Brine är källan en helig rest av renhet i ett vanhelgat land."},{t="Uthållighet i mörkret",b="Brine ser den rena brunnen i Tarren Mill som mer än en ingrediens. Hon jämför dess uthållighet med Warchief Thrall, som bar prövningar, fångenskap och sorg innan han steg fram som ledare för orcfolket. Thrall ger Horde hopp, och brunnen visar att liv och renhet kan bestå genom tragedi och fördärv."}},faq={{q="Var samlas vattenprovet in?",a="Du hämtar provet ur brunnen mitt i Tarren Mill, en gammal mänsklig bosättning i Hillsbrad Foothills som nu hålls av Forsaken.",al={"vatten i tarren mill","var ligger brunnen","call of water brunnens plats"}},{q="Varför skickar Brine dig så långt bort efter vatten?",a="Brine behöver särskilda vattenessenser för att brygga Water Sapta, som låter schamaner uppfatta elementandar. Hon fann källan under en tidigare resa till Hillsbrad och värdesätter dess renhet mitt i Forsakens förfall, både för dess kraft och lärdom.",al={"varför tarren mill","varför vatten från hillsbrad","varför brine vill ha det här vattnet"}},{q="Vad är Tarren Mill?",a="Tarren Mill är en anspråkslös mänsklig stad i norra Hillsbrad Foothills, som nu hålls av Sylvanas Windrunners Forsaken som en befäst Horde-utpost mot de lokala människostyrkorna.",al={"tarren mills historia","vem äger tarren mill"}},{q="Hur hänger det här uppdraget ihop med Thrall?",a="Brine jämför den rena brunnen med Warchief Thrall. Trots att Thrall förslavades och fick lida behöll han styrkan och visionen att leda den nya Horde, liksom brunnen behåller sin friskhet mitt bland pest och död.",al={"dialog mellan brine och thrall","kopplingen till thrall"}},{q="Vad händer när du lämnar tillbaka den fyllda vattenskinnet?",a="Brine tar emot den fyllda röda vattensäcken och berättar att hon behöver ytterligare ett särskilt vattenprov för att färdigställa reagensblandningen till din Water Sapta.",al={"vad händer sedan i call of water","efter vattnet från tarren mill"}},{q="Varför anses brunnens renhet ovanlig?",a="Stora delar av Lordaeron orenades av Scourges odödlighetspest, och Forsaken-bosättningar förknippas sällan med färska källor. Brunnen mitt i Tarren Mill ger fortfarande kristallklart vatten, en sällsynt orörd rest.",al={"varför är vattnet i tarren mill rent","förorenad brunn hos forsaken"}}},fx={["05ee6a54"]={q="Vad används Filled Red Waterskin till?",a="Filled Red Waterskin innehåller rent källvatten från brunnen i Tarren Mill i Hillsbrad. Brine behöver detta orörda prov tillsammans med de andra för att bereda ett särskilt reagens till din Water Sapta. Om du dricker brygden får du den andliga syn som behövs för att kommunicera direkt med vattenandar.",al={"användning av filled red waterskin","varför filled red waterskin","vattenprov från tarren mill"}}},fp="13,169,19.303.0,21.308.0,36.136.0,46.240.0,20.167.0,38.198.0,50.145.0,44.216.0"}
P.entries["quest:154"] = {n="Return the Comb",s="Return the Comb är ett alliansuppdrag i Duskwood som avslutar den hemsökta överenskommelsen med anden Blind Mary. När hon får en kam för att samla in testar av hennes spöklika hår grips det plågade spöket av förtvivlan över sin förlorade skönhet och kastar bort kammen. När du lämnar tillbaka kammen med håret till Madame Eva kan mystikern spinna det eteriska Ghost Hair Thread.",h="Return the Comb är ett alliansuppdrag i Duskwood som avslutar den hemsökta överenskommelsen med anden Blind...",kw={"blind mary","darkshire","duskwood","spökhår","ghost hair thread","madame eva","return the comb"},ang={["class:Priest"]="Att bevittna Blind Marys plågsamma självförakt ger en dyster inblick i plågan hos rastlösa andar som hålls kvar i den dödliga världen av sorg snarare än illvilja.",["faction:Alliance"]="När du färdas längs de dystra vägarna mellan Darkshire och Marys öde hem möter du det genomgripande förfall som har grepp om hjärtat av Duskwood.",["profession:Tailoring"]="Spinningen av Ghost Hair Thread visar Duskwoods kusliga hantverk och hur spöklikt material kan samlas in och kardas till slitstarka övernaturliga textilier."},sec={{t="En bitter spegelbild",b="Blind Mary dröjer sig kvar i en förfallen koja söder om Darkshire och sörjer för evigt sin tragiska död och sitt förändrade tillstånd. När du närmar dig med Madame Evas kam fördjupar påminnelsen om vanlig hårvård bara hennes sorg. När hon inser att hon inte längre är något annat än en vålnad — ett monster berövat sin mänskliga grace som ingen någonsin kommer att älska igen — ryggar hon tillbaka i fasa och trycker kammen och det spöklika håret som trasslat in sig i tänderna tillbaka i dina händer."},{t="Övernaturlig väv",b="Madame Eva väntar i Darkshire på att kammen ska återlämnas och känner väl till uppgiftens kusliga natur. Med det spöklika håret säkrat har spåkvinnan det sällsynta andliga material som krävs för att spinna en rulle Ghost Hair Thread. Eva spinner dessa eteriska fibrer till tråd och betalar resenärer för eventuella överblivna hårstrån från den varsamma spinningen."}},faq={{q="Varför reagerar Blind Mary med fasa på kammen?",a="Kammen påminner Blind Mary om hennes liv som dödlig och om hennes skönhet. När hon ser sig själv förvandlad till en vissen, spöklik skepnad brister hon ut i sorg, stöter bort kammen och beklagar att hon blivit ett monster som ingen någonsin kommer att hålla av igen.",al={"varför är mary upprörd","varför skrek blind mary","marys reaktion på kammen"}},{q="Vad gör Madame Eva med håret på kammen?",a="Madame Eva väver stråna som samlats i kammen till Ghost Hair Thread, en mystisk tråd med tusen användningsområden, från att binda onda andar till att sy liv i livlösa föremål.",al={"varför spökhår","vad gör eva med spökhåret","madame evas tråd"}},{q="Var finns Blind Mary?",a="Blind Mary hemsöker en övergiven, förfallen koja strax söder om Darkshire, nära Tranquil Gardens Cemetery i Duskwood.",al={"var finns blind mary","blind marys plats"}},{q="Vem är Madame Eva?",a="Madame Eva är en mystisk mänsklig siare och mystiker som bor i Darkshire. Hon spår framtiden, ger kryptisk vägledning och tillverkar magiska prydnader och reagenser åt dem som färdas genom Duskwoods faror.",al={"vem är madame eva","eva i darkshire"}},{q="Vad händer efter att du lämnat tillbaka kammen till Madame Eva?",a="När Madame Eva tagit emot kammen och förberett rullen med Ghost Hair Thread ber hon dig att leverera den färdiga tråden till Abercrombie, eremiten som bor nära Raven Hill Cemetery.",al={"what comes next","nästa uppdrag efter return the comb"}},{q="Varför ger Madame Eva dig mynt när uppdraget är klart?",a="Eva säger att kammen gav mer än nog med spöklikt hår för att väva den trådrulle som behövdes, och ger dig några mynt för att köpa loss de överblivna stråna till eget bruk.",al={"varför får jag mynt","pengar för överblivna strån"}}},fp="15,123,19.365.0,24.226.0,50.208.0,50.145.0,28.101.0,18.183.0,52.145.1,51.135.0"}
P.entries["quest:155"] = {n="The Defias Brotherhood",s="I Westfall söker Folkets milis efter Defias Brotherhoods gömda bas. En avhoppare går med på att leda Alliansens hjältar dit i utbyte mot beskydd. Vägen går genom Moonbrook, där Edwin VanCleefs innersta helgedom ligger dold.",h="I Westfall söker Folkets milis efter Defias Brotherhoods gömda bas.",kw={"the deadmines","defiasförrädaren","edwin vancleef","eskort","gryan stoutmantle","moonbrook","folkets milis","sentinel hill","westfall"},ang={["class:Rogue"]="Som lönnmördare ser du vad svek kostar i den kriminella undre världen, där brutna löften besvaras med dolkar.",["faction:Alliance"]="För den hårt ansatta Folkets milis är gömstället en stor militär framgång och den första verkliga chansen att utdela ett avgörande slag mot Westfalls kriminella uppror.",["race:Human"]="Som människa från Stormwind ser du hur Moonbrook fallit i laglöshet och ockuperats av före detta stenhuggare, ett tecken på hur djupt kungariket har splittrats sedan det tredje kriget."},sec={{t="En avhoppares uppgörelse",b="Gryan Stoutmantles kamp mot Defias Brotherhood når en vändpunkt när en tillfångatagen bandit går med på att tala. Hans forna bröder kan avrätta eller mörda honom, så The Defias Traitor gör upp med Folkets milis. Eskortera honom säkert genom fientligt område, så avslöjar han var Edwin VanCleef och hans ledare håller sig gömda. Tjuvarnas nätverk tystar dem som säger ifrån, och avhopparen behöver beväpnat beskydd längs vägen."},{t="Vägen genom Moonbrook",b="Vägen till gömstället går sydväst från Sentinel Hill in i Moonbrook, en ort som översvämmats av Brotherhood. Förrädaren leder sina beskyddare förbi det övergivna torget och fontänen, och väcker ilskan hos banditer, plundrare och stråtrövare som patrullerar ruinerna. Han visar vägen till ingången till det vidsträckta Deadmines under Moonbrook, där VanCleef har befäst ett underjordiskt fäste."}},faq={{q="Vem är The Defias Traitor?",a="The Defias Traitor är en före detta medlem av Brotherhood som blev informatör åt Gryan Stoutmantle och Folkets milis. Av rädsla för att dödas av sina tidigare kamrater bytte han platsen för Edwin VanCleefs underjordiska skans mot en eskort till säkerhet.",al={"vem är förrädaren","defiasförrädarens identitet","defiasråtta"}},{q="Vart leder förrädaren dig?",a="Han leder dig sydväst från Sentinel Hill in i Moonbrook, genom det förstörda torget och förbi fontänen, till ingången till Deadmines under orten.",al={"var finns defias gömställe","förrädarens väg","vart går han"}},{q="Varför behöver Gryan Stoutmantle den här informationen?",a="Folkets milis har kämpat mot stråtrövare i hela Westfall utan att veta var Edwin VanCleef leder verksamheten. När milisen hittar ingången till hans underjordiska lya får den ett tydligt mål mitt i upproret.",al={"varför eskorterar vi förrädaren","stoutmantles syfte","varför hitta gömstället"}},{q="Varför kryllar Moonbrook av Defias?",a="Moonbrook var en gång ett blomstrande jordbrukscentrum, men Stormwinds kungarike försummades och banditer flyttade in. Invånarna övergav orten, och Defias Brotherhood tog över de tomma byggnaderna som en yttre försvarslinje ovan jord kring ingången till Deadmines.",al={"varför finns defias i moonbrook","övertagandet av moonbrook","vem äger moonbrook"}},{q="Vad händer efter att du har hittat gömstället?",a="När förrädaren har avslöjat ingången till Deadmines rapporterar du till Gryan Stoutmantle vid Sentinel Hill. Med bevis för var VanCleef befinner sig förbereder milisen ett direkt anfall mot den underjordiska lyan.",al={"what comes next","efter defiaseskorten","uppdragets fortsättning"}},{q="Varför vill Brotherhood döda förrädaren?",a="Defias förlitar sig på hemlighetsmakeri. De gömmer sig i tunnlar medan de leder verksamhet över hela Stormwinds territorier. En avhoppare som avslöjar ingången till deras centrala verksamhet hotar att nysta upp deras konspiration.",al={"varför döda förrädaren","defias angriper förrädaren"}}},fx={["0ac3b75c"]={q="Varför är The Defias Traitor villig att vägleda dig?",a="Förrädaren slöt en desperat överenskommelse med People's Militia. Han har vänt Edwin VanCleef och Brotherhood ryggen och vet att han är en jagad man vars forna kamrater vill se honom död. Att leda dig rakt till det hemliga gömstället är hans enda återstående förhandlingskort för att köpa sin överlevnad och frihet under Gryan Stoutmantles beskydd.",al={"varför hjälpa defias traitor","defias traitors motiv","varför leder förrädaren dig"}},ef72c66d={q="Varför skickar Gryan Stoutmantle dig att eskortera förrädaren i stället för sina egna vakter?",a="People's Militia är hårt ansträngd bara av att hålla Sentinel Hill och slå tillbaka banditräder i Westfall. Stormwind har vägrat skicka kungliga trupper till regionens hjälp, så Stoutmantle saknar de disciplinerade soldater och de extra vakter som krävs för en säker eskort genom fiendeland. Hans enda praktiska val är att anförtro uppdraget åt dugliga, självständiga äventyrare.",al={"varför inte skicka milisvakter","varför eskortera förrädaren","varför behöver stoutmantle dig"}}},fp="22,242,20.448.0,26.404.1,26.261.0,32.155.0,49.224.0,38.270.0,44.197.1,47.210.0"}
P.entries["quest:156"] = {n="Gather Rot Blossoms",s="Tavernkeep Smitts i Darkshire behöver röta blommor för att brygga en sats av sin ökända ”zombie juice”. Dessa makabra växter spirar direkt ur ruttnande dödskallar från skelettmonster och vidunder som strövar omkring på Duskwoods rastlösa kyrkogårdar.",h="Tavernkeep Smitts i Darkshire behöver röta blommor för att brygga en sats av sin ökända ”zombie juice”.",kw={"darkshire","night watch","raven hill cemetery","rot blossom","skelettvidunder","skelettmonster","tavernkeep smitts","tranquil gardens cemetery","zombie juice"},ang={["faction:Alliance"]="Jakten på odöda på Duskwoods kyrkogårdar ger Night Watch i Darkshire välbehövlig avlastning. De utkämpar en daglig strid för att hindra staden från att falla.",["profession:Herbalism"]="Till skillnad från vanliga örter, som frodas i näringsrik jord och solljus, är Rot Blossoms mörka botaniska avvikelser som helt och hållet har sina rötter i nekromantisk förruttnelse och animerade ben."},sec={{t="En besynnerlig ingrediens",b="Medan de flesta värdshusvärdar stoltserar med lagrad öl och fina viner brygger Tavernkeep Smitts på Scarlet Raven Tavern ibland mer obehagliga drycker. Hans recept på ”zombie juice” kräver Rot Blossoms, vidrig, nekrotisk växtlighet som slår rot i tomma skallar på animerade skelett. Smitts är själv klok nog att aldrig komma nära de odöda, så han överlåter den fasansfulla skörden åt förbipasserande legosoldater."},{t="Skadedjursbekämpning på kyrkogården",b="För att samla dessa blommor måste du fälla skelettmonster och vidunder som strövar omkring bland de igenvuxna gravarna på Tranquil Gardens Cemetery eller över den väldiga Raven Hill Cemetery. Duskwoods lokala milis, Night Watch, är ständigt hårt ansträngd i kampen mot skogens krypande fasor. Smitts ser till att alla äventyrare som vågar sig bland gravstenarna blir vederbörligen rekommenderade till Commander Althea Ebonlocke för att rensa ut de rastlösa döda."}},faq={{q="Vad är en Rot Blossom?",a="En Rot Blossom är en vidrig växt som spirar i miljöer präglade av mörk magi och förruttnelse. I Duskwood växer de direkt inuti kranierna på animerade skelettmonster och vidunder.",al={"rot blossom","vad är en rot blossom","var kommer rot blossoms ifrån"}},{q="Varför behöver Tavernkeep Smitts Rot Blossoms?",a="Smitts använder blommorna som en viktig ingrediens när han brygger en dryck som kallas ”zombie juice”, en stark dryck som vissa gäster i trakten efterfrågar.",al={"varför vill smitts ha blommor","ingredienser i zombie juice","smitts dryck"}},{q="Var finns skeletten som bär på dessa blommor?",a="Skelettmonster och skelettvidunder samlas på gravplatser i hela Duskwood, särskilt på Tranquil Gardens Cemetery nära Darkshire och över den vidsträckta Raven Hill Cemetery i väster.",al={"var finns skelettmonster","rot blossom plats","skelett på tranquil gardens"}},{q="Hjälper det här uppdraget till att försvara Darkshire?",a="Ja. Darkshires överlevnad hänger på Night Watch, som skyddar staden mot ständiga attacker från odöda. Smitts säger att jakten på skelett efter blommorna hjälper Commander Althea Ebonlocke att minska antalet monster som hotar staden.",al={"hjälp till night watch","althea ebonlocke döda skelett"}},{q="Vad händer efter att blommorna har lämnats in?",a="När Smitts har fått blommorna och bryggt zombie juice ber han dig leverera den färdiga drycken till Abercrombie, en excentrisk eremit som bor nära Raven Hill Cemetery.",al={"nästa uppdrag efter rot blossoms","uppföljning på dryckesleveransen"}},{q="Är zombie juice en vanlig dryck som serveras i Darkshire?",a="Nej. Scarlet Raven Tavern serverar vanligtvis vanliga drycker från trakten. Zombie juice är en besynnerlig specialbrygd som Smitts bara tillreder när han får en excentrisk beställning som kräver nekrotiska ingredienser.",al={"är zombie juice vanlig","drycker på scarlet raven"}}},fx={["1d59b9b9"]={q="Vilka skelett bär på förruttnelseblommor?",a="Du skickas mot Skeletal Horrors och Skeletal Fiends som hemsöker Duskwoods gravplatser, särskilt Tranquil Gardens Cemetery och Raven Hill. Dessa odöda vidunder reser sig ur störda gravar i de skuggiga skogarna och bär på märkliga, nekrotiska förruttnelseblommor inne i sina skallhålor.",al={"skeletal horrors i duskwood","skeletal fiends på tranquil gardens","vilka skelett släpper förruttnelseblommor"}},["1e6a32cf"]={q="Varför skickar Tavernkeep Smitts dig i stället för Night Watch?",a="Smitts driver Scarlet Raven Tavern och erkänner att han aldrig vågat komma nära nog för att undersöka ett levande skelett. Samtidigt är Night Watch farligt hårt ansträngd med att försvara Darkshire mot fiender från alla håll. När en duglig äventyrare jagar nära gravplatserna kan den lokala vakten i stället skydda stadens utkanter.",al={"varför dödar inte night watch skeletten","varför skickar smitts mig","varför behöver tavernkeep smitts dig"}}},fp="19,155,20.266.0,22.348.0,22.147.0,45.109.0,56.172.0,45.190.0,46.159.1,54.172.0"}
P.entries["quest:1560"] = {n="Tooga's Quest",s="Tooga, en vilsegången sköldpadda, skickades ut för att hämta middag av sin fru Torta, men tog fel väg någonstans. Tooga ber dig leda honom tillbaka till Torta, som väntar strax söder om Steamwheedle Port.",h="Tooga, en vilsegången sköldpadda, skickades ut för att hämta middag av sin fru Torta, men tog fel väg...",kw={"steamwheedle port","tanaris","thistleshrub valley","tooga","torta","sköldpadda"},sec={{t="En vilsegången vandrare",b="Tooga vandrar omkring nära ett kraschlandat goblinzeppelin nära Thistleshrub Valley. Torta skickade ut Tooga för att hämta middag, men en felaktig avstickare har gjort sköldpaddan hopplöst vilse. Tooga ber dig visa vägen tillbaka."},{t="Tvärs över området",b="Torta väntar strax söder om Steamwheedle Port, i motsatta hörnet av Tanaris, så promenaden tar dig tvärs över nästan hela området."},{t="Ett varmt välkomnande",b="Torta är inte förvånad över att Tooga inte kunde hitta hem på egen hand och säger åt Tooga att gå ut i havet och hämta mat."}},faq={{q="Vem är Tooga?",a="En vilsegången sköldpadda i Tanaris som behöver hjälp att hitta tillbaka till sin fru.",al={"vem är tooga","tooga sköldpadda","vem är sköldpaddan i tanaris"}},{q="Vem är Torta?",a="Toogas fru, som väntar strax söder om Steamwheedle Port.",al={"vem är torta","var är torta","tortas plats"}},{q="Varför har Tooga gått vilse i öknen?",a="Torta skickade Tooga för att hämta middag, men en felaktig avstickare gjorde honom vilse.",al={"varför har tooga gått vilse","vad hände med tooga","toogas bakgrund"}},{q="Var hittar man Tooga från början?",a="Nära ett kraschlandat goblinzeppelin vid Thistleshrub Valley i Tanaris.",al={"toogas startplats","var börjar toogas uppdrag","hitta tooga"}}},fp="13,186,15.213.0,15.144.0,16.132.1,13.73.0,13.56.0,32.65.0,32.65.0"}
P.entries["quest:157"] = {n="Deliver the Thread",s="Deliver the Thread är ett uppdrag åt Alliansen i Duskwood. Du ska föra en rulle Ghost Hair Thread från Madame Eva i Darkshire genom den hemsökta skogen till Abercrombie. Den excentriske eremiten nära Raven Hill Cemetery säger att han behöver den förtrollade tråden för att skydda sin fallfärdiga hydda mot rastlösa andar. Men Madame Evas mörka kommentarer om tråden antyder att den kan ha långt mer illvilliga användningsområden.",h="Deliver the Thread är ett uppdrag åt Alliansen i Duskwood.",kw={"abercrombie","darkshire","deliver the thread","duskwood","ghost hair thread","madame eva","raven hill","raven hill cemetery","zombie juice"},ang={["class:Priest"]="Att skydda sitt hem mot de rastlösa döda brukar kräva heliga riter till Ljusets ära. Att förlita sig på vävda rester av de döda själva tyder på att Abercrombie slagit in på en betydligt mörkare väg.",["faction:Alliance"]="Darkshires bräckliga trygghet är beroende av vaksamhet. Att skicka hjälp genom de monsterfyllda västra skogarna till en isolerad eremit tänjer på Nattvakten, vars gränsstyrkor redan är hårt ansträngda.",["profession:Tailoring"]="Att spinna spöklikt hår till användbara trådrullar är ingen vanlig vävning. Det förenar nålkonst med folknära nekromanti och skapar ett material som kan sy i materia bortom den fysiska världen."},sec={{t="En färd i mörkret",b="När Madame Eva har spunnit klart det spöklika hår hon samlat från spöket Blind Mary, anförtror hon Ghost Hair Thread åt varje resenär som är villig att bära den västerut. Färden kräver att du tar dig genom Duskwoods skuggiga vidder och förbi lurande spindlar och kringströvande odöda för att nå Abercrombies förfallna skjul, strax norr om den vidsträckta kyrkogården."},{t="Livets och dödens trådar",b="Abercrombie hävdar att han behöver den vävda spöksträngen för att klä sina fönster och dörrkarmar och hålla Raven Hills jämrande döda ute. Men Madame Eva råkar avslöja att tråd av spökhår har tusen användningsområden: den kan binda illvilliga andar, men också sy sken av liv i död och livlös materia. Eremiten tar emot rullen med stor förtjusning och är ivrig att sätta sitt dolda hantverk i verket."}},faq={{q="Vad är ghost hair thread?",a="Det är en förtrollad trådrulle som Madame Eva spinner i Darkshire med hår från spöket Blind Mary. Enligt Eva har den kraftfulla ockulta egenskaper och kan binda andar eller sy liv i livlösa föremål.",al={"spökhår","vad är tråden","spöktråd"}},{q="Vem är Abercrombie?",a="Abercrombie är en gammal enstöring som bor i ett ensligt skjul strax norr om Raven Hill Cemetery. Han framställer sig som en harmlös och skröplig eremit som ständigt är livrädd för de odöda som stryker omkring nära hans hem.",al={"eremit","vem är abercrombie","karl i skjul"}},{q="Varför säger Abercrombie att han behöver tråden?",a="Abercrombie säger till besökare att han tänker spänna upp spökhåret längs fönstren och dörröppningarna. Han hävdar att dess andliga egenskaper ska fungera som skydd mot de oönskade gastar och andar som vandrar omkring i Duskwood.",al={"varför tråden","abercrombies ursäkt","skydda mot andar"}},{q="Var finns Abercrombie?",a="Han bor i ett avskilt träskjul norr om Raven Hill Cemetery, strax intill den västra vägen genom Duskwood.",al={"abercrombies plats","var finns skjulet","eremitens skjul"}},{q="Vad händer när du ger tråden till Abercrombie?",a="När Abercrombie tar emot tråden belönar han budbäraren och börjar genast klaga över andra brådskande behov. Han skickar iväg resenärer på fler ärenden efter märkliga alkemiska ingredienser som Zombie Juice.",al={"nästa uppdrag","vad händer sedan","efter deliver the thread"}},{q="Vet Madame Eva vad Abercrombie håller på med?",a="Eva anklagar inte Abercrombie direkt för något ont, men hennes gåtfulla avskedsord nämner att spökhår kan användas för att sy liv i livlösa föremål. Hon verkar väl känna till trådens nekromantiska potential, trots att hon utför beställningen utan protester.",al={"vet eva","madame eva medskyldig","evas varning"}}},fx={["011e87a7"]={q="Varför vill Madame Eva att Ghost Hair Thread levereras till Abercrombie?",a="Madame Eva infriar sin del av en överenskommelse. Abercrombie bad om ghost hair thread för att skydda sitt eremitage mot The Restless Dead, och Eva gick med på att spinna tråden när du hämtat Blind Marys spökhår. Hon ser honom bara som en skröplig, excentrisk eremit som försöker överleva fasorna nära Raven Hill och anförtror dig att tryggt bära den färdiga trådrullen till hans dörr.",al={"varför hjälper madame eva abercrombie","madame evas motiv","varför leverera tråden"}}},fp="18,174,22.245.0,25.356.1,26.180.0,19.162.0,47.133.0,29.134.0,52.166.0,47.215.0"}
P.entries["quest:1578"] = {n="Supplying the Front",s="Supplying the Front är en tidig uppgift för dvärgiska smeder under utbildning, beställd av Tormus Deepforge i Ironforge. Smederna ska smida vapen och rustningar som stöd åt Mountaineers i Loch Modan mot de ständiga troggintrången.",h="Supplying the Front är en tidig uppgift för dvärgiska smeder under utbildning, beställd av Tormus Deepforge i...",kw={"smide","kopparyxa","kopparkedjebälte","ironforge","loch modan","supplying the front","thelsamar","thorvald deepforge","tormus deepforge","troggs"},ang={["faction:Alliance"]="Gränssäkerheten i Khaz Modan skyddar bergsvägarna som förbinder Ironforge med Stormwind och Alliansens verksamhet i de södra områdena.",["profession:Blacksmithing"]="Uppgiften är ett tidigt mandomsprov för blivande metallarbetare och prövar deras förmåga att tillverka pålitliga, enhetliga kopparvapen och rustningar för verkligt militärt bruk.",["race:Dwarf"]="Försvaret av Loch Modan är direkt beroende av dvärgarnas hantverksskicklighet. Det visar att en hantverkare vid blåsbälgen är lika viktig för kungarikets överlevnad som en bergsjägare med gevär."},sec={{t="Att beväpna Mountaineers",b="I Ironforges stora smedjor håller mästersmeden Tormus Deepforge noga uppsikt över gränserna till kungariket Khaz Modan. Mountaineers som försvarar Loch Modans dalar pressas hårt av plötsliga troggattacker från nyupptäckta ruiner och grottor. För att hålla försvarslinjerna försedda krävs en ständig tillförsel av nya klingor, bälten och beslag, så lokala hantverkare får hjälpa till."},{t="Deepforge-släkten",b="För att hålla försvaret försett utan att dra bort erfarna hantverkare från stadens smedjor skickar Tormus lärlingar österut till Loch Modan. Där sköter hans kollega Thorvald Deepforge en fältsmedja i det södra vakttornet. Genom att leverera stadiga kopparyxor och kopparkedjebälten direkt till Thorvald visar smederna att de är pålitliga och lär sig avancerade smidestekniker."}},faq={{q="Vem erbjuder uppdraget och vad krävs?",a="Tormus Deepforge, en smed i Great Forge i Ironforge, erbjuder uppgiften till smedlärlingar med minst trettio i färdighet. Du måste tillverka sex kopparyxor och sex kopparkedjebälten.",al={"vem ger supplying the front","uppdragsgivare","krav för smedsuppdrag"}},{q="Var finns Thorvald Deepforge?",a="Thorvald Deepforge är stationerad inne i det södra vakttornet i Loch Modan. Följ huvudvägen söderut förbi Thelsamar mot gränsen till Badlands, där tornet står intill bergspasset.",al={"var finns thorvald","thorvalds plats","södra vakttornet i loch modan"}},{q="Varför behöver Mountaineers så många kopparföremål?",a="Mountaineers i Loch Modan utkämpar ständiga skärmytslingar med våldsamma troggs. Den hårda striden gör snabbt deras utrustning kantstött, slö och trasig, så de behöver en oavbruten tillförsel av enkla vapen och ringbrynjerustningar.",al={"varför behöver de yxor","vad ska kopparen användas till"}},{q="Hur är Thorvald släkt med Tormus?",a="Tormus kallar Thorvald sin kollega, och eftersom de delar klannamnet Deepforge är de nära knutna hantverkare som samarbetar för att förena Ironforges industriella kapacitet med försvaret i fält.",al={"är thorvald och tormus släkt","tormus kollega"}},{q="Vilken sorts belöning erbjuder Thorvald?",a="Som tack för att du avlastar försörjningen av det södra vakttornet delar Thorvald med sig av sin yrkeskunskap genom att ge dig ritningar till ny rustning.",al={"uppdragsbelöning","vad lär thorvald ut"}},{q="Varför är troggs ett så stort problem i Loch Modan just nu?",a="Dvärgarnas senaste utgrävningar har blottlagt underjordiska valv och håligheter i Khaz Modan. Av misstag har de väckt och grävt fram svärmar av aggressiva troggs som nu hotar bosättningarna och vakttornen i området.",al={"varför anfaller troggs","troggproblemet i loch modan"}}},fx={["0062256f"]={q="Varför behöver Tormus Deepforge fler Copper Axes?",a="Ironforge Mountaineers som strider i Loch Modan utkämpar oupphörliga skärmytslingar mot troggs. Vapen går snabbt sönder i ständiga strider, och Thorvald Deepforge behöver desperat nya vapen så att försvararna kan hålla sin frontlinje.",al={"vad används copper axes till","användning av copper axes för fronten","varför copper axes"}},c19cb0c2={q="Varför behöver Thorvald Copper Chain Belts?",a="Troggs attacker är brutala och obevekliga, och Mountaineers skyddsutrustning slits ner lika snabbt som de hinner reparera den. Thorvald är beroende av stadiga leveranser av hållbara rustningsdelar som kopparkedjebälten för att hålla dvärgposteringarna ordentligt skyddade i de södra passen.",al={"vad används copper chain belts till","användning av copper chain belt","varför copper chain belts"}},f96d051f={q="Varför ber Tormus Deepforge en äventyrare att hjälpa till med att förse fronten?",a="Thorvald är överhopad med att försöka hinna med reparationerna vid fronten, och Tormus kan inte överge sin egen städ i Ironforge. Som blivande smed får du pröva ditt hantverk genom att smida utrustningen och bära den österut genom tunnlarna, samtidigt som du avlastar bergsvakten direkt.",al={"varför jag hjälpa fronten","varför behöver tormus mig","varför skicka en äventyrare till thorvald"}}},fp="19,170,23.282.0,21.309.0,43.199.0,36.184.0,53.197.0,36.153.0,40.103.0,57.211.0"}
P.entries["quest:1579"] = {n="Gaffer Jacks",s="Wizbang Cranktoggle, en gnomisk uppfinnare med baksmälla i Auberdine, behöver hjälp att hämta en låda med förlorade delar som han kastade i havet. Efter att ha flytt från Ironforges oväsen till Kalimdors stilla stränder lyckades han tappa sina viktiga gaffer jacks överbord under resan. Den som har ett fiskespö och tålamod kan dra upp de försvunna delarna längs kusten.",h="Wizbang Cranktoggle, en gnomisk uppfinnare med baksmälla i Auberdine, behöver hjälp att hämta en låda med...",kw={"auberdine","darkshore","electropellers","fiske","gaffer jacks","ironforge","stintle pegs","wizbang cranktoggle"},ang={["profession:Engineering"]="Alla ingenjörer vet hur eländigt det är att sakna en enda liten, ovanlig mekanisk del som behövs för att kalibrera en känslig apparat.",["race:Gnome"]="Wizbang personifierar gnomiska uppfinnares rastlösa excentricitet, även om till och med andra gnomer kan rysa åt hans vårdslösa kombination av högprecisionskomponenter och kraftigt drickande.",["race:NightElf"]="Darkshores stilla, heliga skogar är ett märkligt resmål för en bitsk gnomisk uppfinnare med baksmälla, och sätter tålamodet hos Auberdines Night Elf-väktare på prov."},sec={{t="Ett rörigt sinne i en stilla hamn",b="För att komma bort från oväsendet i Ironforges Great Forge och finna lugn och ro seglade den excentriske gnomiske uppfinnaren Wizbang Cranktoggle över Great Sea till Darkshore. Tyvärr drack Wizbang lite för mycket under överfarten. När han lutade sig över relingen i ett alkoholrus lyckades han tappa en hel låda med specialiserade metalldelar, så kallade gaffer jacks, i kustvattnen utanför Auberdine."},{t="Justering av stintle pegs",b="För vanliga förbipasserande kan gaffer jacks se ut som obetydliga metallskrot, men för Wizbang är de oumbärliga precisionsverktyg. Han hävdar att det är helt omöjligt att kalibrera hans stintle pegs ordentligt eller fortsätta med något av hans finmekaniska arbete utan dem. Eftersom han helst slipper kasta sig i det kalla havet ber gnomens lokala fiskare att kasta ut sina linor längs Darkshores strand och fiska upp de utspridda delarna."}},faq={{q="Vad är gaffer jacks?",a="Gaffer jacks är små gnomiska mekaniska fästen och komponenter. Enligt Wizbang Cranktoggle är de viktiga specialverktyg som används specifikt för att justera stintle pegs i hans uppfinningar.",al={"vad är en gaffer jack","användning av gaffer jack","föremålet gaffer jacks"}},{q="Hur hamnade gaffer jacks i havet?",a="Wizbang Cranktoggle drack lite för mycket under sjöresan från Eastern Kingdoms till Kalimdor. När han var berusad ombord råkade han tappa sin låda med delar överbord nära Darkshores kust.",al={"hur tappade han dem","varför ligger de i vattnet","varför fiska efter gaffer jacks"}},{q="Varför är Wizbang Cranktoggle i Auberdine i stället för Ironforge?",a="Wizbang sökte sig till Auberdine just för dess tystnad och stillhet. Det ständiga oväsendet, de ringande städen och de högljudda verkstäderna i Ironforge blev outhärdliga för honom, särskilt när han led av baksmällorna efter sitt kraftiga drickande.",al={"varför är wizbang i auberdine","varför lämnade wizbang ironforge"}},{q="Var kan man fiska upp de förlorade gaffer jacks?",a="De går att fiska upp ur det öppna saltvattnet längs Darkshores kust nära Auberdine. Fiskare får upp dem med vanliga kast från stranden, inte från särskilda fiskstim.",al={"var fiskar jag gaffer jacks","gaffer jacks plats"}},{q="Vad händer när man har hittat gaffer jacks?",a="När Wizbang får tillbaka sina gaffer jacks så att han kan justera sina pegs avslöjar han att han också lyckades tappa ännu en viktig utrustningsuppsättning i Darkshores floder och sjöar: sina electropellers, som också måste fiskas upp.",al={"vad händer efter gaffer jacks","uppdrag efter gaffer jacks"}},{q="Varför behöver Wizbang äventyrare som hämtar dem åt honom?",a="Med sin bultande baksmälla och utan fiskeutrustning för havsfiske föredrar Wizbang att hålla sig torr och trygg på bryggorna i Auberdine. Han överlåter det långtråkiga arbetet med att dra upp delarna åt förbipasserande med fiskespö.",al={"varför kan wizbang inte hämta dem","varför fiskar inte wizbang"}}},fx={bd1e627b={q="Varför vill Wizbang Cranktoggle att de där gafferjacksen hämtas?",a="Wizbang reste hela vägen från Ironforge till Darkshore för att få lugn och ro att arbeta med sina uppfinningar. Tyvärr hamnade hans oumbärliga förnödenheter på havets botten efter ett klumpigt, berusat missöde under resan. Utan gafferjacksen stannar hans fantastiska uppfinningsarbete omedelbart, eftersom han inte ens kan stämma sina stintle pegs utan dem.",al={"varför behöver wizbang gafferjacks","wizbang cranktoggle motiv","varför hjälpa wizbang cranktoggle"}}},fp="12,213,33.266.0,23.280.0,22.132.0,43.168.0,61.144.0,45.154.0,47.161.1,69.147.0"}
P.entries["quest:158"] = {n="Zombie Juice",s="Zombie Juice är ett ärende åt Abercrombie, den säregne eremiten som bor i Duskwoods hemsökta vildmarker. Han säger sig lida av den tryckande midnattskölden och skickar resenärer till Darkshires värdshus för att hämta en ovanligt stark brygd.",h="Zombie Juice är ett ärende åt Abercrombie, den säregne eremiten som bor i Duskwoods hemsökta vildmarker.",kw={"abercrombie","darkshire","duskwood","sprit","scarlet raven tavern","tavernkeep smitts","zombie juice"},ang={["faction:Alliance"]="Alliansens äventyrare som hjälper den hårt ansatta utposten Darkshire får ofta agera kurirer åt de excentriska enstöringar som söker skydd längs Duskwoods farliga vägar."},sec={{t="En kylig begäran",b="Eremiten Abercrombie bor ensam bland skuggskogarnas fasor och skickar ofta hjälpsamma resenärer på märkliga ärenden. Han säger att den smygande skymningen berövar honom värme och livskraft och ber en äventyrare bege sig österut till Darkshire. Målet är Tavernkeep Smitts på Scarlet Raven Tavern, där han vill ha en flaska av en stark brygd med det olycksbådande namnet Zombie Juice, så att han kan få elden tillbaka i ådrorna."},{t="På Scarlet Raven",b="Värdshuset i Darkshire får besök av många utmattade vakter och skrämda stadsbor, men förfrågningar om Zombie Juice är ovanliga även för Tavernkeep Smitts. Drycken är känd för att vara farligt stark. Smitts känner igen årgången, men Abercrombies törst efter en så makaber brygd väcker diskreta blickar i en trakt som redan är belägrad av de rastlösa döda."}},faq={{q="Vad är Zombie Juice?",a="Det är en exceptionellt stark sprit med ett makabert namn, som säljs av Tavernkeep Smitts på Scarlet Raven Tavern i Darkshire. Vanliga gäster frågar sällan efter den.",al={"drycken zombie juice","vad är det för sprit","zombie juice i berättelsen"}},{q="Vem skickar dig för att hämta Zombie Juice?",a="Eremiten Abercrombie, som lever isolerad i en koja i västra Duskwood, ber resenärer hämta drycken för att värma hans frusna ben.",al={"vem ger uppdraget zombie juice","abercrombies uppdragsdryck","eremitens dryckesbegäran"}},{q="Var lämnar du in uppdraget?",a="Du talar med Tavernkeep Smitts inne på Scarlet Raven Tavern, det centrala värdshuset i Darkshire i östra Duskwood.",al={"var finns smitts","lämna in zombie juice","smitts plats"}},{q="Varför vill Abercrombie ha den?",a="Abercrombie säger att de dystra, skuggade nätterna i Duskwood får honom att huttra och att han behöver den eldiga drycken för att värma blodet.",al={"varför behöver abercrombie drycken","abercrombie fryser","varför dricker han zombie juice"}},{q="Blir Tavernkeep Smitts förvånad över beställningen?",a="Ja. Smitts påpekar att Zombie Juice är oerhört starkt och nämner att hans stamgäster sällan frågar efter den.",al={"smitts reaktion","har smitts zombie juice","smitts dialog"}},{q="Innebär uppdraget att du måste slåss mot monster?",a="Nej. Själva ärendet kräver bara att du färdas längs vägen från Abercrombies avskilda koja till Darkshire och talar med Tavernkeep Smitts, även om Duskwoods vägar alltid är fulla av kringströvande bestar och odöda.",al={"strid i zombie juice-uppdraget","är zombie juice farligt","monster i zombie juice-uppdraget"}}},fx={aa8c42e6={q="Varför behöver Abercrombie att du hämtar Zombie Juice?",a="Abercrombie lever som en bräcklig, ensam eremit i avskildhet bland de dystra, hemsökta skogarna nära Raven Hill. Att färdas hela vägen till Darkshire längs Duskwoods monsterfyllda vägar, bara för att besöka Scarlet Raven Tavern, är alldeles för farligt för en ålderstigen enstöring, särskilt när skickliga äventyrare som du gärna uträttar hans ärenden.",al={"varför kan inte abercrombie hämta den","varför jag zombie juice","varför skicka mig efter zombie juice"}}},fp="12,145,16.409.0,20.305.0,21.170.0,36.146.0,31.110.0,29.120.0,44.105.0,46.176.0"}
P.entries["quest:1580"] = {n="Electropellers",s="Electropellers är ett lättsamt ärende åt den excentriske gnomuppfinnaren Wizbang Cranktoggle i Auberdine. Efter att ha tappat sin väska med prototypdelar i Darkshores sötvattenbäckar under ett missöde med en explosiv andattrapp ber Wizbang förbipasserande fiskare att fiska upp dem igen.",h="Electropellers är ett lättsamt ärende åt den excentriske gnomuppfinnaren Wizbang Cranktoggle i Auberdine.",kw={"auberdine","cliffspring river","darkshore","andattrapp","electropellers","fiske","wildbend river","wizbang cranktoggle"},ang={["profession:Engineering"]="Electropellers är märkliga exempel på miniatyriserad gnomisk framdrivning, utformade för att driva mekaniska lockänder innan de exploderar våldsamt.",["race:Gnome"]="Wizbangs kaotiska ambition att bygga exploderande andattrapper är en välbekant syn för alla gnomer, även om det är lite pinsamt att tappa dyra delar i en flod som vaktas av alver.",["race:NightElf"]="De lokala nattalverna ser med tyst ogillande på Wizbangs högljudda, rökiga uppfinningar och hans nedskräpning av floderna. De föredrar att Darkshores bäckar förblir orörda."},sec={{t="En berusad uppfinning",b="Gnomuppfinnaren Wizbang Cranktoggle, stationerad i den stillsamma nattalvshamnen Auberdine, tillbringade en kväll med att ströva inåt land i Darkshore på jakt efter testområden. Hans senaste projekt var en självgående, exploderande andattrapp. Tyvärr ledde lite för mycket dryck till att han plötsligt slocknade. Wizbang vaknade flera timmar senare i staden med svedd hår och en helt tom packning. Han hade råkat tappa sin dyrbara väska med electropellers i en av kustens floder."},{t="Att muddra vattnen",b="I stället för att själv ge sig ut i vildmarken för att hämta de utspridda mekaniska delarna ber Wizbang lokala fiskare att muddra Darkshores sötvattenbäckar. Fiskare som kastar ut linan i vattendrag som Wildbend River och Cliffspring River får ofta upp de flytande metallmojängerna tillsammans med den lokala fisken. När delarna återfunnits kan den omedvetne gnomen återuppta sina farligt oberäkneliga experiment med sjöfåglar."}},faq={{q="Var hittar jag electropellers?",a="De måste fiskas upp ur Darkshores sötvattensfloder och sjöar, till exempel Cliffspring River eller Wildbend River. De dyker inte upp i havsvattnet längs kusten.",al={"var finns electropellers","hur får man electropellers","electropellers plats"}},{q="Vem är Wizbang Cranktoggle?",a="Wizbang är en excentrisk gnomingenjör som bor i Auberdine. Han är känd för sina bisarra och explosiva uppfinningar och förlitar sig på äventyrslystna resenärer som samlar in förlorade delar och märkliga föremål till hans experiment.",al={"vem ger electropellers","wizbang cranktoggle"}},{q="Vad försökte Wizbang bygga?",a="Han arbetade på en självgående, exploderande andattrapp. Testet gick snett efter att han druckit lite för mycket och råkat detonera en tidig prototyp. Håret sveddes och väskan med delar försvann i vattnet.",al={"exploderande andattrapp","wizbangs projekt"}},{q="Kan electropellers hittas i fiskstim?",a="Nej, electropellers dras upp när du fiskar i öppet sötvatten. Om du kastar linan direkt i särskilda stim, som Lesser Oily Blackmouth-stim, får du inte upp de mekaniska delarna.",al={"electropellers i fiskstim","kan jag fiska i stim"}},{q="Vilket uppdrag kommer före det här?",a="Du måste först slutföra Gaffer Jacks, en tidigare fiskeuppgift som Wizbang ger dig för att testa din fiskelycka i de lokala vattnen.",al={"förkrav för electropellers","electropellers förkunskapskrav"}},{q="Släpps electropellers av monster?",a="Nej. De kan inte plundras från fiender eller hittas i behållare på marken. De måste hämtas upp ur floderna med ett fiskespö.",al={"släpper fiender electropellers","vem släpper electropellers"}}},fx={["42aa198c"]={q="Varför vill Wizbang Cranktoggle att du hämtar electropellers?",a="Wizbang tappade hela sin väska med komponenter under ett berusat äventyr där han testade uppfinningar längs Darkshores vattenvägar. Han vaknade upp i Auberdine med svedda hårtestar och en tom packning. Utan de saknade delarna står hans pågående ingenjörsforskning om självgående, exploderande andbeten helt stilla.",al={"varför behöver wizbang electropellers","wizbangs motiv","varför hämta electropellers"}},c9029636={q="Vad används en Electropeller till?",a="Electropellers är särskilda mekaniska komponenter som Wizbang konstruerade för framdrivning. Mer specifikt utgör de drivmekanismen i hans prototyp till ett självgående, exploderande andbete. De låter betet styra och ta sig fram genom vatten innan dess flyktiga laddning detonerar.",al={"vad är electropellers","electropeller användning","electropeller syfte"}},d23bdc75={q="Varför ber Wizbang dig att fiska upp electropellers i stället för att göra det själv?",a="Wizbang har redan sett bevis på din ofattbara tur och fiskeskicklighet när du tidigare fiskade upp gafferjacks åt honom. Efter att ha vaknat omtöcknad och svedd i Auberdine efter sitt berusade missöde föredrar han att förlita sig på en beprövad fiskare i stället för att själv söka igenom Darkshores vildmarker.",al={"varför jag wizbang","varför fiskar inte wizbang upp dem"}}},fp="14,177,17.379.0,19.321.0,35.165.0,27.199.0,33.192.0,44.109.0,29.121.0,39.119.0"}
P.entries["quest:1581"] = {n="Elixirs for the Bladeleafs",s="I Dolanaars trädkronor söker Syral Bladeleaf en alkemist som kan fylla på familjens växande handel. Hennes make tillbringar ändlösa timmar vid brygdgrytorna, och Syral hoppas att en omgång färska elixir ska lätta hans arbetsbörda och ge bidragsgivaren ett knippe sällsynta örter.",h="I Dolanaars trädkronor söker Syral Bladeleaf en alkemist som kan fylla på familjens växande handel.",kw={"alkemi","dolanaar","earthroot","elixir of lion's strength","elixir of minor defense","elixirs for the bladeleafs","silverleaf","syral bladeleaf","teldrassil"},ang={["faction:Alliance"]="Om Dolanaar har gott om läkande och skyddande brygder är försvarare och resande bundsförvanter redo för hoten i skogen.",["profession:Herbalism"]="Teldrassils bördiga jord myllrar av Silverleaf och Earthroot, så det är enkelt att samla in de råörter som behövs för att uppfylla butikens beställning.",["race:NightElf"]="Att stödja lokala hantverkare som familjen Bladeleaf hjälper den unga bosättningen Dolanaar att växa under Teldrassils trädkronor."},sec={{t="Välståndets börda",b="Bosättningen Dolanaar är en viktig knutpunkt för resenärer, väktare och druider som färdas genom Teldrassils trädkronor. Med så många vandrare på genomresa har örthandeln och alkemin som Syral Bladeleaf och hennes make driver blomstrat. Men den stora efterfrågan har sitt pris. Hennes make tillbringar nästan all sin tid böjd över flaskor och grytor för att hålla hyllorna fyllda, så att paret knappt får någon tid tillsammans."},{t="En handelsmans utbyte",b="I stället för att låta sin partner bränna ut sig under orderberget vänder sig Syral till förbipasserande örtkunniga och bryggare. Genom att beställa färdigblandade brygder, särskilt Elixirs of Lion's Strength och Minor Defense, fyller hon på butikens lager och erbjuder nyskördade, ovanliga örter i utbyte. För en nybörjaralkemist som övar sitt hantverk under det stora trädet är det ett idealiskt tillfälle att förvandla vanliga skogsväxter till eftertraktade örter från trakten."}},faq={{q="Varför behöver Syral Bladeleaf dessa brygder?",a="Familjens ört- och alkemibutik i Dolanaar har blivit mycket välbesökt. Hennes make ägnar all sin tid åt att brygga drycker för att möta efterfrågan, så de får ingen tid för varandra. Genom att lägga ut arbetet får han en välbehövlig paus.",al={"varför behövs elixir","syral bladeleafs motiv","problem med bladeleafs butik"}},{q="Vilka brygder krävs för uppdraget?",a="Syral ber om sex Elixirs of Lion's Strength och två Elixirs of Minor Defense. Båda är vanliga brygder som äventyrare och lokala väktare i Teldrassil ofta köper.",al={"vilka elixir","vad behöver jag brygga","drycker som behövs"}},{q="Vilka örter behövs för att brygga elixiren?",a="För att brygga den efterfrågade omgången behövs Silverleaf och Earthroot, som båda växer rikligt på skogsmarken i Teldrassil, samt vanliga Crystal Vials.",al={"ingredienser som behövs","material till elixir","vilka örter ska jag plocka"}},{q="Vem kan ta sig an den här begäran?",a="Endast alkemister som har uppnått grundläggande färdighet i yrket erbjuds uppdraget. Syral vill ha pålitliga, välblandade läkemedel till sin butik, inte amatörbrygder.",al={"nivåkrav","yrkeskrav","kan vem som helst göra uppdraget"}},{q="Vad erbjuder Syral i utbyte mot elixiren?",a="Syral belönar hjälpsamma alkemister med ett knippe nyskördade, ovanliga örter som är svåra att hitta när man bara strövar längs Teldrassils skogsstigar.",al={"belöningsberättelse","vad ger syral","bladeleafs handelsbelöning"}},{q="Var finns Syral Bladeleaf?",a="Hon finns utanför den norra byggnaden i Dolanaar, nära huvudvägen som löper genom skogsbyn.",al={"var finns syral","bladeleafs plats","var lämnar jag in det här"}}},fx={c3ad307f={q="Vad används Elixir of Lion's Strength till?",a="Elixir of Lion's Strength är en vanlig brygd bland frontkrigare och alkemister, framställd för att tillfälligt öka den fysiska styrkan hos den som dricker den. Syral Bladeleaf har den i lager i Dolanaar för att möta den ständiga efterfrågan från jägare, väktare och resenärer som förbereder sig på Teldrassils farliga vildmarker.",al={"elixir of lion's strength användning","varför lion's strength-elixir","elixir of lion's strength syfte"}},["34301f2f"]={q="Vad används Elixir of Minor Defense till?",a="Elixir of Minor Defense är en alkemisk brygd som ska göra huden hårdare och stärka det naturliga pansaret mot fysiska slag. Syral Bladeleaf har den i sin butik för att sälja till beskyddare och äventyrare som behöver ett pålitligt grundskydd när de patrullerar det stora trädets grenar.",al={"elixir of minor defense användning","varför minor defense-elixir","elixir of minor defense syfte"}}},fp="26,213,22.291.0,19.362.0,44.197.0,39.147.0,51.136.0,31.131.0,50.123.0,33.111.0"}
P.entries["quest:1582"] = {n="Moonglow Vest",s="Moonglow Vest är en yrkesuppgift från nattalven Lotherias, läderarbetare i Darnassus. Hon överväldigas av de ständiga behoven hos unga äventyrare som ger sig ut i Kalimdors vildmark. I utbyte mot stora leveranser av präglad läderutrustning delar hon med sig av kunskapen om ett särskilt mönster för nattalvernas tunikor.",h="Moonglow Vest är en yrkesuppgift från nattalven Lotherias, läderarbetare i Darnassus.",kw={"hantverk","darnassus","präglat läder","kaldorei","läderarbete","lotherias","moonglow vest","teldrassil"},ang={["faction:Alliance"]="Att utrusta nya rekryter i Darnassus hjälper Alliansen att behålla sitt bräckliga grepp om norra Kalimdor medan hoten från vildmarken och fienderna växer.",["race:NightElf"]="Moonglow Vest står för det eleganta hantverk som är typiskt för Teldrassils hantverkare och ger spejare och väktare smidigt skydd under skogens tak."},sec={{t="Utrustning åt Kaldorei",b="I Darnassus skyddande trädkronor arbetar hantverkarna outtröttligt för att utrusta allt fler väktare och blivande vildmarksspejare. Unga nattalver och allierade vandrare ger sig bortom Teldrassil ut i ett oroligt Kalimdor, där efterfrågan på pålitligt pansar är stor. Mästerliga läderarbetare som Lotherias bär ansvaret för att hålla dessa gränstrakter försedda med slitstarkt läder."},{t="Bemästra hantverket",b="För att försäkra sig om att hennes lärlingar har både uthållighet och teknisk precision kräver Lotherias bevis på deras hantverk i form av flera matchande plagg: präglade handskar, stövlar och kappor. När de uppfyller kvoten vinner de hennes förtroende, och då lär hon ut det särpräglade nattalvsmönstret för Moonglow Vest, ett plagg uppskattat för sin balans mellan smidigt skydd och rörlighet."}},faq={{q="Vem är Lotherias?",a="Lotherias är en skicklig nattalv och läderarbeteslärare i Darnassus. Hon ansvarar för hantverksutbildning för Alliansens hantverkare och erbjuder avancerade mönster till läderarbetare som visar sin hängivenhet.",al={"lotherias darnassus","vem ger moonglow vest"}},{q="Varför behöver Lotherias så många läderplagg?",a="Darnassus myllrar av nyutbildade äventyrare som förbereder sig på att ge sig ut i världen. Hantverkarna har svårt att möta den ständiga efterfrågan på utrustning för fältbruk, så Lotherias låter kapabla lärlingar tillverka vanliga präglade plagg.",al={"varför behövs så många stövlar","varför tillverka präglat läder"}},{q="Vad är Moonglow Vest?",a="Moonglow Vest är en avancerad del läderrustning. Lotherias lär ut mönstret som belöning när du visar att du kan tillverka präglade varor av hög kvalitet i stora mängder.",al={"moonglow vest mönster","vad får jag"}},{q="Vilka material krävs för att slutföra uppgiften?",a="Du måste lämna in ett par Embossed Leather Gloves, fem par Embossed Leather Boots och fem Embossed Leather Cloaks. Alla delar måste vara tillverkade och lämnas direkt till Lotherias.",al={"vad behöver jag","moonglow vest föremål"}},{q="Kan läderarbetare från Horde lära sig mönstret här?",a="Nej. Lotherias bor i Darnassus och utbildar enbart hantverkare från Alliansen. Hantverkare från Horde måste söka upp sina egna lärare i Kalimdor och Eastern Kingdoms för att utveckla sitt yrke.",al={"kan horde göra detta","är moonglow vest bara för alliansen"}},{q="Kräver uppgiften en viss yrkesnivå?",a="Ja, en hantverkare måste ha minst 70 i läderarbete innan Lotherias anser att de är skickliga nog att ta sig an beställningen och lära sig mönstret till västen.",al={"läderarbetesnivå som krävs","när kan jag få moonglow vest"}}},fx={["304f0e76"]={q="Vad används Embossed Leather Gloves till?",a="Lotherias och de andra hantverkarna i Darnassus är överhopade med att utrusta den ström av unga äventyrare som beger sig ut i vildmarken. Hon ber dig tillverka ett par Embossed Leather Gloves för att hjälpa till att beta av hennes överfulla order. Det prövar din förmåga att arbeta med fina detaljer innan hon delar avancerade tekniker med dig.",al={"varför embossed leather gloves","embossed leather gloves användning","lotherias handskar"}},["3d684782"]={q="Vad används Embossed Leather Boots till?",a="Lotherias behöver fem par Embossed Leather Boots för att utrusta lokala äventyrare som förbereder sig för farliga expeditioner över Kalimdor. Genom att leverera rejäla, pålitliga skor i större mängder visar du att du är en jämn läderarbetare och avlastar de hårt arbetande hantverksverkstäderna i Darnassus.",al={"varför embossed leather boots","embossed leather boots användning","lotherias stövlar"}},["83a79481"]={q="Vad används Embossed Leather Cloak till?",a="De fem Embossed Leather Cloaks ska utrusta nya äventyrare som trotsar vädret i Teldrassil och längre bort. Lotherias överöses av beställningar på förnödenheter, och när du tillverkar de här slitstarka mantlarna visar du att du har både uthålligheten och den tekniska skicklighet som krävs för avancerad utbildning i läderarbete.",al={"varför embossed leather cloak","embossed leather cloaks användning","lotherias mantlar"}}},fp="13,187,22.252.0,19.254.0,17.153.0,46.157.0,26.120.0,50.173.0,49.154.0,53.146.0"}
P.entries["quest:159"] = {n="Juice Delivery",s="Juice Delivery är ett ärende mellan Darkshire och den västra utkanten av Duskwood. Tavernkeep Smitts anförtror dig en kraftig brygd som kallas Zombie Juice, att leverera till en tillbakadragen eremit vid namn Abercrombie. Den sägs hålla den skakande gamle mannen varm, men brygdens kusliga styrka väcker misstankar.",h="Juice Delivery är ett ärende mellan Darkshire och den västra utkanten av Duskwood.",kw={"abercrombie","darkshire","duskwood","juice delivery","scarlet raven","tavernkeep smitts","zombie juice"},ang={["faction:Alliance"]="Darkshires invånare förlitar sig på modiga kurirer från Alliansen som färdas längs Duskwoods farofyllda vägar, men det kan leda till oväntade problem att lita på varje eremit i skogen.",["profession:Cooking"]="Tavernkeep Smitts recept på Zombie Juice bygger till stor del på skarpa och ovanliga ingredienser och tänjer på gränsen för vad som kan kallas en krogdryck."},sec={{t="En tvivelaktig brygd",b="Tavernkeep Smitts i Darkshire brygger en legendarisk dryck som i folkmun kallas Zombie Juice. När beställningen till slut är klar räcker Smitts över flaskan med en sträng varning om att hantera den varsamt och säger att brygden är stark nog att väcka de döda. För en trött äventyrare som springer ärenden genom en hemsökt skog känns det som vanlig välgörenhet att leverera starkt månsken till en excentrisk ensamvarg."},{t="Eremitens felsägning",b="Med den oberäkneliga brygden i släptåg går färden västerut, förbi ylande worgen och rastlösa döda, till Abercrombies stuga vid skogsbrynet. När den skröplige enstöringen får flaskan säger han att han bara behöver spriten för att värma sina värkande ben under Duskwoods iskalla, dimmiga nätter. Men när han tar emot den hinner han nästan tacka resenären för dennes ”dårskap” innan han snabbt rättar sig och berömmer dennes ”vänlighet” – en kort felsägning som antyder att det jäser betydligt mer i eremitens sinne än en enkel kvällsdrink."}},faq={{q="Vad är Zombie Juice?",a="Zombie Juice är en extremt stark brygd som Tavernkeep Smitts tillverkar på Scarlet Raven Tavern i Darkshire. Den ses som en stark alkoholdryck, men Smitts påpekar att brygden är kraftig nog att väcka de döda och därmed betydligt mer oberäknelig än vanlig sprit.",al={"zombie juice berättelse","vad är smitts juice","abercrombies dryck"}},{q="Vem beställer Zombie Juice?",a="Beställningen kommer från Abercrombie, en excentrisk gammal eremit som bor i en enslig stuga nära Duskwoods västra gräns.",al={"vem vill ha juicen","vem är juice delivery till"}},{q="Varför vill Abercrombie ha drycken?",a="Abercrombie säger att han behöver drycken för att hålla sig varm under de iskalla, fuktiga nätterna i Duskwood. Men hans felsägning när han får flaskan antyder att han har betydligt ondskefullare planer för brygden.",al={"varför behöver abercrombie juice","abercrombie frusen"}},{q="Vem brygger Zombie Juice?",a="Tavernkeep Smitts, som driver Scarlet Raven Tavern mitt i Darkshire, brygger drycken själv när han fått de nödvändiga skarpa ingredienserna.",al={"vem gör zombie juice","smitts krogvärd"}},{q="Var ligger Abercrombies stuga?",a="Abercrombies stuga ligger avsides i västra Duskwood, strax norr om Raven Hill Cemetery.",al={"abercrombies plats","var ligger abercrombies stuga"}},{q="Vad gör Abercrombie efter att ha fått juicen?",a="När Abercrombie väl har fått tag på Zombie Juice fortsätter han att utnyttja godtrogna resenärer. Han skickar dem till Raven Hill Cemetery för att samla ghoulrevben till en makaber avbild som enligt honom ska hålla de odöda borta.",al={"nästa uppdrag efter juice delivery","vad händer sedan"}}},fx={["9f2016f2"]={q="Varför vill Tavernkeep Smitts att juicen levereras?",a="Smitts driver Scarlet Raven Tavern i Darkshire och har fullgjort sin del av uppgörelsen genom att brygga den kraftfulla blandning som Abercrombie bad om. Drycken är buteljerad och klar, så hans enda intresse är att den utlovade beställningen blir uppfylld och lämnar hans händer. På vägen varnar han dig för att hantera den flyktiga drycken varsamt.",al={"varför vill smitts att det här görs","tavernkeep smitts motiv","varför leverera zombie juice"}},["6bab1f80"]={q="Varför låter Smitts en äventyrare leverera juicen i stället för att göra det själv?",a="Tavernkeep Smitts måste sköta baren på Scarlet Raven Tavern, och det är alldeles för farligt för en vanlig värdshusvärd att ge sig ut på Duskwoods skuggiga vägar. Abercrombies eremitage ligger på andra sidan de skuggiga skogarna nära Raven Hill, ett område fullt av odöda och vilddjur som bara en beväpnad resenär tryggt kan ta sig igenom.",al={"varför jag smitts","varför kan inte smitts leverera juicen","varför går inte värdshusvärden"}}},fp="14,278,20.329.0,17.437.1,21.189.0,28.117.0,36.188.0,27.164.0,29.93.0,56.201.0"}
P.entries["quest:1598"] = {n="The Stolen Tome",s="I Northshire Valley skickas en mänsklig novis i häxkonst för att återta en förbjuden bok och visa sin skicklighet. Drusilla La Salle hoppas få tag på Powers of the Void från Defias, vars läger ligger i vingårdarna.",h="I Northshire Valley skickas en mänsklig novis i häxkonst för att återta en förbjuden bok och visa sin...",kw={"defias brotherhood","drusilla la salle","northshire abbey","novistjuv","powers of the void","stulen bok","vingårdar","häxmästarens imp"},ang={["class:Warlock"]="Som häxmästare bevisar du att du kan ta dig över farlig mark utan att tveka. När du säkrar boken får du ritualerna som låter dig åkalla din första imp.",["faction:Alliance"]="Som medlem i Alliansen måste du röra dig försiktigt bland Northshires paladiner och präster och utnyttja laglösas misstag för att få tag på förbjuden ockult kunskap.",["race:Human"]="Som människa ser du hur långt Defias Brotherhood når i Northshire, där till och med klostrets studenter stjäl heliga texter och ansluter sig till upproret."},sec={{t="En förbjuden möjlighet",b="Häxmästare i Stormwinds länder döljer sin konst och håller nyfikna blickar borta från sin forskning. Northshire Abbey vaktar förbjudna svartkonstböcker i sina arkiv. Drusilla La Salle, häxkonstläraren på klostrets område, åtrår Powers of the Void men kan inte riskera att väcka misstankar hos prästerna och paladinerna genom att själv gå in i bibliotekets skyddade del."},{t="Defias chansar",b="En novis från klostret ansluter sig till Defias Brotherhood och stjäl flera värdefulla texter på vägen ut. Han flyr till Northshire Vineyards och söker skydd kring Defias läger. Tjuvarna gömmer sitt byte i ett fälttält, ovetande om faran i bokens mörka konster."},{t="Den första bindningen",b="Att återta boken prövar en novis häxmästares mod och öppnar vägen till mörkare kunskap. Att trotsa banditlägret och återvända med texten uppfyller Drusillas ambition och bevisar att lärjungen är redo. Hon belönar lärjungen med de mörka ritualerna för att åkalla och binda en imp, den första demon en lärling lär sig att befalla."}},faq={{q="Vad är Powers of the Void?",a="Powers of the Void är en förbjuden svartkonstbok om mörk magi och kontroll över planen. Den förvaras i en bevakad del av biblioteket i Northshire Abbey och innehåller kunskap som Drusilla La Salle åtrår för sin forskning och undervisning.",al={"boken powers of the void","vad är boken","vad stal novisen"}},{q="Varför stal inte Drusilla La Salle boken själv?",a="Drusilla La Salle måste skydda sin ställning i Northshire Abbey. Om hon gick in i bibliotekets låsta arkiv skulle prästerna få veta det. När en novis stal boken och anslöt sig till Defias fick hon chansen att skaffa den utan att dra uppmärksamhet till sig, genom en lärling.",al={"varför stal inte drusilla den","varför skickas jag"}},{q="Var göms den stulna boken?",a="Defias gömde boken i ett tält vid sitt läger i Northshire Vineyards, öster om klostret.",al={"var finns boken","bokens plats","stulen bok i tält"}},{q="Varför anslöt sig en novis från Northshire till Defias Brotherhood?",a="Missnöje och stridigheter i riket driver arbetare, bönder och kyrkans studenter att ansluta sig till Defias Brotherhood. Novisen övergav sina löften, stal flera viktiga böcker från biblioteket och flydde sedan till banditerna i vingården.",al={"varför novisen gick med i defias","förrädare från klostret i defias","vem stal boken"}},{q="Vilken belöning får en häxmästare för att återta boken?",a="När lärjungen återlämnar boken visar det att hen har modet och uthålligheten som krävs för att utöva de mörka konsterna. Drusilla belönar lärlingen med undervisning i hur man åkallar en imp, den första demonen hen får befalla.",al={"vad lär man sig","belöning för häxmästaruppdrag","varför göra uppdraget"}},{q="Vet Defias hur man använder boken?",a="Banditerna betraktar de stulna böckerna som värdefullt byte från klostret. Defias anlitar visserligen avfälliga magiker, men novisen och hans kamrater stoppade boken i en tältkista i stället för att bemästra dess mörka hemligheter.",al={"kan defias använda boken","vad gör defias med boken"}}},fx={["1f0061ae"]={q="Varför vill Drusilla La Salle ha Powers of the Void?",a="Drusilla har länge trånat efter den förbjudna kunskap som finns låst i Powers of the Void, men den förvarades i en bevakad och skyddad del av Northshire Abbeys bibliotek, dit hon inte kunde ta sig utan att väcka misstankar. När en novis på avvägar stal den fick hon det perfekta tillfället att äntligen lägga beslag på dess mörka hemligheter, samtidigt som hon prövar om du har styrkan att studera häxmästarens konster.",al={"varför vill drusilla ha boken","drusilla la salles motiv","varför stjäla skriftrullen"}},a46315b9={q="Vem skickas du mot för att återta skriftrullen?",a="Du skickas mot banditerna i Defias Brotherhood som slagit läger i Northshire Vineyards. En novis från klostret stal flera värdefulla böcker ur det skyddade biblioteket innan han flydde för att ansluta sig till deras uppror. Han gömde skriftrullen bland deras tält.",al={"vem tog boken","defias i vingårdarna","vem stal powers of the void"}}},fp="15,206,23.341.0,18.270.0,17.315.0,31.215.0,52.243.0,32.99.0,56.231.0,55.179.0,39.219.0"}
P.entries["quest:1599"] = {n="Beginnings",s="Beginnings är en övergångsrit för blivande trollkarlar i Alliansen som börjar i Dun Morogh. Under Alamar Grimms motvilliga ledning skickas noviser ut för att samla magiska fjäderamuletter från närliggande Frostmane-noviser och bevisa sin förmåga innan de får lära sig att frammana en imp.",h="Beginnings är en övergångsrit för blivande trollkarlar i Alliansen som börjar i Dun Morogh.",kw={"alamar grimm","anvilmar","beginnings","coldridge valley","dun morogh","feather charm","frostmane-novis","imp"},ang={["class:Warlock"]="Det här uppdraget markerar det avgörande första steget på en trollkarls resa i Alliansen genom Dun Morogh och låser upp förmågan att frammana din första demoniska tjänare.",["race:Gnome"]="Gnomtrollkarlar som lär sig sitt hantverk i Coldridge Valley måste bevisa sin intelligens och magiska dominans genom att överlista de lokala Frostmane-trollen."},sec={{t="En motvillig mentor",b="I Anvilmars trygga famn firas inte mörk magi öppet, men den tolereras av nödtvång. Alamar Grimm, en etablerad trollkarl, bedriver sin ockulta forskning relativt diskret. När nya utövare visar rå talang ber namnlösa personer, som har fattat intresse för rekryten, Grimm att lägga studierna åt sidan och själv bedöma rekryten."},{t="Den mörka magins gnista",b="Innan Grimm avslöjar hemligheterna bakom att kuva mindre demoner kräver han praktiska bevis på både fysisk uthållighet och magisk fallenhet. Närliggande Frostmane-noviser, som samlas i en grotta sydväst om Anvilmar, bär primitiva fjäderamuletter som genomsyras av subtil urmagisk kraft. Genom att samla in amuletterna bevisar den blivande trollkarlen att hen kan besegra en magisk motståndare, samtidigt som Grimm får intressanta föremål till sin pågående forskning."},{t="Frammaning av imp",b="När novisen återvänder med amuletterna är Grimm övertygad om att hen har tillräcklig viljestyrka för att överleva. Provet avslutas med att han lär ut hur man frammana en imp, trollkarlens mest grundläggande tjänare. Grimm ger en sträng varning tillsammans med ritualen: trots sin ringa storlek behärskar imps kaotisk eldmagik som lätt kan övermanna en odisciplinerad mästare."}},faq={{q="Vem ger uppdraget Beginnings?",a="Alamar Grimm ger uppdraget. Han är en tränare för trollkarlar i Anvilmar i Coldridge Valley, Dun Morogh.",al={"vem inleder beginnings","uppdragsgivare för beginnings","alamar grimms plats"}},{q="Vad används fjäderamuletterna till?",a="Fjäderamuletterna har två syften: de bevisar att en blivande trollkarl kan möta och besegra magiskt skickliga fiender, och de ger Alamar Grimm märkliga, förtrollade trollprydnader att undersöka i sin forskning.",al={"varför fjäderamuletter","fjäderamulettens syfte","frostmane-amuletter"}},{q="Var finns Frostmane-noviserna?",a="De håller till i en grotta sydväst om Anvilmar i Coldridge Valley, där Frostmane-trollen har etablerat sig.",al={"var finns trollnoviserna","frostmane-grottans plats","frostmane-novisernas plats"}},{q="Vilken belöning får en trollkarl när uppgiften är slutförd?",a="När uppgiften är slutförd får du Alamar Grimms godkännande och kunskapen som krävs för att frammana en imp, en trollkarls första demoniska följeslagare.",al={"vad lär beginnings ut","belöning för beginnings","impbesvärjningens uppdrag"}},{q="Varför lär Alamar Grimm upp nya trollkarlar?",a="Grimm nämner att inflytelserika personer har fattat intresse för den blivande trollkarlen, vilket får honom att göra ett uppehåll i sina privata ockulta studier för att pröva och vägleda rekryten.",al={"varför tränar alamar mig","vem bad alamar träna mig"}},{q="Är en imp farlig för en novis till trollkarl?",a="Ja. Alamar Grimm varnar uttryckligen för att en imp är oberäknelig på grund av sin fel-eld och slughet, trots sin ringa storlek. En oerfaren besvärjare kan lätt bli övermannad av en imp.",al={"impfara","kan imps döda dig","impvarningar"}}},fx={["5dfeed0e"]={q="Varför vill Alamar Grimm att det här ska göras?",a="Alamar Grimm övertalades att lägga sin egen forskning åt sidan och träna dig eftersom framstående beskyddare hade fått upp ögonen för din potential. Innan han lär dig att frammana din första demon, en imp, kräver han bevis på att du har den magiska styrkan och fysiska tåligheten att överleva det. Att återta fjäderamuletterna stillar också hans nyfikenhet och ger honom trollmagi att studera.",al={"alamar grimms motiv","varför fjäderamuletter","varför vill alamar ha fjäderamuletter"}},f653bf22={q="Vilka är Frostmane-noviserna som du skickas mot?",a="Frostmane-noviserna är unga istroll som övar på enkel magi i en grotta sydväst om Anvilmar. Den inhemska Frostmane-stammen ligger i konflikt med dvärgarna i Ironforge över hela Dun Morogh. De använder grottorna i närheten för att samla sig och träna sina nyblivna besvärjare.",al={"frostmane-noviser dun morogh","vilka är frostmane-noviserna","trollnoviser i grotta"}}},fp="10,180,18.330.0,23.429.0,17.264.0,31.102.0,37.192.0,40.139.0,58.110.0,42.147.0,42.149.0"}
P.entries["quest:16"] = {n="Give Gerard a Drink",s="På The Maclure Vineyards arbetar Gerard Tiller långa dagar på fälten och behöver friskt källvatten. Han byter äpplen mot vatten som förbipasserande resenärer tar med sig.",h="På The Maclure Vineyards arbetar Gerard Tiller långa dagar på fälten och behöver friskt källvatten.",kw={"äpplen","byteshandel","elwynn forest","gerard tiller","the maclure vineyards","refreshing spring water"},ang={["faction:Alliance"]="När du hjälper Elwynns jordbrukare på platser som The Maclure Vineyards bidrar du till att försörja skogarnas gårdar och garnisoner medan kungariket försvarar sig.",["race:Human"]="Som människa med start i Northshire visar du den gemenskap som håller Elwynn samman när du hjälper grannar som Gerard Tiller."},sec={{t="Törstigt arbete i vingårdens fält",b="Elwynn Forests gårdar förser Stormwinds invånare och garnisoner med spannmål, frukt och grönsaker. Att sköta grödorna under bar himmel är hett och krävande arbete. Gerard Tiller tillbringar långa dagar i jorden på The Maclure Vineyards, där han håller skadedjur borta och sköter skörden. Eftersom han sällan hinner tillbaka till stadens brunnar förlitar han sig på förbipasserande rekryter som tar med rent källvatten så att han kan fortsätta arbeta."},{t="Byteshandelns villkor",b="Gerard byter till sig förnödenheter i stället för mynt. Resenärer med extra flaskor Refreshing Spring Water kan byta dem mot färska äpplen från fruktträdgården. Kungariket tänjer på sina resurser för att upprätthålla ordningen och försörja sin armé, så direkt byteshandel mellan småbrukare och rekryter är fortfarande ett praktiskt sätt att klara sig på landsbygden i Elwynn."}},faq={{q="Vem är Gerard Tiller?",a="Gerard Tiller är en jordbrukare på The Maclure Vineyards i södra Elwynn Forest. Han sköter fälten och fruktträdgårdarna som försörjer traktens invånare.",al={"gerard tiller","vem är tiller","gerard"}},{q="Varför behöver Gerard vatten?",a="Det är utmattande att arbeta hela dagen ute på fälten under solen. Gerard förlitar sig på förbipasserande resenärer för att få färskt källvatten, så att han kan hålla sig hydrerad utan att lämna sina sysslor.",al={"varför källvatten","gerard törstig","varför behöver han dryck"}},{q="Var hittar man Refreshing Spring Water?",a="Försäljare av mat och dryck samt värdshusvärdar runt om i Elwynn Forest säljer ofta Refreshing Spring Water. Brother Danil säljer det inne i Northshire Abbey.",al={"var hittar man vatten","källa till källvatten","hur får man vatten"}},{q="Kan man upprepa bytet?",a="Ja. Gerard fortsätter att arbeta på fälten och byter gärna fler färska äpplen från fruktträdgården mot vattenflaskor du kan avvara.",al={"upprepningsbart uppdrag","kan jag göra detta igen","lämna in mer vatten"}},{q="Vad erbjuder Gerard i utbyte mot drycken?",a="Gerard byter till sig färskt vatten mot ett Shiny Red Apple.",al={"gerards belöning","vad får jag","bytesbelöning"}},{q="Var finns Gerard?",a="Gerard är utanför ladan på The Maclure Vineyards i södra Elwynn Forest.",al={"gerard tillers plats","var finns gerard","var ligger gården"}}},fx={d51fec31={q="Vad används Refreshing Spring Water till?",a="Arbetet på fälten vid The Maclure Vineyards är utmattande, och Gerard Tiller behöver helt enkelt en stadig tillgång till friskt, rent vatten för att släcka törsten medan han arbetar i solen. I stället för att lämna grödorna utan tillsyn för att hämta något att dricka byter han gärna till sig vatten av förbipasserande resenärer som har lite över.",al={"refreshing spring water användning","varför källvatten","gerard källvatten"}}},fp="19,156,35.392.0,21.324.0,21.139.0,27.168.0,43.149.0,25.113.0,47.48.0,24.78.0"}
P.entries["quest:160"] = {n="Note to the Mayor",s="Note to the Mayor är ett uppdrag för Alliansen i Duskwood som knyter den excentriske eremiten Abercrombie till ledningen i Darkshire. När du har hjälpt den tillbakadragne gamle mannen får äventyrare i uppdrag att personligen överlämna ett meddelande till borgmästaren Lord Ello Ebonlocke. Brevet väcker dock genast misstankar i stället för värme.",h="Note to the Mayor är ett uppdrag för Alliansen i Duskwood som knyter den excentriske eremiten Abercrombie...",kw={"abercrombie","darkshire","duskwood","ello ebonlocke","brev","borgmästare","note to the mayor"},ang={["faction:Alliance"]="Darkshires överlevnad beror på att märkliga störningar reds ut innan de bryter igenom Night Watchs bevakningslinje, vilket gör det misstänkta brevet till ett omedelbart säkerhetshot för Alliansens agenter.",["race:Human"]="Mänskliga kurirer i Night Watchs och House of Ebonlockes tjänst inser snabbt att den märklige gamle eremiten i utkanten av Duskwood har lurat dem."},sec={{t="Ett vänligt meddelande?",b="När du har hjälpt Abercrombie att återta sin stulna kista från ogres vid Vul'Gol Ogre Mound skickar eremiten dig tillbaka längs de dimhöljda vägarna mot staden. Abercrombie skrattar förtjust och påstår att han och borgmästaren Lord Ello Ebonlocke är gamla vänner. Han insisterar på att borgmästaren kommer att bli lika glad som han när han får veta vad du har åstadkommit."},{t="En förbryllad ledare",b="När du kommer fram till stadshuset i Darkshire visar sig verkligheten motsäga Abercrombies påståenden. Lord Ello Ebonlocke minns inte någon vid namn Abercrombie. När han vecklar upp pergamentet blir mysteriet bara större: i stället för en innerlig hälsning mellan gamla vänner är texten skriven med ett uråldrigt, oläsligt skriftspråk som gör borgmästaren i Darkshire fullständigt förbryllad."}},faq={{q="Vem skickar Note to the Mayor?",a="Abercrombie, en excentrisk eremit som bor ensam i en koja vid Duskwoods västra utkant, ger dig brevet när du har återtagit hans stulna ägodelar från de lokala ogres.",al={"vem ger borgmästaren brevet","vem startar note to the mayor","abercrombie brevets avsändare"}},{q="Är Abercrombie och borgmästare Ebonlocke verkligen vänner?",a="Nej. Abercrombie påstår att de är gamla bekanta, men borgmästaren Lord Ello Ebonlocke har aldrig hört talas om honom och blir fullständigt förbryllad när han får meddelandet.",al={"känner de varandra","är abercrombie vän med borgmästaren","abercrombie och ello ebonlockes relation"}},{q="Vad står det i brevet?",a="Brevet är skrivet på ett uråldrigt, svårbegripligt språk som varken kuriren eller borgmästare Ebonlocke kan tyda, så borgmästaren ber någon utomstående om hjälp med översättningen.",al={"vad står det i abercrombies brev","kan ello läsa brevet","vilket språk är brevet skrivet på"}},{q="Var finns Lord Ello Ebonlocke?",a="Borgmästaren Lord Ello Ebonlocke finns inne i Darkshire Town Hall, på stadens östra sida längs huvudvägen i Duskwood.",al={"var är borgmästaren","ello ebonlockes plats","var lämnar jag in note to the mayor"}},{q="Vad händer när borgmästare Ebonlocke får brevet?",a="Eftersom Lord Ebonlocke inte kan läsa den mystiska skriften ber han dig hitta någon som kan tolka texten. Det leder till uppdraget Translate Abercrombie's Note.",al={"vad kommer efter note to the mayor","vad följer efter note to the mayor"}},{q="Varför skrattade Abercrombie när han gav dig brevet?",a="Abercrombies glada skratt antyder att hans avsikter är betydligt mörkare än en enkel återförening med en gammal bekant och förebådar olycksbådande problem för Darkshire.",al={"varför skrattar abercrombie","är abercrombie ond","abercrombie skratt brev"}}},fx={["7816d016"]={q="Varför skickar Abercrombie dig med brevet i stället för att lämna det själv?",a="Abercrombie lever som en bräcklig, ensam eremit, avskild i de hemsökta skogarna långt väster om Darkshire. Genom att låta en intet ont anande resenär som just hjälpt honom bära hans meddelande kan han leverera sin illavarslande överraskning direkt till rådhuset utan att själv sätta sin fot nära Darkshires misstänksamma Night Watch eller dess stadsråd.",al={"varför skicka mig med note to the mayor","varför lämnar abercrombie inte brevet själv","varför använda spelaren för att leverera brevet"}}},fp="17,202,19.315.0,18.183.1,32.151.0,53.129.0,28.141.0,37.118.0,55.147.0,57.163.1"}
P.entries["quest:161"] = {n="A Dark Threat Looms",s="Chief Engineer Hinderweir VII misstänker sabotage vid Stonewrought Dam och skickar en kurir norrut genom de farliga Wetlands för att få ett prov av det flyktiga pulvret undersökt. Kuriren måste ta sig längs den förrädiska landsvägen förbi Algaz Gate och lämna provet till sprängämnesexperten Ashlan Stonesmirk i Dun Modr.",h="Chief Engineer Hinderweir VII misstänker sabotage vid Stonewrought Dam och skickar en kurir norrut genom de...",kw={"ashlan stonesmirk","ett mörkt hot tornar upp sig","dun modr","explosivt pulver","hinderweir","stonewrought dam","thandol span","wetlands"},ang={["faction:Alliance"]="Landsvägen genom Loch Modan och Wetlands är en viktig militär livlina mellan Ironforge och Alliansens nordliga besittningar på andra sidan Thandol Span.",["profession:Engineering"]="För att identifiera rester av högkvalitativa sprängämnen krävs en sprängares tränade öga. Även ett alldagligt pulver kan avslöja hur tekniskt sofistikerad en fiendesabotör är.",["race:Dwarf"]="Stonewrought Dam är ett av Bronzebeard-ingenjörskonstens främsta mästerverk. Varje tecken på en plan att krossa dess murverk hotar hela Khaz Modans stolthet och säkerhet."},sec={{t="Ett pulver med onda avsikter",b="Efter oroligheter kring Stonewrought Dam får Chief Engineer Hinderweir VII ett märkligt luktande pulver från en misstänkt tunna nära dammens östra ramp, där han hade sett Dark Iron-sprängare. Hinderweir inser att det kan röra sig om katastrofalt sabotage och misstänker att ämnet är ett förädlat sprängämne avsett att krossa dvärgarnas murverk. Eftersom det saknas specialutrustning för kemiska tester vid dammen vill han rådfråga en militär sprängämnesexpert innan han drar några slutsatser."},{t="Vägen norrut",b="Den brådskande analysen kräver en färd genom Algaz Gate och ner i Wetlands blöta lågland. Träsken kryllar av fientliga djur, aggressiva drakkin och Dark Iron-infiltratörer, så vägen är full av faror. Hinderweir uppmanar resenärer att hålla sig till den kullerstensbelagda vägen ända till Dun Modr, den plundrade dvärgstaden vid den södra infarten till Thandol Span, där ett regemente från Ironforge fortfarande håller vakt."},{t="Sprängexperten i Dun Modr",b="Ashlan Stonesmirk är stationerad vid den norra fronten i Khaz Modan och regementets expert på kraftiga sprängämnen. Efter årtionden av öronbedövande detonationer är han halvdöv, men hans skarpa syn och luktsinne bekräftar genast Hinderweirs värsta farhågor: ämnet är verkligen en specialiserad sprängladdning, vilket tyder på en samordnad plan riktad rakt mot hjärtat av dvärgarnas ingenjörskonst."}},faq={{q="Vad är det märkligt luktande pulvret?",a="Det är en alkemisk sprängladdning som samlats in nära Stonewrought Dam. Chief Engineer Hinderweir VII misstänker att sabotörer tänker spränga hål i dammens murar med den.",al={"vad är pulvret","hinderweirs pulver","märkligt pulver"}},{q="Varför skicka pulvret hela vägen till Dun Modr?",a="I Dun Modr finns Ironforges militärstyrka som försvarar Thandol Span, däribland sprängämnesexperten Ashlan Stonesmirk. Som erfaren expert på sprängämnen har han den tekniska kunskap som krävs för att identifiera specialiserade sprängämnen.",al={"varför dun modr","varför ashlan stonesmirk","varför åka till wetlands"}},{q="Var finns Ashlan Stonesmirk?",a="Ashlan Stonesmirk är stationerad i militärlägret i Dun Modr, längst norrut i Wetlands, strax söder om Thandol Span.",al={"var finns stonesmirk","hitta ashlan","stonesmirks plats"}},{q="Varför varnar Hinderweir för att hålla sig till vägen?",a="Vägen från Algaz Gate genom Wetlands går rakt genom områden som hemsöks av fientliga bestar, rovfåglar, gnoller och Dark Iron-sabotörer. Därför är det extremt farligt för kurirer att färdas utanför vägen.",al={"varför hålla sig till vägen","faror i wetlands","vägen till wetlands"}},{q="Vem saboterar Stonewrought Dam?",a="Sprängämnena tillhör Dark Iron-dvärgarna, som vill underminera Bronzebeard-infrastrukturen och få Stonewrought Dam att rasa så att dalarna nedanför dränks.",al={"vem gjorde pulvret","dammsabotörer","vem ligger bakom det mörka hotet"}},{q="Varför hör Ashlan Stonesmirk dåligt?",a="Åratal som militär sprängare vid fronten och sprängämnesspecialist har gett Ashlan ett kroniskt öronsus och svår hörselnedsättning från tryckvågorna vid explosioner.",al={"stonesmirk döv","varför hör ashlan inte"}}},fx={["4fa83212"]={q="Varför vill Chief Engineer Hinderweir VII att det här ska göras?",a="Chief Engineer Hinderweir ansvarar för att Stonewrought Dam håller. Den är ett av Khaz Modans främsta ingenjörsmästerverk. Han misstänker att det märkliga pulvret som hittats i närheten är sprängämne avsett att sabotera dammen. Därför behöver han en expertanalys för att förstå exakt vilket hot dammen står inför innan katastrofen slår till.",al={"varför behöver hinderweir det här","hinderweirs motiv","varför skicka pulvret"}}},fp="19,223,22.438.0,14.367.0,28.372.1,36.185.0,44.210.0,35.122.0,46.220.0,39.159.1,41.173.0"}
P.entries["quest:1618"] = {n="Gearing Redridge",s="Gearing Redridge är ett smidesuppdrag för Alliansen som Tormus Deepforge erbjuder i Ironforge. Blivande smeder tillverkar tålig kopparutrustning för att avlasta Lakeshires belägrade garnison och hjälpa den lokale smeden Verner Osgood att försvara området mot fientliga orcher och gnoller.",h="Gearing Redridge är ett smidesuppdrag för Alliansen som Tormus Deepforge erbjuder i Ironforge.",kw={"blackrock-orcher","smide","gnoller","heavy copper maul","lakeshire","redridge","runed copper belt","stonewatch","tormus deepforge","verner osgood"},ang={["faction:Alliance"]="Leveransen visar hur viktig ömsesidig hjälp är mellan Ironforge och människornas utsatta städer i söder. De rycker in där Stormwinds splittrade ledning har dröjt.",["profession:Blacksmithing"]="Uppdraget är ett mandomsprov för lärlingar i smide och prövar din förmåga att serietillverka hållbara vapen och skyddande rustningar för en aktiv krigsfront.",["race:Dwarf"]="Dvärgarnas hantverk är ryggraden i Alliansens krigsinsats, och Tormus ser till att Ironforges talanger använder sina färdigheter för att hjälpa utsatta allierade.",["race:Human"]="För människorna i de södra kungarikena innebär metallarbete från Khaz Modan en efterlängtad lättnad i kampen mot de aggressiva resterna av Blackrock."},sec={{t="En vädjan över kungariken",b="Great Forge i Ironforge slumrar sällan, men dvärgsmederna vet att Alliansens frontlinje sträcker sig långt bortom Dun Morogh. Långt nere i Redridge Mountains ligger människornas bosättning Lakeshire, som ständigt är under belägring. Blackrock-orcher tågar ut från Stonewatch Keep och kringströvande gnollflockar härjar på de norra åsarna. Kungliga förstärkningar från Stormwind dröjer, och de lokala förråden är farligt nära att sina."},{t="Lakeshires städ",b="Lakeshires lokale smed Verner Osgood arbetar nästan ensam vid sin utomhussmedja och försöker laga krossade rustningar och ersätta trasiga vapen. Tormus Deepforge ser hur hårt arbetet sliter på sin mänskliga yrkesbroder och skickar därför ut blivande smeder med fyra Runed Copper Belts och fyra Heavy Copper Mauls till Lakeshire. Som tack för att de stärker milisens försvarsförråd delar Verner gärna med sig av mer avancerade smidestekniker till resande hantverkare."}},faq={{q="Vem ger uppdraget Gearing Redridge?",a="Tormus Deepforge, en dvärgsmed vid Great Forge i Ironforge, erbjuder uppdraget till allianssmeder som har nått tillräcklig skicklighet i sitt yrke.",al={"uppdragsgivare för gearing redridge","vem ger gearing redridge","tormus-uppdrag"}},{q="Varför behöver Lakeshire vapen och rustningar från Ironforge?",a="Lakeshire utsätts för ständiga attacker från Blackrock-orcherna som håller till i Stonewatch Keep och från aggressiva gnoller i området. Stadens enda smed, Verner Osgood, är helt överhopad med att laga vapen och rusta milisen på egen hand.",al={"varför redridge behöver utrustning","varför lakeshire behöver vapen","brist på förnödenheter i redridge"}},{q="Vem tar emot leveransen i Redridge?",a="Leveransen lämnas till Verner Osgood, den lokale smeden som arbetar nära smedjan i Lakeshire, staden vid sjön.",al={"var lämnar man in gearing redridge","var finns verner osgood","lämna in till smeden i redridge"}},{q="Vilken utrustning måste smidas för uppdraget?",a="Du måste leverera fyra Runed Copper Belts och fyra Heavy Copper Mauls. De visar prov på både skyddande plåtarbete och skickligt hantverk med tunga vapen.",al={"föremål som behövs för gearing redridge","material för gearing redridge","vad ska jag tillverka åt tormus"}},{q="Vilka hot plågar Redridge just nu?",a="De främsta hoten mot Lakeshire är Blackrock-orchernas klaner, som befäster sig i Stonewatch Keep, och våldsamma gnollflockar som stryker omkring i de norra bergssluttningarna.",al={"fiender i redridge","vem attackerar lakeshire","hot i redridge"}},{q="Vilken belöning erbjuder Verner Osgood i utbyte?",a="När Verner slipper den hektiska bördan att utrusta varje vakt från grunden får han tid att lära dig avancerade smidestekniker.",al={"verner osgoods träning","belöning för gearing redridge","vad får jag"}}},fx={ba6aca96={q="Varför vill Tormus Deepforge att det här blir gjort?",a="Tormus Deepforge förstår att Ironforges mänskliga allierade är hårt pressade och utkämpar sina egna desperata strider. När Blackrock-klanen genomför oupphörliga räder mot Lakeshire vill Tormus stärka banden mellan dvärgar och människor genom att ge avgörande smideshjälp till en allierad som redan har fullt upp.",al={"varför hjälpa redridge","tormus deepforges motiv","varför skicka förnödenheter till redridge"}},e26bdf46={q="Vad ska det runristade kopparbältet användas till?",a="De här förtrollade bältena ger Lakeshires försvarare ett viktigt extra skydd. De lokala smederna är överhopade med att reparera trasig utrustning, så de slitstarka, smidda bältena hjälper till att skydda stadens vakter och milis i deras ständiga skärmytslingar med Blackrock-orcher och gnoller.",al={"vad används det runristade kopparbältet till","varför runristade kopparbälten","syftet med det runristade kopparbältet"}},["61555f3e"]={q="Vad ska den tunga kopparstridsklubban användas till?",a="De tunga kopparklubborna ger Lakeshires frontförsvarare slitstarka vapen som kan utdela hårda slag. Redridges försvarare drabbar ständigt samman med bepansrade Blackrock-orcher och tuffa Redridge-gnoller, så krossande trubbvapen är oumbärliga i kriget.",al={"syftet med den tunga kopparstridsklubban","varför tunga kopparstridsklubbor","tung kopparstridsklubba i redridge"}},["330fd0fb"]={q="Varför behöver Tormus Deepforge att du levererar dem i stället för att göra det själv?",a="Tormus är en mästersmed som utbildar lärlingar och sköter Ironforges viktiga Great Forge. Han kan inte lämna sin post för en resa till människornas länder. Genom att anförtro leveransen åt en blivande smed hjälper han deras allierade och låter dig lära dig hantverkstekniker av Verner Osgood.",al={"varför skicka mig till redridge","varför kan inte tormus leverera","varför jag ska rusta upp redridge"}}},fp="16,230,22.356.0,23.419.0,38.133.0,57.225.0,38.103.0,43.151.0,49.109.0,47.124.0"}
P.entries["quest:162"] = {n="Rise of the Silithid",s="Senior Surveyor Fizzledowser ber dig att ta rapporten om insekthotet till Gracina Spiritmight, en Night Elf-lärd och historiker i Darnassus.",h="Senior Surveyor Fizzledowser ber dig att ta rapporten om insekthotet till Gracina Spiritmight, en Night...",kw={"darnassus","fizzledowser","gracina","insektsanalys","silithider","spiritmight","tanaris","temple of the moon"},sec={{t="En lärd i Darnassus",b="Fizzledowser vill att rapporten når någon med praktisk kunskap om sådana frågor. Gracina Spiritmight är en Night Elf-lärd som har ägnat mycket tid åt att studera livsformer som är unika för Azeroths ekologi, och hon är också historiker. Fizzledowser hoppas att hon kan hjälpa till att ta reda på vad faran egentligen är och framför allt hur den kan stoppas. Enligt Fizzledowsers senaste uppgift bodde hon i Temple of the Moon i Darnassus."},{t="Gracinas svar",b="Gracina säger att nattalverna känner till den fasa som beskrivs i rapporten, och tror att Fizzledowser gjorde rätt i att skicka den, och dig. Dessa varelser kommer snabbt att sluka Tanaris öken och hör till de största hot någon kommer att möta. De är silithiderna, redskap för ett av de allvarligaste hoten mot både Horde och Alliance. Gracina beklagar att ingen var klok nog att inse det tidigare."}},faq={{q="Vem är Gracina Spiritmight?",a="En Night Elf-lärd och historiker som har ägnat mycket tid åt att studera livsformer som är unika för Azeroths ekologi.",al={"gracina spiritmight berättelse","vem är gracina","lärd i temple of the moon"}},{q="Vem skickar dig till Gracina?",a="Senior Surveyor Fizzledowser ger dig Insect Analysis Report och ber dig ta den till henne.",al={"varifrån kom rapporten","insect analysis report ursprung"}},{q="Var finns Gracina Spiritmight?",a="I Temple of the Moon i Darnassus, enligt Fizzledowsers senaste uppgift.",al={"var finns gracina","gracina spiritmight plats","hitta gracina spiritmight"}},{q="Vad föregick resan till Darnassus?",a="Den följer efter Insect Part Analysis.",al={"föregående uppdrag","vad ledde till silithidernas uppkomst","tidigare uppdrag till gracina"}}},fp="20,151,22.429.0,16.395.1,27.122.0,25.97.0,39.68.0,43.32.0"}
P.entries["quest:163"] = {n="Raven Hill",s="Rapporter om skiftande skuggor och fladdrande ljus i fönstren i den övergivna bosättningen Raven Hill har gjort Night Watch oroliga. Elaine Carevin i Darkshire skickar resande västerut genom de hemsökta skogarna för att möta den ondskefulla närvaro som tagit sin tillflykt bland ruinerna.",h="Rapporter om skiftande skuggor och fladdrande ljus i fönstren i den övergivna bosättningen Raven Hill har...",kw={"calor","darkshire","duskwood","elaine carevin","jitters","night watch","raven hill"},ang={["class:Paladin"]="En paladin som tränats i att jaga de rastlösa odöda som hemsöker den närliggande kyrkogården kan få en oväntad upptäckt när han undersöker rapporter om en ondskefull hemsökelse: den ynkligt kvidande Jitters är av kött och blod.",["faction:Alliance"]="Night Watch i Duskwood får knappt någon hjälp från Stormwinds garnison och måste därför förlita sig på resande hjältar från Alliansen för att undersöka hotfulla ting i territoriets ruinerade hörn."},sec={{t="Ögon i väster",b="För Night Watchs skogvaktare har Duskwoods avlägsna västra utkant länge varit överlåten åt de döda och vildmarken. Men fullständig övergivenhet vore ändå att föredra framför oväntad aktivitet. Calor, en väktare som patrullerar de dystra vägarna, lade märke till rörelser bland Raven Hills tysta hus två nätter i rad, tillsammans med det oroande fladdret från en lykta i ett fönster. I ett land hemsökt av gastar, skelett och bestar måste alla oförklarliga livstecken undersökas omedelbart."},{t="En skärrad eremit",b="De som väntar sig att möta en nyuppstånden demon eller odöd krigsherre inne i Raven Hill möter en långt ynkligare verklighet. Hopkrupen av skräck bland de förfallna ruinerna sitter Jitters, en fullständigt från vettet gången luffare som darrar vid minsta prassel i mörkret. Han protesterar febrilt att det inte finns något hot förutom \"den harmlöse Jitters\", men hans maniska svammel antyder att han vet betydligt mer om mardrömmen som slukar Duskwood än han vågar säga."}},faq={{q="Vem skickar dig för att undersöka Raven Hill?",a="Elaine Carevin, en invånare i Darkshire som hjälper Night Watch, ber resande som bryr sig om Duskwoods säkerhet att undersöka de oroande iakttagelserna från väster.",al={"vem ger uppdraget i raven hill","uppdragsgivare raven hill","elaine carevin uppdrag"}},{q="Vad såg Calor egentligen i Raven Hill?",a="Calor rapporterade att han sett rörliga skuggor i den övergivna bosättningen två nätter i rad, liksom en lykta eller ett ljus som brann i ett av byggnadernas fönster natten innan.",al={"vad såg calor","calors iakttagelse raven hill","skuggor i raven hill"}},{q="Vilket monster hemsöker ruinerna?",a="Det är just det du skickas dit för att ta reda på. Calor har bara skymtat rörliga skuggor och ett ljus i ett fönster. Du måste själv ta reda på vad som lurar i Raven Hills förfallna byggnader.",al={"vem hemsöker raven hill","vad finns i raven hill","finns monstret i raven hill på riktigt"}},{q="Vem är Jitters?",a="Jitters är en nervös och paranoid luffare som lever på randen till skräck i västra Duskwood. Han påstår sig vara helt ofarlig, men hans enorma skuldkänslor och febriga svammel antyder att han är indragen i regionens mörkare mysterier.",al={"jitters bakgrund","vem är jitters i duskwood","varför gömmer sig jitters"}},{q="Var ligger Raven Hill?",a="Raven Hill ligger längst västerut i Duskwood, strax söder om den väldiga, odöda kyrkogården som delar dess namn.",al={"raven hills läge","var hittar man raven hill","karta över raven hill"}},{q="Varför oroar sig Night Watch så mycket över rörliga skuggor?",a="Darkshire är hårt ansatt av skelettuppror, vilda vargar och lurande spindlar. Varje tecken på organiserad rörelse eller främmande invånare i den övergivna västern kan varsla om ett nära förestående angrepp på de återstående bebodda bosättningarna.",al={"varför bry sig om raven hill","night watch raven hill"}}},fx={["2c575d43"]={q="Varför vill Elaine Carevin att Raven Hill undersöks?",a="Elaine Carevin är fast besluten att hålla Duskwood tryggt. Night Watch är redan hårt pressade av fasorna som kryper genom skogarna, så märkliga ljus och rörliga skuggor i den övergivna bosättningen Raven Hill kan inte ignoreras. Hon behöver någon som tar reda på om ett nytt hot håller på att få fäste i regionens västra utkant.",al={"varför skickar elaine dig","elaine carevins motiv","varför undersöka raven hill"}},["2a1c77d7"]={q="Varför ber Elaine Carevin en äventyrare om hjälp i stället för Night Watch?",a="Night Watch har farligt få mannar och är överväldigade av försöken att hålla Darkshires ytterområden och skydda vägarna. Varje stridsduglig försvarare är upptagen med att vakta mot odöda, spindlar och worgen, så Elaine förlitar sig på dugliga resenärer som är villiga att bege sig in bland Raven Hills förfallna ruiner.",al={"varför jag till raven hill","varför skickar elaine inte night watch","varför be en äventyrare"}}},fp="10,179,16.371.0,16.274.1,40.165.0,42.164.0,35.168.1,15.199.1,28.111.0,57.213.0"}
P.entries["quest:1638"] = {n="A Warrior's Training",s="I Goldshire skickar A Warrior's Training unga krigare till Stormwind för att lära sig uthållighet på slagfältet. Lyria Du Lac hänvisar dem till Pig and Whistle Tavern i Old Town, där den erfarne Harry Burlguard delar med sig av sina kunskaper.",h="I Goldshire skickar A Warrior's Training unga krigare till Stormwind för att lära sig uthållighet på...",kw={"bartleby","goldshire","harry burlguard","lyria du lac","old town","pig and whistle","stormwind","träning","krigare"},ang={["class:Warrior"]="Som krigare markerar den här riten din övergång från lokal milisrekryt till officiellt erkänd soldat i Alliansen. Den öppnar vägen till avancerade ställningar och försvarstekniker.",["faction:Alliance"]="Som rekryt i Alliansen kan du ta med dig praktisk slagsmålsvisdom från veteraner som Harry Burlguard till omstridda gränser, vid sidan av taktiken du lärt dig ur böcker.",["race:Human"]="Som mänsklig kämpe går din väg från Elwynns lantliga försvar till Old Town, Stormwinds uråldriga arbetarklasskvarter och vagga för stadens krigstradition."},sec={{t="Från Elwynn till Old Town",b="När blivande kämpar visar att de behärskar grunderna mot hoten i Elwynn Forest, ser deras tränare inte mycket mer för Goldshires exercismästare att lära ut. Lyria Du Lac skickar rekryterna till Stormwind, mot den kärva stadsdelen Old Town. Där samlas veteraner för att dela med sig av sina stridserfarenheter, långt från det kungliga garnisonens strikta seder."},{t="Veteranens lärdomar",b="Harry Burlguard, en åldrad stridsveteran, håller till på Pig and Whistle Tavern. Han prövar en krigares mod med värdshusets råa stämning och praktisk uthållighet i stället för exercis. Innan han lär ut försvarsmanövrer som hjälper soldater att överleva farliga fälttåg, förväntar sig Harry att nykomlingarna ska tåla lika mycket att dricka som han och möta lokala slagskämpar på värdshuset."}},faq={{q="Vem ger det här uppdraget?",a="Lyria Du Lac, krigartränaren bakom smedjan i Goldshire, erbjuder den här träningen när en kämpe har visat sin tidiga stridsförmåga.",al={"uppdragsgivare","vem ger en krigares träning","lyria du lac uppdrag"}},{q="Var hittar man Harry Burlguard?",a="Harry Burlguard finns inne på Pig and Whistle Tavern i stadsdelen Old Town i Stormwind City.",al={"var finns harry burlguard","harry burlguards plats","pig and whistle tavern"}},{q="Vad lär Harry Burlguard ut?",a="Harry lär ut praktiska rörelser och ställningar som hjälper krigare att hålla ut längre i fält, med uthållighetsprov som första steg.",al={"vad lär man sig","krigaruppdrag belöning nivå 10","harry burlguards lektion"}},{q="Varför hålls träningen på ett värdshus i stället för i kasernen?",a="Old Town är Stormwinds traditionella, råa hjärta, där pensionerade soldater och härdade veteraner samlas. Harry undervisar över öl och med disciplin från knytnävsslagsmål i stället för kasernens formella militära seder.",al={"varför pig and whistle","varför träna på värdshus","stormwinds kasern"}},{q="Vad händer efter att man talat med Harry?",a="Efter samtalet med Harry får rekryten möta den lokala slagskämpen Bartleby the Drunk i en utmaning som prövar den fysiska uthålligheten innan träningen är fullbordad.",al={"vad är nästa uppdrag","efter a warriors training","nästa steg"}},{q="Kan andra än krigare få det här uppdraget?",a="Bara krigare kan få den här träningen. Den ingår i den särskilda träningslinjen för krigare.",al={"är uppdraget bara för krigare","kan paladiner göra detta","uppdrag för krigarklassen"}}},fx={["7596c61a"]={q="Varför skickar Lyria Du Lac dig till Harry Burlguard?",a="Lyria Du Lac vet att du har visat dig vara en skicklig krigare, men hon vet också att rå entusiasm bara räcker en bit på slagfältet. För att du ska överleva farligare hot skickar hon dig till Harry Burlguard. Som erfaren veteran har Harry finslipade stridstekniker och praktisk kunskap om slagfältet som nya rekryter verkligen behöver om de hoppas överleva.",al={"varför vill lyria detta","lyria du lacs motiv","varför skicka till harry burlguard"}}},fp="20,234,23.356.0,22.374.0,21.139.0,35.103.0,32.121.0,57.209.0,35.166.1,36.91.0"}
P.entries["quest:1639"] = {n="Bartleby the Drunk",s="På värdshuset Pig and Whistle ställs Bartleby inför ett prov som Harry Burlguard har satt upp. En aspirerande krigare i Alliansen måste ta Bartlebys dyrbara mugg innan Harry lär ut mer avancerade stridsfärdigheter.",h="På värdshuset Pig and Whistle ställs Bartleby inför ett prov som Harry Burlguard har satt upp.",kw={"bartleby","berusad","harry burlguard","mugg","old town","pig and whistle","stormwind","träning","krigare"},ang={["class:Warrior"]="Som krigare ställs du inför ett praktiskt prov från tränarna i Stormwind innan de lär ut försvarstaktik och behärskning av ställningar.",["faction:Alliance"]="Som resenär i Alliansen får du se den råa och oglamorösa sidan av Old Town i Stormwind, långt från kungliga hovet i Keep."},sec={{t="Ett prov på värdshuset",b="Harry Burlguard vill se att en nybörjare har mod innan han lär ut mer avancerade stridsfärdigheter på värdshuset Pig and Whistle. Tvärs över rummet sitter Bartleby och smuttar på sina drinkar längst bort vid disken. Harry vill att du tar mannens mugg, eftersom han vet att Bartleby hellre slåss än lämnar ifrån sig sin öl. Utmaningen sätter en krigares beslutsamhet på prov."},{t="Old Towns värdshusseder",b="Soldater, arbetare och barska lokalbor fyller Pig and Whistle, där goda manér betyder föga. Bartleby hånar nykomlingar som alltför fisförnäma för ett slagsmål på värdshuset i stället för att svara artigt. Utbytet leder till ett slagsmål på golvbrädorna, där en krigares träning i Stormwind börjar med ett prov i grundläggande slagsmål på krogen."}},faq={{q="Vem är Bartleby?",a="Bartleby är en tjurskallig storkonsument av alkohol som sitter vid bardisken på värdshuset Pig and Whistle i Old Town i Stormwind.",al={"vem är bartleby","bartleby npc","bartleby the drunk"}},{q="Varför skickar Harry Burlguard mig till Bartleby?",a="Harry Burlguard vill se vilka rörelser du behärskar innan han lär ut avancerade krigar tekniker. Om du tar Bartlebys mugg blir det garanterat slagsmål, och du får visa att du kan ta en smäll och stå på dig.",al={"varför slåss mot bartleby","harry burlguards prov","varför ta muggen"}},{q="Var utspelar sig mötet?",a="Mötet äger rum inne på värdshuset Pig and Whistle i Old Town, på den östra sidan av Stormwind City.",al={"var finns bartleby","pig and whistle plats"}},{q="Vad händer när du talar med Bartleby?",a="Bartleby förolämpar dig och kallar dig fin och fisförnäm, och varnar dig sedan för att bryta en nagel på Pig and Whistle. Hans ord leder snart till slagsmål.",al={"vad säger bartleby","bartlebys dialog"}},{q="Vad händer efter att du har talat med Bartleby?",a="Efter att du har talat med Bartleby börjar ett slagsmål på värdshuset. Du måste besegra honom för att ta hans mugg och lämna tillbaka den till Harry Burlguard.",al={"nästa uppdrag efter bartleby","vad följer efter bartleby the drunk"}},{q="Kan alla klasser ta det här uppdraget?",a="Nej. Den här klassträningen är för krigare i Alliansen som har nått nivå tio.",al={"kan alla göra bartleby","endast krigare"}}},fx={["1d302574"]={q="Varför skickar Harry Burlguard dig i stället för att själv konfrontera Bartleby?",a="Harry Burlguard har inget personligt otalt med den lokale suputen. Han är en krigartränare som prövar din förmåga. Innan han slösar tid på att lära dig avancerade stridstekniker vill han se om du har mod nog att klara dig i ett rejält slagsmål. Att skicka dig för att rycka en mugg från en motsträvig krogfyllerist är helt enkelt hans praktiska inträdesprov.",al={"varför jag","varför skicka mig till bartleby","varför slåss inte harry mot bartleby"}}},fp="18,193,18.347.0,18.330.0,16.113.0,45.195.0,37.111.0,40.133.0,37.122.0,37.76.0"}
P.entries["quest:164"] = {n="Deliveries to Sven",s="Deliveries to Sven är ett alliansuppdrag från Elaine Carevin i Darkshire, där du ska föra livsviktiga förnödenheter till ett ensligt läger vid Duskwoods nordvästra gräns. Där utkämpar Sven Yorgen och hans få kvarvarande följeslagare en desperat, ensam kamp mot de fördärvade skogarnas fasor. Uppdraget förbinder stadsbor som kämpar i dunklet med en isolerad grupp vid vildmarkens utkant.",h="Deliveries to Sven är ett alliansuppdrag från Elaine Carevin i Darkshire, där du ska föra livsviktiga...",kw={"carevin","darkshire","duskwood","elaine carevin","ljuset","supplies for sven","sven yorgen"},ang={["class:Paladin"]="Elaine beskriver Sven som en man som utför Ljusets sanna verk. Att leverera förnödenheterna blir därmed en solidaritetshandling med en broder under belägring.",["faction:Alliance"]="Avlägsna väktare som Sven visar hur bräckligt Alliansens grepp om Duskwood är. Där hänger överlevnaden på frivilliga budbärare snarare än regelbundna leveranser från garnisonen.",["race:Human"]="Familjen Carevin och Svens följeslagare visar landsbygdens okuvliga Stormwindbor vägrar överge Duskwood trots dess obevekliga dunkel."},sec={{t="En livlina till vildmarken",b="Darkshire kämpar för att hålla vargar, spindlar och rastlösa döda borta från stadsmurarna, men vissa vägrar hukande gömma sig bakom palissader. Sven Yorgen och en liten handfull följeslagare slog upp ett ensligt läger längs Duskwoods nordvästra gräns. De är så hårt trängda av den ständiga faran att de inte kan avvara en enda person för den riskfyllda färden tillbaka till staden efter förnödenheter. Elaine Carevin samordnar hjälpen och förlitar sig på modiga resenärer för att se till att dessa gränskrigare inte svälter."},{t="Bandet till familjen Carevin",b="Familjen Carevin hyser stor aktning för Sven och ser hans beslutsamma motstånd som sann hängivenhet till Ljuset. Elaine visar genom sin vilja att organisera och skicka förnödenheter hur de stillsamma överlevnadsnäten hindrar Duskwood från att helt falla i skugga. När Sven tar emot lådan känner han igen familjen Carevins orubbliga stöd, men tankarna upptas fortfarande av den dystra striden som pågår."}},faq={{q="Vem är Sven Yorgen?",a="Sven Yorgen är en gränsbo som håller ett beväpnat läger vid Duskwoods nordvästra utkant. Elaine Carevin och andra ser honom som en hederlig kämpe som utför Ljusets verk. Sven och hans lilla grupp kämpar mot de otaliga fasor som hemsöker skogarna omkring dem.",al={"vem är sven","sven i berättelsen","information om sven yorgen"}},{q="Varför behöver Sven få förnödenheter levererade?",a="Svens grupp är mycket liten och måste ständigt hålla vakt mot hoten runtomkring. De kan inte avvara ens en person för den farliga färden till Darkshire och tillbaka. Därför är de helt beroende av välvilliga stadsbor och förbipasserande budbärare för sin försörjning.",al={"varför kan sven inte få förnödenheter","svens förnödenheter","varför leverans"}},{q="Vem står för förnödenheterna?",a="Elaine Carevin står för förnödenheterna från Darkshire. Hennes familj står Sven nära och hyser stor aktning för hans hängivenhet. De ordnar regelbundet hjälp till hans läger.",al={"vem skickar förnödenheter","elaine carevin","familjen carevin"}},{q="Var ligger Svens läger?",a="Svens läger ligger invid bergen i nordvästra Duskwood, långt bortom vägen och norr om de fördärvade åkrarna, ute i vildmarken vid gränsen.",al={"var finns sven","svens plats","svens läger"}},{q="Måste jag leverera detta innan jag hjälper Sven vidare?",a="Nej. Elaine Carevin erbjuder uppdraget för att visa resenärer vägen till Sven, men den som själv hittar lägret kan hjälpa honom direkt utan att bära Elaines låda.",al={"krävs deliveries to sven","behöver jag deliveries to sven","förutsättning för leveransen"}},{q="Vad gör Sven efter att ha fått leveransen?",a="Sven uttrycker uppriktig tacksamhet för familjen Carevins stöd, men tankarna går genast till hoten mot lägret och familjens mörka historia. Han söker stridsdugliga kämpar som kan hjälpa honom att utkräva hämnd.",al={"vad händer sedan","efter deliveries to sven","svens nästa uppdrag"}}},fx={cd88e308={q="Varför vill Elaine Carevin att förnödenheter levereras till Sven?",a="Elaine Carevin hyser stor aktning för Sven Yorgen och ser hans korståg i vildmarken som ett sant verk i Ljusets tjänst. Hennes familj stöder regelbundet hans sak med viktiga förnödenheter, men Svens grupp är alldeles för liten för att avvara någon som tryggt kan ta sig till Darkshire och hämta dem.",al={"varför skickar elaine förnödenheter","elaine carevins motiv","varför elaine hjälper sven"}},d0ad7f5e={q="Varför ber Elaine Carevin dig i stället för Night Watch?",a="Night Watch är redan hårt pressade och nära bristningsgränsen när de vaktar Darkshire och patrullerar huvudvägarna mot Duskwoods odöda och bestar. De har inga vakter att avvara för att köra förnödenheter till ett avlägset läger i vildmarken i nordväst.",al={"varför behöver elaine mig","varför inte skicka night watch","varför leverera förnödenheterna själv"}}},fp="18,165,28.384.0,22.253.0,19.223.0,43.204.0,26.115.0,29.149.0,55.93.0,47.174.0"}
P.entries["quest:1640"] = {n="Beat Bartleby",s="I Stormwind vaktar Bartleby muggen som en ung krigare måste ta. Instruktörerna skickar rekryterna att möta honom i en knytnävsfight och vinna kärlet till sin träning.",h="I Stormwind vaktar Bartleby muggen som en ung krigare måste ta.",kw={"bartleby","slagsmål","berusad","mugg","stormwind","träning","prov","krigare"},ang={["class:Warrior"]="Som krigare i Alliansen möter du det här tidiga krogslagsmålet och lär dig att viljestyrka och en tung näve kan lösa tvister när diplomatin misslyckas.",["faction:Alliance"]="På Stormwinds huvudstads gator får du en glimt av stadens råa baksida, sida vid sida med dess ståtliga stenmurar."},sec={{t="En slagskämps utmaning",b="Stormwinds krigarinstruktörer förväntar sig att rekryterna möter strid utan ursäkter eller högtidliga ceremonier. Som en del av sin formella träning måste unga krigare hämta en särskild mugg från Bartleby, en ökänd suput som slår dank i staden. Han hånskrattar åt artiga förfrågningar och svär att ingen får hans dyrbara dryckeskärl utan att först slita det ur hans kalla, döda fingrar. För en nybörjarkrigare övergår ord snart i slagsmål."},{t="En berusad läxa",b="Bartleby skryter om att han tänker slåss till döden, men en rejäl omgång stryk räcker för att nyktra till honom. När han väl är besegrad ger hans skrytsamhet vika för blåslagen beundran. Han inser att motståndaren är tuffare än hen verkar och ger sig fredligt, så att segraren kan ta muggen och slutföra provet i träningssalen."}},faq={{q="Vem är Bartleby?",a="Bartleby är en stridslysten suput som ofta håller till i Stormwind City. Han håller hårt i ett älskat dryckeskärl och sätter nybörjarkrigare på prov när de skickas dit för att visa sin fysiska beslutsamhet.",al={"bartleby","vem är bartleby","bartleby npc"}},{q="Varför måste jag slåss mot Bartleby?",a="Alliansens krigarinstruktörer skickar rekryterna för att hämta en mugg som Bartleby har. Han vägrar lämna ifrån sig den utan slagsmål, så rekryten måste besegra honom i närstrid för att ta den.",al={"varför slåss mot bartleby","orsak att besegra bartleby","varför besegra honom"}},{q="Dödar jag verkligen Bartleby i det här uppdraget?",a="Nej. Bartleby skryter om att du måste slita muggen ur hans kalla, döda fingrar, men han ger sig när han blir besegrad och medger att du är tuffare än han trodde.",al={"dör bartleby","döda bartleby","är bartleby död"}},{q="Var utspelar sig det här uppdraget?",a="Konfrontationen äger rum i Stormwind, där Bartleby dricker och driver omkring.",al={"plats där bartleby besegras","var finns bartleby","bartlebys plats"}},{q="Vad händer när jag besegrar honom?",a="När du har besegrat honom ger Bartleby sig och pratar vänligt med dig. Du kan ta hans mugg tillbaka till krigarinstruktörerna och slutföra din invigning.",al={"efter att ha besegrat bartleby","vad händer sedan med bartleby"}},{q="Vilken nivå av träning motsvarar det här provet?",a="Det här slagsmålet är en tidig milstolpe för nybörjarkrigare med omkring tio säsongers erfarenhet, ett praktiskt test av grundläggande uthållighet i närstrid.",al={"bartleby uppdragsnivå","när slåss jag mot bartleby"}}},fx={["14f26138"]={q="Varför slåss Bartleby mot dig?",a="Bartleby vill inte alls att det här slagsmålet ska äga rum. Det var du som startade det genom att kräva hans mugg. Han är envis, berusad och fäst vid sin dryck, och vägrar lämna ifrån sig den frivilligt. Han säger att du får ta den ur hans kalla, döda händer. För Bartleby handlar slagsmålet bara om berusad stolthet och att hålla fast vid sitt öl.",al={"varför anfaller bartleby","bartlebys motiv","varför slåss bartleby"}}},fp="13,171,21.424.0,16.316.0,16.167.0,32.181.0,42.149.0,33.78.0,32.142.0,49.139.0"}
P.entries["quest:1641"] = {n="The Tome of Divinity",s="I Stormwind vägleder The Tome of Divinity unga paladiner genom en högtidlig rit. Under Duthorian Ralls ledning i Cathedral of Light får du lära dig om dygd, hängivenhet och plikterna som följer med Holy Light.",h="I Stormwind vägleder The Tome of Divinity unga paladiner genom en högtidlig rit.",kw={"book of divinity","brother wilhelm","cathedral of light","duthorian rall","holy light","paladin","stormwind","the tome of divinity","dygd"},ang={["class:Paladin"]="Som paladin markerar den här riten din övergång från vapenelev till tjänare åt Holy Light. Den visar på uppoffringen och barmhärtigheten som utgör ordens kärna.",["faction:Alliance"]="Som medlem av Alliance stärker din träning Stormwinds hjärta och förbereder dess paladiner på att skydda Alliance från det växande mörkret.",["race:Human"]="Som människa från Stormwind hedrar du Lordaerons fallna riddare och för Silver Hands stolta tradition vidare i det södra kungariket."},sec={{t="En paladins kall",b="Duthorian Rall vägleder dem som följer paladins kallelse i Cathedral of Light. Den första träningen lär ut stridsdisciplin och ordens riter, men för att gå vidare krävs ett djupare andligt engagemang. Prövningarna ber dig att se bortom striden och väga en paladins moraliska plikter. Stormwind möter faror både innanför och utanför sina gränser, och dess folk behöver försvarare som förstår den plikten."},{t="Dygdens väg",b="När du tar emot Book of Divinity binds du till tjänst och självuppoffring. Duthorian ber dig studera den heliga texten och lära dig vad Light kräver av sina försvarare. Dess lärdomar förbereder paladiner att stå emot Scourges krypande fasor och skydda vanligt folk. Rättfärdig makt måste vägledas av dygd och medkänsla."}},faq={{q="Vad är syftet med The Tome of Divinity?",a="The Tome of Divinity prövar en blivande paladins förståelse för heliga principer. Innan en novis anförtros större gudomliga förmågor måste dennes styrka vila på hängivenhet och dygd, inte bara stridskraft.",al={"varför the tome of divinity","vad är the tome of divinity","paladinens bokuppdrag"}},{q="Vem är Duthorian Rall?",a="Duthorian Rall är en erfaren paladintränare i Stormwinds Cathedral of Light. Han vägleder nya paladiner, ger dem Book of Divinity och leder deras prövningar runt om i kungariket.",al={"duthorian rall","paladintränare i stormwind","vem är duthorian"}},{q="Var äger den här prövningen rum?",a="Prövningen börjar i Cathedral Square i Stormwind City, inne i Cathedral of Light. Efter inledande uppgifter i avlägsna byar som Goldshire anmäler sig noviserna hos Duthorian Rall.",al={"var finns duthorian","uppdrag i cathedral of light","var börjar the tome of divinity"}},{q="Varför nämns Scourge i Stormwinds undervisning?",a="Scourge ödelade Lordaeron i norr, men dess odöda är fortfarande ett hot mot alla levande dödliga. Stormwinds paladiner lär sig känna igen och bekämpa Scourges oheliga fördärv var det än visar sig i Azeroth.",al={"scourges hot mot stormwind","varför scourge här","paladiner mot scourge"}},{q="Vad händer efter att ha läst Book of Divinity?",a="Att läsa Book of Divinity är bara det första steget. Duthorian Rall prövar om du har tagit lärdomarna till dig genom att skicka dig för att hjälpa dem som är i desperat behov, där dina handlingar måste bevisa din medkänsla och uthållighet.",al={"nästa steg i the tome of divinity","efter att ha läst boken","vad vill duthorian att jag gör härnäst"}},{q="Vem brukar hänvisa kandidater till Duthorian Rall?",a="Lokala instruktörer och präster i Elwynnshire kan hänvisa kandidater till Duthorian Rall. Brother Wilhelm i Goldshire är en sådan vägvisare och skickar noviser till huvudstaden när de är redo för formella prövningar.",al={"vem skickade mig till duthorian","föregående uppdrag till the tome of divinity","brother wilhelm"}}},fx={f1eda7dc={q="Varför vill Duthorian Rall att du genomgår det här provet?",a="Duthorian Rall har i Stormwind ansvaret för att vägleda unga paladiner mot sann dygd och hängivenhet till det Heliga Ljuset. Med Azeroth hotat av Scourge och otaliga andra faror behöver orden ståndaktiga försvarare med orubblig tro och förmåga. Genom att ge dig Divinity-boken vill han pröva om du förstår en paladins heliga löften och försäkra sig om att du har den andliga grund som krävs innan han ger dig större heliga välsignelser.",al={"varför vill duthorian rall att detta blir gjort","duthorian ralls motiv","varför studera divinity-boken"}},e0af06a7={q="Varför väljer Duthorian Rall dig för det här uppdraget?",a="Det här provet är en inre, andlig övergångsrit som bara du kan genomgå. Vanliga vakter och etablerade riddare kan inte studera Ljusets lärosatser åt dig. Duthorian Rall vägleder dig i din personliga utveckling som blivande paladin. För att förtjäna ordens ära och förmågor måste du själv visa din hängivenhet och beredskap att axla de heliga ansvar som väntar.",al={"varför jag för duthorian rall","varför väljer duthorian dig","varför inte skicka vakter"}}},fp="20,220,19.405.0,18.313.0,44.220.0,22.179.0,33.184.0,54.218.0,46.214.0,50.222.0"}
P.entries["quest:1642"] = {n="The Tome of Divinity",s="The Tome of Divinity är ett grundläggande steg i utbildningen av paladiner som ägnar sig åt det heliga ljuset. Den heliga läran, som ges för att vägleda blivande förkämpar i Stormwind, betonar att sann gudomlighet ligger i ödmjuk dygd, medkänsla och tålamod, inte i rå krigisk styrka eller strävan efter gudomlighet. Under Duthorian Ralls vakande blick måste noviser omsätta lärdomarna i handling genom att tjäna de behövande och utsatta i kungariket.",h="The Tome of Divinity är ett grundläggande steg i utbildningen av paladiner som ägnar sig åt det heliga ljuset.",kw={"cathedral of light","medkänsla","gudomlighet","duthorian rall","heliga ljuset","paladin","tålamod","stormwind","the tome of divinity"},ang={["class:Paladin"]="The Tome of Divinity beskriver paladinens kallelses moraliska kärna och slår fast att medkänsla och tålamod är lika viktiga som stridsberedskap.",["faction:Alliance"]="Stormwinds paladiner utgör Alliansens andliga och krigiska ryggrad och grundar rikets försvar i moralisk integritet och ödmjuk tjänst åt vanliga invånare.",["race:Human"]="För Stormwinds människor är studierna av den heliga boken en helig övergångsrit som stärker plikten mot samhället och hängivenheten till det heliga ljuset."},sec={{t="Gudomlighetens natur",b="För en novis som vandrar paladinens väg är gudomlighet ofta missförstådd. Som de heliga skrifterna i The Tome of Divinity förklarar innebär strävan efter gudomlighet inte att man söker bli en gud eller göra anspråk på makt över andra. I stället uppmanar Ljuset sina förkämpar att återspegla dess nåd genom rena avsikter och godhet i varje handling. Paladiner tränas utan tvekan i att slå ned ondska och gripa till vapen i farofyllda tider, men krigisk styrka saknar mening utan ett moraliskt syfte. Skriften påminner riddarna om att verklig ära ligger i hur de behandlar Azeroths vanliga folk, så att makten alltid förblir förankrad i rättfärdighet och ödmjukhet."},{t="Prov i medkänsla och tålamod",b="Att studera heliga skrifter är bara inledningen till verklig tjänst. När en novis väl fördjupar sig i The Tome of Divinity prövar Duthorian Rall i Stormwind om lärdomarna har slagit rot i kandidatens hjärta och sinne. Ljusets kallelse kräver mycket mer än att dräpa bestar; den kräver uthålligt tålamod, orubbligt mod och genuin förståelse. I staden och de omgivande länderna finns alltid lidande invånare och uppgifter som inte ger någon ära eller berömmelse. Genom att ge sig ut för att hjälpa de mindre lyckligt lottade och trösta dem som misströstar visar en paladin att hen har det sunda förnuft och den osjälviska anda som krävs för att bruka Ljusets välsignelser ansvarsfullt."}},faq={{q="Vad är The Tome of Divinity?",a="The Tome of Divinity är en helig lärobok som paladiner studerar i Stormwind. Den lär ut att gudomlighet inte handlar om att bli en gud eller söka personlig ära, utan om att återspegla det heliga ljuset genom moralisk godhet, medkänsla och tålamod i varje handling.",al={"vad är the tome of divinity","uppdraget the tome of divinity","paladin the tome of divinity"}},{q="Vem är Duthorian Rall?",a="Duthorian Rall är en respekterad paladinledare i Stormwind. Han leder de unga paladinernas andliga och krigiska prov, vägleder dem i studierna av The Tome of Divinity och prövar deras beslutsamhet genom praktiska uppgifter som gagnar kungariket och dess folk.",al={"vem är duthorian rall","duthorian ralls plats","duthorian rall i stormwind"}},{q="Vilka dygder betonar The Tome of Divinity?",a="The Tome of Divinity lär ut att medkänsla, tålamod och mod är lika viktiga för en helig krigare som stridsförmåga. Paladiner måste slå ned ondska, men deras verkliga ädelmod visar sig när de osjälviskt hjälper de utsatta och återspeglar Ljusets välvilja.",al={"paladinens dygder i the tome of divinity","vad lär boken ut","ljusets dygder"}},{q="Varför prövar Duthorian Rall blivande paladiner?",a="Duthorian Rall prövar noviser för att försäkra sig om att de verkligen har tagit till sig lärdomarna i The Tome of Divinity. En paladin måste visa att hen har sunt förnuft och tålamod nog att hjälpa de mindre lyckligt lottade, och bevisa att hängivenheten bygger på tjänande snarare än stolthet.",al={"varför prövar duthorian paladiner","duthorian ralls prov","syftet med paladinernas prov"}},{q="Lär The Tome of Divinity paladiner att söka gudomlighet?",a="Nej, texten avvisar uttryckligen strävan efter att bli en gud. Den lär paladiner att strävan efter gudomlighet innebär att sträva efter godhet i alla handlingar och använda styrkan från Ljuset till att skydda och stödja andra, i stället för att höja sig över sina medmänniskor.",al={"söker paladiner bli gudar","paladinens strävan efter gudomlighet","paladinens gudomlighet"}},{q="Var utspelar sig det här uppdraget?",a="Det här uppdraget utspelar sig i människornas kungarike Stormwind. Noviser studerar den heliga läran och rapporterar direkt till Duthorian Rall i staden, där de förbereder sig på prov i välgörenhet, tålamod och tapperhet på stadens gator och i rikets omgivande länder.",al={"var finns uppdraget the tome of divinity","the tome of divinity i stormwind","var lämnar man in the tome of divinity"}},{q="Varför är tålamod så viktigt för en paladin som tjänar Ljuset?",a="Tålamod visar att en helig krigare är disciplinerad, ödmjuk och har sunt förnuft. Ljusets sanna tjänare måste ofta utföra anspråkslösa, svåra eller oglamorösa uppgifter för de förtryckta. Det kräver känslomässig uthållighet och genuin empati, inte bara aggressiv kraft i strid.",al={"varför tålamod för paladiner","vikten av tålamod för ljuset","paladinens tålamodsprov"}}},fp="20,441,22.673.0,33.669.0,29.270.0,22.269.0,49.276.0,47.277.0,57.268.0,33.266.0,56.297.0"}
P.entries["quest:1643"] = {n="The Tome of Divinity",s="The Tome of Divinity är en grundläggande helig prövning där Ljusets noviser ska söka upp och hjälpa en invånare i Stormwind med ett rent hjärta och ädla motiv. De hänvisas till Stephanie Turner i Trade District, och prövningen visar att sann tjänst börjar med ödmjuk välgörenhet till de utsatta.",h="The Tome of Divinity är en grundläggande helig prövning där Ljusets noviser ska söka upp och hjälpa en...",kw={"heliga ljuset","ironforge","barnhem","paladin","stephanie turner","stormwind","the tome of divinity","tome of divinity","trade district"},ang={["class:Paladin"]="Den här prövningen är en avgörande tidig läxa för paladiner som lär sig tjäna den Heliga Ljuset. Den visar att sann hängivenhet börjar med ödmjuk välgörenhet, inte med krigisk ära.",["faction:Alliance"]="Uppdraget lyfter fram vardagsproblemen i Stormwind och de gemensamma banden till Ironforge, medan invånarna försöker stödja utsatta föräldralösa barn under ekonomisk press."},sec={{t="En läxa i ödmjukhet och tjänande",b="The Tome of Divinity är en viktig andlig övergångsrit för noviser som studerar den Heliga Ljusets vägar. Innan de får djupare undervisning i heliga plikter får de som vill tjäna i uppgift att vandra på Stormwinds gator och hitta någon med ädla avsikter och rent hjärta som är beroende av främlingars vänlighet. Prövningen förankrar heliga löften i ödmjukt, uppmärksamt tjänande av de utsatta, inte i ärorik strid."},{t="Hjälp i Trade District",b="I Stormwinds livliga Trade District leder plikten noviserna till Stephanie Turner. Tillsammans med sin make ägnar Stephanie dagarna åt att tillverka kläder åt barnen på stadens barnhem. På senare tid har dock fler lokala hantverkare skapat hård konkurrens om rått tyg och läder, vilket gör det svårt för paret att få tag på donationer. Medan hennes make reser till Ironforges stora dvärgahallar för att be om stöd, stannar Stephanie kvar i Stormwind och fortsätter sitt stillsamma, osjälviska arbete."}},faq={{q="Vad är syftet med prövningen The Tome of Divinity?",a="The Tome of Divinity är en grundläggande prövning för blivande paladiner som ägnar sig åt den Heliga Ljuset. I stället för att kräva stridsförmåga eller storslagna hjältedåd leder den noviserna till hjärtat av Stormwind för att söka upp och hjälpa någon med rent hjärta som verkligen behöver hjälp.",al={"vad är the tome of divinity","syftet med tome of divinity","varför göra tome of divinity"}},{q="Vem är Stephanie Turner?",a="Stephanie Turner är en omtänksam invånare i Stormwinds Trade District. Hon arbetar outtröttligt med att sy kläder åt barnen på det lokala barnhemmet och förlitar sig på donationer av tyg och läder för att hålla barnen varma och omhändertagna.",al={"vem är stephanie turner","stephanie turner stormwind","var finns stephanie turner"}},{q="Varför har Stephanie Turners make rest till Ironforge?",a="Hennes make arbetar tillsammans med henne för att tillgodose barnhemmets behov. Medan Stephanie samlar material och syr kläder i Stormwind har hennes make rest norrut till Ironforge för att söka donationer och hjälp från dvärgarnas och gnomernas befolkning.",al={"stephanie turners make","vem är stephanies make","make i ironforge"}},{q="Vilka svårigheter står Stephanie Turner inför?",a="Fler hantverkare i Stormwind har ökat konkurrensen om viktiga råmaterial som tyg och läder. Eftersom färre vill skänka bort dessa resurser får Stephanie allt svårare att samla in materialet som behövs för att sy kläder åt föräldralösa barn.",al={"varför har stephanie det svårt","tygbrist i stormwind","problem med kläder till barnhemmet"}},{q="Varför leder prövningen noviserna särskilt till Stephanie Turner?",a="Prövningen kräver att en novis till Ljuset söker upp någon med ädla avsikter, rena motiv och ett verkligt behov av en hjälpande hand. Stephanie Turner förkroppsligar osjälvisk hängivenhet till andra och är därför den perfekta personen för någon som vill tjäna Ljuset att hjälpa.",al={"varför hjälpa stephanie turner","varför skickar uppdraget dig till stephanie"}},{q="Vilken läxa ger prövningen Ljusets tjänare?",a="Prövningen lär ut att vägen till Ljuset kräver medkänsla, osjälviskhet och tjänande av de utsatta. Innan en förkämpe för Ljuset brukar helig kraft i strid måste hon först förstå plikten att visa vänlighet mot vanliga invånare i nöd.",al={"vad lär ljuset ut här","lärdomen i tome of divinity"}}},fp="20,311,32.438.0,25.536.0,50.272.0,24.256.0,53.245.0,45.280.0,70.265.0,60.259.0"}
P.entries["quest:1644"] = {n="The Tome of Divinity",s="The Tome of Divinity är ett paladinuppdrag i Stormwind där noviser ger linnetyg till Stephanie Turner, som tar hand om barn som blivit föräldralösa efter Scourge. Genom att hjälpa henne att klä barnen medan hennes make samlar förnödenheter i Ironforge visar uppdraget den viktiga paladindygden osjälvisk välgörenhet.",h="The Tome of Divinity är ett paladinuppdrag i Stormwind där noviser ger linnetyg till Stephanie Turner, som...",kw={"välgörenhet","john turner","linnetyg","föräldralösa barn","paladin","scourge","stephanie turner","stormwind","tome of divinity"},ang={["class:Paladin"]="Som en del av prövningarna kring The Tome of Divinity sätter omsorgen om utsatta och osjälvisk välgörenhet i Stormwind en paladins hängivenhet till medkänsla och Ljuset på prov.",["faction:Alliance"]="De krigsföräldralösas situation i Stormwind visar hur de senaste Scourge-angreppen drabbat människor i de nordliga alliansrikena.",["profession:Tailoring"]="Stephanie Turner använder enkla linnetygsrullar för att sy nödvändiga skjortor och byxor åt de föräldralösa barn hon tar hand om."},sec={{t="Krigets föräldralösa",b="På Stormwinds livliga gator tar Stephanie Turner hand om en grupp barn som förlorat sina familjer efter den förödelse Scourge orsakat i de nordliga länderna under det senaste årtiondet. Medan hennes make John reser bort för att samla förnödenheter axlar Stephanie den dagliga bördan att hålla barnen mätta, varma och skyddade. Till och med sådant grundläggande som rena kläder kräver mycket arbete och tid som hon sällan har över."},{t="Ett prov i medkänsla",b="Paladiner som vill bemästra lärdomarna i The Tome of Divinity får visa osjälvisk välgörenhet snarare än kampförmåga. Genom att lämna linnetygsrullar till Stephanie lättar en novis en omedelbar börda från hennes axlar, så att hon kan sy skjortor och byxor åt barnen och samtidigt ägna sig åt att ge dem tak över huvudet och mat. Med sådan anspråkslös hjälp visar Ljusets beskyddare sin hängivenhet till att skydda de svaga."},{t="Påfrestningar i huvudstaden",b="Stephanie kämpar vidare genom vardagens svårigheter, men hon säger att det här året har blivit märkbart hårdare. Hennes make tvingas göra långa och svåra resor ända till Ironforge för att hämta förnödenheter, och påfrestningen på vanligt folk speglar en större oro i kungariket. Även innanför huvudstadens höga stenmurar känns skuggorna från de senaste tragedierna i norr fortfarande starkt."}},faq={{q="Vem är Stephanie Turner?",a="Stephanie Turner är en omtänksam kvinna i Stormwind som vigt sitt liv åt att ta hand om barn som blivit föräldralösa efter Scourge. Hon arbetar outtröttligt för att ge dem mat, kläder och tak över huvudet och förlitar sig mycket på välgörenhet från samhället och på sin make Johns insatser.",al={"vem är stephanie turner","stephanie turner stormwind","barnhemsföreståndare"}},{q="Varför behöver Stephanie Turner linnetyg?",a="Stephanie behöver linnetyg för att sy skjortor och byxor åt de föräldralösa barnen. Hon har fullt upp med att skaffa mat och hålla deras hem i skick, så när hon får tyg slipper hon lägga tid och kraft på att själv samla material.",al={"varför linnetyg","vad används linnetyg till","tyg till stephanie"}},{q="Vem är John och vart har han rest?",a="John är Stephanie Turners make. Han reser bort från Stormwind för att samla viktiga förnödenheter och material, ända till dvärgstaden Ironforge, trots att han ogillar att vara borta från sin familj.",al={"vem är john","var är john","stephanie turners make"}},{q="Varför finns det så många föräldralösa barn i Stormwind?",a="De flesta barnen som Stephanie tar hand om förlorade sina familjer i Scourges förödande angrepp mot de nordliga kungarikena under det senaste årtiondet. Många av dessa föräldralösa barn fördes söderut till Stormwind av människor på flykt och överlevande.",al={"varför finns det föräldralösa i stormwind","scourge-föräldralösa stormwind","vad hände med barnens föräldrar"}},{q="Hur hänger hjälpen till Stephanie ihop med The Tome of Divinity?",a="The Tome of Divinity prövar en blivande paladins grundläggande dygder, framför allt välgörenhet och medkänsla. Den som hjälper en överbelastad vårdnadshavare med nödvändiga förnödenheter visar att Ljusets tjänare skyddar de enkla och utsatta lika gärna som de möter monster.",al={"innebörden av tome of divinity","varför är detta ett paladinuppdrag","paladinuppdrag om välgörenhet"}},{q="Vad menar Stephanie med ”något i luften”?",a="Stephanie säger att det här året har känts mycket hårdare än tidigare, som om något i luften varslar om en stor förändring, men hon medger att hon inte vet vad.",al={"dåligt år i stormwind","något i luften","stormwinds bekymmer"}}},fp="20,327,18.448.0,21.462.0,22.412.0,24.262.0,43.231.0,34.216.0,53.243.0,58.259.0,54.160.0"}
P.entries["quest:1645"] = {n="The Tome of Divinity",s="The Tome of Divinity markerar en viktig milstolpe i en dvärgpaladins träning i Ironforge. Tiza Battleforge överlämnar den i Hall of Mysteries. Den heliga texten inleder en prövningsresa som ska testa den invigdes hängivenhet till Ljuset och beredskap att försvara Azeroth mot mörka krafter som Scourge.",h="The Tome of Divinity markerar en viktig milstolpe i en dvärgpaladins träning i Ironforge.",kw={"book of divinity","hall of mysteries","holy light","ironforge","paladin","återlösning","scourge","tiza battleforge","tome of divinity"},ang={["class:Paladin"]="Denna övergångsrit knyter samman den tidiga stridsundervisningen med Holy Lights djupare dygder och visar de invigda vägen till att kanalisera återlösningens och uppståndelsens kraft.",["race:Dwarf"]="För dvärgkämpar stärker mottagandet av Tome of Divinity den trosallians som har smitts mellan Bronzebeard-kungariket och Silver Hands mänskliga riddare."},sec={{t="En kallelse till dygd",b="Paladinmentorer i Eastern Kingdoms hänvisar lovande invigda till Hall of Mysteries i Ironforge när de visar att de behärskar grunderna i stridskonst och andlighet. Under Tiza Battleforges vaksamma blick får unga dvärgpaladiner lära sig de högtidliga principer som skiljer en enkel krigare från en vigd kämpe för Holy Light. Att anta uppdraget innebär ett medvetet löfte om livslång självuppoffring, plikt och andlig disciplin."},{t="Dygdens bok",b="När novisen accepterar uppdraget får hen en Book of Divinity i sina händer. Texten beskriver de förväntningar, dygder och andliga grundsatser som krävs för att effektivt kunna använda heliga krafter mot onda hot. Att studera dess läror är bara det första steget. Skriften är en grundläggande vägledning innan den invigde skickas ut över Khaz Modan och vidare för att omsätta lärdomarna i verkliga trosgärningar."}},faq={{q="Vad är syftet med uppdraget Tome of Divinity?",a="Det här uppdraget är porten till avancerad paladinträning för dvärgkämpar. Genom att tala med Tiza Battleforge får de invigda sin heliga text och ger sig ut på en rad prövningar som ska visa deras dygd och låsa upp förmågan att återkalla fallna allierade från döden.",al={"vad gör tome of divinity","syftet med tome of divinity","varför göra det här uppdraget"}},{q="Vem är Tiza Battleforge?",a="Tiza Battleforge är en framstående paladintränare som bor i Hall of Mysteries i Ironforge. Hon har i uppgift att vägleda dvärgpaladiner mot större dygd, pröva deras hängivenhet till Ljuset och förbereda dem på att möta hot som Scourge.",al={"tiza battleforge","vem är paladintränaren i ironforge","vem ger tome of divinity"}},{q="Varför måste de invigda studera Book of Divinity?",a="Book of Divinity innehåller grundläggande läror om de plikter och dygder som Holy Light kräver. Studierna försäkrar att den invigde förstår den andliga disciplin som krävs innan hen använder mirakulösa heliga krafter.",al={"vad är book of divinity","varför läsa boken","book of divinity i historien"}},{q="Vilka stora hot förbereder sig dvärgpaladinerna på att bekämpa?",a="Som Tiza Battleforge beskriver det ägnar paladinerna sig åt att försvara Azeroth mot faror över hela landet, med särskild vaksamhet mot Scourges annalkande odöda hot.",al={"vilka slåss paladiner mot","varför träna paladiner i ironforge","paladinens syfte"}},{q="Var äger träningen rum?",a="Invigningen börjar i Hall of Mysteries, en fridfull helgedom i den norra delen av Ironforge där lärda, präster, magiker och paladiner samlas för bön och studier.",al={"var finns tiza battleforge","paladinernas plats i ironforge","paladin i hall of mysteries"}},{q="Vad händer när man har fått boken?",a="När den invigde har läst och begrundat Book of Divinity ger Tiza Battleforge praktiska prövningar där paladinen måste visa medkänsla, plikt och uppoffring utanför stadsmurarnas trygghet.",al={"vad händer sedan","nästa uppdrag efter tome of divinity","vart ska jag gå efter att ha fått boken"}}},fx={b6d4c081={q="Varför vill Tiza Battleforge att du studerar Tome of Divinity?",a="Tiza Battleforge ansvarar för paladinernas utbildning i Ironforge. Hon ser det som sin högtidliga plikt att vägleda noviser mot sann dygd och hängivenhet till det Heliga Ljuset. Med hotet från Scourge och andra faror över Azeroth vill hon se till att varje försvarare hon tränar förstår sitt andliga ansvar och är redo att använda större heliga krafter för att försvara riket.",al={"varför vill tiza att detta blir gjort","tiza battleforges motiv","varför studera tome of divinity"}},a71115f0={q="Varför ber Tiza Battleforge dig att genomgå provet i stället för att göra det själv?",a="Tiza kan inte gå dygdens väg åt dig. Som lärare i det Heliga Ljuset ska hon vägleda och undervisa, men den hängivenhet, förståelse och inre styrka som krävs av en sann paladin måste komma inifrån novisen. För att förtjäna Ljusets välsignelser och förmågor måste du själv visa din förmåga och hängivenhet genom studier och tjänst.",al={"varför jag ska studera tome of divinity","varför gör inte tiza det","varför måste jag studera boken"}}},fp="20,221,19.379.0,20.288.0,50.208.0,24.212.0,46.171.0,59.129.0,36.153.0,41.182.0"}
P.entries["quest:1646"] = {n="The Tome of Divinity",s="Tome of Divinity är ett grundläggande paladinuppdrag om de andliga dygder som vägleder heliga krigare. Mentorer som Tiza Battleforge i Ironforge lär noviser att sann hängivenhet till Ljuset kräver tålamod, medkänsla och ödmjuk tjänst för behövande, vid sidan av stridsstyrka.",h="Tome of Divinity är ett grundläggande paladinuppdrag om de andliga dygder som vägleder heliga krigare.",kw={"medkänsla","heliga ljuset","ironforge","paladin","tålamod","tome of divinity","tiza battleforge","gudomlighetens bok"},ang={["class:Paladin"]="Tome of Divinity introducerar unga paladiner till grundprinciperna i deras kall och betonar att medkänsla och tjänst är lika viktiga som stridsförmåga.",["race:Dwarf"]="Dvärgpaladiner i Ironforge får denna undervisning av mentorer som Tiza Battleforge, så att deras styrka leds av tålamod och dygd."},sec={{t="Gudomlighetens mått",b="Tome of Divinity är en viktig milstolpe i en paladins utbildning. Mentorer som Tiza Battleforge i Ironforge överlämnar texten och förankrar noviserna i det andliga syftet bakom deras stridsförmåga. Boken förhärligar inte herravälde eller gudomlighet, utan lär att sann gudomlighet ligger i att sträva efter moralisk godhet och vara ett stadigt redskap för Ljuset."},{t="Prövningar i tjänst och medkänsla",b="Ljusets krigare kallas ofta att slå ner ondska i Azeroth, men boken betonar att stridsstyrka inte ensam definierar en paladin. Medkänsla, tålamod och ödmjukhet skiljer dem från vanliga stridskämpar. Efter att ha studerat texten får noviser i uppdrag att genomgå prövningar i Ironforge och närliggande trakter. De ska utföra välgörenhet och tjänster för att visa att de är vid sina sinnens fulla bruk och hängivna utan att vackla."}},faq={{q="Vad är Tome of Divinity?",a="Tome of Divinity är en grundläggande lärobok som ges till paladiner under utbildning. Den lär ut att gudomlighet inte handlar om att söka gudaskap, utan om att sträva efter att göra gott, hjälpa de mindre lyckligt lottade och visa medkänsla, tålamod och mod.",al={"vad är tome of divinity","tome of divinity paladin","vad lär tome ut"}},{q="Vem är Tiza Battleforge?",a="Tiza Battleforge är en paladinmentor i Ironforge som vägleder nybörjare genom deras första prövningar och ser till att de förstår balansen mellan rättfärdig strid och osjälvisk tjänst.",al={"vem är tiza battleforge","tiza battleforge plats","var finns tiza"}},{q="Varför måste paladiner studera tålamod och medkänsla?",a="En paladins kraft kommer av att återspegla Ljuset, vilket kräver god karaktär och moralisk disciplin. Styrka i strid räcker inte utan det tålamod och den medkänsla som behövs för att försvara och lyfta andra.",al={"varför läsa tome","paladinens dygder","varför tålamod och medkänsla"}},{q="Vilka prövningar följer efter läsningen av boken?",a="Efter att ha läst texten måste paladiner visa sina dygder genom praktiska prov. Mentorer ger dem uppgifter i staden och de omgivande trakterna där de ska hjälpa behövande och bevisa sin hängivenhet till Ljuset.",al={"vad händer efter att tome har lästs","tome of divinity prövningar","nästa prövning efter läsningen"}},{q="Var äger den här prövningen rum?",a="Uppdraget leder paladinerna tillbaka till Tiza Battleforge i dvärgarnas huvudstad Ironforge när de har studerat bokens lärdomar.",al={"var lämnas uppdraget in","paladinuppdrag i ironforge"}},{q="Vad innebär det att sträva efter gudomlighet?",a="Enligt texten innebär strävan efter gudomlighet inte att eftertrakta gudaskap. I stället handlar det om att aktivt välja att göra gott i alla handlingar och använda Ljuset för att stödja och skydda Azeroths folk.",al={"vad innebär det att sträva efter gudomlighet","paladin gudaskap"}}},fp="20,318,23.392.0,32.429.0,29.229.0,24.190.0,48.216.0,35.213.0,33.142.0,41.207.0"}
P.entries["quest:1647"] = {n="The Tome of Divinity",s="The Tome of Divinity är ett tidigt heligt prov som de Ljusets noviser genomgår i Ironforge. En mentor i stadens tempel skickar den prövade att leta efter någon i den yttre ringen som har goda avsikter och verkligen behöver hjälp. När de hittar den hängivne arbetaren John Turner lär sig noviserna att osjälvisk tjänst och medkänsla är centrala för att följa Ljusets väg.",h="The Tome of Divinity är ett tidigt heligt prov som de Ljusets noviser genomgår i Ironforge.",kw={"ironforge","john turner","ljuset","barnhem","paladin","tempel","the tome of divinity","tome of divinity"},ang={["class:Paladin"]="Det här uppdraget är ett viktigt prov på vägen att följa Ljuset. Det lär paladiner att sann hängivenhet börjar med att osjälviskt hjälpa vanliga människor i nöd.",["faction:Alliance"]="Uppdraget lyfter fram de dygder som förenar Alliansen: medkänsla, välgörenhet och omsorg om utsatta i städer som Ironforge.",["race:Dwarf"]="Provet utspelar sig i Ironforge, dvärgarnas huvudstad, och prövar lokala dvärglärjungar till Ljuset i deras egen hemstads salar."},sec={{t="En lektion i medkänsla",b="The Tome of Divinity är ett formande prov för Ljusets noviser i Ironforge. I stället för att pröva stridsförmåga eller kräva skicklighet i kamp mot fiender beordrar novisens mentor dem att bege sig ut i den livliga dvärgstaden och hitta någon som verkligen behöver hjälp. Uppgiften kräver urskillning: novisen måste hitta någon med ett rent hjärta, ädla avsikter och ett verkligt behov av andras vänlighet. Därmed visar novisen att ödmjuk tjänst är grunden för det heliga kallet."},{t="John Turners börda",b="Sökandet leder lärjungarna till den yttre ringen i Ironforge, där en anspråkslös arbetare vid namn John Turner arbetar. Turner blir överraskad av besökarna medan han ropar om Orphanage of Stormwind och berättar om det stillsamma offer som präglar hans vardag. Han sliter långa dagar och är skild från sin älskade hustru, allt för att föräldralösa barn ska ha kläder på kroppen och mat på bordet. Genom att hjälpa Turner upptäcker noviserna barmhärtighetens verkliga tyngd innan de återvänder till templet för att fortsätta sin färd i Ljusets tjänst."}},faq={{q="Vad är uppdraget The Tome of Divinity?",a="The Tome of Divinity är ett heligt prov för dem som vill tjäna Ljuset i Ironforge. Novisen ska söka upp och hjälpa någon i staden som har ett rent hjärta och ädla motiv, innan de andliga studierna fortsätter.",al={"vad är tome of divinity","syftet med tome of divinity","vad är det här för uppdrag"}},{q="Vem är John Turner?",a="John Turner är en hårt arbetande man som finns i den yttre ringen i Ironforge. Han arbetar outtröttligt, långt från sin älskade hustru, för att samla resurser och ge mat och kläder åt föräldralösa barn i nöd.",al={"vem är john turner","john turner ironforge","var finns john turner"}},{q="Varför skickar mentorn dig för att hitta någon i nöd?",a="Provet prövar novisens förståelse för medkänsla och tjänande. I stället för att slåss mot monster måste en Ljusets tjänare först lära sig att känna igen ädla avsikter, visa vänlighet och vägleda dem som arbetar stillsamt för andras bästa.",al={"varför hitta någon i nöd","syftet med att hjälpa john turner","varför göra det här provet"}},{q="Var i Ironforge finns John Turner?",a="John Turner kan hittas när han går längs den yttre ringen i Ironforge, där han utför sitt krävande dagliga arbete för barnhemmet.",al={"var hittar man john turner","john turners plats","hur hittar man john turner"}},{q="Vad händer när du har talat med John Turner?",a="När du har hittat John Turner och hört om hans svåra situation återvänder du till mentorn i templet för att begrunda vad det verkligen innebär att följa Ljusets väg och förbereda dig för nästa steg i ditt kall.",al={"vad händer när man har hittat john turner","återvänd till ljusets tempel","tome of divinity nästa steg"}},{q="Varför ropade John Turner om ett barnhem?",a="När du först närmar dig John Turner börjar han ropa om Orphanage of Stormwind, men hejdar sig och ber om ursäkt. Hans arbete går ut på att hjälpa de föräldralösa barn som är beroende av välgörenhet för att få mat och kläder.",al={"vilket barnhem ropar john turner om","stormwinds barnhem i ironforge","varför ropade john turner"}}},fp="20,369,22.515.0,25.541.0,35.249.0,19.183.0,53.242.0,42.131.0,45.202.0,48.224.0"}
P.entries["quest:1648"] = {n="The Tome of Divinity",s="The Tome of Divinity uppmanar Ljusets tjänare att visa ödmjuk medkänsla i Ironforge. Att hjälpa John Turner, som driver ett barnhem i Stormwind för barn som tvingats på flykt undan Scourge, prövar en novis hängivenhet åt osjälviskhet och välgörenhet framför krigisk ära.",h="The Tome of Divinity uppmanar Ljusets tjänare att visa ödmjuk medkänsla i Ironforge.",kw={"det heliga ljuset","ironforge","john turner","linnetyg","paladin","scourges föräldralösa barn","stormwinds barnhem","the tome of divinity"},ang={["class:Paladin"]="Paladiner genomgår detta prov utan svärd eller stridskonst. I stället hjälper de osjälviskt de oskyldiga och förkroppsligar den medkänsla som är central för det heliga ljuset.",["faction:Alliance"]="Ärendet blottlägger de djupa sår i människornas vardagsliv som Scourge lämnade efter sig och visar hur Stormwind och Ironforge är beroende av varandra."},sec={{t="Välgörenhet i Great Forge",b="The Tome of Divinity ger den som vandrar Ljusets väg ett prov som inte handlar om vapen, utan om välgörenhet. I Ironforges myllrande salar söker en barmhärtighetens budbärare vid namn John Turner hjälp. Turner och hans hustru driver ett barnhem i kungariket Stormwind, där de tar hand om barn som blivit föräldralösa efter Scourges katastrofala härjningar under det senaste årtiondet. Hans resa till dvärgarnas huvudstad speglar de prövningar som Alliansens vanligt folk delar."},{t="Scourges ärr",b="Det är ingen enkel sak att samla förnödenheter över gränser. En tillströmning av hantverkare i arbete över Azeroth har satt lokal försörjning under press och gjort enkla material svåra att få tag på. Turners resa till Ironforge för att vädja till samhällsgrupper och invånare gick i stå efter veckor med knappa framsteg. Han saknar linnetyget som hans hustru behöver för att sy kläder åt barnen. Genom att erbjuda tyget utan att kräva betalning visar en Ljusets tjänare den osjälviska hängivenhet som ligger till grund för deras heliga kall."}},faq={{q="Vem är John Turner?",a="John Turner är en mänsklig föreståndare som driver ett barnhem i Stormwind tillsammans med sin hustru. Ungefär en gång i månaden reser han till Ironforge för att söka förnödenheter och välgörenhet från dvärgarnas invånare och köpmannagillen, till stöd för barn som blivit föräldralösa i krig.",al={"vem är john turner","john turners bakgrund","ironforge och turner"}},{q="Varför behöver John Turner linnetyg?",a="Turner behöver linnetyg så att hans hustru i Stormwind kan sy varma kläder åt barnen på barnhemmet. En tillströmning av hantverkare och förändrad handel i Azeroth har gjort grundläggande tyger sällsynta och svåra att få tag på.",al={"varför linne","varför behöver john turner tyg","linne till barnhemmet"}},{q="Varför finns det så många föräldralösa barn i Stormwind?",a="Barnen som makarna Turner tar hand om förlorade sina föräldrar under Scourges förödande angrepp under det senaste årtiondet. Det tredje kriget slog sönder många familjer i människorikena och lämnade många unga utan hem.",al={"föräldralösa barn på stormwinds barnhem","varför finns det föräldralösa barn","scourges föräldralösa barn"}},{q="Varför reste John Turner till Ironforge?",a="Turner reser över bergen till Ironforge för att vädja till dvärgarnas invånare och olika handelsgrupper om gåvor och förnödenheter som annars är svåra att få tag på i Stormwind.",al={"varför är john turner i ironforge","varför ironforge för stormwinds barnhem"}},{q="Hur hänger hjälpen till ett barnhem ihop med det heliga ljuset?",a="Det heliga ljuset kräver osjälviskhet, barmhärtighet och tjänande av dem som är förtvivlade. Att hjälpa en utmattad föreståndare att försörja krigets föräldralösa barn prövar blivande paladiner i ödmjukhet och välgörenhet, snarare än i stridsstyrka.",al={"vad har detta med ljuset att göra","paladinernas koppling","varför gör paladiner detta uppdrag"}},{q="Varför har John Turners resa till Ironforge varit så svår?",a="Turners resa har gått plågsamt långsamt och till största delen varit resultatlös eftersom det råder brist på lokala förnödenheter och få grupper har erbjudit hjälp. Därför kan han inte återvända hem förrän han säkrat en leverans.",al={"har john turner fastnat","varför går resan långsamt"}}},fp="20,282,26.481.0,24.530.0,19.240.0,38.230.0,43.236.0,40.183.0,55.239.0,58.218.0"}
P.entries["quest:1649"] = {n="The Tome of Valor",s="Duthorian Rall väntar i Stormwind på paladiner som söker prövningar i tro och mod. Tome of Valor vägleder deras första steg mot att bevisa sin hängivenhet till kyrkan.",h="Duthorian Rall väntar i Stormwind på paladiner som söker prövningar i tro och mod.",kw={"cathedral of light","church of the holy light","duthorian rall","tro","paladin","stormwind","tome of valor","mod"},ang={["class:Paladin"]="Som paladin markerar den här prövningen ett avgörande steg i din utveckling. Den förenar dina stridskunskaper med disciplinerad tro och osjälvisk tjänst.",["faction:Alliance"]="Som medlem i Alliansen delar du den styrka som Stormwinds prövningar bevarar, både i försvaret och i anden under oroliga tider."},sec={{t="Att härda anden",b="Tome of Valor lär att mod måste smidas genom umbäranden. Den heliga texten liknar dygder vid ädla malmer, värdefulla när de hittas men i behov av förädling för att hålla. Genom svåra prövningar och sann hängivenhet förenar en paladin tro, medkänsla och mod till en styrka som kan stå emot ondskan som hotar Azeroth."},{t="Att vända sig till kyrkan",b="När du har läst Tome of Valor hänvisas du till Duthorian Rall, en respekterad ledare bland paladinerna i Cathedral of Light i Stormwind. Han tar emot framställningar från dem som söker modets prövningar. Proven är ingen enkel ritual: att försvara de oskyldiga och värna kyrkan kan kosta dig livet, och endast de ståndaktiga vinner erkännande i orden."}},faq={{q="Vad är syftet med det här uppdraget?",a="Tome of Valor vägleder en novis från helig lära till farliga prövningar. Efter att ha läst den vänder sig blivande paladiner till Duthorian Rall i Cathedral of Light för att prövas i tro och mod.",al={"vad är uppdraget tome of valor","varför behöver jag det här uppdraget","syftet med tome of valor"}},{q="Vem är Duthorian Rall?",a="Duthorian Rall är en högt uppsatt paladin och lärare i Cathedral of Light i Stormwind. Han övervakar träningen av lovande försvarare och de prövningar som visar en novis värde för kyrkan.",al={"vem är duthorian rall","duthorian ralls historia","paladintränare i katedralen"}},{q="Varför prövar kyrkan sina paladiner så hårt?",a="Church of the Holy Light prövar paladiner så att de kan stå stadigt mot förtvivlan och våld. Vacklande beslutsamhet eller svag tro kan kosta liv i strid, så lärarna prövar och härdar varje novis före viktiga heliga uppdrag.",al={"varför är paladinprövningar farliga","varför prövas mod"}},{q="Var äger den här prövningen rum?",a="Du lämnar din framställan till Duthorian Rall i Cathedral of Light, mitt i Cathedral Square i Stormwind City.",al={"var lämnar jag in tome of valor","duthorian ralls plats"}}},fx={["5e1febd2"]={q="Varför hänvisar Tome of Valor dig till Duthorian Rall?",a="Texten i Tome of Valor är en andlig och moralisk vägledning som betonar att dygder som tro och mod måste prövas i handling och formas till en orubblig beslutsamhet. Den skickar dig till Duthorian Rall i Stormwind eftersom prövningar inte räcker att läsa om. En blivande paladin måste vända sig direkt till ledningen för Cathedral of Light och visa att hängivenheten kan stå emot ett dödligt offer.",al={"varför måste jag tala med duthorian rall","varför duthorian rall och tome of valor","varför skicka mig till rall"}}},fp="17,168,20.325.0,22.354.0,34.197.0,22.196.0,50.230.0,33.120.0"}
P.entries["quest:165"] = {n="The Hermit",s="När en äldre enstöring har varit borta länge ber Elaine Carevin i Darkshire resande att se till honom. Den ensamme gamle mannen Abercrombie bor i en ranglig koja precis vid kanten av Raven Hill Cemetery.",h="När en äldre enstöring har varit borta länge ber Elaine Carevin i Darkshire resande att se till honom.",kw={"abercrombie","darkshire","duskwood","elaine carevin","raven hill cemetery","koja","enstöringen"},ang={["faction:Alliance"]="The Night Watch kämpar för att skydda vägarna mellan Darkshire och Raven Hill, vilket gör att avlägsna enstöringar som Abercrombie blir helt avskurna från tryggheten i staden.",["race:Human"]="Familjen Carevin står för de starka grannbanden i Duskwood och håller ett öga på traktens egenartade äldre, även när regionen sjunker in i skuggorna."},sec={{t="Ett vänskapligt besök",b="I en hårt ansatt bosättning som Darkshire är det lätt att tappa bort egenartade enstöringar, tills deras frånvaro börjar oroa folk. Elaine Carevin minns en gammal man som brukade ta sig in till staden för att köpa förnödenheter, men plötsligt försvann. Med tanke på farorna som ständigt hemsöker vägarna i Duskwood ber hon kringvandrande äventyrare undersöka hans koja, med utsikt över det hemsökta området vid Raven Hill Cemetery, för att se till att han inte gått ett dystert öde till mötes."},{t="Enstöringen vid Raven Hill",b="När du kommer fram till den ensliga kojan ser du att dess invånare, en gammal man vid namn Abercrombie, fortfarande är vid liv. Han småskrattar när Carevins nämns och hävdar att hans långa frånvaro bara beror på åldern och de förrädiska monster som stryker omkring i skogen. Lättad över att ha en kapabel resande vid dörren ber Abercrombie genast om hjälp med några ärenden."}},faq={{q="Vem startar det här ärendet?",a="Elaine Carevin, som bor i Darkshire i Duskwood, startar uppdraget eftersom hon oroar sig för en gammal enstöring som brukade köpa förnödenheter i staden.",al={"vem ger enstöringen","var börjar enstöringen","elaine carevin uppdrag"}},{q="Var finns enstöringen?",a="Abercrombie bor i en förfallen träkoja vid den norra kanten av Raven Hill Cemetery, i västra Duskwood.",al={"var finns abercrombie","enstöringens plats i duskwood","koja nära raven hill"}},{q="Varför oroade sig Elaine Carevin för honom?",a="Abercrombie brukade regelbundet besöka Darkshire för att köpa förnödenheter, men slutade plötsligt att synas. Med vilddjur och odöda längs vägarna fruktade hon att han hade omkommit.",al={"varför se till abercrombie","varför är elaine orolig","vad hände med den gamle mannen"}},{q="Är Abercrombie faktiskt i fara när du hittar honom?",a="Nej. När du kommer fram till hans koja är Abercrombie vid liv och mår bra. Han roas stillsamt av stadens oro och förklarar att de farliga vägarna och hans höga ålder gjorde resorna för ansträngande.",al={"mår abercrombie bra","håller enstöringen på att dö","blev enstöringen attackerad"}},{q="Varför väljer någon att bo precis intill Raven Hill Cemetery?",a="Abercrombie säger att han föredrar avskildheten, även om många resande tycker att det är obehagligt att bo i skuggan av en av de mest nekromantisk-korrumperade begravningsplatserna i Eastern Kingdoms.",al={"varför bo vid raven hill","abercrombies koja vid begravningsplatsen","varför bor enstöringen nära gravar"}},{q="Vad ber Abercrombie om när du kommer fram?",a="Abercrombie är ivrig att dra nytta av att ha en stark äventyrare vid sin dörr och ber genast om hjälp med olika ärenden och uppgifter i skogen.",al={"vad vill abercrombie","uppföljningsuppdrag för enstöringen","vad kommer efter enstöringen"}}},fx={e8a34d53={q="Varför ber Elaine Carevin en äventyrare att se till Abercrombie?",a="Darkshires lokala Night Watch är redan farligt hårt pressade med att hålla ytterområdena mot glupska bestar, vilda worgen och The Restless Dead. Stadens vakter kan inte avvara folk för att bege sig djupt in i de västra skogarna mot Raven Hill bara för att se till en egensinnig eremit. Dugliga resenärer är det enda verkliga alternativet.",al={"varför skicka mig","varför behöver elaine en äventyrare","varför ser inte vakterna till eremiten"}}},fp="10,186,21.215.0,25.236.0,23.110.0,28.100.0,41.133.0,52.110.0,66.157.0,49.77.0"}
P.entries["quest:1650"] = {n="The Tome of Valor",s="Duthorian Rall skickar en paladin för att skydda Daphne Stilwell vid Westfalls avlägsna kust. När hennes make är bortrest hotar Defias banditer hennes gård.",h="Duthorian Rall skickar en paladin för att skydda Daphne Stilwell vid Westfalls avlägsna kust.",kw={"daphne stilwell","defias brotherhood","duthorian rall","jordan stilwell","longshore","stormwind","tome of valor","westfall"},ang={["class:Paladin"]="Som paladin lämnar du tryggheten vid Cathedral of Light i Stormwind för att skydda de försvarslösa och bevisa din tapperhet.",["faction:Alliance"]="Familjen Stilwells gård visar hur långt Westfall har fallit utanför Stormwinds beskydd och hur landsbygdens folk lämnats att möta Defias på egen hand."},sec={{t="En maning till vapen",b="I Cathedral of Light i Stormwind prövar Duthorian Rall blivande paladiner genom att be dem försvara rikets folk. När du har tagit på dig tapperhetens mantel omsätter du idealen i handling där lag och myndigheter har svikit."},{t="Fara vid Longshore",b="Daphne Stilwell och hennes make Jordan håller en utpost vid Westfalls avskilda Longshore. Jordan är i Ironforge för att rådfråga dvärgiska smeder, och Defias Brotherhood är mycket aktivt. Duthorian skickar dig västerut för att skydda Daphne innan tjuvarna övermannar henne och tar gården."}},faq={{q="Varför är Daphne Stilwell ensam i Westfall?",a="Hennes make, Jordan Stilwell, reste till Ironforge för att rådfråga andra smeder. Medan han är borta måste Daphne ensam hantera de allt fler Defias-angreppen mot deras kustfastighet.",al={"var är daphnes make","varför är jordan stilwell borta","daphne stilwell ensam"}},{q="Vem ger paladinen uppdraget?",a="Duthorian Rall ger dig uppdraget. Han tränar paladiner vid Cathedral of Light i Stormwind och ger ordern när du visat dig redo för tapperhetsprövningarna.",al={"vem ger tome of valor 1650","uppdragsgivare tome of valor","duthorian rall uppdrag"}},{q="Var hittar man Daphne Stilwell?",a="Daphne bor i en liten stuga längst söderut på Longshore, längs kusten i sydvästra Westfall.",al={"var är daphne stilwell","daphne stilwell plats","hitta daphne stilwell"}},{q="Är Daphne helt hjälplös när du anländer?",a="Nej. När du kommer fram till hennes veranda har Daphne redan dödat ett halvdussin Defias-banditer med sitt eget vapen medan hon försvarade gården.",al={"kan daphne slåss","är daphne försvarslös","daphne stilwell slåss"}},{q="Vilket hot riktas mot familjen Stilwells hem?",a="Defias Brotherhood hotar familjen Stilwells hem. Brödraskapet har tagit över stora delar av Westfall och fortsätter att trakassera den avskilda kustgården. De vill lägga beslag på marken och plundra det som finns kvar.",al={"vem anfaller daphne","defias i westfall","fiender vid stilwells gård"}},{q="Hur passar det här uppdraget in i Tome of Valor-kedjan?",a="Paladinens tapperhet mäts genom uppoffring och försvar av de försvarslösa. När du skyddar Daphne mot härjande banditer omsätter du rättfärdigheten i handling.",al={"varför måste jag hjälpa daphne","syftet med tome of valor-prövningen","vad uppdraget betyder"}}},fx={ef242344={q="Varför skickar Duthorian Rall dig till Daphne Stilwell?",a="Duthorian Rall vill pröva din beslutsamhet och hängivenhet till Ljusets dygder. Medan hennes make Jordan reser till Ironforge för att utbyta smideskunskaper har Daphne Stilwell lämnats ensam i Westfall, just när Defias Brotherhood härjar längs kusten. Att skicka dig för att försvara en oskyddad civilperson är både en rättfärdig plikt och ett sant modprov.",al={"varför vill duthorian rall detta","duthorian ralls motiv","varför skicka en paladin till daphne"}},["49096f91"]={q="Varför behöver Duthorian Rall dig i stället för Stormwinds stadsvakt?",a="Westfall ligger långt utanför tryggheten bakom Stormwinds murar, försummat av kronan och översvämmat av banditer. Stadsvakten är hårt pressad med att försvara Elwynn och hantera oroligheter i staden. För det Heliga Ljusets kyrka är det paladinernas högtidliga plikt att skydda försvarslösa jordbrukare. Det gör detta farliga uppdrag till den perfekta prövningen för att visa att du förtjänar Tome of Valor.",al={"varför jag för duthorian rall","varför inte skicka vakter till daphne","varför skicka en novis"}}},fp="17,148,14.221.0,22.280.0,41.169.0,37.145.0,35.104.0,46.141.0,42.200.0,52.149.0"}
P.entries["quest:1651"] = {n="The Tome of Valor",s="På Daphne Stilwells gård i Westfall ställs en paladin inför ett modprov. Defias Brotherhood hotar gården, och Daphne behöver en försvarare vid sin sida.",h="På Daphne Stilwells gård i Westfall ställs en paladin inför ett modprov.",kw={"daphne stilwell","defias brotherhood","defias-rövare","paladinens prövning","tome of valor","westfall"},ang={["class:Paladin"]="Som paladin prövas du som en ståndaktig beskyddare. När du håller stånd vid Daphnes sida visar du mod i handling: du skyddar de oskyldiga från skada.",["faction:Alliance"]="Stormwinds garnison är utspridd och kan inte vakta gårdarna på landsbygden. Det faller på enskilda hjältar att försvara Westfalls lojala invånare."},sec={{t="En ståndaktig hållning i dammet",b="Daphne Stilwells gård i Westfall ligger i ett område som Defias Brotherhood gör anspråk på. När du söker dygderna som beskrivs i Tome of Valor får du i uppdrag att försvara hennes gård. Defias har upprepade gånger försökt ta över egendomen och döda Daphne. Efter tidigare sammandrabbningar väntas ännu ett anfall. Du måste stå vid hennes hus i stället för att retirera till säkrare mark."},{t="Modprovet",b="Daphne och du möter våg efter våg av Defias-rövare. Hon har bara sitt eget skjutvapen, medan du har den Heliga Ljusets välsignelser. Striden prövar om du kan skydda någon sårbar under hård press. Sant mod handlar inte om att söka personlig ära, utan om viljan att stå mellan oskyldiga civila och hänsynslöst våld."}},faq={{q="Vem är Daphne Stilwell?",a="Daphne Stilwell är en mänsklig gårdsägare som bor bland grässlätterna i Westfall. Trots att Defias Brotherhood regelbundet tränger in på hennes mark vägrar hon att ge sig av och slår tillbaka mot deras räder.",al={"daphne stilwell","vem är daphne","stilwell westfall"}},{q="Varför anfaller Defias just den här gården?",a="Defias Brotherhood har tagit över stora delar av landsbygden i Westfall och drivit bort bönder eller tvingat dem att underkasta sig. Daphnes make Jordan är i Ironforge, så hon är ensam och oskyddad, och Defias vill åt hennes mark.",al={"varför anfaller defias","defias anfaller daphne","varför anfalla stilwell"}},{q="Vad är Tome of Valor?",a="Tome of Valor är en helig skrift som den Heliga Ljusets kyrka använder för att vägleda unga paladiner. Riddare under utbildning genomgår fysiska och andliga prövningar runt om i kungariket för att leva efter dess dygder.",al={"vad är tome of valor","tome of valor-uppdrag","paladinens tome of valor-mod"}},{q="Vad händer om Daphne faller i striden?",a="Om Daphne Stilwell faller i striden misslyckas prövningen. Mod innebär att skydda hennes liv såväl som ditt eget från banditernas anfall.",al={"kan daphne dö","daphne stilwell dör"}},{q="Var äger anfallet rum?",a="Anfallet sker utanför Daphne Stilwells bondgård, en liten gård i Dagger Hills med utsikt över Longshore i södra Westfall.",al={"daphne stilwells plats","var ligger gården"}},{q="Vad händer efter att gården försvarats?",a="När du bevisat ditt mod och drivit bort Defias-rövarna erkänner Daphne din hängivenhet och visar dig vidare till nästa del av dina paladinprövningar.",al={"nästa uppdrag tome of valor","efter att ha försvarat daphne"}}},fx={dca50aad={q="Varför behöver Daphne Stilwell din hjälp med att försvara gården?",a="Stormwinds armé har i stort sett övergett Westfall, så jordbrukarna måste själva försvara sig mot den växande strömmen av laglösa. Daphne är fast besluten att försvara sitt hem och har ett skjutvapen inomhus, men hon kan inte stå ensam mot ett organiserat anfall. En tidigare våg har redan satt henne på prov, och hon vet att nästa räd kommer att bestå av fler laglösa än en ensam bosättare någonsin kan hoppas överleva.",al={"varför hjälpa daphne stilwell","varför kan inte daphne försvara sig själv","varför daphne stilwell behöver hjälp"}},["3da31dda"]={q="Varför vill Daphne Stilwell göra motstånd?",a="Den här gården är Daphne Stilwells levebröd och symboliserar hennes envisa vägran att låta laglösa driva bort henne. I stället för att fly eller överlåta marken åt rövare som tagit över Westfall väljer hon att stå på sig. Att skydda sitt hem är en fråga om ren överlevnad och stolthet. Ger hon efter här förlorar hon allt hon byggt upp.",al={"daphne stilwells motiv","varför bekämpa defias för daphne","varför vill daphne stanna"}},["7af5f29f"]={q="Vilka Defias-angripare går till angrepp mot Daphne Stilwells gård?",a="Angriparna är Defias-rövare, medlemmar av det utbredda kriminella brödraskap som terroriserar Westfall. De opererar i hela regionen, tar över övergivna gårdar, pressar invånarna på pengar och driver med våld bort alla som trotsar deras närvaro. Daphne vägrar överge sitt hem, och därför blir gården ett självklart mål för en samordnad räd som ska krossa allt kvarvarande civilt motstånd.",al={"vilka är angriparna","vad är defias-rövare","defias angriper stilwells gård"}}},fp="17,163,19.375.0,18.346.0,23.194.0,48.225.0,26.191.0,47.132.0,34.140.0,36.158.0"}
P.entries["quest:1652"] = {n="The Tome of Valor",s="Vid Cathedral of Light i Stormwind kommer besked om att Daphne Stilwell är i säkerhet. Efter att ha försvarat sitt hem i Westfall mot banditer rapporterar en blivande paladin till Duthorian Rall och fullbordar därmed Church of the Holy Lights prövningar i mod. Church of the Holy Light har i uppdrag att skydda de oskyldiga utan tanke på sig själv.",h="Vid Cathedral of Light i Stormwind kommer besked om att Daphne Stilwell är i säkerhet.",kw={"cathedral of light","daphne stilwell","duthorian rall","ironforge","jordan stilwell","stormwind","tome of valor","westfall"},ang={["class:Paladin"]="Som paladin fullbordar du din läxa i mod när du rapporterar till Duthorian Rall, och visar den självuppoffring som förväntas av en helig beskyddare av Alliansen.",["faction:Alliance"]="Som medlem i Alliansen kan du se hur familjen Stilwells bekymmer knyter samman människornas jordbruk i Westfall med dvärgarnas verkstäder i Ironforge. Deras historia visar hur Alliansen är beroende av hjälp mellan avlägsna länder."},sec={{t="En helig sköld",b="Daphne Stilwells hem i Westfall är i säkerhet efter att en novis i Church of the Holy Light försvarat det mot banditer. Tillbaka vid Cathedral of Light i Stormwind rapporterar den blivande paladinen till Duthorian Rall att hon är i säkerhet. Försvaret visar det mod och den övertygelse som förväntas av den som står mellan faran och de försvarslösa."},{t="Band mellan kungariken",b="Daphnes make, Jordan Stilwell, befinner sig i Ironforge, där han bidrar till Alliansen med sitt välkända hantverk. Nu när Daphne är i säkerhet och hemmet skyddat förbereder sig Duthorian Rall på att skicka bud norrut till Jordan. När hantverkaren vet att familjen är trygg kan han koncentrera sig på sitt arbete. Deras avlägsna hem knyts samman genom den hjälp Alliansen ger över sina länder."}},faq={{q="Vem är Duthorian Rall?",a="Duthorian Rall är en erfaren paladintränare vid Cathedral of Light i Stormwind. Han vägleder unga paladiner genom andliga och stridstekniska prövningar och lär dem mod, rättfärdighet och ödmjukhet.",al={"duthorian rall","vem är duthorian","paladintränare stormwind"}},{q="Varför var Daphne Stilwell i fara?",a="Daphne Stilwell var i fara eftersom banditer belägrade hennes avlägsna gård i Westfall. Hennes make Jordan var bortrest och arbetade i Ironforge.",al={"daphne stilwell","stilwells gård","vem attackerade daphne"}},{q="Vem är Jordan Stilwell?",a="Jordan Stilwell är Daphnes make, en skicklig smed och hantverkare. Han befinner sig i Ironforge och hjälper Alliansen med sitt arbete medan Church of the Holy Light skyddar hans hustru därhemma.",al={"jordan stilwell","daphnes make","jordan ironforge"}},{q="Vad är Tome of Valor?",a="Tome of Valor är en helig bok med lärdomar som hör samman med praktiska prövningar från Cathedral of Light. Genom dem bevisar paladiner sitt mod när de möter mörkret och skyddar de utsatta med risk för sig själva.",al={"tome of valor betydelse","vad är tome of valor"}},{q="Vad händer när prövningen är avklarad?",a="När Duthorian Rall har bekräftat att du försvarat Daphne Stilwell vägleder han dig vidare till Test of Righteousness, nästa steg i din andliga och stridstekniska utveckling.",al={"nästa uppdrag efter tome of valor","vad händer härnäst"}},{q="Varför bryr sig Church of the Holy Light om familjen Stilwells hem?",a="Church of the Holy Light bryr sig om familjen Stilwells hem eftersom Daphne och Jordan har hjälpt kyrkan genom trogen tjänst och sitt hantverk. Att skydda Daphne medan Jordan är borta hedrar kyrkans löfte att ta hand om de sina.",al={"varför hjälper kyrkan daphne","kyrkan och familjen stilwell"}}},fx={["9332b34b"]={q="Varför vill Daphne Stilwell att du ska rapportera tillbaka till Duthorian Rall?",a="Daphne vill att Duthorian Rall ska få veta att hon är i säkerhet och att gården klarade angreppet, men hennes största oro gäller maken Jordan. Jordan arbetar i Ironforge, och Daphne vet att han kommer att oroa sig tills han får höra hur det står till där hemma. Om du rapporterar tillbaka till Ljusets kyrka i Stormwind kan Duthorian skicka bud till Ironforge och försäkra Jordan om att hans fru och hem är trygga.",al={"varför skicka bud till duthorian","daphne stilwells motiv","varför tala med duthorian rall"}}},fp="17,316,15.335.0,21.361.0,22.185.0,34.134.0,23.171.0,26.211.0,39.171.0,54.217.0"}
P.entries["quest:1653"] = {n="The Test of Righteousness",s="I Ironforge får Jordan Stilwell glada nyheter om sin hustru. Duthorian Rall skickar dig från Westfall för att berätta för den gudfruktige smeden att Daphne överlevde Defias attack.",h="I Ironforge får Jordan Stilwell glada nyheter om sin hustru.",kw={"daphne stilwell","defias brotherhood","dun morogh","duthorian rall","ironforge","jordan stilwell","stormwind","rättfärdighetens prövning"},ang={["class:Paladin"]="Som paladin går du från att skydda de svaga till att skapa heliga redskap för att rena ondskan i Alliansens länder.",["faction:Alliance"]="Som medlem av Alliansen ser du hur vanligt folk i Westfall kämpar mot Defias medan kungliga rådgivare i Stormwind skjuter upp sina åtgärder.",["profession:Blacksmithing"]="Som smed kan du se hur Jordans arbete vid städet uttrycker hans hängivenhet lika tydligt som när han svingar ett konsekrerat svärd i strid."},sec={{t="En budbärare med goda nyheter",b="Duthorian Rall skickar dig från Cathedral Square med nyheter till Jordan Stilwell. Du har skyddat Daphne Stilwell under ett Defias-bakhåll vid hennes gård i Westfall, och hon överlevde. Hennes make reste till Ironforge i tron att hans familj var i fara. Rall ber dig framföra nyheten personligen, så att Jordan får veta att hans hustru är trygg."},{t="Smeden från Dun Morogh",b="Jordan Stilwell var en gång ämnad att ansluta sig till paladinerna, men valde att följa sin fars hantverk och bli vapensmedsmästare. Han arbetar vid sitt städ utanför Ironforges portar och bevarar sin tro medan han formar vapen. När du berättar att Daphne överlevde Defias attack fylls han av tacksamhet och hjälper dig att smida ett välsignat rättfärdighetens vapen."}},faq={{q="Vem är Jordan Stilwell?",a="Jordan Stilwell är en gudfruktig vapensmed som arbetar utanför Ironforges portar. Han studerade en gång Ljusets vägar tillsammans med paladiner, men valde sedan att fortsätta sin fars smideshantverk.",al={"jordan stilwell","vem är jordan","smeden i ironforge"}},{q="Varför var Jordans hustru i fara?",a="Daphne Stilwell bor på en gård i Westfall, där laglösa ur Defias Brotherhood hotar folket. Jordan fruktade att gården skulle angripas när han reste till Ironforge. Banditer stormade gården, men paladinnoviser drev bort dem.",al={"daphne stilwell i fara","vad hände med jordans hustru","varför attackerade defias"}},{q="Var kan Jordan Stilwell hittas?",a="Jordan Stilwell arbetar utanför Ironforges huvudportar i Dun Morogh. Han föredrar bergsluften framför Great Forge inne i staden.",al={"var finns jordan stilwell","stilwells plats","jordans plats i ironforge"}},{q="Varför skickar Duthorian Rall spelaren till Ironforge?",a="Duthorian Rall skickar dig för att berätta för Jordan att Daphne överlevde Defias attack. Resan för dig också till en mästersmed som kan vägleda dig i att tillverka ett heligt paladinvapen.",al={"varför åka till ironforge","duthorian ralls ärende","orsak till meddelandet"}},{q="Vad händer efter att du talat med Jordan?",a="När Jordan hört nyheten erbjuder han sig att hjälpa dig smida en helig stridshammare. Han ber dig samla sällsynta material och helgade reliker från avlägsna länder.",al={"nästa steg i rättfärdighetens prövning","vad vill jordan","efter samtalet med jordan"}},{q="Vad tycker Jordan om hotet från Defias?",a="Jordan är arg på Stormwinds råd och dess försummelse. Defias Brotherhood har plågat Westfall länge, och han hoppas att angrepp på hederliga gårdar ska tvinga pojkkungens regenter att ta itu med krisen.",al={"jordans åsikt om defias","stilwell och kungens rådgivare","defias i westfall"}}},fx={c7e3478b={q="Varför skickar Duthorian Rall dig till Jordan Stilwell?",a="Jordan Stilwell gav sig av till Ironforge utan att veta om hans hem och fru hade överlevt Defias-angreppet i Westfall. Efter att ha prövat ditt mod genom att försvara hans familj vill Duthorian Rall ge smeden sinnesro. Du får överlämna de glädjande nyheterna direkt, som paladin som hörsammade kallelsen.",al={"varför skicka mig till jordan","duthorian ralls motiv","varför besöka jordan stilwell"}},["26f62cea"]={q="Varför väljer Duthorian Rall dig för det här ärendet i stället för en vanlig budbärare?",a="Det var du som faktiskt bekämpade Defias och räddade Jordans fru. I stället för att lita på en anonym kurir anser Duthorian att Jordan förtjänar att höra de goda nyheterna direkt från den som räddade hans familj. Det för din vägledning under Ljuset vidare genom en bundsförvant som känner stark sympati för paladinorden.",al={"varför skicka mig i stället för en budbärare","varför överlämnar jag meddelandet","varför jag i rättfärdighetens prövning"}}},fp="25,170,24.326.0,23.334.0,23.186.0,32.219.0,35.131.0,53.178.0,38.152.1,45.214.0"}
P.entries["quest:1654"] = {n="The Test of Righteousness",s="The Test of Righteousness är ett avgörande prov för blivande paladiner som söker ett helgat vapen från Ljuset. Vapensmeden Jordan Stilwell erbjuder sig att smida ett enastående heligt vapen och skickar mästaren att leta efter sällsynta smidesmaterial i avlägsna länder, däribland hans förlorade familjehammare.",h="The Test of Righteousness är ett avgörande prov för blivande paladiner som söker ett helgat vapen från Ljuset.",kw={"bailor's malm","dun morogh","ironforge","jordan stilwell","kor gem","paladinvapen","the test of righteousness","whitestone oak"},ang={["class:Paladin"]="Uppdraget är ett traditionellt mandomsprov där hängivenhet och uppoffring belönas med ett vapen smitt för att kanalisera Ljuset heliga kraft.",["faction:Alliance"]="Samarbetet förenar mänskligt hantverk med Alliansens besittningar i Khaz Modan och bortom, för att beväpna försvarare mot växande mörka hot.",["profession:Blacksmithing"]="Jordan Stilwell visar vad dödligt smide kan åstadkomma. Han förenar återfunna arvegodsverktyg med renade magiska och mineraliska beståndsdelar för att skapa heliga reliker."},sec={{t="Ett heligt uppdrag",b="Utanför Ironforges mäktiga portar söker Jordan Stilwell en värdig följeslagare till Ljuset. Smeden ser vad en blivande paladin har uträttat och föreslår en helig överenskommelse: han ska smida ett legendariskt vapen som bestående symbol för hängivenhet, om paladinen utför det farliga arbetet med att skaffa material av högsta kvalitet."},{t="Helgelsens beståndsdelar",b="Att smida ett vapen som kan kanalisera Ljuset kräver material från hela Eastern Kingdoms och ännu längre bort. Stilwells ritning kräver fyra olika föremål: stadig Whitestone Oak Lumber, förädlad malm från mästerliga prospektörer, en renad Kor Gem som vibrerar av rå kraft och Jordans egen smideshammare, som han lämnade kvar när han flydde från Shadowfang Keep. Jakten på dem tvingar paladinen att pröva sin duglighet mot hot i fjärran länder."},{t="Smedens arv",b="För Jordan Stilwell är uppdraget mycket mer än enkel handel. Bland föremålen som behövs finns hans fars hammare, ett arvegods med djupa band till hans hantverk och släkt. När Jordan förenar detta återfunna verktyg med en sällsynt, renad Kor Gem får han äntligen möjlighet att förverkliga planer han burit på i åratal och förvandla sin familjehängivenhet till ett heligt rättvisans redskap."}},faq={{q="Vad är syftet med det här uppdraget?",a="Uppdraget skickar blivande paladiner genom riket för att samla de sällsynta material Jordan Stilwell behöver för att smida ett mäktigt heligt vapen. Det fungerar som en övergångsrit.",al={"vad gör uppdraget","varför göra the test of righteousness","målet med the test of righteousness"}},{q="Vem är Jordan Stilwell?",a="Jordan Stilwell är en skicklig mänsklig vapensmed som håller till utanför Ironforges portar i Dun Morogh. Han har länge planerat att smida ett heligt vapen åt en paladin och vill återfinna sin fars förlorade smideshammare.",al={"jordan stilwells bakgrund","vem är smeden utanför ironforge","stilwells bakgrund"}},{q="Vilka material behövs för att smida vapnet?",a="Jordan behöver fyra särskilda beståndsdelar: Jordan's Smithing Hammer, Whitestone Oak Lumber, Bailor's Refined Ore Shipment och en Purified Kor Gem.",al={"vilka föremål behöver jag","material till jordan stilwell","ingredienser till the test of righteousness"}},{q="Varför är Jordans hammare så viktig för honom?",a="Smideshammaren tillhörde ursprungligen Jordans far. När Jordan återfår den får han tillbaka ett oersättligt familjearvegods till sin smedja och kan skapa sitt främsta hantverk.",al={"varför hans fars hammare","historien om jordan's smithing hammer","stilwells hammare historia"}},{q="Vad är en Kor Gem?",a="En Kor Gem är en oerhört sällsynt och kraftfull sten. När den renats från fördärvande inflytanden fungerar den som en enastående fokuspunkt för att helga heliga vapen.",al={"kor gem bakgrund","vad är en kor gem","purified kor gem"}},{q="Var smider Jordan Stilwell vapnet?",a="Jordan Stilwell arbetar strax utanför de snötäckta portarna till Ironforge, i den bergiga trakten Dun Morogh.",al={"jordan stilwells plats","var finns jordan","var lämnar jag in uppdraget"}}},fx={c050f299={q="Varför vill Jordan Stilwell att det här ska göras?",a="Jordan har länge drömt om att skapa ett mäktigt rättfärdighetens vapen, men han saknade både de sällsynta materialen och möjligheten att resa över världen och hämta dem. Genom att ingå en allians med dig får han äntligen chansen att återfinna sin familjs förlorade hammare och skapa sitt främsta mästerverk hittills. Samtidigt belönar han en av Ljusets förkämpar.",al={"jordan stilwells motiv","varför vill jordan ha de här föremålen","varför jordan stilwell"}},["4a2d94b4"]={q="Vad ska Jordan's Smithing Hammer användas till?",a="Jordan's Smithing Hammer är ett arvegods som Jordan Stilwell fick av sin far. Jordan behöver det välbekanta verktyget han litar på innan han kan ta sig an det intrikata och krävande arbetet med att smida ditt heliga vapen.",al={"vad är jordan's smithing hammer","syftet med jordan's smithing hammer","varför behövs jordans hammare"}},deb75c2f={q="Vad ska Jordan's Refined Ore Shipment användas till?",a="Den här sändningen med förädlad malm ger den härdade metall som behövs för att smida vapnets huvud. Vanligt järn kan inte leda en paladins heliga krafter, så malm av hög kvalitet är nödvändig för att stå emot både hårda strider och själva Ljuset.",al={"vad används jordan's refined ore shipment till","vad ska den förädlade malmen användas till","malmsändning till jordan"}},a71ac5b5={q="Vad ska Whitestone Oak Lumber användas till?",a="Whitestone-ek är ett tätt och ovanligt hållbart trä som uppskattas för tåliga skaft. Jordan behöver virket för att snida ett stadigt handtag som bär hammarns tunga, smidda huvud utan att splittras under den väldiga heliga kraften.",al={"vad används whitestone oak lumber till","varför whitestone-ek","syftet med whitestone-virket"}},ab9031e0={q="Vad ska Purified Kor Gem användas till?",a="En Kor-ädelsten har en naturlig förmåga att leda magisk och andlig kraft. När den har befriats från mörk besmittelse och renats blir den en helig fokalpunkt infattad i vapnet. Den låter dig kanalisera och förmedla Ljuset genom dina slag.",al={"vad används purified kor gem till","vad är kor-ädelstenen till för","varför purified kor gem"}},c2f50c47={q="Varför behöver Jordan Stilwell att du samlar ihop materialen?",a="Jordan är en ödmjuk smed som är bunden till sin smedja utanför Ironforge. Han saknar stridsträning och möjlighet att ge sig ut i Azeroths farliga trakter. Föremålen som behövs finns utspridda på avlägsna och farliga platser. För att hämta dem krävs en skicklig paladin av Ljuset som vågar trotsa farorna.",al={"varför jag för jordan stilwell","varför behöver jordan hjälp","varför kan jordan inte hämta malmen"}}},fp="25,175,19.161.0,26.295.0,20.272.1,34.153.0,23.170.0,46.116.0,43.152.0,18.126.0,45.90.0"}
P.entries["quest:1655"] = {n="Bailor's Ore Shipment",s="Bailor's Ore Shipment är ett uppdrag för paladiner som söker förädlad metall till Jordan Stilwells heliga vapen. Mo'grosh-ogrerna plundrade legeringslasten i ett bakhåll längs vägen från Wetlands.",h="Bailor's Ore Shipment är ett uppdrag för paladiner som söker förädlad metall till Jordan Stilwells heliga...",kw={"bailor","jordan stilwell","loch modan","mo'grosh","ogrer","malm","leverans","stonehand","test of righteousness"},ang={["class:Paladin"]="Att hämta Bailors legering är ett viktigt övergångsprov under Test of Righteousness. Det visar att du vågar möta farliga bestar för att samla material till din heliga stridshammare.",["faction:Alliance"]="Mo'grosh-ogreernas närvaro i nordöstra Loch Modan är fortfarande ett hot mot försörjningslederna och karavanerna som färdas genom passet vid Wetlands.",["profession:Blacksmithing"]="Bailors speciallegering visar hur höga metallurgiska krav Jordan Stilwell ställer när han tillverkar legendariska vapen."},sec={{t="En överfallen karavan",b="När Jordan Stilwell behövde en särskild malmleverans, förädlad av hans gamle vän Bailor Stonehand, kom den aldrig säkert fram till Ironforge. Försörjningskaravanen färdades söderut från Wetlands mot Loch Modan när Mo'grosh-ogrerna överföll och slaktade den. Den sista överlevande vakten lyckades stappla in i lägret, men dog strax därefter av sina skador. Leveransen blev kvar i ogreterritorium."},{t="Återta legeringen",b="Bailor Stonehand, som håller till i Loch Modan, skickar paladiner över The Lochs vatten mot kullarna i nordost. Där, bland Mo'grosh-ogreernas läger, ligger den stulna legeringslådan övergiven som byte. När du hämtar lådan visar du att du vågar ta dig in på fientligt territorium, så att Bailor kan hålla sitt ursprungliga avtal med Jordan Stilwell."}},faq={{q="Vem är Bailor Stonehand?",a="Bailor Stonehand är en dvärghantverkare och gammal vän till Jordan Stilwell som arbetar i Loch Modan. Han ansvarar för att förbereda och leverera den särskilda legering som behövs för Jordans arbete.",al={"bailor stonehand","vem är bailor","bailor"}},{q="Vem stal Jordans malmleverans?",a="Mo'grosh-ogrerna överföll försörjningskaravanen när den färdades från Wetlands till Loch Modan, dödade eskorterna och förde lasten till sina läger.",al={"vem stal malmen","vem tog leveransen","malmtjuvar"}},{q="Var ägde bakhållet rum?",a="Karavanen överfölls längs bergsvägen mellan Wetlands och Loch Modan, innan den hann nå de lokala bosättningarnas säkerhet.",al={"bakhållets plats","var överfölls karavanen"}},{q="Var håller Mo'grosh-ogrerna till?",a="Mo'grosh-ogrerna har befästa läger i de karga kullarna nordost om The Loch, på andra sidan vattnet från de västra bosättningarna.",al={"var finns mo'grosh","ogrelägrets plats","var finns leveransen"}},{q="Varför behövs leveransen?",a="Leveransen innehåller en särskild legering som Jordan Stilwell behöver för att smida ett heligt vapen åt paladiner som genomför Test of Righteousness.",al={"varför behövs malmen","vad är leveransen till för","malmens syfte"}},{q="Vad hände med karavanvakterna?",a="Nästan alla dödades genast av ogreerna. Den ensamma vakten som lyckades fly och nå hjälp dog några dagar senare, innan en helare kunde rädda honom.",al={"karavanvakter","karavanens överlevande"}}},fx={f726d253={q="Varför vill Bailor Stonehand att det här ska göras?",a="Bailor lovade sin gamle vän Jordan Stilwell att leverera en särskild sändning med förädlad legering. Karavanen som förde den ut ur Wetlands överfölls, lasten gick förlorad och den siste överlevande vakten dog av sina skador. Bailor är stolt över att hålla sina löften, men transporten är förstörd och ogres håller legeringen. Han behöver någon som kan återta det stulna godset så att Jordan får det som utlovats.",al={"varför hjälpa bailor","bailors motiv","varför vill bailor ha malmen"}},["8c6c3897"]={q="Vilka är Mo'grosh-ogrerna?",a="Mo'grosh är en brutal ogreklan som trängt in i Loch Modans nordöstra högland och byggt en fästning där, känd som Mo'grosh Stronghold. De är aggressiva och tar gärna tillfället i akt. De plundrar regelbundet bergspassen och handelslederna mellan Loch Modan och Wetlands, dödar resenärer och rövar åt sig råvaror, vapen och mat från försörjningsvagnar.",al={"mo'grosh-ogrer","vem tog malmen","ogrer i loch modan"}},["6bcba9e0"]={q="Varför behöver Bailor en äventyrare i stället för de lokala vakterna?",a="De lokala dvärgvakterna och bergsjägarna har fullt upp med att hålla tillbaka trogguppror och försvara området runt The Loch. Vakterna som eskorterade Bailors legering utplånades helt i bakhållet, och den enda överlevande dog innan hjälp hann fram. Bailor har varken soldater att avvara eller styrkan att ensam storma en ogrefästning. En kapabel äventyrare är hans enda utväg.",al={"varför skickar bailor inte vakter","varför jag för bailor","varför inte vakterna från ironforge"}}},fp="21,173,19.319.0,20.284.0,24.171.0,32.143.0,32.120.0,37.125.0,28.106.0,36.135.0"}
P.entries["quest:1656"] = {n="A Task Unfinished",s="A Task Unfinished är ett enkelt leveransuppdrag som visar påfrestningarna unga tauren utsätts för under sina övergångsriter på Red Cloud Mesa. En utmattad ungdom, tyngd av prövningarna och en plikt mot familjen, ber en förbipasserande resenär bära ett knippe pälsar ner till värdshusvärden Kauth i Bloodhoof Village.",h="A Task Unfinished är ett enkelt leveransuppdrag som visar påfrestningarna unga tauren utsätts för under sina...",kw={"a task unfinished","bloodhoof village","knippe pälsar","värdshusvärden kauth","mulgore","red cloud mesa","rite of strength","tauren"},ang={["faction:Horde"]="Bloodhoof Village är en viktig samlingsplats för resenärer i Mulgore, med välkomnande skydd och varma härdar för Horde-medlemmar som färdas över slätterna.",["race:Tauren"]="Unga tauren genomgår krävande prövningar på Red Cloud Mesa för att bevisa sin mognad och styrka. Stamplikter och familjeplikter prövar ofta deras uthållighet lika hårt som de rituella utmaningarna."},sec={{t="Prövningar på mesan",b="Högt uppe på Red Cloud Mesa ställs unga tauren inför hårda övergångsriter för att bevisa att de är redo för den större världen. Att balansera traditionella riter mot vanliga plikter i stammen kan driva en ungdom till gränsen för fysisk utmattning. Med en oavslutad Rite of Strength och en brådskande uppgift från sin far söker en ung tauren hjälp av en förbipasserande resenär med att bära ett knippe pälsar ner från mesan."},{t="Härd och skydd",b="Pälsarna ska till Bloodhoof Village, en välkomnande fristad på de öppna slätterna nedanför. Värdshusvärden Kauth tar gärna emot leveransen och tänker göra varma filtar av pälsarna åt trötta vandrare. Ärendet visar både slättlandets taurers gästfrihet och vikten av vila, och hur gemenskapens stöd ligger till grund för varje enskild styrkeprövning."}},faq={{q="Vad är uppdraget A Task Unfinished?",a="A Task Unfinished är ett ärende som en utmattad ung tauren på Red Cloud Mesa ber dig utföra. Överväldigad av de pågående prövningarna i sin Rite of Strength ber ungdomen en förbipasserande resenär leverera ett knippe pälsar till värdshuset i Bloodhoof Village.",al={"vad är a task unfinished","information om uppdraget a task unfinished","vem ger a task unfinished"}},{q="Vem är värdshusvärden Kauth?",a="Värdshusvärden Kauth driver det lokala värdshuset i Bloodhoof Village i Mulgore. Han erbjuder trötta resenärer som färdas över slätterna från de höga mesorna en välkomnande plats att vila på, varma filtar och gästfrihet.",al={"vem är värdshusvärden kauth","var finns kauth","värdshusvärd i bloodhoof village"}},{q="Varför levereras pälsarna till värdshuset?",a="Den unga tauren ska leverera pälsarna till värdshusvärden Kauth på sin fars begäran. Kauth använder de tåliga pälsarna som varma filtar åt gäster som söker skydd och vila på hans värdshus i Bloodhoof Village.",al={"varför leverera pälsar","vad ska pälsarna användas till","knippe pälsar mulgore"}},{q="Varför kunde den unga tauren inte leverera pälsarna själv?",a="Den unga tauren genomgår just nu Rite of Strength på Red Cloud Mesa. De fysiska kraven i prövningen har gjort ungdomen alldeles för utmattad för att färdas hela vägen till Bloodhoof Village utan att misslyckas med den heliga riten eller kollapsa av utmattning.",al={"varför kan uppdragsgivaren inte leverera pälsarna","varför behöver ungdomen hjälp"}},{q="Vad är Rite of Strength?",a="Rite of Strength är en av de grundläggande övergångsriterna för unga tauren på mesan. Den prövar deras fysiska uthållighet, motståndskraft och förmåga att bli beskyddare av stammen.",al={"vad är rite of strength","taurenernas styrkeprövning rite of strength"}},{q="Var ligger Bloodhoof Village?",a="Bloodhoof Village är en viktig bosättning på de böljande slätterna i Mulgore, nedanför Red Cloud Mesas skyddade höjder. Där finns viktiga tjänster för stammen, bland annat ett öppet värdshus, hantverksmaterial och handelsplatser.",al={"var ligger bloodhoof village","bloodhoof village plats"}}},fp="17,319,18.404.0,18.390.0,36.262.0,23.212.0,44.207.0,58.254.0,29.195.0,36.233.0"}
P.entries["quest:166"] = {n="The Defias Brotherhood",s="Det här uppdraget är höjdpunkten på Gryan Stoutmantles långa kamp för att befria Westfall från laglösa.",h="Det här uppdraget är höjdpunkten på Gryan Stoutmantles långa kamp för att befria Westfall från laglösa.",kw={"the deadmines","huvud","juggernaut","milis","moonbrook","stenhuggare","stoutmantle","vancleef","westfall"},ang={["class:Rogue"]="VanCleef är en legendarisk skurk och mästerlig hantverkare. Att korsa klingor med honom i hans innersta helgedom prövar varje smygoperatörs stridsträning.",["faction:Alliance"]="Uppdraget markerar en viktig tidig seger för Alliansen och säkrar Westfalls kornbod när Stormwinds tron inte kan avvara egna soldater.",["race:Human"]="För människor i kungariket är det en bitterljuv tragedi att fälla VanCleef och därmed döda hantverkaren vars händer byggde upp deras huvudstad ur askan."},sec={{t="Domen faller",b="I månader har Gryan Stoutmantle och den hårt prövade People's Militia kämpat förtvivlat för att hålla stånd mot Defias Brotherhood i Westfall. Nu har tjuvarnas fäste avslöjats under Moonbrook. Stoutmantle utfärdar sin sista, dystra order: Edwin VanCleef måste mördas för att en gång för alla krossa upproret."},{t="In i labyrinten",b="För att verkställa domen måste kämpar ta sig djupt in i Deadmines vindlande schakt. Bakom avhoppade stenhuggare, gobliningenjörer och tunga järnportar ligger den centrala torrdockan, där VanCleef övervakar bygget av sitt mäktiga krigsfartyg. När han mister huvudet bryts den kommandokedja som håller hela nätverket av laglösa samman."},{t="Skuggor av en större konspiration",b="Stoutmantle tror att VanCleefs död blir början på slutet för Brotherhood, men den fallne gillemästarens lik döljer oroande hemligheter. På hans kropp finns ett osänt brev, som antyder att upproret i Westfall aldrig var en isolerad revolt, utan en del av ett större och mörkare nätverk som sträcker sig ända in i Stormwind Citys adel."}},faq={{q="Vad är målet med uppdraget?",a="Gryan Stoutmantle ger dig i uppdrag att ta dig in i grottkomplexet Deadmines i Moonbrook, döda Edwin VanCleef och återvända till Sentinel Hill med hans avhuggna huvud.",al={"uppdragsmål","vad ska jag göra","vad är det här för uppdrag"}},{q="Vem är Edwin VanCleef?",a="Edwin VanCleef var tidigare stormästare i Stonemasons Guild och ledde återuppbyggnaden av Stormwind City efter att orcherna jämnat staden med marken under första kriget. Efter en bitter tvist om betalning med House of Nobles grundade han Defias Brotherhood för att utkräva hämnd på kungariket.",al={"vem är vancleef","vancleefs identitet","edwin vancleefs bakgrund"}},{q="Varför beordrar Gryan Stoutmantle ett mord?",a="People's Militia saknar förstärkningar från Stormwinds reguljära armé, som behövs för att utkämpa ett långvarigt krig. Stoutmantle inser att Westfalls enda realistiska chans att bryta syndikatets grepp om jordbruken är att slå ut dess ledning.",al={"varför döda vancleef","stoutmantles motiv","varför dödsstraff"}},{q="Var finns Edwin VanCleef?",a="Han gömmer sig djupt inne i Deadmines under Moonbrook. Gryan Stoutmantle ber dig att ta dig in i gömstället och leta upp honom.",al={"vancleefs plats","var finns edwin vancleef","deadmines boss plats"}},{q="Förintas Defias helt när VanCleef dödas?",a="Stoutmantle hoppas att VanCleefs död ska bryta Brotherhoods grepp om Westfall. Vad som händer och vilka fler fynd som görs återstår att se under anfallet.",al={"är defias besegrade","är defias borta","brotherhoods slut"}},{q="Vilket anmärkningsvärt föremål hittar man på VanCleef när han besegrats?",a="Stoutmantle kräver VanCleefs huvud som bevis. Andra fynd inne i gömstället avslöjas under uppdraget.",al={"vancleefs byte","osänt brev","vad tappar vancleef"}}},fx={e9d4d384={q="Vad ska Head of VanCleef användas till?",a="Gryan Stoutmantle kräver obestridliga bevis för att Edwin VanCleef verkligen är död. Defias Brotherhood har terroriserat Westfall från skuggorna i åratal, spridit rykten och undkommit tillfångatagande. När du visar upp VanCleefs avhuggna huvud får People's Militia ett definitivt besked, och de hårt prövade bönderna får veta att deras värsta plågoande äntligen har fallit.",al={"varför ta vancleefs huvud","syftet med head of vancleef","varför behöver jag vancleefs huvud"}},["48642626"]={q="Varför skickar Gryan Stoutmantle dig i stället för People's Militia?",a="People's Militia är redan hårt pressad av att försvara Sentinel Hill och Westfalls utspridda gårdar mot dagliga banditräder och gnollangrepp. Stormwind har vägrat skicka förstärkningar, så Stoutmantle saknar den vältränade slagstyrka som krävs för att bryta sig in i The Deadmines befästa djup. Han måste förlita sig på erfarna och kapabla äventyrare som du för att slå direkt mot konspirationens hjärta.",al={"varför anfaller inte milisen the deadmines","varför skicka mig mot vancleef","varför dödar inte stoutmantle vancleef"}}},fp="22,182,17.276.0,18.304.1,31.243.1,31.134.0,22.274.0,50.241.0,34.127.0,52.140.1,55.107.1"}
P.entries["quest:1665"] = {n="Bartleby's Mug",s="I Stormwind prövar Bartleby's Mug en ung krigares tålighet. När du besegrat Bartleby på Pig and Whistle Tavern tar du hans dryckeskanna till din tränare Harry Burlguard.",h="I Stormwind prövar Bartleby's Mug en ung krigares tålighet.",kw={"bartleby","burlguard","kanna","old town","pig and whistle","stormwind","krigare"},ang={["class:Warrior"]="Som krigare i Stormwind visar du att du kan mäta dig med bråkmakare genom att ta Bartleby's Mug.",["faction:Alliance"]="Som medlem av Alliance vet du att stökiga gäster i Old Town ofta ställer till huvudvärk för Stormwinds stridsinstruktörer."},sec={{t="Trofé från ett krogslagsmål",b="Harry Burlguard prövar unga krigare med ett slagsmål i Old Town. Han ber dig slå ner Bartleby, en envis fyllerist vid bardisken på Pig and Whistle Tavern. När Bartleby väl gett sig lämnar han motvilligt ifrån sig sin dyrbara dryckeskanna, men tar först en sista klunk för att tömma den på slattarna."},{t="Ett steg mot mästerskap",b="När du återlämnar kannan till Harry Burlguard är ditt nybörjarprov avklarat. Burlguard ser att du kan övertyga med råstyrka och inser att du är redo att bli mästare på försvar. Han skickar dig vidare till mer stridsfältsträning hos Marshal Haggard, en erfaren veteran i Elwynn Forest."}},faq={{q="Varför vill Harry Burlguard ha Bartleby's Mug?",a="Harry Burlguard vill ha Bartleby's Mug som bevis på att du har kämpat mot och besegrat Bartleby. Bartleby är mycket fäst vid sin dryck, så att han lämnar ifrån sig sin personliga kanna visar att han blev ordentligt besegrad och tvingades ge sig.",al={"varför bartleby's mug","burlguards syfte med kannan","bevis på att ha besegrat bartleby"}},{q="Vem är Bartleby?",a="Bartleby är en bråkig gäst vid bardisken på Pig and Whistle i Stormwinds Old Town. Han är berusad och lynnig och ger de lokala krigartränarna ett informellt prov för blivande kämpar.",al={"bartleby-lore","vem är fylleristen bartleby","bartleby i old town"}},{q="Var utspelar sig striden?",a="Slagsmålet utspelar sig inne på Pig and Whistle Tavern i Stormwinds Old Town.",al={"var finns bartleby","bartlebys plats","slagsmålet på pig and whistle"}},{q="Vad händer när jag lämnat tillbaka kannan till Burlguard?",a="När Burlguard granskat kannan och bekräftat att du vunnit lär han dig avancerade försvarsställningar. Sedan skickar han dig ut genom stadsportarna för att söka upp Marshal Haggard i Elwynn Forest.",al={"vad händer efter bartleby's mug","uppdrag efter bartleby's mug","haggards uppdrag"}},{q="Blir Bartleby skadad för livet i slagsmålet?",a="Nej. Slagsmålet är inte dödligt. Bartleby ger sig, dricker upp, lämnar ifrån sig kannan och stannar kvar på värdshuset med blåmärken och sårad stolthet.",al={"är bartleby död","dog bartleby","överlevde bartleby"}},{q="Kan alla Alliance-klasser göra det här uppdraget?",a="Bara krigare i Alliance genomgår det här provet som en del av sin klassutbildning på nivå tio i stridsställningar och försvarsmanövrer.",al={"är bartleby's mug bara för krigare","vem kan göra bartleby-uppdraget","klasser för kannuppdraget"}}},fx={["2bbd1f99"]={q="Varför lämnar Bartleby ifrån sig sin mugg?",a="Bartleby lämnar ifrån sig sin dyrbara mugg först när du har besegrat honom i ett rättvist slagsmål på krogen. Han ville inte frivilligt skiljas från den, men efter att ha blivit rejält tilltygad ger han sig hederligt, fast inte förrän han hastigt svept det som fanns kvar i muggen.",al={"varför ger bartleby bort sin mugg","bartlebys motiv","varför ge upp muggen"}}},fp="14,183,24.276.0,21.290.0,45.196.0,16.191.0,33.80.0,48.192.0,48.143.0,37.128.0"}
P.entries["quest:1666"] = {n="Marshal Haggard",s="I Eastvale förvarar Marshal Haggard de vapen han samlade under ett helt liv i tjänst. Harry Burlguard skickar unga krigare från Stormwind City till den pensionerade marskalken för att söka bättre vapen.",h="I Eastvale förvarar Marshal Haggard de vapen han samlade under ett helt liv i tjänst.",kw={"eastvale","eastvale logging camp","elwynn forest","harry burlguard","marshal haggard","stormwind","krigare"},ang={["class:Warrior"]="Som krigare i Alliansen lämnar du Stormwinds formella träning och ger dig ut i vildmarken för att söka vapen.",["faction:Alliance"]="Som kämpe i Alliansen följer du Stormwinds tilltro till pensionerade veteraner och deras privata förråd för att förbereda nästa generation försvarare."},sec={{t="En veteranrustkammare",b="Stormwinds unga krigare behöver mer än skicklighet för att möta faror utanför staden. Harry Burlguard skickar lovande kämpar österut genom Elwynn Forest för att hitta Marshal Haggard, en pensionerad officer som tjänade riket i många år. Haggard samlade ett eget vapenförråd under ett helt liv i fält, och hans hem nära Eastvale Logging Camp rymmer vapen åt unga krigare som söker bättre utrustning."},{t="Pensionärsliv i Eastvale",b="Marshal Haggard bor i en avskild herrgård nära Eastvale Logging Camp. Många års tjänst har försämrat hans syn, och ibland misstar han besökare på väg fram för Riverpaw-gnoller på jakt. Åldern håller honom i denna stillsamma del av östra Elwynn, men Stormwinds vakter och tränare hyser fortfarande respekt för den gamle marskalken."}},faq={{q="Vem ger uppdraget?",a="Harry Burlguard, en krigartränare i Stormwind City, skickar lovande unga krigare till Marshal Haggard.",al={"var får jag uppdraget från marshal haggard","vem ger uppdraget marshal haggard","uppdragsgivare marshal haggard"}},{q="Var finns Marshal Haggard?",a="Marshal Haggard bor i en herrgård strax öster om Eastvale Logging Camp, längst österut i Elwynn Forest nära gränsen till Redridge Mountains.",al={"marshal haggards plats","var finns haggard","herrgården vid eastvale logging camp"}},{q="Varför skickar Harry Burlguard dig till Haggard?",a="Harry Burlguard skickar dig till Marshal Haggard eftersom unga krigare behöver bättre vapen än sina träningssvärd. Haggard samlade vapen och rustningar under sin långa karriär och kan dela med sig till dem som visar sig värdiga.",al={"varför marshal haggard","varför bege sig till eastvale som krigare","syftet med marshal haggards uppdrag"}},{q="Varför misstar Haggard besökare för gnoller?",a="Marshal Haggards syn har försämrats med åldern. Gnoller trakasserar Elwynn Forests timmerverksamhet och utkanter i öster, så den gamle veteranen är på sin vakt mot oväntade besökare.",al={"haggards syn","är haggard blind","marshal haggards gnolldialog"}},{q="Vad händer när uppdraget är slutfört?",a="När du hälsar på Marshal Haggard prövar han ditt mod genom att skicka dig för att ta hand om Dead-tooth Jack innan han överväger att dela med sig av vapnen i sina förråd.",al={"nästa uppdrag efter marshal haggard","uppföljning till marshal haggard"}},{q="Kan andra klasser än krigare göra uppdraget?",a="Nej. Den här vägen är för krigare och ingår i deras träning runt nivå tio och förberedelser inför farorna bortom Elwynn Forest.",al={"kan paladiner göra marshal haggards uppdrag","uppdraget med haggard är bara för krigare"}}},fp="15,194,18.386.0,22.325.0,22.104.0,33.137.0,45.223.0,45.169.0,39.150.1,55.129.0"}
P.entries["quest:1667"] = {n="Dead-tooth Jack",s="En stulen bricka ger Defias Brotherhood tillgång till Marshal Haggards auktoritet. Den pensionerade officeren bor i östra Elwynn Forest, där Dead-tooth Jack lurade honom att lämna ifrån sig sin officiella insignia. Jack bar en Stormwind-tabard i mörkret och utgav sig för att vara Marshal Dughan. Haggard måste få tillbaka brickan innan Defias Brotherhood kan använda den för att utge sig för att vara Stormwinds ämbetsmän.",h="En stulen bricka ger Defias Brotherhood tillgång till Marshal Haggards auktoritet.",kw={"bricka","dead-tooth jack","defias","elwynn forest","vakt burlguard","identitetsbedrägeri","marshal dughan","marshal haggard","kassakista"},ang={["class:Rogue"]="Som rövare ser du hur Dead-tooth Jacks kupp bygger lika mycket på förklädnad, bedrägeri och fräckhet som på simpelt vägröveri.",["class:Warrior"]="Marshal Haggard var en gång en erfaren frontkämpe. Som krigare kan du vinna hans tacksamhet och välja bland överblivna vapen från hans tjänsteår.",["race:Human"]="För dig som människa från Stormwind visar den här stölden hur sårbara rikets landsbygdsgränser är för Defias-infiltratörer. De bär kronans egna färger för att lura pensionerade veteraner."},sec={{t="Ett nattligt bedrägeri",b="Marshal Haggard bor i en avskild stuga på Elwynns östra höjder. En natt kom en gestalt i en Stormwind-tabard fram och påstod sig ha ett officiellt ärende. Han bad om Haggards gamla marskalksbricka. Haggard trodde att han lämnade den till en kollega och gick med på det. Främlingen skrattade honom rakt i ansiktet och försvann in i skogen. Tjuven var en Defias-rövare som kallades Dead-tooth Jack."},{t="Hotet från falsk auktoritet",b="Marshal Haggard har gått i pension, men hans gamla bricka har fortfarande Stormwinds juridiska tyngd. Defias-banditer smyger sig fram genom Elwynn, Westfall och Redridge. Brickan skulle kunna hjälpa dem att passera vaktposter, omdirigera patruller eller ta befälet över förnödenheter. Jack drog sig tillbaka till ett läger i söder och låste in brickan i en kassakista. Haggard måste få den tillbaka innan Defias kan ställa till med allvarlig skada."}},faq={{q="Vem är Dead-tooth Jack?",a="Dead-tooth Jack är en Defias-agent i östra Elwynn Forest. I skydd av mörkret utgav han sig för att vara Marshal Dughan och lurade pensionerade Marshal Haggard att lämna över sin officiella Stormwind-bricka.",al={"dead tooth jack","vem är dead tooth","dead tooth jack bakgrund"}},{q="Varför behöver Marshal Haggard få tillbaka sin bricka?",a="Marshal Haggard behöver få tillbaka sin bricka eftersom den är en äkta symbol för Stormwinds auktoritet. Han fruktar att Defias ska använda den för att utge sig för att vara ämbetsmän, kringgå militärpatruller och skapa kaos i riket.",al={"varför återfå brickan","haggards bricka","varför är brickan viktig"}},{q="Hur lyckades Jack lura Marshal Haggard?",a="Jack kom till Haggards stuga på natten, klädd i en Stormwind-tabard. I det svaga ljuset tog Haggard honom för Marshal Dughan från Goldshire och lämnade över insignian i tron att han gav den till en kollega.",al={"hur lurade han haggard","haggard lurad","varför gav haggard bort brickan"}},{q="Var förvarar Jack den stulna brickan?",a="Jack har låst in brickan i en kassakista i sitt banditläger söder om Marshal Haggards hus. Han bär nyckeln till kistan på sig.",al={"var brickan finns","var är brickan","dead tooths läger"}},{q="Vem skickade dig till Marshal Haggard från början?",a="Harry Burlguard, en veteran som ofta besöker Pig and Whistle Tavern i Stormwind, skickar äventyrare till Marshal Haggard. Han vet att den pensionerade marskalken kan tänka sig att lämna ifrån sig överblivna vapen i utbyte mot hjälp.",al={"vem skickar dig hit","burlguard","uppdragsgivare start"}},{q="Vad händer när brickan återlämnas?",a="Marshal Haggard blir mycket lättad över att Defias inte kan använda hans identitet eller rang mot kungariket. Som tack gör han honnör för dig och låter dig välja bland välskötta militärvapen från hans tjänsteår.",al={"lämna in uppdrag","haggards reaktion","brickan återlämnad"}}},fx={["5b8b35d8"]={q="Vad ska Marshal Haggard's Badge användas till?",a="Marshal Haggard's Badge är ett gammalt tecken på hög auktoritet inom Stormwinds armé. I ärliga händer är det ett kärt arvegods från Haggards år i tjänst. I Defias Brotherhoods händer kan en officiell marschalkokard däremot låta tjuvar och banditer utge sig för att vara officerare från Stormwind, passera kontrollposter och iscensätta farliga bedrägerier i hela kungariket.",al={"syftet med haggards bricka","vad gör brickan","varför är brickan farlig"}},["55355d07"]={q="Varför behöver Marshal Haggard att du hämtar hans bricka?",a="Haggard är sedan länge pensionerad och bor i en avskild stuga. Han skäms över att ha blivit lurad i mörkret av en skurk. Om han ber stadsvakten eller Marshal Dughan om hjälp måste han erkänna att han gav sin officiella bricka rakt i händerna på en Defias-tjuv. Stormwinds vakter har redan fullt upp med att försvara staden. Du kom för att leta efter hans reservvapen, så du är perfekt lämpad att diskret hjälpa honom att utkräva sin hämnd.",al={"varför behöver haggard mig","varför hämtar inte haggard den själv","varför inte använda vakterna"}}},fp="15,367,17.381.0,29.408.0,23.199.0,45.211.0,44.219.0,38.142.0,51.207.0,40.219.1"}
P.entries["quest:167"] = {n="Oh Brother. . .",s="”Oh Brother. . .” är ett uppdrag för Alliansen som Wilder Thistlenettle ger i Stormwind City. Förtvivlad efter ett ras under en expedition ner i djupen under Moonbrook ber Wilder äventyrare söka igenom de labyrintiska gruvgångarna efter hans försvunna bror, Foreman Thistlenettle, eller återfinna hans Explorers' League Badge.",h="”Oh Brother.",kw={"bricka","the deadmines","explorers' league","moonbrook","stormwind","thistlenettle","odöd","westfall","wilder"},ang={["faction:Alliance"]="Deadmines ligger som en pest vid Stormwinds tröskel, och det här uppdraget visar hur djupt Defias och underjordiska fasor har skadat oskyldiga invånare.",["race:Dwarf"]="En förman från Explorers' League går ett tragiskt öde till mötes i människornas land. Det berör varje dvärg som värdesätter brödraskap, stenhuggeri och förbundets outtröttliga arbete."},sec={{t="En instängd expedition",b="Wilder Thistlenettle och hans bror gick in i de väldiga underjordiska gångarna under Moonbrook som medlemmar i ett gruvbolag. Men allt blev katastrofalt när fientliga tjuvar svärmade över området och ett våldsamt ras blockerade de nedre gångarna. Wilder lyckades fly till Stormwind, men hans bror och resten av arbetslaget blev kvar bakom rasmassorna."},{t="Foreman Thistlenettles dystra öde",b="Sanningen som väntar varje räddare som tränger djupt in i Deadmines gångar är tragisk. Foreman Thistlenettle överlevde inte raset; i stället återupplivade mörka krafter som rörde sig i de övergivna gruvorna den olycklige dvärgen till ett odött skal. Förmannen vandrar genom de underjordiska grottorna tillsammans med andra rastlösa lik och har bara kvar sin dyrbara Explorers' League Badge som ett tecken på vem han en gång var."}},faq={{q="Var börjar jag uppdraget ”Oh Brother. . .”?",a="Uppdraget ges av Wilder Thistlenettle, som finns i Dwarven District i Stormwind City.",al={"uppdragsgivare oh brother","vem ger oh brother","var får man oh brother"}},{q="Var finns Foreman Thistlenettle?",a="Foreman Thistlenettle vandrar omkring i Deadmines yttre gruvgångar, under staden Moonbrook i Westfall. Han finns någonstans i de yttre gångarna som leder upp till instansportalen.",al={"foreman thistlenettle plats","var finns thistlenettle","var finns brodern"}},{q="Vad hände med Foreman Thistlenettle?",a="Ett ras stängde in Foreman Thistlenettle och hans gruvarbetslag i grottorna, och ingen av dem har hörts av sedan dess. Att hitta honom, eller åtminstone hans bricka, är det enda sättet för Wilder att få veta vad som hänt hans bror.",al={"lever thistlenettle","vad hände med brodern","thistlenettle bakgrund"}},{q="Vilket föremål ska jag hämta?",a="Du ska hämta Foreman Thistlenettles Explorers' League Badge, som han alltid bar på sig. Hitta förmannen djupt inne i Deadmines gångar, så har han brickan med sig.",al={"föremål till oh brother","vad får man från oh brother"}},{q="Vad gjorde expeditionen i Moonbrook?",a="Bröderna Thistlenettle var medlemmar i ett gruvbolag som arbetade i den väldiga gruvan under Moonbrook, innan Defias-banditer överföll dem och ett plötsligt tunnelras skilde dem åt.",al={"varför var dvärgarna i westfall","explorers league deadmines","varför var de i moonbrook"}},{q="Slutförs det här uppdraget inne i Deadmines-instansen?",a="Nej, du behöver inte gå in i fängelsehålan. Foreman Thistlenettle är en elitfiende som strövar omkring i de omstridda gruvgångarna som leder upp till instansportalen.",al={"är oh brother inne i deadmines-instansen","behöver jag en grupp till fängelsehålan"}}},fx={["7bf03114"]={q="Varför vill Wilder Thistlenettle att det här ska göras?",a="Wilder kom undan med livet i behåll när tunnlarna rasade långt under Moonbrook. Hans bror och resten av gruvexpeditionen kom aldrig ut. De slukades av mörkret och av tjuvarna som härjar i gångarna. Wilder sitter kvar i plågsam ovisshet i Stormwind och söker sinnesro. Han behöver få veta om hans bror fortfarande lever eller om han mötte ett grymt öde i djupet.",al={"varför vill wilder hitta sin bror","wilder thistlenettles motiv","varför hitta foreman thistlenettle"}},ebc7a172={q="Vad är Thistlenettle's Badge?",a="Foreman Thistlenettle bar ett märke från Explorers' League som visade hans ställning inom Ironforges gille för grävare och äventyrare. Om du inte hittar någon levande dvärg där nere, blir återlämnandet av denna personliga ägodel ett bevis på hans öde och ger hans sörjande bror ett avslut.",al={"vad är thistlenettles badge","thistlenettles märke från explorers league","varför hämta märket"}},["5e05fe78"]={q="Varför ber Wilder Thistlenettle dig att göra det i stället för att gå själv?",a="Wilder kom knappt levande undan när katastrofen inträffade. Den vidsträckta labyrinten under Moonbrook kryllar av skurkar och farliga fällor, långt bortom vad en förrymd gruvarbetare kan klara ensam. När han ser en kapabel äventyrare sätter han sitt hopp till att du ska lyckas där han bara kunde fly.",al={"varför går wilder inte själv","varför skicka mig till deadmines","varför behöver wilder hjälp"}}},fp="15,194,20.273.0,38.264.1,45.76.0,39.136.0,39.193.1,32.154.1,43.146.0,62.141.0"}
P.entries["quest:1679"] = {n="Muren Stormpike",s="Muren Stormpike är ett introduktionsuppdrag för blivande krigare i Alliansen, som ges när en rekryt visat sitt grundläggande mod i Dun Morogh. På uppdrag av Granis Swiftaxe i Kharanos reser den unga kämpen till bergsstaden Ironforge för att få formell undervisning i stridskonst. Mötet med Muren markerar början på fördjupad träning i taktiska ställningar och dvärgarnas militära traditioner.",h="Muren Stormpike är ett introduktionsuppdrag för blivande krigare i Alliansen, som ges när en rekryt visat...",kw={"defensive stance","granis swiftaxe","hall of arms","ironforge","kharanos","military ward","muren stormpike","krigartränare"},ang={["class:Warrior"]="Den här kallelsen markerar din övergång från en stridslysten rekryt till en disciplinerad soldat som kan hålla linjen och skydda sina allierade.",["race:Dwarf"]="För dvärgakrigare innebär rapporteringen till Hall of Arms att du knyts direkt till bergsklanernas anrika stridstradition och taktiska disciplin.",["race:Gnome"]="Efter Gnomeregans fall flydde gnomiska krigare till Dun Morogh. För att bemästra traditionell tung frontstrid förlitar de sig på Hall of Arms i Ironforge."},sec={{t="En kallelse till Ironforge",b="Efter att ha prövat sin styrka mot lokala hot i Dun Moroghs snöiga dalar fångar krigarnoviser Granis Swiftaxes uppmärksamhet i Kharanos. Swiftaxe inser att råa skärmytslingar bara kan föra en slagskämpe en bit och skickar lovande kämpar till den dvärgska stridskonstens hjärta: Military Ward i Ironforge. Där, i smedjestadens ekande salar, övervakar erfarna kombattanter den formella utbildningen av dem som är ämnade för strid."},{t="Vapenmästaren",b="När rekryterna når Hall of Arms presenteras de för Muren Stormpike, en erfaren veteran från en ryktbar dvärgaklan. Muren bryr sig föga om krogskrönor och kräver bevis på att hans nya adepter kan uthärda verklig strid. När du rapporterar till honom öppnas vägen till att bemästra försvarskonsten, lära dig att ta emot och styra fiendens aggression och förtjäna välgjorda järnvapen som passar en riktig frontsoldat."}},faq={{q="Vem skickar dig för att hitta Muren Stormpike?",a="Granis Swiftaxe, krigartränaren i Kharanos, ger dig uppdraget när du har visat din grundläggande stridsförmåga i Dun Morogh.",al={"vem ger uppdraget muren stormpike","var får jag uppdraget muren stormpike","uppdragsgivare muren stormpike"}},{q="Var finns Muren Stormpike?",a="Muren Stormpike finns i Hall of Arms, som ligger i Military Ward på östra sidan av Ironforge.",al={"var finns muren stormpike","muren stormpikes plats","hur hittar jag muren"}},{q="Varför är det här uppdraget viktigt för krigare?",a="När du rapporterar till Muren inleds avancerad krigarträning. Det leder direkt till uppgifter som låser upp Defensive Stance, lär ut viktiga försvarsfärdigheter som Taunt och ger ett pålitligt vapen för karriärens början.",al={"vad låser muren stormpike upp","varför göra muren stormpike","muren stormpikes belöningar"}},{q="Vem är Muren Stormpike?",a="Muren är en veteraninstruktör i strid i Ironforge och tillhör den berömda Stormpike-klanen, en inflytelserik dvärgasläkt känd för sina vilda krigare och ingenjörer på expeditioner.",al={"vem är muren","muren stormpikes bakgrund","tillhör muren stormpike en klan"}},{q="Kan alla klasser ta det här uppdraget?",a="Nej. Uppdraget är endast för krigarnoviser som är redo för specialiserad stridsutbildning.",al={"kan andra än krigare göra muren stormpike","är muren stormpike endast för krigare","muren stormpike och klasser"}},{q="Vad händer när du har rapporterat till Muren?",a="När du har kommit fram och talat med Muren prövar han genast din beslutsamhet genom att skicka dig på ett stridsprov, som börjar med uppdraget att konfrontera Vejrek.",al={"vad händer efter muren stormpike","nästa uppdrag efter muren stormpike","vejrek-uppdraget"}}},fx={["61377fd6"]={q="Varför skickar Granis Swiftaxe dig till Muren Stormpike?",a="Granis Swiftaxe ser verklig potential i din stridsförmåga, men Kharanos kan bara lära dig grunderna. För att utveckla din stridsträning och lära dig vad det verkligen innebär att vara krigare hänvisar han dig till Muren Stormpike, en erfaren veteran som är stationerad i Hall of Arms i Ironforge.",al={"granis swiftaxes motiv","varför skicka mig till muren","varför tala med muren stormpike"}}},fp="15,188,22.252.0,18.287.0,38.116.0,33.89.0,41.143.0,23.162.0,30.76.0,38.100.0"}
P.entries["quest:168"] = {n="Collecting Memories",s="Collecting Memories är ett högtidligt uppdrag som dvärgen och gruvarbetaren Wilder Thistlenettle fått i Stormwind City. Han ber äventyrare som trotsar de förfallna gruvorna under Moonbrook att återfinna hans fallna arbetskamraters Miners' Union Cards. När dessa minnessaker återlämnas får sörjande familjer i huvudstaden visshet efter ett katastrofalt ras.",h="Collecting Memories är ett högtidligt uppdrag som dvärgen och gruvarbetaren Wilder Thistlenettle fått i...",kw={"collecting memories","the deadmines","gruvarbetarnas fackföreningskort","moonbrook","stormwind","odöda gruvarbetare","wilder thistlenettle"},ang={["faction:Alliance"]="Genom att återfinna minnessakerna efter Westfalls fallna arbetare hjälper du direkt de sörjande arbetarfamiljerna som kämpar i Stormwinds skydd.",["profession:Mining"]="Alla gruvarbetare känner den kvardröjande skräcken efter ett schakt som rasat in. Därför väcker uppdraget att återfinna förlorade fackföreningskort djupa och sorgsna känslor hos dem som svingar hacka.",["race:Dwarf"]="Dvärgar värdesätter banden som smids under jord och vördnaden för fallna bröder högt. Därför känns Wilder Thistlenettles vädjan personlig för andra av hans stenfolk."},sec={{t="Ett tragiskt ras",b="Innan Moonbrook helt föll i laglöshet och Defias Brotherhoods skugga var Westfalls gruvor en viktig försörjningskälla för många arbetarfamiljer. Wilder Thistlenettle överlevde ett förödande ras som begravde en del av de labyrintiska tunnlarna, men många av hans vänner och arbetskamrater hade inte samma tur. Avskurna från räddning omkom arbetarna djupt under jord och lämnade sörjande anhöriga i Stormwind utan bekräftelse eller visshet om sina närståendes öde."},{t="Oroliga kvarlevor",b="Tunnlarna utanför det stora underjordiska järnverket är inte längre tysta gravkamrar. Gruvarbetarnas själar, som omkom i raset, vandrar nu genom de mörka gångarna som oroliga, odöda skepnader. För att återfinna Miners' Union Cards måste resenärer ta sig genom dessa hemsökta schakt och möta de levande kvarlevorna av gruvarbetarna som Wilder en gång arbetade med. När korten återlämnas till Stormwind får deras anhöriga äntligen veta sanningen, och Wilder får möjlighet att hedra sina fallna bröder."}},faq={{q="Vem är Wilder Thistlenettle?",a="Wilder Thistlenettle är en dvärg och gruvarbetare som bor i Stormwind City. Han överlevde ett katastrofalt tunnelras under Westfall som tog livet av hans nära arbetskamrater och vill nu ge deras efterlevande familjer visshet och ro.",al={"wilder thistlenettle","uppdragsgivare","vem ger uppdraget collecting memories"}},{q="Vad hände med gruvarbetarna i Deadmines?",a="Ett förödande tunnelras stängde in och dödade ett helt arbetslag i en del av Moonbrooks gruvor. Utan räddning eller ordentlig begravning har deras andar och kroppar återuppstått som oroliga odöda som hemsöker de övergivna gångarna.",al={"varför finns det odöda gruvarbetare","ras i gruvan","ras i deadmines"}},{q="Varför vill Wilder ha deras Miners' Union Cards?",a="Fackföreningskorten fungerar som officiell identifikation för arbetarna som dog i raset. Eftersom kropparna aldrig återfanns kan Wilder använda korten för att underrätta deras familjer i Stormwind och ge dem visshet.",al={"vad är fackföreningskorten till för","gruvarbetarnas fackföreningskort"}},{q="Var finns fackföreningskorten?",a="Korten finns i de hemsökta yttre tunnlarna under Moonbrook, i gångarna strax före den bevakade ingången till själva Deadmines.",al={"var hittar jag korten","var finns de odöda i deadmines","var finns de döda gruvarbetarna"}},{q="Orsakade Defias Brotherhood raset?",a="Wilder Thistlenettle minns det bara som en hemsk gruvolycka och ett tunnelras. Defias Brotherhood styr nu de djupa gångarna i Deadmines, men själva tragedin verkar ha varit ett katastrofalt industriellt ras som stängde in hans arbetskamrater.",al={"orsakade defias raset","vem rasade gruvan"}},{q="Tillhörde gruvarbetarna Defias Brotherhood?",a="Nej. De var vanliga gruvarbetare i facket som arbetade i gruvorna när raset inträffade. Deras oroliga odöda kvarlevor vandrar i grottornas utkanter, åtskilda från Edwin VanCleefs organiserade Defias-styrkor längre in.",al={"tillhör döda gruvarbetare defias","är odöda gruvarbetare med defias"}}},fx={e1328ead={q="Vad är Miners' Union Card?",a="Dessa fackföreningskort fungerade som officiell legitimation för arbetarna i Moonbrooks rika gruvor före katastrofen. Nu är de det enda bestående beviset på vilka som omkom under jorden när tunnlarna rasade. Att återfinna dem är det enda sättet att bekräfta vilka arbetare som mötte sitt slut där nere, så att Wilder Thistlenettle kan underrätta deras sörjande familjer i Stormwind och ge dem ett avslut.",al={"miners union card","vad är fackföreningskorten","fackföreningskort"}},["22601dce"]={q="Varför behöver Wilder Thistlenettle en äventyrare för den här uppgiften?",a="Wilder Thistlenettle överlevde det fruktansvärda raset, men sedan dess har djupen i Moonbrooks gruvor fallit i farligt kaos. Området kring det gamla raset är översvämmat av fientliga styrkor och rastlösa döda, långt bortom vad en vanlig civilperson eller före detta gruvarbetare kan möta. Eftersom inga stadsvakter har skickats in i Westfalls förrädiska ruiner förlitar sig Wilder på dugliga äventyrare som ändå tänker utforska gruvorna och kan söka igenom rasmassorna efter hans försvunna vänner.",al={"varför ska jag samla minnen","varför behöver wilder hjälp","varför skicka en äventyrare"}}},fp="19,167,17.365.0,16.332.0,28.191.0,45.152.0,47.200.0,32.131.0,45.194.0,57.175.0"}
P.entries["quest:1680"] = {n="Tormus Deepforge",s="Tormus Deepforge är en vapensmed i Ironforge som fått i uppdrag att förse lovande kämpar med vapen av Muren Stormpike. Innan han smider ett specialbeställt vapen kräver Tormus att The Adventurer genomgår ett farligt prov för att bevisa sin styrka.",h="Tormus Deepforge är en vapensmed i Ironforge som fått i uppdrag att förse lovande kämpar med vapen av Muren...",kw={"dvärgsmed","great forge","ironforge","muren stormpike","tormus deepforge","krigaruppdrag","vapensmed"},ang={["class:Warrior"]="Muren Stormpike skickar krigare under utbildning till Tormus Deepforge i Ironforge för att de ska bevisa sitt mod och få ett specialsmitt vapen som passar deras brutala kall.",["faction:Alliance"]="Mästersmederna i Ironforge prövar ofta lovande krigare i Alliansen med farliga uppgifter innan de smider fina vapen åt dem."},sec={{t="Smedens städ",b="Tormus Deepforge är en mästersmed bland dvärgarnas vapensmeder i Ironforge. När krigare visar Muren Stormpike att de blir allt skickligare skickas de genom staden för att träffa Tormus. Han är känd för att smida robusta och kraftfulla vapen, men delar inte bara ut fina klingor och klubbor till vem som än dyker upp vid hans städ. Krigarna måste förtjäna hans hantverk genom handling."},{t="Ett farligt prov",b="Innan Tormus går med på att bearbeta het metall åt en äventyrare kräver han ett löfte om en gentjänst. Som en typisk dvärg skräder han inte orden om farorna som väntar och varnar för att uppdraget innebär verklig livsfara. För Tormus är en uppgift fylld av faror och risk för döden inget avskräckande, utan det perfekta provet på en krigares mod."}},faq={{q="Vem är Tormus Deepforge?",a="Tormus Deepforge är en skicklig vapensmed bland dvärgarna, verksam vid Great Forge i Ironforge. Han kan smida utomordentliga vapen åt krigare som visar sig vara kapabla och modiga nog att ta sig an farliga uppgifter.",al={"vem är tormus","tormus deepforge ironforge","vem är tormus deepforge"}},{q="Vem skickar dig till Tormus Deepforge?",a="Muren Stormpike, den erfarne krigartränaren i Ironforge, skickar lovande kämpar till Tormus Deepforge när de är redo att få ett vapen smitt som passar deras växande stridsförmåga.",al={"vem skickade mig till tormus","varför prata med tormus","muren stormpikes hänvisning"}},{q="Vad begär Tormus Deepforge i utbyte mot att smida ett vapen?",a="Tormus går med på att smida ett fint vapen, men kräver först en gentjänst. Han insisterar på ett farligt uppdrag som mycket väl kan innebära döden och menar att det är precis den sortens utmaning en blivande krigare söker.",al={"tormus gentjänst","vilket vapen smider tormus","vad vill tormus"}},{q="Varför betonar Tormus att uppdraget är farligt?",a="Uppgiften Tormus tänker på innebär betydande faror. I stället för att avskräcka kämpar anser han att dödliga uppdrag är det enda rätta provet för den som förtjänar att bära ett vapen smitt av honom.",al={"är tormus deepforge farlig","vad är tormus uppdrag","krigaruppdrag i ironforge med tormus"}},{q="Var hittar man Tormus Deepforge?",a="Tormus Deepforge arbetar nära Great Forge i dvärgarnas huvudstad Ironforge, omgiven av andra smeder, städ och dånande smältugnar.",al={"var finns tormus","tormus deepforge plats"}},{q="Vilka äventyrare arbetar Tormus Deepforge med?",a="Tormus arbetar särskilt med krigare som skickats av sina tränare. Han söker personer med den stridsvilja och beslutsamhet som krävs för att ta sig an livsfarliga ärenden.",al={"vilken klass får tormus uppdrag","är tormus deepforge bara för krigare"}}},fp="16,248,22.399.0,16.353.0,24.242.0,45.192.0,61.197.0,52.189.0,36.139.0,50.160.0"}
P.entries["quest:1681"] = {n="Ironband's Compound",s="Smeden Tormus Deepforge från Ironforge söker hämnd för sin mentor Sturgy Ironband, vars avlägsna läger för lärlingar i östra Dun Morogh föll offer för ett plötsligt och blodigt anfall. Massakern följde på ankomsten av en sällsynt leverans umbralmalm, som genast väckte Dark Iron-dvärgarnas våldsamma intresse.",h="Smeden Tormus Deepforge från Ironforge söker hämnd för sin mentor Sturgy Ironband, vars avlägsna läger för...",kw={"smide","dark iron","dun morogh","helm's bed lake","ironband's compound","sturgy ironband","tormus deepforge","umbralmalm"},ang={["profession:Blacksmithing"]="Sturgy Ironbands tragiska öde visar hur jakten på exotiska, oprövade malmer kan dra dödliga faror till smedjan.",["race:Dwarf"]="Anfallet mot Ironbands utpost visar det bittra och långvariga hatet mellan Bronzebeard-dvärgarna i Ironforge och deras Dark Iron-släktingar."},sec={{t="En mästares fall",b="Sturgy Ironband vördades i hela Ironforge som en oöverträffad lärare i smide. Från sitt avskilda läger söder om Helm's Bed Lake undervisade han lovande elever, långt från Great Forges trängsel vid städet. Den fredliga verksamheten fick ett abrupt slut när en av hans elever skaffade ett okänt mineral som kallades umbralmalm. Ironband blev nyfiken på dess egenskaper och bestämde sig för att experimentera med provet, helt ovetande om att innehavet hade gjort hans skola till mål för förödelse."},{t="Dark Iron-anfallet",b="Kort efter att umbralmalmen nådde lägret gick fientliga Dark Iron-dvärgar till en hänsynslös överraskningsattack mot utposten. Angriparna visade ingen nåd. De dödade Sturgy Ironband och alla lärlingar under hans ledning innan de tog området i besittning. Tormus Deepforge, en av Ironbands tidigare lärlingar som överlevde och nu bor i huvudstaden, vägrar låta massakern stå oemotsagd. Han skickar ut Alliance-resenärer för att hämnas sin lärare och återta den förbannade malm som förde förödelse över lägret."}},faq={{q="Var ligger Ironband's Compound?",a="Ironband's Compound ligger i östra Dun Morogh, undangömt bland de snötäckta kullarna söder om Helm's Bed Lake.",al={"ironbands läge","var ligger lägret","hitta ironband's compound"}},{q="Vem var Sturgy Ironband?",a="Sturgy Ironband var en berömd dvärgmästare i smide. Han drev ett särskilt läger för undervisning utanför Ironforge, där han lärde elever avancerad metallbearbetning innan han dödades i ett Dark Iron-anfall.",al={"vem är ironband","sturgy ironbands bakgrund","vem var sturgy"}},{q="Varför anföll Dark Iron-dvärgarna lägret?",a="Anfallet utlöstes av en leverans umbralmalm som en av Ironbands elever hade fört dit. Kort efter att malmen anlänt stormade Dark Iron-dvärgarna lägret, dödade alla där och tog kontroll över platsen.",al={"varför anfalla","varför dark iron-anfallet","dark irons motiv"}},{q="Vad är umbralmalm?",a="Umbralmalm är ett ovanligt och gåtfullt mineral. Mästare Ironband ville gärna smida med det, men dess ankomst väckte genast Dark Iron-klanens dödliga intresse.",al={"umbralmalmens bakgrund","vad är umbralmalm","märklig malm"}},{q="Vem är Tormus Deepforge?",a="Tormus Deepforge är smed i Ironforge och tidigare lärling till Sturgy Ironband. Förkrossad över att ha förlorat sin lärare skickar han ut äventyrare för att straffa Dark Iron-intrångarna och hämta malmen.",al={"vem ger uppdraget vid ironband's compound","tormus deepforges bakgrund","vem är deepforge"}},{q="Vad vill Tormus att man hämtar från lägret?",a="Tormus ger resenärer i uppdrag att döda Dark Iron-rövarna för att hämnas Ironband och säkra leveransen umbralmalm som orsakade katastrofen.",al={"vad ska hämtas","lägrets mål","lämna in uppdrag"}}},fp="19,204,15.456.0,18.428.0,37.73.0,24.175.0,50.198.0,19.146.0,24.190.0,50.144.0"}
P.entries["quest:1683"] = {n="Vorlus Vilehoof",s="Vorlus Vilehoof är ett övergångsprov för unga nattalvskrigare som tränar i Darnassus. På krigartränaren Elanarias uppmaning måste aspiranterna jaga rätt på en vidrig satyr som har skändat en dold månskälla nära Ban'ethil Barrow Den.",h="Vorlus Vilehoof är ett övergångsprov för unga nattalvskrigare som tränar i Darnassus.",kw={"ban'ethil","darnassus","elanaria","vorlus horn","månskälla","satyr","teldrassil","vorlus vilehoof","krigaruppdrag"},ang={["class:Warrior"]="Jakten på Vorlus Vilehoof är din invigning i avancerad stridsträning. Den visar att ditt svärd skyddar kaldoreiernas land och gudinnans helighet.",["faction:Alliance"]="Genom att säkra Teldrassils inre mot kvarvarande demoner ser du till att Darnassus förblir en stadig fästning för Alliansen i norra Kalimdor.",["race:NightElf"]="Månskällor står för Elunes renhet och kaldorei-andlighetens livsblod. Att tåla att en satyr badar i deras vatten är en outhärdlig förolämpning mot alla nattalver."},sec={{t="Ett prov på beslutsamhet",b="Innan Elanaria lär ut avancerade stridstekniker till unga nattalvskrigare kräver hon bevis på deras hängivenhet och disciplin. Ord betyder ingenting när Kalimdor ska försvaras. En sann väktare måste våga möta fördärvet ansikte mot ansikte och rena Teldrassils heliga grenar från smitta."},{t="De heliga vattnen skändas",b="Målet för detta prov är Vorlus Vilehoof, en satyr som har tagit sig in i en avskild månskälla bland bergen sydost om Ban'ethil Barrow Den. Satyrerna är urgamla förrädare, förvridna av demoniskt inflytande, och hyser ett djupt hat mot heliga kaldorei-reliker. Vorlus har börjat bada i månskällan och smutsa ner dess välsignade vatten med sin närvaro, samtidigt som han hånar Elunes nåd."},{t="Att hämta hornet",b="För att hitta Vorlus måste du följa en dold bergsstig som vaktas av fientliga Gnarlpine-furbolger. När satyren väl trängts in vid den fördärvade källan måste han fällas i strid. Om du tar Vorlus horn tillbaka till Warrior's Terrace i Darnassus bevisar du att besten är död. Då återställs heligheten i den avskilda gläntan och vägen öppnas till särskilda stridsvapen."}},faq={{q="Vem är Vorlus Vilehoof?",a="Vorlus Vilehoof är en fördärvad satyr som håller till på Teldrassil. Han upptäckte en avskild månskälla sydost om Ban'ethil Barrow Den och började bada i den och aktivt skända dess invigda vatten.",al={"vorlus vilehoofs bakgrund","vem är vorlus","vorlus, satyren"}},{q="Varför skickar Elanaria krigare efter Vorlus?",a="Elanaria använder jakten som ett prov för lovande krigare. Att besegra en farlig, fördärvad fiende som Vorlus visar den koncentration, det mod och den beslutsamhet som krävs innan hon lär ut avancerade stridsfärdigheter eller vägleder dem i att smida särskilda vapen.",al={"varför döda vorlus","varför elanaria ger uppdraget","syftet med uppdraget vorlus vilehoof"}},{q="Var ligger den dolda månskällan?",a="Månskällan ligger dold bland bergsryggarna sydost om Ban'ethil Barrow Den. För att nå den måste du hitta en svårupptäckt bergsstig med facklor längs vägen, precis bakom ett läger med Gnarlpine-furbolger öster om gravhögarna.",al={"vorlus plats","hur hitta vorlus","stigen till den dolda månskällan"}},{q="Vad är en månskälla, och varför spelar hans närvaro roll?",a="Månskällor är heliga bassänger fyllda med välsignat vatten som förmedlar Elunes ljus och upprätthåller naturens livskraft. Att en demonisk satyr som Vorlus vältrar sig i en sådan betraktas som en direkt skändning av kaldorei-tron och en farlig källa till fördärv på Teldrassil.",al={"varför månskällor är viktiga","skändning av månskällan","nattalvernas månskällor"}},{q="Vad händer efter att Vorlus Vilehoof har besegrats?",a="När du återvänder med Vorlus avhuggna horn blir Elanaria nöjd och får bekräftat att krigaren är redo. Därefter skickar hon krigaren vidare för att söka efter de legendariska Weapons of Elunite, med början i sökandet efter Shade of Elura.",al={"nästa uppdrag efter vorlus","vad händer härnäst","uppdraget shade of elura"}},{q="Finns det fler satyrer på Teldrassil?",a="Ja. Trots att Teldrassil är relativt ungt lurar satyrer på platser som Fel Rock och i utspridda fördärvade hålor. De försöker ständigt smitta Världsträdet med demoniskt fördärv.",al={"satyrer på teldrassil","satyrhotet mot teldrassil"}}},fx={["2a0bd33d"]={q="Varför vill Elanaria att Vorlus Vilehoof dödas?",a="För Elanaria och nattalverna är månkällor heliga fristäder fyllda med välsignat vatten. Vorlus Vilehoof har upptäckt en avskild månkällare sydost om Ban'ethil Barrow Den och vanhelgar den aktivt genom att skvätta sin korrumperade satyrsmuts över den heliga dammen. Elanaria kan inte låta sådan skändning fortgå på Teldrassil, och att döda odjuret undanröjer ett omedelbart hot om korruption mot det stora trädet.",al={"elanarias motiv","varför döda vorlus","elanarias skäl till att döda vorlus"}}},fp="15,156,17.240.0,26.311.0,17.295.1,23.189.0,45.248.0,37.186.0,53.223.0,43.203.1,37.140.0"}
P.entries["quest:1685"] = {n="Gakin's Summons",s="En kallelse som Remen Marcot överlämnar på uppdrag av Gakin the Darkbinder till lovande häxmästare i Alliansen. Den leder nybörjare ner i kryptorna under Slaughtered Lamb i Stormwinds Mage Quarter, där de inleder nästa steg i sin mörka ockulta utbildning.",h="En kallelse som Remen Marcot överlämnar på uppdrag av Gakin the Darkbinder till lovande häxmästare i...",kw={"demonologi","gakin the darkbinder","mage quarter","remen marcot","slaughtered lamb","stormwind","voidwalker","häxmästare"},ang={["class:Warlock"]="Kallelsen markerar att du lämnar salongstrick och små imps bakom dig och inleder prövningarna som krävs för att förslava en voidwalker som skyddar dig i strid.",["faction:Alliance"]="Till och med i Stormwinds hjärta tolererar Alliansen en underjordisk skuggvävarsekt vars kunskap om fel ger dem ett skuggornas övertag mot fienderna."},sec={{t="Ett diskret meddelande",b="Demonologi är strängt förbjuden i Stormwinds civiliserade kvarter, men de mörka konsterna frodas ändå mitt framför stadsvaktens ögon. När en häxmästare visar tillräcklig skicklighet med sina första imparationer sprids ordet i tysthet till mer erfarna utövare. Remen Marcot överlämnar meddelandet med stor diskretion och uppmanar de nya att hålla mötesplatsen hemlig och bege sig ner i de skuggiga utrymmena under Mage Quarter."},{t="Slaughtered Lambs kryptor",b="Bakom Slaughtered Lambs anspråkslösa fasad finns ett nätverk av fuktiga källare och dolda katakomber. Här leder Gakin the Darkbinder undervisningen för Stormwinds häxmästare, skyddad från nyfikna Kirin Tor-magiker och Cathedral of Lights inkvisitorer. Kallelsen är vägen till att bemästra en voidwalker, en rit som kräver farliga stulna reagenser och riskfyllda frammaningscirklar."}},faq={{q="Varför kallar Gakin the Darkbinder på häxmästare?",a="Gakin kallar på blivande häxmästare när de har nått tillräcklig erfarenhet. Han anser att otränade häxmästare är en belastning som lätt tappar huvudet och vill lära dem den komplicerade ritualen för att binda en voidwalker i sin tjänst.",al={"varför gakin kallar","vad är gakin-kallelsen till för","start på voidwalker-uppdraget"}},{q="Var finns Gakin the Darkbinder?",a="Gakin håller sig gömd i de djupa underjordiska kryptorna under Slaughtered Lamb, en krog i Stormwinds Mage Quarter.",al={"var finns gakin","gakins plats","källaren under slaughtered lamb"}},{q="Vem är Remen Marcot?",a="Remen Marcot är knuten till Stormwinds häxmästarkult och håller till i källaren på Lion's Pride Inn i Goldshire. Där letar han upp lovande kandidater och visar dem i tysthet till Gakins gömda tillhåll.",al={"remen marcot","vem startar gakin-kallelsen"}},{q="Varför måste platsen hållas hemlig?",a="Fel-magi och demonframmaning är förbjudna i kungariket Stormwind. Om Silver Hand, Cathedral of Light eller stadsvakten upptäcker dem väntar fängelse eller avrättning.",al={"varför hemligt","häxmästarnas hemlighetsmakeri i stormwind"}},{q="Vad händer när man har svarat på Gakins kallelse?",a="När häxmästaren har rapporterat till Gakin skickar han denne till Brackwell Pumpkin Patch i Elwynn Forest för att hämta ett Bloodstone Choker från Surena Caledon. Det är en viktig del av ritualen för att binda en voidwalker.",al={"nästa uppdrag efter gakins kallelse","vad händer sedan"}},{q="Kan andra än häxmästare få den här kallelsen?",a="Nej. Kallelsen är endast avsedd för häxmästare som har bemästrat sin grundläggande imp-följeslagare och behöver avancerad ockult undervisning.",al={"kan magiker få den här","vem kan göra gakins kallelse"}}},fx={["0d517c2f"]={q="Varför vill Remen Marcot att du ska träffa Gakin?",a="Remen Marcot följer enbart order från Master Gakin the Darkbinder. Han ägnade hela dagen åt att genomsöka staden för att hitta dig och blev ordentligt frustrerad på kuppen. Det enda han bryr sig om är att slutföra uppdraget så att han kan sluta jaga dig och återgå till sina egna ärenden. Han varnar dig för att rapportera snabbt, innan din mästare tappar tålamodet.",al={"varför skickar remen dig till gakin","remen marcots motiv","varför letar remen efter dig"}}},fp="15,265,18.434.0,34.392.0,46.241.0,38.128.0,20.204.0,37.188.0,43.219.1,38.135.0"}
P.entries["quest:1686"] = {n="The Shade of Elura",s="”The Shade of Elura” är en tidig övergångsrit för unga nattalvskrigare, ledd av krigartränaren Elanaria i Darnassus. Krigaren får i uppdrag att dyka ner i vattnet utanför Auberdine, ge en plågad sjökaptens vålnad ro och bärga lådor med sällsynt Elunite-malm. Materialet ger grunden för att smida ett personligt vapen.",h="”The Shade of Elura” är en tidig övergångsrit för unga nattalvskrigare, ledd av krigartränaren Elanaria i...",kw={"auberdine","darkshore","darnassus","elanaria","elunite-malm","elura","the shade of elura","smith mathiel","vapen av elunite"},ang={["class:Warrior"]="Det här uppdraget är ett avgörande steg i en nattalvskrigares karriär. Det prövar modet i vattnet och kampdisciplinen för att förtjäna ett smitt vapen av Elunite.",["profession:Blacksmithing"]="Bärgningen av sjunken Elunite visar nattalvernas unika metallurgiska traditioner. De smider kraftfulla vapen av välsignade material.",["race:NightElf"]="Att ge Eluras skugga ro hedrar en kaldorei vars gränslösa pliktkänsla höll henne fången under vågorna i generationer."},sec={{t="En kaptens eviga vakt",b="För länge sedan förliste ett fartyg med en last av sällsynt Elunite-malm mot de vassa kustklipporna nära fyren i Auberdine. Förtvivlad och orubbligt trogen sin plikt lade kaptenen Elura en förbannelse över sin egen själ. Hennes skugga är bunden till vraket under vågorna och dröjer kvar på havsbottnen för att försvara sin förlorade last mot alla som vågar störa den."},{t="Vapen av Elunite",b="För nattalvskrigare som börjar finna sin plats krävs både kampkonst och vördnad för fallna fränder för att göra anspråk på sitt första riktiga, smidda vapen. Tränaren Elanaria skickar blivande krigare ut i Darkshores kalla bränningar, inte bara för att bärga metall, utan också för att besegra The Shade of Elura och återta hennes medaljong. När Elura får ro befrias den förbannade kaptenen från sin vakt, och malmen som behövs till smeden Smith Mathiels ässja blir tillgänglig."}},faq={{q="Vem är The Shade of Elura?",a="Elura var kapten på ett alvfartyg som förliste på de förrädiska grunden nära fyren i Auberdine. I stället för att överge sin plikt förbannade hon sig själv, i liv eller död, att för all framtid vaka över fartygets sjunkna last av Elunite-malm.",al={"the shade of eluras historia","vem är elura","kapten elura"}},{q="Varför skickar Elanaria krigare efter Elura?",a="Elanaria vill både ge Eluras plågade ande ro och återta den sjunkna Elunite-malmen. Att besegra kaptenen och ta hennes medaljong bevisar en ung krigares skicklighet och säkrar råmaterialet som krävs för att smida ett bättre vapen.",al={"varför dödar vi elura","syftet med elanarias uppdrag"}},{q="Var skedde förlisningen?",a="Vraket ligger under vatten utanför Auberdines kust i Darkshore, nära fyren och strax söder om hamnens huvudkajer. Delarna ligger utspridda på havsbottnen.",al={"var ligger skeppsvraket","var ligger eluras skepp"}},{q="Vad används Elunite-malm till?",a="Elunite är en sällsynt malm som värdesätts av nattalvernas smeder. I det här provet lämnas de bärgade lådorna till smeden Smith Mathiel i Darnassus, som smider ett personligt vapen åt lovande krigare.",al={"vad är elunite","vad används elunite-malm till"}},{q="Skadar det Elura för alltid att besegra hennes skugga?",a="När hennes skugga besegras bryts den självförvållade förbannelse som binder hennes ande till havsbottnen. Som Elanaria säger får kaptenen den välförtjänta ron efter sin långa, kalla och övernaturliga vakt.",al={"dog elura","blir elura räddad"}},{q="Vem smider vapnet när malmen har bärgats?",a="När Elanaria fått malmen och medaljongen visar hon krigaren till Smith Mathiel i Warrior's Terrace i Darnassus. Där formar han metallen till ett enastående vapen.",al={"vem smider elunite-vapnet","nästa uppdrag efter elura"}}},fx={["522232db"]={q="Varför skickar Elanaria dig i stället för att själv hämta malmen?",a="Som din krigartränare vägleder Elanaria dig genom övergångsriten till verkligt mästerskap i strid. Att återfinna elunitmalmen är inte bara ett förrådsärende åt Darnassus. Genom att trotsa farorna i djupen utanför Auberdine och ge Captain Eluras rastlösa ande ro bevisar du att du har modet och skickligheten som krävs för att bära ett specialsmitt vapen för en krigare.",al={"varför ska jag hjälpa shade of elura","varför skickar elanaria en krigare","varför skickas inga vakter efter elura"}}},fp="18,224,25.293.0,18.338.0,26.155.0,44.169.0,27.122.0,29.175.0,48.157.0,48.166.0"}
P.entries["quest:1688"] = {n="Surena Caledon",s="Under Slaughtered Lamb i Stormwind söker Gakin sin före detta elev och ett Bloodstone Choker. Han skickar en blivande häxmästare efter Surena Caledon, som förrådde honom och gick med i Defias Brotherhood.",h="Under Slaughtered Lamb i Stormwind söker Gakin sin före detta elev och ett Bloodstone Choker.",kw={"bloodstone choker","brackwell pumpkin patch","defias","erlan drudgemoor","gakin the darkbinder","slaughtered lamb","surena caledon","voidwalker"},ang={["class:Warlock"]="Som häxmästare ställs du inför ett elddop när du jagar Surena Caledon. Gakin lär ut att förräderi har ett dödligt pris och att känslor inte hör hemma i de mörka konsterna.",["race:Human"]="Som människa ser du hur Defias Brotherhood fortsätter att locka missnöjda invånare i kungariket Stormwind."},sec={{t="En bitter mästare",b="Under Slaughtered Lamb i Stormwinds Mage Quarter lär Gakin the Darkbinder noviser de förbjudna konsterna i att åkalla demonisk magi. En gång tog han en ung kvinna vid namn Surena Caledon som sin elev. Han beundrade hennes naturliga magiska talang och hennes skönhet. Surena övergav sina studier och Gakins gunst och flydde sedan från Stormwind med sin älskare, Erlan Drudgemoor, för att gå med i Defias Brotherhood."},{t="Den stulna blodstenen",b="Gakin bryr sig inte om huruvida Surena överlever, men han vill ha tillbaka Bloodstone Choker som han gav henne under hennes lärlingstid. Han skickar sin nyaste lärling sydost till Brackwell Pumpkin Patch i Elwynn Forest, en gård som översvämmats av Defias-banditer. Lärlingen ska ta juvelen från Surena med alla nödvändiga medel. Blodstenen ska fungera som magisk katalysator för nästa prövning: att åkalla och binda en Voidwalker."}},faq={{q="Vem är Surena Caledon?",a="Surena Caledon var lärling hos Gakin the Darkbinder i Stormwind. Hon hade en naturlig talang och vann hans gunst och gåvor innan hon övergav sina studier och flydde med Erlan Drudgemoor, en Defias-bandit.",al={"surenas historia","vem är surena","surena caledons bakgrund"}},{q="Varför vill Gakin ha tillbaka hennes halssmycke?",a="Gakin gav Surena halssmycket under hennes lärlingstid, och i det sitter en värdefull blodsten. Han hyser agg mot henne för hennes förräderi och behöver stenen som ritualingrediens för att hjälpa sin nya lärling att binda en Voidwalker.",al={"varför hämta halssmycket","blodstenens betydelse i halssmycket"}},{q="Var kan Surena Caledon hittas?",a="Surena kan hittas bland sina Defias-kamrater vid Brackwell Pumpkin Patch, en övergiven gård i sydöstra Elwynn Forest.",al={"surenas plats","var finns surena","var ligger pumpagården"}},{q="Vad händer när man återfår halssmycket?",a="När du återlämnar Bloodstone Choker till Gakin klarar du prövningen. Nästa steg är att gå in i åkallandecirkeln i kryptorna under Slaughtered Lamb och binda en Voidwalker från Twisting Nether.",al={"what comes next","nästa uppdrag efter surena"}},{q="Vem är Erlan Drudgemoor?",a="Erlan Drudgemoor är en skurk i Defias Brotherhood. Han förförde Surena Caledon och övertalade henne att överge sin häxmästarträning och fly från Stormwind för att leva bland banditerna.",al={"erlans historia","vem är erlan drudgemoor"}},{q="Känner Gakin någon ånger över Surenas öde?",a="Gakin känner ingen ånger över Surenas öde. Han säger att hennes liv inte betyder något för honom och att det är synd att hennes magiska talang går till spillo, men att hennes förräderi gör det nödvändigt att röja henne ur vägen.",al={"bryr sig gakin","gakins reaktion på surena"}}},fx={["8bc53c35"]={q="Vad ska Surena's Choker användas till?",a="Halsbandet är ett förtrollat smycke av blodsten som Gakin the Darkbinder i sin enfald gav till sin tidigare lärling. För en häxmästare har blodsten rå kraft för magi och åkallan. Gakin behöver artefaktens kvarvarande kraft för att förbereda ritualcirkeln under Slaughtered Lamb, så att du kan åkalla och binda en voidwalker till din vilja.",al={"vad ska surena's choker användas till","varför bloodstone choker","vad gör halsbandet"}},["703ff238"]={q="Varför skickar Gakin en lärling i stället för att själv ta hand om Surena?",a="Häxmästare i Stormwind verkar i strikt hemlighet under Slaughtered Lamb. Kungarikets lagar förbjuder dem, och de jagas om de avslöjas. Gakin kan inte be stadsvakten hämta ett olagligt magiskt arvegods från Defiaslaglösa, och han kan inte heller lämna sin helgedom för att reda ut en personlig förödmjukelse. Genom att skicka dig prövar han din hänsynslöshet och ser om du har den styrka som krävs för att bemästra mörka konster.",al={"varför skicka mig efter surena","varför kan inte gakin hämta halsbandet","varför går inte gakin själv"}}},fp="14,196,15.376.0,21.419.1,22.198.0,36.201.0,34.128.0,41.199.1,24.176.0,47.179.0"}
P.entries["quest:1689"] = {n="The Binding",s="I Stormwind sätter Gakin the Darkbinder en novis häxmästare på sitt sista prov. Med sin återfunna Bloodstone Choker kallar du en voidwalker till en dold cirkel och tvingar den att underkasta sig.",h="I Stormwind sätter Gakin the Darkbinder en novis häxmästare på sitt sista prov.",kw={"bindning","bloodstone choker","gakin the darkbinder","mage quarter","slaughtered lamb","stormwind","kallelsecirkel","voidwalker"},ang={["class:Warlock"]="Som häxmästare får du en voidwalker som försvarar dig. Riten markerar din övergång från novis besvärjare till befälhavare över krafter från andra världar.",["faction:Alliance"]="Som medlem av Alliansen tjänar du en sak som värnar det Heliga Ljuset och den arkana ordningen. I farliga tider blundar pragmatiska ledare för mörka utövare under Mage Quarter.",["race:Gnome"]="Som gnomisk häxmästare använder du ditt skarpa, nyfikna intellekt vid mörka besvärjelser. Under Gakins ledning studerar du underkuvandet av varelser från tomrummet som ett metafysiskt experiment.",["race:Human"]="Som mänsklig häxmästare granskas du noga av Stormwinds prästerskap. Du bemästrar farliga varelser i skuggorna och håller din kraft dold för staden ovanför."},sec={{t="Underkuvande i kryptorna",b="Under Slaughtered Lamb i Stormwinds Mage Quarter sträcker sig bortglömda katakomber bortom Silver Hands vaksamma blick och Kirin Tor-domarnas uppsikt. Gakin the Darkbinder lär novisa häxmästare att mörk magi kräver mer än att kanalisera kraft; de måste också betvinga varelser från andra världar. Du har återfått Gakins stulna Bloodstone Choker från Surena Caledon. Nu ber han dig kalla en voidwalker till kallelsecirkeln under värdshuset."},{t="Viljan över tomrummet",b="En voidwalker förhandlar inte med dig. Kraften i Bloodstone Choker öppnar en reva och drar skuggvarelsen in i den dödliga världen. Du måste slå den med magi och våld tills dess vilja bryts och bevisa att du kan befalla den. När den besegrats binds voidwalkerns väsen till dig och ger dig en tålig, skuggfylld beskyddare som kan uthärda stryk i de kommande striderna."}},faq={{q="Var ligger kallelsecirkeln?",a="Kallelsecirkeln ligger djupt nere i källarkatakomberna under The Slaughtered Lamb i Stormwinds Mage Quarter. Följ trapporna från Gakin the Darkbinder genom de underjordiska gångarna ner till den nedersta kammaren, där en glödande lila runa för ritualen markerar stengolvet.",al={"kallelsecirkelns plats","var kallar jag på voidwalkern","var finns cirkeln"}},{q="Vem är Gakin the Darkbinder?",a="Gakin the Darkbinder är en tränare för häxmästare som arbetar under The Slaughtered Lamb i Stormwind. I hemlighet lär han lovande människor och gnomer att kalla på och kontrollera demoniska varelser och varelser berörda av tomrummet, långt från stadsvakten och kyrkans myndigheter.",al={"vem är gakin","gakin the darkbinder historia","gakin"}},{q="Vad används Bloodstone Choker till?",a="Surena Caledon stal Bloodstone Choker innan du återfick den åt Gakin. Dess fokuserade magi hjälper en novis häxmästare att bryta igenom slöjan och dra en voidwalker till kallelsecirkeln.",al={"bloodstone choker användning","varför behöver jag halsbandet","halsband"}},{q="Varför måste häxmästare slåss mot sina demoner för att binda dem?",a="Demoner och varelser från tomrummet tjänar inte dödliga mästare frivilligt. En häxmästare måste bryta ner en av dem i strid med styrka och vilja innan den binds till tjänst.",al={"varför slåss jag mot voidwalkern","varför kuva demoner","demonunderkuvande"}},{q="Vad händer efter att ritualen slutförts?",a="När du har besegrat varelsen och återlämnat halsbandet till Gakin får du kunskapen och tekniken att kalla på och befalla en lojal voidwalker som skyddar dig på dina resor.",al={"vilken belöning får jag","voidwalker-besvärjelse","efter bindningen"}},{q="Varför utförs ritualen i hemlighet under ett värdshus?",a="Demonologi och magi från tomrummet är tabubelagda, och den Heliga Ljusets kyrka och Alliansens magiker ser dem med fientlighet. Häxmästare i Stormwind verkar i dolda källare och katakomber, långt från myndigheterna.",al={"varför gömd under värdshuset","är felmagi olaglig","slaughtered lambs källare"}}},fx={bc8c924d={q="Varför vill Gakin the Darkbinder att du ska binda en voidwalker?",a="Gakin ser en outnyttjad potential i dig efter att du återfann hans Bloodstone Choker, men han anser att din magiska träning är ofullständig. Att vara en sann häxmästare kräver långt mer än att kanalisera skuggkrafter. Det kräver viljan att kuva varelser från Nether. Innan han kan lära dig att styra en voidwalker i strid måste du bevisa din överlägsenhet över en med egen kraft.",al={"varför vill gakin ha det här","gakins motiv","varför binda en voidwalker"}},["8fb1392b"]={q="Vad är voidwalkern du åkallar?",a="Du kallar en fientlig varelse från Twisting Nether till åkallandecirkeln under värdshuset. Voidwalkers är skuggvarelser som tål mycket och drivs av kaotisk illvilja. Den här varelsen lockas över gränsen av Bloodstone Chokers kraft och går genast till angrepp. Den försöker förgöra den som åkallat den om den inte tvingas till underkastelse genom fysisk och magisk strid.",al={"vad är en voidwalker","vem ska du slåss mot","återkallad voidwalker"}},b41bc1ad={q="Varför låter Gakin dig själv åkalla voidwalkern?",a="En demon kan inte bindas till en häxmästare genom någon annans försorg. Om Gakin eller en assistent tämjde odjuret skulle det bara lyda dem. För att vinna en voidwalkers kraft och beskydd måste du själv kalla den till cirkeln och bryta dess vilja. Först när du besegrar den på egen hand kan du skapa det mystiska band som krävs för att åkalla och styra den i framtiden.",al={"varför måste jag själv åkalla den","varför kan inte gakin göra det","varför ska jag hantera voidwalkern"}}},fp="11,184,25.450.0,28.374.0,38.275.0,28.258.0,39.183.0,56.150.0,41.170.0,56.215.0"}
P.entries["quest:169"] = {n="Wanted: Gath'Ilzogg",s="Wanted: Gath'Ilzogg är en alliansbelöning som utlysts i Redridge Mountains för att fånga krigsherren bakom Blackrocks invasion av Stonewatch. Magistrate Solomon utlovar en generös belöning till den som vågar storma det erövrade fortet och återvända med befälhavarens avhuggna huvud.",h="Wanted: Gath'Ilzogg är en alliansbelöning som utlysts i Redridge Mountains för att fånga krigsherren bakom...",kw={"blackrock","belöning","gath'ilzogg","lakeshire","magistrate solomon","redridge","stonewatch","efterlysningsaffisch"},ang={["class:Warrior"]="Att ta sig upp till Stonewatch Keeps topp innebär att möta Dark Hordes härdade veteraner och brutala frontbefälhavare.",["faction:Alliance"]="När Gath'Ilzogg fälls undanröjs ett av de mest omedelbara militära hoten mot kungarikets östra gränser, vilket ger Lakeshires invånare ett välbehövligt andrum.",["race:Human"]="För folket i Stormwind var Stonewatch Keep en befästning som vunnits till ett högt pris. Gath'Ilzoggs massaker på oskyldiga när fortet föll gör belöningen till en fråga om bitter hämnd."},sec={{t="Krigsherren över Stonewatch",b="Gath'Ilzogg är den brutale befälhavaren som leder Blackrock-klanens räder genom Redridge Mountains. Under hans ledning stormade och erövrade orcherna Stonewatch Keep och gjorde den tidigare mänskliga bastionen till en befäst utgångspunkt för angrepp mot bosättningarna i området. Från fortets högsta murkrön planerar han fler infall i Lakeshire och hotar att skära av Redridge från resten av kungariket."},{t="En stad pressad till bristningsgränsen",b="Stormwinds kungliga armé har inte lyckats skicka förstärkningar till gränsområdena, så Magistrate Solomon har själv tagit saken i egna händer. Lakeshire saknar helt enkelt soldater nog för att återta Stonewatch Keep med våld. Genom att utlysa en offentlig belöning för Gath'Ilzogg vill Solomon halshugga Blackrocks ledarskap och inleda återtagandet av fortet åt kronan."}},faq={{q="Vem är Gath'Ilzogg?",a="Gath'Ilzogg är en orchisk krigsherre som leder Blackrock-klanens styrkor som ockuperar Stonewatch. Han ledde erövringen av fortet och bär ansvaret för de återkommande dödliga räderna mot Lakeshires mänskliga nybyggare.",al={"gath'ilzoggs bakgrund","vem är gathilzogg","blackrockledare redridge"}},{q="Var hittar man Gath'Ilzogg?",a="Han har befäst sin ställning högst upp i Stonewatch Keep, bland de östra klipporna i Redridge Mountains. Han bevakas noga av sina Blackrock-mästare och livvakter.",al={"gath'ilzoggs plats","var finns gathilzogg","stonewatch-bossens plats"}},{q="Varför utlyser Magistrate Solomon en belöning i stället för att skicka soldater?",a="Lakeshires lokala stadsvakt är hårt ansträngd, och kronan i Stormwind har inte skickat de trupper som behövs för att avlösa regionen. Magistrate Solomon måste förlita sig på legosoldater och självständiga äventyrare för att hantera stora hot.",al={"varför en belöning","var är stormwinds soldater","hjälp från lakeshires vakt"}},{q="Vad händer när Gath'Ilzogg dödas?",a="Magistrate Solomon ser krigsherrens död som det avgörande första steget mot att rensa ut orchernas härjningar och så småningom återta Stonewatch Keep åt kungariket Stormwind, även om Blackrock fortfarande har en stark närvaro i regionen.",al={"har stonewatch återtagits","efter gath'ilzogg"}},{q="Varför invaderade Blackrock-orcherna Stonewatch Keep?",a="Blackrock-klanen använder Stonewatch Keep som en befäst framskjuten bas. Högt uppe i bergen ovanför Redridge ger fortet dem strategisk kontroll över passen och en direkt utgångspunkt för räder mot mänskliga bosättningar.",al={"varför är blackrock i redridge","varför intogs stonewatch"}},{q="Vem får belöningen när Gath'Ilzogg är död?",a="Belöningen måste lämnas direkt till Magistrate Solomon i Lakeshires stadshus, tillsammans med Gath'Ilzoggs huvud som slutgiltigt bevis på hans nederlag.",al={"vem lämnar man in gathilzogg till","lämna in gathilzogg-uppdraget"}}},fx={["1d021e94"]={q="Varför vill Lakeshire att Gath'Ilzogg dödas?",a="Gath'Ilzogg är generalen som leder Blackrock-orchernas invasion av Redridge. Under hans befäl har orcherna slaktat mänskliga försvarare, intagit Stonewatch Keep och genomfört våldsamma räder direkt mot samhället Lakeshire. Stadens ledare vet att Blackrock-klanen fortsätter att planera illdåd mot oskyldiga så länge han samordnar deras styrkor. Att göra slut på honom är avgörande för att bryta belägringen och så småningom återta borgen.",al={"varför döda gath'ilzogg","varför finns belöningen för gath'ilzogg","varför vill solomon att gath'ilzogg ska dö"}},["69773e29"]={q="Vad ska Head of Gath'Ilzogg användas till?",a="Huvudet är ett obestridligt bevis på att Blackrock-krigsherren verkligen har fallit. Magistrate Solomon behöver konkreta bevis på Gath'Ilzoggs död innan han kan betala ut stadens belöning och försäkra Lakeshires panikslagna invånare om att anstiftaren bakom attackerna har oskadliggjorts.",al={"vad ska head of gath'ilzogg användas till","varför samla in gath'ilzoggs huvud","vad gör jag med gath'ilzoggs huvud"}}},fp="19,216,25.329.0,26.330.0,19.193.0,31.150.0,72.197.0,41.209.0,50.179.0,47.95.0"}
P.entries["quest:1690"] = {n="Wastewander Justice",s="Chief Engineer Bilgewhizzle från Gadgetzan Water Company säger att nomaderna Wastewander nu håller nästan alla vattenbrunnar i Tanarisöknen. Du skickas öster om Gadgetzan för att skipa rättvisa bland Wastewander Bandits och Thieves.",h="Chief Engineer Bilgewhizzle från Gadgetzan Water Company säger att nomaderna Wastewander nu håller nästan...",kw={"bandit","bilgewhizzle","gadgetzan","tanaris","tjuv","wastewander","vattenbolag","brunnar"},sec={{t="Rättvisa för brunnarna",b="Ute i Tanarisöknen håller nomaderna Wastewander nu nästan alla vattenbrunnar, och Gadgetzans vattenförsörjning kommer snart att sina utan tillgång till dem. Chief Engineer Bilgewhizzle, som har smak för rättvisa på goblinvis, vill att tio Wastewander Bandits och Thieves ska röjas ur vägen öster om staden, och att du sedan genast rapporterar tillbaka."},{t="Långt ifrån klart",b="Bilgewhizzle är nöjd med hur snabbt arbetet gick. Nomaderna har blivit tillräckligt fåtaliga för att företaget ska kunna börja fundera på att återta sina vattenbrunnar, men det är långt ifrån färdigt med de motbjudande nomaderna och har mer i åtanke."}},faq={{q="Vem är Chief Engineer Bilgewhizzle?",a="En Chief Engineer vid Gadgetzan Water Company i Gadgetzan.",al={"bilgewhizzle","vem skipar rättvisa bland wastewander","gadgetzan water company-ingenjör"}},{q="Varför ger sig Gadgetzan Water Company på Wastewanders?",a="Nomaderna Wastewander håller nästan alla vattenbrunnar i öknen, och utan tillgång till dem kommer Gadgetzans vattenförsörjning att sina.",al={"varför döda wastewander-banditer","orsak till wastewander-rättvisa","varför anfalla nomader i tanaris"}},{q="Var finns Wastewander Bandits och Thieves?",a="Öster om Gadgetzan, ute i öknen.",al={"var hittar man wastewander-banditer","wastewander-banditernas plats","tjuvarnas plats i tanaris"}}},fp="19,230,21.320.0,13.223.1,35.62.0,64.131.0,54.44.0"}
P.entries["quest:1691"] = {n="More Wastewander Justice",s="Chief Engineer Bilgewhizzle i Gadgetzan riktar nu in sig på de farligare Wastewander-nomaderna: deras skurkar, lönnmördare och skuggmagiker, som finns öster och sydost om staden. Ju färre nomader som är kvar, desto lättare blir det att återta vattenbrunnarna.",h="Chief Engineer Bilgewhizzle i Gadgetzan riktar nu in sig på de farligare Wastewander-nomaderna: deras...",kw={"lönnmördare","bilgewhizzle","gadgetzan","skuggmagiker","tanaris","wastewander","vattenföretag"},sec={{t="De starkare leden",b="Enligt Bilgewhizzle har du gjort ett bra jobb hittills, men det går bäst att återta brunnarna när så få nomader som möjligt finns kvar. Nu är målen nomadernas skurkar, lönnmördare och skuggmagiker öster och sydost om Gadgetzan. Bilgewhizzle medger att de är ett otrevligt gäng, men säger att brunnarna med rätta tillhör företaget."},{t="Ta striden till dem",b="Nomaderna är nu så få att företaget kan ta striden till dem. Bilgewhizzle föreslår att du talar med Spigot Operator Luglunket i staden, som betalar en belöning för alla Wastewander-vattenpåsar du fått tag på medan du tog hand om nomaderna."}},faq={{q="Vem ber om det här?",a="Chief Engineer Bilgewhizzle från Gadgetzan Water Company i Gadgetzan.",al={"vem ger mer rättvisa åt wastewander","uppdragsgivare"}},{q="Varför vill Gadgetzan Water Company få bort de här nomaderna?",a="Företaget tänker återta vattenbrunnarna, och det går lättare när så få nomader som möjligt finns kvar.",al={"varför döda wastewander","bilgewhizzles motiv"}},{q="Var finns nomaderna som är måltavlor?",a="Öster och sydost om Gadgetzan, där nomaderna håller till.",al={"var finns wastewander-skurkar","var hittar man skuggmagiker"}},{q="Vad kommer före det här steget?",a="Det följer efter Wastewander Justice.",al={"förutsättning","föregående uppdrag"}}},fp="24,242,18.322.0,24.255.1,18.73.0,63.101.0,39.66.0,28.31.0"}
P.entries["quest:1692"] = {n="Smith Mathiel",s="Smith Mathiel är ett viktigt krigaruppdrag i Darnassus och markerar steget från råmaterial till smidda vapen. Efter att ha hämtat helig elunitmalm från ett skeppsvrak utanför Auberdine lämnar en blivande krigare malmen till mästersmeden Mathiel. Han går med på att smida den välsignade metallen till ett vapen som kan försvara Kaldorei.",h="Smith Mathiel är ett viktigt krigaruppdrag i Darnassus och markerar steget från råmaterial till smidda vapen.",kw={"warrior's terrace","darnassus","elanaria","elunit","mathiel","smed","krigare"},ang={["class:Warrior"]="För unga Kaldorei-krigare är det en övergångsrit att ta med elunit till Mathiel; de byter ut enkla träningssvärd mot specialsmidda vapen välsignade av mångudinnan.",["profession:Blacksmithing"]="Mathiels vördnad för elunit visar hur Kaldorei-smeder väver in heliga välsignelser i sitt smide i stället för att enbart förlita sig på hetta och hammarslag.",["race:NightElf"]="Att bearbeta elunitmalm förenar Night Elf-hantverk med helig hängivenhet till Elune och visar att krigisk styrka och gudomlig tro hör ihop."},sec={{t="En helig leverans",b="Efter att ha hämtat elunitmalm från det hemsökta skeppsvraket utanför Auberdine och säkrat den med hjälp av krigartränaren Elanaria skickas unga Night Elf-krigare över Warrior's Terrace i Darnassus. Elanaria packar omsorgsfullt malmen i ett stadigt skrin och instruerar novisen att söka upp Mathiel, en av huvudstadens främsta smeder, så att han kan smida ett vapen värdigt deras krigarkall."},{t="Elunitens välsignelse",b="Mathiel ser inte smidet som enbart kroppsarbete, utan som ett hängivet hantverk. Elunit är ingen vanlig malm – den bär mångudinnan Elunes heliga välsignelse. När han får skrinet tar Mathiel gärna på sig uppdraget och ser det som en stor ära att forma denna heliga metall till vapen som ska försvara Teldrassils unga grenar."}},faq={{q="Vem är Smith Mathiel?",a="Mathiel är en skicklig Night Elf-smed som arbetar i Warrior's Terrace i Darnassus. Han tillverkar specialvapen och smider på beställning åt Darnassus försvarare.",al={"vem är mathiel","smeden mathiel","var finns mathiel"}},{q="Vad är speciellt med elunitmalm?",a="Elunit är en sällsynt metall som Night Elf vördar eftersom den välsignats av Elune själv. Smeder som Mathiel ser det som en stor ära att arbeta med den och använder dess heliga egenskaper för att smida kraftfulla vapen.",al={"vad är elunit","är elunit magiskt","elunit i berättelsen"}},{q="Vem skickar dig till Mathiel?",a="Elanaria, en framstående krigartränare som håller till i Warrior's Terrace i Darnassus, packar din upphämtade malm och hänvisar dig till Mathiel, tvärs över terrassen.",al={"vem ger uppdraget smith mathiel","uppdragsgivare smith mathiel"}},{q="Är det här uppdraget bara tillgängligt för krigare?",a="Ja. Det här uppdraget ingår i krigarnas klassuppdragskedja på nivå tio och är utformat för att ge unga krigare deras första specialiserade vapen.",al={"bara för krigare","kan andra klasser göra smith mathiel"}},{q="Var i Darnassus hittar man Mathiel?",a="Mathiel arbetar i Warrior's Terrace i Darnassus, strax söderut på andra sidan byggnaden från Elanaria.",al={"mathiels plats","hitta mathiel"}},{q="Vad händer när du lämnar malmen till Mathiel?",a="Mathiel börjar hamra elunitmalmen till rätt form och erbjuder genast nästa uppdrag, där du väljer vilket elunitsmitt vapen som passar din kampstil bäst.",al={"vad kommer efter smith mathiel","nästa uppdrag efter smith mathiel"}}},fx={["4e03f025"]={q="Varför skickar Elanaria dig till Smith Mathiel?",a="Elanaria är din krigartränare i Darnassus, och hennes uppgift är att övervaka din träning och rusta dig för kommande utmaningar. När du hade samlat den heliga elunitmalmen från Darkshore förpackade hon den säkert så att Smith Mathiel, en hantverkare skicklig på heligt metallarbete, kunde smida den till ett passande vapen för en alvkrigare.",al={"elanarias motiv","varför skicka mig till mathiel","varför skickar elanaria mig till mathiel"}}},fp="13,192,17.303.0,23.227.0,21.159.0,34.123.0,25.133.0,41.120.0,40.94.0,50.127.0"}
P.entries["quest:1693"] = {n="Weapons of Elunite",s="Weapons of Elunite är slutpunkten för en tidig övergångsrit för nattalvskrigare i Darnassus. Efter att ha återfunnit råmalm välsignad av Elune tar krigaren materialet till den skicklige smeden Mathiel, som smider det till vapen värdiga en försvarare av Kalimdor.",h="Weapons of Elunite är slutpunkten för en tidig övergångsrit för nattalvskrigare i Darnassus.",kw={"darnassus","elune","elunit","kaldorei","mathiel","teldrassil","krigare","vapensmed"},ang={["class:Warrior"]="Det här uppdraget är en viktig tidig övergångsrit för unga kaldoreikrigare och belönar deras hängivenhet med pålitliga vapen välsignade av Elune.",["profession:Blacksmithing"]="Smeden Mathiels hantverk visar den fina balansen mellan konventionellt metallarbete och hanteringen av gudomliga material som elunit.",["race:NightElf"]="Smidet av elunit visar hur nattalvernas samhälle väver in vördnaden för Mångudinnan direkt i krigets och försvarets praktiska hantverk."},sec={{t="En helig smedja",b="Nattalvskrigare har en helig plikt att försvara Teldrassil och kaldoreifolket. I stället för att enbart förlita sig på vanligt stål får de som visar löfte i uppdrag att samla elunit, ett mineral genomsyrat av Mångudinnans nåd. För att forma sådana vapen krävs en hantverkare som förstår både metallarbete och den vördnad Elunes gåvor förtjänar."},{t="Mathiels hantverk",b="Smeden Mathiel, som är verksam i huvudstaden Darnassus, är mycket stolt över att forma den välsignade malmen till krigsvapen. För Mathiel är arbetet med elunit inte bara rutinmässig metallbearbetning, utan en ära. När han får malmen tillverkar han ett urval redskap anpassade efter krigarens stil och belönar deras tjänst med vapen välsignade av deras gudinna."}},faq={{q="Vad är syftet med det här uppdraget?",a="Det här uppdraget markerar slutet på det tidiga krigarprovet i Darnassus. När krigaren har säkrat sällsynt elunitmalm lämnar hen den till smeden Mathiel, som tillverkar pålitliga vapen genomsyrade av Elunes kraft för att hjälpa till på färden genom Kalimdor.",al={"uppdraget weapons of elunite","varför göra uppdraget","krigare nivå 10 darnassus"}},{q="Vem är Mathiel?",a="Mathiel är en skicklig nattalvssmed som tillverkar rustningar och vapen och bor i Darnassus. Han har den specialkunskap som krävs för att smida elunitmalm till välbalanserade vapen åt stadens växande skara försvarare.",al={"smeden mathiel","vem är mathiel","smed i darnassus"}},{q="Vad är elunit?",a="Elunit är ett sällsynt mineral som är heligt för nattalverna. De tror att det är genomsyrat av Mångudinnan Elunes sken och välvilja. På grund av dess gudomliga natur betraktar hantverkare det som en högtidlig ära att forma det till vapen.",al={"vad är elunitmalm","elunits historia"}},{q="Vem kan ta sig an det här uppdraget?",a="Det här uppdraget är enbart avsett för krigare i Alliansen som tränar kring Darnassus och har slutfört de inledande uppgifterna att hitta och samla elunit åt smeden Mathiel.",al={"vem får weapons of elunite","är det bara för krigare"}},{q="Var utspelar sig det här uppdraget?",a="Uppdraget lämnas direkt till smeden Mathiel i nattalvernas huvudstad Darnassus, högt uppe bland grenarna på världsträdet Teldrassil.",al={"plats för weapons of elunite","var finns mathiel"}},{q="Varför tackar Mathiel äventyraren?",a="Mathiel betraktar arbetet med elunit som både en helig ära och ett personligt nöje. Att forma malm med band till Elune är ett privilegium som få smeder får uppleva, så krigarens leverans är också en gåva till hantverkaren.",al={"varför är mathiel hedrad","mathiels dialog"}}},fx={cb47846f={q="Varför ber Mathiel dig göra det här i stället för en vakt?",a="Det här uppdraget är en övergångsrit för en lovande ung krigare, inte en officiell samhällsuppgift. Vaktposter och tempelvakter har svurit att försvara Darnassus och Teldrassil mot aktiva hot, så de har ingen tid att samla sällsynta smidesmaterial till personliga vapen. Genom att själv samla malmen visar du ditt engagemang och din disciplin och förtjänar ett vapen smitt särskilt för din stridsväg.",al={"varför skicka mig","varför ska jag hjälpa mathiel","varför krigare"}}},fp="18,198,14.262.0,15.261.0,34.186.0,15.135.0,16.156.0,29.153.0,33.104.0,38.188.0"}
P.entries["quest:1698"] = {n="Yorus Barleybrew",s="På Lakeshire Inn väntar Yorus Barleybrew på allianskrigare som är djärva nog att anta hans utmaning. Tränare i alliansens huvudstäder skickar erfarna kämpar från Stormwind mot Redridge-gränslandet för att möta den excentriske dvärgen och pröva sin vapenfärdighet.",h="På Lakeshire Inn väntar Yorus Barleybrew på allianskrigare som är djärva nog att anta hans utmaning.",kw={"kelv sternhammer","lakeshire","lakeshire inn","redridge","rethban","stormwind","krigare","wu shen","yorus barleybrew"},ang={["class:Warrior"]="Som allianskrigare står du inför en övergångsrit från grundläggande övningar till farliga prövningar vid Redridge-gränsen.",["faction:Alliance"]="Som rekryt i alliansen kan du skickas till Lakeshire, en utsatt bosättning som hemsöks av gnoller och Blackrock-orcher."},sec={{t="En utmaning för de starka",b="I alliansens huvudstäder håller krigartränare utkik efter kämpar som vuxit ur sina första övningar. När en lärling visar sin duglighet runt sin tjugonde säsong berättar tränare som Kelv Sternhammer, Wu Shen och Darnath Bladesinger om Yorus Barleybrew. Dvärgen erbjuder ingen vanlig militär order. I stället har han utlyst ett öppet vad och en vapenprövning för alla allianskrigare som är djärva nog att anta utmaningen."},{t="Väntar i Lakeshire",b="Yorus Barleybrew väntar på värdshuset i Lakeshire, vid frontlinjen i Redridges kamp mot framryckande gnoller och Blackrock-orcher. De som hittar honom möter en skrytsam dvärg med en rejäl drink i handen, redo att bedöma varje utmanare som påstår sig ha den rätta kampandan. För krigare som vill bevisa sig bortom huvudstadens trygga kullerstensgator leder hans prövning vidare till gränslandets hårdare strider."}},faq={{q="Vem är Yorus Barleybrew?",a="Yorus Barleybrew är en dvärg från den berömda bryggarsläkten Barleybrew, som har utfärdat en öppen kamputmaning till allianskrigare. Han väntar på Lakeshire Inn, där han prövar kämpar som tror sig vara redo för den brutala gränsbygden i Redridge Mountains.",al={"yorus barleybrew","vem är barleybrew","dvärg på lakeshire inn"}},{q="Varför skickar tränarna krigare till Redridge?",a="När en krigare har blivit tillräckligt skicklig i Stormwind skickar lokala vapendragare dem mot praktiska strider med höga insatser. Yorus Barleybrews prövning tar lärlingarna utanför stadsmurarna, där de får bevisa sin uthållighet mot verkliga hot i vildmarken.",al={"varför lakeshire","krigartränaruppdrag redridge","varför gå till yorus"}},{q="Var hittar jag Yorus Barleybrew?",a="Yorus Barleybrew väntar inne på Lakeshire Inn, i staden Lakeshire i Redridge Mountains, strax öster om Elwynn Forest.",al={"yorus barleybrews plats","var är yorus","hitta barleybrew"}},{q="Vad händer efter att jag talat med Yorus?",a="När du talar med Yorus inleder du hans kampprövning: Rethban Gauntlet, en farlig utmaning mot de våldsamma bestarna och gnollerna i de omgivande kullarna.",al={"efter yorus","barleybrews prövning","nästa uppdrag"}},{q="Vem ger uppdraget att hitta honom?",a="Krigartränare i alliansens huvudstäder, däribland Kelv Sternhammer, Wu Shen och Darnath Bladesinger, skickar krigare för att hitta Yorus när de har visat grundläggande färdighet.",al={"vem ger uppdraget","uppdragsgivare","tränare för yorus"}},{q="Är prövningen öppen för andra klasser än krigare?",a="Nej. Yorus Barleybrew erbjuder utmaningen enbart till krigare, närstridskämpar som förlitar sig på fysisk uthållighet och vapen.",al={"kan paladiner göra detta","är detta bara för krigare","klassbegränsningar"}}},fx={f43b4090={q="Varför skickar tränarna dig till Yorus Barleybrew?",a="Dina tränare inser att du har vuxit ifrån grundövningarna och behöver prövningar som testar din styrka ute i fält. Yorus Barleybrew har utfärdat en öppen utmaning särskilt till dugliga krigare i Alliansen och lovar en storslagen belöning till den som är stark nog att klara den. I stället för att hålla dig skyddad i huvudstadens träningssalar skickar dina mentorer dig till Redridge för att bevisa din skicklighet i ett verkligt prov.",al={"varför skicka mig till yorus","varför ska jag träffa yorus barleybrew","varför pröva en krigare i redridge"}}},fp="16,259,20.418.0,20.414.0,24.257.0,46.254.0,34.128.0,39.147.0,33.172.0,50.120.0"}
P.entries["quest:1699"] = {n="The Rethban Gauntlet",s="Rethban Gauntlet är ett egensinnigt uthållighetsprov, skapat av den dvärglike bryggaren Yorus Barleybrew i Lakeshire. Utmanarna måste ta en rejäl klunk av familjens starka Barleybrew Scalder och spurta norrut till de koboldhärjade Rethban Caverns och tillbaka innan en timme har gått.",h="Rethban Gauntlet är ett egensinnigt uthållighetsprov, skapat av den dvärglike bryggaren Yorus Barleybrew i...",kw={"barleybrew scalder","kobolder","lakeshire","redridge","rethban caverns","rethban gauntlet","tidtagning","yorus barleybrew"},ang={["faction:Alliance"]="Medan Lakeshire kämpar mot hotet från koboldernas intrång hjälper den som antar utmaningen till att glesa ut fiendepatrullerna som stryker kring de norra grottorna.",["race:Dwarf"]="Dvärgar kommer att känna sig som hemma med Yorus bullriga idé om nöje: att blanda stark familjebrygd med farliga sprinter i bergen."},sec={{t="En dvärgautmaning",b="I staden Lakeshire, där dystert tal om koboldräder och försvunna stadsvakter vanligtvis dominerar på värdshuset, bjuder dvärgen Yorus Barleybrew på ett högst dvärgiskt nöje. Hans egen utmaning, Rethban Gauntlet, prövar en äventyriares mod, snabbhet och lever på samma gång. Deltagarna måste svepa en skvätt av familjens särskilda brygd, Barleybrew Scalder, precis innan de ger sig av till fots mot de norra bergssluttningarna."},{t="Löpning i vildmarken",b="Provet är betydligt farligare än ett enkelt fyllesprång. Mellan Lakeshire och målet ligger Redridge, fullt av aggressiva Redridge-kobolder. För att klara utmaningen måste löparen slåss mot eller smita förbi flockarna, nå den första korsningen inne i de mörka gångarna i Rethban Caverns och skynda tillbaka till Yorus inom en timme, samtidigt som den starka dvärgölen gör löparen överväldigad och ostadig."}},faq={{q="Vem utlyser Rethban Gauntlet?",a="Yorus Barleybrew, en dvärgisk bryggare som vistas i Lakeshire, utmanar resande på loppet för att pröva deras uthållighet och sin brygd.",al={"vem ger rethban gauntlet","yorus barleybrew uppdrag","vem startar utmaningen"}},{q="Vad gör utmaningen särskilt svår?",a="Förutom att ta sig förbi koboldflockarna i Redridges bergssluttningar inom en strikt tidsgräns på en timme måste löparna först svälja Barleybrew Scalder, en stark dryck som gör dem kraftigt berusade och får dem att kämpa för att hålla balansen.",al={"varför är rethban gauntlet svårt","barleybrew scalder effekt"}},{q="Var ligger Rethban Caverns?",a="Grottorna ligger i de norra bergssluttningarna i Redridge Mountains, nordväst om Lakeshire. Stigen går norrut förbi traktens gårdar mot klipporna där koboldflockarna håller till.",al={"rethban caverns plats","var ligger rethban","hur tar man sig till rethban caverns"}},{q="Hur långt in i grottorna måste löparen ta sig?",a="Utmanarna behöver inte röja hela grottsystemet. De behöver bara nå den första korsningen inne i grottorna innan de vänder om och rusar tillbaka till Lakeshire.",al={"rethban caverns mål","hur långt in i rethban"}},{q="Vilka bor i kullarna och grottorna längs rutten?",a="Området runt rutten och inne i grottorna är översvämmat av fientliga Redridge-kobolder, så smygande eller snabb strid är nödvändigt för att överleva färden.",al={"vilka fiender finns i rethban","vad finns i rethban caverns"}},{q="Vart leder utmaningen härnäst?",a="Om du överlever utmaningen bevisar du din uthållighet för Yorus Barleybrew och får möjlighet att ta dig an fler uppgifter i området, som att söka upp sköldsmeden Furen Longbeard i Stormwind.",al={"uppföljning till rethban gauntlet","vilket uppdrag kommer efter rethban gauntlet"}}},fx={["26a182c4"]={q="Varför vill Yorus Barleybrew att det här ska göras?",a="Yorus Barleybrew försöker inte lösa någon kris eller rädda Lakeshire med den här prövningen. I stället har han utformat Rethban Gauntlet som ett högljutt prov på mod, uthållighet och alkoholtålighet. Genom att skicka djärva äventyrare djupt in i gnollernas område, rejält berusade av hans familjs starka Barleybrew Scalder, söker Yorus ren underhållning och spänningen i att se någon våga övervinna både Redridges vilda gnoller och brygdens bedövande kraft.",al={"varför genomföra utmaningen","yorus barleybrews motiv","varför utmanar yorus dig"}}},fp="20,182,14.302.0,22.312.0,32.136.0,49.187.0,38.173.0,40.100.0,51.132.0,36.180.0"}
P.entries["quest:170"] = {n="A New Threat",s="A New Threat är ett tidigt stridsuppdrag från Balir Frosthammer i Coldridge Valley. Dvärgarnas bergsjägare har överrumplats av en plötslig våg troggs som strömmar ut över Dun Morogh och hotar bosättningar och läger i trakten.",h="A New Threat är ett tidigt stridsuppdrag från Balir Frosthammer i Coldridge Valley.",kw={"a new threat","anvilmar","balir frosthammer","burly rockjaw","coldridge valley","dun morogh","rockjaw trogg"},ang={["faction:Alliance"]="När det underjordiska hotet i Coldridge Valley hålls i schack kan Ironforges träningsmarker fortsätta användas, och den södra bergsporten förblir säker för Alliansens rekryter.",["race:Dwarf"]="För unga Bronzebeard-dvärgar som ger sig ut från Anvilmar är det en personlig plikt att slå tillbaka troggarnas intrång och skydda Dun Moroghs heliga marker och tunnlar."},sec={{t="Inbrott i Coldridge Valley",b="Coldridge Valley sågs länge som en skyddad tillflykt för unga dvärgkrigare och bergsjägare som tränade i Dun Morogh. Freden krossades när underjordiska Rockjaw-troggs började gräva sig upp till ytan i förbluffande antal. Rapporter nådde snart Anvilmar om att troggs svärmade över den frusna sjön och de omgivande bergssluttningarna, störde de dagliga patrullerna och skar av viktiga försörjningsvägar genom dalpasset."},{t="Ett överrumplat läger",b="Krisen nådde sin kulmen när varelserna samordnat anföll ett dvärgläger i väster och tvingade bergsjägarna att retirera och överge sina poster. Balir Frosthammer har ont om folk och kan inte avvara hela stridsregementen från Ironforge. Därför har han vänt sig till nyrekryterade äventyrare, som ska ta sig igenom Rockjaw-ledet och säkra kullarna innan bestarna når ända fram till Anvilmar."}},faq={{q="Vem är Balir Frosthammer?",a="Balir Frosthammer är en erfaren dvärgisk bergsjägare som är stationerad utanför Anvilmar i Coldridge Valley. Han organiserar försvaret mot vilddjuren och de invaderande troggs som hotar de lokala rekryterna.",al={"balir frosthammer","vem ger uppdraget a new threat","frosthammer anvilmar"}},{q="Varför finns det plötsligt troggs i Coldridge Valley?",a="Rockjaw-troggs har börjat gräva sig upp ur djupa underjordiska sprickor runtom i Dun Morogh. Coldridge Valley är en av de första bebodda dalarna som drabbats av plötsliga, våldsamma utbrott när varelserna stormar lägren vid ytan.",al={"varifrån kom troggs","varför anfaller troggs","trogginvasion"}},{q="Vilket läger blev överrumplat av troggs?",a="Ett dvärgiskt bergsjägarläger i västra Coldridge Valley överfölls nyligen och intogs av troggs. De överlevande tvingades retirera mot Anvilmar.",al={"översvämmat läger","lägret i väster","var anföll troggs"}},{q="Vilken sorts troggs hotar dalen?",a="Angriparna tillhör Rockjaw-stammen. De består främst av vanliga Rockjaw Troggs och de större, kraftigare Burly Rockjaw Troggs, som leder anfallet runt den frusna sjön och bergssluttningarna.",al={"rockjaw-troggs","vilka troggs","burly rockjaw troggs"}},{q="Känner King Magni till problemet med troggs?",a="De lokala vakterna hoppas att King Magni Bronzebeard och Ironforge-senaten förbereder en större insats. Gränsutposter som Coldridge Valley tvingas dock just nu hantera lokala anfall på egen hand.",al={"vet magni om det","ironforges svar på troggs","ironforge-senaten och troggs"}},{q="Vad händer när dessa troggs har rensats ut?",a="När troggs blir färre stabiliseras området närmast Anvilmar. Balir och andra dväriska officerare fortsätter ändå att organisera motanfall för att återta det förlorade lägret i väster och driva skadedjuren tillbaka under jord.",al={"uppföljningsuppdrag","efter a new threat","trogg-uppdragskedjan i coldridge"}}},fx={["54af52f4"]={q="Varför vill Balir Frosthammer att troggarna ska gallras ut?",a="Coldridge Valley är under omedelbar belägring. Troggarna har inte bara tagit över de södra kullarna och den frusna sjön, utan stormade också våldsamt det dvärgiska lägret i väster för bara några nätter sedan. Balir måste minska deras antal innan de vilda varelserna tränger djupare in i dalen och helt övermannar Anvilmar.",al={"varför döda troggar","balir frosthammers motiv","varför behöver balir döda troggar"}},["3d273126"]={q="Varför behöver Balir Frosthammer din hjälp i stället för de lokala vakterna?",a="Försvararna vid Anvilmar har farligt få man. Den nyliga överraskningsattacken mot deras västra läger skingrade styrkorna och lämnade garnisonen hårt ansträngd när den försöker hålla bosättningens yttergräns. De har inga soldater över att avvara för en offensiv motattack, så Balir måste rekrytera varje äventyrslysten person som dyker upp.",al={"varför jag, balir","varför inte använda vakterna","varför behöver balir mig"}}},fp="12,212,26.337.0,14.326.0,25.180.0,44.188.0,36.130.0,47.163.0,41.181.0,40.198.0"}
P.entries["quest:1700"] = {n="Grimand Elmore",s="Efter att ha skapat en specialanpassad rustning skickar dvärgsmeden Furen Longbeard en kopia av sina rön genom Dwarven District till Grimand Elmore. Det korta ärendet förmedlar tekniska anteckningar mellan två envisa vapensmeder som arbetar i Stormwind City.",h="Efter att ha skapat en specialanpassad rustning skickar dvärgsmeden Furen Longbeard en kopia av sina rön...",kw={"smide","dwarven district","fire hardened mail","furen longbeard","furen's notes","grimand elmore","stormwind"},ang={["class:Warrior"]="Den här leveransen utgör en brygga mellan att rusta dig själv och att söka upp närstridsvapen som smitts med samma elementära experiment.",["profession:Blacksmithing"]="Utbytet mellan Furen och Grimand visar den hårda yrkesrivalitet och det delande av yrkeshemligheter som är vanligt bland mästersmeder.",["race:Dwarf"]="Det hetsiga, stolta käbblet mellan Grimand och Furen speglar de starkt tävlingsinriktade men samtidigt samarbetsvilliga traditionerna inom Khaz Modans smideskultur."},sec={{t="Ett meddelande genom stadsdelen",b="Efter att ha smitt den specialanpassade Fire Hardened Mail dokumenterar Furen Longbeard de intrikata värmebehandlingstekniker och elementära principer han upptäckte under arbetet. I stället för att behålla kunskapen för sig själv skriver han ner anteckningarna på pergament och ber en äventyrare leverera dem direkt till Grimand Elmore, en erfaren hantverkare som arbetar i en närbelägen vapenbutik."},{t="Yrkesstolthet och nyfikenhet",b="Grimand Elmore reagerar först med sårad stolthet när han får manuskriptet. Han hävdar bestämt att han lärt Furen allt den yngre dvärgen kan och blir irriterad över tanken på att hans tidigare elev skulle kunna lära honom något. Trots sin synliga ilska kan hantverkaren inte låta bli att läsa texten. Snart hittar han en spännande idé bland anteckningarna som han gärna vill pröva själv."}},faq={{q="Vem är Grimand Elmore?",a="Grimand Elmore är en respekterad vapensmed med en butik i Dwarven District i Stormwind City. Han är känd för sin enorma yrkesstolthet och för att tidigare ha lärt ut hantverket till andra lokala smeder, däribland Furen Longbeard.",al={"grimand elmore","vem är grimand","elmore stormwind"}},{q="Varför skickar Furen anteckningar till Grimand?",a="När Furen tillverkade Fire Hardened Mail upptäckte han nya tekniker och skrev ner sina metoder. Han ville dela sina genombrott med Grimand, trots att han visste att Grimands häftiga humör och envisa ego skulle få honom att reagera defensivt på att bli lärd något nytt.",al={"varför skicka anteckningar","furens anteckningar","furen till grimand"}},{q="Var hittar man Grimand Elmore?",a="Han arbetar i vapenbutiken i Dwarven District i Stormwind City, bara en kort promenad från Furen Longbeards smedja.",al={"var är grimand","grimands plats","grimand elmores butik"}},{q="Hur reagerar Grimand på anteckningarna?",a="Grimand blir först rasande och förklarar att han lärt Furen allt dvärgen kan. Men som mästersmed tar nyfikenheten snabbt över när han upptäcker en spännande teknik i texten som han vill experimentera med.",al={"grimands reaktion","är grimand arg"}},{q="Vad händer efter att Grimand har läst anteckningarna?",a="Grimand blir nyfiken på Furens arbete med att anlöpa metall över eld och bestämmer sig för att genomföra ett eget ambitiöst smidesprojekt. Det leder till fler uppgifter där sällsynta komponenter med elementär hetta ska samlas in.",al={"vad händer efter grimand","efter uppdraget grimand elmore"}},{q="Varför varnar Furen för att du ska ducka när han lämnar över anteckningarna?",a="Furen känner till Grimands häftiga humör och överdrivna stolthet av egen erfarenhet. Han räknar med att Grimand kan få ett raseriutbrott, eller kasta något, bara för att antydan om att en lärling skulle kunna lära mästaren en ny teknik.",al={"varför ducka","furens varning att ducka"}}},fx={["7d98159c"]={q="Varför skickar Furen dig i stället för att själv gå till Grimand?",a="Furen känner Grimand Elmores lättretliga humör alltför väl. Grimand hävdar att han lärt Furen allt han kan, och om hans tidigare elev dök upp i verkstaden för att föreläsa om nya smidestekniker skulle det utlösa ett häftigt gräl. Genom att låta dig överlämna anteckningarna slipper Furen en direkt konfrontation och låter sin envisa mentor svälja stoltheten i enrum.",al={"varför skicka mig till grimand elmore","varför lämnar inte furen över anteckningarna själv","varför behöver furen mig"}}},fp="14,256,29.392.0,32.407.0,22.240.0,37.270.0,34.149.0,36.233.0,43.187.1,56.215.0"}
P.entries["quest:1701"] = {n="Fire Hardened Mail",s="I Stormwind har Furen Longbeard en ny rustningsdesign för en krigare i Alliansen. Dvärgpansarsmeden erbjuder sig att smida Fire Hardened Mail om krigaren hämtar sällsynta material från båda kontinenterna.",h="I Stormwind har Furen Longbeard en ny rustningsdesign för en krigare i Alliansen.",kw={"charred horn","fire hardened mail","furen longbeard","galvanized horn","flogiston","razorfen kraul","roogug","scorched spider fang","stonetalon","wetlands"},ang={["class:Warrior"]="Som krigare visar du ditt värde genom att trotsa Kalimdors vildmarker och djupa grottor för att förtjäna en rustningsdel av mästerklass.",["faction:Alliance"]="Som soldat i Alliansen ger du dig djupt in i The Barrens och Stonetalon Mountains, där Horde gör anspråk på landet.",["race:Dwarf"]="Som dvärg vet du att sann rustning kräver oböjliga material hämtade direkt från naturens hårdaste rovdjur."},sec={{t="En mästerpansarsmeds ambition",b="Furen Longbeard har smitt en enastående bucklare åt den blivande krigaren och föreslår nu ett större verk: ringbrynja som står emot hårda slag. Hans hantverk kräver mer än järn eller stål. Han behöver sällsynta material som präglats av elementär hetta och naturlig motståndskraft. Furen kan inte lämna sitt städ i Stormwind, så krigaren som vill ha rustningen måste samla in dessa farliga ingredienser."},{t="En expedition över kontinenterna",b="Furen skickar krigaren till avlägsna vildmarker och farliga djup efter de delar han behöver. Receptet kräver huggtänder från giftiga spindlar i Wetlands fuktiga skrevor, samt förkolnade och galvaniserade horn från våldsamma chimaeror i Stonetalon Mountains. För att binda och härda dessa bestdelar till ringbrynja behöver Furen också flyktig flogiston från Roogug, en geomant djupt inne i Razorfen Krauls taggiga labyrint i The Barrens."}},faq={{q="Vem är Furen Longbeard?",a="Furen Longbeard är en erfaren dvärgpansarsmed och sköldmakare i Dwarven District i Stormwind City. Han tillverkar skräddarsydda skydd åt lovande krigare som är villiga att hjälpa honom.",al={"furen","vem ger fire hardened mail","vem är smeden"}},{q="Varför behöver Furen så märkliga ingredienser?",a="Furen behöver ovanliga ingredienser för att härda metallen utöver vanliga dvärgmetoder. Hans hemliga hantverk använder organiska material som behandlats med naturligt gift, bergsvindar och andedräkter, tillsammans med flyktig flogiston.",al={"varför spindelhuggtänder","varför horn","vad är flogiston"}},{q="Varifrån kommer chimaerhornen?",a="De förkolnade och galvaniserade hornen kommer från chimaeror i Stonetalon Mountains i Kalimdor. De yngre bestarna och den väldiga Chimaera Matriarch som leder dem bär hornen.",al={"var hittar man chimaerhorn","plats för charred horn","galvanized horn"}},{q="Var hittar man flogiston?",a="Roogug, en quilboar-geomant, bär på en Vial of Phlogiston i sitt näste i Razorfen Kraul, nära den södra spetsen av The Barrens i Kalimdor.",al={"vial of phlogiston","vem släpper flogiston","roogug"}},{q="Vilka spindlar bär på förkolnade spindelhuggtänder?",a="Leech Stalkers och Cave Stalkers bär på de förkolnade spindelhuggtänderna. Dessa jättelika spindeldjur lurar i träskmarkerna och grottorna i Wetlands i Eastern Kingdoms.",al={"förkolnade spindelhuggtänder","var finns spindlarna","spindlar i wetlands"}},{q="Vad händer när alla material har samlats in?",a="När Furen får huggtänderna, hornen och flogistonen börjar han smida en bröstplåt särskilt åt krigaren. Han tillverkar den i sin smedja som en del av Furen's Armor.",al={"what comes next","fortsättning på fire hardened mail","belöning"}}},fx={cecd81db={q="Varför vill Furen Longbeard att det här blir gjort?",a="Furen är mycket stolt över sitt smide. Efter att redan ha tillverkat din sköld vill han bevisa sin skicklighet genom att smida en ovanligt tålig ringbrynjerustning. Han känner till de hemliga tekniker som krävs för att bearbeta dessa exotiska, eldhärdade reagenser. Han erbjuder sig att smida rustningen åt dig bara för att få se en sådan enastående rustning bli till, förutsatt att du vågar möta farorna när du samlar ihop delarna.",al={"furen longbeards drivkraft","varför tillverka eldhärdad ringbrynja","varför vill furen ha material"}}},fp="18,193,27.377.0,30.431.0,23.168.0,48.225.0,38.178.0,30.139.0,42.154.0,50.160.0"}
P.entries["quest:1702"] = {n="The Shieldsmith",s="I Stormwind skickar Yorus Barleybrew tillbaka krigare efter en prövande färd i Redridge Mountains. Han ger dem ett fat Barleybrew Scalder att ta till Furen Longbeard, som ska smida en rejäl sköld.",h="I Stormwind skickar Yorus Barleybrew tillbaka krigare efter en prövande färd i Redridge Mountains.",kw={"barleybrew scalder","fat","dwarven district","furen longbeard","rethban","sköldmakare","stormwind","krigare","yorus barleybrew"},ang={["class:Warrior"]="Som krigare tar du med dig Redridge Mountains okuvliga anda till Stormwind och visar att du förtjänar att bära en sköld smidd av en legendarisk dvärgisk rustningssmed.",["profession:Blacksmithing"]="Som smed träffar du Furen Longbeard, vars specialiserade arbete med skyddande rustningar är berömt i hela Alliansen.",["race:Dwarf"]="Som dvärg vet du att byta ett fat fint Barleybrew-öl mot smitt järn i Stormwinds Dwarven District är en välbekant affär."},sec={{t="Ett löfte infriat",b="När du har bevisat ditt mod mot gnollerna och farorna i Rethban Gauntlet håller Yorus Barleybrew sin del av avtalet. Den utlovade belöningen kan inte smidas i Lakeshire, så han skickar lovande kämpar tillbaka till Stormwind City. Där väntar en dvärgisk rustningssmed som vill återgälda en personlig skuld."},{t="Barleybrews finaste",b="Yorus ger dig ett tungt fat Barleybrew Scalder i stället för en kreditväxel. Ta det till Furen Longbeard i Stormwinds Dwarven District, där sot och hammarslag fyller luften. Den erfarne smeden känner igen namnet bakom leveransen och lånar ut sitt hantverk till en krigare som söker en rejäl sköld."}},faq={{q="Vem är Furen Longbeard?",a="Furen Longbeard är en mästersmed bland dvärgarna och sköldmakare i Stormwind Citys Dwarven District. Alliansens krigare känner till hans skicklighet, och han tillverkar särskild skyddsutrustning åt stridsveteraner som vinner hans respekt.",al={"furen longbeard","vem är furen","vem är sköldmakaren"}},{q="Varför skickar Yorus dig till Stormwind?",a="Yorus Barleybrew skickar dig till Stormwind eftersom han lovade en stridssköld men saknar de specialiserade smideskunskaper som krävs för att smida en själv. Hans vän Furen Longbeard står i stor skuld till honom.",al={"varför åka till stormwind","varför stormwind","yorus belöning plats"}},{q="Vad är Barleybrew Scalder?",a="Barleybrew Scalder är en exceptionellt stark dvärgisk dryck som tillverkas av familjen Barleybrew. Yorus skickar ett färskt fat till Furen Longbeard för att släcka smedens törst och få deras uppgörelse att gå smidigare.",al={"cask of scalder","barleybrew scalder","vad är scalder"}},{q="Var hittar man Furen Longbeard?",a="Furen Longbeard sköter sin smedja mitt i Stormwind Citys Dwarven District, bland sotet, städen och dvärgarnas verkstäder.",al={"furen plats","var finns furen longbeard","hitta furen"}},{q="Vad händer när du har gett Furen fatet?",a="Fatet bekräftar att Yorus har skickat dig. Furen erkänner sin skuld och erbjuder genast att tillverka skyddande rustning för hårda strider, vilket inleder vägen mot eldhärdad utrustning.",al={"what comes next","furens uppföljningsuppdrag"}},{q="Varför är detta ärende viktigt för Alliansens krigare?",a="Leveransen för en Allianskrigare till en av rikets skickligaste rustningssmeder. Den öppnar vägen till skräddarsydd stridsutrustning och vidare undervisning i försvarskonst.",al={"krigaruppdragets betydelse","varför krigare bryr sig"}}},fx={["23250e3d"]={q="Varför skickar Yorus Barleybrew dig med leveransen i stället för en kurir?",a="Yorus håller sitt löfte efter att du trotsat Rethban Gauntlet. I stället för att sköta en vanlig leverans skickar han dig för att hämta belöningen du blivit lovad personligen. Skölden han lovat finns hos hans vän Furen Longbeard i Stormwind. Genom att låta dig bära en kagge av hans berömda Scalder kan han hålla sitt ord och själv be om en gammal gentjänst å dina vägnar.",al={"varför skicka mig till sköldsmeden","varför skickar yorus mig","varför jag, yorus barleybrew"}}},fp="15,205,14.296.0,19.301.0,23.225.0,37.197.0,27.206.0,35.141.0,41.187.0,51.179.0"}
P.entries["quest:1703"] = {n="Mathiel",s="Det här uppdraget skickar en äventyrare med Furen Longbeards hantverksanteckningar över haven till Darnassus. Mottagaren är Mathiel, en skicklig smed på Warrior's Terrace som ivrigt vill studera dvärgarnas nya metoder för att smida ringbrynjor. Det är ett viktigt utbyte av militär metallurgi mellan Ironforge och kaldorei.",h="Det här uppdraget skickar en äventyrare med Furen Longbeards hantverksanteckningar över haven till Darnassus.",kw={"smed","darnassus","eldhärdad ringbrynja","furen longbeard","furen's notes","mathiel","teldrassil","warrior's terrace"},ang={["class:Warrior"]="När du bär de här anteckningarna går din resa från Eastern Kingdoms flammande smedjor till Darnassus prövningsplatser och utökar din personliga vapensamling.",["profession:Blacksmithing"]="Leveransen visar hur viktigt samarbetet mellan mästersmeder är, när ritningar och tekniker för värmebehandling förs mellan avlägsna städ.",["race:Dwarf"]="När Furen delar sina framsteg inom metallarbete med nattalverna visar det hur stolta dvärgarna är över sin oöverträffade skicklighet vid smedjan.",["race:NightElf"]="Mathiel visar hur gärna kaldorei studerar dvärgarnas underjordiska smide och förenar det med nattalvernas traditionella rustningssmide."},sec={{t="En kurir över havet",b="Efter att ha bemästrat den svåra konsten att smida eldhärdad rustning beslutar den erfarne dvärgsmeden Furen Longbeard att dela sina framsteg med andra hantverkare i Alliansen. I stället för att hålla sin nya metallurgiska kunskap för sig själv skriver Furen ner detaljerade tekniska ritningar och skickar dig, en beprövad äventyrare, över kontinenterna för att hitta Mathiel, en skicklig smed högt uppe i Teldrassil."},{t="Kaldoreistål och dvärkhantverk",b="Mathiel arbetar vid sin smedja på den trädkantade Warrior's Terrace i Darnassus och tillverkar utrustning åt väktarna och kämparna som försvarar nattalvernas huvudstad. När han tar emot Furen's Notes knyts olika hantverkstraditioner samman: Khaz Modan-dvärgarnas robusta, underjordiska smältning och kaldoreiernas eleganta rustningssmide, präglat av naturen."}},faq={{q="Vem är Mathiel?",a="Mathiel är en nattalvssmed som tjänstgör på Warrior's Terrace i Darnassus. Han tillverkar utrustning åt huvudstadens försvarare och håller kontakt med andra mästersmeder i Alliansen.",al={"mathiel-lore","vem är mathiel i darnassus"}},{q="Varför skickar Furen dig till Darnassus?",a="Furen Longbeard vill att hans forskning om att smida eldhärdad rustning ska komma andra hantverkare i Alliansen till nytta. Eftersom Mathiel är en betrodd kollega som kan förstå och använda avancerade metallurgiska tekniker, anförtror Furen dig uppgiften att överlämna sina personliga hantverksanteckningar till honom.",al={"varför skicka anteckningar till mathiel","varför furen's notes"}},{q="Var hittar jag Mathiel i Darnassus?",a="Mathiel finns vid smedjan på Warrior's Terrace, i den östra delen av Darnassus nära huvudporten, där krigare och väktare tränar.",al={"mathiels plats","var finns mathiel"}},{q="Vad händer när jag ger Mathiel anteckningarna?",a="Mathiel blir imponerad av Furen's upptäckter och bestämmer sig för att utveckla dvärgarnas tekniker. Han skickar ut krigaren på fler prövningar i Kalimdors vildmark för att samla ovanliga material, som solbrända skal.",al={"nästa uppdrag efter mathiel","uppföljning till mathiel"}},{q="Vad innehåller anteckningarna?",a="Anteckningarna innehåller detaljerade metallurgiska observationer och smidestekniker som Furen lärde sig när han experimenterade med brända spindelgiftständer, chimärhorn och flogiston för att tillverka förstärkt ringbrynja.",al={"innehållet i furens anteckningar","vad är furen's notes"}},{q="Är det här uppdraget bara för krigare?",a="Ja, det här kuriruppdraget ingår i krigarnas särskilda prövningar och utveckling, där de stärker sin stridsförmåga och kunskap om rustningssmide.",al={"krigaruppdrag mathiel","kan andra klasser göra mathiel"}}},fx={c109af9e={q="Varför litar Furen Longbeard på att du levererar hans anteckningar till Mathiel?",a="Du bevisade ditt engagemang och din styrka genom att samla de sällsynta reagenser som Furen behövde för att smida din eldhärdade rustning. Han har sett med egna ögon att du är pålitlig och vet att du klarar den långa resan över havet till Darnassus för att överlämna hans hårt förvärvade tekniker till Mathiel.",al={"varför skicka mig till mathiel","varför jag ska leverera furens anteckningar","varför behöver furen mig"}}},fp="7,190,24.239.0,32.275.0,15.168.0,37.190.0,38.138.0,44.215.1,39.156.0,37.132.0"}
P.entries["quest:1704"] = {n="Klockmort Spannerspan",s="Det här uppdraget skickar en äventyrare från Stormwind till Ironforge för att överlämna handelshemligheter till Klockmort Spannerspan i Tinkertown. Efter att ha bemästrat konsten att härda rustningar med eld delar dvärgssmeden Furen Longbeard ivrigt sina metallurgiska upptäckter med sin gnomiska kollega. Det är en viktig länk på vägen för en blivande krigare som vill pröva ovanliga hantverksmetoder.",h="Det här uppdraget skickar en äventyrare från Stormwind till Ironforge för att överlämna handelshemligheter...",kw={"smed","eldhärdad","furen","ironforge","klockmort","longbeard","anteckningar","spannerspan","tinkertown"},ang={["class:Warrior"]="Din resa mot att tillverka hållbar stridsutrustning tar dig från dvärgarnas härdar rakt in i gnomisk uppfinningsrikedom och väcker uppmärksamhet hos Tinkertowns främsta hantverkare.",["profession:Blacksmithing"]="Furen's Notes står för utbytet av avancerade smidestekniker mellan Ironforges mästerliga hantverkare.",["race:Gnome"]="Klockmort förenar klassisk dvärgisk metallurgi med gnomisk experimentlusta i Tinkertown."},sec={{t="En kollega i Tinkertown",b="Efter att ha smitt en uppsättning eldhärdad ringbrynja sammanställer Furen Longbeard sina detaljerade rön för att dela dem med en hantverkskollega. I stället för att hålla sina nyupptäckta tekniker för sig själv litar Furen på att du tar hans anteckningar från Stormwind till Ironforge och vidare in bland slamret och ångan i Tinkertown, där den gnomiska smeden Klockmort Spannerspan arbetar."},{t="Gnomisk entusiasm",b="Gnomiska smeder är relativt sällsynta bland sina dvärgvärdar, och Klockmort brinner för att tänja på gränserna för traditionellt metallarbete. När Klockmort granskar Furen's Notes blir han vilt entusiastisk över genombrottet och ivrig att använda de eldbaserade teknikerna i sina egna ovanliga projekt."}},faq={{q="Vem är Klockmort Spannerspan?",a="Klockmort Spannerspan är en gnomisk smed som arbetar i Tinkertown i den underjordiska staden Ironforge. Han samarbetar nära med dvärgsmeder som Furen Longbeard om avancerade metallbearbetningstekniker.",al={"klockmort spannerspan","vem är klockmort","gnomisk smed ironforge"}},{q="Varför skickar Furen Longbeard dig till Klockmort?",a="Furen skrev ner genombrottsteknikerna som han upptäckte när han tillverkade eldhärdad ringbrynja. Eftersom han känner till Klockmorts passion för nyskapande smide skickar Furen dig med anteckningarna, så att gnomen kan experimentera med dem.",al={"varför lämna över anteckningar","furen's notes","furen longbeard klockmort"}},{q="Var hittar jag Klockmort Spannerspan?",a="Klockmort Spannerspan finns i Tinkertown, den gnomdominerade stadsdelen i den östra delen av Ironforge, omgiven av arbetsbänkar och maskiner.",al={"klockmorts plats","var finns klockmort","klockmort ironforge"}},{q="Vad händer när jag har gett Klockmort anteckningarna?",a="Klockmort blir helt uppslukad av Furens genombrott och börjar genast planera egna metallurgiska projekt. Det leder dig vidare mot att samla ovanliga material som iron coral.",al={"fortsättning på uppdraget","vad händer efter klockmort","iron coral uppdrag"}},{q="Är det här uppdraget bara för krigare?",a="Ja. Överlämningen ingår i en särskild rustningstillverkningskedja som bara är tillgänglig för allianskrigare under träning hos erfarna vapen- och rustningsmästare.",al={"endast krigare","kan alla göra uppdraget","klasskrav"}},{q="Varför säger Klockmort att han inte kan skilja dag från natt?",a="Ironforge är en helt underjordisk stad, uthuggen djupt inne i bergen i Dun Morogh. I Tinkertown, under stenvalv och glödande lampor, kan hantverkarna inte se solen eller himlen.",al={"klockmorts dag natt dialog","dialogen way down here"}}},fp="21,184,25.238.0,18.246.0,29.172.0,47.190.0,39.123.0,46.151.1,34.124.0,53.140.0"}
P.entries["quest:1705"] = {n="Burning Blood",s="I Stormwind tar Grimand Elmore till Furen Longbeards smidesmetoder. Han behöver brinnande blod och en Burning Rock från Duskwood för att själv pröva rustningstekniken.",h="I Stormwind tar Grimand Elmore till Furen Longbeards smidesmetoder.",kw={"brinnande blod","burning rock","duskwood","furen longbeard","grimand elmore","gutspill","nightbane-worgen","roland's doom"},ang={["class:Warrior"]="Som krigare kan du trotsa Duskwoods förbannade bestar för Grimands experiment och förtjäna en unikt härdad rustning, gjord för frontlinjen.",["faction:Alliance"]="Som medlem av Alliansen kan du hämta reagenser från Roland's Doom, bidra till att hejda worgenhotet i Duskwood och förse Stormwinds rustkammare med nya försvarsmetoder.",["profession:Blacksmithing"]="Som smed kan du se Grimand pröva metoderna från sin tidigare elev Furen med sällsynta metaller och härdningsmedel."},sec={{t="Ett motvilligt försök",b="Grimand Elmore är en av Alliansens skickliga rustningsmakare, och han medger sällan att någon annan smed kan överträffa hans metoder. När han får höra om Furen Longbeards ovanliga smidesupptäckter väcks hans yrkesmässiga nyfikenhet. Grimand går med på att pröva Furens metoder genom att tillverka en rustningsdel. Han behöver märkliga, flyktiga beståndsdelar från sydens mörka trakter för att härda och anlöpa metallen enligt sina exakta krav; vanligt vatten och vanliga kol duger inte."},{t="Rysligheterna i Roland's Doom",b="Grimand skickar dig till Duskwood, till den övergivna gruvan Roland's Doom. Vilda Nightbane-worgen har tagit över dess tunnlar, och deras förbannade ådror pulserar av brinnande vätska. Han behöver vialer med deras brinnande blod och en sällsynt, flammande kärna kallad Burning Rock, som bärs av flockens ledare Gutspill. Ta med de glödheta materialen tillbaka så att Grimand kan pröva Furens metoder vid smedjan."}},faq={{q="Vem är Grimand Elmore?",a="Grimand Elmore är en respekterad mästarrustningsmakare i Stormwinds Dwarven District. Han arbetar med andra hantverkare för att utrusta stadens försvarare och tränar blivande krigare i hur en riktig stridsrustning känns och håller.",al={"grimand","grimand elmore","rustningsmakare i stormwind"}},{q="Varför vill Grimand ha brinnande blod och en Burning Rock?",a="Grimand vill pröva en rustningsteknik som utvecklats av Furen Longbeard. Det brinnande blodet och Burning Rock ger den övernaturliga hetta som behövs för att smida och anlöpa specialgjorda rustningsplåtar.",al={"varför brinnande blod","vad används burning rock till","uppdragets syfte"}},{q="Var hittar jag Nightbane-worgen som bär på materialen?",a="Du hittar materialen i Duskwood vid Roland's Doom, en övergiven gruva i sydöstra Duskwood, sydväst om Darkshire. Nightbane-worgen fyller tunnlarna och bär på det brinnande blodet.",al={"var finns worgen","var ligger roland's doom","var finns brinnande blod"}},{q="Vem har Burning Rock?",a="Gutspill, en mäktig ledare bland Nightbane-worgen, bär Burning Rock djupt inne i Roland's Doom.",al={"vem har burning rock","gutspill","var finns gutspill"}},{q="Vilket förhållande har Grimand Elmore till Furen Longbeard?",a="Furen Longbeard är Grimand Elmores tidigare elev. Grimand är vanligtvis skeptisk till idéer utifrån, men Furens senaste rustningstekniker har övertygat honom om att pröva dem själv.",al={"grimand och furen","vem är furen longbeard"}},{q="Vad händer när jag lämnar tillbaka blodet och stenen?",a="När Grimand fått de eldiga reagenserna börjar han smida rustning för att pröva Furens metoder. Han lovar den färdiga rustningsdelen till äventyraren som samlade ihop materialen.",al={"nästa uppdrag","belöning","vad tillverkar grimand"}}},fx={["50895b50"]={q="Vad ska Burning Blood användas till?",a="Grimand Elmore behöver Burning Blood för att pröva en exotisk smidesteknik som hans tidigare elev, Furen Longbeard, utvecklat. Grimand vill använda den onaturliga, brännande hettan i Duskwoods worgens ådror för att härda en specialtillverkad rustning och se om Furens metallurgi verkligen håller måttet.",al={"uppdragsföremålet burning blood","vad används burning blood till","varför burning blood"}},["8a0ab7ce"]={q="Vad ska Burning Rock användas till?",a="Grimand behöver Burning Rock som en viktig beståndsdel när han prövar Furen Longbeards metoder för att tillverka rustningar. Den glödheta stenen kommer från worgenledaren Gutspill, djupt inne i Roland's Doom. Den ger den råa elementära hettan och de magiska egenskaper som behövs för att smida Fire Hardened Coif.",al={"vad används burning rock till","varför burning rock","vad gör grimand med burning rock"}},["0438723a"]={q="Vilka är Nightbane-worgenerna i Duskwood?",a="Nightbane är vilda, varglika humanoider som hemsöker Duskwoods mörka skogar. En grupp av dem har tagit skydd i den övergivna gruvan Roland's Doom, där den fruktade Gutspill för befälet. Deras onaturligt heta blod och brinnande skatter gör dem till mål för ambitiösa rustningssmeder som Grimand.",al={"vilka är nightbane-worgenerna","worgener i roland's doom","nightbane i roland's doom"}}},fp="13,176,22.471.0,28.390.0,22.221.0,55.196.0,62.189.0,27.109.0,68.186.0,48.168.0"}
P.entries["quest:1706"] = {n="Grimand's Armor",s="I Stormwind tar Grimand's Armor form genom ett prov av Furen Longbeards metoder. Grimand Elmore smider en hjälm av sällsynta material, avsedd att tåla hårda slag i strid. För en krigare i Alliansen är den ett steg mot mästerskap.",h="I Stormwind tar Grimand's Armor form genom ett prov av Furen Longbeards metoder.",kw={"rustning","coif","burning blood","dwarven district","furen longbeard","grimand elmore","stormwind","krigaruppdrag"},ang={["class:Warrior"]="Som krigare i Alliansen når du ett avgörande steg i din träning: en tålig coif smidd för att stå emot de hårda slagen i stridens frontlinje.",["faction:Alliance"]="Grimand Elmore bygger vidare på Furen Longbeards ritningar, medan dvärgsmederna i Stormwinds Dwarven District samlar sina upptäckter för att beväpna krigare i Alliansen.",["profession:Blacksmithing"]="Utbytet för samman två dvärgsmeder i Stormwinds Dwarven District, där ovanliga ingredienser används för att härda metall."},sec={{t="En mästares beprövade nytänkande",b="Grimand Elmore prövar Furen Longbeards djärva smidesmetoder vid sin ässja i Stormwinds Dwarven District. Grimand hade tvivlat på den dvärgiske mästerpansarsmedens teorier. För att sätta dem på prov samlar en krigare sällsynta elementar- och bestkomponenter i fientligt område och tar dem till Grimand. Han använder materialen för att smida en förstärkt hjälm som ska tåla krossande stötar."},{t="Att smida skyddet",b="Grimands färdiga coif visar att Furens metallurgiska insikter stämde. Han behandlar metallen så att den står emot tryck och fysiska slag som skulle böja vanligt stål. Grimand ger coifen till krigaren som hjälpte honom och hedrar därmed Furens hantverk och krigarens beslutsamhet. Rustningen kan hjälpa dem att hålla frontlinjen mot Azeroths största hot."}},faq={{q="Vad är syftet med det här uppdraget?",a="Grimand Elmore färdigställer en specialbehandlad coif av de sällsynta material du samlade in och prövar Furen Longbeards experimentella smidesmetoder. Detta är det sista överlämnandet i en omfattande träningskedja för krigare.",al={"syftet med grimand's armor","varför grimand's armor","vad ger grimand mig"}},{q="Vem är Grimand Elmore?",a="Grimand Elmore är en skicklig dvärgisk vapensmed i Stormwinds Dwarven District. Han samarbetar med kolleger i Ironforge för att hjälpa blivande krigare att få specialiserad rustning.",al={"vem är grimand","grimand elmores roll","var finns grimand"}},{q="Vem är Furen Longbeard och varför nämns han?",a="Furen Longbeard är en dvärgisk mästerpansarsmed i Stormwinds Dwarven District. Han utformade en metod för att förstärka rustning mot enorm påfrestning, men Grimand tvivlade på hans påståenden tills du kom med material för att pröva metoden.",al={"vem är furen","furens teknik","furen longbeard"}},{q="Vilket uppdrag leder direkt till det här?",a="Det här följer efter 'Burning Blood'. Där tar krigaren med sig den sista sällsynta ingrediensen till Grimand: Burning Blood från Nightbane-worgarna i Roland's Doom i Duskwood, så att han kan kyla och härda metallen.",al={"förkrav för grimand's armor","uppdraget burning blood","vilket uppdrag kommer före det här"}},{q="Kan alla klasser slutföra det här uppdraget?",a="Nej. Den här kedjan är för krigare i Alliansen kring sin trettionde säsong och markerar en övergångsrit på vägen mot slitstark ringbrynja.",al={"är grimand's armor bara för krigare","vem kan göra grimand armor"}},{q="Var sker inlämningen?",a="Du lämnar coifen till Grimand Elmore vid hans städ i Stormwind Citys Dwarven District.",al={"var lämnar man in grimand armor","grimands plats i stormwind"}}},fx={c92a0d61={q="Varför vill Grimand Elmore att det här blir gjort?",a="Grimand Elmore sätter Furen Longbeards radikala smidestekniker på det ultimata provet. Till en början tvivlade Grimand på att Furens metoder kunde ge bättre resultat, men han behövde sällsynta och kraftfulla material för att själv smida rustningen. När han färdigställer den och bevisar att den tål oerhörda påfrestningar bekräftar han sin kollegas genombrott och rustar samtidigt en erfaren krigare för strid.",al={"varför smida grimands rustning","grimand elmores drivkraft","varför smida rustningen"}}},fp="15,236,28.378.0,17.351.0,34.203.0,22.168.0,47.208.0,40.196.0,34.125.0,35.87.0"}
P.entries["quest:1707"] = {n="Water Pouch Bounty",s="Spigot Operator Luglunket i Gadgetzan vill ha de vattenläglar från Wastewander som nomaderna stal, var du än hittar dem ute i öknen. Gadgetzans vattenbolag erbjuder ett officiellt omsorgspaket för var femte.",h="Spigot Operator Luglunket i Gadgetzan vill ha de vattenläglar från Wastewander som nomaderna stal, var du än...",kw={"gadgetzan","luglunket","tanaris","wastewander","vattenbolag","vattenlägel"},sec={{t="Vatten som tillhör Gadgetzan",b="Luglunket, en erfaren kranoperatör, vill inget hellre än att få de vattenläglar från Wastewander som du hittar i öknen. Det var Gadgetzans vatten från början, och nomaderna stal det helt enkelt. För var femte lägel du lämnar in erbjuder Gadgetzans vattenbolag ett officiellt omsorgspaket, och du hjälper Gadgetzan att hjälpa sig självt."},{t="Fortsätt lämna in dem",b="Luglunket är glad för varje återtagen lägel, eftersom var och en håller alla längre från katastrofen. Luglunket lovar att belöna dig för var femte lägel du tar med."}},faq={{q="Vem är Spigot Operator Luglunket?",a="En erfaren kranoperatör i Gadgetzan som efterfrågar vattenläglar från Wastewander.",al={"vem är luglunket","luglunkets roll","kranoperatör"}},{q="Varför vill Luglunket ha vattenläglar från Wastewander?",a="Vattnet tillhör Gadgetzan, och nomaderna stal det.",al={"varför vattenläglar","varför döda wastewander","wastewanders vattenlore"}},{q="Var hittar man vattenläglar från Wastewander?",a="Ute i öknen, hos Wastewander-nomaderna som stal dem.",al={"var hittar man vattenläglar","wastewander-läglarnas plats","vem släpper vattenläglar"}},{q="Vad erbjuder Gadgetzans vattenbolag för läglarna?",a="Ett officiellt omsorgspaket för varje fem läglar.",al={"omsorgspaket","vad får jag för läglar"}}},fp="18,219,31.357.0,16.177.1,33.79.0,50.54.0,45.73.0,60.55.0"}
P.entries["quest:1708"] = {n="Iron Coral",s="Iron Coral är ett alliansuppdrag som ges av den gnomiska smeden Klockmort Spannerspan i Tinker Town i Ironforge. Han vill pröva nya smidesmetoder på en specialbyggd rustning och skickar dig att hämta sällsynt Searing Coral längs Wetlands kust. När du hjälper honom kan han förena gnomisk uppfinningsrikedom med dvärgiskt hantverk.",h="Iron Coral är ett alliansuppdrag som ges av den gnomiska smeden Klockmort Spannerspan i Tinker Town i...",kw={"smältning av rustning","furen longbeard","iron coral","ironforge","klockmort spannerspan","menethil harbor","searing coral","tinker town","wetlands"},ang={["profession:Blacksmithing"]="Smeder lär uppskatta den okonventionella smältteknik som Klockmort prövar och som förvandlar havsfynd till härdade rustningsplåtar.",["profession:Engineering"]="Uppdraget visar hur uppfinnare testar egenskaperna hos ovanliga material för att få bättre skydd.",["race:Dwarf"]="Experimentet bygger direkt på de metallurgiska upptäckterna som gjorts av Ironforges mästersmed Furen Longbeard och visar det nära samarbetet mellan gnomer och dvärgar i Tinker Town.",["race:Gnome"]="Klockmort väljer märkliga kustmineral framför vanlig järnmalm, vilket speglar typisk gnomisk uppfinningsrikedom och strävan efter att förbättra traditionellt hantverk genom experiment."},sec={{t="En förening av hantverk",b="Efter att ha utbytt insikter med dvärgmästaren Furen Longbeard är Klockmort Spannerspan full av inspiration. Den excentriske gnomiska smeden vill förena Furen Longbeards metallurgi med sina egna uppfinningar för att skapa en ovanligt tålig rustning. För att genomföra det djärva metallurgiska experimentet räcker inte vanliga malmer från bergen. Klockmort behöver ett ovanligt, naturligt härdat havsmaterial som kallas Searing Coral."},{t="Dykning vid Wetlands kust",b="Searing Coral är en flyktig, hård havsbildning som bara finns i ett särskilt område: under vatten utanför kusten söder om Menethil Harbor i Wetlands. För att samla tjugo kluster måste du vada genom förrädiskt kärrvatten, trotsa lokala vattenrovdjur och bära den droppande skörden tillbaka till Ironforge. För Klockmort är belöningen värd den blöta utflykten, eftersom han tänker smälta och hamra in korallen direkt i sina experimentella rustningsplåtar."}},faq={{q="Vem är Klockmort Spannerspan?",a="Klockmort Spannerspan är en skicklig gnomisk smed som bor i Tinker Town i bergsstaden Ironforge. Han brinner för mekaniska uppfinningar och banbrytande metallurgi och samarbetar nära med dvärgiska hantverkare för att hitta på nya metoder att tillverka rustningar.",al={"klockmort","vem ger iron coral","uppdragsgivare för iron coral"}},{q="Vad är Searing Coral?",a="Searing Coral är en sällsynt havsbildning som samlas från havsbottnen söder om Menethil Harbor i Wetlands. Den har unika kemiska och fysiska egenskaper som gör att en uppfinningsrik hantverkare kan smälta och hamra in den som förstärkning i rustningar.",al={"searing coral i historien","vad används searing coral till"}},{q="Var hittar jag Searing Coral?",a="Korallbankarna växer bara under vatten längs havsstranden strax söder om Menethil Harbor i Wetlands. Dyk under vågorna och bänd loss de mineralrika grenarna.",al={"searing coral plats","var finns iron coral","wetlands korallplats"}},{q="Varför behöver Klockmort Searing Coral i stället för metallmalm?",a="Klockmort försöker utveckla smidesteknikerna han lärde sig av dvärgen Furen Longbeard. I stället för att enbart förlita sig på traditionella malmer från Ironforge hoppas han att Searing Corals ovanliga egenskaper ska ge en lättare och betydligt tåligare yta när materialet smälts.",al={"varför korall till rustning","korallmetallurgi"}},{q="Hur är Furen Longbeard inblandad i uppdraget?",a="Furen Longbeard utvecklade tidigare nya rustningstekniker med din hjälp. Tacksam för hjälpen delade Furen med sig av sina yrkeshemligheter till Klockmort, vilket inspirerade gnomen att anpassa dem till sina egna skyddande uppfinningar.",al={"furens koppling","furen longbeard iron coral"}},{q="Vad händer när jag tar korallen till Klockmort?",a="När Klockmort fått tjugo lass Searing Coral börjar han genast smälta och hamra materialet vid sin arbetsbänk. Det leder direkt till att hans experimentella utrustning visas upp i uppdraget Klockmort's Creation.",al={"fortsättning på iron coral","nästa uppdrag efter iron coral"}}},fx={f5cb4716={q="Varför vill Klockmort Spannerspan att den glödande korallen samlas in?",a="Klockmort är en entusiastisk gnomuppfinnare som gärna experimenterar. Efter att ha lärt sig nyskapande smidestekniker av Furen Longbeard vill han kombinera Furens metoder med sina egna ingenjörskunskaper för att smida en ovanligt tålig rustning. För att tillverka den behöver han de unika egenskaperna hos glödande korall från Wetlands kust.",al={"varför vill klockmort ha korall","klockmorts drivkraft och iron coral","varför tillverka rustning av iron coral"}}},fp="10,225,18.345.0,25.309.0,29.212.0,22.211.0,34.138.0,59.186.0,45.184.0,51.184.1"}
P.entries["quest:1709"] = {n="Klockmort's Creation",s="Klockmort's Creation markerar att en specialutformad rustning har smitts framgångsrikt i Ironforges Tinker Town. Med en ovanlig teknik som mästersmeden Furen Longbeard tagit fram formar gnomsmeden Klockmort Spannerspan råmaterial till en ovanligt tålig utrustningsdel.",h="Klockmort's Creation markerar att en specialutformad rustning har smitts framgångsrikt i Ironforges Tinker...",kw={"furen longbeard","järnkorall","ironforge","klockmort","belägringsmaskin","spannerspan","tinker town","krigarrustning"},ang={["class:Warrior"]="Att beställa dessa handskar är en viktig milstolpe för allianskrigare. De får en specialhärdad rustning som byggts för att tåla de krossande slagen i strid vid frontlinjen.",["profession:Blacksmithing"]="Att Furen Longbeards formel fungerar visar värdet av att experimentera med ovanliga härdningsmetoder och sällsynta material från havet.",["race:Gnome"]="Klockmorts arbete visar att gnomisk uppfinningsrikedom spelar en viktig roll även i tung pansarsmidning, och att mekanisk precision kan förbättra traditionellt dvärghantverk."},sec={{t="En förening av hantverk",b="Tung rustning smids vanligtvis vid Great Forges stora städ, men Klockmort Spannerspan arbetar i Tinker Town. Rustningen är en gemensam triumf för dvärgarnas metallurgiska tradition och gnomernas mekaniska innovation. Genom att anpassa Furen Longbeards noggranna metoder färdigställer Klockmort ett par pansrade handskar som är konstruerade för att tåla slag som skulle krossa vanligt stål."},{t="Oöverträffad tålighet",b="Enligt Klockmort är rustningen så stabil att en belägringsmaskin kan rulla rakt över den utan att den får någon bestående formförändring. Hemligheten ligger i den säregna behandlingen av sällsynta komponenter. Det visar att uråldriga dvärgiska smidestekniker i kombination med gnomisk uppfinningsrikedom ger en rustning som klarar de hårdaste striderna vid frontlinjen."}},faq={{q="Vem är Klockmort Spannerspan?",a="Klockmort Spannerspan är en skicklig gnomsmed som bor i Tinker Town i Ironforge. Han hjälper till med komplicerade mekaniska arbeten och samarbetar med dvärghantverkare som Furen Longbeard för att skapa unik och slitstark utrustning.",al={"klockmort","vem är klockmort","gnom i tinker town"}},{q="Vem utformade metoden för att göra rustningen?",a="Smidesprocessen utformades av Furen Longbeard, en skicklig dvärgpansarsmed. Klockmort följde Furens exakta metod för att behandla materialen och färdigställa rustningen.",al={"vem skapade metoden","furen longbeards rustning","furens metod"}},{q="Varför tillverkade en gnomsmed rustningen?",a="Klockmort, en gnomsmed, ville prova Furen Longbeards nya teknik på en egen rustningsdel. Eftersom du hade hjälpt Furen erbjöd han dig den färdiga rustningen i utbyte mot att du samlade in Searing Coral som han behövde.",al={"varför en gnom","gnomisk smide","rustningssmide"}},{q="Vad gör rustningen speciell jämfört med vanlig plåtrustning?",a="Klockmort hävdar att den färdiga rustningen har en anmärkningsvärd fjädring och elasticitet, samtidigt som den är mycket hållbar. Han skryter med att metallen genast skulle återfå sin ursprungliga form även om den plattades till under banden på en tung belägringsmaskin.",al={"hur tålig är den","rustning mot belägringsmaskin","rustningens hållbarhet"}},{q="Var passar rustningen in i en krigares träning?",a="Den här skapelsen är slutmålet för en särskild uppdragsserie som lovande allianskrigare genomför för att utrusta sig med slitstark rustning, specialsmidd av Ironforges främsta hantverkare.",al={"krigaruppdragets rustning","varför göra uppdraget","krigarbelöning"}},{q="Var hittar man Klockmort?",a="Klockmort Spannerspan finns bland verkstäderna, de skramlande kugghjulen och ångventilerna i Tinker Town, Ironforges gnomkvarter.",al={"klockmorts plats","var finns spannerspan"}}},fx={fd9fc5fd={q="Varför hjälper Klockmort Spannerspan till med att tillverka den här rustningen?",a="Klockmort Spannerspan tog sig an uppgiften för att pröva Furen Longbeards radikala teori om rustningstillverkning. Dvärgars smide bygger sällan på gnomisk precisionsteknik, så arbetet med handskarna gav Klockmort chansen att bevisa att Furens metoder i kombination med gnomisk mekanik kan ge en rustning som står emot till och med en belägringsmaskin.",al={"varför hjälper klockmort till","klockmort spannerspans drivkraft","varför smider klockmort den här rustningen"}}},fp="20,224,23.328.0,20.271.0,29.201.0,44.171.0,43.200.0,57.207.0,62.136.0,25.125.0"}
P.entries["quest:1710"] = {n="Sunscorched Shells",s="I Darnassus samarbetar pansarsmeden Mathiel med dvärgsmeden Furen Longbeard för att finslipa en ny teknik för ringbrynjor. Han skickar krigare till Thousand Needles för att samla tåliga wyvernäggskal från Highperchs höjder.",h="I Darnassus samarbetar pansarsmeden Mathiel med dvärgsmeden Furen Longbeard för att finslipa en ny teknik för...",kw={"äggskal","furen longbeard","highperch","lack","ringbrynja","mathiel","thousand needles","wyvern"},ang={["class:Warrior"]="Mathiels experiment ska ge en tålig ringbrynja och är ett viktigt övergångsprov för allianskrigare som vill uppgradera sin stridsutrustning.",["faction:Alliance"]="Samarbetet visar hur hantverkskunskaper utbyts mellan Night Elf-hantverkare i Darnassus och dvärgiska pansarsmeder i Stormwind.",["profession:Blacksmithing"]="Uppdraget visar en ovanlig smidesteknik: att bearbeta delar från bestar till skyddande lack för metallänkar i ringbrynjor."},sec={{t="En hantverksallians över fraktionsgränserna",b="Mathiel arbetar från Warrior's Terrace i Darnassus, men hans hantverk tar honom långt bortom traditionella Night Elf-tekniker. Han brevväxlar med Furen Longbeard, en skicklig dvärgisk pansarsmed i Stormwind. Inspirerad av Furens upptäckter inom metallurgi och pansarsmide vill Mathiel smida en ringbrynja förstärkt med naturliga material som tål extrema påfrestningar. För att pröva den här blandade teorin behöver han exotiska material som inte går att hitta i närheten av Teldrassil."},{t="Farorna vid Highperch",b="Nyckeln till Mathiels experiment finns långt söderut, på andra sidan havet, i Thousand Needles raviner. Där, högt ovanför saltslätterna och de röda stenplatåerna, häckar wyverns vid Highperch under Kalimdors brännande sol. Deras äggskal hårdnar av den ständiga hettan och höjden. Mathiel tänker mala sönder de soltorkade skalen och bearbeta dem till en motståndskraftig lack. Den ska täcka ringbrynjelänkarna och ge en flexibel men ovanligt tålig rustning."}},faq={{q="Vem är Mathiel?",a="Mathiel är en Night Elf-pansarsmed som bor vid Warrior's Terrace i Darnassus. Han arbetar nära dvärgiska hantverkare och samarbetar med Furen Longbeard för att utveckla avancerade ringbrynjor åt beprövade krigare.",al={"mathiel","vem ger soltorkade skal","mathiel darnassus"}},{q="Varför behöver Mathiel wyvernskal?",a="Skalen från wyverns vid Highperch har bakats och hårdnat i Thousand Needles obarmhärtiga sol. Mathiel krossar dem och bearbetar dem till en särskild lack som täcker ringbrynjelänkarna och gör dem betydligt tåligare.",al={"varför wyvernskal","vad används soltorkade skal till","vad används skalen till"}},{q="Var ligger Highperch?",a="Highperch är en brant stenplatå i västra Thousand Needles, nära gränsen till Feralas. Wyverns bygger sina bon längs klipporna och platån.",al={"highperchs läge","var ligger highperch","hur hittar man highperch"}},{q="Hur hänger Furen Longbeard ihop med uppdraget?",a="Furen Longbeard är en mästerlig dvärgisk pansarsmed i Stormwind. Mathiel ser Furen som en respekterad kollega och låter Furens upptäckter inom pansarsmide inspirera sitt eget arbete i Darnassus.",al={"furen longbeards koppling","vem är furen"}},{q="Varför ber en Night Elf i Darnassus om material från Thousand Needles?",a="Den särskilda kemiska tålighet Mathiel behöver finns bara i wyverns ägg som utsatts för den skoningslösa, torra hettan på de södra ravinernas platåer. Den går inte att återskapa bland Teldrassils dimhöljda grenar.",al={"varför thousand needles","darnassus till thousand needles"}},{q="Vad händer när du lämnar skalen till Mathiel?",a="När Mathiel får tjugo soltorkade skal börjar han genast framställa lacken och smida en specialanpassad ringbrynja som belöning för dina insatser i fält.",al={"vad gör mathiel sedan","efter soltorkade skal","mathiels fortsättning"}}},fx={dd37f0b8={q="Vad ska Sunscorched Shell användas till?",a="De tåliga äggskalen från wyvernerna vid Highperch är förvånansvärt hårda. Mathiel tänker mala ner dem och göra en skyddande lack av dem. Den ska han använda för att täcka de enskilda ringarna i sin experimentella ringbrynja och göra den mer hållbar.",al={"vad används sunscorched shell till","varför sunscorched shell","vad ska äggskalen användas till"}}},fp="18,217,33.396.0,23.433.0,15.171.0,36.166.0,27.123.0,46.152.0,70.161.0,50.155.0"}
P.entries["quest:1711"] = {n="Mathiel's Armor",s="”Mathiel's Armor” markerar att Mathiels arbete med att smida rustning i Warrior's Terrace i Darnassus är slutfört. Genom att kombinera sitt eget nattalviska hantverk med innovativa dvärgiska metallbearbetningsmetoder, utvecklade av Furen Longbeard, smider Mathiel om exotiska material till skyddande stridsutrustning. Uppdraget visar hur allierade traditioner kan förenas till gagn för Alliansens krigare.",h="”Mathiel's Armor” markerar att Mathiels arbete med att smida rustning i Warrior's Terrace i Darnassus är...",kw={"craftsmen's terrace","darnassus","furen longbeard","mathiel","mathiel's armor","solbrända skal","krigarrustning"},ang={["class:Warrior"]="Den här uppdragskedjan ger Alliansens krigare ett par stadiga benkläder, smidda med den samlade metallurgiska kunskapen hos nattalviska och dvärgiska smeder.",["faction:Alliance"]="Mathiel och Furens samarbete visar vilka praktiska militära fördelar Alliansen ger. Avlägsna folk förenas genom handel och gemensamt försvar.",["profession:Blacksmithing"]="Projektet är ett lysande exempel på hantverk mellan fraktioner och visar att dvärgisk, sträng härdning kan samspela med nattalviskt, elegant smide."},sec={{t="En blandning av hantverk",b="Nattalviska rustningssmeder föredrar traditionellt metoder som förfinats under årtusenden och förlitar sig på samklang med naturen, följsamt läder eller omsorgsfullt bearbetade metaller. Men utbytet mellan nattalverna och Eastern Kingdoms har fått mästersmeder som Mathiel att experimentera. Genom att använda nyutvecklade tekniker från den dvärgiske rustningssmeden Furen Longbeard lyckas Mathiel förena dvärgisk metallurgi med alvisk konstnärlighet."},{t="Exotiska beståndsdelar",b="För att smida den här tåliga rustningen behövdes solbrända äggskal från wyvernnästen vid Highperch i Thousand Needles. Mathiel förvandlade skalen, som härdats i solen, till lack och använde Furen Longbeards värmebehandlingsformler. På så vis skapade han ett tåligt par benkläder som kan stå emot brutal strid vid frontlinjen."}},faq={{q="Vem är Mathiel?",a="Mathiel är en skicklig nattalvisk rustningssmed som arbetar i Warrior's Terrace i Darnassus. Han samarbetar nära med hantverkare i hela Alliansen och prövar nya idéer från allierade som Furen Longbeard.",al={"mathiel","vem är mathiel","rustningssmed i darnassus"}},{q="Vem är Furen Longbeard?",a="Furen Longbeard är en mästersmed bland dvärgarna och bor i Stormwind City. Han är känd för att ha uppfunnit innovativa tekniker för att härda och smida specialanpassade rustningsplåtar. Han delar regelbundet instruktioner och ritningar med allierade smeder i hela Alliansen.",al={"furen","furen longbeard"}},{q="Vilka material användes för att smida rustningen?",a="Rustningen smids av solbrända äggskal som samlats nedanför wyvernnästena vid Highperch i Thousand Needles. Mathiel förstärker och formar dem med hjälp av Furen Longbeards särskilda smidesmetoder.",al={"rustningsmaterial","vad är mathiel's armor gjord av"}},{q="Varför använder en alv dvärgiska tekniker?",a="Alliansens smeder delar ofta kunskap för att rusta sina kämpar mot växande hot. Nattalviskt smide är känt för sin finess och hållbarhet, och Mathiel använder gärna dvärgiska nyheter som ger exceptionellt effektiva härdningsmetoder.",al={"varför dvärgismide","samarbete mellan nattalver och dvärgar"}},{q="Var utspelar sig uppdraget?",a="Uppdraget börjar och avslutas vid smedjan i Warrior's Terrace i Darnassus på ön Teldrassil.",al={"mathiels plats","var finns mathiel"}},{q="Vilket uppdrag kommer före detta i kedjan?",a="Det här uppdraget följer direkt efter ”Sunscorched Shells”. Där måste en äventyrare resa till Kalimdors avlägsna trakter för att hämta tåliga äggskal som Mathiel kan använda i sitt hantverk.",al={"föregående uppdrag","förkrav för mathiels armor"}}},fx={["5fea36e4"]={q="Varför smider Mathiel den här rustningen åt dig?",a="Mathiel vill pröva och bekräfta hantverket som Furen Longbeard förmedlat. Genom att kombinera dvärgarnas rustningssmidestekniker med alvernas traditioner kan han tillverka ovanligt tåliga ringbrynjehalsar som stärker krigare som strider för Alliansen.",al={"varför tillverkar mathiel rustning","mathiels drivkraft","varför smida mathiels rustning"}}},fp="15,228,17.302.0,17.226.0,15.168.0,23.202.0,44.175.0,39.179.0,33.100.0,41.147.0"}
P.entries["quest:1712"] = {n="Cyclonian",s="Cyclonian är en mäktig vindherre som man försökt besegra i urminnes tider. För att utmana honom måste en hjälte samla de delar som krävs för att åkalla elementaren och fälla honom för att ta hans Whirlwind Heart. När vindherren besegras kan hjärtats kraft infogas i ett mäktigt vapen.",h="Cyclonian är en mäktig vindherre som man försökt besegra i urminnes tider.",kw={"hjälte","cyclonian","elementare","åkallning","whirlwind heart","vindherre"},ang={["class:Warrior"]="Att besegra vindherren Cyclonian är ett avgörande styrkeprov. Det visar din stridsmässiga skicklighet när du tar hans Whirlwind Heart och smider ett kraftfullt vapen."},sec={{t="Den slumrande vindherren",b="Cyclonian är en rasande elementarisk vindherre vars närvaro inger vördnad och försiktighet. I urminnes tider har en vaksam väktare hållit vakt över åkallningsplatsen och väntat på en stridskämpe med tillräcklig rå stridsförmåga för att utmana och förgöra denna stormande varelse."},{t="Åkalla stormen",b="För att kalla fram Cyclonian krävs en åkallningsritual med sällsynta material som beskrivs på ett särskilt pergament. När vindherren väl har åkallats måste du möta honom i direkt strid. Då prövas det om utmanaren verkligen är en hjälte eller bara ännu ett offer för hans ylande stormvind."},{t="Whirlwind Heart",b="Det yttersta målet med att möta vindherren är att ta hans Whirlwind Heart. När hjärtat skilts från den besegrade elementaren kan dess våldsamma elementarkrafter bindas och infogas i ett vapen värdigt en erfaren hjälte."}},faq={{q="Vem är Cyclonian?",a="Cyclonian är en mäktig elementarisk vindherre. Han utgör ett allvarligt elementärt hot som länge har bevakats av väktare i väntan på en hjälte stark nog att utmana och besegra honom.",al={"vem är cyclonian","cyclonians bakgrund","vad är cyclonian"}},{q="Varför måste Cyclonian åkallas?",a="Cyclonian åkallas för att utmanas och dödas av en värdig hjälte. När vindherren besegras kan en beprövad krigare ta hans Whirlwind Heart, vars kraft sedan kan infogas i ett mäktigt vapen.",al={"varför åkalla cyclonian","cyclonians syfte","varför slåss mot cyclonian"}},{q="Vad är Whirlwind Heart?",a="Whirlwind Heart är vindherren Cyclonians innersta väsen. När det slits ur den besegrade elementaren kan dess stormande krafter smidas direkt in i ett vapen med stor stridskraft.",al={"vad är whirlwind heart","cyclonians hjärta","whirlwind hearts syfte"}},{q="Vem har hållit uppsikt över Cyclonian?",a="Bath'rah the Windwatcher i Alterac Mountains har i urminnes tider hållit vakt över platsen och outtröttligt sökt efter en sann hjälte som kan störta elementarherren och bemästra hans stormande hjärta.",al={"vem vill döda cyclonian","vem håller uppsikt över cyclonian"}},{q="Hur kallas Cyclonian fram?",a="För att åkalla Cyclonian måste du samla särskilda sällsynta reagenser som finns nedtecknade på ett särskilt pergament. De lockar fram vindherren i världen, så att han kan utmanas.",al={"hur åkallar man cyclonian","cyclonians ingredienser"}},{q="Vilket vapen smids av Cyclonian?",a="En hjälte som samlar de nödvändiga delarna, åkallar Cyclonian och dödar honom får ett vapen genomsyrat av den slumrande vreden i elementarens Whirlwind Heart.",al={"cyclonians belöning","vilket vapen får man från cyclonian"}}},fp="9,298,24.270.0,21.268.0,19.234.1,17.190.0,31.198.0,28.192.0,32.209.0,31.171.0,37.161.0"}
P.entries["quest:1713"] = {n="The Summoning",s="The Summoning är ett krigarprov som leds av mystikern Bath'rah Windwatcher för att kalla fram Cyclonian, vindherren. Genom att åkalla och dräpa det stormande elementarväsendet gör en krigare anspråk på Whirlwind Heart, som fyller ett vapen med stormens kraft.",h="The Summoning är ett krigarprov som leds av mystikern Bath'rah Windwatcher för att kalla fram Cyclonian...",kw={"bath'rah windwatcher","bathrah","cyclonian","elementarväsen","the summoning","krigaruppdrag","whirlwind heart","vindherre"},ang={["class:Warrior"]="Att möta Cyclonian och ta Whirlwind Heart är ett avgörande prov för blivande krigare och ger ett vapen genomsyrat av stormens råa kraft.",["race:Troll"]="Bath'rah Windwatcher använder uråldriga, primitiva konster långt från civilisationen för att befalla vindandar. Det speglar trollschamaners och häxdoktorers djupa mystiska traditioner."},sec={{t="Kalla fram stormen",b="The Summoning fullbordar Bath'rah Windwatchers förberedelser. Eremitmystikern förbereder en uråldrig ritual för att kalla Cyclonian, ett fruktansvärt elementarväsen känt som vindherren, till de dödligas värld. I stället för att förhandla med stormen försöker den som utför ritualen kuva den och ger en skicklig mästare i uppdrag att slå ner varelsen så snart den tar form."},{t="Stormens hjärta",b="I stridens mitt finns Whirlwind Heart, kraftvirveln som upprätthåller Cyclonians fysiska gestalt. När vindherren har besegrats och hans hjärta slitits loss tar Bath'rah vara på den rasande stormvind som är fångad däri. Denna instabila elementarkärna blir katalysatorn som fyller ett vapen med stormens obändiga kraft."}},faq={{q="Vem är Cyclonian?",a="Cyclonian är ett mäktigt elementarväsen som kallas vindherren. När han kallas fram genom Bath'rah Windwatchers ritual visar han sig som en våldsam storm som måste besegras för att man ska få tag på essensen i hans kärna.",al={"vem är cyclonian","vad är cyclonian","cyclonians bakgrund"}},{q="Vad är Whirlwind Heart?",a="Whirlwind Heart är Cyclonians elementarkärna. Bath'rah Windwatcher behöver den för att binda vindherrens virvlande, förgörande energier direkt till ett mäktigt vapen.",al={"vad är whirlwind heart","varför behövs whirlwind heart","whirlwind hearts användning"}},{q="Vem är Bath'rah Windwatcher?",a="Bath'rah Windwatcher är en trollmystiker som bor i vildmarken och har kunskapen som krävs för att kalla fram Cyclonian. Han vägleder krigare genom ritualen och använder det fallna elementarväsendets hjärta för att smida mäktiga vapen.",al={"vem är bathrah","bathrah windwatcher","uppdragsgivare the summoning"}},{q="Varför kallas Cyclonian fram?",a="Syftet med att kalla fram Cyclonian är att möta vindherren i strid, dräpa honom och ta vara på hans elementarhjärta. Essensen används sedan för att fylla ett vapen med virvelvindens bestående raseri.",al={"varför kalla fram cyclonian","syftet med the summoning","skäl att kalla fram"}},{q="Vad händer när Cyclonian har besegrats?",a="När Cyclonian har besegrats och hans Whirlwind Heart har överlämnats till Bath'rah kan mystikern ta vara på de fångade elementarkrafterna och stärka ett vapen med Cyclonians stormmagi.",al={"vad händer efter att cyclonian besegrats","cyclonians belöning","efter the summoning"}},{q="Var äger ritualen rum?",a="Ritualen äger rum vid Bath'rah Windwatchers läger, där mystikern samlar den uråldriga kraft som krävs för att dra Cyclonian från elementarplanet till den fysiska världen.",al={"var sker ritualen","platsen för the summoning"}}},fp="13,254,19.374.0,22.345.0,17.216.0,28.178.0,28.217.0,32.204.0,41.185.0,36.180.0"}
P.entries["quest:1714"] = {n="Essence of the Exile",s="Essence of the Exile är en mystisk transmutationsritual kring en bubblande kittel som sprutar ut ånga. När resenärer lägger amuletter i dess djup utlöses en våldsam reaktion som skapar en sjudande klump av smält sten. Ritualen förenar kraftfulla, instabila reagenser med elementarkraft.",h="Essence of the Exile är en mystisk transmutationsritual kring en bubblande kittel som sprutar ut ånga.",kw={"bubbla","kittel","amuletter","essence of the exile","smält sten","transmutation","ångor"},ang={["class:Mage"]="Alkemistiska kittlar och elementära transmutationer kanaliserar ofta rå, instabil magi för att binda samman olika essenser till fast form.",["class:Shaman"]="Att arbeta med elementära essenser, även i bubblande kittlar som formar smält sten, kräver förståelse för de uråldriga elementarkrafterna."},sec={{t="En kittel som lockar",b="Essence of the Exile omfattar en märklig transmutation kring en mystisk, bubblande kittel. Kärlet avger lockande ångor som frestar resenärer att undersöka dess sjudande djup. Det fungerar som ett elementarkärl som kan reagera kraftigt med vissa förtrollade amuletter."},{t="Den smälta degeln",b="När de nödvändiga amuletterna sänks ner i kitteln sjunker de långsamt mot botten. När blandningen reagerar stiger en stor bubbla genom den trögflytande vätskan och brister. Då visar sig en sjudande klump av smält sten, smidd av de förenade materialen."}},faq={{q="Vad är Essence of the Exile?",a="Essence of the Exile är en mystisk ritual som utförs vid en bubblande kittel. När amuletter läggs i kärlets sjudande djup sker en instabil transmutation som ger en sjudande klump av smält sten.",al={"vad är essence of the exile","questen essence of the exile"}},{q="Vad händer när amuletter läggs i kitteln?",a="Kitteln bubblar och avger ångor som lockar resenärer närmare. När amuletter släpps ner sjunker de långsamt till botten, tills en stor bubbla brister vid vätskans yta och lämnar smält sten efter sig.",al={"vad händer vid kitteln","hur fungerar kitteln"}},{q="Vad framställer kitteln?",a="När amuletterna sjunkit ner i kittelns ångande vätska och en stor bubbla brister vid ytan, visar sig en sjudande klump av smält sten inifrån kärlet.",al={"vad framställs i kitteln","vad får man från essence of the exile"}},{q="Var används kitteln i ritualen?",a="Ritualen äger rum direkt vid en kokande kittel vars heta ångor lockar alla som närmar sig. Kitteln fungerar som ett altare för transmutation.",al={"kittelns plats","var hittar jag kitteln"}},{q="Varför läggs amuletter i kitteln?",a="Amuletterna fungerar som reagenser som förbrukas i kittelns djup. När de sänks ner i den upphettade vätskan sätter de bildandet av den smälta stenen i gång.",al={"vad används amuletterna till","varför läggs amuletter i kitteln"}},{q="Varför bubblar kitteln hela tiden?",a="Den bubblande vätskan och de lockande ångorna tyder på en aktiv och kraftfull kemisk eller elementär reaktion i kärlet, redo att förvandla allt som hamnar i dess djup.",al={"varför bubblar den","vad är ångorna"}}},fp="20,311,20.290.0,19.255.0,33.213.0,52.203.0,31.166.0,43.142.0,40.146.0,40.173.0"}
P.entries["quest:1715"] = {n="The Slaughtered Lamb",s="Det här uppdraget skickar novisa gnomiska häxmästare från Ironforge för att söka avancerad undervisning i människornas rike. Eftersom King Magni Bronzebeard håller mörka utövare under noggrann uppsikt i dvärgarnas berg måste mentorer förlita sig på Stormwinds hemliga nätverk för att slutföra sina lärjungars utbildning.",h="Det här uppdraget skickar novisa gnomiska häxmästare från Ironforge för att söka avancerad undervisning i...",kw={"gakin the darkbinder","gnomeregan","ironforge","lago blackwrench","mage quarter","slaughtered lamb","stormwind","häxmästare"},ang={["class:Warlock"]="Den här resan är en viktig övergångsrit för unga häxmästare i Alliansen och introducerar dem till det hemliga underjordiska nätverk som förenar utövare från olika folkslag.",["race:Dwarf"]="Myndigheterna i Ironforge har noll tålamod med demoniska utsvävningar, vilket driver stadens häxmästare djupt in i skuggorna och tvingar deras elever att söka sig någon annanstans.",["race:Gnome"]="Uppdraget belyser den förnedring som gnomerna utsätts för i exil: de trängs ihop i Ironforge och tvingas förlita sig på människors gästfrihet efter att ha förlorat sina egna akademier i Gnomeregan."},sec={{t="Exil och granskning",b="Före Gnomeregans fall studerade blivande häxmästare i Khaz Modan under sina egna tinker-mager och demoniska lärda djupt inne i teknikstaden. Katastrofen som drev gnomerna i exil skingrade dessa institutioner. De överlevande utövarna fann sig trängda i Ironforges dystra, underjordiska grottor, där de verkade under King Magni Bronzebeards och dvärgagardets misstänksamma blickar. Eftersom de inte kunde utöva demoniska konster öppet eller ägna sig åt farliga ritualer i så trånga utrymmen hade seniora instruktörer som Lago Blackwrench inget annat val än att skicka iväg sina elever."},{t="Mage Quarters hemliga källare",b="Målet för dessa landsflyktiga elever är Slaughtered Lamb, en anspråkslös krog i Stormwinds Mage Quarter. Under serveringen, dold bakom slingrande stengångar och trappor som leder nedåt, ligger en underjordisk helgedom där mänskliga häxmästare samlas i skuggorna. Under ledning av erfarna besvärjare som Gakin the Darkbinder erbjuder platsen utrymmet och de mörka tillbehör som behövs för att lära noviser att frammana och binda mindre demoner utan att genast dra stadsvakternas vrede över sig."},{t="Ökande spänningar i skuggorna",b="Stormwinds häxcirkel välkomnar dugliga händer, men tillströmningen av noviser på flykt skapar friktion. Mänskliga mentorer balanserar redan på en knivsegg för att undvika upptäckt av stadens paladiner och myndigheter. Gakin och hans kollegor märker hur deras hemliga tillflyktsort blir allt trängre av utövare som skickats söderut från Khaz Modan. Den jämna strömmen av resande från dvärgarnas berg riskerar att röja deras diskreta verksamhet, men ingen av sidorna har något enklare alternativ."}},faq={{q="Varför kan inte gnomiska häxmästare utbilda sig i Ironforge?",a="King Magni Bronzebeard håller utövarna i Ironforge under noggrann övervakning. Efter Gnomeregans fall har de fördrivna häxmästarna ingen egen akademi, vilket gör riskfyllda besvärjelseritualer inne i dvärgarnas berg alltför farliga.",al={"varför skicka till stormwind","häxmästarutbildning i ironforge","varför lämnade gnomeregan-häxmästarna"}},{q="Var utbildades häxmästarna i Khaz Modan förr?",a="Förr i tiden utbildades mörka utövare runt om i Khaz Modan under ledning av mästarhäxmästare i Gnomeregan. Trogginvasionen och strålningsförgiftningen utplånade dessa institutioner och tvingade de överlevande till Ironforge.",al={"häxmästarnas historia i gnomeregan","häxmästarutbildning förr i khaz modan"}},{q="Vem är Gakin the Darkbinder?",a="Gakin the Darkbinder är en senior mänsklig häxmästare med bas i katakomberna under Slaughtered Lamb i Stormwind. Han undervisar lärlingar i att binda och frammana demoner, däribland novisa gnomer som skickats söderut från Ironforge.",al={"vem är gakin","gakins roll"}},{q="Vad är Slaughtered Lamb?",a="Slaughtered Lamb är en krog i Stormwinds Mage Quarter. Gatunivån ser ut som en vanlig krog, men den djupa källaren döljer en hemlig enklav av häxmästare som verkar utom synhåll för stadens myndigheter.",al={"slaughtered lamb-krogen","var ligger slaughtered lamb"}},{q="Varför är Gakin frustrerad på nykomlingarna?",a="Gakin oroar sig för att en massiv tillströmning av gnomer på flykt ska dra oönskad uppmärksamhet till den hemliga häxcirkeln i Stormwind. Utrymmet och lärarna är få, och alltför stor aktivitet bland häxmästare riskerar att avslöja dem för stadens myndigheter.",al={"gakin klagar","varför är gakin arg"}},{q="Vem är Lago Blackwrench?",a="Lago Blackwrench är en gnomisk häxmästartränare som håller till i Ironforges mörka gränder. Han är bitter över Gnomeregans fall och dvärgarnas övervakning och skickar lovande noviser till Stormwind för att slutföra sina grundläggande pakter.",al={"lago blackwrench","uppdragsgivare slaughtered lamb"}}},fx={["2a96a15b"]={q="Varför skickar Lago Blackwrench dig till Stormwind?",a="Lago Blackwrench har inget val om du ska kunna utvecklas inom demonisk magi. Sedan Gnomeregans fall tvingade gnomernas utövare att söka sig till Ironforge har King Magni Bronzebeard hållit ett vaksamt och misstänksamt öga på svart magi i sin bergsfästning. Eftersom de inte kan driva egna ordentliga träningshelgedomar under dvärgarnas övervakning måste de landsförvisade trollkarlarna i Ironforge svälja stoltheten och skicka lovande noviser söderut till mänskliga mästare.",al={"varför skicka mig till stormwind","blackwrenchs drivkraft","varför gå till slaughtered lamb"}}},fp="20,214,18.472.0,32.431.0,29.429.0,44.203.0,46.186.0,28.209.0,29.148.0,43.195.0,24.149.0"}
P.entries["quest:1716"] = {n="Devourer of Souls",s="En allianseslock korsar havet för att söka råd hos Takar the Seer om hur man åkallar en succuba. Gakin the Darkbinder skickar Stormwinds noviser till The Barrens för att få den kunskap de behöver.",h="En allianseslock korsar havet för att söka råd hos Takar the Seer om hur man åkallar en succuba.",kw={"camp taurajo","gakin the darkbinder","heartswood","slaughtered lamb","stormwind","succubus","takar the seer","the barrens","häxmästaruppdrag"},ang={["class:Warlock"]="Som slock markerar bindningen av en succuba ett steg mot att bemästra mental manipulation och förförelsemagi. Att nå exotiska ritualreagenser kräver fysiskt mod.",["faction:Alliance"]="Som alliansens magiker reser du djupt in i omstridda Horde-länder, över havet och kontinenten."},sec={{t="En farlig resa västerut",b="Under Slaughtered Lamb i Stormwinds Mage Quarter vägleder Gakin the Darkbinder lovande slockar i hur de åkallar en succuba. Demonen slukar själar, krossar hjärtan och härskar över sinnen, så den får inte åkallas lättvindigt till Azeroth. En slock behöver ett kraftfullt lockbete: ett föremål knutet till ren kärlek. Denna symbol lockar succuban från Twisting Nether, där slocken kan besegra och binda den. Stormwinds coven kan inte lära dem var de hittar ett sådant föremål."},{t="Siaren i fientligt land",b="Gakin skickar sina elever över Great Sea till Kalimdor för att leta efter den nödvändiga katalysatorn. Takar the Seer väntar i det torra The Barrens, nära Hordens bosättning Camp Taurajo. För att nå honom måste en allianseslock ta sig genom vildmark som patrulleras av fientliga kentaurer, quilboar och Hordens krigare. Resan prövar om en åkallare kan överleva innan ritualen ens börjar."}},faq={{q="Vad är syftet med det här uppdraget?",a="Du reser från Stormwind till Kalimdor för att lära dig åkalla och binda en succuba under din fullständiga kontroll.",al={"varför devourer of souls","succubusuppdragets mål","häxmästarens succubusuppdrag"}},{q="Varför måste jag färdas ända till The Barrens?",a="Gakin the Darkbinder skickar dig till The Barrens eftersom Takar the Seer har den ockulta kunskap du behöver för att hitta en symbol för ren kärlek, lockbetet som krävs för att åkalla en succuba.",al={"varför kalimdor","varför resa till the barrens","varför skickas jag så långt bort"}},{q="Vem är Gakin the Darkbinder?",a="Gakin the Darkbinder är en mästerlig åkallare som verkar i katakomberna under The Slaughtered Lamb i Stormwind. Han lär novisa slockar om demoniska pakter, bindningar och mörka konster, långt från stadsvaktens blickar.",al={"gakin the darkbinder bakgrund","vem ger uppdraget devourer of souls"}},{q="Vem är Takar the Seer?",a="Takar the Seer är en mystiker som bor i centrala The Barrens, strax utanför taurenernas utpost Camp Taurajo. Han visar resande slockar vägen till reliker som kan locka demoner in i Azeroth.",al={"var finns takar the seer","takar the seer bakgrund"}},{q="Varför krävs en kärlekssymbol för att åkalla en succubus?",a="En succuba dras till äkta, ren kärlek och slukar den. Som Gakin förklarar fördärvar demonen hjärtan och härskar över sinnen, så en romantisk relik kan locka den från Twisting Nether.",al={"varför kärlek till succubus","succubus lockbete bakgrund","bete för succubus"}},{q="Är The Barrens säkert för en karaktär från alliansen?",a="Nej. The Barrens är Hordens territorium, med fientliga bestar, quilboarstammar och bosättningar som Camp Taurajo. Håll låg profil och undvik vakterna medan du söker efter Takar.",al={"är the barrens farligt","kommer horden att anfalla mig i the barrens"}}},fx={["25fde1fe"]={q="Varför vill Gakin the Darkbinder att det här blir gjort?",a="Gakin the Darkbinder lär dig att kuva farligare demoniska väsen. För att utvecklas som trollkarl måste du tillkalla, besegra och binda en succubus, en grym själsförgörare som härskar över sinnen. Ett sådant väsen kan inte lockas genom Twisting Nether utan ett kraftfullt känslomässigt lockbete. Därför skickar Gakin ut dig på den långa färden för att förbereda betet som behövs för att kuva varelsen och få den i din tjänst.",al={"varför skickar gakin mig","gakins drivkraft och devourer of souls","varför tillkalla succubus åt gakin"}}},fp="17,185,24.470.0,29.370.0,34.109.0,47.173.0,28.216.0,22.188.0,55.186.0,46.168.0"}
P.entries["quest:1717"] = {n="Gakin's Summons",s="En kallelse till lovande allianshäxmästare i Ironforge leder dem söderut till Stormwind. Gakin the Darkbinder väntar under stadens Mage Quarter för att hjälpa dem bemästra mäktigare demoner.",h="En kallelse till lovande allianshäxmästare i Ironforge leder dem söderut till Stormwind.",kw={"gakin","gakins kallelse","ironforge","lago blackwrench","mage quarter","slaughtered lamb","succubus","häxmästare"},ang={["class:Warlock"]="Det här vägledande uppdraget skickar häxmästare i Ironforge tillbaka till Stormwind för att inleda den flerdelade uppdragskedjan där de binder sin succubus som tjänare.",["faction:Alliance"]="Visar hur det hemliga nätverket av häxmästare håller kontakten mellan Alliansens huvudstäder, trots att de utövar demonologi i hemlighet och utom synhåll för civila.",["race:Gnome"]="Gnomhäxmästare som tränar under Lago Blackwrench i Ironforge hänvisas till Stormwinds underjordiska nätverk för att ta del av djupare demonisk kunskap."},sec={{t="Ett meddelande från underjorden",b="Demonologi utövas fortfarande helt i skymundan i Alliansens områden. I Ironforge håller Lago Blackwrench diskret koll på kringvandrande utövare för brödraskapets räkning i Stormwind. När en häxmästare visar tillräcklig kontroll över sina första tjänare sprids ryktet snabbt. Lago förmedlar ordern: lämna det du håller på med i Khaz Modans snöiga berg och bege dig genast söderut."},{t="Återvänd till Slaughtered Lamb",b="Djupt under Stormwinds Mage Quarters kullerstensgator, under värdshuset som kallas The Slaughtered Lamb, samordnar Gakin the Darkbinder stadens häxmästares utveckling. Gakin ser varje skicklig elev som en värdefull men farlig investering. Hans kallelse markerar början på verklig demonisk bindning och på prövningarna som krävs för att kuva en succubus från Twisting Nether."}},faq={{q="Vem skickar mig den här kallelsen?",a="Lago Blackwrench, en häxmästartränare i Ironforge, förmedlar kallelsen på uppdrag av Gakin the Darkbinder, som leder undervisningen i demonologi i Stormwind.",al={"vem ger uppdraget","vem startar det här","lago blackwrench"}},{q="Var hittar jag Gakin the Darkbinder?",a="Gakin gömmer sig i de mörka, vindlande katakomberna under The Slaughtered Lamb, ett värdshus undangömt i Stormwinds Mage Quarter.",al={"gakins plats","var finns gakin","slaughtered lambs plats"}},{q="Varför kallar Gakin på mig?",a="Du har kommit tillräckligt långt i din konst för att genomföra ritualerna som krävs för att frammana och kuva en succubus och utöka din arsenal av demoner.",al={"uppdragets syfte","vad är det här till för","varför kallad"}},{q="Vad händer när jag talar med Gakin?",a="Gakin skickar dig på ett uppdrag som heter Devourer of Souls. Du beger dig till farliga trakter för att skaffa ritualkomponenterna som behövs för att frammana och binda en succubus.",al={"nästa steg","vad händer sedan","uppdragskedja"}},{q="Varför tar en häxmästare i Ironforge order från Stormwind?",a="Alliansens häxmästare bildar av nödvändighet ett diskret, hemligt nätverk. Utövare i Ironforge och Stormwind håller kontakten och hänvisar lovande lärlingar till Gakin, som har specialiserad ritualutrustning och kunskap under Slaughtered Lamb.",al={"häxmästare i ironforge","gnomhäxmästare i stormwind","häxmästarnas organisation"}},{q="Kan jag ignorera kallelsen om jag vill stanna i Khaz Modan?",a="Du kan vänta med att besöka Stormwind, men du kan inte lära dig att frammana en succubus utan att klara Gakins prövning. Resan är nödvändig för alla blivande häxmästare.",al={"är det här nödvändigt","kan jag hoppa över","måste jag åka till stormwind"}}},fx={["27281f2a"]={q="Varför skickar Lago Blackwrench dig till Stormwind?",a="Lago Blackwrench har uttryckliga instruktioner från andra utövare i Stormwind att hålla utkik efter lovande trollkarlar som reser genom Ironforge. Koven har redan investerat mycket tid och resurser i dina mörka konster, och Lago vill se till att du inte går vilse eller omkommer innan du kan utveckla din förmåga under Gakin the Darkbinders vägledning.",al={"varför vill lago få det här gjort","lago blackwrenchs drivkraft","varför skickar lago mig till stormwind"}}},fp="15,239,30.352.0,30.305.0,26.152.0,37.110.0,26.142.0,36.164.0,59.243.0,58.165.0"}
P.entries["quest:1718"] = {n="The Islander",s="The Islander är en inbjudan från veterantränare i krigarkonst runtom i Azeroth till dem som har visat sitt grundläggande kunnande i strid. Den leder blivande krigare till Fray Island utanför The Merchant Coast, där ett isolerat brödraskap av krigare prövar sina jämlikar i rå närstrid. Mötet med hövdingen Klannoc Macleod är ett avgörande steg mot att bemästra avancerade stridsdiscipliner.",h="The Islander är en inbjudan från veterantränare i krigarkonst runtom i Azeroth till dem som har visat sitt...",kw={"fray island","klannoc macleod","the merchant coast","ratchet","the affray","the barrens","the islander","krigare"},ang={["class:Warrior"]="Denna övergångsrit är bara för krigare och markerar det avgörande steget från att lära sig grundläggande manövrer till att frigöra veteranställningarnas fulla ursinne och taktiska mångsidighet.",["faction:Alliance"]="Krigare från Alliansen måste färdas över havet eller genom Kalimdors vildmark för att nå Fray Island. Där visar de sin hängivenhet åt krigskonsten vid en karg gränsbygd, långt från människornas och dvärgarnas fästen.",["faction:Horde"]="Från Thunder Bluff eller Orgrimmar färdas krigare från Horden ner till The Barrens för att bevisa sin styrka bortom hövdingarnas vakande ögon."},sec={{t="En samling klingor",b="Krigartränare i huvudstäder hos både Alliansen och Horden märker när en elev har vuxit ur grundövningarna. Krigisk utveckling kräver att kämpar mäter sig mot verkliga jämlikar, inte formell rang eller politisk lojalitet. Resan för krigarna bort från civiliserade övningsgårdar till en karg ö, isolerad i Stora havet."},{t="Fray Island och The Merchant Coast",b="Fray Island ligger öster om The Merchant Coast, strax söder om goblinhamnen Ratchet i The Barrens. Dit tar man sig genom att simma över sandbankarnas grunda vatten. På denna klippa får politiska band ge vika för krigisk gemenskap. Kämpar samlas under Klannoc Macleods blick, öns hövding, och väntar på vilken brutal prövning han än anser nödvändig."}},faq={{q="Vad är Fray Island?",a="Fray Island är en klippig holme utanför The Merchant Coast i The Barrens, söder om Ratchet. Ön fungerar som en avskild prövningsplats där krigare från hela Azeroth samlas för att vässa sina färdigheter, sparras och möta utmattande stridsprövningar långt från civil myndighet.",al={"var ligger fray island","fray island i berättelsen","fray island"}},{q="Vem är Klannoc Macleod?",a="Klannoc Macleod är krigarnas hövding på Fray Island. Han bedömer hoppfulla utmanare som tar sig till ön och avgör om deras anda och skicklighet förtjänar att ledas vidare längs The Warrior's Path.",al={"vem är klannoc","klannoc macleods roll","macleod krigare"}},{q="Varför skickar tränare från både Horden och Alliansen krigare hit?",a="Sant mästerskap i krigskonst överskrider fraktionsgränser. Mästare bland tränarna i Orgrimmar, Stormwind, Thunder Bluff och Ironforge inser att rå stridsförmåga måste prövas i obändig strid. Fray Island är en outtalad prövningsplats för varje krigare som kan överleva dess utmaningar.",al={"varför går båda fraktionerna hit","är fray island neutral","horden och alliansen på fray island"}},{q="Hur tar du dig till Fray Island från fastlandet?",a="Res söderut längs The Merchant Coast från hamnstaden Ratchet i The Barrens. Från strandlinjen tar du dig genom de grunda sandbankarna och simmar österut över öppet vatten mot ön.",al={"hur tar man sig till fray island","vägbeskrivning till fray island","hitta fray island"}},{q="Vad händer efter mötet med Klannoc Macleod?",a="När Klannoc har bekräftat att du gjort resan och bedömt din beslutsamhet bjuder han in dig att delta i The Affray, en prövning som testar din stridsuthållighet mot vågor av utmanare.",al={"vad kommer efter the islander","klannoc macleods nästa uppdrag"}}},fx={b7452d18={q="Varför skickar krigartränarna dig till Fray Island?",a="Din träning i städerna har tagit dig så långt som vanliga övningar räcker. När ditt rykte växer vet dina mentorer att sann stridskonst inte går att lära sig av övningsdockor eller vänskaplig sparring. De skickar dig till Klannoc Macleod så att du kan mäta din styrka mot verkliga jämlikar från hela världen och visa om du verkligen förtjänar att gå vidare längs The Warrior's Path.",al={"varför skicka mig till fray island","tränarens drivkraft och the islander","varför vill tränaren att jag åker"}}},fp="12,228,21.284.0,34.309.0,20.206.0,23.183.0,64.244.0,47.136.0,43.165.1"}
P.entries["quest:1719"] = {n="The Affray",s="På Fray Island ställs krigare inför ett prov innan Klannoc Macleod tränar dem. I The Affray möter de öns utmanare och deras mästare.",h="På Fray Island ställs krigare inför ett prov innan Klannoc Macleod tränar dem.",kw={"affray","barrens","big will","fray island","klannoc macleod","twiggy flathead","krigarprövning"},ang={["class:Warrior"]="Som krigare ställs du inför The Affray, ett prov på dina stridsställningar och din uthållighet. Bevisar du ditt värde där öppnas vägen till djupare behärskning av ditt hantverk."},sec={{t="En prövning i Great Sea",b="Fray Island ligger avskilt från fastlandet och lockar till sig slagskämpar, utstötta och stridsinstruktörer. Klannoc Macleod lär inte upp varje vandrare som anländer med båt. Krigare som vill träna måste först gå in i The Affray, där uthållighet och uppmärksamhet i strid visar vem som kan kämpa utan att bara skryta."},{t="Järnets och blodets cirkel",b="En krigare inleder The Affray genom att kliva upp på det centrala järngallret bland åskådarna. Ringmaster Twiggy Flathead skickar sedan in utmanare i ringen, en efter en. De som överlever möter öns tungviktsmästare, Big Will. Att besegra honom är det enda sättet att vinna Klannocs respekt."}},faq={{q="Vad är Affray?",a="The Affray prövar krigare som vill träna genom en serie arenakamper på Fray Island. Klannoc Macleod använder provet för att avgöra om de är redo för avancerad stridsträning.",al={"affray-prövning","vad är affray","arena på fray island"}},{q="Var äger Affray rum?",a="The Affray äger rum på Fray Island, utanför The Barrens östkust i Great Sea.",al={"var ligger affray","affrays plats"}},{q="Vem leder prövningen?",a="Krigartränaren Klannoc Macleod håller uppsikt över öns kämpar och utformar provet. Twiggy Flathead leder matcherna från kanten av gropen.",al={"vem leder affray","affrays organisatör"}},{q="Hur går striderna i ringen till?",a="En krigare kliver upp på det centrala järngallret för att visa att hen är redo. Twiggy Flathead skickar in Affray Challengers i gropen i vågor och släpper sedan in öns mästare, Big Will.",al={"hur går striden till","affray-vågor","starta affray"}},{q="Vem är Big Will?",a="Big Will är den regerande mästaren bland Fray Islands slagskämpar. Att besegra honom är det sista kravet för att klara The Affray.",al={"big will","vem är big will","mästare på fray island"}},{q="Varför måste krigare klara den här prövningen?",a="Klannoc Macleod lär inte ut sina kampsportstekniker förrän en krigare har bevisat sin tålighet i strid mot flera motståndare.",al={"varför göra affray","affrays syfte"}}},fx={["0df51000"]={q="Varför kräver Klannoc Macleod att du slåss i stället för att själv sätta dig på prov?",a="Klannoc Macleod slösar inte bort sin avancerade stridsundervisning på varje skrytsam slagskämpe som seglar till Fray Island. The Affray är särskilt utformat som ett uthållighetsprov för krigare på väg uppåt. Genom att kasta in dig i gropen mot vågor av erfarna utmanare och mästaren Big Will kan Klannoc betrakta dig på avstånd och bedöma ditt mod, din förmåga att hantera flera fiender och din uthållighet under verklig press innan han tar dig som elev.",al={"varför jag, klannoc","varför prövar klannoc mig","varför kämpa i the affray"}}},fp="10,145,33.287.0,28.297.0,19.164.0,33.93.0,24.142.0,37.173.0,16.119.0,38.130.0"}
P.entries["quest:173"] = {n="Worgen in the Woods",s="Calor, en desillusionerad före detta vakt i Darkshire, ber äventyrare att rensa Duskwood från de lömska Nightbane Shadow Weavers. Genom att ta jakten till Brightwood Grove och The Rotting Orchard kan främlingar visa vad de går för för Master Jonathan Carevins monsterjägare.",h="Calor, en desillusionerad före detta vakt i Darkshire, ber äventyrare att rensa Duskwood från de lömska...",kw={"brightwood grove","calor","carevin","darkshire","duskwood","nightbane","the rotting orchard","shadow weaver","worgen"},ang={["class:Hunter"]="Jakten på Nightbane sätter spårning och kunskap om bestar på hårda prov, eftersom worgen varken är naturliga djur eller vanliga mänskliga laglösa, utan tvåbenta fasor som brukar skuggmagi.",["faction:Alliance"]="Darkshire känner sig helt övergivet av Stormwinds High Seat, så stadsbor och vaksamma jägare som Calor får värva alla kringvandrande äventyrare från Alliansen som kan hålla monstren tillbaka.",["race:Human"]="För människor från Elwynn eller Westfall är synen av gårdar i Duskwood som gått under, exempelvis The Rotting Orchard, en dyster varning om vad okontrollerad mörk magi kan göra med ett kungarikes spannmålsbodar."},sec={{t="En privat vaktpost",b="The Night Watch kämpar ständigt mot odöda, spindlar och laglösa som tränger mot Darkshires gränser. För vissa, som Calor, var den officiella vakten för långsam och självgod för att rena landet. Calor lämnade The Night Watch bakom sig och slöt sig till Master Jonathan Carevin, vars svärd han ägnade åt att helt utrota kätteri och fördärv. Men Carevin släpper inte in vem som helst i sin krets. Den som vill hjälpa deras sak måste först visa att den kan överleva skogens mest ursinniga fasor."},{t="Nightbane-lurendrejarna",b="Prövningen väntar i Brightwood Grove och det fördärvade The Rotting Orchard, där vilda varglika bestar som kallas worgen härskar. Bland dem använder Nightbane Shadow Weavers mörk magi för att förblinda och snärja sina offer innan de sliter dem i stycken. Calor skickar blivande jägare för att fälla dessa trollkunniga bestar, både för att pröva en främlings beslutsamhet och för att minska ett hot vars ursprung fortfarande oroar Darkshires försvarare djupt."},{t="Monster från ingenstans",b="Även om vargmän blivit en ofrånkomlig mardröm i Duskwood, trotsar deras närvaro alla förklaringar. Calor säger att worgen tycktes dyka upp ur tomma intet, utan någon naturlig härstamning i området. Till skillnad från de glupska vildvargarna eller liken som stigit upp ur traktens gravkullar använder dessa tvåbenta rovdjur bisarra och främmande trolldomar. Att döda Shadow Weavers visar prov på stridskonst, men det skrapar bara på ytan av en onaturlig plåga som får fäste i skogen."}},faq={{q="Vem är Calor?",a="Calor är jägare och tidigare medlem av Darkshires Night Watch. Frustrerad över stadsmilisens försiktiga byråkrati anslöt han sig till Master Jonathan Carevin för att aktivt jaga de vidriga varelser som hotar Duskwood.",al={"calor","calor darkshire","vem ger uppdraget worgen i skogen"}},{q="Varför vill Calor döda Nightbane Shadow Weavers?",a="Calor använder Nightbane Shadow Weavers för att pröva skicklighet och mod. Den som vill hjälpa Master Carevins uppdrag måste visa att den kan jaga farliga trollkunniga worgen, i stället för att bara prata om att försvara staden.",al={"varför döda shadow weavers","målet med worgen i skogen"}},{q="Var hittar man Nightbane Shadow Weavers?",a="De stryker omkring i två huvudområden väster och sydväst om Darkshire: bland de förvridna träden i Brightwood Grove och på The Rotting Orchards övergivna, igenvuxna marker.",al={"var finns nightbane shadow weavers","shadow weavers plats"}},{q="Varifrån kom worgen i Duskwood?",a="Deras plötsliga uppdykande är ett mysterium för folket i Duskwood. Som Calor konstaterar tycktes bestarna materialiseras ur intet och föra med sig mörk skuggmagi och glupsk vrede till en skog som redan står på randen till sammanbrott.",al={"worgens ursprung duskwood","varför finns worgen i duskwood","var kommer worgen ifrån"}},{q="Vem är Master Carevin?",a="Master Jonathan Carevin är en självständig monsterjägare med bas i Darkshire. Han och hans följeslagare verkar utanför The Night Watch och inriktar sig målmedvetet på att utrota ondska, odöda och bisarra vidunder i trakten.",al={"carevin","master carevin","vem är master carevin"}},{q="Varför lämnade Calor The Night Watch?",a="Calor blev desillusionerad av vad han såg som The Night Watchs passivitet och självgodhet. I stället för att bemanna stängsel medan mörkret slöt sig omkring dem föredrog han Carevins aktiva sätt att jaga ondska.",al={"varför lämnade calor vakten","calor night watch"}}},fx={e85e2f18={q="Vad är Nightbane Shadow Weavers?",a="Nightbane Shadow Weavers är trollkunniga worgener som lurar på platser som Brightwood Grove och The Rotting Orchard. Dessa varglika bestar dök plötsligt upp över hela Duskwood och använder mörk magi som hotar Darkshires gränser. Calor och Master Carevin ser deras plötsliga ankomst som en aktiv farsot i skogarna som måste utrotas.",al={"vilka är nightbane shadow weavers","nightbane shadow weaver","vad är worgenerna"}},["5ce72e6e"]={q="Varför behöver Calor att du jagar worgenerna i stället för att göra det själv?",a="Calor har lämnat Night Watch eftersom han blivit desillusionerad av deras likgiltighet och passivitet. Nu tjänar han Master Carevin i deras målmedvetna strävan att rensa Duskwood från kätteri och ondska. Calor förväntar sig att nykomlingar som vill ansluta sig bevisar sig genom handling i stället för tomma ord.",al={"varför skicka mig","varför behöver calor mig","varför inte night watch"}}},fp="19,298,15.405.0,21.363.0,21.468.1,13.196.0,52.184.0,45.156.0,43.216.0,22.207.0,36.197.0"}
P.entries["quest:1738"] = {n="Heartswood",s="Under åren sedan det tredje kriget har Heartswood lockat häxmästare till en gammal tragedi bland nattalver. Takar the Seer skickar dem till Ashenvale för Gakin the Darkbinder, som behöver veden för att locka fram och kuva en succubus i Stormwind.",h="Under åren sedan det tredje kriget har Heartswood lockat häxmästare till en gammal tragedi bland nattalver.",kw={"anathera","ashenvale","barrens","dark strand","gakin the darkbinder","heartswood","latherion","ordil'aran","succubus","takar the seer"},ang={["class:Warlock"]="Som häxmästare behöver du Heartswood för att åkalla och förslava en succubus, vars krafter kan vända dina fienders sinnen mot dem på slagfältet.",["faction:Alliance"]="Som magiker i Alliansen färdas du genom omstridd vildmark och möter fientliga utposter från Horden bland forntida nattalvsruiner i Kalimdor.",["race:Human"]="Som människa kan du förlita dig på avlägsna spanare som Takar the Seer för att hitta reliker från det gamla Kalimdor, bortom det som mänskliga arkanister har dokumenterat."},sec={{t="Ett minnesmärke över tragisk kärlek",b="Takar the Seer säger att Heartswood växte där nattalvförälskade Anathera och Latherion föll under de forntidas krig för tiotusen år sedan. Deras sista andetag och hängivenhet gav näring åt trädet. För dödliga ögon är det ett tecken på tragisk kärlek; för utövare av mörka konster är dess koncentrerade känslor ett kraftfullt magiskt bränsle."},{t="Lockbetet för succubusen",b="Succubi livnär sig på dödligas lidelse, begär och plåga. Takar vet att vanliga lockelser inte kan mäta sig med en relik fylld av tusentals års hängivenhet. En bit Heartswood ger Gakin the Darkbinder den katalysator han behöver för att dra en listig demon genom Nether och in i en åkallelsesirkel i Stormwinds Mage Quarter."},{t="The Ruins of Ordil'Aran",b="Heartswood-trädet växer bland Ruins of Ordil'Aran i nordvästra Ashenvale. Vilda bestar, fientliga marker och Dark Strand-kultister som tagit de alviska ruinerna i besittning står i vägen. När veden väl har hämtats måste den föras över havet till Slaughtered Lamb i Stormwind, där kuvningsritualen börjar."}},faq={{q="Varför behöver häxmästare Heartswood för att åkalla en succubus?",a="Succubi dras till lidelse, begär och starka känslomässiga band. Heartswood växte där två hängivna nattalvförälskade dog tillsammans för tiotusen år sedan, och deras kvarvarande lidelse fyller veden. Därför är den perfekt som bete för att locka en succubus genom Nether.",al={"varför heartswood","lockbete för succubus","varför trä för succubus"}},{q="Var växer Heartswood-trädet?",a="Heartswood-trädet växer i Ruins of Ordil'Aran i nordvästra Ashenvale, inte långt söder om Darkshore. Ondskefulla kultister har tagit kontroll över området.",al={"heartswoods plats","var finns heartswood","var hittar man heartswood"}},{q="Vilka var Anathera och Latherion?",a="Anathera och Latherion var nattalver som stred sida vid sida under de forntidas krig. De föll tillsammans på slagfältet, och Heartswood växte där de drog sina sista andetag och blev ett tecken på deras bestående kärlek.",al={"anathera och latherion","vilka var de älskande","ashenvales älskande"}},{q="Vem är Takar the Seer?",a="Takar the Seer är en mänsklig siare som är allierad med Stormwinds häxmästare. Han lever som eremit i södra Barrens nära Camp Taurajo och använder sin syn för att blicka in i det förflutna och hitta bortglömda reliker åt Gakin the Darkbinder.",al={"vem är takar","takar the seer","eremit i barrens"}},{q="Hur tar sig en häxmästare från Alliansen säkert till Ashenvale från Barrens?",a="Alliansens resenärer som färdas genom The Barrens måste undvika Hordens utpost vid The Mor'shan Rampart, där vakterna håller noggrann uppsikt. Häxmästare kan smita igenom en obevakad öppning strax öster om huvudporten, ta den höga vägen genom Stonetalon eller simma över gränsfloden.",al={"hur tar man sig till ashenvale","förbi mor'shan","undvika hordens mur"}},{q="Vad händer när Gakin får Heartswood?",a="Gakin använder veden för att förbereda en ritual i katakomberna under Slaughtered Lamb i Stormwind. Han ritar en åkallelsesirkel för att dra en succubus från Twisting Nether och ger sedan häxmästaren i uppgift att besegra och kuva henne.",al={"vad händer efter heartswood","vad gör gakin med heartswood"}}},fx={bf8a48f3={q="Varför skickar Takar the Seer dig för att hitta Heartswood?",a="Takar fungerar som en klarsynt allierad till Gakin the Darkbinder och hans krets i Stormwind. Han förberedde sig på din ankomst genom att utforska tidens dimmor med sin mystiska syn och hitta en artefakt som är stark nog att snärja och locka en succubus mellan planen. Inom det hemliga brödraskapet hjälper han blivande häxmästare genom deras prövningar.",al={"takars motiv för heartswood","varför hjälper takar","varför ber takar mig hämta heartswood"}}},fp="10,225,25.321.0,20.325.0,23.309.1,53.262.0,36.158.0,32.219.0,22.218.0,73.260.0,49.231.0"}
P.entries["quest:1739"] = {n="The Binding",s="Warlocks i Stormwind försöker binda en succubus till sin vilja. Under Slaughtered Lamb använder en novis den förtrollade kärnan från Heartswood för att åkalla demonen och besegra den i strid.",h="Warlocks i Stormwind försöker binda en succubus till sin vilja.",kw={"bindning","krypta","darkbinder","gakin","heartswood","slaughtered lamb","stormwind","succubus","åkallandecirkel"},ang={["class:Warlock"]="Som människa eller gnom-warlock markerar den här riten ett steg från att hantera tanklösa imps och voidwalkers till att befalla kännande, beräknande demoner.",["faction:Alliance"]="Som medlem av Alliance får du se hur Stormwind i tysthet tolererar skuggmagi i dolda nischer, trots kyrkans lära."},sec={{t="Nedstigning i kryptan",b="En krypta under Slaughtered Lamb i Stormwinds Mage Quarter skyddar stadens warlocks. Där övar de på förbjudna konster, utom räckhåll för stadsvakten och Cathedral of Light. Stensatta åkallandecirklar leder in kraft från Nether och låter noviser nå genom slöjan mellan världarna."},{t="Att kuva förförerskan",b="En warlock behöver den förberedda Heartswood Core för att åkalla en succubus. Ritualen öppnar en reva vid åkallandecirkeln, men demonen kan korrumpera och övermanna även ett befäst sinne. För att bemästra den måste warlocken besegra den i envig. Dess fysiska gestalt återvänder till Twisting Nether, medan dess sanna band säkras."},{t="Gakins hemligheter",b="Efter att ha dödat den åkallade varelsen tar novisen den uttömda kärnan tillbaka till Gakin the Darkbinder. Gakin lär sedan ut kunskapen som krävs för att kalla succubusen genom tomrummet. Riten markerar hur en warlock i Alliance utvecklas till en adept som anförtros att hantera oberäkneliga, kännande demoner."}},faq={{q="Var sker åkallandet?",a="Åkallandet sker i katakomberna under Slaughtered Lamb, en krog i Stormwinds Mage Quarter. Spiraltrappor leder förbi krogens källare till en underjordisk helgedom med magiska åkallandecirklar.",al={"var åkallar jag","plats för att åkalla succubus","kryptans plats"}},{q="Vad är syftet med Heartswood Core?",a="Heartswood Core förankrar och driver åkallandet. Den kommer från Heartswood, ett träd som växte där två nattalvsälskande dog i Ashenvale under War of the Ancients. Kärnan bär på den andliga resonans som krävs för att öppna en reva och dra en succubus genom Twisting Nether.",al={"varför heartswood core","vad gör heartswood"}},{q="Varför måste warlocken döda succubusen?",a="En warlock måste döda succubusen för att hävda sin makt över den. Succubi använder manipulation och mental kuvning, och att låta en manifestera sig utan att besegra den leder till fördärv. Striden präglar anden med warlockens auktoritet innan den åter tar form i Nether.",al={"varför slåss jag mot succubusen","varför döda demonen för att binda den"}},{q="Vem är Gakin the Darkbinder?",a="Gakin the Darkbinder är en högt uppsatt warlock som bor i Slaughtered Lamb och ansvarar för träningen av Alliance-utövare i Stormwind. Han ordnar den hemliga anskaffningen av demonologiska artefakter och bedömer om akolyterna har viljan att befalla demoner.",al={"vem är gakin","gakin darkbinder berättelse"}},{q="Vem är Surena som Gakin nämner?",a="Surena Caledon var Gakins tidigare elev. Hon rymde med Defias, och du återfann hennes halsband tidigare. Gakin undrar torrt om hon var en succubus i förklädnad som skickats för att förvrida hans sinne, men kommer sedan fram till att han ger henne för mycket ära.",al={"surena-referens","vem var surena"}},{q="Är succubi tillåtna på Stormwinds gator?",a="Church of the Holy Light och rikets myndigheter förbjuder strikt öppen demonologi. Bundna demoner kan följa med warlocks genom staden, men i berättelsen sker detta i skuggorna, källare och avskilda helgedomar som kryptorna under Slaughtered Lamb.",al={"kan vakterna se min succubus","är demonåkallande lagligt i stormwind"}}},fx={["69ec55c9"]={q="Varför vill Gakin the Darkbinder att det här ska göras?",a="Gakin prövar din disciplin och skicklighet som blivande häxmästare. Han vill försäkra sig om att du har viljestyrkan att böja demoniska krafter under din vilja i stället för att falla för deras bedrägerier. Genom att visa att du kan besegra en frammanad demon under värdshuset bevisar du att du förtjänar att lära dig binda och kontrollera en succubus för gott.",al={"varför vill gakin detta","gakins motiv","varför frammana succubus åt gakin"}},["2be029b1"]={q="Vad är succubusen som du ska frammana?",a="Du frammanar en succubus, en förförisk och listig demon från Twisting Nether. Succubier är kända för att manipulera begär och överväldiga även beslutsamma sinnen. Den finns inte naturligt i Stormwind; din besvärjelse och Heartswood Core river upp en lokal reva särskilt för att dra fram varelsen, så att du kan besegra den och förslava dess väsen.",al={"vad är succubusen","vem är målet i the binding","frammanad succubus"}},f36093f2={q="Varför låter Gakin dig frammana succubusen i stället för att göra det själv?",a="En demon kan inte bindas till att tjäna en annan häxmästare; tjänstepakten kräver att den som frammanar varelsen själv betvingar den. Gakin behärskar redan sina egna mörka konster. För att kalla succubusen som din tjänare måste du själv möta faran, visa att du kan stå emot dess lockelser och binda dess vilja till din.",al={"varför måste jag frammana succubusen","varför jag i the binding","varför kan inte gakin slåss mot succubusen"}}},fp="11,188,22.291.0,26.323.0,15.283.1,36.206.0,43.278.0,39.271.0,28.254.0,34.229.0,50.257.0"}
P.entries["quest:174"] = {n="Look To The Stars",s="Look To The Stars inleder Viktori Prism'Antras försök att blicka bortom Duskwoods kusliga trädkronor. Han tror att skogens mörka förbannelse har en vetenskaplig förklaring bortom vidskepelse och värvar dig för att samla delar till ett teleskop som hans gnomiska medhjälpare har konstruerat.",h="Look To The Stars inleder Viktori Prism'Antras försök att blicka bortom Duskwoods kusliga trädkronor.",kw={"bronsrör","cog","darkshire","duskwood","look to the stars","teleskop","viktori prism'antras"},ang={["faction:Alliance"]="Medan Night Watch-patruller håller fasorna borta från vägarna kring Darkshire är Viktoris projekt stadens lilla, envetna hopp om att förstå vad som förgiftat deras hem.",["profession:Engineering"]="Hela företaget hänger på gnomisk konstruktion och skickligt metallarbete, vilket ger hantverkare en direkt roll i Viktoris astronomiska strävanden.",["race:Gnome"]="Viktori förlitar sig på sin gnomiska medhjälpare Cogs uppfinningsrikedom och visar hur gnomiskt hantverk för med sig ordning och förnuft även till rikets mörkaste hörn."},sec={{t="På jakt efter stjärnorna",b="Mitt i det mörker och den rädsla som omger Darkshire har Viktori Prism'Antras en högst okonventionell syn på Duskwoods olycka. I stället för att skylla landets fördärv enbart på svartkonst, förbannelser eller rastlösa döda misstänker Viktori att större sanningar väntar högt ovanför trädkronorna. Med hjälp av ritningar från sin gnomiska partner Cog ger han sig i kast med att bygga ett optiskt instrument som kan skåda himlen."},{t="En fråga om ingenjörskonst",b="För att börja bygga stjärnskådningsapparaten behöver Viktori en stadig stomme. Enligt Cogs specifikationer ber han resande att skaffa ett bearbetat bronsrör. Det första steget bygger på dödliga mekanikers uppfinningsrikedom snarare än trollkonst och visar hur envist Viktori håller fast vid tanken att praktiskt hantverk och observationer kan kasta ljus där mystiken har misslyckats."}},faq={{q="Vem är Viktori Prism'Antras?",a="Viktori Prism'Antras är en lärd invånare i Darkshire. Till skillnad från många ortsbor som lamslås av rädsla eller slukas av vidskepelse söker han rationella förklaringar till det fördärv som sprider sig över Duskwood genom att studera stjärnorna.",al={"viktori","vem ger uppdraget look to the stars","viktori prism'antras"}},{q="Varför vill Viktori bygga ett teleskop?",a="Viktori tror att det finns en påtaglig sanning bortom magin som förklarar Duskwoods märkliga förvandling. Han hoppas att himlen ska avslöja insikter genom teleskopet som lokala sägner och magiker har förbisett.",al={"varför titta på stjärnorna","varför bronsrör i duskwood","teleskopuppdrag darkshire"}},{q="Vem är Cog?",a="Cog är en gnomisk ingenjör och vän till Viktori. Han ritade de mekaniska ritningar som behövs för att bygga stjärnskådningsapparaten.",al={"cog gnom","vem konstruerade teleskopet"}},{q="Var får man tag på ett bronsrör?",a="Ett bronsrör tillverkas vanligtvis av ingenjörer med viss erfarenhet. Resande som inte själva är ingenjörer skaffar ofta ett genom handel, auktionshus eller kringresande försäljare av ingenjörsvaror som råkar ha några i lager.",al={"hur får man tag på bronsrör","bronsrörets plats","var hittar man bronsrör"}},{q="Är det här en del av en längre uppdragskedja?",a="Ja. Det här uppdraget är första steget i ett större försök att montera och kalibrera Viktoris stjärnskådningsapparat i Darkshire.",al={"look to the stars uppdragskedja","hur många look to the stars-uppdrag finns det"}},{q="Varför söker Viktori naturliga förklaringar till det som händer i Duskwood?",a="Trots att skogen kryllar av odöda och mörka förtrollningar tror Viktori att grundläggande kosmiska eller naturliga lagar fortfarande kan styra förvandlingen. Därför söker han svar genom att studera himlakropparna.",al={"varför vetenskaplig förklaring till duskwood","magi mot vetenskap i duskwood"}}},fx={["45e6e811"]={q="Vad används bronsröret till?",a="Bronsröret utgör den bärande kroppen till teleskopet som Viktori Prism'Antras bygger. Enligt ritningarna från hans gnompartner Cog blir metallhöljet det nödvändiga fäste där linserna monteras och instrumentet riktas mot himlen.",al={"vad används bronsröret till","varför behöver viktori ett bronsrör","viktoris syfte med bronsröret"}}},fp="17,219,19.335.0,23.250.0,28.132.0,43.140.0,11.92.0,36.163.0,35.101.0,60.158.0"}
P.entries["quest:1740"] = {n="The Orb of Soran'ruk",s="I södra Barrens samlar Doan Karhan in spridda delar av Soran'ruk med hjälp av häxmästare. De vill återställa en klotformad artefakt som rymmer en vanärad demons väsen.",h="I södra Barrens samlar Doan Karhan in spridda delar av Soran'ruk med hjälp av häxmästare.",kw={"blackfathom","demon","doan karhan","orb of soran'ruk","orb of zargain","shadowfang","soranruk","häxmästare"},ang={["class:Warlock"]="Att återställa Soran'ruk är en viktig milstolpe för dig som häxmästare. Det lär dig hur Legion håller sina egna i schack och hur bundna demoner kan utnyttjas i fungerande redskap.",["faction:Horde"]="Som medlem av Horde kan du hitta Doan Karhan i det karga södra Barrens. Besvärjare på resa kommer till dessa slätter för att söka avancerad mörk kunskap."},sec={{t="Den vanärades kärl",b="Ett misslyckande inom Burning Legion leder till ett evigt straff. När mindre demoner förlorar sina herrars gunst binds deras andar i kristallklot. Legion ger dessa fängelser till dödliga besvärjare och häxmästare som kraftkällor under demonisk kontroll. Att krossa ett klot befriar inte dess fånge; även skärvorna rymmer mäktig magi."},{t="Spridd över kontinenterna",b="Soran'ruks klot ligger i bitar på två kontinenter. Twilight's Hammer-kultister håller mindre fragment i de fuktiga grottorna i Blackfathom Deeps i Ashenvale. En magiker i de hemsökta ruinerna av Shadowfang Keep i Silverpine Forest gjorde anspråk på den större, till största delen intakta halvan. Doan Karhan har ägnat sitt liv åt att studera Legion-klot och har tidigare satt ihop Orb of Zargain. Med de återfunna bitarna kan han återställa Soran'ruk till ett fungerande redskap."}},faq={{q="Vad är Orb of Soran'ruk?",a="Soran'ruk var en demon från Burning Legion som föll i onåd. Enligt demonisk sed fängslades dess ande i ett magiskt klot och gavs till dödliga utövare. Klotet krossades senare, men dess fragment rymmer fortfarande demonens kraft.",al={"soranruk-lore","vad är soranruk","vem var soranruk"}},{q="Vem är Doan Karhan?",a="Doan Karhan är en tillbakadragen häxmästare som bor i södra Barrens och har ägnat sitt liv åt att studera och återställa Burning Legions klot. Han tillbringade många år med att sätta ihop Orb of Zargain och hjälper nya häxmästare att foga samman Soran'ruk.",al={"vem är doan karhan","doan karhans bakgrund"}},{q="Varför finns klotets delar i två olika grottor?",a="Klotet delades i två huvuddelar. Twilight's Hammer-kultister håller mindre fragment i Blackfathom Deeps, medan en trollkarl gjorde anspråk på den större återstoden i Shadowfang Keep.",al={"varför finns delar i bfd och sfk","var finns soranruks fragment"}},{q="Vem kan utföra uppdraget?",a="Häxmästare som vill utveckla sitt hantverk och bemästra artefakter skapade av fängslade demonandar kan genomgå denna ritual.",al={"vem kan göra uppdraget","är orb of soran'ruk bara för häxmästare"}},{q="Vad gör Doan Karhan med de återfunna fragmenten?",a="Doan Karhan studerar de återfunna fragmenten för att fördjupa sin forskning om Legion-reliker och bygger sedan ihop dem till ett magiskt redskap som häxmästaren själv väljer form på.",al={"vad händer efter att skärvorna samlats in","återskapa soranruk"}},{q="Vad är Orb of Zargain?",a="Orb of Zargain är ett fängelse för en demon från Legion som föll i onåd. Doan Karhan spårade upp det och ägnade många år åt att återställa det för eget bruk.",al={"orb of zargain","zargains bakgrund"}}},fx={f1114029={q="Varför vill Doan Karhan ha fragmenten av Orb of Soran'ruk?",a="Doan Karhan har vigt sitt liv åt att studera de demoniska klot som Burning Legion smidde och att bemästra konsten att återskapa dem. När han återfår de utspridda skärvorna av Orb of Soran'ruk kan han själv undersöka kärlet som håller en vanärad demons ande fången och omsätta sin omfattande forskning i praktiken.",al={"varför vill doan karhan ha klotet","doan karhans motiv","varför samla fragmenten"}},["32900559"]={q="Vad är Soran'ruk Fragment?",a="Soran'ruk Fragment är små skärvor från det krossade Orb of Soran'ruk, ett kärl som håller anden från en demon som förlorade Burning Legions gunst. Twilight's Hammers kultister bar skärvorna till Blackfathom Deeps för att utnyttja deras kvarvarande demoniska kraft.",al={"vad används soran'ruk fragment till","vad är soran'ruk fragment","fragmenten i blackfathom deeps"}},["321416b0"]={q="Vad är Large Soran'ruk Fragment?",a="Large Soran'ruk Fragment är den största återstående delen av Orb of Soran'ruk. Den innehåller tillräckligt koncentrerat demoniskt väsen för att en mörk trollkarl i Shadowfang Keeps hemsökta salar skulle göra anspråk på den och använda den för sina egna besvärjelser.",al={"large soran'ruk fragment","fragment i shadowfang keep","vad används det stora fragmentet till"}},["120120b9"]={q="Vem har klotets fragment?",a="Fragmenten delades mellan två farliga grupper som sökte demonisk kraft. De mindre skärvorna hamnade hos Twilight's Hammers akolyter, som smider planer under vågorna i Blackfathom Deeps, medan den större återstoden togs av en listig trollkarl som håller till inne i Shadowfang Keep.",al={"vem har fragmenten","var finns soran'ruks delar","vem har klotets delar"}}},fp="20,163,24.344.0,27.439.0,29.240.0,19.246.0,52.173.0,28.119.0,54.163.0,27.159.0"}
P.entries["quest:175"] = {n="Look To The Stars",s="Efter att ha fått ritningarna av uppfinnaren Cog söker Viktori Prism'Antras en reflekterande yta för att bygga sitt observatorieteleskop i Darkshire. Han hänvisar resande till södra Duskwood för att leta efter Mary, en kvinna i trakten som är ihågkommen för att alltid bära en spegel.",h="Efter att ha fått ritningarna av uppfinnaren Cog söker Viktori Prism'Antras en reflekterande yta för att...",kw={"blind mary","darkshire","duskwood","se mot stjärnorna","spegel","mary","teleskop","tranquil gardens","viktori prism'antras"},ang={["faction:Alliance"]="Att hjälpa Viktori att bygga sitt teleskop ger en sällsynt strimma av nyfikenhet och framsteg i en stad som annars slukas av skräck och förruttnelse.",["profession:Engineering"]="Teleskopet byggs enligt exakta optiska specifikationer och använder gnomiska ritningar för att spegla och förstora det svaga stjärnljuset."},sec={{t="En reflekterande yta",b="När Viktori Prism'Antras har skaffat ett bronsrör till sitt teleskop vänder han sig till nästa krav i Cogs ritningar: en tillförlitlig spegel som kan leda och reflektera ljus genom apparaten. I stället för att smälta fint, silverbelagt glas från grunden medan Darkshire lider av brist på förnödenheter, minns Viktori Mary, en invånare i trakten som är känd i hela regionen för att alltid bära en spegel."},{t="Sökandet i söder",b="Marys tidigare hem ligger djupt i södra Duskwood, strax norr om den hemsökta Tranquil Gardens Cemetery. För att leta efter henne måste äventyrare passera Night Watchs trygga patrullgränser och ta sig in bland fördärvade dungar fulla av glupska vargar, vilda spindlar och vandrande odöda."},{t="En tragisk invånare",b="När du når Marys enkla skjul i söder blir Duskwoods dystra fall tydligt. Kvinnan som Viktori mindes är inte längre en levande invånare, utan Blind Mary, en kringirrande ande som dröjer sig kvar nära sitt gamla hem och den närliggande kyrkogården, bunden till minnena och ägodelarna från sitt tidigare liv."}},faq={{q="Vad bygger Viktori Prism'Antras?",a="Viktori bygger ett astronomiskt teleskop i sin stuga uppe på kullen i Darkshire, efter ritningar som uppfinnaren Cog har tagit fram.",al={"viktoris teleskop","projektet se mot stjärnorna","vad bygger viktori"}},{q="Varför behöver Viktori en spegel?",a="Cogs optiska ritningar kräver en spegel som reflekterar och fokuserar ljuset genom teleskopets hölje. Viktori minns att Mary brukade bära en spegel och hoppas kunna få tag på den till bygget.",al={"varför behövs en spegel","reflekterande yta teleskop"}},{q="Var hittar man Mary?",a="Mary håller till i ett förfallet hus i sydöstra Duskwood, strax norr om Tranquil Gardens Cemetery.",al={"var finns mary","marys plats duskwood","hitta blind mary"}},{q="Vem är Mary?",a="Mary bodde i södra Duskwood innan landet föll i förhäxad mörkermakt och var välkänd i Darkshire för att alltid bära en spegel. Vad som hände henne får du upptäcka vid hennes gamla hem nära Tranquil Gardens Cemetery.",al={"vem är blind mary","blind marys bakgrund"}},{q="Har Mary fortfarande sin spegel?",a="När du närmar dig bekräftar Mary att hon en gång ägde en spegel, men att hon inte längre har den. Hon kan bara visa dig vart den tog vägen.",al={"har mary en spegel","blind marys spegel"}},{q="Vilka faror finns kring Marys stuga?",a="Skogarna i sydöst och den intilliggande Tranquil Gardens Cemetery kryllar av fientliga odöda, vilda skymningsfladdermöss, giftiga nätspindlar och rabiata vargar som jagar resande som vågar sig söder om Darkshire.",al={"faror nära mary","hot vid tranquil gardens cemetery"}}},fx={["9372b916"]={q="Varför är Viktori Prism'Antras så inriktad på att färdigställa sitt teleskop?",a="Viktori Prism'Antras är helt uppslukad av sin ambition att färdigställa ett astronomiskt teleskop i sin hydda i Darkshire. Efter ritningarna från gnomen Cog behöver han specialdelar för att reflektera och fokusera ljus. Han hoppas kunna se bortom det ständiga mörker som täcker Duskwood, och varje svårfunnen del behövs för att få hans storslagna konstruktion att fungera.",al={"varför vill viktori att detta görs","viktori prism'antras motiv","varför bygga teleskopet"}}},fp="17,196,20.311.0,19.239.0,17.208.1,38.123.0,38.168.0,24.88.0,12.222.1,39.108.1,37.172.0"}
P.entries["quest:1758"] = {n="Tome of the Cabal",s="Ovanför Ratchet skickar Strahad Farsan en blivande Alliance-trollkarl till biblioteket i Ironforge. En feljägares hunger kan överväldiga en oförberedd besvärjare, och Tome of the Cabal innehåller kunskapen som behövs för att frammana och binda demonen.",h="Ovanför Ratchet skickar Strahad Farsan en blivande Alliance-trollkarl till biblioteket i Ironforge.",kw={"feljägare","hall of explorers","ironforge","krom stoutarm","ratchet","strahad farsan","tome of the cabal","häxmästare"},ang={["class:Warlock"]="Som trollkarl är det ett mandomsprov på vägen mot mästerskap över feljägare att få tag i Tome of the Cabal. Det tar dig bortom enklare tjänare och in i antimagisk demonologi.",["faction:Alliance"]="Som Alliance-utövare färdas du tillbaka från Kalimdors utmarker till Hall of Explorers i Ironforge för att söka efter förbjudna mörka texter.",["race:Dwarf"]="Som dvärg ser du att inte alla som håller till i Hall of Explorers gräver fram titanartefakter; Krom Stoutarm sammanställer i hemlighet demonisk kunskap."},sec={{t="Ett vidunder som livnär sig på magi",b="En imp, en voidwalker eller en succubus kan kuvas genom ritualer, men en feljägare innebär en annan fara. Feljägare tjänar Burning Legion och jagar arkan energi för att sluka den. En vanlig frammaningscirkel faller samman inför en sådan, som dränerar besvärjarens magi innan en bindning kan få fäste. Från sitt gömställe i The Barrens vakar Strahad Farsan över Ratchet och vet att en amatör inte får försöka binda en utan förberedelser."},{t="Den första bindningen",b="En akolyt behöver de arkana formlerna i Tome of the Cabal för att tryggt frammana och binda en feljägare. Det första dödliga krigarkotteri av trollkarlar som lyckades kuva en feljägare utan hjälp utifrån skrev manuskriptet. Dess sidor beskriver geomantin, materialet och bindningsrunorna som krävs för att stå emot varelsens hunger. Exemplaret försvann för länge sedan och lämnade Strahad och hans krets utan mästerverket."},{t="Dun Moroghs samlare",b="Strahad skickar Alliance-trollkarlar över Great Sea till Hall of Explorers i Ironforge, eftersom han inte själv kan tillhandahålla texten. Krom Stoutarm, en kringvandrande dvärgtrollkarl, bor där och ägnar sina sista år åt att gå igenom gamla manuskript och biblioteksregister. Om något spår av det förlorade grimoaret finns nedtecknat i Eastern Kingdoms, ligger det begravt i Kroms noggranna kataloger."}},faq={{q="Varför behöver jag hitta Tome of the Cabal?",a="Tome of the Cabal innehåller exakta instruktioner från de första dödliga trollkarlarna som framanade och kuvade en feljägare utan hjälp utifrån. Vanliga frammaningsritualer kan inte fånga en demon som aktivt livnär sig på magisk energi.",al={"vad är tome of the cabal","varför hitta boken","syftet med tome of the cabal"}},{q="Vem är Krom Stoutarm?",a="Krom Stoutarm är en kringvandrande dvärgtrollkarl som bor i biblioteket i Hall of Explorers i Ironforge. Han tillbringar dagarna bland dammiga böcker och katalogiserar gamla historiska dokument.",al={"var finns krom","vem är krom stoutarm","krom i ironforge"}},{q="Varför är Strahad Farsan i The Barrens?",a="Strahad Farsan är en erfaren mänsklig trollkarl med ett stillsamt, neutralt gömställe på klipporna ovanför Ratchet. Bortom Kirin Tors och Stormwinds myndigheters vakande ögon tränar han både Alliance- och Horde-utövare i avancerad demonologi.",al={"strahads plats","varför ratchet","vem är strahad"}},{q="Vad händer när jag talar med Krom Stoutarm?",a="Krom Stoutarm minns hänvisningar till boken i gamla katalogregister. Han ber dig spåra upp dess förlorade delar och hämta de sällsynta reagenser som behövs för att återskapa grimoaret.",al={"nästa uppdrag","efter krom","nästa steg i tome of the cabal"}},{q="Kan hordens häxmästare göra det här uppdraget?",a="Resan till Ironforge är avsedd för Alliance-trollkarlar. Strahad ger Horde-trollkarlar en likvärdig uppgift och skickar dem för att söka upp kunniga kontakter inom Horde-territorium.",al={"hordens version","är det bara för alliansen"}},{q="Vilken demon låser den här uppdragskedjan upp?",a="När du slutför Tome of the Cabal-uppdragskedjan väntar en rituell strid mot en frammanad feljägare. Trollkarlen lär sig att frammana och binda en sådan som en permanent tjänare.",al={"vilken demon","uppdrag med feljägare","vilket husdjur får jag"}}},fx={["8ce24f0c"]={q="Varför vill Strahad Farsan att jag hittar Tome of the Cabal?",a="Strahad Farsan vägleder dig i din utveckling som häxmästare och förbereder dig på att befalla en av Nether mest glupska rovdjur: en feljägare. Att frammana en sådan best kräver invecklade och farliga ritualer som går långt utöver vanliga magiska cirklar. Den förlorade Tome of the Cabal innehåller de ursprungliga riterna som de första häxmästarna utformade när de band en feljägare utan hjälp. Strahad och hans akolyter står redo att väva frammaningscirklarna ovanför Ratchet, men ritualen kan inte inledas säkert utan den särskilda kunskap som finns bevarad i Tome.",al={"varför vill strahad ha tome","strahad farsans motiv","strahads skäl till tome of the cabal"}},["327d5815"]={q="Varför skickar Strahad mig i stället för att hämta Tome själv?",a="Att kuva en demonisk tjänare är en djupt personlig prövning som sätter din påhittighet och beslutsamhet på prov. Strahad tillhandahåller kunskapen, ritualplatsen och akolyterna som förankrar magin, men ansvaret för att få tag i den nödvändiga kunskapen vilar helt på dig. Strahad är dessutom kvar ovanför Ratchet och hanterar farliga arkana krafter, medan du kan resa fritt till Hall of Explorers i Ironforge, rådfråga lärda som Krom Stoutarm och själv återfinna de utspridda relikerna.",al={"varför skickar strahad mig","varför kan inte strahad hämta tome","varför skicka spelaren till ironforge"}}},fp="17,237,27.435.0,17.410.0,25.404.0,44.225.0,21.197.0,37.252.0,44.192.1,33.168.0,38.154.0"}
P.entries["quest:176"] = {n="Wanted: \"Hogger\"",s="Wanted: \"Hogger\" är en alliansbelöning på en efterlysningsaffisch utanför Goldshire. Den utlovas för huvudet av en väldig, vild gnollhövding. Hogger stryker omkring i de sydvästra skogarna i Elwynn Forest och har med våld slagit tillbaka varje försök från de lokala myndigheterna att fånga honom.",h="Wanted: \"Hogger\" är en alliansbelöning på en efterlysningsaffisch utanför Goldshire.",kw={"belöning","dughan","elwynn","forest's edge","gnoll","goldshire","hogger","efterlyst"},ang={["faction:Alliance"]="Att fälla Hogger ses som ett mandomsprov för unga allianshjältar som vill visa sitt mod när de försvarar Stormwinds hjärtland.",["race:Human"]="För människorna i Elwynn innebär det att döda Hogger att gårdarna och handeln längs vägarna, som terroriserats av gnollöverfall i månader, blir trygga igen."},sec={{t="Ett hot i skogen",b="Medan Elwynn Forest kämpar mot banditer och koboldangrepp har gnollstammarna i söder blivit djärvare och mer organiserade under den råbarkade Hoggers ledning. Hogger är mycket större än vanliga Riverpaw-gnoller. Han har slagit läger nära Forest's Edge, där han överfaller resenärer och övermannar de lokala milispatruller som skickas för att kuva honom."},{t="Goldshires desperation",b="Stormwind-armén är hårt ansträngd och kan inte avvara reguljära styrkor för att patrullera huvudstadens utkanter. Därför tog Marshal Dughan det ovanliga steget att utlysa en öppen belöning för odjuret. För att fälla Hogger måste man ta sig in på djupt fientligt gnollterritorium. Hans grymhet har gjort honom till det dödligaste hotet mot nyblivna äventyrare i Elwynn."}},faq={{q="Vem är Hogger?",a="Hogger är en ovanligt stor och vild gnollhövding som terroriserar sydvästra Elwynn Forest. Han styr de lokala flockarna runt Forest's Edge och har med våld slagit tillbaka alla tidigare försök från Stormwinds vakter att fånga eller döda honom.",al={"vem är hogger","hoggers bakgrund","vad är hogger"}},{q="Var finns Hogger?",a="Hogger strövar omkring bland gnollernas läger i sydvästra Elwynn Forest, nära de södra gränstrakterna som kallas Forest's Edge, strax norr om flodgränsen mot Westfall och Duskwood.",al={"hoggers plats","var finns hogger","hitta hogger"}},{q="Varför har en belöning utlysts för Hogger?",a="Stormwind-armén utlyste en belöning för Hogger eftersom han har övermannat lokala patruller och utgör en dödlig fara för resenärer. Eftersom rikets reguljära trupper är hårt ansträngda vände sig Marshal Dughan till fristående äventyrare och prisjägare för att undanröja hotet.",al={"varför döda hogger","efterlysningsaffisch för hogger","vem utlyste belöningen för hogger"}},{q="Vem tar emot beviset på Hoggers död?",a="Beviset på odjurets död, hans Huge Gnoll Claw, måste lämnas direkt till Marshal Dughan, som leder den lokala garnisonen i Goldshire.",al={"lämna in hogger","var lämnar man in hogger","vem vill ha hoggers klo"}},{q="Varför är Hogger farligare än andra gnoller?",a="Till skillnad från de vanliga gnollerna som stryker omkring i Elwynn är Hogger enormt stor och brutal. Han slår betydligt hårdare och tål mycket mer stryk. Ofta övermannar han ensamma kämpar som underskattar honom.",al={"är hogger stark","varför är hogger elit"}},{q="Varför kan inte Stormwinds vakter ta hand om Hogger själva?",a="Rikets militära resurser är kraftigt uttömda och upptagna med att försvara viktiga gränser eller söka efter den försvunne kung Varian Wrynn. Marshal Dughans lilla truppstyrka i Goldshire har inte tillräckligt med manskap för att säkert jaga ner ett så uthålligt monster.",al={"varför dödar inte dughan hogger","var är stormwind-armén"}}},fx={fccb34f1={q="Vad används Huge Gnoll Claw till?",a="Huge Gnoll Claw är ett obestridligt bevis på Hoggers död. Eftersom besten har övermannat alla försök att fånga den kräver Marshal Dughan och Stormwind Army otvetydiga fysiska bevis innan de betalar ut den utlovade belöningen.",al={"huge gnoll claw","varför behöver jag hoggers klo","vad används hoggers klo till"}}},fp="16,253,21.347.0,23.369.0,14.234.0,26.184.0,32.274.0,41.151.0,52.226.0,56.251.0"}
P.entries["quest:177"] = {n="Look To The Stars",s="Det här uppdraget skickar äventyrare för att återta Blind Marys bortkastade spegel åt astronomen Viktori Prism'Antras. Den ömtåliga spegeln hamnade hos en Insane Ghoul som strövar omkring på den öde Tranquil Gardens Cemetery i södra Duskwood.",h="Det här uppdraget skickar äventyrare för att återta Blind Marys bortkastade spegel åt astronomen Viktori...",kw={"blind mary","cog","darkshire","insane ghoul","look to the stars","mary's looking glass","teleskop","tranquil gardens cemetery","viktori prism'antras"},ang={["class:Priest"]="Präster som vandrar på den fördärvade marken vid Tranquil Gardens Cemetery bevittnar den fasansfulla vanära som drabbat Duskwoods döda, där stupade bybor förvandlats till vansinniga asätare.",["faction:Alliance"]="Att återta förlorade reliker från staden ur glupska odödaz händer visar Duskwoods folks bittra öde: övergivna vid Stormwindrikets farliga utkanter.",["profession:Engineering"]="Ingenjörer kan uppskatta Viktoris improviserade optiska mekanik, där vanliga polerade handspeglar förvandlas till reflekterande delar i ett astronomiskt instrument."},sec={{t="En relik från bättre dagar",b="Innan det krypande mörkret svepte över Duskwood och förvandlade henne till en gråtande ande, höll Blind Mary en utsmyckad spegel kär. Efter den fasansfulla händelsen som tog hennes syn och förstånd kastade hon minnessaken i jorden bakom familjens lada. Den reflekterande spegeln är precis vad Viktori Prism'Antras behöver för att bygga sitt storslagna teleskop i Darkshire, men den stals och försvann i skuggorna långt innan astronomen drömde om att studera himlavalvet."},{t="Kyrkogårdens asätare",b="En Insane Ghoul rotade fram spegeln bakom de förstörda gårdarna. Den eländiga odöda varelsen drevs söderut av en rastlös hunger och bar spegeln till Tranquil Gardens Cemetery, där den hemsöker ett övergivet kapell bland de igenvuxna gravstenarna. För att återta den ömtåliga linsen måste du ta dig fram bland de människoätande fasor som hemsöker de södra skogarna och rycka Marys förlorade skatt ur ruttnande klor."}},faq={{q="Varför behöver Viktori Marys spegel?",a="Viktori Prism'Antras bygger ett kraftfullt teleskop i sin stuga uppe på kullen i Darkshire. Han behöver högkvalitativa reflekterande linser och speglar för att samla det svaga stjärnljuset, och Marys älskade arvegods uppfyller uppfinningens exakta optiska krav.",al={"viktoris spegel","varför spegel","vad är spegeln till för"}},{q="Vem är Insane Ghoul som stal spegeln?",a="Insane Ghoul är ett odött asätarmonster som samlade på prydnadssaker från de övergivna gårdarna nära Marys hus. Det flydde söderut och tog sin tillflykt till det förstörda kapellet inne på Tranquil Gardens Cemetery.",al={"var finns den vansinniga besten","vem har spegeln","gast i kapellet"}},{q="Varför kastade Blind Mary bort sin spegel?",a="Mary höll sin spegel kär fram till ”händelsen” som tog hennes syn, slet sönder hennes förstånd och band henne som en rastlös vålnad. Efter den katastrofen stod hon inte längre ut med att se på den eller hålla i den, så i sin förtvivlan kastade hon bort den bakom ladan.",al={"varför kastade mary bort den","blind marys spegel","marys spegel och händelsen"}},{q="Var ligger Tranquil Gardens Cemetery?",a="Tranquil Gardens Cemetery ligger i de sydöstra delarna av Duskwood, söder om huvudvägen. Den var en gång en fridfull begravningsplats för Duskwoods folk, men hemsöks nu av aggressiva gastar, skelett och asätande bestar.",al={"tranquil gardens läge","var ligger kyrkogården"}},{q="Vem är Cog?",a="Cog är en gnomisk uppfinnare som bor i Darkshire. Viktori förlitar sig på Cogs tekniska kunnande för att bedöma och hjälpa till med konstruktionen av de ömtåliga mekanismerna i hans stjärnkikare.",al={"vem är cog","viktori och cog"}},{q="Vad händer när spegeln återlämnas till Viktori?",a="Med den reflekterande anordningen i handen är Viktori överlycklig över hur arbetet med apparaten går. Han går sedan vidare med det sista steget i monteringen av teleskopet och ber om ytterligare en avgörande komponent för att färdigställa linssystemet.",al={"nästa uppdrag efter look to the stars","what comes next"}}},fx={["9a9407cc"]={q="Varför hjälper Blind Mary dig att hitta spegeln?",a="Mary vill inte behålla sin spegel. Den var en gång bland hennes finaste skatter, men blev outhärdlig för henne efter en tragisk händelse som gjorde henne blind och tog allt ifrån henne. I sin förtvivlan hade hon redan kastat bort den bakom ladan och har ingen anledning att dölja vad som hände med den. Hon visar dig gärna vägen till asätaren som tog den.",al={"varför hjälper blind mary","blind marys motiv med spegeln","varför berättar mary var spegeln är"}},f9c44b13={q="Varför behöver Blind Mary att du hämtar spegeln i stället för att göra det själv?",a="Blind Mary är ett hjälplöst, blindt spöke som dröjer sig kvar i ensamhet utanför Darkshire. Även i livet hade hon inte kunnat möta en vild ghoul, och i döden är hon bunden till sitt hemsökta skjul. En beväpnad äventyrare är den enda som kan våga sig in på Tranquil Gardens Cemetery och hämta den.",al={"varför kan inte mary hämta spegeln","varför behöver mary mig","varför hämtar inte mary spegeln"}}},fp="17,160,22.336.0,23.351.0,43.213.0,46.172.0,48.204.0,39.207.0,11.167.0,51.173.1"}
P.entries["quest:1778"] = {n="The Tome of Divinity",s="The Tome of Divinity är ett grundläggande prov för blivande paladiner som lär sig den Heliga Ljusets grundläggande dygder. Efter att ha hjälpt någon i nöd återvänder de till Ironforge för att berätta för sin mentor Tiza Battleforge om sin osjälviska insats.",h="The Tome of Divinity är ett grundläggande prov för blivande paladiner som lär sig den Heliga Ljusets...",kw={"välgörenhet","det heliga ljuset","ironforge","paladinprov","stephanie","stormwind","tiza battleforge","the tome of divinity"},ang={["class:Paladin"]="Prövningarna i The Tome of Divinity lär blivande paladiner att bruket av det Heliga Ljuset kräver osjälviskhet, välgörenhet och varaktig pliktkänsla gentemot vanliga invånare, före ära på slagfältet.",["faction:Alliance"]="Banden mellan Ironforge och kungariket Stormwind är fortfarande starka. Det märks på hur paladinmentorer och resenärer färdas mellan Alliansens stora städer.",["race:Dwarf"]="Dvärgpaladiner som genomgår sina prövningar i Dun Morogh rapporterar till Tiza Battleforge i Ironforges salar för att redogöra för sina handlingar ute i den vidare världen."},sec={{t="Den Heliga Ljusets lärdomar",b="The Tome of Divinity utgör grunden för en novis inträde bland paladinerna. I stället för att kräva prov på stridsförmåga betonar lärorna ödmjukhet, samhällsplikt och välgörenhet mot dem som lider. En sann tjänare av det Heliga Ljuset måste först förstå vanliga dödligas lidande och vara beredd att hjälpa utan att vänta sig personlig vinning eller uppskattning."},{t="Redogörelse i Ironforge",b="När en blivande paladin har slutfört en hjälpinsats i Ironforge återvänder hen till Tiza Battleforge. Inför sin mentor berättar novisen hur hen använde tiden borta och vems bördor hen hjälpte till att bära. Tiza är nöjd med att novisen visat sann välgörenhet och pliktkänsla och berömmer hen. Hon bekräftar att en sådan osjälvisk uppoffring är precis vad det innebär att följa Ljuset."}},faq={{q="Vad är The Tome of Divinity?",a="The Tome of Divinity står för de grundläggande heliga prövningar som unga paladiner genomgår. Genom olika uppgifter prövas noviser i dygder som medkänsla, välgörenhet och självuppoffring, snarare än enbart styrka på slagfältet.",al={"vad är the tome of divinity","the tome of divinity-provet","vad går det här uppdraget ut på"}},{q="Vem är Tiza Battleforge?",a="Tiza Battleforge är en paladinmentor av dvärgsläkt i Ironforge. Hon ansvarar för novisernas andliga och moraliska utveckling och bedömer om deras handlingar speglar det Heliga Ljusets sanna läror.",al={"vem är tiza battleforge","var finns tiza battleforge","paladintränare i ironforge"}},{q="Vem är Stephanie?",a="Stephanie Turner är John Turners hustru i Stormwind, där de driver ett barnhem tillsammans. John hoppas kunna återvända till henne efter att ha samlat förnödenheter i Ironforge.",al={"vem är stephanie","stephanie i stormwind"}},{q="Vad ber Tiza Battleforge återvändande noviser att göra?",a="Tiza prövar om paladinen har förstått välgörenhetens och tjänandet av andras verkliga innebörd. Hon lyssnar på hur novisen har hjälpt en ädel sak och bistått vanliga invånare innan hon ger sin välsignelse.",al={"vilken lärdom prövar tiza","vad vill tiza","paladinernas välgörenhetsprov"}},{q="Varför måste noviser rapportera till Ironforge?",a="Noviser skickas tillbaka till Ironforge för att berätta om sina handlingar för Tiza Battleforge och visa att de handlat med medkänsla och osjälviskhet genom att hjälpa John Turner i staden.",al={"varför tala med tiza i ironforge","the tome of divinity i ironforge"}},{q="Varför är självuppoffring central i det här provet?",a="Enligt paladinernas läror är det grundläggande för att följa det Heliga Ljuset att sätta andras välbefinnande framför sitt eget. Tiza påminner sina elever om att en sådan osjälvisk uppoffring alltid belönas med tiden.",al={"hur belönar ljuset uppoffringar","paladinernas uppoffring"}}},fp="20,243,25.386.0,27.395.0,29.228.0,24.205.0,17.157.0,54.203.0,39.177.0,44.213.0"}
P.entries["quest:1779"] = {n="The Tome of Divinity",s="The Tome of Divinity är en helig prövning som paladinlärlingar i Ironforge genomgår för att bevisa sin behärskning av helig kraft och sin hängivenhet i strid. Med Symbol of Life i sin vård skickas en blivande paladin för att hjälpa den sårade krigaren Muiredon Battleforge efter en dödlig drabbning med Dark Iron-dvärgar.",h="The Tome of Divinity är en helig prövning som paladinlärlingar i Ironforge genomgår för att bevisa sin...",kw={"dark iron","heliga ljuset","ironforge","muiredon battleforge","narm","paladin","symbol of life","tome of divinity"},ang={["class:Paladin"]="Den här prövningen testar en ung paladins hängivenhet. Du får i uppgift att bära Symbol of Life för att trösta de sårade och förbereda dig för den heliga plikten att återuppväcka de döda.",["race:Dwarf"]="Prövningen utspelar sig i hjärtat av Ironforge och speglar de starka banden mellan dvärgförsvarare som trotsar bakhåll från fientliga Dark Iron-klaner."},sec={{t="En prövning i tro och kraft",b="The Tome of Divinity är en avgörande milstolpe i utbildningen av en paladin i bergariket Ironforge. Lärlingar som redan har visat ödmjukhet, tålamod och givmildhet kallas att demonstrera sin behärskning av närstrid och helig kraft. Med en helig relik kallad Symbol of Life i sin vård skickas lärlingen ut i stadens salar för att hjälpa dem som lider av de bittra striderna som rasar utanför portarna."},{t="En fallen broder",b="Det omedelbara uppdraget leder lärlingen till Muiredon Battleforge, en blåslagen dvärgkrigare som vårdar svåra skador efter en sammandrabbning med fientliga Dark Iron-dvärgar. Medan en präst tar hand om Muiredons akuta sår förbereder sig den sargade krigaren på att berätta vad som hände med hans expedition och hans följeslagare Narm. Det blir en utmaning för den blivande paladinen att träda fram och använda Ljusets gåva att förnya liv."}},faq={{q="Vad är The Tome of Divinity?",a="The Tome of Divinity är en övergångsrit för unga paladiner som lär sig den Heliga Ljusets vägar. I det här skedet av prövningen får en lärling som redan har visat givmildhet och tålamod en artefakt kallad Symbol of Life och i uppdrag att hjälpa en sårad dvärg i Ironforge.",al={"vad är det här uppdraget","syftet med tome of divinity","vad går uppdraget ut på"}},{q="Vad är Symbol of Life?",a="Symbol of Life är en helig symbol som paladinlärlingar får i sin vård under sina prövningar. Den förkroppsligar den Heliga Ljusets helande och återställande kraft och är avsedd att hjälpa och återuppliva dem som fallit i försvaret av sitt folk.",al={"vad är symbol of life","föremålet symbol of life"}},{q="Vem är Muiredon Battleforge?",a="Muiredon Battleforge är en dvärgkrigare som nyligen överlevde en brutal skärmytsling mot Dark Iron-dvärgar. Trots att han är blåslagen och hostar av sina skador får han vård av en lokal präst i Ironforge, medan hans fru skickar lovande paladiner för att höra hans berättelse.",al={"vem är muiredon battleforge","vem är den sårade dvärgen"}},{q="Vem ger dig Symbol of Life?",a="Uppdraget ges av Muiredon Battleforges fru, en paladinmentor i Ironforge. Efter att ha sett dig visa givmildhet och tålamod skickar hon dig med Symbol of Life för att pröva din kraft, din stridsberedskap och din vilja att hjälpa hennes sårade make.",al={"vem skickar dig till muiredon","vem ger det här uppdraget"}},{q="Vad hände med Muiredon Battleforge?",a="Muiredon och hans följeslagare Narm överfölls av fientliga Dark Iron-dvärgar. Muiredon undkom med knapp nöd och tog sig tillbaka till Ironforge med svåra skador som kräver både andlig och fysisk läkning.",al={"vem attackerade muiredon","vad hände med muiredon"}},{q="Vem är Narm?",a="Narm är Muiredon Battleforges bästa vän och en annan paladin som följde med honom i strid. Muiredon lyckades fly från drabbningen med Dark Iron-dvärgarna, men Narm hade inte samma tur. Därmed uppstår behovet av en paladin som kan ingripa för hans skull.",al={"vem är narm","vad hände med narm"}}},fp="20,302,26.454.0,16.400.0,29.289.0,27.221.0,28.267.0,33.257.0,38.220.0,12.258.0"}
P.entries["quest:178"] = {n="Theocritus' Retrieval",s="Theocritus' Retrieval börjar när en äventyrare hittar ett magiskt smycke som de lokala gnollerna bär på i Redridge, och hör en avlägsen röst eka genom det. Rösten tillhör Theocritus, övermagiker vid Tower of Azora, som har lyckats avlyssna gnollernas mystiska nätverk och ber enträget att hänget ska föras till honom för undersökning.",h="Theocritus' Retrieval börjar när en äventyrare hittar ett magiskt smycke som de lokala gnollerna bär på i...",kw={"elwynn","gnoller","morganth","hänge","redridge","shadowhide","theocritus","tower of azora"},ang={["class:Mage"]="Theocritus arbete visar hur förtrollande och spådomskonst kan användas på ett sinnrikt sätt: han tar sig in i en annan magikers nätverk för att sända motbesvärjelser över stora avstånd.",["faction:Alliance"]="Samarbetet mellan Tower of Azora i Elwynn och Lakeshires hårt ansatta försvarare visar hur lokala magiker rycker in när Stormwinds kungliga armé har lämnat garnisonerna underbemannade."},sec={{t="En röst i stenen",b="När resande strider mot de vilda Shadowhide-gnollerna i Redridge Mountains händer det att de hittar ett förtrollat smycke som kallas Shadowhide Pendant. I stället för gutturala skall eller förbannelser hörs en lugn, kroppslös röst när någon rör vid föremålet. Den tillhör Theocritus, en mänsklig magiker som bor i Tower of Azora på andra sidan gränsen, i Elwynn Forest. Överföringen är resultatet av lång och mödosam forskning, med målet att tränga igenom de mörka besvärjelser som styr gnollflockarna."},{t="Utnyttja Morganths nätverk",b="Shadowhide-gnollerna handlar inte enbart på instinkt. De lyder Morganth, en avfällig mörk magiker som gömmer sig i bergen. Morganth tillverkar och delar ut de förtrollade hänget för att sända order direkt till sina bestialiska undersåtar. Theocritus ägnade månader åt att nysta upp frekvensen i Morganths sändningsbesvärjelser. När en äventyrare återlämnar det blekta hänget till Tower of Azora bekräftar magikern att hans skådande nådde talismanen. Det öppnar möjligheten att baklängeskonstruera en attack som helt kan slå ut gnollerna."}},faq={{q="Vem är Theocritus?",a="Theocritus är en övermagiker i Alliansen, stationerad i Tower of Azora i östra Elwynn Forest. Han håller noggrann uppsikt över oroligheter i trakten och ägnar en stor del av sina magiska studier åt att motverka den mörka magi som tränger in från Redridge.",al={"theocritus bakgrund","vem talar genom hänget","magikern i tower of azora"}},{q="Varför bar Shadowhide-gnollerna magiska hängen?",a="Hängena är magiska kanaler som tillverkats av den avfällige magikern Morganth. Genom dem sänder han mentala order och styr Shadowhide-klanens rörelser på avstånd.",al={"varför har gnollerna hängen","shadowhide pendant syfte","magiskt föremål hos gnollerna"}},{q="Varför dröjde rösten när Theocritus sände den?",a="Theocritus kastade sin besvärjelse flera veckor innan en äventyrare hittade stenen. Till en början trodde han att besvärjelsen hade klingat av och misslyckats. Det uppstod en betydande magisk fördröjning eftersom han trängde igenom Morganths mörka skydd och upprättade en länk över ett så stort avstånd.",al={"fördröjt meddelande","varför dröjde theocritus flera veckor","fördröjning med blekt hänge"}},{q="Vad hoppas Theocritus uppnå med det återfunna hänget?",a="Genom att tyda den specifika magiska frekvens som knyter hänget till Morganth hoppas Theocritus kunna vända magins flöde. Hans yttersta mål är att sända en offensiv besvärjelse genom nätverket som genast kan göra varje gnoll som bär ett hänge orörlig.",al={"theocritus plan","vad ska theocritus göra","varför undersöka hänget"}},{q="Vart leder uppdragskedjan sedan?",a="När hänget lämnas in är det här ärendet avslutat. Theocritus fortsatta kamp mot Morganth är ett separat uppdrag som fortsätter i 'A Watchful Eye'. Där får äventyrare i uppdrag att spionera på Morganths fäste vid Tower of Ilgalar.",al={"nästa uppdrag efter theocritus' retrieval","morganths uppdragskedja","vad händer sedan"}}},fx={["24fcac1f"]={q="Varför behöver Theocritus en äventyrare som levererar hänget?",a="Theocritus kastade ut sitt meddelande blint över de magiska frekvenser som Morganth använder för att kommunicera med gnollerna. Han visste inte var eller när ett hänge skulle ta emot det. Han är bunden till sitt heliga rum i Tower of Azora i Elwynn Forest och kunde inte själv genomsöka de fientliga vildmarkerna i Redridge Mountains. Han förlitar sig på att en duglig resenär hittar artefakten och för tillbaka den till tryggare, bebodda trakter.",al={"varför skicka en äventyrare","varför behöver theocritus mig","varför kan inte theocritus hämta hänget"}}},fp="21,233,20.399.0,29.429.1,18.186.0,57.146.0,50.221.0,64.218.0,38.200.1"}
P.entries["quest:1780"] = {n="The Tome of Divinity",s="The Tome of Divinity är ett heligt prov som paladiner genomgår för att visa sin hängivenhet till Holy Light. Under Duthorian Ralls vägledning i Cathedral of Light i Stormwind måste de visa osjälviskhet, givmildhet och en orubblig vilja att skydda behövande.",h="The Tome of Divinity är ett heligt prov som paladiner genomgår för att visa sin hängivenhet till Holy Light.",kw={"cathedral of light","givmildhet","duthorian rall","holy light","paladinprov","stormwind","tome of divinity"},ang={["class:Paladin"]="The Tome of Divinity prövar en blivande paladins hängivenhet till osjälviskt tjänande och lär ut att trohet mot Holy Light kräver konkreta handlingar av givmildhet och skydd för vanliga invånare.",["faction:Alliance"]="Proven stärker Stormwinds andliga grund och påminner Alliansens försvarare om att sann styrka ligger i att skydda de utsatta bland deras folk."},sec={{t="Ett dygdernas prov",b="The Tome of Divinity är en avgörande övergångsrit för paladiner i Holy Lights tjänst. Duthorian Rall leder dessa prov i Cathedral of Light i Stormwind City och skickar ut aspiranter för att visa sin hängivenhet, inte genom krigsära, utan genom moralisk integritet och osjälviska handlingar för rikets invånare."},{t="Osjälviskhetens dygd",b="När aspiranterna återvänder efter att ha hjälpt utsatta genom att ge behövande barn välkommen hjälp och få deras innerliga tacksamhet, berättar de för Duthorian Rall vad de gjort. Mentorn imponeras av handlingar där andra sätts främst och påminner dem om att givmildhet, medkänsla och plikten mot Azeroths folk är de verkliga måtten på den som följer Ljuset."}},faq={{q="Vad är The Tome of Divinity?",a="The Tome of Divinity består av en grundläggande serie prov för blivande paladiner. Uppdraget leds av mentorer i Cathedral of Light i Stormwind och går ut på att aspiranterna visar moralisk dygd, givmildhet och pliktkänsla genom att hjälpa rikets behövande invånare direkt.",al={"vad är tome of divinity","uppdraget tome of divinity","paladinernas provuppdrag"}},{q="Vem är Duthorian Rall?",a="Duthorian Rall är en erfaren paladintränare i Cathedral of Light i Stormwind City. Han vägleder nya paladiner genom deras andliga utbildning och moraliska prov och bedömer om deras handlingar speglar verklig trohet mot Holy Lights dygder.",al={"vem är duthorian rall","paladintränare i stormwind","duthorian ralls roll"}},{q="Vad lär provet ut?",a="Provet förmedlar paladinernas grundläggande ethos: att utöva Ljuset kräver ödmjukhet, osjälviska uppoffringar och tjänande av andra. I stället för att enbart fokusera på krigisk skicklighet betonar det medkänsla, givmildhet och moraliska skyldigheter gentemot Azeroths folk.",al={"syftet med tome of divinity","varför gör paladiner detta","vad lär uppdraget ut"}},{q="Var utspelar sig uppdraget?",a="Uppdraget kretsar kring Cathedral of Light, den storslagna andliga helgedomen i Cathedral Square i Stormwind City. Aspiranterna ger sig ut för att hjälpa invånarna och återvänder sedan till katedralen för att rapportera sina handlingar till Duthorian Rall.",al={"var utspelar sig uppdraget","var lämnar man in tome of divinity","uppdrag i cathedral of light"}},{q="Vem fick hjälp i uppdraget?",a="Under den här delen av provet fick människor i stor nöd hjälp, däribland små barn. Mottagaren uttrycker stor tacksamhet och påpekar att paladiner i Stormwind aldrig får vända de oskyldiga och utblottade ryggen.",al={"vem fick hjälp i uppdraget","uppdrag om välgörenhet för barn","vem fick hjälp"}},{q="Varför betonar Duthorian Rall givmildhet?",a="Givmildhet och skydd av oskyldiga är centrala grundpelare i Holy Light. Duthorian Rall betonar att personliga uppoffringar och att värdera andras välmående högre än sitt eget utgör grunden för en paladins heliga kall.",al={"varför är givmildhet viktig för paladiner","paladiner och fattiga","givmildhet och holy light"}}},fp="20,277,17.348.0,26.372.0,29.299.0,22.266.0,37.269.0,33.248.0,23.229.0,42.221.0"}
P.entries["quest:1781"] = {n="The Tome of Divinity",s="The Tome of Divinity utgör ett avgörande prov för paladinlärlingar i Stormwinds Cathedral of Light, där de får i uppgift att fokusera den heliga Symbol of Life. Efter att ha bevisat sin dygd får aspiranterna i uppdrag att hjälpa Gazin Tenorm, som med knapp nöd undkom ett dödligt Defias-bakhåll nära Heroes' Vigil i Elwynn Forest.",h="The Tome of Divinity utgör ett avgörande prov för paladinlärlingar i Stormwinds Cathedral of Light, där de...",kw={"cathedral of light","defias","duthorian","duthorian rall","gazin tenorm","henze","heroes vigil","symbol of life","the tome of divinity","tome of divinity"},ang={["class:Paladin"]="Detta uppdrag är en avgörande milstolpe i en paladins utbildning i Stormwind. Det prövar om en lärling har den andliga styrkan som krävs för att använda Symbol of Life.",["faction:Alliance"]="Defias verksamhet nära Heroes' Vigil utgör ett ständigt hot mot resande och invånare i Elwynn Forest, och kräver kyrkans ingripande."},sec={{t="Ett prov i hängivenhet",b="I Cathedral of Light får paladinlärlingar som visat tålamod och givmildhet ta emot Symbol of Life. Duthorian Rall anförtror dem denna heliga relik, som prövar om en blivande förkämpe har tillräcklig andlig hängivenhet för att fokusera en av Ljusets största gåvor: kraften att återge de fallna livet."},{t="Bakhåll vid Heroes' Vigil",b="Gazin Tenorm visar hur brådskande behovet av Symbol of Life är. Han kröp nyligen tillbaka till Stormwind efter ett brutalt anfall från Defias-banditer nära Heroes' Vigil i Elwynn Forest. Medan präster vid katedralens altare vårdar Gazins svåra sår är hans följeslagare Henze fortfarande i fara där laglösa slog till."}},faq={{q="Vem är Gazin Tenorm?",a="Gazin Tenorm är en bundsförvant till Duthorian Rall som med knapp nöd undkom ett bakhåll från Defias-banditer nära Heroes' Vigil i Elwynn Forest. Han skadades svårt i striden och fördes till Cathedral of Light i Stormwind för att vårdas av lokala präster.",al={"vem är gazin tenorm","gazin elwynn defias","sårad man stormwind altare"}},{q="Vad är Symbol of Life?",a="Symbol of Life är en helig relik som anförtros åt paladinlärlingar som anses vara givmilda och tålmodiga. Den prövar om en blivande förkämpe har den andliga koncentration och styrka som krävs för att kanalisera en av den Heliga Ljusets största gåvor: att återge liv.",al={"vad gör symbol of life","symbol of life paladin","paladins uppståndelserelikt"}},{q="Vad hände vid Heroes' Vigil?",a="Heroes' Vigil är ett område i Elwynn Forest där Gazin Tenorm och hans följeslagare Henze överfölls av Defias-laglösa. Gazin lyckades fly tillbaka till Stormwind svårt sårad, men hans vän Henze behöver hjälp.",al={"var ligger heroes vigil","heroes vigil elwynn defias","platsen för gazins bakhåll"}},{q="Vem är Henze?",a="Henze är Gazin Tenorms följeslagare och var med när Defias-banditer anföll dem i Elwynn Forest nära Heroes' Vigil. Gazin tog sig levande tillbaka till Stormwind, men Henze lämnades kvar i fältet.",al={"vem är henze","henze faulk","gazins vän defias"}},{q="Vem ber dig tala med Gazin Tenorm?",a="Uppdragsgivaren är Duthorian Rall, en ledare bland paladinerna i Cathedral of Light i Stormwind. När han har bekräftat att en lärling visat tålamod och givmildhet skickar han denne till altaret för att tala med Gazin Tenorm.",al={"vem skickar dig till gazin","duthorian rall the tome of divinity","stormwind paladintränarens uppdrag"}},{q="Varför angriper Defias-banditer resande nära Heroes' Vigil?",a="Defias Brotherhood har spritt laglösa och stråtrövare över Elwynn Forest, där de överfaller resande till och med inom räckhåll från huvudstaden. Gazin Tenorms fasansfulla möte visar hur djärva och dödliga Defias operationer har blivit.",al={"defias hot elwynn","varför är defias nära heroes vigil","defias brotherhood stormwind"}}},fp="20,318,18.338.0,23.310.0,20.257.0,27.264.0,31.227.0,13.201.0,41.227.0,62.245.0"}
P.entries["quest:1782"] = {n="Furen's Armor",s="I Stormwind söker Furen Longbeard hjälp med att testa en ny rustning. En blivande krigare samlar spindeltänder, chimärhorn och flogiston så att mästersmeden kan smida eldhärdad ringbrynja. Furen ger den färdiga rustningen till krigaren och lovar att dela med sig av sina lärdomar till smeder i Alliansen.",h="I Stormwind söker Furen Longbeard hjälp med att testa en ny rustning.",kw={"krigare i alliansen","smedja","eldhärdad ringbrynja","furen longbeard","furens rustning","ringbrynja","stormwind"},ang={["class:Warrior"]="Som krigare i Alliansen markerar Furens specialhärdade rustning att du går ut i stridens främsta led och ger skydd under de första fälttågen.",["faction:Alliance"]="Starka armar hjälper till att hålla Alliansens styrkor vid liv mot hot från Defias, gnoller och fientliga elementarkrafter.",["profession:Blacksmithing"]="Furens experiment visar hur smeder i Alliansen delar metallurgiska rön för att utveckla sitt hantverk i Stormwind och Ironforge."},sec={{t="En mästares genombrott",b="Furen Longbeard, en dvärgisk rustningssmed i Stormwind, arbetar med att förbättra hur Alliansens rustningar står emot hetta och krossande slag. Han ber en blivande krigare samla sällsynta material till sina tester. Ringbrynjan blir en framgång och stärker Furens anseende bland Alliansens rustningssmeder."},{t="Dela hantverket",b="Furen ger den färdiga eldhärdade ringbrynjan till krigaren som samlade materialen, tacksam för hjälpen. Experimenten fördjupar också hans kunskap om skyddande smide. Han planerar att skicka sina anteckningar och rön till andra smeder i Alliansen, så att de kan använda de nya metoderna."}},faq={{q="Vem är Furen Longbeard?",a="Furen Longbeard är en mästersmed av dvärgisk härkomst i Stormwind. Han arbetar nära Alliansens militära ordnar, särskilt med krigare som behöver specialanpassad rustning.",al={"vem är furen","furen longbeard","smeden furen i stormwind"}},{q="Vilken sorts rustning skapade Furen?",a="Furen smidde en Fire Hardened Hauberk, en ringbrynjekyrass tillverkad av sällsynta huggtänder, horn och flogiston. Den är utformad för att stå emot våldsamma angrepp och extrem hetta.",al={"vilken rustning smider furen","eldhärdad ringbrynja","furens belöning"}},{q="Vart skickar Furen Longbeard sina smidesupptäckter?",a="Furen lovar att skicka sina rön och anteckningar till smideskollegor i hela Alliansen. På så vis delar han med sig av de testade härdningsmetoderna till smedjor runt om i riket.",al={"furen's notes","vem får furens ritningar","alliansens smeder"}},{q="Varför fick krigaren i uppdrag att samla reagenser åt Furen?",a="Furen behövde sällsynta, flyktiga material för att testa nya smidestekniker. Han kunde inte lämna sin smedja för att jaga spindlar i Wetlands och chimärer i Stonetalon, så han förlitade sig på en ambitiös krigare som kunde samla in dem.",al={"varför samla reagenser åt furen","material till uppdraget eldhärdad ringbrynja"}},{q="Var smids och lämnas rustningen över?",a="Furen smider och lämnar över rustningen vid sin smedja i Stormwind, där han färdigställer ringbrynjan.",al={"var finns furen longbeard","plats för inlämning","furens plats"}},{q="Gör arbetet nytta för andra kämpar i Alliansen?",a="Ja. Furen planerar att dela med sig av sina lärdomar till andra rustningssmeder i Alliansen och hoppas att de använder metoderna för att tillverka stark utrustning åt Alliansens soldater.",al={"nytta för alliansen","furens genombrott"}}},fp="13,288,23.282.0,17.283.0,23.161.0,36.162.0,57.159.0,55.207.0,41.96.0,47.152.0"}
P.entries["quest:1783"] = {n="The Tome of Divinity",s="The Tome of Divinity skickar en paladinlärling till de iskalla stränderna söder om Helm's Bed Lake i Dun Morogh. Beväpnad med Symbol of Life måste paladinen hitta och återuppväcka Narm Faulk, en modig spejare som stupade när han höll stånd mot en grupp Dark Iron-dvärgar.",h="The Tome of Divinity skickar en paladinlärling till de iskalla stränderna söder om Helm's Bed Lake i Dun...",kw={"dark iron","dun morogh","helm's bed lake","muiredon","narm faulk","paladin","återuppväckning","symbol of life","the tome of divinity"},ang={["class:Paladin"]="Den här prövningen visar att en paladin kan bemästra själva döden och kanalisera Ljuset genom Symbol of Life för att återställa en fallen allierad.",["faction:Alliance"]="Genom att rädda dvärgspanare och återta heliga skrifter skyddas viktig kunskap och alliansens försvarare från Dark Irons planer.",["race:Dwarf"]="Prövningen ställer paladinen direkt inför hotet från Dark Iron-dvärgarna som befäst sina ställningar söder om Helm's Bed Lake i Dun Morogh."},sec={{t="Bakhåll vid sjön",b="Ett rutinmässigt spaningsuppdrag söder om Helm's Bed Lake blev farligt när dvärgspanarna Muiredon och Narm Faulk fick syn på fientliga Dark Iron-dvärgar som befäste sina ställningar. Efter att ha sett en fiendebefälhavare ge order försökte spanarna slå ut flera fiender och säkra ett dokument, men Dark Iron-dvärgarna övermannade dem med oväntad grymhet. Muiredon flydde för att hämta förstärkningar medan Narm höll stånd."},{t="Ett trosprov",b="Beväpnad med Symbol of Life beger sig en paladinlärling in i Dun Moroghs snötäckta vidder för att hitta Narm Faulk. Narm föll under Dark Iron-dvärgarnas anfall, men genom att kanalisera den heliga relikens kraft dras hans ande tillbaka precis när Ljuset var redo att helt omfamna honom. Handlingen befäster paladinens gryende kallelse och förmåga att återställa livet hos de stupade."}},faq={{q="Vad är syftet med det här uppdraget?",a="The Tome of Divinity är en avgörande prövning för unga paladiner. I det här steget får en lärling Symbol of Life och skickas för att rädda en fallen spejare. Lärlingen bevisar sitt värde och sin hängivenhet genom att åkalla Ljuset och återföra någon från de döda.",al={"vad är the tome of divinity","syftet med the tome of divinity","paladinuppdrag för återuppväckning"}},{q="Vem är Narm Faulk?",a="Narm Faulk är en alliansspejare som överfölls av Dark Iron-dvärgar söder om Helm's Bed Lake. Han offrade sin chans att fly så att hans partner Muiredon kunde komma undan. Han föll i strid innan Ljuset återställde honom.",al={"vem är narm faulk","var finns narm","den fallne dvärgen narm"}},{q="Vem är Muiredon?",a="Muiredon är spejaren som flydde från Dark Iron-bakhållet på Narm Faulks uppmaning. Han återvänder för att söka förstärkningar och visar paladinen hur den fallne kamraten kan räddas med Symbol of Life.",al={"vem är muiredon","uppdragsgivaren muiredon","vem ger uppdraget"}},{q="Vad är Symbol of Life?",a="Symbol of Life är en helig relik som paladinen får tillsammans med instruktioner från Tiza och Muiredon. När en värdig tjänare av Ljuset kanaliserar dess kraft kan den återuppväcka de döda.",al={"vad är symbol of life","föremål för återuppväckning","berättelsen om symbol of life"}},{q="Vad gjorde Narm och Muiredon nära Helm's Bed Lake?",a="Muiredon och Narm Faulk spionerade på Dark Iron-dvärgar som hade befäst sina ställningar söder om Helm's Bed Lake. Under sitt spaningsuppdrag såg de en fiendeledare ryta ut order och försökte återta heliga skrifter, innan de blev övermannade.",al={"vad gjorde de söder om helm's bed lake","varför spionera på dark iron","dark iron vid helm's bed lake"}},{q="Vem är Tiza?",a="Tiza är en av mentorerna eller samordnarna som hjälper till att skicka förstärkning och förbereda Symbol of Life tillsammans med Muiredon inför räddningsuppdraget.",al={"vem är tiza","tiza och paladiner"}}},fp="20,257,18.417.0,15.377.1,34.259.0,18.222.0,16.185.0,27.204.0,55.255.0,12.147.0"}
P.entries["quest:1784"] = {n="The Tome of Divinity",s="The Tome of Divinity är ett avgörande paladinprov som går ut på att avslöja en hemlig Dark Iron-infiltration i Dun Morogh. Blivande paladiner hjälper de skadade spejarna Narm Faulk och Muiredon Battleforge och säkrar viktiga fiendeorder för att övertyga det skeptiska rådet i Ironforge om faran som hotar i närheten.",h="The Tome of Divinity är ett avgörande paladinprov som går ut på att avslöja en hemlig Dark Iron-infiltration...",kw={"dark iron-dvärgar","dark iron script","dun morogh","helm's bed lake","ironforge","muiredon battleforge","narm faulk","tome of divinity"},ang={["class:Paladin"]="Det här uppdraget är ett viktigt steg i en dvärgpaladins tidiga prövningar med The Tome of Divinity och lär ut osjälvisk hängivenhet till Ljuset genom att skydda riket och rädda kamrater i nöd.",["faction:Alliance"]="Genom att avslöja Dark Iron-sabotage kring Ironforge skyddar man dvärgarnas huvudstad och stärker Alliansens norra försvar mot dolda hot.",["race:Dwarf"]="Det är livsviktigt för dvärgarnas försvar att avslöja Dark Iron-infiltration alldeles inpå Ironforge. Det bevisar för de envisa rådsmedlemmarna att deras ärkefiende har tagit sig in i Dun Morogh."},sec={{t="Ett tjänsteprov",b="The Tome of Divinity vägleder unga dvärgpaladiner på deras andliga väg. Under det här provet dras blivande hjältar in i försvaret av Dun Morogh när en expedition mot hemliga Dark Iron-agenter går snett nära Helm's Bed Lake. Narm Faulk och Muiredon Battleforge försökte överfalla fiendespejare, men Narm sårades i striden medan Muiredon drog sig tillbaka till Ironforge för att återhämta sig."},{t="Bevis åt rådet",b="Trots växande rykten vägrar flera medlemmar av det styrande rådet i Ironforge att erkänna att Dark Iron-infiltratörer har tagit sig in i Dun Morogh. Genom att spåra upp spionerna nära Helm's Bed och återta ett Dark Iron Script som deras kapten skickat vidare, säkrar paladinen obestridliga bevis på fiendens rörelser och avslöjar deras planer som håller på att ta form strax utanför huvudstadens portar."},{t="Skydda härden",b="Det innebär en stor lättnad att återlämna de avlyssnade orderna till Muiredon Battleforge i Ironforge. När Narm har räddats och dokumenten lämnats över så att Muiredons fru kan lägga fram dem inför rådet, visar paladinen både osjälviskt mod och hängivenhet till Ljuset och skyddar dvärgriket från dolt förräderi."}},faq={{q="Vem ger uppdraget The Tome of Divinity?",a="Uppdraget ges av Narm Faulk, en skadad dvärg som stupade i strid mot Dark Iron-spioner nära Helm's Bed Lake. Han ber dig hämta fiendens skrifter och rapportera tillbaka till hans följeslagare Muiredon Battleforge i Ironforge.",al={"vem ger uppdraget","uppdragsgivare för tome of divinity","vem är narm"}},{q="Vem är Muiredon Battleforge?",a="Muiredon Battleforge är en dvärg som håller till i Ironforge. Han spanade efter Dark Iron-spionerna tillsammans med Narm Faulk nära Helm's Bed Lake innan han återvände till staden för att återhämta sig från sina skador.",al={"vem är muiredon battleforge","var finns muiredon","muiredon battleforge plats"}},{q="Vad är Dark Iron Script?",a="Dark Iron Script innehåller skriftliga order som skickats mellan Dark Iron-spioner och deras kapten nära Helm's Bed Lake. Det ger konkreta bevis på fientlig infiltration som kan visas för det skeptiska rådet i Ironforge.",al={"vad är dark iron script","varför hämta dark iron script","dark iron scripts syfte"}},{q="Varför behöver rådet i Ironforge bevis på Dark Iron?",a="Vissa rådsmedlemmar i Ironforge tvivlar fortfarande på att Dark Iron-dvärgar har lyckats infiltrera Dun Morogh. De återfunna skrifterna bevisar att de är aktiva i området och avslöjar deras hemliga planer.",al={"varför förnekar rådet dark iron","bevis på dark iron inför ironforges råd"}},{q="Var finns Dark Iron-spionerna?",a="Helm's Bed Lake ligger i östra Dun Morogh, öster om Kharanos. Dark Iron-spioner håller till nära ett litet hus i området och försöker skicka vidare hemliga stridsorder.",al={"var ligger helms bed lake","dark iron vid helms bed","dark iron-plats i dun morogh"}},{q="Vilken roll spelar uppdraget för paladiner?",a="The Tome of Divinity-serien prövar en blivande paladins hängivenhet åt tjänande, medkänsla och mod. Genom att hjälpa fallna kamrater som Narm och försvara Dun Morogh mot lömska fiender visar paladinen sig värdig att svinga Ljuset.",al={"vad lär tome of divinity ut","paladinlore om tome of divinity"}}},fp="20,311,18.396.0,21.378.0,19.325.1,37.222.0,28.181.0,29.210.0,63.202.0,38.164.0,44.234.0"}
P.entries["quest:1785"] = {n="The Tome of Divinity",s="The Tome of Divinity är ett avgörande prov som heliga mästare genomgår i Ironforge, och det kulminerar i ett möte med Tiza Battleforge. När du klarar provet visar du att du är värdig att bära Symbol of Life och låser upp den heliga kraften att återuppväcka fallna allierade.",h="The Tome of Divinity är ett avgörande prov som heliga mästare genomgår i Ironforge, och det kulminerar i ett...",kw={"ironforge","paladin","redemption","återuppväckning","symbol of life","the tome of divinity","tiza battleforge","tome of divinity"},ang={["class:Paladin"]="Det här uppdraget är en helig övergångsrit för dvärgiska paladiner i Ironforge och kulminerar i gåvan att återuppväcka genom Ljuset.",["faction:Alliance"]="Mästare som tränats i Ljuset är redo att stå vid frontlinjen mot Scourge och Dark Iron-klanen.",["race:Dwarf"]="Provet äger rum i Ironforge och ger Battleforge-familjen dvärgrikets tacksamhet."},sec={{t="En helig rit i Ironforge",b="The Tome of Divinity är en av de viktigaste milstolparna i en dvärgisk helig krigares träning. Efter att ha genomgått prövningar runt om i kungariket skickas mästaren till Tiza Battleforge i Ironforge, en vördad lärare i de heliga konsterna. Hennes make ser stolt på när du går fram till henne, ivrig att se dig erkännas som redo inför dvärgfolket och det heliga Ljuset."},{t="Uppståndelsens välsignelse",b="För att få den sista välsignelsen måste en mästare visa den andliga beslutsamhet som krävs för att hantera Symbol of Life. Som Tiza Battleforge förklarar svarar reliken bara på ett hjärta som verkligen är redo att förmedla Ljusets största gåvor. När du bevisar att du är värdig kan Tiza ge dig en helig skriftrulle som låter dig kalla fallna kamrater tillbaka från dödens rand. Mästaren får denna kraft för att hjälpa Ironforge i dess kamp mot Scourge och Dark Iron-klanen."}},faq={{q="Vad är The Tome of Divinity?",a="The Tome of Divinity är ett heligt prov som heliga mästare genomgår i Ironforge. När du klarar provet bevisar du din andliga mognad och får förmågan att kanalisera Ljuset för att återuppväcka fallna följeslagare.",al={"vad är tome of divinity","uppdraget tome of divinity","vad gör det här uppdraget"}},{q="Vem är Tiza Battleforge?",a="Tiza Battleforge är en framstående dvärgisk lärare i Ljuset i staden Ironforge. Hon ger den sista välsignelsen till mästare som har visat sig redo att bruka uppståndelsens kraft.",al={"vem är tiza battleforge","var finns tiza battleforge","hitta tiza battleforge"}},{q="Vem skickar dig till Tiza Battleforge?",a="Hennes make hänvisar dig till Tiza Battleforge efter att du har klarat ett tidigare fältprov. Han är redan i Ironforge och skickar dig vidare till sin hustru med stolta och uppmuntrande ord.",al={"vem ger uppdraget","tizas make","vem skickade mig till tiza"}},{q="Vad är Symbol of Life?",a="Symbol of Life är ett heligt föremål som används under paladinens prövningar. Det fungerar bara för en mästare vars hängivenhet gör hen värdig att få ett av Ljusets största mirakel: att kalla en fallen allierad tillbaka från döden.",al={"vad är symbol of life","symbol of life paladin","hur fungerar återuppväckning"}},{q="Vilken förmåga lär du dig när du slutför det här uppdraget?",a="När du inställer dig hos Tiza Battleforge välsignar hon dig med en helig skriftrulle som lär dig Redemption, kraften att återuppväcka fallna allierade.",al={"vilken kraft lär jag mig","uppdrag med återuppväckningsbesvärjelse","paladinuppdrag för återuppväckning"}},{q="Varför behöver Ironforge Ljusets mästare?",a="Ironforge står ständigt inför hot från både de förrädiska Dark Iron-dvärgarna och Scourges odöda vidunder. Därför är mäktiga helare och heliga försvarare avgörande för att försvara riket.",al={"vilka är ironforges fiender","varför slåss mot dark irons och scourge","fiender på slagfältet"}}},fp="20,260,26.406.0,28.504.0,29.213.0,24.208.0,34.190.0,27.223.0,53.155.0,51.203.0"}
P.entries["quest:1786"] = {n="The Tome of Divinity",s="The Tome of Divinity är ett heligt prov i tro och uppoffring för paladiner i Elwynn Forest. Efter att Defias-magiker överfallit och dödat spejaren Henze Faulk vid Heroes' Vigil måste en blivande helig krigare använda Symbol of Life för att återuppväcka honom och sätta stopp för brödraskapets planer.",h="The Tome of Divinity är ett heligt prov i tro och uppoffring för paladiner i Elwynn Forest.",kw={"defias","duthorian","gazin","henze faulk","heroes' vigil","paladin","uppståndelse","stone cairn lake","symbol of life","tome of divinity"},ang={["class:Paladin"]="Uppdraget är en viktig milstolpe för unga paladiner. De visar sin tro och sitt band till Ljuset genom att använda Symbol of Life för att återuppväcka en fallen allierad.",["faction:Alliance"]="Defias-magiker i nordöstra Elwynn hotar Stormwinds hjärtland. Därför är det viktigt för Alliansen att samla underrättelser vid Heroes' Vigil."},sec={{t="Överfallet vid Heroes' Vigil",b="Henze Faulk och hans partner Gazin reste till Heroes' Vigil, en ö mitt i Stone Cairn Lake i nordöstra Elwynn Forest, efter rapporter om att Defias Brotherhood-agenter tagit sig över gränsen. De två spejarna ville få obestridliga bevis att visa kungens rådgivare och försökte överfalla två konspiratörer som granskade planer. Men de blev snabbt övermannade när Defias magiker anslöt sig till striden. Henze offrade sig genom att stå emot de fientliga magikerna och gav Gazin tillräckligt med tid att fly med livet i behåll."},{t="Uppståndelsens gåva",b="För att återhämta sig efter överfallet krävs mer än vanlig medicin. Den heliga Ljusets kraft behövs. En blivande paladin skickas till Stone Cairn Lake med Symbol of Life för att hitta Henzes livlösa kropp på ön. Genom att kanalisera sin egen tro genom den heliga artefakten återuppväcker hen Henze. Det blir ett avgörande prov på den heliga krigarens andliga band och beredskap att försvara Stormwind i Ljusets tjänst."}},faq={{q="Vem är Henze Faulk?",a="Henze Faulk är en modig försvarare som begav sig med Gazin till Heroes' Vigil på Stone Cairn Lake för att säkra bevis på Defias infiltration. Han höll Defias-magikerna stången så att hans följeslagare kunde fly. Till slut föll han för deras magiska attacker, men återuppväcktes med Symbol of Life.",al={"vem är henze faulk","henze faulk","var är henze"}},{q="Var ligger Heroes' Vigil?",a="Heroes' Vigil är en ö mitt i Stone Cairn Lake i nordöstra Elwynn Forest. Defias-magiker och rövare har upprättat en utpost där och granskar hemliga planer.",al={"var ligger heroes' vigil","heroes' vigil plats","ön heroes' vigil"}},{q="Vad är Symbol of Life?",a="Symbol of Life är ett heligt föremål som används för att kanalisera en paladins tro och återuppväcka de fallna. Det krävs sann andlig övertygelse för att ge det kraft, så att lyckas använda det på Henze Faulk blir ett prov på paladinens kallelse.",al={"vad är symbol of life","hur återuppväcker man henze","använda symbol of life"}},{q="Vem leder räddningen av Henze Faulk?",a="Gazin Tenorm, som flydde från Defias på ön och nu ligger sårad nära altaret i Stormwinds Cathedral of Light, ber om hjälp. Han är vän till Duthorian Rall, paladinernas ledare, som skickade novisen till honom.",al={"vem skickade mig till henze","duthorian eller gazin","uppdragsgivare tome of divinity"}},{q="Vad gör Defias vid Heroes' Vigil?",a="Defias-agenter tog sig in i nordöstra Elwynn och samlades vid Heroes' Vigil för att granska dokument och samordna sina operationer. Henze och Gazin försökte återta dokumenten som bevis åt kungens rådgivare.",al={"varför är defias vid heroes' vigil","vad gör defias vid stone cairn lake","defias planer i elwynn"}},{q="Varför begav sig Henze och Gazin till Stone Cairn Lake?",a="Henze Faulk och Gazin reste till Stone Cairn Lake efter att ha hört rapporter om Defias-infiltratörer. Målet var att överfalla konspiratörerna och återta skriftliga bevis på deras planer, så att de kunde visa dem för kung Anduins rådgivare i Stormwind.",al={"varför var henze och gazin där","henze och gazins uppdrag"}}},fp="20,298,23.564.0,24.427.1,19.287.0,23.188.0,27.215.0,38.219.0,43.216.0,47.231.0"}
P.entries["quest:1787"] = {n="The Tome of Divinity",s="The Tome of Divinity är ett viktigt uppdrag i träningen av paladiner i Alliansen som vill bevisa sin hängivenhet till Ljuset. Efter att ha hjälpt en skadad spejare vid namn Henze i Elwynn Forest måste novisen konfrontera Defias Rogue Wizards för att återta känsliga dokument som hotar rikets säkerhet.",h="The Tome of Divinity är ett viktigt uppdrag i träningen av paladiner i Alliansen som vill bevisa sin...",kw={"defias rogue wizards","defias script","elwynn forest","gazin tenorm","henze faulk","heroes' vigil","paladinuppdrag","tome of divinity"},ang={["class:Paladin"]="The Tome of Divinity är en central prövning av hängivenhet och mod för unga paladiner. Den testar deras beslutsamhet att skydda oskyldiga och försvara Ljuset mot hot som Defias Brotherhood.",["faction:Alliance"]="När du avslöjar Defias rörelser och dokument i Elwynn Forest kan du ge Stormwinds försvarare viktiga underrättelser."},sec={{t="En paladins prövning",b="The Tome of Divinity är en avgörande övergångsrit för paladiner under träning. I den här prövningen måste en novis hitta Henze, en allierad som skadats medan han bevakade olaglig verksamhet på en ö i Elwynn Forest, och hjälpa till att avslöja omfattningen av Defias lokala infiltration."},{t="Infiltratörer i Elwynn",b="Henze upptäcker Defias Rogue Wizards när de granskar hemliga dokument på ön, men han är för illa tilltygad för att själv strida mot dem. Han ger novisen i uppdrag att besegra dessa förrädiska magiker och återta deras skrift för att avslöja deras planer, innan underrättelserna förs säkert tillbaka till Gazin Tenorm i Stormwind."},{t="Försvara kungariket",b="När du säkrar Defias Script bekräftas att brödraskapet utgör ett aktivt hot mot närliggande områden som Heroes' Vigil. När du återlämnar de stulna underrättelserna till Cathedral of Light bevisar du både novisens hängivenhet till Ljuset och att Henze har överlevt."}},faq={{q="Vilka är inblandade i det här uppdraget?",a="Det här steget i uppdragskedjan börjar när du hittar Henze Faulk, som är skadad på en ö i Elwynn Forest, och avslutas när du rapporterar tillbaka till Gazin Tenorm i Cathedral of Light i Stormwind.",al={"vem ger uppdraget","vem ger tome of divinity","var får jag tome of divinity"}},{q="Vem är Henze?",a="Henze är en allierad med anknytning till paladinernas prövningar, som skadades när han höll uppsikt över Defias verksamhet. Han kan inte själv strida, men hänvisar äventyrare till bevis på brödraskapets infiltration.",al={"vem är henze","henze faulks bakgrund","vem är den skadade mannen"}},{q="Vem är Gazin Tenorm?",a="Gazin Tenorm är Henzes vän och vän till Duthorian Rall. Du hittar honom nära altaret i Stormwinds Cathedral of Light. Han undkom med knapp nöd Defias vid Heroes' Vigil och vill få besked om att Henze är i säkerhet.",al={"vem är gazin tenorm","var finns gazin tenorm","gazin i stormwind"}},{q="Varför verkar Defias Rogue Wizards på ön?",a="Defias Brotherhood har etablerat positioner runt om i Elwynn Forest och använder förrädiska magiker för att studera planer och samordna operationer. Dokumenten de bär på innehåller direkta bevis på deras avsikter i regionen.",al={"varför finns defias i elwynn","defias rogue wizards","defias script"}},{q="Vad är Heroes' Vigil?",a="Heroes' Vigil är en plats i Elwynn Forest som hotas av Defias operationer. Gazin Tenorm hoppas att om de närliggande förrädiska magikerna oskadliggörs och deras dokument säkras, kan platsen skyddas från ytterligare skada.",al={"vad är heroes vigil","heroes vigil i elwynn","är heroes vigil säkert"}},{q="Vad är Defias Script?",a="Defias Script består av skriftliga order eller brev som bärs av Defias Rogue Wizards. De bevisar infiltrationen och beskriver deras närmaste planer i Elwynn Forest.",al={"vad är defias script","vad är det för dokument","defias dokument i elwynn"}}},fp="20,291,17.276.0,22.313.1,21.248.1,30.203.0,13.207.0,20.199.0,53.217.0,22.204.0,26.182.0"}
P.entries["quest:1788"] = {n="The Tome of Divinity",s="The Tome of Divinity är ett avgörande trosprov för paladiner i Stormwind. Genom att visa att de behärskar den heliga Symbol of Life och återuppliva en fallen bundsförvant får en novis Duthorian Ralls högtidliga välsignelse att återuppväcka döda.",h="The Tome of Divinity är ett avgörande trosprov för paladiner i Stormwind.",kw={"duthorian","duthorian rall","henze","paladin","återuppståndelse","stormwind","symbol of life","the tome of divinity","gudomlighetens bok"},ang={["class:Paladin"]="Detta prov markerar en paladins övergång till verklig tjänst åt Ljuset och bemästrandet av den heliga kraft som återför fallna följeslagare till livet.",["faction:Alliance"]="Stormwinds paladiner tränas under Cathedral of Light och stärker kungarikets försvar genom att rädda livet på Alliansens försvarare."},sec={{t="Återvänd till Cathedral",b="Efter att ha klarat ett prov ute i fält och använt Symbol of Life för att återuppliva den fallne Henze återvänder en blivande paladin till Cathedral of Light i Stormwind. Defias-dokumenten från ön ska lämnas till kungens rådgivare via Gazin Tenorm, men först väntar Duthorian Rall på besked om novisens framgång."},{t="Återuppståndelsens gåva",b="Att åkalla Ljuset för att återföra döda till livet är ingen förmåga man får lättvindigt. Enligt Duthorian Rall visar en lyckad kanalisering av Symbol of Life att en novis har den tro och andliga styrka som krävs för en av paladinordenens främsta uppgifter: återuppståndelsens kraft. När paladinen behärskar denna rit är hen redo att skydda bundsförvanter på framtida slagfält runt om i kungariket."}},faq={{q="Vad är The Tome of Divinity?",a="The Tome of Divinity är ett avslutande prov för paladiner som lär sig att använda det heliga Ljuset. I detta skede återvänder novisen till Duthorian Rall efter att ha visat sig kunna kanalisera Ljuset för att återföra de fallna till livet.",al={"the tome of divinity","vad är det här för uppdrag","the tome of divinity paladin"}},{q="Vem är Duthorian Rall?",a="Duthorian Rall är en högt uppsatt paladintränare vid Cathedral of Light i Stormwind. Han leder paladinnovisernas utveckling och bedömer om de är redo att använda heliga riter.",al={"vem är duthorian","duthorian ralls roll","var finns duthorian"}},{q="Vad är Symbol of Life?",a="Symbol of Life är ett heligt fokus som används för att åkalla Ljuset och återställa livet hos de döda. Att visa att man kan kanalisera dess kraft bevisar att en novis är redo att behärska paladinens förmåga att återuppväcka döda.",al={"symbol of lifes syfte","vad gjorde symbol of life"}},{q="Vem var Henze?",a="Henze är en bundsförvant som föll i fält och återupplivades med Symbol of Life under novisens prov. Det visade att paladinen hade den beslutsamhet och tro som krävdes för att vända döden.",al={"vem är henze","henzes bakgrund","henze paladinuppdrag"}},{q="Hur får en paladin kraften att återuppväcka döda?",a="Återuppståndelse räknas som en av paladinens högsta hedersbetygelser. Genom att stämma sig direkt med det heliga Ljuset och visa djup tro lär sig en paladin att kalla fallna följeslagare tillbaka från dödens tröskel.",al={"paladiners återuppståndelse","hur återupplivar paladiner"}},{q="Varför förs dokumenten till kungens rådgivare?",a="Dokumenten är Defias-papperen som togs från ön. Gazin Tenorm ska föra dem till kungens rådgivare när Duthorian Rall har granskat dem. De bevisar att Defias har infiltrerat Elwynn.",al={"kungens rådgivare dokument","vilka dokument ska till stormwind"}}},fp="20,242,23.333.0,24.407.0,29.228.0,22.192.0,27.213.0,14.206.0,50.207.0,53.198.0"}
P.entries["quest:179"] = {n="Dwarven Outfitters",s="Dwarven Outfitters är en inledande överlevnadsuppgift i Coldridge Valley som Sten Stoutarm ger. Som belöning får nyrekryteringar stadiga handskar som skyddar mot köldskador i Dun Moroghs bitande kyla, i utbyte mot att de jagar lokala vargar och samlar deras sega kött till vinterransoner.",h="Dwarven Outfitters är en inledande överlevnadsuppgift i Coldridge Valley som Sten Stoutarm ger.",kw={"anvilmar","coldridge valley","dun morogh","dwarven outfitters","köldskador","handskar","sten stoutarm","tough wolf meat"},ang={["race:Dwarf"]="För unga Bronzebeard-dvärgar som ger sig ut i Coldridge Valley blir uppgiften en tidig läxa i att klara sig själv i gränslandet: gör rätt för dig, bidra till lägret och visa respekt för bergskylan.",["race:Gnome"]="Efter att ha sökt skydd hos sina dvärgkusiner i Dun Morogh upptäcker gnomer snabbt att överlevnad i Anvilmar kräver praktiska bergskläder lika mycket som skarpt intellekt."},sec={{t="En rättvis byteshandel i Coldridge",b="Det höga bergspasset i Coldridge Valley är brutalt kallt, och oförberedda resenärer inser snabbt att vanlig utrustning inte räcker mot vädrets makter. Utanför Anvilmar erbjuder Sten Stoutarm nyrekryteringar en enkel gränslandsaffär: ge dig ut i snödrivorna, jaga de strövande vargarna och ta med bitar av segt kött som proviant till utposten. I gengäld ger han dig ordentliga handskar för kallt väder, så att unga äventyrare får behålla alla tio fingrar."},{t="Livnära sig på dalen",b="Vargar utgör ett ständigt hot mot dvärgspanare och de unga gnomer som tränar i dalen, men de är också en viktig resurs. Köttet håller garnisonen i Anvilmar mätt, och när vargarna blir färre blir stigarna mellan de lokala lägren något säkrare. Stoutarms överenskommelse fyller två syften: den prövar om en rekryt kan hantera det lokala djurlivet och samlar samtidigt mat inför de bittra nätterna som väntar."}},faq={{q="Vem är Sten Stoutarm?",a="Sten Stoutarm är en dvärg som är stationerad utanför Anvilmar i Coldridge Valley. Han håller utkik efter nyanlända rekryter och ser till att de har rätt utrustning för att överleva den iskalla väderleken i Dun Morogh. I utbyte mot att de jagar lokalt vilt får de praktisk utrustning.",al={"sten stoutarm","vem ger dwarven outfitters","utrustningshandlare i anvilmar"}},{q="Varför behöver Sten vargkött?",a="Utposten i Anvilmar förlitar sig på lokal jakt för att hålla förråden fyllda. Vargkött ger mättande och pålitlig proviant åt trupperna och tränarna som bor i den avlägsna, snötäckta dalen.",al={"varför vargkött","tough wolf meat","vad ska köttet användas till"}},{q="Var hittar du vargarna till uppgiften?",a="Vargar strövar omkring på de snötäckta gläntorna i hela Coldridge Valley, särskilt strax bortom Anvilmars huvudgård och längs stigarna mot de avlägsna lägren.",al={"var finns vargar","vargplatser i coldridge","var får man tag på kött"}},{q="Vilken belöning ger Sten?",a="Sten belönar rekryter med ett par pålitliga, varma handskar som är särskilt utformade för att motverka köldskador och skydda en krigares händer mot Dun Moroghs bittra vindar.",al={"belöning för dwarven outfitters","vilka handskar får man","uppdragsbelöning"}},{q="Anses vargkött vara god mat bland dvärgar?",a="Tough Wolf Meat är grovt och segt, men i Dun Moroghs kärva bergsklimat prioriterar dvärgar mättande och rejäl mat framför gourmetmåltider. Kokt eller grillat över en lägereld gör det god nytta för garnisonen.",al={"är vargkött gott","dvärgarnas vargkött","äta vargkött"}},{q="Kan gnomer också göra det här uppdraget?",a="Ja. Gnomer som tränar sida vid sida med sina dvärgallierade i Coldridge Valley utsätts för samma bitande vindar och behöver varma kläder lika mycket.",al={"gnomer och dwarven outfitters","kan gnomer få handskar","gnomer i kallt väder"}}},fx={cf6e8786={q="Vad gör vargarna i Coldridge Valley?",a="Skrangliga unga vargar och skrangliga timmervargar strövar omkring bland de frusna klipporna i Coldridge Valley som områdets naturliga rovdjur. De hör hemma i Dun Moroghs karga bergsmiljö, men deras aggressiva strykande precis utanför Anvilmar är ett ständigt bekymmer för unga rekryter och en bekväm källa till färska förnödenheter för utposten.",al={"varför finns det vargar här","vargar i coldridge valley","vargarnas hot i dun morogh"}}},fp="18,184,25.262.0,21.304.0,21.174.0,29.154.0,43.147.0,30.96.0,48.192.0,29.122.0"}
P.entries["quest:1791"] = {n="The Windwatcher",s="Krigare som har bemästrat berserkerställningen skickas norrut för att hitta The Windwatcher. Efter striden på Fray Island visar Klannoc Macleod dem vägen till ett vapen värdigt deras raseri.",h="Krigare som har bemästrat berserkerställningen skickas norrut för att hitta The Windwatcher.",kw={"alterac mountains","bath'rah","berserkerställning","cyclonian","fray island","klannoc macleod","tarren mill","the affray","the windwatcher"},ang={["class:Warrior"]="Som krigare har du bemästrat berserkerställningen på Fray Island och söker nu ett kraftfullt vapen smitt genom elementär konst.",["race:Troll"]="Som troll kan du se hur trollschamaner och vapensmeder bevarar mystisk kunskap bland Lordaerons sönderslagna ruiner, en kunskap som krigare av alla börder vördar."},sec={{t="Ett vapen åt en berserker",b="Du har överlevt striden på Fray Island och lärt dig berserkerställningen av Klannoc Macleod. Nu skickar Klannoc dig långt bort från The Barrens kust, över kontinenter, för att hitta en ensam hantverkare som kan smida ett enastående vapen."},{t="Eremiten vid flodstranden",b="Bath'rah the Windwatcher bor intill floden som rinner norrut förbi Tarren Mill. Hans läger ligger bland stenruiner i det omstridda landet mellan Alterac Mountains och det pesthärjade Western Plaguelands. Troll-eremiten smider vapen och behärskar kraftfull elementär schamanism. Han väntar på krigare som är fast beslutna att smida ett vapen med stor kraft."}},faq={{q="Vem skickar dig för att hitta Windwatcher?",a="Klannoc Macleod skickar dig norrut efter att du överlevt striden på Fray Island och lärt dig berserkerställningen.",al={"uppdragsgivare","vem ger uppdraget the windwatcher","klannoc macleods uppdrag"}},{q="Vem är Bath'rah the Windwatcher?",a="Bath'rah är en troll-eremit, en mästersmed och en mäktig schaman som lever i vildmarken mellan Alterac Mountains och Western Plaguelands.",al={"vem är bathrah","bathrah the windwatcher bakgrund","bath'rahs identitet"}},{q="Var befinner sig Bath'rah exakt?",a="Bath'rah slår läger nära forntida ruiner på flodens östra strand, där den rinner norrut förbi Tarren Mill, nära gränsen till Alterac och Western Plaguelands.",al={"var finns bath'rah","bathrahs plats","hitta bathrah"}},{q="Varför skickar Klannoc krigare till Bath'rah?",a="Klannoc skickar krigare till Bath'rah eftersom de som bemästrar berserkerställningen behöver ett enastående vapen, och Bath'rah kan både smide och elementär schamanism.",al={"varför gå till bathrah","vad är syftet med uppdraget","syftet med windwatcher"}},{q="Vad händer efter att du har talat med Bath'rah?",a="När du har talat med Bath'rah ställs du mot elementaren Cyclonian och samlar sällsynta material för att tillverka ett kraftfullt vapen.",al={"vad händer efter windwatcher","nästa uppdrag efter cyclonian","fortsättning på windwatcher"}},{q="Är resan säker för en resenär från The Barrens?",a="Resan är farofylld. Du färdas genom Hillsbrad Foothills till omstridda nordliga länder, där Syndicate-gömställen, aggressiva rovdjur i bergen och Western Plaguelands dödliga pesthotar dig.",al={"är det farligt","faror vid floden nära tarren mill"}}},fx={ff43a27e={q="Varför skickar Klannoc dig till Bath'rah i stället för att själv bege sig dit?",a="Klannoc Macleod är inte ute efter en legendarisk beväpning åt sig själv; han är en erfaren mentor på Fray Islands prövningsmarker. Han har sett dig överleva Affray och bemästra berserkställningen och tror att du är redo för ett vapen som motsvarar ditt nyväckta raseri. Den långa färden till eremiten Bath'rah på avlägsen ort prövar en krigares egen beslutsamhet och utveckling.",al={"varför jag i the windwatcher","varför skicka krigaren","varför skickar klannoc spelaren"}}},fp="15,186,24.233.0,27.344.0,38.107.0,32.151.0,34.157.0,43.166.0,40.115.1,60.218.0"}
P.entries["quest:1792"] = {n="Whirlwind Weapon",s="Uppdraget Whirlwind Weapon innebär att krigarens vapen får sin slutliga kraft genom Whirlwind Heart från elementaren Cyclonian. När besten binds till ett utvalt vapen får bäraren själva stormens väsen och raseri. Det är en milstolpe i vapenkonsten.",h="Uppdraget Whirlwind Weapon innebär att krigarens vapen får sin slutliga kraft genom Whirlwind Heart från...",kw={"cyclonian","elementar","storm","vapen","krigarvapen","whirlwind heart","whirlwind weapon"},ang={["class:Warrior"]="Att vinna ett Whirlwind-vapen är en legendarisk övergångsrit för krigare och ger dem ett vapen fyllt med Cyclonians stormande kraft."},sec={{t="Stormens kraft",b="Uppdraget Whirlwind Weapon är slutprovet i styrka och vapenkonst. Efter att ha besegrat elementarstormen Cyclonian och hämtat dess instabila kärna förbereder en krigare ett fysiskt kärl för stormens urkrafter. Hantverkaren står redo att förena varelsens virvlande hjärta med det utvalda vapnet och förvandla enkelt smitt stål till en legendarisk kanal för elementarisk vrede."},{t="Cyclonians kraft",b="Cyclonians hjärta rymmer de rytande vindarnas och stormbyarnas tygellösa våld. När kärnan fästs i ett smitt vapen behärskar bäraren både sin egen krigskonst och stormens levande kraft. Varje slag genljuder av den besegrade elementarens styrka, och Cyclonians storm fortsätter att rasa i segrarens händer."}},faq={{q="Vad är uppdraget Whirlwind Weapon?",a="Whirlwind Weapon är kulmen på en krigares prövning mot elementarkrafter. Genom att ta Whirlwind Heart från Cyclonian väljer krigaren ett vapen som ska fyllas med elementarens fångade väsen och bli ett vapen med oerhörd urkraft.",al={"vad är whirlwind weapon","lore om whirlwind weapon","vad är det här för uppdrag"}},{q="Vem är Cyclonian?",a="Cyclonian är en mäktig manifestation av vind och storm. När denna stormande varelse besegras får man Whirlwind Heart, som binder vindens urkrafter direkt till ett fysiskt vapen.",al={"vem är cyclonian","cyclonians bakgrund","vad är cyclonian"}},{q="Vad är Whirlwind Heart?",a="Whirlwind Heart är kärnan som fås från den besegrade elementaren Cyclonian. Den rymmer stormens råa vrede och kan bindas till ett smitt vapen som krigaren själv väljer.",al={"vad är whirlwind heart","cyclonians hjärta","hjärtat hos cyclonian"}},{q="Hur får vapnet sin kraft?",a="Ett whirlwind-vapen skapas genom att Whirlwind Heart kanaliseras in i ett utvalt vapen. Processen binder Cyclonians elementarvrede direkt till stålet och fyller varje slag med vindkraft.",al={"hur tillverkas whirlwind weapon","valfritt vapen","smida whirlwind weapon"}},{q="Vilka vapen kan man välja?",a="Krigaren kan välja vilket vapen som ska ta emot Cyclonians stormväsen och anpassa elementarkraften efter sin föredragna stridsstil och vapentyp.",al={"vilket vapen kan jag välja","val av whirlwind-vapen","vilka vapen erbjuds"}},{q="Varför söker man Cyclonians kraft?",a="Krigare söker denna kraft eftersom Cyclonians kärna låter dem styra en levande stormvinds våldsamma raseri och förvandla vapenslag till förödande elementarkrafter.",al={"varför vill krigare ha whirlwind weapon","whirlwind weapons betydelse"}}},fp="16,314,18.433.0,22.393.0,35.268.0,17.231.0,28.202.0,28.220.0,40.178.0,38.190.0"}
P.entries["quest:1793"] = {n="The Tome of Valor",s="Tome of Valor är ett grundläggande prov för alliansens paladiner som börjar finna sin plats. Paladinmentorer i Stormwind och Ironforge leder provet, där noviser måste visa att deras mod och hängivenhet att skydda oskyldiga motsvarar deras stridsförmåga.",h="Tome of Valor är ett grundläggande prov för alliansens paladiner som börjar finna sin plats.",kw={"cathedral of light","duthorian rall","heliga ljuset","ironforge","paladinprov","silver hand","tiza battleforge","tome of valor"},ang={["class:Paladin"]="Denna övergångsrit markerar steget från en enkel akolyt till en betrodd försvarare av det heliga ljuset och utmanar dig att sätta osjälvisk plikt framför din egen säkerhet.",["faction:Alliance"]="Prövningarna i Tome of Valor förbereder förkämpar på att försvara alliansens bosättningar mot växande hot, från lokala banditer till monstruösa inkräktare.",["race:Dwarf"]="Paladinerna i Ironforge, ledda av mentorer som Tiza Battleforge, ser Tome of Valor som ett bevis på att dvärgarnas tålighet stärks av ett heligt syfte.",["race:Human"]="Prövningen, som hålls under Duthorian Ralls vakande öga i Cathedral of Light, speglar Stormwinds orubbliga hängivenhet till Silver Hands grundideal."},sec={{t="En paladins måttstock",b="Att använda det heliga ljuset i strid kräver mer än tung rustning och vapendisciplin. När unga paladiner når längre i sin träning kräver lärare i Cathedral of Light och Hall of Mysteries bevis på deras inre styrka. Lärdomarna i Tome of Valor prövar om en novis är redo att möta fasansfull ondska, från drakar till demoner, utan att vackla eller överge dem som inte kan försvara sig själva."},{t="Ordens dygder",b="Mod inför livsfara anses lika viktigt för en helig krigare som vapen och sköld. Genom prövningarna i Tome of Valor lär sig paladiner att rå styrka är tom utan ett orubbligt löfte att skydda de hjälplösa. Att möta verklig fara säkerställer att alliansens försvarare står stadigt när mörkret faller, i stället för att brytas ned."}},faq={{q="Vad är syftet med Tome of Valor?",a="Tome of Valor är en övergångsrit för blivande paladiner i alliansen. De heliga ljusets mentorer har utformat den för att säkerställa att en novis har genuint mod och en osjälvisk vilja att skydda de utsatta innan hen avancerar inom orden.",al={"vad är tome of valor","syftet med tome of valor","varför göra tome of valor"}},{q="Vem leder paladinerna genom prövningen?",a="Noviser kallas vanligtvis till prövningen av äldre paladiner i alliansens huvudstäder, såsom Duthorian Rall i Cathedral of Light i Stormwind eller Tiza Battleforge i Hall of Mysteries i Ironforge.",al={"vem ger tome of valor","uppdragsgivare för tome of valor","vem startar tome of valor"}},{q="Vart leder prövningen?",a="Den första kallelsen är inkörsporten till en rad särskilda uppgifter som prövar paladinens beslutsamhet och driver ut hen i fält för att möta verklig fara till försvar av riket och de oskyldiga.",al={"vad kommer efter tome of valor","fortsättning på tome of valor","uppdragskedja för tome of valor"}},{q="Varför betonas mod så starkt hos paladiner?",a="Det heliga ljuset svarar på tro och vilja. När man möter överväldigande fasor som demoner eller drakar kan rädslan krossa en krigares själ. Mod säkerställer att en paladin förblir en stadig sköld för andra, även under de allra värsta omständigheterna.",al={"varför tapperhet","varför mod är viktigt för paladiner"}},{q="Genomgår dvärg- och människopaladiner samma prov?",a="Dvärgpaladiner tränar i Ironforge och människor i Stormwinds Cathedral of Light, men båda traditionerna följer samma grundläggande dygder: mod, plikt och att försvara de hjälplösa under ljuset.",al={"är det annorlunda för dvärgar","tome of valor i ironforge","tome of valor i stormwind"}},{q="Vilka grundläggande lärdomar ingår i prövningen?",a="Prövningen kretsar kring tre grundläggande ansvar: att bemästra orubbligt mod oavsett oddsen, aktivt skydda de svaga från skada och bevara tron när man möter skräck.",al={"lärdomar från tome of valor","vad lär tome ut"}}},fx={["81822402"]={q="Varför vill paladinmästarna att du genomgår den här prövningen?",a="Tiderna blir allt farligare i Azeroth, där hotande ondska som demoner och drakar lurar. Du har redan bevisat att det heliga ljuset svarar på din kallelse, men Duthorian Rall och Tiza Battleforge vet att ren tro inte räcker. De måste pröva din styrka och försäkra sig om att du har det orubbliga mod som krävs av en sann paladin innan större faror drabbar ditt hemland.",al={"varför genomgå prövningen","duthorian ralls motiv","varför tiza battleforge prövar"}},f91e68e3={q="Varför måste du genomgå den här prövningen i stället för äldre paladiner eller vakter?",a="Den här resan är ingen försvarsuppgift som stadsvakter eller erfarna riddare kan sköta åt dig. Den är en personlig övergångsrit. Mästarna måste se hur din egen själ står pall när du möter motgångar och pröva din förmåga att skydda de svaga, hålla fast vid din tro och stå orubblig inför skräck.",al={"varför jag i tome of valor","varför skicka spelaren för att visa sitt mod","varför kan inte vakterna göra det"}}},fp="17,185,24.393.0,20.264.0,41.213.0,35.207.0,27.154.0,50.153.0,52.176.0,44.106.0"}
P.entries["quest:1795"] = {n="The Binding",s="Ovanför Ratchet ställs häxmästare inför ritualen som binder en felfångare till deras vilja. Strahad Farsan övervakar frammaningen med den återställda Tome of the Cabal och drar en aggressiv demon ur Nether för att kuva den i strid.",h="Ovanför Ratchet ställs häxmästare inför ritualen som binder en felfångare till deras vilja.",kw={"the barrens","felhunter","ratchet","strahad farsan","frambesvärjelse","the binding","tome of the cabal","häxmästare"},ang={["class:Warlock"]="Som häxmästare når du en viktig milstolpe när du binder en felfångare. Hunden är ett specialiserat antimagiskt rovdjur som kan sluka besvärjelser och oskadliggöra fientliga magiker.",["faction:Alliance"]="Som häxmästare i Alliance reser du från Stormwind över havet till det neutrala Ratchet, där Strahad övervakar den livsfarliga frammaningsritualen.",["faction:Horde"]="Som häxmästare i Horde färdas du in i hjärtat av The Barrens för att bevisa din dominans över Nether och binda hunden inför Strahad på neutral mark."},sec={{t="The Cabals cirkel",b="På Kalimdors klippor ovanför goblinhamnen Ratchet utför Strahad Farsan farliga prövningar i demonframmaning. När en häxmästare har samlat fragmenten och reagenserna som krävs för att återställa den uråldriga Tome of the Cabal förbereder Strahad bindningsplatsen. Han lägger en inre skyddsglyf, medan hans lärjungar kanaliserar kraft genom förtrollade stavar för att sluta den yttre cirkeln. Cirklarna håller allt som framträder avskilt från bosättningen nedanför."},{t="Kuva jägaren",b="Tome of the Cabal innehåller besvärjelserna som öppnar en bro till Twisting Nether. Felfångare är glupska demoniska hundar som hungrar efter arkansk kraft och festar på magisk energi. Ingen varsam förtrollning eller övertalning kan binda en. Häxmästaren måste kuva och bryta det frammanade odjuret med våld i strid, innan det erkänner sin rättmätiga mästare. Att överleva sammanstötningen visar att den som frammanat besten kan använda den mot fiendens besvärjare."}},faq={{q="Vad är syftet med den här ritualen?",a="Ritualen låter en häxmästare frammana en felfångare och binda den till sin vilja. När häxmästaren läser ur den färdigställda Tome of the Cabal i Strahad Farsans frammaningscirkel dras demonen ur Nether. Häxmästaren måste besegra den i strid och vinna dess tjänst för alltid.",al={"varför göra det här uppdraget","målet med felhunter-uppdraget","bindningens syfte"}},{q="Vem är Strahad Farsan?",a="Strahad Farsan är en skicklig mänsklig häxmästare som verkar från ett torn ovanför Ratchet i The Barrens. Hans omfattande kunskaper i mörka frammaningskonster får mentorer från både Alliance och Horde att i hemlighet skicka sina mest lovande utövare till honom för att studera avancerade bindningsritualer.",al={"vem är strahad","strahad farsans bakgrund","uppdragsgivaren strahad"}},{q="Varför måste en häxmästare döda demonen i stället för att förslava den?",a="En felfångare är ett aggressivt rovdjur som slukar magi och respekterar total dominans. Utövaren måste besegra den i fysisk och magisk strid, bryta dess vildsinthet och prägla sin auktoritet på dess ande så att den lyder vid framtida frammaningar.",al={"varför döda felhuntern","kan jag förslava felhuntern","felhunter-strid"}},{q="Kan häxmästare från både Horden och Alliansen utföra ritualen här?",a="Ja. Stegen för att återskapa Tome of the Cabal skiljer sig mellan fraktionerna, men häxmästare från både Alliance och Horde hänvisas till slut till Strahad Farsan ovanför Ratchet för den sista frammaningen.",al={"är det bara för horden","är det bara för alliansen","vem får det här uppdraget"}},{q="Vad händer om felhuntern besegrar besvärjaren?",a="Om den som frammanat besten faller förvisas felfångaren till Nether och ritualen misslyckas. Häxmästare som överlever nederlaget kan hämta ett nytt exemplar av Tome of the Cabal från Strahad och försöka igen när de är ordentligt förberedda.",al={"vad händer om jag dör","när bindningen misslyckas","kan jag försöka ritualen igen"}},{q="Vad gör felhunters unika jämfört med andra demoner?",a="Felfångare är demoniska hundar som jagar genom att känna av magiska emanationer. De förlitar sig mindre på råstyrka eller skuggmagi. I stället vädrar de upp trolldom, slukar aktiva förtrollningar och stör fiendens besvärjare. Det gör dem till värdefulla följeslagare mot rivaliserande magiker.",al={"vad gör en felhunter","felhunters bakgrund","varför felhunters"}}},fx={b1095368={q="Varför vill Strahad Farsan att du ska frammana en feljägare?",a="Strahad Farsan använder dig inte för att uträtta ett ärende – han tränar dig i att bemästra mäktigare demonisk magi. Han anser att varje häxmästare bör ha en feljägare till sitt förfogande, eftersom varelsens störande krafter vida överträffar faran med att binda den. Han har väglett dig när du samlat ihop materialet och Tome of the Cabal. Nu vill han pröva din potential och se om du överlever provet och kan räknas bland tidens mest formidabla utövare.",al={"varför vill strahad ha det här","strahad farsans motiv","varför frambesvärja feljägare åt strahad"}},["44d888c5"]={q="Varför måste du själv möta feljägaren i stället för att Strahad gör det?",a="En frambesvärjd demon kan inte besegras åt dig. För att kuva en tjänare från Twisting Nether måste du bevisa din egen vilja och dominans över varelsen. Om Strahad eller hans adepter besegrade den skulle det inte skapa något tjänsteband till dig. Strahad och hans medhjälpare använder de större besvärjelsecirklarna för att hålla inbuktningen i schack, men att bryta bestens vilda styrka i strid är ett prov som bara den blivande härskaren kan utstå.",al={"varför kan inte strahad slåss mot den","varför måste jag döda feljägaren","varför måste jag slåss ensam mot demonen"}},["6bf7b15d"]={q="Vad är den frambesvärjda feljägaren, och varifrån kommer den?",a="Du möter en grym, rovgirig demon som hämtats direkt från Twisting Nether med besvärjelserna i Tome of the Cabal. Feljägare är monstruösa bestar som dras till magiska energier och ivrigt spårar upp, dränerar och stör dem. Eftersom de till sin natur är glupska vidunder kommer varelsen som dras in i besvärjelsecirkeln genast att anfalla dig när den tar fysisk form. Du måste övermanna den i strid innan dess ande kan bindas till din tjänst.",al={"vad är den frambesvärjda feljägaren","vad slåss jag mot","feljägarens bakgrund"}}},fp="11,219,18.445.0,22.441.0,35.259.0,22.296.0,66.251.0,62.188.0,51.213.0,54.277.0"}
P.entries["quest:1796"] = {n="Components for the Enchanted Gold Bloodrobe",s="I Ratchet ber Menara Voidrender häxmästare att hitta Robes of Arcana till ett plagg som ska bära mäktiga förtrollningar.",h="I Ratchet ber Menara Voidrender häxmästare att hitta Robes of Arcana till ett plagg som ska bära mäktiga...",kw={"the barrens","bloodrobe","enchanted gold bloodrobe","menara voidrender","robes of arcana","skrädderi","häxmästaruppdrag"},ang={["class:Warlock"]="Som häxmästare lär du dig genom att skapa Enchanted Gold Bloodrobe att bygga mäktiga artefakter på en stark och noggrant förberedd grund.",["profession:Tailoring"]="Som skräddare behöver du det sällsynta mönstret till Robes of Arcana och färdighet i att arbeta med spindelsilke och många bultar fint silke.",["race:Orc"]="Som orcisk häxmästare ger insamlingen av material till diskreta dräkter dig ett stillsammare sätt att bemästra kaosenergi, långt från nyfikna blickar och skuggan av ditt folks demoniska förflutna.",["race:Undead"]="Som Förfallen kan du resa långt till de solblekta Barrens för att lära dig av Menara och stärka ditt skröpliga dödliga hölje mot dina oberäkneliga konster."},sec={{t="En behållare för mystisk kraft",b="Menara Voidrender ber häxmästare som söker större makt att skaffa henne ett set Robes of Arcana. Hon vill ha ett plagg starkt nog att hålla mörk magi. En magisk reliks styrka beror på materialens kvalitet, sällsynthet och arbetet som lagts ner på dem. Vanliga trasor skulle inte tåla djupa förtrollningar, så dräkten måste vara välgjord och redo att ta emot dem."},{t="Hantverk och ambition",b="Menara beundrar häxmästare som kan väva dräkten själva, men ambition betyder mer för henne än stolthet. Du kan sy silket, anlita en skicklig hantverkare eller köpa dräkten på marknaden. Oavsett hur du får tag på den är det färdiga plagget redo att bli ett specialiserat redskap för att bemästra kaosmagi."}},faq={{q="Varför behöver Menara Voidrender just Robes of Arcana?",a="Mäktiga förtrollningar kräver ett plagg gjort med skicklighet och sällsynta material. Menara använder Robes of Arcana som en mottaglig grund för krafterna hon tänker binda till plagget.",al={"varför robes of arcana","varför den här manteln","mantelns syfte"}},{q="Var finns Menara Voidrender?",a="Menara Voidrender bor i Ratchet, goblinernas hamn i The Barrens. Hon vägleder häxmästare som vill utveckla sitt hantverk och skapa specialiserad utrustning.",al={"menara voidrender plats","var finns menara","menara voidrender var"}},{q="Måste jag själv sy Robes of Arcana?",a="Nej. Menara uppskattar arbetet med att göra dräkten själv, men godtar också en som skaffats genom handel eller köpts av en annan hantverkare. Du kan få tag på den på vilket praktiskt sätt som helst.",al={"måste jag kunna skrädderi","kan jag köpa manteln","krävs skrädderi"}},{q="Varifrån kommer mönstret till Robes of Arcana?",a="Mönstret är sällsynt och kan hittas hos kultister och mörka magiker. Dark Strand Voidcallers vid Tower of Althalaxx i Darkshore och Defias Enchanters i Duskwood är några av dem som bär på det.",al={"robes of arcana-mönster","hur får jag mönstret","var finns skrädderireceptet"}},{q="Vad händer med Robes of Arcana när jag lämnar in dem?",a="Menara tar emot dräkten som material för den efterföljande ritualen där den genomsyras av magi. Om du bär den när du lämnar över den till henne tar hon av dig den genast, så att du står utan bröstskydd tills de senare stegen är klara.",al={"förlorar jag manteln","manteln försvunnen","vad händer med manteln"}},{q="Vad är Enchanted Gold Bloodrobe?",a="Enchanted Gold Bloodrobe är ett specialiserat plagg för häxmästare av mellangrad. Mörka komponenter och skyddande förtrollningar stärker bärarens motståndskraft och förråd av mörk energi.",al={"vad är bloodrobe","bloodrobe-bakgrund","enchanted gold bloodrobe"}}},fx={["44990969"]={q="Varför vill Menara Voidrender att det här ska göras?",a="Menara Voidrender vägleder ambitiösa häxmästare mot större mästerskap i de mörka konsterna. Hon vill inte ha en mantel till sin egen garderob, utan prövar ditt engagemang och din påhittighet samtidigt som hon lär dig att smida kraftfulla häxmästarplagg. När lovande utövare får kanalisera vildekrafter genom skräddarsydda fokus stärks deras skuggkonst.",al={"varför hjälper menara mig","menara voidrenders motiv","varför sy kläderna"}}},fp="43,118,18.352.0,18.280.0,61.172.0,35.149.0,47.172.0,53.196.0,58.211.0,37.187.0"}
P.entries["quest:1798"] = {n="Seeking Strahad",s="Häxmästare lämnar Stormwind City för Ratchet, där Strahad Farsan kan lära dem att frammana felhunters. Under goblinhamnen erbjuder hans kunskap en väg till farligare demonbesvärjelser.",h="Häxmästare lämnar Stormwind City för Ratchet, där Strahad Farsan kan lära dem att frammana felhunters.",kw={"felhunter","gakin the darkbinder","ratchet","seeking strahad","stormwind","strahad farsan","the barrens","krigslock"},ang={["class:Warlock"]="Som häxmästare når du en milstolpe när du lämnar enklare djävlar och succubi bakom dig och lär dig frammana den listiga, magidränerande felhuntern.",["faction:Alliance"]="Som häxmästare i Alliance korsar du Great Sea och tar dig in i Kalimdors oländiga, Horde-dominerade inland för att nå Strahad."},sec={{t="En kallelse över havet",b="Gakin the Darkbinder skickar dig från Stormwind för att söka hjälp med att frammana en felhunter. Han vägleder häxmästare i Slaughtered Lamb, nedanför Mage Quarter, men ritualerna kräver kunskap utöver vad han kan erbjuda där. Din resa för dig över Great Sea till Kalimdor, där en annan häxmästare kanske känner till vägen."},{t="Ermiten i Ratchet",b="Strahad Farsan bor i de torra kullarna ovanför Ratchet, goblinernas hamn. Han är en mänsklig häxmästare och jämlike till Gakin i deras hemliga kabal. Från neutralt territorium kan Strahad verka utan att dra till sig uppmärksamhet från Alliancens magistrater, kyrkans inkvisitorer och Hordens vaktposter. Häxmästare kommer till honom i hopp om att bemästra demoner som dränerar mana."}},faq={{q="Vem skickar dig för att hitta Strahad?",a="Gakin the Darkbinder skickar dig från Slaughtered Lamb i Stormwinds Mage Quarter när du är redo att lära dig frammana en felhunter.",al={"vem ger uppdraget seeking strahad","uppdragsgivare","gakin"}},{q="Var finns Strahad Farsan?",a="Strahad Farsan bor i The Barrens, på höjderna med utsikt över Ratchet, goblinhamnen.",al={"strahads plats","var finns strahad","hitta strahad"}},{q="Varför måste en krigslock från Alliansen resa ända till The Barrens?",a="Gakin kan inte tillhandahålla den kunskap och de material som behövs för felhunter-ritualerna i Stormwind. Strahad Farsan har den kunskapen och verkar från neutralt territorium nära Ratchet, utom räckhåll för lokal insyn.",al={"varför åka till the barrens","varför kalimdor","varför ratchet"}},{q="Vilken förmåga leder uppdraget till att låsa upp?",a="När du talar med Strahad inleds en uppdragskedja som leder till Tome of the Cabal och bindningsritualen för att frammana en felhunter som följeslagare.",al={"vilket husdjur är uppdraget till","vad får jag","felhunteruppdrag"}},{q="Är Strahad Farsan fientligt inställd till Horden?",a="Nej. Strahad bor i neutralt goblinterritorium och lär Alliance- och Horde-häxmästare att frammana felhunters, samtidigt som han håller kontakt med olika kabaler.",al={"är strahad bara för alliansen","horden strahad"}},{q="Vad händer när du har talat med Strahad?",a="Strahad ber dig samla ihop komponenterna till en bindningsritual. Därmed inleds en uppdragskedja som handlar om Tome of the Cabal.",al={"nästa uppdrag","vad händer efter seeking strahad","tome of the cabal"}}},fx={["034d02a4"]={q="Varför vill Gakin the Darkbinder att du ska söka upp Strahad?",a="Gakin bedömer att du har blivit mäktig nog att befalla en feljägare, men han saknar de magiska reagenser och ritualkomponenter som behövs för att undervisa dig under Stormwind. För att din träning inte ska stanna av skickar han dig till Strahad Farsan, en betrodd bundsförvant i deras innersta krets som har den nödvändiga kunskapen och tillgång till material på andra sidan havet.",al={"varför skicka mig till strahad","gakin the darkbinders motiv","varför skickar gakin iväg dig"}}},fp="15,190,24.318.0,21.325.0,30.135.0,32.89.0,71.205.0,47.132.0,39.152.0,40.114.0"}
P.entries["quest:18"] = {n="Brotherhood of Thieves",s="Deputy Willem skickar rekryter över Northshires östra flod för att möta Defias Brotherhood. Deras röda bandanor av säckväv ger Stormwind det första konkreta beviset på rövarnas organiserade närvaro i dalen.",h="Deputy Willem skickar rekryter över Northshires östra flod för att möta Defias Brotherhood.",kw={"bandanor","brotherhood of thieves","defias","deputy willem","elwynn","northshire","stormwind-armén"},ang={["class:Rogue"]="För nya skurkar ger Defias en inblick i hur organiserade kriminella nätverk verkar i skuggorna av människornas hjärtland.",["faction:Alliance"]="Stormwinds myndigheter förlitar sig på nyanlända alliansrekryter för att bevara freden i Northshire medan kungarikets reguljära militär är hårt ansträngd.",["race:Human"]="För människor som börjar sin utbildning i Northshire är Defias en hård påminnelse om att säkerheten i kungariket Stormwind håller på att vittra sönder inifrån."},sec={{t="Banditer i dalen",b="Northshire Valley har länge varit en trygg tillflykt i Elwynn Forest, skyddad av Stormwind och använd för att utbilda rekryter och den Heliga Ljusets präster. På senare tid har disciplinen längs dess gräns försämrats. Lösdrivare och tjuvar har korsat den östra floden och lurar nära skogen, där de slår upp små läger nära klostret. Deputy Willem upprätthåller den lokala ordningen, men vakterna har inte manskap nog att hålla uppsikt över varje hörn av dalen utan frivilliga."},{t="Den röda symbolen",b="Dessa laglösa samarbetar och bär likadana kläder. De kallar sig Defias Brotherhood, och deras röda bandanor av säckväv visar deras lojalitet. Deputy Willem skickar rekryter för att driva tillbaka rövarna och återta deras masker, i hopp om att hejda deras framryckning och ta reda på hur djupt Defias har trängt in i kungarikets hjärtland."}},faq={{q="Vilka är Defias Brotherhood?",a="Defias Brotherhood är ett organiserat band av rövare och laglösa som verkar i Elwynn Forest och Westfall. I Northshire betraktas de först som djärva tjuvar, men de bär likadana röda masker av säckväv och följer en samordnad ledning.",al={"vilka är defias","vad är defias brotherhood","defias historia"}},{q="Varför ber Deputy Willem rekryter om hjälp i stället för att använda Stormwind-armén?",a="Stormwind-armén och stadsvakterna är utspridda och har ont om manskap i hela kungariket. Oroligheterna ökar i grannregionerna, och ledningen i Stormwind City är hårt pressad. Därför förlitar sig lokala deputerade på ivriga frivilliga och nya rekryter för att slå tillbaka banditerna.",al={"varför willem behöver hjälp","var är stormwinds vakter","varför ingen armé"}},{q="Varifrån kommer tjuvarna?",a="Tjuvarna har samlats på andra sidan floden, öster om klostret. De smyger omkring i utkanten av lokala gårdar och lägerplatser nära vingården.",al={"var finns banditerna","defias plats northshire"}},{q="Varför bär tjuvarna röda bandanor av säckväv?",a="Den röda bandanan av säckväv visar lojalitet till Defias Brotherhood och döljer varje tjuvs identitet. Den signalerar också deras lojalitet till andra laglösa i människornas områden.",al={"varför röda bandanor","vad röda masker betyder","röd säckväv"}},{q="Vad händer när du har slutfört det här uppdraget?",a="Deputy Willem och lokalbefolkningen inser snart att bandithotet sträcker sig längre in i Northshire. Rekryterna hjälper sedan Milly Osworth med hennes förstörda skörd och letar rätt på Garrick Padfoot, en särskild ledare.",al={"what comes next","efter brotherhood of thieves"}},{q="Vet Deputy Willem vem som leder Defias?",a="Willem förstår inte organisationens fulla omfattning. Han vet bara att rövarna kallar sig Defias Brotherhood, och han misstänker att deras närvaro nära klostret bådar illa för Stormwind.",al={"vet willem om vancleef","vem leder defias i northshire"}}},fx={e491bbee={q="Varför vill Deputy Willem att du ska bekämpa tjuvarna?",a="Deputy Willem har fått i uppdrag att skydda Northshire Abbey och dalen runt omkring. Ett fräckt rövarband som kallar sig Defias Brotherhood har smugit sig in i skogen österut, på andra sidan floden, och hotar tryggheten för klostret och de lokala arbetarna. Willem vill att de kuvas genast, innan de får ett starkare fäste eller går till direkt angrepp mot dalen.",al={"varför vill willem det här","willems motiv","varför stoppa defias här"}},["4db9a478"]={q="Vilka är tjuvarna på andra sidan floden?",a="Du skickas efter Defias Thugs, laglösa medlemmar av Defias Brotherhood som slagit läger i skogen på andra sidan bäcken, öster om Northshire Abbey. De har samlats nära vingårdarna och fälten runt omkring, där de spanar på dalen och trakasserar lokalbefolkningen samtidigt som de etablerar en väpnad närvaro mitt framför näsan på Stormwind.",al={"vilka är tjuvarna","vem slåss jag mot","defias i northshire"}}},fp="22,214,21.447.0,17.338.0,31.242.0,82.245.0,36.142.0,44.179.0,41.204.0,45.205.0"}
P.entries["quest:180"] = {n="Wanted: Lieutenant Fangore",s="Wanted: Lieutenant Fangore är en lokal belöning som Magistrate Solomon har satt upp i Lakeshire. Den uppmanar äventyrare att jaga rätt på Lieutenant Fangore, den grymme hövdingen för Shadowhide-gnollerna som tränger in i Redridge Mountains. Att döda honom blir ett direkt slag mot avfällingen och trollkarlen Morganth, som gnollerna tjänar.",h="Wanted: Lieutenant Fangore är en lokal belöning som Magistrate Solomon har satt upp i Lakeshire.",kw={"fangore","gnoll","lakeshire","lieutenant fangore","magistrate solomon","morganth","redridge","shadowhide"},ang={["faction:Alliance"]="Lakeshire är ett viktigt fäste för Alliansen i Redridge. Om Fangore röjs ur vägen slipper bosättningen bli helt isolerad.",["race:Human"]="Försvararna i Redridge känner själva av Stormwinds försummelse, och därför handlar det om hembygdens överlevnad att ingripa mot gnollhövdingar."},sec={{t="En stad under belägring",b="Lakeshire befinner sig i ett desperat läge. Stormwinds armé är hårt ansatt och kung Varian Wrynn är mystiskt försvunnen, så Highlord Bolvar Fordragon har lämnat gränsbosättningar som Redridge åt sitt öde. Shadowhide-klanen har blivit allt djärvare. De plundrar handelsvägar, bränner gårdar och tränger ända fram till stadens utkant. Magistrate Solomon förlitar sig på anslagna belöningar för att locka till sig legosoldater dit kungliga soldater inte vill marschera."},{t="Morganths löjtnant",b="Lieutenant Fangore är inte bara ett härjande odjur. Han tjänar som Morganths hantlangare. Morganth är en avfällig mörk trollkarl som håller till i Redridges kullar. Under Fangores befäl samordnar Shadowhide-gnollerna sina anfall i stället för att slåss som splittrade asätare, och hotar därmed att helt kapa Lakeshires förbindelse till Elwynn Forest. Att hugga av Fangores tass ger Magistrate Solomon bevis på att Morganths brutala förtrupp har krossats."}},faq={{q="Vem är Lieutenant Fangore?",a="Lieutenant Fangore är en mäktig ledare inom Shadowhide-gnollklanen som bor i Redridge. Han samordnar gnollernas plundringståg och upprätthåller Morganths vilja. Morganth är en mörk trollkarl som hotar Lakeshire.",al={"lieutenant fangore","vem är fangore","fangores bakgrund"}},{q="Vem satte upp belöningen för Lieutenant Fangore?",a="Belöningen utfärdades av Magistrate Solomon, ledaren för Lakeshire. Han försöker säkra Redridges utkanter mot fientliga gnoller och mörka magiker.",al={"vem satte upp belöningen","vem vill se fangore död","magistrate solomon fangore"}},{q="Varför skickar inte Stormwind soldater för att ta hand om gnollerna?",a="Stormwind är lamslaget av kung Varian Wrynns plötsliga försvinnande och oroligheter på hemmaplan. Highlord Bolvar Fordragon och adelsrådet har vägrat skicka reguljära arméförband till avlägsna städer som Lakeshire, så Magistrate Solomon tvingas anlita äventyrare som legosoldater.",al={"varför finns inga vakter från stormwind","var är stormwinds soldater","varför hjälper inte armén"}},{q="Vilket bevis krävs för att få belöningen?",a="Magistrate Solomon kräver Lieutenant Fangores avhuggna tass som fysiskt bevis på att Shadowhide-krigsherren har dödats.",al={"bevis för fangore","fangores tass","vilket föremål ska lämnas in"}},{q="Vem är Morganth och varför följer Fangore honom?",a="Morganth är en avfällig mänsklig magiker som utövar mörk magi från ett torn i Redridge Mountains. Han har böjt Shadowhide-gnollerna under sin vilja och använder Lieutenant Fangore som hantlangare för att terrorisera trakten.",al={"vem är morganth","varför följer gnollerna morganth","fangore morganth"}},{q="Vad är Shadowhide-gnollerna?",a="Shadowhide-klanen är en våldsam gnollstam som lever bland klipporna och skogarna i Redridge Mountains. De är kända för sin aggressivitet och brutala bakhållstaktik, och har plågat nybyggarna i Lakeshire i åratal.",al={"shadowhide-klanen","gnoller i redridge","shadowhides bakgrund"}}},fp="26,256,18.401.0,21.396.0,26.161.0,45.136.0,57.275.0,43.113.0,48.221.0,31.175.0"}
P.entries["quest:1801"] = {n="Tome of the Cabal",s="I The Barrens skickar Strahad Farsan hordens häxmästare österut för att söka efter en förlorad grimoar. Tome of the Cabal innehåller riter för att kalla på och binda en feljägare, och sökandet börjar hos kartografen Jorah Annison i Undercity.",h="I The Barrens skickar Strahad Farsan hordens häxmästare österut för att söka efter en förlorad grimoar.",kw={"the barrens","feljägare","jorah annison","ratchet","strahad farsan","tome of the cabal","undercity","warlock-uppdrag"},ang={["class:Warlock"]="Som hordens häxmästare måste du fullborda denna övergångsrit för att tämja en feljägare. Du färdas mellan Kalimdor och Eastern Kingdoms för att samla bortglömda ritualkomponenter.",["faction:Horde"]="Som medlem av horden ser du hur Kalimdors mörka magiker samarbetar med Förfallnas ockulta lärda under Ruins of Lordaeron."},sec={{t="Jakten på forntida kunskap",b="Strahad Farsan säger att det krävs mer än vanlig avgrundsmagi för att kalla på en feljägare. Dessa rovdjur livnär sig på magiska energier och står emot vanliga åkallelsecirklar. En lärling behöver särskilda cirklar och en uråldrig grimoar som kallas Tome of the Cabal. Boken skrevs av den första grupp häxmästare som band en feljägare utan hjälp utifrån. Dess riter och sigill visar hur man förslavar en så farlig demon."},{t="Kartografen i Undercity",b="Häxmästare i Kalimdor har länge saknat exemplar av Tome of the Cabal, så Strahad skickar sin elev över havet till Jorah Annison i Undercity. Annison arbetar som kunglig kartograf och kartlägger Lordaeron, men kan mycket om gamla och obskyra texter. Han erkänner att han avskyr kartografi och törstar efter sällsynta historieskildringar, ockulta berättelser och avhandlingar om mörk magi."}},faq={{q="Vad är Tome of the Cabal?",a="Tome of the Cabal är en sällsynt ockult grimoar, skriven av de första häxmästarna som kallade på och band en feljägare utan hjälp utifrån. Dess precisa instruktioner, skydd och riter gör det möjligt att tryggt kalla en av dessa magiätande bestar till Azeroth.",al={"tome of the cabal-lore","vad är den här boken","tome of the cabal"}},{q="Varför skickar Strahad Farsan dig till Undercity?",a="Strahad och hans akolyter i The Barrens har inget exemplar av Tome of the Cabal. Han skickar dig till Jorah Annison, en kartograf i Undercity och lärd inom sällsynta, uråldriga böcker som kanske vet var Tome går att återfinna.",al={"varför åka till undercity","strahad farsan undercity","varför träffa jorah"}},{q="Vem är Jorah Annison?",a="Jorah Annison är en lärd Förfallen som arbetar i Undercity. Hans officiella yrke är kartografi, men hans passion gäller obskyra texter, nekromantiska avhandlingar och uråldrig litteratur.",al={"vem är jorah","jorah annison-lore"}},{q="Varför behövs en särskild bok för att frammana en feljägare?",a="Feljägare livnär sig på arcana och andra magiska energier, vilket gör dem farliga att kalla på med vanliga demoniska cirklar. Tome of the Cabal beskriver skydd som binder dem innan de slukar den som kallar på dem.",al={"varför behöver feljägare en bok","varför är feljägare svåra att frammana"}}},fx={["9f4798be"]={q="Varför vill Strahad Farsan att det här ska göras?",a="Strahad Farsan övervakar dina framsteg som en ambitiös häxmästare värdig att hantera större demonisk makt. Att frambesvärja och kuva en feljägare är en farlig övergångsrit som prövar om en utövare kan bemästra en varelse skapad för att livnära sig på rå magisk essens. Strahad är beredd att bidra med sina adepter och magiska cirklar till bindningsritualen, men först måste du skaffa den uråldriga kunskap som behövs för att möjliggöra frambesvärjningen.",al={"strahad farsans motiv","varför hjälper strahad","strahads anledning"}},["5aabed1a"]={q="Varför skickar Strahad Farsan dig i stället för att gå själv?",a="Det är helt och hållet ditt prov att klara. En häxmästare måste visa påhittighet, uthållighet och personlig kontroll över de mörka konsterna för att kunna binda en best så farlig som en feljägare. Strahad och hans adepter måste också stanna vid besvärjelsecirkeln ovanför Ratchet och förbereda de komplicerade skydden och ritualerna inför din återkomst med den återfunna texten.",al={"varför skicka mig","varför åker inte strahad själv","varför måste jag åka till undercity"}}},fp="17,231,28.397.0,29.386.0,30.250.0,50.210.0,21.184.0,51.209.0"}
P.entries["quest:1802"] = {n="Tome of the Cabal",s="Det här uppdraget går ut på att en allianskriglock ska leta reda på de utspridda, förstörda delarna av en unik grimoar som kallas Tome of the Cabal. De saknade sidorna måste hämtas från avlägsna länder för att tyda de mörka riter som krävs för att binda en feljägare.",h="Det här uppdraget går ut på att en allianskriglock ska leta reda på de utspridda, förstörda delarna av en...",kw={"azurelode mine","feljägare","ironforge","krom stoutarm","moldy tome","splithoof hold","strahad farsan","tattered manuscript","tome of the cabal"},ang={["class:Warlock"]="Att återta grimoarens sönderrivna delar är ett övergångsprov som låser upp de viktiga åkallningsriterna som behövs för att dra en feljägare ur Nether och förslava den.",["faction:Alliance"]="Alliansens utövare förlitar sig på kontakter i Ironforge, som Krom Stoutarm, för att spåra sällsynta demoniska reliker över kontinenter utan att väcka kyrkans eller kronans misstankar."},sec={{t="En delad grimoar",b="Bara ett exemplar av Tome of the Cabal skrevs någonsin, och dess våldsamma historia gjorde att det inte förblev helt. Det slets sönder och vandaliserades, och resterna spreds till vitt skilda delar av världen. En del, ett slitet manuskript som slitits loss direkt ur bokbandet, hamnade på något vis tvärs över havet i Kalimdors karga kanjoner, där det föll i centaurklanernas händer. Den återstående delen skulle fraktas sjövägen från Lordaerons kust ner till Khaz Modan, men fartyget förliste innan det nådde hamnen."},{t="Över hav och kanjon",b="För att sätta ihop grimoaren måste du överleva två förrädiska faror. Sidorna som gått förlorade till havs spolades i land vid Hillsbrads kust väster om Southshore, där strandmurlocker vid Azurelode Mine lade beslag på vrakgods och vattendränkta reliker. För att återta den torra halvan måste du infiltrera Splithoof Hold i Thousand Needles och ta dig djupt in i centaurernas grottor för att hämta manuskriptet ur en uråldrig kista. Först när de båda delarna förenats kan Krom Stoutarm granska den förlorade texten innan den återlämnas till Strahad Farsan."}},faq={{q="Vad är Tome of the Cabal?",a="Det är en sällsynt, unik demonisk grimoar med esoterisk kunskap som kriglockar behöver. Den innehåller de komplicerade besvärjelser och bindningsriter som krävs för att åkalla och kuva en feljägare från Twisting Nether.",al={"lore om tome of the cabal","vad är den här boken","tome cabal"}},{q="Vem är Krom Stoutarm och varför vill han ha grimoaren?",a="Krom Stoutarm är en dvärg från Ironforge som ägnar sig åt studier av sällsynta och bortglömda texter. I utbyte mot att berätta för alliansens kriglockar var grimoarens sönderrivna delar hamnat ber han bara om att få studera innehållet på nära håll när de har hämtats.",al={"vem är krom stoutarm","varför vill krom ha boken","krom stoutarm ironforge"}},{q="Var hamnade bokens två delar?",a="Moldy Tome spolades i land vid Hillsbrads kust väster om Southshore, nära Azurelode Mine, och plockades upp av kustmurlocker. Tattered Manuscript hamnade i Kalimdor, inne i Splithoof Hold, undanstoppat i en illa medfaren kista djupt inne i en centaurgrotta i Thousand Needles.",al={"var finns grimoarens delar","bokens platser","tattered manuscript plats"}},{q="Varför slets grimoaren sönder från början?",a="Bara ett exemplar av Tome of the Cabal skrevs någonsin av. Någon gång i dess dunkla förflutna vandaliserades den med avsikt. En stor del slets loss ur bokbandet och fördes till Kalimdor, medan resten gick förlorad till havs under en olycksalig resa till Menethil Harbor.",al={"varför slets boken sönder","vem vandaliserade grimoaren"}},{q="Vem är Strahad Farsan och vad har han med uppdraget att göra?",a="Strahad Farsan är en erfaren kriglock som bor nära Ratchet i The Barrens. Han skickar blivande åkallare för att hämta grimoaren, så att de under hans ledning kan lära sig riterna som krävs för att åkalla och binda en feljägare.",al={"vem är strahad","strahad farsan","strahads koppling"}},{q="Varför är Moldy Tome täckt av havssmuts?",a="Boken låg ombord på ett fartyg på väg från Lordaerons kust till Menethil Harbor, men det nådde aldrig fram. Vraket drev nära Hillsbrads kust, där kustmurlocker samlade in de fuktiga, mögliga sidorna nära Azurelode Mine.",al={"varför är moldy tome blöt","hillsbrad grimoar murlocker"}}},fx={["7c4e226c"]={q="Vad är Moldy Tome?",a="Moldy Tome är de vattenskadade resterna av den ursprungliga huvudboken till Tome of the Cabal. Den gick förlorad till havs utanför Hillsbrad Foothills när ett transportfartyg på väg mot Menethil Harbor sjönk. När du återfår den får du tillbaka kärnan i grimoarens ondskefulla läror.",al={"moldy tome","vad är moldy tome","varför hitta moldy tome"}},aa350fa4={q="Vad är Tattered Manuscript?",a="Tattered Manuscript är delen som slets ur den ursprungliga Tome of the Cabal innan boken gick förlorad. Den fördes långt över havet och hamnade hos Galak-kentaurerna i Thousand Needles. Där innehåller den de saknade riter som behövs för att sätta ihop hela texten.",al={"tattered manuscript","vad är tattered manuscript","kentaurernas manuskript"}}},fp="17,154,18.402.0,21.417.0,30.210.0,51.185.0,44.251.0,47.236.0,66.207.0,43.231.0"}
P.entries["quest:1803"] = {n="Tome of the Cabal",s="Det här uppdraget ber Horde-warlocks att återförena de två åtskilda delarna av den uråldriga Tome of the Cabal åt Jorah Annison i Undercity. Grimoiren förvarades en gång i kungariket Lordaeron, men slets sönder och spreds över världen innan den gick helt förlorad. För att spåra upp de fuktiga, trasiga resterna måste du trotsa fientliga vatten i Eastern Kingdoms och ta dig djupt in i centaurernas område i Kalimdor.",h="Det här uppdraget ber Horde-warlocks att återförena de två åtskilda delarna av den uråldriga Tome of the...",kw={"galak","jorah annison","lordaeron","moldy tome","southshore","splithoof hold","tattered manuscript","thousand needles","tome of the cabal","warlock-uppdrag"},ang={["class:Warlock"]="Att återta Tome of the Cabal är en övergångsrit för utövare på mellannivå. Du samlar in förlorad Lordaeron-magi för att utöka din repertoar av åkallelser.",["faction:Horde"]="Jakten på manuskriptet för dig genom ravinerna i Thousand Needles, där Horde-styrkorna vid Freewind Post ständigt strider mot traktens centaurer.",["race:Undead"]="Boken förvarades i Lordaeron innan kungariket föll. Att återfinna den innebär därför att återta ett ockult arv från Forsakens tidigare mänskliga liv."},sec={{t="Ett splittrat arv",b="Tome of the Cabal förvarades en gång innanför bibliotekets väggar i det gamla kungariket Lordaeron. Någon gång vandaliserades den illavarslande grimoiren med avsikt: nästan hälften av sidorna togs bort och boken slets i två delar. Den återstående formella texten skulle fraktas söderut till dvärgarnas salar i Ironforge, men ödet ingrep. Transportfartyget förliste längs den klippiga kusten väster om Southshore, och sidorna blev liggande och ruttna i det grunda vattnet under uppsikt av asätande murlocs."},{t="Spridda över kontinenterna",b="Den vandaliserade halvan av boken hamnade ännu längre bort. Den fördes bort från Lordaeron och färdades hela vägen till södra Kalimdor, där den hamnade i Galak-centaurernas hårda grepp djupt inne i Splithoof Hold i Thousand Needles. För att återfå hela texten måste en warlock genomsöka den fuktiga kuststräckan i Hillsbrad efter Moldy Tome och infiltrera dammet och brutaliteten i centaurernas raviner för att hitta Tattered Manuscript. När båda resterna förs samman inför Jorah Annison återställs den legendariska mörka texten till en enda läsbar volym."}},faq={{q="Vad är Tome of the Cabal?",a="Det är en arkan och demonisk grimoire som en gång förvarades i Lordaerons huvudstad. Den innehåller avancerade ritualer för warlocks och skändades och delades i två delar innan den gick förlorad på två olika kontinenter.",al={"tome of the cabal-lore","vad är den här boken","tome of the cabal"}},{q="Varför finns en del av boken nära Southshore?",a="Efter att boken vandaliserats skulle den återstående inbundna delen överföras till de lärda i Ironforge. Men fartyget som fraktade den förliste utanför kusten väster om Southshore, och grimoiren blev kvar bland traktens murlocs.",al={"varför southshore","moldy tome-ursprung","kusten väster om southshore"}},{q="Hur hamnade sidorna hos centaurerna i Thousand Needles?",a="Ungefär hälften av sidorna slets ut ur den ursprungliga boken i Lordaeron och smugglades bort. Genom handel, plundring eller kringvandrande händer hamnade det trasiga manuskriptet till slut djupt inne i Splithoof Hold, förvarat i en kista av Galak-centaurerna.",al={"varför centaurerna har den","sidorna i thousand needles","boken i splithoof hold"}},{q="Vem är Jorah Annison?",a="Jorah Annison är en Forsaken-warlock som håller till i Magic Quarter i Undercity. Han vägleder blivande Horde-warlocks i jakten på bortglömd, förbjuden kunskap så att de kan bemästra de demoniska krafterna bättre.",al={"jorah annison-lore","vem är jorah"}},{q="Vem vandaliserade boken från början?",a="Den skyldiges exakta identitet är fortfarande okänd. Jorah Annison själv beklagar vandaliseringen och undrar vem som kunde begå en sådan avskyvärd handling mot en text med så djup ockult kraft.",al={"vem slet sönder boken","vem stal sidorna","bokens vandal"}},{q="Vad gör Jorah med boken när du lämnar tillbaka båda delarna?",a="När Jorah Annison får både Moldy Tome och Tattered Manuscript sätter han samman delarna till en enda volym och läser igenom dess sidor. Han förbereder dig då för nästa steg i dina demoniska riter.",al={"vad händer efter inlämningen","återställd tome"}}},fx={a3cceb5d={q="Varför vill Jorah Annison ha Tome of the Cabal?",a="Jorah Annison är en Fördärvad häxmästarlärd som ägnar sig åt att gräva fram förlorad vildekraftslära som en gång fanns i Lordaeron. När han återfår den splittrade Tome of the Cabal kan han studera dess ockulta hemligheter på nära håll och vägleda lovande häxmästare i att bemästra farliga, avancerade frambesvärjelser.",al={"varför vill jorah ha det här","jorah annisons motiv","varför samla ihop tome of the cabal"}},["968099ef"]={q="Vad är Moldy Tome?",a="Moldy Tome innehåller de bärgade resterna av originaltexten som skulle föras till Ironforge. Den gick förlorad i ett skeppsbrott vid kusten nära Southshore och plockades upp av murlocer. Den rymmer ena viktiga halvan av Cabals ritualer.",al={"vad är moldy tome","moldy tomes bakgrund","vad används moldy tome till"}},["2b99c3ce"]={q="Vad är Tattered Manuscript?",a="Tattered Manuscript är den saknade halvan av Tome of the Cabal, som slets bort när boken vandaliserades i Lordaeron. De stulna sidorna färdades genom okända händer över havet till Kalimdor och hamnade till slut inlåsta i en kista hos Galak-kentaurerna i Thousand Needles.",al={"vad är tattered manuscript","tattered manuscripts bakgrund","vad används tattered manuscript till"}}},fp="17,290,16.391.0,27.405.1,30.177.0,44.206.0,62.251.0,21.184.0,43.153.0,64.185.0"}
P.entries["quest:1804"] = {n="Tome of the Cabal",s="I The Barrens väntar Strahad Farsan på att en häxmästare ska komma med Tome of the Cabal och kanaliseringsstavar. Tillsammans förbereder de bindningen av en avgrundsjägare.",h="I The Barrens väntar Strahad Farsan på att en häxmästare ska komma med Tome of the Cabal och...",kw={"the barrens","dragonmaw","viljägare","krom stoutarm","ratchet","kanaliseringsstavar","strahad farsan","tome of the cabal","wetlands"},ang={["class:Warlock"]="Som häxmästare markerar kuvandet av en avgrundsjägare övergången från pakter med imps och voidwalkers till att bemästra rovdemoner skapade för att sluka arkane magier.",["faction:Alliance"]="Som besvärjare för Alliansen färdas du mellan Ironforge, Wetlands dimmiga träsk och Ratchet, den neutrala goblinhamnen i Kalimdor.",["race:Dwarf"]="Som dvärg vet du värdet av varsamt bevarande. I Hall of Explorers i Ironforge fogar Krom Stoutarm samman förstörda reliker bit för bit."},sec={{t="En motvillig överlämning",b="I Hall of Explorers i Ironforge fogar Krom Stoutarm samman Tome of the Cabals trasiga, mögliga rester. Dvärgforskaren lämnar motvilligt ifrån sig detta sällsynta verk inom mörk lärdom, men försäkrar sig först om ett löfte om en kopia. Han lämnar också vidare ett färskt meddelande från Strahad Farsan. Boken innehåller riter för att öppna en väg till Nether, men pergament kan inte ensamt utföra ritualen."},{t="Stulna reliker från Dragonmaw",b="Strahads akolyter behöver fokusredskap för att stadga energierna som åkallas för att binda en avgrundsjägare. Krom skickar häxmästaren till Wetlands, där Dragonmaw-besvärjare bär kanaliseringsstavar. När stavarna tas från de fientliga orcherna får Strahads krets den ledare som behövs för att kontrollera sprickan och stabilisera de åkallade energierna."},{t="Tillbaka till The Barrens",b="I Strahads torn högt ovanför Ratchet fullbordar den rekonstruerade boken och kanaliseringsstavarna den mödosamma förberedelsen. Med redskapen säkrade och texten översatt förbereder Strahad den farliga bindningsriten. Besvärjarens viljestyrka kommer att prövas mot en hund från Burning Legion."}},faq={{q="Varför behöver Strahad kanaliseringsstavar?",a="Strahads akolyter använder stavarna för att fokusera och stadga energierna som krävs för att åkalla och binda en avgrundsjägare. Deras arbete hjälper till att hindra portalen från att kollapsa eller löpa amok.",al={"varför kanaliseringsstavar","kanaliseringsstavarnas syfte","vad används stavarna till"}},{q="Var hittar man kanaliseringsstavarna?",a="Dragonmaw-orchernas besvärjare i Wetlands håller i kanaliseringsstavarna, särskilt kring träskmarkerna och ruinerna där de håller till.",al={"var får man kanaliseringsstavar","vem släpper kanaliseringsstavar","kanaliseringsstavarnas plats"}},{q="Varför var Krom Stoutarm inblandad i en häxmästarritual?",a="Krom Stoutarm är en mästerforskare i Ironforge, skicklig på att översätta, bevara och återställa gamla skadade manuskript. Hans intresse för sällsynta fornminnen fick honom att restaurera de fördärvade sidorna i Tome of the Cabal.",al={"varför krom","varför hjälper en dvärg från ironforge en häxmästare","krom stoutarm häxmästare"}},{q="Vad händer när man ger Strahad boken och stavarna?",a="När du lämnar över boken och stavarna till Strahad börjar han bindningsriten högst upp i sitt torn. Du möter den åkallade avgrundsjägaren och försöker kuva den.",al={"vad händer sedan","nästa uppdrag efter tome of the cabal 3","vad gör strahad"}},{q="Vem är Strahad Farsan?",a="Strahad Farsan är en mäktig häxmästare i ett ensligt torn på klipporna ovanför Ratchet i The Barrens. Erfarna utövare i Kalimdor och Eastern Kingdoms erkänner hans mästerskap inom demonologi.",al={"strahad farsans historia","vem är strahad","snubben ovanför ratchet"}},{q="Använder Horde också Tome of the Cabal?",a="Hordens häxmästare följer sina egna riter för Tome of the Cabal, med spår till andra kontakter i Kalimdor och Undercity i stället för till Krom Stoutarm i Ironforge.",al={"hordens tome of the cabal","gör orcher det här uppdraget"}}},fx={["7a279078"]={q="Varför måste du jaga Dragonmaw-klanen i Wetlands?",a="Den kvarvarande Dragonmaw-klanen, som slagit sig ner i Wetlands, använder fortfarande kraftfull mörk magi från tiden då de härskade där. Krom vet att deras besvärjare bär på de särskilda kanaliseringsstavar som behövs för att förankra Strahads besvärjelsecirkel. För att få tag på fokuseringsstavarna måste du ta dem direkt från de fientliga orc-besvärjarna.",al={"varför dragonmaw-orcer","dragonmaw-häxmästare i wetlands","vem har rods of channeling"}}},fp="17,158,19.397.0,30.327.0,19.291.1,41.169.0,39.124.0,51.223.0,55.138.1,22.203.0,51.166.0"}
P.entries["quest:1805"] = {n="Tome of the Cabal",s="En häxmästares arbete med Tome of the Cabal leder nu in i fientligt territorium. Efter att ha hjälpt Jorah Annison att återställa boken måste du hämta tre Rods of Channeling och föra dem till Strahad Farsan i Ratchet.",h="En häxmästares arbete med Tome of the Cabal leder nu in i fientligt territorium.",kw={"angerfang encampment","dragonmaw","viljägare","jorah annison","ratchet","rod of channeling","strahad farsan","tome of the cabal","wetlands"},ang={["class:Warlock"]="Som häxmästare ställs du inför ett prov på din beslutsamhet: att säkra farliga ritualingredienser i fientliga länder kräver kunskap och mod för att binda en rovgirig viljägare till din tjänst.",["faction:Horde"]="Som medlem av horden möter du Dragonmaw-avfällingar i Wetlands, bittra fiender till Thralls hord. Att ta deras kanaliseringsstavar är en seger för hordens intressen.",["race:Orc"]="Som orch påminner du dig om den mörka och obevekliga väg som horden kämpade för att lämna bakom sig när du slår ner förrädiska Dragonmaw i Wetlands.",["race:Undead"]="Som odöd kan du se Jorah Annisons arbete i Undercity: fördömda häxmästare studerar förbjudna mystiska texter för att nå praktisk överlägsenhet."},sec={{t="Den återskapade bokens hemligheter",b="I Undercity studerar Jorah Annison de återfunna fragmenten av Tome of the Cabal. Den fördömda forskaren fogar samman dess ockulta passager och välkomnar den sällsynta kunskap de erbjuder. Sedan överlämnar Jorah ett brådskande direktiv från Strahad Farsan. Kunskap ensam kan inte binda en viljägare. En häxmästare behöver exakta redskap för att fokusera demonisk kraft i en bindningscirkel."},{t="Ge dig in i Wetlands",b="Strahad behöver tre Rods of Channeling, som bärs av avfälliga orcher från Dragonmaw-klanen. De håller till bland ruinerna av Angerfang Encampment i Wetlands, långt från hordens länder. Du måste ta dig in i omstritt territorium och möta klanrester som hatar den moderna horden lika mycket som de slaktar alliansens upptäcktsresande."},{t="Återvänd till Ratchet",b="När stavarna och Reconstructed Tome är säkrade återvänder du över havet till Strahad Farsans torn ovanför Ratchet. Strahad hälsar dig med bister tillfredsställelse. Ritualens beståndsdelar är samlade, och ett farligt viljeprov mot ett odjur från Twisting Nether väntar."}},faq={{q="Vad är syftet med uppdraget?",a="Det här är det tredje steget i hordens uppdragskedja för häxmästare som vill lära sig att frammana en viljägare. Du överlämnar den återställda Tome of the Cabal och tre Rods of Channeling till Strahad Farsan ovanför Ratchet.",al={"varför göra uppdraget","uppdragets syfte","vad används tome of the cabal till"}},{q="Vem är Jorah Annison?",a="Jorah Annison är en fördömd häxmästare och forskare i Magic Quarter i Undercity. Jorah studerar esoteriska och mörka texter och hjälper andra utövare att foga samman sönderslagna grimoirer som Tome of the Cabal.",al={"vem är jorah","jorah annisons bakgrund"}},{q="Varför behövs Rods of Channeling?",a="Stavarna ger en häxmästare exakt kontroll när en viljägare frammana­s och betvingas. De fokuserar ritualen och stabiliserar och formar åkallelsens cirkel, så att häxmästaren kan kuva demonen i stället för att bli uppslukad.",al={"varför rods of channeling","stavarnas syfte"}},{q="Var finns Dragonmaw-orcherna i det här uppdraget?",a="Dragonmaw-klanen håller Angerfang Encampment i Wetlands, på andra sidan havet i Khaz Modan. Deras benväktare bär kanaliseringsstavarna.",al={"var hittar man dragonmaw","dragonmaw i wetlands","angerfang encampment"}},{q="Vem är Strahad Farsan?",a="Strahad Farsan är en mänsklig häxmästare som samarbetar med hordens mörka magiker. Han arbetar från ett ensligt torn på klipporna ovanför Ratchet, hamnstaden i The Barrens där gobliner bor.",al={"vem är strahad","strahad farsan i ratchet"}},{q="Vad händer när uppdraget är slutfört?",a="Din leverans leder vidare till ”The Binding”. Strahad instruerar dig sedan att rita en åkallelsescirkel och möta en frambesvärjd viljägare i magisk strid för att bemästra odjuret.",al={"what comes next","nästa uppdrag efter tome"}}},fx={["9475dbd0"]={q="Varför hjälper Jorah Annison dig?",a="Jorah Annison är en Fördärvad kartograf i Undercitys Magic Quarter. Han törstar efter magiska och esoteriska texter, eftersom han för länge sedan läst ut det magra urvalet av geografiböcker han hade tillgång till. I utbyte mot att få studera den återskapade Tome of the Cabal vidarebefordrar han instruktioner från Strahad Farsan och avslöjar var du kan hitta de sällsynta kanaliseringsstavarna som behövs för din träning.",al={"varför hjälper jorah","jorah annisons motiv","vad vill jorah ha"}},cff1ec65={q="Varför har Dragonmaw-orcerna Rods of Channeling?",a="Den utbrytargrupp som kallas Dragonmaw Clan har fästen runtom i Wetlands, där mörka besvärjare och benväktare utövar ondskefull magi vid sidan av den moderna Horde. De använder kraftfulla kanaliseringsstavar för att fokusera och binda rå magisk energi. Därför är deras läger den bästa platsen att leta efter de magiska fokus som Strahad behöver för sina frambesvärjelseritualer.",al={"dragonmaw-orcer i wetlands","vem har rods of channeling","varför dragonmaw-orcer"}}},fp="17,208,33.376.0,25.305.0,17.280.1,34.186.0,21.220.0,34.211.0,52.137.0,22.164.0,41.162.1"}
P.entries["quest:1806"] = {n="The Test of Righteousness",s="The Test of Righteousness kulminerar vid Jordan Stilwells smedja utanför Ironforge i Dun Morogh. Efter att ha samlat farliga beståndsdelar från hela Eastern Kingdoms och Kalimdor väntar en paladin medan smeden tillverkar en mäktig krigshammare. Den markerar övergången från lärling till erkänd Ljusets förkämpe.",h="The Test of Righteousness kulminerar vid Jordan Stilwells smedja utanför Ironforge i Dun Morogh.",kw={"bosch verigan","dun morogh","smedja","hammare","ironforge","jordan stilwell","paladin","the test of righteousness","verigan"},ang={["class:Paladin"]="Den här övergångsriten belönar dina farliga resor genom avlägsna länder med Verigan's Fist, ett ikoniskt vapen ägnat åt att upprätthålla rättfärdigheten.",["profession:Blacksmithing"]="När du ser Jordan Stilwell arbeta vid sitt städ får du se hur mästerligt hantverk kan kanalisera ett heligt syfte genom rått stål och återvunna material.",["race:Dwarf"]="Hammaren som smids här gör minnet av Bosch Verigan odödligt. Han var en ärad dvärgpaladin som förkroppsligade Khaz Modans motståndskraft."},sec={{t="En smeds hyllning",b="Mästersmeden Jordan Stilwell utövar sitt hantverk utanför Ironforges portar. Han medger att han känner en viss avund mot kringvandrande paladiner, men är mycket stolt över att stödja saken med hammare och städ. När han får sällsynta material som samlats från skuggiga kryptor, sjunkna ruiner och farliga gruvor håller Stilwell sitt löfte och smider ett vapen värdigt en sann försvarare."},{t="Bosch Verigans arv",b="Den färdiga krigshammaren döps till Verigan's Fist, till minne av Bosch Verigan, en ärad dvärgpaladin och Jordan Stilwells nära vän. Genom att överlämna detta heliga vapen till en ung förkämpe, för egen och sin hustrus räkning, ser Stilwell till att minnet av hans fallne vän och dennes tapperhet består mot mörkret som hotar Azeroth."}},faq={{q="Vad händer under det här steget i uppdraget?",a="Jordan Stilwell går fram till sitt städ och hamrar på glödande metall för att sätta samman delarna du samlat under dina mödosamma prövningar. När han har arbetat vid smedjan kommer han tillbaka och räcker dig det färdiga vapnet.",al={"slutet på the test of righteousness","jordan smider vapen","verigan-filmsekvens"}},{q="Vem är Bosch Verigan?",a="Bosch Verigan var en ansedd dvärgpaladin och nära vän till Jordan Stilwell. Jordan döpte den nyss smidda tvåhandshammaren efter honom för att hedra hans hängivenhet till det heliga ljuset.",al={"vem är verigan","verigan's fist namne","bosch verigan"}},{q="Var äger smidet rum?",a="Smidet äger rum strax utanför Ironforges väldiga portar, bland de snöiga topparna i Dun Morogh, där Jordan Stilwell har sin smedja och sitt städ.",al={"jordan stilwells plats","var finns smedjan","dun moroghs städ"}},{q="Varför behövde Jordan sällsynta material från hela världen?",a="Jordan utformade ett vapen med enastående balans och helig resonans. För att smida något som kunde stå emot en paladins heliga vrede behövde han sällsynta malmer, träslag och ädelstenar som bara kunde återvinnas från farliga platser runt om i världen.",al={"varför samla material","uppdragsdelar till the test of righteousness"}},{q="Kämpar Jordan Stilwell själv någonsin i strid?",a="Jordan Stilwell är smed, inte en kringvandrande krigare. Han medger att han ibland avundas äventyrare som färdas genom landet, men finner sitt verkliga syfte och sin stolthet i att smida vapen åt Ljusets försvarare.",al={"är jordan krigare","jordan stilwell stridande"}},{q="Vad innebär det för en paladin att få den här hammaren?",a="Att få hammaren markerar att en paladin har klarat sina långa prövningar. Det bevisar att bäraren har modet, uthålligheten och den heliga övertygelse som krävs för att vara Ljusets förkämpe i Azeroths farligaste hörn.",al={"vad betyder verigan's fist","paladinens övergångsrit"}}},fx={["49955bc3"]={q="Varför vill Jordan Stilwell smida den här hammaren?",a="Jordan Stilwell erkänner att han känner ett sting av avund när han ser hjältars djärva bedrifter runtom Azeroth, eftersom han själv är smed och inte äventyrare. Genom att smida Verigan's Fist av de sällsynta komponenterna du samlat in kan han hjälpa en försvarare av Ljuset direkt och bidra till att skydda riket på sitt eget viktiga sätt.",al={"jordan stilwells motiv","varför smida vapnet","varför smider jordan hammaren"}}},fp="25,276,17.369.0,27.327.0,43.161.0,21.181.0,35.142.0,59.239.0,50.179.0,54.191.0"}
P.entries["quest:181"] = {n="Look To The Stars",s="Det här uppdraget är sista kapitlet i Viktori Prism'Antras försök att bygga ett stjärnskådningsteleskop i Darkshire. När själva teleskopet nästan är färdigt skickar Viktori resenärer till det farliga Vul'Gol Ogre Mound för att hämta en lins som är stor nog: en monokel som ogret Zzarc'Vul bär.",h="Det här uppdraget är sista kapitlet i Viktori Prism'Antras försök att bygga ett stjärnskådningsteleskop i...",kw={"cog","darkshire","blicka mot stjärnorna","monokel","teleskop","viktori prism'antras","vul'gol ogre mound","zzarc'vul"},ang={["faction:Alliance"]="Darkshire kämpar för sin sköra överlevnad mot fasor och bestar. Viktoris jakt på kunskap om himlen blir därför en stadig, om än egendomlig, ledstjärna för civilbefolkningens uthållighet.",["profession:Engineering"]="Både magiker och uppfinnare uppskattar djärvheten i att ersätta en astronomisk lins med en enorm ogremonokel för att uppfylla kraven på fokusering.",["race:Gnome"]="Apparaten bygger på ritningar som utformats med gnomiskt hantverkskunnande och kräver fyndiga improvisationer i fält, som att göra precisionsoptik av ett odjurs glasögon."},sec={{t="Den sista delen",b="Under hela bygget av sitt stjärnskådningsteleskop har Viktori Prism'Antras förlitat sig på ritningar från gnomingenjören Cog Glitzspinner. Mässingsrör och stadiga fästen kunde skrotas ihop eller tillverkas av lokala material, men apparaten krävde en ovanligt massiv fokuseringslins. Vanliga förstoringsglas och optiska delar från Stormwinds handlare hade helt enkelt inte den diameter som Cogs ambitiösa konstruktion krävde. Därför började Viktori överväga ett oväntat och farligt alternativ."},{t="Ogrets okular",b="I skuggan av de södra kullarna ligger Vul'Gol Ogre Mound, ett läger fullt av fientliga brutala släktingar. Där bor Zzarc'Vul, ett särpräglat ogre som är känt för att bära en glasmonokel stor nog att fungera som observatoriets lins. Genom att ta sig djupt in i kullen och ta okularet från Zzarc'Vul uppfyller du Cogs ritningar. Då kan Viktori färdigställa teleskopet och blicka mot himlen ovanför Duskwoods skuggade trädkronor."}},faq={{q="Vem är Viktori Prism'Antras?",a="Viktori Prism'Antras är en astronom och lärd som bor i en stuga uppe på kullen i Darkshire. Trots mörkret som omsluter Duskwood är han fast besluten att färdigställa sitt observatorieteleskop för att studera stjärnorna.",al={"vem är viktori","viktori prism'antras"}},{q="Var hittar jag Zzarc'Vul?",a="Zzarc'Vul håller till i södra Duskwood, i Vul'Gol Ogre Mound. Han strövar omkring vid lägret och grottorna, så den som letar efter honom måste ta sig genom ogreterritorium som bevakas noga.",al={"zzarc'vuls plats","var är ogret","ogremonokelns plats"}},{q="Varför har ett ogre en monokel?",a="Ogres är inte särskilt kända för sina akademiska intressen eller sin fina optik, men Zzarc'Vul bär en överdimensionerad monokel. Den har ovanliga mått och är den enda linsen i trakten som är tillräckligt stor för Cogs teleskopritningar.",al={"varför ogremonokel","ogres monocelns historia"}},{q="Vad händer när apparaten är färdig?",a="När Viktori får tag på monokeln kan han sätta den sista optiska delen på plats. Med teleskopet färdigmonterat kan Viktori återuppta sina astronomiska studier utan att den dystra skogsmarken nedanför stör honom.",al={"teleskopet färdigt","uppdragets slut"}},{q="Vem ritade teleskopet?",a="Ritningarna till apparaten kom från en ingenjör vid namn Cog. Hans komplicerade konstruktion krävde specialdelar, metallramar och en lins som var mycket större än vanliga glasögon för dvärgar eller gnomer.",al={"cogs ritningar","vem byggde teleskopet"}},{q="Är det säkert att gå in i Vul'Gol Ogre Mound ensam?",a="Nej. Vul'Gol Ogre Mound är fullt av fientliga ogres som ofta patrullerar i grupper eller vaktar smala stigar. Det är mycket farligt för ensamma resenärer att ta sig djupt in i kullen för att hitta Zzarc'Vul.",al={"vul'gol svårighetsgrad","säkert i ogrekullen"}}},fx={ac1c4dd0={q="Varför vill Viktori Prism'Antras att det här ska göras?",a="Viktori är en excentrisk lärd som ägnar sig åt att bygga ett särskilt stjärnskådningsinstrument utifrån Cogs ritningar. Han har lagt ner mycket arbete på att samla ihop ömtåliga delar, men konstruktionen saknar fortfarande en lins som är tillräckligt stor för att skåda himlen. När teleskopet är färdigbyggt kan han äntligen återuppta sin astronomiska forskning i Darkshires dunkel.",al={"varför behöver viktori en monokel","viktori prism'antras mål","look to the stars-motiv"}},f331a2d2={q="Vad ska Ogre's Monocle användas till?",a="Ritningarna till Viktoris stjärnskådningsinstrument kräver en ovanligt stor optisk lins. I stället för att slipa en från grunden i Duskwoods skuggiga avskildhet insåg Viktori att den överdimensionerade monokeln som ogret Zzarc'Vul bär har precis rätt mått och fokuseringsglas för att färdigställa instrumentet.",al={"vad ogremonokeln används till","varför ogre's monocle","vad används monokeln till"}},bbeac028={q="Vem är Zzarc'Vul?",a="Zzarc'Vul är en bemärkt ogre som bor bland sina fränder vid Vul'Gol Ogre Mound i de södra kullarna i Duskwood. Till skillnad från sina brutala följeslagare bär han ett enormt monokel som har fångat Viktori Prism'Antras uppmärksamhet, vilket gör honom till det sista hindret mellan forskaren och ett färdigställt teleskop.",al={"vem är zzarcvul","vem är ogren","målet zzarc'vul"}}},fp="17,161,15.379.0,19.340.1,28.200.0,27.130.0,35.114.0,42.145.0,27.166.0,42.159.0"}
P.entries["quest:1818"] = {n="Speak with Dillinger",s="Speak with Dillinger är en militär order från Horden i Brill. Austil de Mon, krigartränaren på Gallows' End Tavern, skickar stridsdugliga krigare till Deathguard Dillinger vid byns västra ände för ett farligt stridsuppdrag i Lady Sylvanas tjänst.",h="Speak with Dillinger är en militär order från Horden i Brill.",kw={"austil de mon","brill","deathguard dillinger","speak with dillinger","tirisfal glades","ulag the cleaver","undercity"},ang={["class:Warrior"]="Deathguard-befälhavarna värdesätter ren stridsvilja framför allt annat, så den här utsändningen är ett direkt prov på din stridsförmåga vid frontlinjen.",["faction:Horde"]="När du svarar på Undercitys försvarsrop stärker du sammanhållningen mellan Kalimdors allierade och de nyligen införlivade Förfallna.",["race:Undead"]="För de nyligen befriade Förfallna är det ett viktigt steg att svara på Dillingers kallelse och bevisa sin hängivenhet till den mörka damen och Tirisfals försvar."},sec={{t="En kallelse till fronten",b="På Gallows' End Tavern i Brill håller krigartränaren Austil de Mon utkik efter lovande stridskämpar som är villiga att tjäna den mörka damen. När Deathguards behöver dugliga händer skickar de Mon oprövade äventyrare från värdshuset ut i fält. Deathguard Dillinger, som ansvarar för säkerheten i Brills västra utkanter, har begärt någon med stridsvana för ett brådskande uppdrag."},{t="De trognas prov",b="Brill ligger mitt på frontlinjen i Tirisfal Glades, där de Förfallna ständigt måste bevisa sin militära överlägsenhet mot fientliga hot. Dillingers post nära byns kyrkogård ger honom ett utmärkt läge för att hantera lokala angrepp. För den unge krigaren är det mer än ett enkelt ärende att anmäla sig hos Dillinger: det är ett formellt prov på stridsförmåga och politisk lojalitet mot den nybildade nationen av Förfallna."}},faq={{q="Vem skickar mig på det här uppdraget?",a="Austil de Mon, krigartränaren på Gallows' End Tavern i Brill, upptäcker potentiella soldater och skickar dem för att hjälpa Deathguard Dillinger.",al={"uppdragsgivare","austil de mon","vem startar speak with dillinger"}},{q="Var hittar jag Deathguard Dillinger?",a="Deathguard Dillinger är stationerad i västra utkanten av Brill i Tirisfal Glades, nära ingången till kyrkogården.",al={"dillingers plats","var finns dillinger","hitta dillinger"}},{q="Varför ska jag anmäla mig hos Dillinger?",a="Dillinger behöver en stridsduglig kämpe för ett stridsuppdrag som ska försvara Brill och bevisa kämparens lojalitet mot de Förfallnas sak.",al={"varför speak with dillinger","dillingers syfte"}},{q="Vilket uppdrag har Dillinger förberett?",a="När du rapporterar till Deathguard Dillinger ger han dig i uppdrag att jaga rätt på ett farligt hot som kallas Ulag the Cleaver.",al={"vad vill dillinger","nästa uppdrag efter dillinger"}},{q="Får andra raser i Horden den här ordern?",a="Alla krigare i Horden som har vunnit tjänstemännen i Undercitys förtroende kan ta sig an uppdraget, även om det främst är tänkt att pröva rekryter som försvarar Tirisfal Glades.",al={"är uppdraget bara för odöda","kan orcher göra detta"}},{q="Varför skickar en krigartränare mig till Dillinger?",a="Austil de Mon tränar krigare på Gallows' End Tavern i Brill och skickar nyblivna dugliga äventyrare vidare till Deathguard-befälhavare som behöver omedelbar förstärkning.",al={"varför börja i undercity","austil de mons roll"}}},fx={["277a5d32"]={q="Varför skickar Austil de Mon dig till Dillinger?",a="Austil de Mon fungerar som mellanhand och hänvisar framväxande Forsaken som söker högre status till platser där deras stridsförmåga kan tjäna riket. Genom att skicka dugliga händer från Gallows' End Tavern i Brill ut på fältet under Deathguard Dillinger befäl ser han till att bosättningarna vid fronten får förstärkning, samtidigt som han prövar om du har verkligt värde och är hängiven Lady Sylvanas sak.",al={"austil de mons motiv","varför skicka till dillinger","austil de mons skäl"}}},fp="20,247,22.325.0,20.240.0,29.140.0,40.106.0,46.126.0,45.116.1,40.169.0,48.148.0"}
P.entries["quest:1819"] = {n="Ulag the Cleaver",s="Ulag the Cleaver är en övergångsrit för unga Forsaken-krigare i Tirisfal Glades. Deathguard Dillinger ber dig att befria och avrätta en förslavad Scourge-krigare som hålls fången i ett mausoleum i norr, för att pröva din stridsvilja och vinna Deathguards respekt.",h="Ulag the Cleaver är en övergångsrit för unga Forsaken-krigare i Tirisfal Glades.",kw={"brill","deathguard dillinger","dillinger","mausoleum","scourge","dödskallesten","ulag","ulag the cleaver"},ang={["class:Warrior"]="Den här prövningen är en tidig utmaning för Forsaken-krigare och testar ditt mod mot en mäktig, tankekontrollerad Scourge-mästare.",["race:Undead"]="Ulags öde visar den fasansfulla verkligheten bakom Scourges kontroll och den tragiska skillnaden mellan Forsaken som lyckades bryta sig fria och dem vars sinnen fortfarande är förslavade av Lich King."},sec={{t="En bunden Scourge-träl",b="När Scourge svepte fram över Lordaeron lyckades Forsaken tillfångata en märklig odöd krigare som kallade sig Ulag the Cleaver. Ulag hade ett medvetet och klart sinne, men hans ande var fortfarande helt underkastad Lich Kings psykiska kontroll. För att förstå hur Scourge binder den fria viljan höll Forsaken honom fången under en magisk försegling i ett mausoleum norr om Brill, i hopp om att bryta entitetens andliga bojor."},{t="Bödelns prövning",b="Alla försök att lösgöra Ulag från Lich Kings mentala grepp misslyckades. Deathguard Dillinger insåg att verklig frihet bara kunde nås genom förintelse och gjorde därför fången till en stridsprövning för unga Forsaken-krigare. När en krigare rör vid dödskallestenen utanför kryptan bryts skyddsmagin, Ulag befrias ur sitt fängelse och får sin frihet vid yxans egg."}},faq={{q="Vem är Ulag the Cleaver?",a="Ulag the Cleaver var en odöd krigare som tillfångatogs av Forsaken under Scourges invasion av Tirisfal Glades. Märkligt nog behöll han sitt fria sinne och sin identitet, men var ändå helt underkastad Lich Kings mentala befallningar.",al={"ulag-lore","vem är ulag","ulag the cleavers identitet"}},{q="Varför spärrades Ulag in under mausoleet?",a="Forsaken-lärda och soldater spärrade in honom under en magisk sigillförsegling för att studera hur Lich Kings tankekontroll fungerade. De hoppades hitta ett sätt att bryta den psykiska länk som band honom, men deras experiment misslyckades.",al={"varför är ulag inspärrad","fånge i mausoleum i tirisfal"}},{q="Varför vill Deathguards döda Ulag nu?",a="Efter att ha medgett att de inte kunde bryta Lich Kings grepp om Ulag beslutade Forsaken att döden var den enda nåd som återstod. Deathguard Dillinger valde att använda avrättningen som en prövning av mod och disciplin för blivande krigare.",al={"varför döda ulag","skäl att döda ulag"}},{q="Hur kallar man fram Ulag?",a="Han är inspärrad under ett mausoleum strax norr om Brill. Rör du vid dödskallestenen nära graven bryts den magiska sigillförsegling som binder honom, och han reser sig och anfaller.",al={"hur man kallar fram ulag","var finns ulag","ulags dödskallesten"}},{q="Vem ger uppdraget att döda Ulag?",a="Deathguard Dillinger, som vaktar vägen västerut från Brill i Tirisfal Glades, ger uppdraget särskilt till Forsaken-krigare som söker vidare träning.",al={"uppdragsgivare för ulag","vem skickar mig till ulag"}},{q="Vad händer när Ulag har besegrats?",a="När Deathguard Dillinger fått bekräftat att Ulag är död erkänner han ditt mod och skickar dig till Coleman Farthing i Brill för att fortsätta din träning.",al={"efter ulag","fortsättningsuppdrag efter ulag"}}},fx={["6de55395"]={q="Varför låter Deathguard Dillinger dig möta Ulag i stället för att ta hand om honom själv?",a="Deathguard Dillinger prövar din tapperhet. Ulag var ingen obetydlig tjänare åt Scourge, och att möta honom ensam visar om du har den skicklighet, det mod och den beslutsamhet som krävs av en sann krigare i Lady Sylvanas tjänst. Dillinger vaktar Brill och övervakar din träning; genom att skicka dig till kryptan sätter han dig på prov i strid för att se om du förtjänar mer avancerad utbildning.",al={"varför jag dillinger","varför inte själv döda ulag","varför skicka spelaren efter ulag"}}},fp="16,193,22.372.0,23.321.0,24.185.0,44.161.0,44.197.0,21.143.0,33.146.0,36.146.0"}
P.entries["quest:182"] = {n="The Troll Cave",s="På bergsbestigaren Grelin Whitebeards uppdrag skickas äventyrare för att minska antalet unga Frostmane-troll som samlas i Coldridge Valleys grottor i söder. När Ironforges senat är upptagen av en tilltagande troggkris måste ensamma spanare och villiga rekryter hantera gränsstriderna innan trollen får ett permanent fäste.",h="På bergsbestigaren Grelin Whitebeards uppdrag skickas äventyrare för att minska antalet unga Frostmane-troll...",kw={"coldridge valley","dun morogh","frostmane","grelin whitebeard","trogger","troll","ungtroll"},ang={["class:Hunter"]="Klipporna kring grottan i söder är en hård prövningsplats för unga spårare som lär sig att driva fram fientligt villebråd från bergshöjderna.",["race:Dwarf"]="För unga Bronzebeard-dvärgar som ger sig ut i snön handlar det både om att säkra gränsen och om en urgammal bergsfejd att slå ner Frostmane-krigsband.",["race:Gnome"]="Efter Gnomeregans fall finner gnomer skydd i Dun Morogh. De bidrar gärna med sin klokhet och sina vapen för att hjälpa sina dvärdvärdar att bemöta hoten omkring dem."},sec={{t="Ögon i kylan",b="Medan Ironforges reguljära styrkor är upptagna med att slå tillbaka de klippkäkade troggernas intrång över snöfälten får de södra tillfarterna inte lämnas obevakade. Grelin Whitebeard och hans bror Senir skickades ut av bergsmyndigheterna för att bedöma om de inhemska istrollen utgjorde ett omedelbart hot mot hjärtlandet. Grelin håller ensam uppsikt över deras rörelser från en klippa med utsikt över den frusna dalen."},{t="Ett förebyggande slag",b="Grelins spaning visade att den lokala Frostmane-klanen hade börjat slå sig ner i en djup grotta längs den södra bergskammen i Coldridge Valley. Han ansåg att en fullständig militär mobilisering skulle slösa dvärgarnas manskap i onödan och föredrog därför att anlita dugliga frivilliga från trakten för att minska antalet aggressiva ungtroll. Genom att decimera de unga kämparna stör man deras läger innan Frostmane kan organisera räder mot närliggande dvärgbosättningar."}},faq={{q="Varför skickar inte Ironforge reguljära soldater för att ta hand om de här trollen?",a="Ironforges senat och dvärgarnas militär är hårt ansträngda av den plötsliga, förödande trogginvasionen över Dun Morogh. Mindre hot som små trollkrigsband lämnas åt spanare som Grelin Whitebeard, som anlitar självständiga äventyrare för att ta hand om dem.",al={"varför ingen dvärgarmé","var är vakterna","varför anlita äventyrare"}},{q="Vilka är Frostmane-trollen?",a="Frostmane är en ursprunglig istrollsstam från de iskalla klipporna i Dun Morogh. De har länge varit fientliga mot Bronzebeard-dvärgarna och drabbar ständigt samman med bergsbestigare om jaktmarker, territorium och urgamla bergspass.",al={"frostmane-klanen","trollen i dun morogh","vilka är frostmane"}},{q="Var ligger trollgrottan?",a="Grottan ligger längs Coldridge Valleys södra bergskam, söder om Grelin Whitebeards observationsläger.",al={"trollgrottans plats","var ligger grottan","var finns ungtrollen"}},{q="Vem är Grelin Whitebeard?",a="Grelin Whitebeard är en spanare från Ironforge som är stationerad i Coldridge Valley. Tillsammans med sin bror Senir, som undersöker andra delar av Dun Morogh, spårar Grelin fientliga trollbestånd och rapporterar till dvärgarnas ledare.",al={"grelin","uppdragsgivare","whitebeard"}},{q="Varför riktar Grelin särskilt in sig på Frostmane-ungtroll?",a="Lägret i södra Coldridge Valley är en växande bosättning full av unga krigare. Genom att slå ut deras växande kämpar hindrar man gruppen från att bli stark nog att hota dvärgarnas försörjningslinjer.",al={"varför ungtroll","varför rikta in sig på unga troll"}},{q="Vad händer när grottan har rensats?",a="När du återvänder upptäcker du att trollen slog tillbaka under natten, plundrade Grelins läger och stal hans personliga fältdagbok. Nu måste du genast ge dig djupare in i deras hålor för att återta den.",al={"vad händer sedan","fortsättning på trollgrottan"}}},fx={["9e422164"]={q="Varför vill Grelin Whitebeard att trollen ska tas om hand?",a="Grelin och hans bror Senir skickades runt i Dun Morogh för att bedöma om de inhemska Frostmane-trollen utgör ett allvarligt hot mot riket. Ironforges senat är redan överhopad av trogguppror på andra håll, så Grelin hoppas kunna kväsa den här ansamlingen i sin linda innan den växer till en kris som kräver reguljära trupper.",al={"varför döda trollen","grelin whitebeards motiv","varför röja trollgrottan"}}},fp="14,188,16.350.0,19.390.0,70.225.0,29.210.0,32.115.0,25.201.0,53.249.0,36.169.1"}
P.entries["quest:1820"] = {n="Speak with Coleman",s="Speak with Coleman är ett övergångsuppdrag i Tirisfal Glades för hjältar som har visat sitt värde i kampen mot Scourge. Deathguard Dillinger hänvisar dugliga krigare från torget till den lokala tavernan, där de ska hjälpa Coleman Farthing med personliga och fraktionsrelaterade vendettor.",h="Speak with Coleman är ett övergångsuppdrag i Tirisfal Glades för hjältar som har visat sitt värde i kampen...",kw={"agamand","brill","coleman farthing","deathguard dillinger","forsaken","gallow's end tavern","horde","tirisfal glades"},ang={["faction:Horde"]="För resande som hjälper till att säkra Lordaeron ger kontakter med invånarna i Brill en viktig grund för insatser i hela Tirisfal Glades.",["race:Undead"]="Många Forsaken bär på personliga agg samtidigt som de är lojala mot Dark Lady. Coleman Farthings önskemål visar hur personlig förlust och rikets försvar flätas samman i Tirisfal."},sec={{t="Ett ord från vakten",b="Efter att ha hjälpt till att begränsa allvarliga lokala hot, som att ge farliga rester av Scourge ro till vila, däribland Ulag the Cleaver, vinner äventyrare Deathguard Dillingers personliga förtroende. Som en av väktarna som håller uppsikt över vägarna in mot Brill bedömer Dillinger vilka som klarar mer än vanliga patrullrundor och hänvisar dugliga kämpar till invånare som behöver särskilda tjänster."},{t="En privat vendetta",b="Alla konflikter i Tirisfal Glades utkämpas inte på order från högsta ledningen i Undercity. I det ruinerade kungariket Lordaeron bär de överlevande odöda på djupa agg knutna till markerna, familjerna och förmögenheterna de lämnade bakom sig. Coleman Farthing väntar i Gallow's End Tavern och söker någon som kan hjälpa honom att hämnas på hoten som dröjer sig kvar nära gamla bosättningar som Agamand Mills."}},faq={{q="Var hittar jag Coleman Farthing?",a="Coleman Farthing väntar inne i Gallow's End Tavern, på den östra sidan av staden Brill i Tirisfal Glades.",al={"coleman farthing plats","var finns coleman farthing","hitta farthing i brill"}},{q="Vem skickar dig till Coleman?",a="Deathguard Dillinger, som vaktar vägen in till Brill, skickar dig till Coleman när du har visat din stridsförmåga.",al={"vem ger speak with coleman","dillinger uppdrag"}},{q="Vilket arbete har Coleman Farthing?",a="Coleman söker en duglig kämpe som kan hjälpa till med hämnden på Forsakens fiender, särskilt i frågor som rör de gamla Agamand-ägorna.",al={"vad vill coleman","coleman farthing uppdrag"}},{q="Vilka krav måste vara uppfyllda för att få uppdraget?",a="Deathguard Dillinger hänvisar dig till Coleman först när du har bevisat din lojalitet och stridsförmåga gentemot Forsaken genom att besegra Ulag the Cleaver.",al={"krav för speak with coleman","ulag-krav"}},{q="Ger det här uppdraget några större belöningar direkt?",a="Uppdraget för dig bara till Farthing i tavernan och öppnar för hans personliga uppdrag. Det ger i sig inga större mängder utrustning eller mynt.",al={"belöningar för speak with coleman","är det värt att göra"}},{q="Vad är Gallow's End Tavern?",a="Gallow's End Tavern är Brills centrala värdshus. Det fungerar som samlingsplats, viloplats och informell mötesplats för privata uppdrag bland de lokala odöda.",al={"brills taverna","gallows end tavern"}}},fx={["75bd5c35"]={q="Varför vill Deathguard Dillinger att jag ska tala med Coleman?",a="Deathguard Dillinger inser att du har bevisat din styrka och lojalitet mot Dark Lady genom att hantera hoten i Brill. Coleman Farthing har personliga oförrätter att hämnas och behöver en skicklig stridskämpe för att utkräva hämnd på Forsakens fiender. Genom att hänvisa dig till honom ser Dillinger till att dugliga hjältar hjälper sina medborgare och samtidigt stärker rikets säkerhet i stort.",al={"varför skicka till coleman","dillingers motiv att tala med coleman","varför träffa coleman farthing"}},["5d6ae549"]={q="Varför skickar Deathguard Dillinger mig i stället för att själv hantera Colemans begäran?",a="Dillinger är en Deathguard som är stationerad för att skydda Brills stadsgräns mot omedelbara hot som Scourge. Han kan inte lämna sin post för att lösa lokala stadsbors personliga vendettor eller privata bekymmer. Du har visat din stridsförmåga och självständighet, vilket gör dig till den perfekta agenten för att hjälpa Coleman Farthing direkt.",al={"varför jag coleman","varför inte dillinger","varför dillinger skickar dig"}}},fp="18,166,21.303.0,18.328.0,34.97.0,33.111.0,45.132.0,57.133.0,53.137.0,32.149.0"}
P.entries["quest:1821"] = {n="Agamand Heirlooms",s="Coleman Farthing ger äventyrare i uppdrag att plundra Agamand Family Crypt vid norra änden av Agamand Mills. Bitter över sin död som levande vill han beröva sina forna herrar deras arvegods och utplåna deras sista rester av värdighet.",h="Coleman Farthing ger äventyrare i uppdrag att plundra Agamand Family Crypt vid norra änden av Agamand Mills.",kw={"agamand family crypt","agamand-arvegods","agamand mills","coleman farthing","arvegodsvapen","scourge","tirisfal glades"},ang={["class:Rogue"]="Att smyga förbi lurande gastar och stjäla uråldriga vapen från bevakade gravvalv är en självklarhet för smygande agenter.",["faction:Horde"]="När kryptan rensas försvagas Scourges fasta grepp om norra Tirisfal Glades, vilket gör riket tryggare för resande från Horde.",["race:Undead"]="Coleman Farthings bittra uppdrag speglar de kvardröjande agg och oläkta sår som många Forsaken bär med sig från livet till sin odöda tillvaro."},sec={{t="En tjänares bittra agg",b="Innan det tredje kriget ödelade Lordaeron tjänade Coleman Farthing den rika och inflytelserika familjen Agamand vid deras vidsträckta kvarnar i Tirisfal Glades. Vad som än hände när deras gods föll, håller Farthing sina forna herrar helt ansvariga för sin död. Nu när han återuppstått som odöd bland Forsaken ser han med skadeglädje på familjen Agamands fall och jublar över att den en gång stolta ätten reducerats till viljelösa slavar under Lich King."},{t="Skändningen av kryptan",b="För att helt utplåna det som återstår av familjens anseende skickar Farthing äventyrare till Agamand Family Crypt, som ligger under kvarnarnas norra klippor. I dess hemsökta stensalar vandrar rastlösa döda sida vid sida med kvarvarande Scourge. Farthing kräver att fyra ryktbara reliker hämtas: familjen Agamands svärd, yxa, dolk och stridsklubba. På så sätt ska deras släktarv berövas varje sista spår av heder."}},faq={{q="Vem var Coleman Farthing när han levde?",a="Coleman Farthing var en tjänare hos den rika familjen Agamand vid Agamand Mills före Scourges invasion av Lordaeron. Han dog under katastrofen och skyller sina forna herrar för sin död. Han bär på ett starkt agg som följde med in i hans odöda tillvaro.",al={"vem är coleman farthing","coleman farthings bakgrund","farthings historia"}},{q="Varför vill Coleman Farthing ha arvegodset?",a="Farthing vill hämnas fullständigt på sina forna herrar. Genom att plundra deras förfäders svärd, yxa, dolk och stridsklubba ur familjegraven vill han beröva den fallna ätten dess sista spår av heder och minne.",al={"varför stjäla arvegods","colemans motiv","varför ta vapnen"}},{q="Vad hände med familjen Agamand?",a="Familjen Agamand omkom när Scourge drog fram över Tirisfal Glades. I stället för att finna frid i döden återuppväcktes de som viljelösa odöda slavar bundna till Lich Kings vilja. De vandrar nu bland sina förstörda kvarnar och i kryptan.",al={"agamandernas öde","lever agamanderna","vad är agamanderna nu"}},{q="Var ligger Agamand Family Crypt?",a="Kryptan ligger vid norra kanten av Agamand Mills, insprängd i de klippiga branterna med utsikt över de pesthärjade gårdarna i norra Tirisfal Glades.",al={"kryptans plats","var ligger kryptan","karta över agamand crypt"}},{q="Vilka vapen finns i kryptan?",a="Kryptan rymmer fyra olika förfädersvapen som tillhör ätten: Agamand Family Sword, Agamand Family Axe, Agamand Family Dagger och Agamand Family Mace.",al={"vilka arvegods","fyra arvegods","agamandernas vapen"}},{q="Varför angriper Forsaken familjen Agamand när båda är odöda?",a="Forsaken har fri vilja och kämpar för sin egen överlevnad, medan de odöda Agamanderna förblir viljelösa slavar under Scourge och tjänar Lich King, som Forsaken avskyr.",al={"odöda mot odöda","varför slåss de mot agamanderna","konflikten mellan forsaken och scourge"}}},fx={c3afbf3e={q="Vad ska Coleman Farthing göra med Agamand-arvegodset?",a="För Coleman Farthing representerar de fyra vapnen – Agamand-familjens svärd, yxa, dolk och stridsklubba – de sista resterna av hans forna herrars stolthet och släktlinje. Genom att vanhelga deras grav och ta vapnen berövar han de förbannade Agamand-ägorna de sista spåren av ära och minne, och förkunnar att familjen verkligen är borta.",al={"användning av agamand-arvegodset","vad är arvegodset till för","syftet med agamand-familjens vapen"}},c1f9d064={q="Vem vaktar Agamand Family Crypt?",a="Kryptan och de kringliggande kvarnarna är fulla av viljelösa undersåtar från Scourge, däribland de återupplivade kvarlevorna av själva Agamand-familjen. Dessa odöda är bundna till Lich Kings vilja, inte fria som Forsaken, och lurar i sina förfäders mörka gravar. De vaktar familjerelikterna ursinnigt mot alla inkräktare.",al={"fiender i agamand-kryptan","vem skyddar arvegodset","monster i agamand family crypt"}}},fp="17,169,25.388.0,21.294.0,33.207.0,45.158.0,36.182.0,42.149.0,39.145.0,63.162.0"}
P.entries["quest:1824"] = {n="Trial at the Field of Giants",s="I Camp Taurajo skickar Ruga Ragetotem krigarkandidater söderut för att möta en okänd fiende. De måste döda silithider i Field of Giants och återvända med flera ryckande antenner inom en halvtimme.",h="I Camp Taurajo skickar Ruga Ragetotem krigarkandidater söderut för att möta en okänd fiende.",kw={"barrens","camp taurajo","field of giants","ruga ragetotem","silithider","twitching antenna","krigarprov"},ang={["class:Warrior"]="Som krigare genomgår du denna övergångsrit omkring nivå tjugo. Den prövar hur snabbt du kan besegra svärmande fiender och uthärda en sträng tidsgräns.",["faction:Horde"]="Som medlem av Horden möter du silithidernas växande närvaro i södra Barrens. Prövningarna samlar också information om ett krypande hot.",["race:Tauren"]="Som taurenförsvarare hjälper du till att skydda jaktmarkerna kring Camp Taurajo genom att ta itu med skändningen vid Field of Giants och dess onaturliga, invaderande kupa."},sec={{t="Ett prov på snabbhet och stålhårdhet",b="I Camp Taurajo utmanar Ruga Ragetotem blivande krigare att bevisa sig mot en okänd motståndare. Hordens krigartränare prövar mer än stridsförmåga: kandidaterna måste döda varelserna och ta med färska antenner tillbaka inom en halvtimme. Färden genom södra Barrens prövar deras snabbhet och beslutsamhet, medan antennerna fortfarande måste rycka när de når Taurajo."},{t="Ovälkomna inkräktare",b="Silithidkupor reser sig i Field of Giants, under väldiga förstenade revben. De bisarra, krypande insekterna har nyligen kommit till Barrens och oroar taurenjägare och schamaner som vakar över savannerna. Ruga säger att deras närvaro bådar illa för Kalimdor. Provet prövar en ung krigares stridsinstinkter och samlar underrättelser om ett växande hot mot landet."}},faq={{q="Varför finns det en tidsgräns för antennerna?",a="Ruga Ragetotem kräver att antennerna fortfarande rycker när krigarna tar dem till Camp Taurajo, så de får bara trettio minuter på sig att jaga och återvända. Deras färskhet visar att kandidaten dödade en silithid i direkt strid i stället för att leta rätt på en död.",al={"varför tidsgräns","tidsgräns för ryckande antenner","hur lång tid"}},{q="Vilka varelser lever i Field of Giants?",a="Bisarra, aggressiva silithidgrävare lever i Field of Giants. De har grävt ut väldiga högar och kupor under uråldriga fossil, stört den lokala ekologin och oroat Horden.",al={"vad är det för insekter","varelser i field of giants","vad är silithider"}},{q="Vem är Ruga Ragetotem?",a="Ruga Ragetotem är en taurenkrigartränare i Camp Taurajo i södra Barrens. Han leder prövningar för hordkrigare som vill höja sin status och testar deras skicklighet, uthållighet och snabbhet.",al={"ruga","vem ger uppdraget","ruga ragetotems bakgrund"}},{q="Var ligger Field of Giants?",a="Field of Giants ligger rakt söder om Camp Taurajo, intill vägen före det södra passet mot Thousand Needles. Väldiga skelettrevben och silithidhögar utmärker fältet.",al={"var ligger field of giants","field of giants plats","var hittar jag insekterna"}},{q="Vart leder nästa steg i den här träningen?",a="När krigaren återlämnat de ryckande antennerna i tid skickar Ruga dem till Thun'grim Firegaze, en äldre orksmed som bor på toppen av en kulle öster om Crossroads. Thun'grim ska smida rustning åt beprövade krigare.",al={"nästa uppdrag","vad kommer efter","fortsättning på krigarkedjan"}},{q="Varför oroar sig tauren för insekterna?",a="Ruga säger att silithiderna är onaturliga nykomlingar i Barrens och att deras ankomst bådar illa för landet. Han misstänker att deras aggressiva grävande och expansion tyder på en större fara under sanden.",al={"varför bryr sig tauren","insekternas förebud","silithidhotet"}}},fx={["5312a899"]={q="Varför vill Ruga Ragetotem att det här ska göras?",a="Ruga Ragetotem prövar din stridsförmåga som en del av din krigarträning, samtidigt som han håller ett öga på ett växande hot. Märkliga insektslika varelser har nyligen dykt upp vid Field of Giants och oroar de lokala tauren. Genom att skicka dig för att snabbt gallra bland dem och hämta färska troféer innan de slutar sprattla, prövar Ruga din stridsförmåga, snabbhet och uthållighet ute i fält.",al={"ruga ragetotems motiv","varför prövning vid field of giants","varför skickar ruga dig"}},["2d3c0cc0"]={q="Varför behöver Ruga Ragetotem dig i stället för lägervakter?",a="Det här uppdraget är en personlig övergångsrit utformad särskilt för en blivande krigare under Rugas handledning. Lägervakterna måste försvara Camp Taurajo och hålla uppsikt över de närliggande gränstrakterna, medan du bevisar att du är redo att följa krigarens större väg genom att överleva hårda ensamma prövningar mot farliga rovdjur.",al={"varför jag prövning vid field of giants","varför skicka en äventyrare, ruga"}}},fp="28,199,25.384.0,19.369.0,42.255.0,43.190.0,22.200.0,37.185.0,41.214.0,47.206.0"}
P.entries["quest:1825"] = {n="Speak with Thun'grim",s="Det här uppdraget leder framväxande krigare i Horde till Thun'grim Firegaze, en berömd orcisk smed som slagit läger i The Barrens. Efter att ha bevisat sig genom krävande fysiska prövningar får krigarna låta smida skräddarsydd rustning som erkänsla för sitt mod. Uppdraget är den avgörande länken mellan allmän krigarprövning och tillverkningen av Brutal Armor.",h="Det här uppdraget leder framväxande krigare i Horde till Thun'grim Firegaze, en berömd orcisk smed som slagit...",kw={"the barrens","brutal armor","the crossroads","firegaze","ragetotem","ruga","thun'grim","krigare"},ang={["class:Warrior"]="Det här uppdraget markerar en viktig övergångsrit och lyfter dig från nybörjarkämpe till en erkänd mästare värdig skräddarsydd rustning.",["faction:Horde"]="Hordes rustningssmeder är stolta över att rusta sina främsta försvarare och ser till att de som strider vid gränsen bär utrustning som motsvarar deras bedrifter på slagfältet.",["profession:Blacksmithing"]="Thun'grim Firegaze står för den traditionella orciska smidesfilosofin: rustning av mästarhantverk måste förtjänas genom stridsprövningar, inte bara köpas för mynt."},sec={{t="Smedens kallelse",b="Efter att ha visat sitt mod mot silithidernas bon under Trial at the Field of Giants får krigare i Horde mer än bara beröm från Ruga Ragetotem. Snart når ryktet om deras uthållighet och stridskonst Thun'grim Firegaze, en berömd orcisk smed med ett läger på en ås öster om The Crossroads. Thun'grim känner igen en krigare som förtjänar hans hantverk och låter meddela att han vill smida en enastående brynja åt dem."},{t="En mästares krav",b="Thun'grim Firegaze smider inte åt vanliga soldater. För en rustningssmed med hans anseende måste stålet motsvara andan hos den som bär det i strid. När en krigare når hans läger visar det att hen lämnat enkla milisövningar bakom sig och är redo för de mödosamma, specialiserade uppgifter som krävs för att samla sällsynta hantverksmaterial runtom på Kalimdor."}},faq={{q="Vem är Thun'grim Firegaze?",a="Thun'grim Firegaze är en ansedd orcisk smed som slagit läger högst uppe på en klippig ås strax öster om The Crossroads i The Barrens. Han smider skräddarsydd, mäktig rustning åt krigare i Horde som har bevisat sitt mod i farliga prövningar.",al={"vem är thungrim","thungrim-lore","thungrim firegaze"}},{q="Varför skickar Ruga Ragetotem mig till honom?",a="Ruga Ragetotem förstår att du har vuxit ifrån de grundläggande prövningarna efter att ha överlevt silithiderna i södra The Barrens. Hen visar dig till Thun'grim, så att mästersmeden kan belöna din tjänst för Horde genom att smida en specialanpassad rustning åt dig.",al={"varför tala med thungrim","ruga skickar mig"}},{q="Var hittar jag Thun'grims läger?",a="Thun'grim har sitt läger på de höga klipporna öster om The Crossroads i The Barrens, med utsikt över den torra savannen.",al={"var finns thungrim","thungrims plats","hitta thungrim firegaze"}},{q="Vad händer efter att jag talat med Thun'grim?",a="Mötet med Thun'grim inleder uppdragskedjan Brutal Armor och skickar krigare till avlägsna trakter för att samla tåliga material som rökiga järntackor och järnstänger till en skräddarsydd brynja.",al={"nästa uppdrag efter thungrim","vad vill thungrim"}},{q="Är uppdraget tillgängligt för alla klasser?",a="Nej. Det här uppdraget och rustningskedjan hör helt och hållet till den krigsträning som är förbehållen krigare i Horde.",al={"kan andra än krigare göra detta","är det här bara för krigare"}},{q="Vilken prövning krävdes före det här mötet?",a="Före det här uppdraget måste krigare resa till södra The Barrens och klara Trial at the Field of Giants genom att samla ryckande silithidantenner för att visa sin uthållighet i strid.",al={"förutsättningsuppdrag","vad gjorde jag före det här"}}},fx={["2df90612"]={q="Varför skickar Ruga Ragetotem dig i stället för att gå själv?",a="Ruga Ragetotem övervakar träningen och prövningen av framväxande Horde-krigare från sin post vid Camp Taurajo. Thun'grim Firegaze hörde särskilt av sig och bad om dig, eftersom han hört talas om ditt mod och dina prövningar runt om i The Barrens. Ruga för bara vidare kallelsen, så att du kan få rustning smidd efter dina personliga mått.",al={"varför skicka mig, ruga","varför jag ruga ragetotem","varför behöver ruga mig"}}},fp="20,365,21.455.0,19.360.0,26.226.0,39.239.0,34.116.0,43.192.0,39.124.0,44.189.0"}
P.entries["quest:183"] = {n="The Boar Hunter",s="Boar Hunter är ett tidigt uppdrag från dvärgjägaren Talin Keeneye i Coldridge Valley. En kraftig ökning av klippvildsvinen har gjort skogen alltför farlig, så unga rekryter får i uppgift att gallra bland de aggressiva bestarna så att erfarna jägare kan spåra vilt i lugn och ro.",h="Boar Hunter är ett tidigt uppdrag från dvärgjägaren Talin Keeneye i Coldridge Valley.",kw={"anvilmar","boar hunter","coldridge valley","klippvildsvin","dun morogh","jakt","talin keeneye"},ang={["class:Hunter"]="Talin Keeneye står för dvärgarnas rättframma inställning till spårning: håll siktet stadigt, visa respekt för bestarna och röj snåren när villebrådet blir alltför fientligt.",["race:Dwarf"]="Den som bor i bergen måste dela marken med vildsint djurliv. Att gallra bland de stridslystna klippvildsvinen kring Anvilmar är en prövning för varje ung dvärg som tar sina första steg utanför smedjan.",["race:Gnome"]="För de gnomiska flyktingar som nyligen kommit från Gnomeregan blir mötet med Dun Moroghs våldsamma vildsvin en hård, praktisk introduktion till livet i det karga dvärglandet."},sec={{t="En trång dal",b="Coldridge Valley är vanligtvis en lugn, skyddad övningsplats för unga bergsvandrare och lärda från Ironforge. Men djurlivet blir ofta oroligt och alltför talrikt i det hårda vinterklimatet. Talin Keeneye, en erfaren jägare som håller till utanför Anvilmar, märker att de aggressiva, små klippvildsvinen har blivit så många att de utgör ett verkligt hot mot alla som vandrar längs de snötäckta stigarna."},{t="Att hålla snön i schack",b="Jakt är en hörnsten i dvärgarnas liv och ger kött, skinn och viktig övning i friluftsfärdigheter. Men när villebrådet blir en plåga som går till angrepp vid första anblicken måste det gallras för att återställa balansen. Genom att minska antalet klippvildsvin på dalens sluttningar visar unga äventyrare att de är redo för strid, samtidigt som de ger de lokala jägarna utrymme att ägna sig åt sin jakt utan att bli övermannade."}},faq={{q="Vem är Talin Keeneye?",a="Talin Keeneye är en dvärgjägare som håller till i Coldridge Valley, nära Anvilmar. Han ägnar dagarna åt att spåra vilt i snön och hjälper till att lära nya äventyrare hur det faktiskt är att röja undan fientliga bestar.",al={"talin keeneye","vem ger uppdraget boar hunter","boar hunter-npc"}},{q="Varför är klippvildsvinen ett så stort problem?",a="De små klippvildsvinen i Coldridge Valley har blivit ovanligt talrika och angriper alla de ser utan förvarning. Deras stora antal gör vanliga resor och jakt farliga för lokalbefolkningen.",al={"varför döda vildsvin","vildsvinsproblem i coldridge","varför är vildsvin farliga"}},{q="Var kan man hitta klippvildsvinen?",a="Små klippvildsvin strövar omkring på de öppna, snötäckta slätterna och i de glest skogbevuxna områdena runt Anvilmar, i hela Coldridge Valley.",al={"var finns vildsvinen","klippvildsvinens plats","karta över små klippvildsvin"}},{q="Har uppdraget koppling till ett större hot i dalen?",a="Nej. Till skillnad från trogginvasionerna som oroar dvärgarnas utposter handlar det här uppdraget bara om att hålla det lokala djurlivet i schack, så att stigarna förblir säkra och Talin kan jaga i lugn och ro.",al={"finns det ett fortsättningsuppdrag","boar hunter-uppdragskedja","historien bakom vildsvinen"}},{q="Vad gör klippvildsvinen lämpade för Dun Morogh?",a="Klippvildsvin är tåliga svin med tjock hud, byggda för att stå ut med den iskalla kylan i Dun Morogh. Deras aggressiva lynne och vassa betar hjälper dem att böka efter föda i frusen jord och värja sig mot rovdjur i bergen.",al={"klippvildsvinens bakgrund","dvärgarnas vildsvin","djurlivet i dun morogh"}},{q="Varför dödar inte Talin Keeneye vildsvinen själv?",a="Talin säger att de aggressiva vildsvinen är så många att hans lugna jaktturer har blivit obehagligt farliga. Han ber nya, ivriga äventyrare på genomresa i Anvilmar att gallra i flocken, så att han kan återgå till att spåra vilt som vanligt.",al={"varför behöver talin hjälp","är talin lat","varför kan talin inte jaga dem"}}},fx={aa61ef91={q="Varför vill Talin Keeneye att små klippvildsvin ska gallras ut?",a="Talin Keeneye tycker att vildsvinsjakt är ett utmärkt tidsfördriv, men det stora antalet små klippvildsvin som hemsöker Coldridge Valley har förstört hans nöje. Deras aggressiva natur och explosionsartade ökning har gjort hans dagliga rutin farlig i stället för avkopplande. När du gallrar ut ett dussin av bestarna blir dalen lite tryggare, så att han kan njuta av jakten utan att ständigt bli omringad.",al={"varför döda vildsvinen","talin keeneyes motiv","varför vill talin ha döda vildsvin"}},cf0c4f7e={q="Vad är små klippvildsvin, och varför finns de i Coldridge Valley?",a="Små klippvildsvin är de tåliga inhemska svinen i Dun Morogh. Deras tjocka skinn och häftiga humör hjälper dem att överleva den kalla bergsterrängen. Coldridge Valley erbjuder gott om föda längs de snöiga bergssluttningarna, men på sistone har deras antal ökat så dramatiskt att de strövar omkring överallt och går till aggressivt anfall mot alla som kommer nära.",al={"vad är klippvildsvin","varför finns vildsvinen här","små klippvildsvins bakgrund"}}},fp="15,186,16.338.0,17.316.0,21.170.0,38.164.0,34.116.0,57.168.0,43.211.0,49.186.0"}
P.entries["quest:1838"] = {n="Brutal Armor",s="En krigare i norra Barrens ställs inför Thun'grim Firegazes prov. Den nästan blinde smeden skickar erfarna horderkrigare genom avlägsna länder efter sällsynta ingredienser och smältmedel. När du uppfyller kraven på hans skriftrulle kan smidet av en komplett uppsättning brutal stridsrustning börja.",h="En krigare i norra Barrens ställs inför Thun'grim Firegazes prov.",kw={"barrens","brutal armor","brutal hauberk","fosfor","powdered azurite","smoky iron ingot","thun'grim firegaze","krigaruppdrag"},ang={["class:Warrior"]="Som krigare i horden bevisar du ditt mod och din uthållighet på flera kontinenter för att förtjäna skräddarsydd stridsrustning.",["faction:Horde"]="Som medlem av horden ser du orcher, taurer, troll och Fördärvade smeder förena sina olika hantverkstraditioner i en enda stridsrustning.",["profession:Blacksmithing"]="Som smed kan du se hur Thun'grims skriftrulle förenar sotigt järn, Powdered Azurite och phlogiston för att förädla vanlig järnsmältning."},sec={{t="En mästares kallelse",b="I norra Barrens lyssnar Thun'grim Firegaze efter nytt om kriget. Den erfarne orksmedens syn sviktar, men hans skicklighet vid smedjan är fortfarande oöverträffad. Rykten når honom om en krigare vars styrka och mod överträffar vanliga soldaters. Thun'grim tänker smida ringbrynja som kan stå emot de allra hårdaste striderna genom Kalimdor och Eastern Kingdoms."},{t="Ett sökande över kontinenterna",b="Thun'grims rustning kräver mer än vanlig malm. I skenet från elden vägleder hans sviktande syn honom när han skriver en noggrann skriftrulle för den centrala bröstplåten. Ingredienserna omfattar förädlat järn, sotiga järntackor som bärs av grävande kobolder, Powdered Azurite som bearbetas av gruvarbetare på andra sidan havet och en flyktig Vial of Phlogiston. Bara en krigare som är redo att möta prövningar i avlägsna länder kan samla ihop de material som krävs."},{t="Hammarens första slag",b="Thun'grims sällsynta material sätter ett mycket större arbete i rullning. När de anländer tänder han ugnen och smider Brutal Hauberk. Den gamle smeden inser att han inte kan fullborda en så ambitiös rustning ensam. Hela uppsättningen kräver skickliga hantverkare från hordens andra folk: en tauren som formar hjälmar, en troll som tillverkar handskar och en odöd som smider benskenor, alla på olika håll över kontinenterna."}},faq={{q="Vem är Thun'grim Firegaze?",a="Thun'grim Firegaze är en erfaren orksmed som bor på en kulle med utsikt över norra Barrens. Trots att hans syn sviktar är hans instinkter vid städet skarpa, och han smider kraftfull, skräddarsydd stridsringbrynja åt horderkrigare som är kända för sitt mod.",al={"vem är thun'grim","thun'grim firegazes bakgrund","thun'grims bakgrund"}},{q="Vad är Brutal Armor?",a="Brutal Armor är en uppsättning stridssmidd ringbrynja för erfarna horderkrigare. Hordens smeder förenar sina färdigheter för att tillverka den, och varje del kräver farliga resor för att hitta sällsynta alkemiska reagenser, renade malmer och uråldriga tekniker.",al={"vad är brutal armor","bakgrund om brutal armor-setet","krigarens rustningskedja"}},{q="Varför behöver Thun'grim så ovanliga ingredienser?",a="Thun'grim behöver ovanliga ingredienser eftersom vanligt järn är för sprött för att tåla de hårda slagen som en frontlinjekämpe utsätts för. Han använder Powdered Azurite, sotiga järntackor och flyktig phlogiston som flussmedel och härdningsmedel för att göra metallen tåligare och starkare.",al={"varför powdered azurite","varför fosfor","vad används reagenserna till"}},{q="Smider Thun'grim hela setet själv?",a="Nej. Thun'grim smider den centrala ringbrynjan, medan andra smeder inom horden tillverkar den matchande hjälmen, handskarna och benskenorna. Bland dem finns Orm Stonehoof, Ula'elek och Velora Nitely.",al={"tillverkar thun'grim allt själv","vem tillverkar delarna till brutal armor"}},{q="Vart leder den här uppdragskedjan härnäst?",a="Prövningen leder till smidet av Brutal Hauberk och öppnar vägen till smeder i Thunder Bluff, Sen'jin Village och Undercity för resten av den brutala stridsringbrynjan.",al={"vad kommer efter brutal armor","uppföljning till brutal armor"}},{q="Varför måste en krigare resa så långt efter materialen?",a="Resan prövar en krigares stridsvilja och uppfinningsrikedom. För att visa sig värdig en mästarsmidd rustning måste en krigare ta sig genom fiendeland, ge sig in i farliga gruvor och samla delar som är svåra att nå.",al={"varför resa till eastern kingdoms","varför så många material"}}},fx={["31952f55"]={q="Varför vill Thun'grim Firegaze tillverka den här rustningen?",a="Thun'grim har hört talas om ditt växande anseende inom Horde och vill smida en rustning som motsvarar din styrka. För den åldrande, nästan blinde smeden är det en ära och ett bevis på hans hantverk att smida legendarisk rustning åt en framväxande krigare på dennes resa.",al={"varför hjälper thun'grim mig","thun'grim firegazes motiv","varför tillverka brutal armor"}},["8131a754"]={q="Varför behöver Thun'grim att du samlar in materialen?",a="Thun'grim är en åldrad orc vars syn nästan helt har försvunnit; det tog honom flera nätter att ens skriva ner dina instruktioner. Att samla farliga reagenser från avlägsna gruvor och vilda bestar ligger långt bortom hans fysiska förmåga, så en beprövad krigare måste ge sig ut på färden.",al={"varför måste jag skaffa materialen","varför jag brutal armor","varför behöver thun'grim min hjälp"}}},fp="12,258,18.364.0,26.416.0,30.378.1,26.254.0,21.242.0,49.278.0,44.175.1,38.181.1,61.213.0"}
P.entries["quest:1839"] = {n="Ula'elek and the Brutal Gauntlets",s="Thun'grim Firegaze skickar dig från The Barrens till Sen'jin Village för att hämta Brutal Gauntlets. Där smider Darkspear-hantverkaren Ula'elek dem åt dig.",h="Thun'grim Firegaze skickar dig från The Barrens till Sen'jin Village för att hämta Brutal Gauntlets.",kw={"brutal gauntlets","darkspear","durotar","sen'jin village","the barrens","thun'grim firegaze","ula'elek","krigare"},ang={["class:Warrior"]="Som krigare i Horden markerar arbetet med att sätta ihop Brutal Armor din väg mot att bli en stridshärdad frontkämpe.",["faction:Horde"]="Som medlem av Horden ser du orksmeder i The Barrens och trollsmeder i Durotar arbeta tillsammans och knyta samman Thralls unga koalition.",["race:Troll"]="Som troll visar Ula'eleks arbete hur Darkspears smideskonst och andliga samklang bidrar till Hordens krigsinsats."},sec={{t="En resa till kusten",b="Thun'grim Firegaze skickar dig österut efter att du visat ditt mod i The Barrens och börjat sätta ihop Brutal Armor-setet. Den erfarne orksmeden förlitar sig på skickliga hantverkare runtom i Horde-länderna i stället för att smida varje del vid sin bergsfästning. För de tunga ringbrynjehandskarna hänvisar han dig till Durotars klippiga sydkust."},{t="Loas ögon",b="I Sen'jin Village arbetar trollrustmästaren Ula'elek bland sina Darkspear-fränder. Thun'grim har redan berättat om dina bedrifter för honom, och Ula'elek säger att andarna har bevittnat dina segrar i strid. För en krigare som förtjänar sin plats bland Hordens elit går fint hantverk och andligt erkännande hand i hand."}},faq={{q="Vem ger uppdraget Ula'elek and the Brutal Gauntlets?",a="Orkrutmakaren Thun'grim Firegaze, som håller till högt uppe i bergen i The Barrens, ger dig uppdraget.",al={"uppdragsgivare","vem startar ula'elek and the brutal gauntlets","thun'grim firegaze uppdrag"}},{q="Var hittar jag Ula'elek?",a="Du hittar Ula'elek i Sen'jin Village på Durotars sydkust.",al={"ula'eleks plats","var finns ula'elek","ulaelek senjin"}},{q="Vad är Brutal Armor-setet?",a="Brutal Armor är ett specialtillverkat ringbrynje-set för erfarna Horde-krigare kring sin trettionde säsong. Allierade smeder runtom i Kalimdor tillverkar delarna.",al={"brutal armor","vad är brutal gauntlets","krigarens klassrustning nivå 30"}},{q="Vad händer när jag kommer fram till Ula'elek?",a="Efter att ha välkomnat dig och erkänt dina bedrifter i strid ber Ula'elek dig samla de exotiska materialen till Brutal Gauntlets, med Satyr Hooves som första ingrediens.",al={"nästa uppdrag","efter samtalet med ula'elek","satyr hooves uppdrag"}},{q="Varför skickar Thun'grim dig till en trollrustningssmed?",a="Thun'grim låter Hordens främsta specialiserade smeder dela på arbetet med att smida Brutal Armor-setet. En av dem är Darkspear-hantverkaren Ula'elek, som tillverkar handskarna.",al={"varför ula'elek","varför bege sig till sen'jin village","trollsmed brutal armor"}},{q="Har alliansspelare ett motsvarande uppdrag?",a="Alliansens krigare genomgår ett liknande krigarprov för att tillverka klasspecifik rustning, men Brutal Armor-kedjan och Ula'eleks arbete tillhör Horden.",al={"alliansens brutal gauntlets","motsvarighet för alliansen"}}},fx={a664db53={q="Varför vill Thun'grim Firegaze att du reser till Sen'jin Village?",a="Thun'grim Firegaze vägleder dig medan du växer som krigare i Horde. Han övervakar din träning, men den uråldriga konsten att smida Brutal Armor kräver särskilda färdigheter hos andra hantverkare runt om i Horde-länderna. Ula'elek i Sen'jin Village är en skicklig Darkspear-rustningssmed som står i förbindelse med andarna och passar för att smida handskarna. Thun'grim skickar dig dit personligen både för att beställa rustningsdelen och för att du ska visa din hängivenhet och vinna rustningssmedens förtroende direkt.",al={"varför jag ula'elek","varför kan inte thun'grim smida handskarna","varför skicka en krigare till durotar"}}},fp="33,143,22.321.0,19.303.0,54.89.0,26.69.0,29.140.0,37.162.0,50.157.0,53.150.0"}
P.entries["quest:184"] = {n="Furlbrow's Deed",s="Familjen Furlbrow flyr från sin gård medan Defias-banditer för deras lagfart genom Elwynn Forest. Om du återlämnar lagfarten till Farmer Furlbrow nära gränsen till Westfall bevarar paret sitt anspråk på sitt stulna hem.",h="Familjen Furlbrow flyr från sin gård medan Defias-banditer för deras lagfart genom Elwynn Forest.",kw={"defias","elwynn","furlbrow","theodore furlbrow","verna furlbrow","westfall","lagfart i westfall"},ang={["class:Paladin"]="Som paladin hedrar du dina heliga löften att försvara de försvarslösa och skipa rättvisa i laglösa gränstrakter när du återlämnar en stulen lagfart till flyktingar.",["faction:Alliance"]="Familjen Furlbrows svåra situation visar att Stormwinds krona har misslyckats med att skydda sina skattebetalande invånare utanför huvudstadens befästa murar."},sec={{t="Ett spår på stulet papper",b="Defias-banditer i Elwynn bär på en lagfart undertecknad av Theodore och Verna Furlbrow. En grovhuggen anteckning på baksidan säger att de drev bort den åldrande bonden från hans egendom och sedan förde dokumentet över floden till Elwynn för att kopiera det och förfalska anspråk på annan mark de lagt beslag på. I anteckningen står det att familjen Furlbrow blev strandsatt strax bortom gränsen, vid vägen, efter att deras vagn gått sönder."},{t="Westfalls bönders svåra situation",b="Defias har drivit bort dussintals familjer från deras ärvda mark i Westfall. När Stormwinds armé är frånvarande och rikets resurser är ansträngda använder Brotherhood våld och falska anspråk för att ta över kungarikets kornbod. Theodore och Verna lämnar sin gård för att sätta sig i säkerhet, men deras lagliga lagfart bevarar deras anspråk om ordningen någonsin återvänder till provinsen."}},faq={{q="Var hittar jag lagfarten?",a="Banditer från Defias Brotherhood bär lagfarten i södra och västra Elwynn Forest, bland annat nära Jerod's Landing och i läger i området.",al={"lagfartsbyte","så får du tag på familjen furlbrows lagfart","var faller lagfarten"}},{q="Var finns Farmer Furlbrow?",a="Farmer Furlbrow och hans fru Verna har blivit strandsatta vid sin trasiga vagn på huvudvägen, strax innanför Westfall, kort efter att du korsat bron västerut från Elwynn Forest.",al={"familjen furlbrows plats","var lämnar man in familjen furlbrows lagfart","var finns bonden"}},{q="Varför ville Defias ha lagfarten från början?",a="En anteckning på baksidan säger att banditerna tänker kopiera Furlbrows giltiga lagfart och förfalska anspråk på andra egendomar för att stärka sitt grepp om stulna gårdar med falska dokument.",al={"varför stal banditerna lagfarten","varför vill defias ha lagfarter"}},{q="Återvänder familjen Furlbrow till sin gård?",a="Paret flyr från området på grund av laglöshet och banditangrepp. Om de behåller sin lagfart kan de återta sin mark lagligt om Westfall någonsin bringas till fred.",al={"åker familjen furlbrow hem","vad händer med familjen furlbrows gård"}},{q="Varför skyddar inte Stormwind de här gårdarna?",a="Stormwinds beskydd har sviktat efter kung Varian Wrynns plötsliga försvinnande och de inrikespolitiska spänningarna. När kungliga resurser riktas mot huvudstaden lämnas avlägsna områden som Westfall att möta Defias Brotherhoods växande styrka.",al={"varför finns det inga vakter i westfall","varför ignorerar stormwind westfall"}},{q="Hur hänger Elwynn och Westfall ihop i det här uppdraget?",a="Defias nätverk sträcker sig från Elwynn Forest över floden till Westfall och visar hur långt dess räckvidd når in i kungarikets kärnområden.",al={"varför fanns lagfarten i elwynn","samband mellan områdena"}}},fx={["9b306b68"]={q="Varför ska jag återlämna Furlbrow's Deed?",a="Själva lagfarten är bara en livlös papperslapp, men meddelandet på baksidan avslöjar att Defias-rövare skrämde Theodore och Verna Furlbrow till att avstå från sin mark. Tjuvarna tänkte använda den som mall för att förfalska anspråk på andra egendomar. Om du återlämnar den till de flyende Furlbrow-familjemedlemmarna får en ärlig jordbrukarfamilj det enda ägarbevis de har kvar. Det ger dem hopp om att en dag återta sitt stulna arv, om freden någonsin återvänder till Westfall.",al={"varför återlämna lagfarten","westfalls lagfarts motiv","syftet med furlbrow's deed"}}},fp="15,214,22.371.0,32.368.0,26.131.0,25.172.0,52.176.0,42.168.0,43.239.0,65.148.0"}
P.entries["quest:1840"] = {n="Orm Stonehoof and the Brutal Helm",s="Det här ärendet leder lovande krigare i Horden till Thunder Bluff för att rådfråga Orm Stonehoof, en smedmästare. På rekommendation av Thun'grim Firegaze har Orm det särskilda hantverkskunnande som krävs för att smida Brutal Helm.",h="Det här ärendet leder lovande krigare i Horden till Thunder Bluff för att rådfråga Orm Stonehoof, en...",kw={"rustningsuppdrag","brutal helm","orm stonehoof","thun'grim firegaze","thunder bluff","krigare"},ang={["class:Warrior"]="Det här uppdraget markerar övergången till rejält huvudskydd och skickar krigare till en av Hordens främsta mästersmeder.",["faction:Horde"]="Uppdraget visar samarbetet mellan orciska vapenmästare i The Barrens och taurenhantverkare högt ovanför Thunder Bluff."},sec={{t="En rekommendation i järn",b="Efter att ha visat sitt mod och samlat delar till Brutal Armor i The Barrens skickas krigarna högre upp till mesastaden Thunder Bluff. Thun'grim Firegaze, själv en skicklig rustningssmed, inser sina begränsningar och hänvisar sina kämpar till Orm Stonehoof. Orms hantverk är berömt i hela Kalimdor, särskilt hans förmåga att forma tåliga hjälmar för slagfältet av sällsynta, vilda troféer."},{t="Hantverkaren vid dammen",b="Orm har sitt hem och sin arbetsplats på Mulgore höga klippor, nära det stilla vattnet under stadens väldiga centrala totem. När en krigare kommer med ett meddelande från Thun'grim lämnar Orm sitt rutinjobb för att diskutera de krävande komponenter som behövs för att smida huvudskydd värdigt Hordens frontlinjer."}},faq={{q="Vem är Orm Stonehoof?",a="Orm Stonehoof är en skicklig taurenrustningssmed som bor i Thunder Bluff. Han är känd för sitt hantverk och hjälper krigare som skickats av Thun'grim Firegaze att skapa specialanpassat stridshuvudskydd.",al={"orm stonehoof","vem är orm"}},{q="Var finns Orm Stonehoof?",a="Han finns mitt i Thunder Bluff, nära vattenbassängen intill stadens väldiga centrala totem.",al={"var finns orm","orm stonehoof plats","hitta orm"}},{q="Varför skickar Thun'grim Firegaze dig till Thunder Bluff?",a="Thun'grim kan smida bröstplåten och andra delar av Brutal-setet, men medger att Orm Stonehoof har den exakta expertis som krävs för att tillverka Brutal Helm.",al={"varför thunder bluff","varför träffa orm"}},{q="Vad är Brutal Helm?",a="Brutal Helm är en ikonisk huvudbonad som smids åt Horde-krigare som nått veteranstatus. Den kräver farliga material från bestar runt om i Kalimdor.",al={"uppdraget brutal helm","vad är brutal helm"}},{q="Vad ber Orm dig göra härnäst?",a="När du talat med Orm skickar han dig att samla in de besttroféer som behövs till hjälmen. Börja med att jaga chimaeror i vildmarken och ta en Chimaeric Horn.",al={"nästa uppdrag","efter orm stonehoof","uppdraget chimaeric horn"}},{q="Kan alla klasser ta det här uppdraget?",a="Nej. Den här uppdragskedjan är endast för krigare som kommit långt nog i sin stridsträning och slutfört Thun'grims första rustningsuppgifter.",al={"är det bara för krigare","vem kan ta uppdraget"}}},fx={["528c5ae8"]={q="Varför vill Thun'grim Firegaze att du ska träffa Orm Stonehoof?",a="Thun'grim Firegaze har hjälpt till att vägleda din träning som krigare, men att smida en brutal hjälm kräver en mästerhantverkare vars skicklighet överträffar vanlig smideskonst. Thun'grim känner till Orm Stonehoofs oöverträffade skicklighet i att bearbeta metall och ben och skickar dig därför till tauren-hantverkaren i Thunder Bluff, så att du kan få en rustningsdel värdig din växande styrka och tjänst för Horde.",al={"thun'grim firegazes motiv","varför skicka till orm stonehoof","thun'grims skäl för brutal-hjälmen"}}},fp="33,127,24.374.0,23.303.0,21.153.0,33.80.0,54.143.0,24.149.0,27.121.1,30.130.0"}
P.entries["quest:1841"] = {n="Velora Nitely and the Brutal Legguards",s="Thun'grim Firegaze skickar Hordens krigare över Stora havet för att få Velora Nitelys Brutal Legguards. I Undercity använder den försmädliga smeden hantverket hon bevarade från sitt dödliga liv för att smida rustningen. Hennes arbete bidrar till att sätta samman en slitstark rustning åt Hordens krigare.",h="Thun'grim Firegaze skickar Hordens krigare över Stora havet för att få Velora Nitelys Brutal Legguards.",kw={"brutal armor","brutal legguards","lordaeron","thun'grim firegaze","trade quarter","undercity","velora nitely","krigaruppdrag"},ang={["class:Warrior"]="Som krigare når du en milstolpe i Hordens rustningsprövningar kring nivå trettio, när du reser bortom Kalimdor för specialiserad klassrustning.",["faction:Horde"]="Som medlem av Horden går du in i ett uppdrag som för samman orcher, troll och taurer från Kalimdor med försmädliga hantverkare i Eastern Kingdoms.",["race:Undead"]="Som försmädlig kan du se Velora Nitely föra vidare Lordaerons förfinade färdigheter och konstnärliga arv."},sec={{t="En resa över havet",b="Thun'grim Firegaze skickar dig österut över Stora havet för att hitta en smed till Brutal Legguards. Du har visat ditt värde för den erfarne smeden under hans vaka i The Barrens, och nu hänvisar han dig till den legendariska Brutal Armor. Thun'grim kan inte tillverka hela rustningen ensam, så han förlitar sig på skickliga allierade runtom i Horden. Benskydden kräver en hantverkare vars arbete vör d a d e s innan mänskligheten i norr föll, i de försmädliga underjordiska rike."},{t="Velora Nitelys hantverk",b="Velora Nitely arbetar i Undercitys Trade Quarter, där hennes gamla hantverk fortfarande tjänar Horden. Innan Scourge avslutade hennes dödliga liv var hon en av kungariket Lordaerons främsta rustningssmeder. Hennes hemland fördärvades och hon blev en av de försmädliga, men döden tog inte hennes mästerskap i metall ifrån henne. Nu riktar hon sin mänskliga skicklighet mot Hordens krigare, med torr, makaber humor kring att vara odöd."}},faq={{q="Vem är Velora Nitely?",a="Velora Nitely hyllades en gång som en av de skickligaste rustningssmederna i kungariket Lordaeron. Efter det tredje kriget återuppstod hon som en av de försmädliga och slog sig ner i Undercitys Trade Quarter, där hon fortfarande utövar sitt hantverk för Horden.",al={"velora nitelys bakgrund","vem är velora","den fördömda smeden velora"}},{q="Varför skickar Thun'grim mig till Undercity?",a="Thun'grim Firegaze skickar dig till Undercity eftersom hela Brutal Armor-setet kräver skickliga hantverkare runtom i Horden. Han känner till Veloras rykte som rustningssmed och skickar dig till Lordaeron för att beställa benskydden av henne.",al={"varför åka till undercity","thun'grim-uppdraget i undercity","krigare från the barrens till undercity"}},{q="Var hittar jag Velora Nitely i Undercity?",a="Velora Nitely arbetar i Undercitys Trade Quarter, vid smedjorna bland smeder och andra mästerhantverkare som tjänar Lady Sylvanas Windrunner.",al={"velora nitelys plats","var finns velora nitely","hitta velora nitely"}},{q="Vad händer efter att jag har talat med Velora Nitely?",a="Velora ber dig samla skenben från Dragonmaw-orcher i Wetlands till dina Brutal Legguards.",al={"nästa uppdrag efter velora","dragonmaw-skenbensuppdrag","vad vill velora ha"}},{q="Säger Velora något om att vara odöd?",a="Ja. Velora skämtar torrt om huruvida hon tillverkar rustningen åt dig eller tvärtom. Hon säger att hon förlorade sin humor ungefär samtidigt som hon förlorade luktsinnet och slutade andas.",al={"veloras skämt","den odöda smedens dialog","veloras humor"}},{q="Är Brutal Armor bara till för krigare?",a="Ja. Prövningarna för Brutal Armor, däribland att söka upp Velora Nitely för benskydden, är till för Hordens krigare som avancerar genom de erfarna leden.",al={"kan andra klasser få brutal armor","brutal armor-uppdrag bara för krigare"}}},fx={["7eb107f7"]={q="Varför vill Thun'grim Firegaze att det här ska göras?",a="Thun'grim Firegaze hjälper dig att smida hela din uppsättning Brutal Armor, en stridsmässig övergångsrit för lovande krigare i Horde. Thun'grim kan själv tillverka flera delar, men benskenornas specialiserade hantverk överstiger hans personliga smidesteknik. Därför hänvisar han dig till Velora Nitely, som är känd som en av Lordaerons främsta rustningssmeder.",al={"thun'grim firegazes motiv","varför tillverka brutal legguards","varför skicka till velora nitely"}}},fp="38,269,24.444.0,29.430.0,21.257.0,40.233.0,48.145.0,43.98.1,49.198.0,34.141.0"}
P.entries["quest:1842"] = {n="Satyr Hooves",s="I Sen'jin Village skickar Ula'elek krigare norrut efter Satyr Hooves. Han behöver deras märkliga kraft för att smida brutala handskar.",h="I Sen'jin Village skickar Ula'elek krigare norrut efter Satyr Hooves.",kw={"ashenvale","brutal gauntlets","durotar","hovar","satyr","sen'jin village","ula'elek","klövlös"},ang={["class:Warrior"]="Som krigare möter du listiga demoniska bakhållskrigare som en del av din utvecklingsrit. Prövningen testar din motståndskraft i strid och ger dig en personlig rustning.",["faction:Horde"]="Som Horde-krigare lämnar du Durotars torra slätter och färdas djupt in i omstritt nattalvsterritorium i Ashenvale.",["race:Troll"]="Som troll ser du Darkspears hantverk i Ula'eleks metoder: han utvinner rå essens ur besegrade magiska fiender i stället för att enbart förlita sig på traditionell smideskonst."},sec={{t="Att tämja fördärvad essens",b="Ula'elek skickar dig in i Ashenvales urgamla skogar för att samla det hans hantverk kräver. Demonisk korruption dröjer sig fortfarande kvar hos satyrernas klaner där, och han söker mer än järn och läder till rustning som ska kunna mäta sig med Kalimdors hårdaste styrkor."},{t="Ashenvales magiska svullnad",b="I nordöstra Ashenvale livnär sig satyrer på skogens kvarvarande renhet och förvrider den till vidrig kraft. De som får i sig mest utvecklar svullna hovar utan den vanliga kluvna formen. Ula'elek planerar att utvinna den koncentrerade magin och väva in den i handskarna han tillverkar."}},faq={{q="Varför behöver Ula'elek satyrhovar?",a="Ula'elek behöver hovarna för att ge kraft åt de brutala handskar han tillverkar. Han tänker utvinna skogsmagin som satyrerna har dränerat och fördärvat.",al={"varför satyrhovar","hovarnas syfte","vad hovarna är till för"}},{q="Var hittar man satyrerna?",a="Satyrer håller till i nordöstra Ashenvale, bland fördärvade urgamla ruiner, där de dränerar den djupa skogens kvarvarande magi.",al={"var satyrer finns","satyrernas plats","var man hittar satyrhovar"}},{q="Vad är speciellt med en klövlös hov?",a="En hov utan kluven form kännetecknar en satyr som har frossat i Ashenvales rena magi. Den stulna kraften får dess fötter att svälla.",al={"klövlösa hovar i berättelsen","varför klövlös","svullna hovar"}},{q="Vem är Ula'elek?",a="Ula'elek är en skicklig rustningshantverkare av Darkspear-trollen i Sen'jin Village, i södra Durotar. Han hjälper krigare att tillverka utrustning för prövningar.",al={"vem är ula'elek","uppdragsgivare","troll i sen'jin"}},{q="Vilken rustning smider Ula'elek?",a="Ula'elek förbereder ett par Brutal Gauntlets, tunga handskydd genomsyrade av stulen magi för Horde-krigare på frammarsch.",al={"vad är brutal gauntlets","handskuppdrag","rustningsbelöning"}},{q="Tjänar satyrerna Burning Legion här?",a="Ja. Satyrer är urgamla nattalver som förvandlats genom demoniska pakter. Klanerna som dröjer sig kvar i Kalimdors skogar brukar fortfarande kaoskorruption i demoniska makters tjänst.",al={"satyrernas lojalitet","är satyrerna legionen"}}},fx={["749a1d7b"]={q="Varför finns satyrerna i nordöstra Ashenvale?",a="Satyrerna hemsöker nordöstra Ashenvale för att frossa i den uråldriga skogens renhet. Genom att suga ut och förvrida dess latenta förtrollningar stärker de sina onda ritualer och förvrider sina egna kroppar. De som frossar mest i Ashenvales naturmagi utvecklar groteska, svullna klövar utan klövspalt och blir levande kärl för koncentrerad arkan styrka.",al={"varför satyrer i ashenvale","bakgrund om satyrklövar","vem jagar vi klövar åt"}}},fp="12,123,28.236.0,30.277.0,36.148.0,27.122.0,36.127.0,16.130.0,31.118.0,44.167.0"}
P.entries["quest:1843"] = {n="Brutal Gauntlets",s="Ula'elek har färdigställt ett par Brutal Gauntlets åt en erfaren krigare i Horde. Sällsynta material från avlägsna länder har använts i arbetet, som ska hedra både smeden och bäraren.",h="Ula'elek har färdigställt ett par Brutal Gauntlets åt en erfaren krigare i Horde.",kw={"rustningssmide","brutal gauntlets","durotar","horde","satyrklövar","ula'elek","krigarrustning"},ang={["class:Warrior"]="Som krigare bär du handskar avsedda för tung närstrid. De markerar ett steg mot ett disciplinerat militärt ledarskap.",["faction:Horde"]="Som medlem i Horde för du dina hantverkares tradition och krigiska stolthet med dig ut i strid. Deras arbete bär på andlig tyngd och ära."},sec={{t="En hantverkares mästerverk",b="Ula'elek låter sitt arv och sin skicklighet prägla smidet av rustning åt en erfaren frontkrigare. I Durotar formar hantverkaren i Horde brutala handskar av förhärdade troféer från farliga fiender. Den färdiga rustningen ska tåla hårda slag och stärka bärarens attacker."},{t="Förfädernas ära",b="För orcher och troll för med sig fina vapen och rustningar smedjans prestige och smedens anda ut i strid. När Ula'elek överlämnar de färdiga handskarna anförtror han en krigare sina förfäders arv. En mästare som bär dem förväntas möta hantverket med mod, krigisk disciplin och styrka."}},faq={{q="Vem är Ula'elek?",a="Ula'elek är en hantverkare i Durotar som tillverkar skräddarsydd rustning åt krigare i Horde. Han ber om exotiska material så att hans arbete hedrar hans yrke och förfädernas traditioner.",al={"ulaelek","vem ger brutal gauntlets","uppdragsgivare"}},{q="Varför behövdes satyrklövar till handskarna?",a="Satyrhovar är svullna och osplittrade, och rymmer kraft som sugit åt sig magi från Ashenvale. Ula'elek utvinner kraften och för in den i handskarna, vilket ger dem stor magi.",al={"varför satyrklövar","satyrdelar","använda material"}},{q="Vad innebär det för Ula'elek att bära handskarna?",a="För Ula'elek är handskarna hans hantverks främsta verk. Att ge dem till en värdig krigare hedrar hans yrke och förfäder och knyter hans arbete till Hordes segrar i strid.",al={"ära förfäderna","ula'eleks ära"}},{q="Var äger uppdraget rum?",a="Smidet avslutas i Durotar, orchernas och Darkspear Trolls torra hemland. Där inspekterar Ula'elek de återvunna materialen och överlämnar den färdiga rustningen.",al={"plats","var lämnas brutal gauntlets in"}},{q="Är den här prövningen avsedd för alla äventyrare?",a="Prövningen är avsedd för frontkrigare som har bevisat sin uthållighet och sitt krigiska engagemang. Den markerar deras avancemang till mer erfarna stridsroller inom Horde.",al={"bara för krigare","klasskrav"}},{q="Vad händer efter att man fått handskarna?",a="När handskarna tas emot är smidesprövningen avklarad. Krigaren är rustad att möta större hot på Azeroths krigshärjade slagfält.",al={"nästa uppdrag","fortsättning på brutal gauntlets"}}},fp="16,186,25.291.0,15.305.0,16.163.0,49.172.0,52.179.0,32.161.0,43.165.0,41.142.0"}
P.entries["quest:1844"] = {n="Chimaeric Horn",s="Som en del av krigarriten för att smida Brutal Helm ger Orm Stonehoof en blivande mästare i uppdrag att bege sig in i det ödelagda Charred Vale. Där måste krigaren jaga en vansinnig chimaeramoder för att ta hennes galvaniserade horn, både som en barmhärtighetshandling och ett bevis på styrka.",h="Som en del av krigarriten för att smida Brutal Helm ger Orm Stonehoof en blivande mästare i uppdrag att bege...",kw={"brutal helm","the charred vale","chimaeramatriark","chimaeriskt horn","galvanized horn","orm stonehoof","stonetalon","thunder bluff","krigaruppdrag"},ang={["class:Warrior"]="Den här prövningen testar krigarens förmåga att spåra upp ensamma alfadjur i brutala miljöer och vinna rätten att bära Brutal Helm.",["faction:Horde"]="Hordens krigare som utgår från Sun Rock Retreat tränger djupt in i Stonetalon Mountains omstridda vildmarker för att smida de vapen som behövs för Kalimdors försvar.",["race:Tauren"]="Orm Stonehoof närmar sig krigföring med taurenisk vördnad och påminner krigare om att även våld kan hedra Jordmodern, när man befriar ett plågat djur från dess lidande."},sec={{t="Ett prov på beslutsamhet",b="Orm Stonehoof är villig att smida den legendariska Brutal Helm åt hordens krigare, men krigartraditionen kräver att bäraren först bevisar sitt värde. Orm ber inte bara om råmetall eller mynt. Han kräver bevis på stridsförmåga och en vilja att möta de dystra ärr som lämnats efter förödande konflikter."},{t="Charred Vales ärr",b="Uppdraget leder krigare till de sydvästra delarna av Stonetalon Mountains, in i den askgrå ödemark som kallas Charred Vale. Dalen var en gång frodig och grön, men brändes till en rykande ödemark. De överlevande djur som strövar bland dess sotklädda kratrar har förvridits av vånda och raseri, särskilt de mäktiga chimaerorna som bygger bon bland de döda träden och heta ångventilerna."},{t="Barmhärtighet i strid",b="I den taureniske smedens ögon fyller det två syften att döda en chimaeramatriark. Det ger krigaren det härdade, galvaniserade horn som behövs för att tillverka hjälmen, men det gör också slut på varelsens lidande. När krigaren fäller matriarken blir hen både bödel och ett redskap för barmhärtighet åt en vild ande som drivits till vansinne av hemmets förstörelse."}},faq={{q="Vem är Orm Stonehoof?",a="Orm Stonehoof är en skicklig taurenisk smed som bor i Thunder Bluff. Han hjälper hordens veteraner att tillverka ikoniska delar av sina klassrustningar, däribland Brutal Helm.",al={"orm stonehoof historia","vem är orm stonehoof","smeden orm i thunder bluff"}},{q="Varför vill Orm ha det galvaniserade hornet?",a="Det galvaniserade hornet fungerar både som en tålig beståndsdel i Brutal Helm och som ett konkret bevis på att krigaren har modet att spåra upp och besegra ett farligt alfadjur i oländig terräng.",al={"galvaniserat horns användning","varför skaffa ett galvaniserat horn","horn till brutal helm"}},{q="Vad är chimaeror i Stonetalon?",a="Chimaeror är stora, tvåhövdade bevingade bestar som hör hemma i Kalimdors vildmarker. De som överlevt i Charred Vale har drivits till våldsamt vansinne av bränderna och förstörelsen av sina boplatser.",al={"chimaeror i stonetalon","chimaerors historia","vad är chimaeror"}},{q="Hur passar det här uppdraget in i krigarträningen?",a="När de närmar sig sin trettionde säsong hänvisas hordens krigare till specialister som Orm Stonehoof för att genomgå farliga prövningar. När de klarat utmaningarna får de bära det tunga, spikförsedda rustningssetet Brutal, som är utformat för mästare på slagfältet.",al={"krigarens uppdragskedja för brutal helm","krigaruppdrag i thunder bluff på nivå 30","uppdragskedja för brutal-rustningen"}},{q="Varför beskriver Orm jakten som en barmhärtighetshandling?",a="Taurenkulturen betonar harmoni med jorden och dess varelser. Charred Vales invånare lider ständigt av plågorna efter förödelsen av sitt land. Därför ses det som att befria ett lidande djur från ändlös vånda när matriarken dödas, snarare än som meningslöst slaktande.",al={"varför visa matriarken barmhärtighet","befria henne från hennes lidande"}}},fx={["3a1b9e89"]={q="Vad används Galvanized Horn till?",a="Orm Stonehoof har två användningsområden för Galvanized Horn. Rent praktiskt ger det det kraftiga, härdade horn som behövs för att smida din Brutal Helm. Rituellt fungerar det som ett fysiskt bevis på att du trotsade Charred Vales asködemarker, konfronterade en vansinnig chimärmatriark och visade både stridsstyrka och barmhärtighet genom att ge henne en frist från lidandet.",al={"användning av galvanized horn","varför behöver jag galvanized horn","galvanized horn till brutal helm"}},["241e9666"]={q="Vem skickas du för att jaga i Charred Vale?",a="Du skickas för att jaga en chimärmatriark som håller till bland ruinerna i Charred Vale. Dalen var en gång en lummig höglandsdal, men ödelades fullständigt av eld och förstörelse. De överlevande bestarna drevs till vansinne av plåga och förtvivlan. Matriarken är ett av dessa majestätiska rovdjur. Nu lider hon utan slut i den fördärvade askan, tills du ger henne en hedervärd död.",al={"mål för chimärmatriark","vem ska jag döda i charred vale","mål för chimaeric horn"}},c3120874={q="Varför skickar Orm dig i stället för att gå själv?",a="Orm Stonehoof prövar din anda. Han ber dig inte utföra ett rutinärende. Brutal Helm är en traditionell, kraftfull rustningsdel som bara ges till krigare som visat sin beslutsamhet, stridsförmåga och förmåga till hedervärd barmhärtighet. När du själv jagar besten i Charred Vales fientliga ödemarker bevisar du för Orm att du förtjänar att bära hans verk.",al={"varför skickar orm mig","varför jagar orm inte matriarken","varför behöver orm en äventyrare"}}},fp="14,192,17.230.0,29.276.0,15.259.0,21.146.0,38.168.0,33.157.0,46.227.0,47.231.0"}
P.entries["quest:1845"] = {n="Brutal Helm",s="Brutal Helm markerar slutpunkten på ett krävande krigarprov under Orm Stonehoofs ledning på Thunder Bluff. Efter att ha samlat sällsynta troféer från bestar i Kalimdor får en blivande krigare en imponerande hjälm med horn som bevis på sin styrka.",h="Brutal Helm markerar slutpunkten på ett krävande krigarprov under Orm Stonehoofs ledning på Thunder Bluff.",kw={"brutal helm","chimaeric horn","jordemodern","hunter rise","orm stonehoof","thunder bluff","krigare"},ang={["class:Warrior"]="Den här riten är en viktig milstolpe för hordens krigare och för dem vidare till tunga rustningar smidda av våldsamma bestar och välsignade av erfarna veterantränare.",["faction:Horde"]="Provet för Brutal Armor säkerställer att mästarna som strider under hordens baner har den råa fysiska uthållighet och jaktförmåga som deras ledare kräver.",["race:Tauren"]="Hjälmen ges i Thunder Bluff och speglar tauren-traditionen att förvandla jakttroféer till skyddande krigsutrustning under Jordemoderns nåd."},sec={{t="En krigares rit",b="Orm Stonehoof är en sträng smed i Thunder Bluff och vägleder hordens krigare genom hårda övergångsriter. Proven kräver bevis på stridsförmåga och driver de invigda ut i förrädisk terräng för att jaga våldsamma varelser och ta sällsynta troféer. Bara de som uppfyller Orms höga krav får träffa honom för att färdigställa sin rustning."},{t="Jordemoderns gåva",b="När krigaren överlämnar det sällsynta chimaeriska hornet till Orm Stonehoof bevisar hen sin beslutsamhet inför vildmarkens faror. Som erkänsla ger Orm krigaren Brutal Helm, en tung och hotfull ringbrynja skapad för att hedra besten och stärka bäraren i stridens främsta led. När han överräcker den åkallar Orm Jordemoderns välsignelser och ser fram emot de större dåd som krigaren är ämnad att utföra runtom i Azeroth."}},faq={{q="Vem ger Brutal Helm?",a="Orm Stonehoof, en vördad tauren-smed i Thunder Bluff, ger Brutal Helm till hordens krigare som klarar hans prov.",al={"vem ger brutal helm","brutal helm npc","orm stonehoof-uppdrag"}},{q="Vilket uppdrag måste slutföras innan man får hjälmen?",a="Du måste klara provet 'Chimaeric Horn', som kräver att du jagar våldsamma bestar i vildmarken och lämnar deras horn till Orm Stonehoof i Thunder Bluff.",al={"förkrav för brutal helm","chimaeric horn-uppdrag"}},{q="Var finns Orm Stonehoof?",a="Orm Stonehoof finns nära bassängen vid den stora centrala totempålen i högplatåstaden Thunder Bluff.",al={"orm stonehoofs plats","var finns orm stonehoof"}},{q="Varför åkallar Orm Stonehoof Jordemodern?",a="Som tauren vördar Orm Jordemodern som världens skapare och andliga beskyddare. Att be om hennes välsignelse över en färdig krigarhjälm speglar den traditionella tauren-tron att styrka i strid måste balanseras med andlig vördnad.",al={"varför nämns jordemodern","jordemoderns historia"}},{q="Är det här provet öppet för alla äventyrare?",a="Nej. Provet och dess Brutal Armor-belöningar är förbehållna hordens krigare som bevisar sitt värde genom särskilda klassuppdrag.",al={"kan vem som helst få brutal helm","brutal helm klass"}},{q="Vad betyder Brutal Armor-setet?",a="Delarna i Brutal Armor står för krigarens utveckling från novissoldat till hordens elitmästare. De tillverkas av material som samlats från de våldsammaste rovdjuren i Kalimdor.",al={"brutal armor historia","varför heter den brutal helm"}}},fx={["3a1185bd"]={q="Varför belönar Orm Stonehoof dig med Brutal Helm?",a="Orm Stonehoof skänker dig hjälmen som ett högtidligt erkännande av din utveckling som krigare, inte av något desperat behov eller en plötslig kris. Genom att samla sällsynta material från hela Kalimdor och visa din styrka i krigarprövningarna har du bevisat att du är redo att axla ansvaret som vilar på erfarna mästare. Orm hedrar din uthållighet och åkallar Jordmoderns välsignelse, så att rustningen kan skydda dig i de ännu större strider som väntar.",al={"varför ger orm dig hjälmen","orm stonehoofs motiv med brutal helm","varför brutal helm"}}},fp="11,259,16.365.0,27.411.0,27.130.0,53.168.0,31.105.0,46.254.0,37.127.0,49.188.0"}
P.entries["quest:1846"] = {n="Dragonmaw Shinbones",s="Dragonmaw Shinbones är ett uppdrag för Hordens krigare, som rustmästaren Velora Nitely ger i Undercity. För att tillverka de tåliga Brutal Legguards skickas krigarna till södra Wetlands för att samla ovanligt tjocka skenben från de fientliga Dragonmaw-orcherna.",h="Dragonmaw Shinbones är ett uppdrag för Hordens krigare, som rustmästaren Velora Nitely ger i Undercity.",kw={"angerfang encampment","brutal legguards","dragonmaw","skenben","thandol span","undercity","velora nitely","wetlands"},ang={["class:Warrior"]="Prövningen testar både krigarens fysiska uthållighet ute i fält och viljan att samla makabra material för att tillverka bättre rustning.",["faction:Horde"]="Genom att slå ner den förrädiska Dragonmaw-klanen i Khaz Modan försvagar man en farlig rest av den gamla Horden och stärker samtidigt Thralls nya allians.",["race:Orc"]="För orcher som är lojala mot Orgrimmar är jakten på de obotfärdiga Dragonmaw en tydlig påminnelse om folkets demoniska förflutna och det våldsamma priset för försoning.",["race:Undead"]="Velora Nitelys pragmatiska användning av humanoida kvarlevor visar Forsakens inställning: varje tillgänglig resurs kan bli ett vapen, hur makaber den än är."},sec={{t="En makaber stomme",b="Att smida rustning åt en erfaren frontkrigare kräver okonventionella material. När rustmästaren Velora Nitely, en Forsaken, får i uppdrag att tillverka Brutal Legguards anger hon att de behöver ett stabilt stöd av tjockt, tåligt ben. I stället för vanliga djur skickar hon blivande krigare efter Dragonmaw-orcherna i Wetlands. Deras kraftiga skelett ger det motstånd som krävs för att stå emot hårda slag i strid."},{t="Marvtestet",b="Att samla ben från Dragonmaw är bara halva prövningen. Velora instruerar krigarna att testa varje ben från fältet för hand. Ben som är så spröda att de går av i bara händer är helt värdelösa vid smidet. Krigarna måste genomsöka de upproriska lägren längs klipporna i Wetlands och knäcka de svaga benen tills åtta verkligt hållbara exemplar klarar styrkeprovet."}},faq={{q="Varför behöver Velora Nitely just orkernas skenben?",a="Velora behöver ett tätt och tjockt material som stödjande stomme i Brutal Legguards. Hon anser att Dragonmaw-orcherna i Wetlands passar särskilt bra, eftersom deras kraftiga skelett ger mycket större stadga än vanliga villebråd eller rester från asätare.",al={"varför orkers skenben","varför dragonmaw-ben","veloras benrustning"}},{q="Varför får Hordens krigare ge sig på Dragonmaw-orcherna?",a="Resterna av klanen Dragonmaw har slagit sig ner i Wetlands och är fientliga rebeller som håller fast vid Andra krigets mörka arv. De är inte lojala mot Thralls moderna Horde och räknas därför som fiender till staten och lovligt byte för Hordens äventyrare.",al={"tillhör dragonmaw horden","varför bekämpa dragonmaw","dragonmaws relation till horden"}},{q="Var finns Dragonmaw för det här uppdraget?",a="De håller till i Wetlands, söder om Arathi Highlands på andra sidan Thandol Span. Krigare jagar dem oftast kring de bergiga klipporna vid Angerfang Encampment, sydväst om den norra huvudvägen.",al={"dragonmaws plats","var hittar man dragonmaws skenben","var ligger angerfang encampment"}},{q="Varför går så många ben sönder under uppdraget?",a="Velora behöver bara de tätaste benstommarna för att smida rustning. Enligt hennes instruktioner testar krigarna varje ben för hand. Ben som går av under rå fysisk kraft kastas bort, eftersom de är för bräckliga för att skydda en krigares ben i strid.",al={"brutna skenben","varför går skenben av","test av hållbara ben"}},{q="Vem är Velora Nitely?",a="Velora Nitely är en Forsaken-rustmästare i Undercity. Hon är barsk och makabert torr i tonen, och försöker sig gärna på svart humor. Hon hjälper Hordens krigare att tillverka specialutrustning för stridsvana veteraner.",al={"velora nitelys bakgrund","vem är velora","rustmästare i undercity"}},{q="Vilken rustningsdel smids av de här benen?",a="Benen som samlas in utgör den inre stommen i Brutal Legguards, ett slitstarkt par ringbensskydd för Hordens krigare på mellannivå.",al={"belöning för skenben","vad används skenbenen till","tillverka brutal legguards"}}},fx={["0579d748"]={q="Varför vill Velora Nitely att det här ska göras?",a="Velora Nitely behöver skenben från Dragonmaw-orcher i Wetlands för att tillverka dina Brutal Legguards. Deras kraftiga ben ger material till rustningen hon har gått med på att smida.",al={"velora nitelys motiv","varför vill velora ha skenben","varför velora nitely"}}},fp="19,213,19.256.0,18.264.0,55.172.0,56.195.0,44.198.0,51.185.0,21.178.0,44.95.0"}
P.entries["quest:1848"] = {n="Brutal Hauberk",s="I The Barrens ställs Hordens krigare inför ett prov innan Thun'grim Firegaze smider deras ringbrynja. De samlar sällsynta material och bevisar sitt värde mot farliga fiender runt om i landet, och för sedan bytet till den tillbakadragne smeden. Han hamrar ihop det till rustning byggd för strid.",h="I The Barrens ställs Hordens krigare inför ett prov innan Thun'grim Firegaze smider deras ringbrynja.",kw={"brutal armor","brutal hauberk","the crossroads","orkiskt smide","the barrens","thun'grim firegaze","krigarens ringbrynja"},ang={["class:Warrior"]="Som ung krigare i Horden förtjänar du Brutal Hauberk när du går från oerfaren rekryt till härdad stridskämpe klädd i specialsmidd ringbrynja.",["faction:Horde"]="Som medlem av Horden kan du se dess dygder av självständighet och styrka i strid återspeglas i en brynja gjord av troféer från Kalimdors vildmarker.",["profession:Blacksmithing"]="Som smed kan du lära dig av Thun'grims traditionella orksmide, där stridsanda och motståndskraft hamras in i stålet."},sec={{t="En smeds mästerverk",b="I norra The Barrens smider Thun'grim Firegaze rustning enbart åt krigare som uppfyller hans krav. Den tillbakadragne orchen skickar dem vida omkring för att samla tåliga bestdelar, sällsynt metall och alkemiska reagenser innan han tänder ässjan. Den färdiga brynjan skyddar och vittnar om bärarens uthållighet och styrka, vilket ger erkännande från veteraner i hela Horden."},{t="Smidd i motgång",b="Thun'grim gör sina krav plågsamma med avsikt. Hordens vapen och rustningar förväntas bära spår av bärarens svett och blod från första stund. När du överlämnar den färdiga Brutal Hauberk ger smeden inget beröm. Han förväntar sig att du bevisar rustningens värde i brutal strid och återvänder med berättelser om blod och ära."}},faq={{q="Vad är Brutal Hauberk?",a="Brutal Hauberk är en stadig bröstplåt smidd av orksmeden Thun'grim Firegaze. Hordens krigare förtjänar den genom att bevisa sin stridsförmåga och samla sällsynta material i flera farliga trakter.",al={"vad är brutal hauberk","uppdraget brutal hauberk","vem tillverkar brutal hauberk"}},{q="Vem är Thun'grim Firegaze?",a="Thun'grim Firegaze är en tillbakadragen veteransmed som bor på en bergsrygg i norra The Barrens, strax öster om vägen mellan The Crossroads och Orgrimmar. Han prövar unga krigare och smider särskild rustning åt dem när de visat sitt värde.",al={"vem är thun grim","thungrim firegaze","var finns thungrim"}},{q="Varför kräver Thun'grim så mycket arbete innan han smider rustningen?",a="Hordens krigartradition värdesätter umbäranden lika högt som stridskonst. Thun'grim anser att fin ringbrynja tillhör dem som har blött och arbetat för att samla de sällsynta beståndsdelar som krävs för att smida den.",al={"varför samla så många material","krav för brutal armor","thungrims prövningar"}},{q="Vart leder den här uppdragskedjan härnäst?",a="När Thun'grim överlämnar den färdiga brynjan är hans arbete för dig klart. Du kan bära rustningen i strid i Kalimdor och Eastern Kingdoms.",al={"vad händer efter brutal hauberk","nästa uppdrag efter brutal hauberk","finns det en fortsättning"}},{q="Är uppdraget Brutal Hauberk tillgängligt för alliansen?",a="Nej. Brutal Hauberk är ett prov för Horden. Alliansens krigare genomgår en separat stridsrit hos smederna i Ironforge och de omgivande dvärgtrakterna för att smida sin egen signaturrustning.",al={"kan alliansen få brutal hauberk","motsvarighet för alliansen","är det här bara för horden"}},{q="Var i The Barrens kan man hitta Thun'grim?",a="Thun'grim bor på en hög bergsrygg i norra The Barrens, strax söder om Thorn Hill och öster om The Crossroads.",al={"thungrims plats","var finns thungrim i the barrens","hur hittar man thun grim"}}},fx={a5674fab={q="Varför smider Thun'grim Firegaze den här rustningen åt dig?",a="Thun'grim Firegaze smider inte sin Brutal-rustning åt vem som helst. Som en ärad mästersmed som prövar lovande krigare från Horde kräver han bevis på uthållighet, styrka och rå beslutsamhet innan han svingar hammaren. Genom att samla de nödvändiga materialen och trotsa faror åt honom har du visat att du förtjänar att bära hans yppersta hantverk i strid.",al={"varför jag ska få brutal hauberk","varför tillverkar thun'grim rustningen","varför ge brutal hauberk"}}},fp="14,276,21.391.0,18.329.0,27.207.0,26.253.0,68.202.0,38.162.0,54.195.0,44.109.0"}
P.entries["quest:185"] = {n="Tiger Mastery",s="Vid den norra safarilägret i Stranglethorn Vale erbjuder jägaren Ajeck Rouack äventyrare träning i konsten att spåra stora kattdjur. Hon låter nykomlingar börja med de yngre tigrarna som stryker omkring nära lägret, för att pröva deras grundläggande jakt- och spårningsförmåga.",h="Vid den norra safarilägret i Stranglethorn Vale erbjuder jägaren Ajeck Rouack äventyrare träning i konsten...",kw={"ajeck rouack","jakt","nesingwary","stranglethorn vale","tigerträning","ung stranglethorn-tiger"},sec={{t="Första lektionerna i djungeln",b="Ajeck Rouack lärde sig konsten att jaga tigrar av sin far som flicka och delar nu hans kunskap med resenärer som når Nesingwary's Expedition efter Welcome to the Jungle. Hon insisterar på att spåra upp och döda de yngsta kattdjuren är den nödvändiga grunden innan en jägare kan gå vidare till större villebråd."},{t="Jakt på strykarna",b="Unga Stranglethorn-tigrar finns ofta i djungeln nära expeditionens läger. Rouack kräver att tio av dessa bestar jagas för att bevisa tillräcklig skicklighet innan hon går med på att ge ytterligare träning."}},faq={{q="Vem erbjuder dig träning i tigerjakt?",a="Ajeck Rouack, en erfaren jägare stationerad vid Nesingwary's Expedition i norra Stranglethorn Vale, erbjuder träningen.",al={"vem ger tigerträning","ajeck rouack uppdrag","uppdragsgivare för tigerjakt"}},{q="Varför riktar Ajeck Rouack in sig på unga tigrar först?",a="Rouack anser att de yngre kattdjuren är mycket lättare att spåra och döda. Därför är de ett lämpligt första prov på en jägares spårningsförmåga innan jägaren ger sig på farligare villebråd.",al={"varför unga tigrar","varför börja med lätta tigrar"}},{q="Var finns de unga tigrarna?",a="Unga Stranglethorn-tigrar kan ofta hittas när de smyger omkring i djungeln alldeles intill expeditionens läger.",al={"var finns unga stranglethorn-tigrar","plats för unga tigrar"}},{q="Vad kommer före den här jakten?",a="Den här jaktprövningen följer på ankomstuppdraget Welcome to the Jungle, som introducerar resenärer till safarilägret.",al={"förutsättning för tigerträning","föregående uppdrag till tigerträning"}}},fp="13,256,27.325.0,20.218.0,41.121.0,48.177.0,33.110.0,28.114.0"}
P.entries["quest:1858"] = {n="The Shattered Hand",s="I Orgrimmar sätter Therzok skickligheten hos skurkar som vill ansluta sig till Shattered Hand på prov. Han ber dem öppna Tazans återfunna väska med en nyckel som tagits från en ovetande medhjälpare.",h="I Orgrimmar sätter Therzok skickligheten hos skurkar som vill ansluta sig till Shattered Hand på prov.",kw={"cleft of shadow","gamon","orgrimmar","ficktjuva","skurk","shattered hand","tazan","therzok"},ang={["class:Rogue"]="Som skurk lär du dig att smyga dig på ett ouppmärksamt mål bland folk, ta en nyckel obemärkt och säkra viktig information.",["faction:Horde"]="Under den krigiska äran i Thralls nya Horde behövs fortfarande hemlig spaning. Shattered Hand sköter den i det tysta, djupt inne i Orgrimmar."},sec={{t="Ett prov i list",b="När du har hämtat Tazans låsta väska upptäcker du att den är värdelös utan nyckeln. Shattered Hand kräver skicklighet, inte råstyrka mot det komplicerade låset. Therzok skickar dig till Gamon, en berusad tauren som ofta besöker Orgrimmars värdshus. Gamon är lätt att distrahera och hjälpte en gång Tazan, vilket gör honom till ett lämpligt mål för en diskret stöld."},{t="Välkommen till skuggorna",b="Ta nyckeln från Gamon utan att väcka uppmärksamhet på värdshuset, öppna sedan väskan och ta Tazans loggbok. Ta det stulna innehållet till Therzok i Cleft of Shadow för att visa att du lever upp till Shattered Hands krav. Ett rent utfört jobb ger dig officiellt erkännande som en av dess agenter."}},faq={{q="Vem är Gamon och varför har han nyckeln?",a="Gamon hjälpte en gång Tazan, agenten som Therzok undersöker. Medan Tazan bar väskan lämnade han dess nyckel hos Gamon, en ovetande suput som tillbringar dagarna med att dricka på Orgrimmars centrala värdshus.",al={"varför gamon","vem har nyckeln","gamon och nyckeln"}},{q="Vad finns i Tazan's Satchel?",a="Tazans loggbok ligger i den låsta väskan. Den innehåller information av intresse för Therzok och Shattered Hand, och att återta den sätter din förmåga att säkra viktig information i hemlighet på prov.",al={"tazan's logbook","väskans innehåll","vad finns i väskan"}},{q="Vad är Shattered Hand i Orgrimmar?",a="Shattered Hand började som en ökänd orcisk klan från Draenor, känd för självstympning och hänsynslöshet. I Orgrimmar har den blivit Hordens gille för lönnmördare, spioner och skurkar, med verksamhet i den underjordiska Cleft of Shadow.",al={"vad är shattered hand","skurkar i shattered hand","skurkar i orgrimmar"}},{q="Var verkar Therzok?",a="Therzok håller till i Cleft of Shadow, ett dunkelt nätverk av grottor under Orgrimmars klippiga åsar. Trollkarlar, skurkar och skuggkonst samlas där, långt från dagsljuset.",al={"var är therzok","therzoks plats","skurk tränare cleft of shadow"}},{q="Varför bryter Therzok inte bara upp väskan?",a="Väskan har ett komplicerat lås, och Therzok prövar en skurks disciplin. Shattered Hand värdesätter precisa stölder och finess framför högljudd förstörelse.",al={"varför ficktjuva","varför behövs nyckeln"}},{q="Vad händer efter det här uppdraget?",a="När du lämnar över Tazans loggbok är din invigning fullbordad. Therzok erkänner dig som medlem i Shattered Hand och ger dig verktyg för hemliga uppdrag.",al={"belöning från shattered hand","slutet på kedjan"}}},fx={["74a53139"]={q="Varför vill Therzok att Tazan's Satchel ska öppnas?",a="Therzok och The Shattered Hand verkar i Orgrimmars skuggor och hanterar hemligheter och dold säkerhet för Horde. Tazan hade information som var avgörande för deras verksamhet, men det känsliga innehållet låg inlåst i en komplicerad väska. Therzok vill åt informationen utan att förstöra den. Uppdraget blir ett praktiskt prov på om du har den list, smygförmåga och skicklighet som krävs för att formellt tas upp i deras gille.",al={"therzoks motiv","varför öppna väskan","vad vill therzok"}},a30dee79={q="Vad är Tazan's Logbook?",a="Tazan's Logbook innehåller Tazans skriftliga anteckningar och hemliga affärer. Hans verksamhet väckte The Shattered Hands uppmärksamhet. Loggboken ligger skyddad i hans låsta väska och innehåller den viktiga information Therzok behöver. Om du levererar den oskadd bevisar du inte bara att du kan vittja fickor och dyrka upp knepiga lås. Du förmedlar också värdefull information direkt till Orgrimmars spionmästare.",al={"tazans loggbok","vad finns i loggboken","tazans loggbok och dess historia"}},["1b7f194d"]={q="Varför skickar Therzok inte Orgrimmars vakter efter Gamon?",a="The Shattered Hand bygger på diskretion och hemlighetsmakeri, långt från stadsvaktens öppna och hedervärda metoder. Om Orgrimmars soldater grep en berusad gäst på värdshuset som Gamon skulle det bli en oönskad offentlig scen och varna eventuella medbrottslingar som Tazan kan ha haft. När Therzok låter en blivande skurk utföra stölden hålls operationen tyst, samtidigt som din finess prövas i det fördolda.",al={"varför jag","varför skicka en rogue","varför inte stadsvakterna"}}},fp="18,167,18.326.0,22.268.0,42.212.0,31.191.0,40.235.0,27.162.0,48.152.0,30.149.1"}
P.entries["quest:1859"] = {n="Therzok",s="I Orgrimmar väntar Therzok på en lovande skurk från Durotar. Kaplak har sett din skicklighet med våld och smygande och skickar dig till Cleft of Shadow för att träffa en agent från Shattered Hand.",h="I Orgrimmar väntar Therzok på en lovande skurk från Durotar.",kw={"lönnmördare","cleft of shadow","durotar","kaplak","orgrimmar","rogue","shattered hand","therzok"},ang={["class:Rogue"]="Som skurk blir du genom den här kallelsen en del av Shattered Hand, och ditt ensamma arbete i Durotar knyts till Hordens organiserade spionnätverk.",["faction:Horde"]="Som medlem av Horden vet du att Thrall predikar heder och krigaranda. Therzoks nätverk visar att Horden också förlitar sig på osedda klingor och hemliga underrättelseinhämtare."},sec={{t="En viskad kallelse",b="Kaplak tar lovande unga skurkar åt sidan när de börjar göra sig ett namn i Durotar. Den nya Horden hedrar Thrall, men alla dess tjänare strider inte öppet under hans fana. Ryktet om en kämpe som är skicklig på våld och smygande och villig att tänja på reglerna för öppen krigföring når det underjordiska gillet i Orgrimmar."},{t="In i Cleft of Shadow",b="Kaplak skickar dig under Orgrimmars röda klippor till Cleft of Shadow. Therzok väntar i dess mörker, utom synhåll för stadens grunts. Där värvas ensamma ficktjuvar och bakhållsmän till Shattered Hand, Hordens dolda nätverk av dolkar i mörkret."}},faq={{q="Vem är Therzok?",a="Therzok är en agent från Shattered Hand i Orgrimmars Cleft of Shadow. Han möter lovande unga skurkar från Durotars träningsplatser och värvar dem till gillets tjänst.",al={"vem är therzok","therzoks bakgrund","npc therzok"}},{q="Varför skickar Kaplak mig till honom?",a="Kaplak ser din skicklighet i strid och din fallenhet för smygande och list. Han vet att Shattered Hand söker dugliga skurkar, så han vidarebefordrar Therzoks begäran om att värva dig.",al={"varför skickas jag till therzok","kaplaks uppdrag","varför åka till orgrimmar"}},{q="Vad är Shattered Hand i Orgrimmar?",a="I Orgrimmar är Shattered Hand ett hemligt gille av lönnmördare, spioner och tjuvar som tjänar Horden. De tar hand om nödvändigt, moraliskt svårt arbete som Thralls hedervärda krigare inte kan utföra öppet.",al={"vad är shattered hand","shattered hand i orgrimmar","hordes roguegille"}},{q="Var ligger Cleft of Shadow?",a="The Cleft är en grotta under centrala Orgrimmar. Mörka gångar leder dit från Valley of Strength och Drag, och där kan stadens häxmästare och skurkar hålla sig undan allmänhetens blickar.",al={"var ligger cleft of shadow","hur hittar jag therzok","cleft of shadows plats"}},{q="Vad händer efter mötet med Therzok?",a="När du hälsar på Therzok berättar han om uppgifterna inom Shattered Hand och ger dig ett uppdrag som prövar din förmåga, ditt smygande och din lojalitet mot nätverket.",al={"nästa uppdrag","vad vill therzok","efter therzok"}},{q="Får andra än rogues det här uppdraget?",a="Nej. Bara skurkar får den här kallelsen när de nått en viss erfarenhetsnivå. Den markerar steget från lokala skärmytslingar till Hordens underrättelsenätverk.",al={"kan andra klasser göra detta","är detta bara för rogues","rogue-uppdrag"}}},fx={["89f659b0"]={q="Varför väljer Kaplak dig till det här mötet?",a="Kaplak fick uttryckliga order om att leta efter personer som matchar din beskrivning. Gillet har hört att du kan försvara dig i strid och inte tvekar att använda smygande, bedrägeri eller mindre hederliga metoder när det behövs. Therzok har ett uppdrag i åtanke som kräver någon med dina mångsidiga talanger.",al={"varför jag, kaplak","varför skicka mig till therzok","varför valde kaplak mig"}}},fp="7,189,19.323.0,24.264.0,15.184.0,31.177.0,40.204.0,37.199.0,33.154.0,33.162.0"}
P.entries["quest:186"] = {n="Tiger Mastery",s="Vid Nesingwary's Expedition i norra Stranglethorn Vale skärper Ajeck Rouack sina jaktprov. Efter att ha sett din talang för unga rovdjur skickar han dig nu in i djungeln för att fälla fullvuxna Stranglethorn Tigers.",h="Vid Nesingwary's Expedition i norra Stranglethorn Vale skärper Ajeck Rouack sina jaktprov.",kw={"ajeck rouack","nesingwary's expedition","stranglethorn-tigrar","stranglethorn vale","tiger mastery"},sec={{t="Jakten på fullvuxna tigrar",b="Efter din första framgång mot yngre rovdjur vill Ajeck Rouack pröva dina växande färdigheter mot mer erfarna bestar. Hon skickar dig tillbaka ut i Stranglethorn Vales vildmark för att jaga tio fullvuxna Stranglethorn Tigers innan du kan ta dig an ännu större utmaningar."}},faq={{q="Vem ger dig jakten?",a="Ajeck Rouack, en jägare vid Nesingwary's Expedition i norra Stranglethorn Vale, ger dig provet.",al={"vem ger tiger mastery","ajeck rouacks plats","vem ger det här uppdraget"}},{q="Vilka bestar ska du jaga?",a="Du får i uppdrag att spåra upp och döda tio fullvuxna Stranglethorn Tigers som strövar omkring i den omgivande djungeln.",al={"vilka tigrar ska jag döda","vilka kattdjur","mål för tiger mastery"}},{q="Var passar det här provet in i jakten?",a="Det här provet följer på den första Tiger Mastery-jakten och leder direkt vidare till ett tredje steg under Ajeck Rouacks ledning.",al={"vad kommer före tiger mastery 2","vad händer härnäst","tiger mastery-uppdragskedja"}}},fp="13,223,23.288.0,22.109.0,40.100.0,38.118.0"}
P.entries["quest:1860"] = {n="Speak with Jennea",s="I Goldshire skickar Zaldimar Wefhellt novismagiker till Stormwind för vidare undervisning. Han hänvisar lärlingar som kommit längre än grundutbildningen i Elwynn Forest till Jennea Cannon i Wizard's Sanctum.",h="I Goldshire skickar Zaldimar Wefhellt novismagiker till Stormwind för vidare undervisning.",kw={"elwynn forest","goldshire","jennea cannon","mage quarter","tala med jennea","stormwind","wizard's sanctum","zaldimar wefhellt"},ang={["class:Mage"]="Som magiker lämnar du landsbygdens besvärjelser i Goldshire bakom dig för att arbeta formellt med höga magiker vid Stormwinds Wizard's Sanctum.",["faction:Alliance"]="Som medlem i Alliansen förlitar du dig på magisk vaksamhet från huvudstaden för att skydda Elwynn Forest och Stormwind."},sec={{t="En kallelse till Wizard's Sanctum",b="Zaldimar Wefhellt skickar dig från Goldshire till Stormwind City när din utbildning går vidare. Din tid med att lära dig grundläggande besvärjelser av lokala lärare i Elwynns byar är över. I Mage Quarter ligger Wizard's Sanctum, där rikets främsta magiker ägnar sig åt magiska studier och undervisning. De samordnar magiska angelägenheter i hela riket."},{t="Frågor om rikets säkerhet",b="Zaldimar säger att din rapport gäller säkerheten i Elwynn Forest och Stormwind, inte bara dina studier. I Stormwind rapporterar du till Jennea Cannon, en magiker som leder lokala uppdrag. Hon är försiktig med att dela stora hemligheter med en nyanländ lärling, men din rapport inleder din tjänstgöring i magikerorden."}},faq={{q="Vem skickar mig på det här uppdraget?",a="Zaldimar Wefhellt, magiläraren på Lion's Pride Inn i Goldshire, skickar dig när dina magiska färdigheter har utvecklats tillräckligt.",al={"uppdragsgivare","vem ger uppdrag","zaldimar"}},{q="Var hittar jag Jennea Cannon?",a="Jennea Cannon finns i Wizard's Sanctum, mitt i Stormwind Citys Mage Quarter.",al={"jennea cannon plats","var är jennea","hitta jennea"}},{q="Vad är Wizard's Sanctum?",a="Wizard's Sanctum är ett framstående magiskt torn i Stormwinds Mage Quarter. Rikets magiker och magiska lärda använder det som akademi, bibliotek och bas för sin verksamhet.",al={"vad är wizard's sanctum","magikertorn stormwind"}},{q="Varför skickar Zaldimar mig till Jennea i stället för att sköta det själv?",a="Zaldimar lär unga magiker grunderna i Goldshire. Högt uppsatta lärda som Jennea Cannon hanterar större regionala hot och specialuppdrag som påverkar riket från huvudstaden.",al={"varför åka till stormwind","varför jennea"}},{q="Vad händer när jag har rapporterat till Jennea Cannon?",a="Jennea skickar dig för att undersöka mystiska magiska avvikelser kring Mirror Lake i Elwynn Forest.",al={"vad händer sedan","fortsättningsuppdrag","nästa steg"}},{q="Är det här uppdraget tillgängligt för alla klasser?",a="Nej. Bara magiker får genomgå denna övergång från byträning till Stormwinds magiska samhälle.",al={"kan andra än magiker göra detta","endast magiker","klasskrav"}}},fx={["8f9ffa7f"]={q="Varför vill Zaldimar Wefhellt att du ska tala med Jennea?",a="Zaldimar Wefhellt handlar av omsorg om säkerheten i både Stormwind City och Elwynn Forest. Ett brådskande ärende kräver skickliga magikers uppmärksamhet. I stället för att hantera det själv hänvisar han lovande lärlingar till Jennea Cannon i Wizard's Sanctum, där hon ansvarar för detaljerna i det känsliga uppdraget.",al={"zaldimars motiv","varför träffa jennea","varför skicka mig till jennea"}}},fp="17,210,30.347.0,27.321.0,27.129.0,31.89.0,29.173.0,67.196.0,46.97.1,37.98.0"}
P.entries["quest:1861"] = {n="Mirror Lake",s="Nybörjarmagiker i Alliansen i Stormwinds Mage Quarter får i uppdrag att ta prover från Mirror Lakes vatten och undersöka om det är magiskt förorenat. Jennea Cannon skickar dem sydväst om stadsportarna för att testa vattenfallets stänk.",h="Nybörjarmagiker i Alliansen i Stormwinds Mage Quarter får i uppdrag att ta prover från Mirror Lakes vatten...",kw={"mystisk förorening","elwynn forest","jennea cannon","leylinjer","mirror lake","vattenprov","wizard's sanctum"},ang={["class:Mage"]="Som magiker går du från studier i Wizard's Sanctum till att undersöka mystiska fenomen ute i världen. Arbetet ger dig din första särskilda magikerstav eller klot för den fria handen.",["faction:Alliance"]="Som medlem av Alliansen kan du hjälpa magikerna i Wizard's Sanctum att skydda Elwynns naturresurser och kungarikets hjärta.",["race:Human"]="Som människa vet du att Mirror Lake försörjer Elwynns jordbruk och vattendrag, så vattnets renhet är viktig för Stormwinds invånare."},sec={{t="Leylinjer och skiftande strömmar",b="Azeroths mystiska strömmar skakades av konflikter från Dark Portals öppnande till Tredje kriget och slaget vid Mount Hyjal. Chockerna slet loss gamla strömmar från deras stabila banor. I Stormwinds Wizard's Sanctum håller magiker som Jennea Cannon noga uppsikt över förändringarna. De fruktar att rubbad mystisk kraft kan nå vildmarken och förgifta de lokala ekosystemen."},{t="Att testa vattnet",b="Mirror Lake ligger nedanför klipporna sydväst om Stormwinds portar och är en viktig naturlig vattenreservoar som får sitt vatten från bergsvattenfall. Landsbygden runt sjön är beroende av dess vatten. Jennea skickar nybörjarmagiker med en glasflaska till vattenfallets fot, där de samlar upp färskt stänk. Sedan kan The Sanctum använda skådning och reagenstester för att ta reda på om vild magi sipprar in i den allmänna vattenförsörjningen."}},faq={{q="Varför vill Jennea Cannon ha ett vattenprov från Mirror Lake?",a="Konflikter över hela Azeroth har slitit sönder naturliga leylinjer. Jennea Cannon fruktar att oroliga mystiska krafter når grundvattnet runt Stormwind och kan skada alla som dricker från sjön.",al={"varför vatten från mirror lake","jenneas vattenprov","vad går uppdraget ut på"}},{q="Var ligger Mirror Lake egentligen?",a="Mirror Lake ligger i nordvästra Elwynn Forest, intill de höga klipporna sydväst om Stormwinds huvudportar. Provet tas från dammen vid vattenfallets fot.",al={"var ligger mirror lake","mirror lakes plats","hitta mirror lake"}},{q="Vad händer om vattnet är förorenat?",a="Jennea fruktar att den som dricker magiskt förorenat vatten under lång tid kan ta skada. De exakta effekterna är okända.",al={"är vattnet förgiftat","vad händer om vatten har magi","effekter av magisk förorening"}},{q="Vem kan utföra det här uppdraget?",a="Nybörjarmagiker i Alliansen under utbildning utför det här uppdraget som en av sina första fältstudier för Wizard's Sanctum.",al={"vem får uppdraget vid mirror lake","är mirror lake bara för magiker"}},{q="Leder det här uppdraget till fler undersökningar?",a="Den första direkta uppgiften som inleds med Jennea Cannons kallelse slutar här. Den ger lärlingen sitt första officiella magikerredskap och fastställer dennes plikt att hålla utkik efter magiska störningar i riket.",al={"vad händer efter mirror lake","uppdragskedjan för mirror lake"}},{q="Vad fick de magiska strömmarna att bli instabila från början?",a="Jennea spårar de förändrade strömmarna till världens stora mystiska strider, men nämner inget särskilt slag eller någon specifik händelse.",al={"varför är leylinjerna skadade","vad betyder mystiska strider","vad bröt magin"}}},fx={["66ca747e"]={q="Vad används Mirror Lake Water Sample till?",a="Jennea Cannon behöver provet för att undersöka om vattnet i Mirror Lake är magiskt förorenat. Väldiga mystiska omvälvningar över hela Azeroth har slitit de magiska strömmarna ur sina vanliga banor, och magikerna i Mage Quarter oroar sig för att dessa instabila energier sipprar direkt ut i den lokala vattenförsörjningen. En undersökning av sjövattnet visar om de som dricker det riskerar magisk förvrängning.",al={"användning av mirror lake water sample","varför hämta vattenprov","vad gör provet"}}},fp="11,198,31.381.0,18.399.0,60.200.0,29.169.0,37.139.0,31.124.0,47.206.0,67.112.0"}
P.entries["quest:187"] = {n="Tiger Mastery",s="Djupt inne i djungeln vid Nesingwary's Expedition höjer Ajeck Rouack insatserna i sina jaktprov. Han kräver att du fäller tio äldre Stranglethorn-tigrar för att bevisa din skicklighet inför det sista provet.",h="Djupt inne i djungeln vid Nesingwary's Expedition höjer Ajeck Rouack insatserna i sina jaktprov.",kw={"ajeck rouack","storviltsjakt","elder stranglethorn tiger","nesingwary","stranglethorn vale","tiger mastery"},sec={{t="Ett skicklighetsprov",b="Efter de tidigare jakterna ber Ajeck Rouack dig att spåra upp tio äldre Stranglethorn-tigrar i vildmarken. Han anser att dessa bestar både är svårast att spåra och farligast att besegra. Att fälla tio av dem blir upptakten till ett avslutande prov, efter vilket han lovar att utropa dig till mästare på tigerjakt inför Master Nesingwary."}},faq={{q="Vem ger dig provet?",a="Ajeck Rouack ger dig provet från lägret tillhörande Nesingwary's Expedition i norra Stranglethorn Vale.",al={"vem ger tiger mastery","ajeck rouack uppdrag","uppdragsgivare"}},{q="Vilket byte spårar du?",a="Du måste jaga rätt på tio äldre Stranglethorn-tigrar.",al={"vad ska jag döda","vilka tigrar","mål för tiger mastery"}},{q="Varför har de äldre Stranglethorn-tigrarna valts ut?",a="Ajeck Rouack påpekar att äldre Stranglethorn-tigrar är de svåraste att hitta och de mest ursinniga att besegra bland traktens kattdjur.",al={"varför äldre tigrar","äldre tigrars svårighetsgrad"}},{q="Vad kommer före den här jakten?",a="Det här provet följer direkt på det andra steget i Ajeck Rouacks serie Tiger Mastery.",al={"föregående uppdrag","förutsättning"}}},fp="13,200,15.349.0,23.103.0,29.50.0,47.129.0,28.84.0"}
P.entries["quest:1878"] = {n="Water Pouch Bounty",s="Spigot Operator Luglunket hälsar dig välkommen tillbaka och hoppas att du har med dig fem till Wastewander water pouches. Ett välkomstpaket väntar.",h="Spigot Operator Luglunket hälsar dig välkommen tillbaka och hoppas att du har med dig fem till Wastewander...",kw={"välkomstpaket","spigot operator luglunket","tanaris","wastewander water pouch","water pouch bounty"},sec={{t="Tillbaka igen",b="Efter Water Pouch Bounty välkomnar Luglunket dig tillbaka och frågar om du har fem till Wastewander water pouches i packningen. I så fall väntar redan ett välkomstpaket med ditt namn på."},{t="Fortsätt komma med dem",b="Luglunket är nöjd med de återtagna påsarna, eftersom var och en för alla längre från katastrofen. Luglunket lovar att belöna dig för varje fem påsar du tar med."}},faq={{q="Vem erbjuder den här belöningen?",a="Luglunket, kranoperatören i Gadgetzan.",al={"vem ger belöning för vattenpåsar","luglunket uppdrag","vem tar emot vattenpåsar"}},{q="Hur många vattenpåsar behövs?",a="Fem Wastewander water pouches, precis som förut.",al={"hur många påsar","antal vattenpåsar","påsar per inlämning"}},{q="Vad har Luglunket gjort i ordning?",a="Ett välkomstpaket som hålls åt dig och har ditt namn på.",al={"vad är välkomstpaketet","vad får jag"}},{q="Vad kommer före det här steget?",a="Det följer på det tidigare Water Pouch Bounty, då du först tog med påsar till Luglunket.",al={"föregående uppdrag","vad gör jag först"}}},fp="18,131,10.189.0,16.182.1,28.44.0,34.51.0,31.37.0,28.91.0"}
P.entries["quest:1879"] = {n="Speak with Bink",s="”Speak with Bink” är en kallelse från Alliansen som skickar novismagiker från Dun Morogh till huvudstaden Ironforge. Magis Sparkmantle utfärdar kallelsen och sänder lovande magiker för att hjälpa Bink, en arkana forskare verksam i Hall of Mysteries.",h="”Speak with Bink” är en kallelse från Alliansen som skickar novismagiker från Dun Morogh till huvudstaden...",kw={"bink","dun morogh","hall of mysteries","ironforge","magiker","magis sparkmantle","mystic ward"},ang={["class:Mage"]="Den här kallelsen markerar din övergång från dalens grundläggande träning till de större angelägenheterna bland Ironforges akademiska arkanister.",["faction:Alliance"]="De gemensamma studierna i Hall of Mysteries visar hur nära gnomisk lärdom och dvärgisk gästfrihet förenas under Alliansens baner.",["race:Gnome"]="Bink och Magis Sparkmantle för vidare den gnomiska arkantraditionen i Ironforges gästfria salar efter förlusten av Gnomeregan."},sec={{t="En kollegas kallelse",b="Novismagiker som tränar bland Dun Moroghs kalla klippor fångar till slut Magis Sparkmantles uppmärksamhet. När en lärling har vuxit ifrån de grundläggande övningarna runt Kharanos förmedlar Sparkmantle en hälsning från sin kollega Bink. Begäran är tydlig och kompromisslös: Bink behöver en arkanspecialist och vägrar anförtro uppgiften åt någon som inte kan bruka magi."},{t="Hall of Mysteries",b="Uppdraget för unga magiker till Ironforges Mystic Ward, där lärda, präster och arkanister samlas under Hall of Mysteries höga valv av sten. Här utför Bink sina studier och granskar anländande lärlingar med skarp blick. Enligt henne är rå potential bara början; en odisciplinerad magiker blir snabbt en fara snarare än en tillgång i arkaniska angelägenheter."}},faq={{q="Vem ger det här uppdraget?",a="Magis Sparkmantle erbjuder uppdraget till novismagiker i Alliansen som har kommit en bit i sin tidiga träning i Dun Morogh.",al={"uppdragsgivare","var börjar man","vem startar speak with bink"}},{q="Var hittar jag Bink?",a="Bink finns i Hall of Mysteries, som ligger i Mystic Ward i den norra delen av Ironforge.",al={"binks plats","var är bink","hitta bink"}},{q="Varför vill Bink bara ha en magiker?",a="Bink bedriver forskning som direkt berör arkan energi och känslig övervakningsutrustning. Hon anser att personer som inte är magiker är olämpliga att hantera de magiska nyanserna och farorna som arbetet innebär.",al={"varför bara magiker","magikerrav","bink vill bara ha magiker"}},{q="Vad händer efter att jag träffat Bink?",a="När Bink har hälsat på dig och bedömt dina förmågor tar hon hjälp av dig i sin forskning, som fortsätter i uppdraget ”Mage-tastic Gizmonitor”.",al={"nästa uppdrag","uppföljning till bink","vad kommer efter speak with bink"}},{q="Är uppdraget tillgängligt för andra klasser än magiker?",a="Nej. Uppdraget är enbart avsett för magiker och leder från den lokala nybörjarträningen till specialiserade uppdrag i huvudstaden.",al={"kan andra klasser göra det här","är det här bara för magiker","specifikt för magiker"}},{q="Vad är Hall of Mysteries?",a="Hall of Mysteries är Ironforges centrum för arkan och helig forskning. Där finns tränare, lärda och forskare som företräder dvärgarnas och gnomernas magiska konster.",al={"ironforge hall of mysteries","vad är hall of mysteries"}}},fx={["96ce9827"]={q="Varför skickar Magis Sparkmantle dig till Bink?",a="Magis Sparkmantle är en gnomisk magitränare i Kharanos och mentor åt blivande besvärjare. Hans kollega Bink i Ironforge har särskilt bett om en skicklig magiker till ett viktigt uppdrag. Magis ser att du behärskar de magiska krafterna allt bättre och skickar dig till dvärgarnas huvudstad för att svara på hennes begäran och fortsätta din magiska träning.",al={"varför skickar magis dig","magis sparkmantles motiv","varför tala med bink"}}},fp="15,157,21.280.0,21.280.0,21.114.0,22.75.0,31.155.0,32.134.0,52.103.0,30.162.0"}
P.entries["quest:188"] = {n="Tiger Mastery",s="Ajeck Rouack erbjuder den ultimata utmaningen i sin serie jakter i norra Stranglethorn Vale. Efter veckor av spårning av ett svårfångat vilddjur utmanar han dig att leta upp tigern Sin'Dall och ta med hennes tass tillbaka.",h="Ajeck Rouack erbjuder den ultimata utmaningen i sin serie jakter i norra Stranglethorn Vale.",kw={"ajeck rouack","mästerlig tigerjägare","nesingwary's expedition","paw of sin'dall","sin'dall","stranglethorn vale","tiger mastery"},sec={{t="Den sista tigern",b="Efter att ha klarat de tidigare prövningarna mot Stranglethorns tigrar får du en sista utmaning av Ajeck Rouack vid Nesingwary's Expedition. Jaktlägret har spårat en ovanligt svårfångad tiger vid namn Sin'Dall genom djungeln i flera veckor. Ajeck utmanar dig att spåra upp henne, fälla besten och ta hennes tass som obestridligt bevis."},{t="Mästerlig tigerjägare",b="När du återvänder till Nesingwary's läger med Sin'Dalls tass bevisar du bortom allt tvivel din skicklighet som spårare. Ajeck Rouack erkänner din bedrift och förklarar dig vara en sann mästerlig tigerjägare."}},faq={{q="Vem erbjuder jakten?",a="Ajeck Rouack, en erfaren jägare stationerad vid Nesingwary's Expedition i norra Stranglethorn Vale, ger dig denna sista utmaning mot en kattdjur.",al={"uppdragsgivare","vem ger tiger mastery","ajeck rouacks plats"}},{q="Vad är Sin'Dall?",a="Sin'Dall är en svårfångad tiger som jägarna vid Nesingwary's Expedition har jagat i flera veckor genom Stranglethorn Vales djungler.",al={"vad är sindall","sindalls historia","vem är sin dall"}},{q="Vilket bevis kräver Ajeck Rouack?",a="Ajeck Rouack kräver att du återvänder med Paw of Sin'Dall som bevis på att besten verkligen har besegrats.",al={"vad ska jag ta med tillbaka","bevis för tiger mastery","paw of sindall"}},{q="Vad föregår den här jakten?",a="Den här jakten är det fjärde och avslutande steget i Ajeck Rouacks serie, efter den tredje Tiger Mastery-prövningen i norra Stranglethorn Vale.",al={"förkunskapskrav","tiger mastery-uppdragskedja","föregående uppdrag"}}},fp="13,216,15.352.0,19.190.1,21.140.0,17.143.0,37.102.0,24.142.0"}
P.entries["quest:1881"] = {n="Speak with Anastasia",s="Speak with Anastasia är en inledande kallelse som leder lovande Forsaken-magiker till Anastasia Hartwell i Undercity. Magikern Cain Firesong skickar den unga magikern till Magic Quarter för att utföra viktigt arbete åt Forsakens magiker. Den korta kallelsen banar väg för undersökningar ute i Tirisfal Glades, ett pesthärjat land.",h="Speak with Anastasia är en inledande kallelse som leder lovande Forsaken-magiker till Anastasia Hartwell i...",kw={"anastasia hartwell","balnir farmstead","cain firesong","magikeruppdrag","magic quarter","undercity"},ang={["class:Mage"]="Det här uppdraget markerar övergången från grundläggande magisk träning till aktiv tjänst för magikerna i Undercity.",["race:Undead"]="För Forsakens magiker innebär Hartwells kallelse en möjlighet att använda Lordaerons intellektuella förflutna mot farorna i nutiden."},sec={{t="En kallelse till Magic Quarter",b="När blivande magiker finslipar sina första talanger under Cain Firesongs ledning i Brill skickas de snart till huvudstaden. Forsakens magiker har ett eget område i Magic Quarter i Undercity, där de organiserar både magiska studier och strategiska försvarsinsatser i Lordaeron. Cain Firesong bedömer eleverna, sållar bort rena nybörjare och skickar dem som visar verklig talang direkt till erfarna magiker som behöver skickliga fältmedarbetare."},{t="Anastasia Hartwells ambition",b="Anastasia Hartwell är en av de framstående magilärarna i Undercity. I stället för att låta lovande elever tryggt studera triviala besvärjelser, skyndar hon sig att sätta dem i arbete för Forsakens territoriella och praktiska intressen. Att svara på hennes kallelse är både ett övergångsprov för magiker och en introduktion till de skuggiga, pragmatiska magiska sysslor som präglar de odöda efter Scourge."}},faq={{q="Vem skickar dig till Anastasia Hartwell?",a="Cain Firesong, en magitränare bland Forsaken, skickar dig till henne efter att ha sett att dina magiska talanger är tillräckligt utvecklade för att hjälpa till med mer krävande uppgifter i huvudstaden.",al={"vem ger speak with anastasia","uppdragsgivare för speak with anastasia","cain firesongs kallelse"}},{q="Var hittar du Anastasia Hartwell?",a="Anastasia Hartwell finns i Magic Quarter i Undercity, där hon samordnar och undervisar Forsakens magiker.",al={"var finns anastasia hartwell","anastasia hartwells plats","hitta anastasia"}},{q="Vad är syftet med den här kallelsen?",a="Anastasia söker en skicklig magiker som kan utföra praktiska uppgifter utanför stadsmurarna, med fältuppdrag i Tirisfal Glades som start, till exempel att undersöka Balnir Farmstead.",al={"varför vill hon ha mig","syftet med speak with anastasia","vad behöver anastasia"}},{q="Vilket uppdrag följer efter Speak with Anastasia?",a="När du rapporterar direkt till Anastasia får du uppdraget 'The Balnir Farmstead'. Du skickas till östra Tirisfal Glades för att samla snapdragons i gårdens trädgård.",al={"vilket uppdrag kommer härnäst","nästa uppdrag efter speak with anastasia","uppföljning till speak with anastasia"}},{q="Är det här uppdraget begränsat till vissa klasser?",a="Ja, uppdraget är särskilt avsett för magiker bland Forsaken och fungerar som ett steg i klassens utveckling när de når grundläggande färdighet omkring nivå tio.",al={"är det här bara ett magikeruppdrag","vem kan göra speak with anastasia","klasskrav"}},{q="Varför har Forsakens magiker egna kvarter i Undercity?",a="Magic Quarter är en egen tillflyktsort för Forsakens magiker, häxmästare och forskare, där de kan studera och kasta besvärjelser på avstånd från de fysiska kvarteren. Där för de vidare traditioner från tiden före Third War i Lordaerons undre värld.",al={"varför magic quarter","forsaken-magiker i undercity"}}},fx={["34129032"]={q="Varför skickar Cain Firesong dig till Anastasia Hartwell?",a="Cain Firesong undervisar nyblivna magiker bland Forsaken i Brill. När du visar tillräcklig skicklighet i magins konst är det hans uppgift att hänvisa lovande besvärjare till Anastasia Hartwell i Magic Quarter i Undercity. Hartwell samordnar större uppdrag åt Forsakens magiska orden, och Cain ser till att dess led fylls på med dugliga utövare som är redo att tjäna.",al={"varför skickar cain dig","cain firesongs motiv","varför besöka anastasia hartwell"}}},fp="20,209,27.370.0,29.355.0,47.157.0,38.123.0,36.171.0,40.134.0,41.129.0,67.206.0"}
P.entries["quest:1882"] = {n="The Balnir Farmstead",s="\"The Balnir Farmstead\" är en tidig övergångsrit för unga Forsaken-magiker, ledd av Anastasia Hartwell i Undercitys Mage Quarter. De skickas till östra Tirisfal Glades för att samla snapdragons från en övergiven gård som ligger farligt nära Plaguelands gräns. Blommorna fungerar som mätare för den magiska förgiftelse som sprider sig från det Scourge-härjade österlandet.",h="\"The Balnir Farmstead\" är en tidig övergångsrit för unga Forsaken-magiker, ledd av Anastasia Hartwell i...",kw={"anastasia","balnir","gård","hartwell","magiker","plaguelands","snapdragons","tirisfal","undercity"},ang={["class:Mage"]="Det här tidiga provet lär novisa magiker att deras studier av det arkaniska är viktiga för att upptäcka och försvara sig mot främmande magisk förgiftelse.",["profession:Herbalism"]="Balnir Snapdragons visar hur växtprover kan fungera som direkta behållare för och indikatorer på magisk förorening.",["race:Undead"]="För Forsaken handlar skyddet av Tirisfal Glades gränser mot Scourge om omedelbar överlevnad och självbestämmande."},sec={{t="En magisk mätare",b="Royal Apothecary Society studerar ofta nekromantins och förfallets effekter, men Forsakens magiker håller också noga uppsikt över gränslandet. Anastasia Hartwell skickar novisa magiker till Balnir Farmstead i östra Tirisfal Glades. Snapdragons som växer naturligt i gårdens trädgårdar är känsliga för skiftningar i magiska strömmar och absorberar energier från marken och luften. Genom att undersöka blommorna kan arkanister i Undercity mäta om den fördärvande smittan från Lich Kings domän har trängt förbi The Bulwark och in i Tirisfal."},{t="Den östra gränsen",b="Balnir Farmstead ligger nära gläntornas utkant, obehagligt nära Western Plaguelands pesthärjade vildmark. Forsaken vet att Lich Kings pest är en vild och destruktiv kraft som aktivt ruttnar själva marken. Även om Forsaken brukar sina egna mörka konster hotar okontrollerad Scourge-förgiftelse deras territorium och säkerhet. Anastasia tänker lämna de insamlade snapdragons till apotekarna, så att arkanisk observation förenas med alkemisk undersökning för att försvara Lordaerons återtagna kärnland."}},faq={{q="Varför vill Anastasia Hartwell särskilt ha snapdragons?",a="Balnir Snapdragons har en särskild naturlig känslighet för magiska krafter i omgivningen. Eftersom de absorberar energier direkt från jord och luft kan Forsaken-magiker undersöka dem för att avgöra om den arkaniska och nekromantiska pesten från närliggande Plaguelands förorenar Tirisfal Glades.",al={"varför snapdragons","balnir snapdragons syfte","vad används snapdragons till"}},{q="Var ligger Balnir Farmstead?",a="Gården ligger i östra Tirisfal Glades, nära gränsen där gläntorna möter Western Plaguelands pesthärjade gränsland. Snapdragons växer i de igenvuxna odlingarna och trädgårdarna kring gårdens förfallna byggnader.",al={"balnir farmstead plats","var ligger balnir farm","hitta balnir farmstead"}},{q="Vem är Anastasia Hartwell?",a="Anastasia Hartwell är en framstående Forsaken-magiker och tränare som bor i Undercitys Mage Quarter. Hon vägleder nyvakna odöda magiker och lär dem disciplin, arkanisk balans och hur de praktiskt försvarar gränserna mot rivaliserande makter.",al={"anastasia hartwell bakgrund","vem är anastasia"}},{q="Varför bryr sig Forsaken-magiker om att stoppa pesten?",a="Forsaken experimenterar visserligen med egna plågor och pesthärdar, men Lich Kings smittsamma Scourge-magi betraktas som en okontrollerad avvikelse. Om den lämnas obekämpad skulle Scourges fördärv uppsluka hela Tirisfal Glades och hota Forsakens självständighet.",al={"varför stoppa pesten","hatar forsaken pesten"}},{q="Vad händer med blommorna efter att du samlat in dem?",a="När Anastasia har tagit emot snapdragons förbereder hon sig på att lämna dem till Undercitys apotekare. Alkemisterna och magikerna dissekerar proverna tillsammans för att bedöma hur djupt Scourge har förgiftat jorden och växtligheten.",al={"vad gör anastasia med blommorna","vem får snapdragons"}},{q="Är det här uppdraget bara för magiker?",a="Ja. Det här är ett klassuppdrag som bara erbjuds unga Forsaken-magiker som har kommit längre än sina första lektioner i Deathknell och anlänt till huvudstaden för att visa att de behärskar arkanisk teori.",al={"är balnir farmstead bara för magiker","magikerns klassuppdrag"}}},fp="20,199,19.395.0,18.454.0,58.214.0,38.186.0,26.203.0,53.231.0,51.176.0,34.176.0"}
P.entries["quest:1885"] = {n="Mennet Carkad",s="Mennet Carkad är ett introduktionsuppdrag för skurkar i Undercity, där lovande agenter förs in i Deathstalkers. På Marion Calls order kallas blivande lönnmördare till att rapportera direkt till Mennet Carkad djupt inne i Rogues' Quarter.",h="Mennet Carkad är ett introduktionsuppdrag för skurkar i Undercity, där lovande agenter förs in i...",kw={"lönnmördare","deathstalkers","forsaken-skurk","marion call","mennet carkad","rogues' quarter","undercity"},ang={["class:Rogue"]="Den här kallelsen markerar din övergång från en oprövad ficktjuv till en erkänd tillgång för Deathstalkers, Forsakens elitnätverk i skuggorna.",["race:Undead"]="Deathstalkers är avgörande för Forsakens överlevnad. De jagar Scarlet Crusades fanatiker och kvarlevor av Scourge, samtidigt som de skyddar Queen Sylvanas från dolda hot."},sec={{t="En kallelse från skuggorna",b="I Undercitys mörka korridorer sprids ordet tyst bland Forsakens hemliga agenter. När en spejare eller lönnmördare fångar ledningens uppmärksamhet utfärdas en inbjudan. Marion Call låter hälsa att Mennet Carkad, en framstående person bland skurkarnas handledare, har lagt märke till dig personligen. Med tanke på Forsakens underrättelseapparats dödliga rykte är det inget rimligt alternativ att ignorera en sådan order."},{t="Gå med i Deathstalkers",b="Mennet Carkad väntar i Rogues' Quarters skuggiga nischer, där han håller uppsikt över rekryter och bedömer om de är redo. De som hörsammar hans kallelse går inte bara med i ett vanligt tjuvgille; de sätts på prov för att få träda in i Deathstalkers, Forsakens fruktade gren för spionage och lönnmord. Snabb lydnad är bara det första grundprovet för den som vill tjäna Dark Lady från skuggorna."}},faq={{q="Vem är Mennet Carkad?",a="Mennet Carkad är en skurkarnas tränare och Deathstalkers-handledare verksam i Rogues' Quarter i Undercity. Han håller uppsikt över lovande hemliga agenter och tilldelar viktiga uppdrag på Forsaken-ledningens vägnar.",al={"mennet carkad bakgrund","vem är carkad"}},{q="Vad händer om någon ignorerar Mennet Carkads kallelse?",a="Marion Call varnar dig för att du inte vill veta vad som hände med dem som ignorerade Carkads kallelse. Hon förklarar inte exakt vad deras öde blev.",al={"ignorera carkad","vad händer om man ignorerar en kallelse"}},{q="Vilka är Deathstalkers?",a="Deathstalkers är den elitstyrka av skurkar, spioner och lönnmördare som tjänar Forsaken. Från Undercitys skuggor röjer de högt prioriterade mål ur vägen, samlar underrättelser och skyddar Lordaeron från fiender som Scarlet Crusade och Scourge.",al={"deathstalkers bakgrund","vad är deathstalkers"}},{q="Var hittar jag Mennet Carkad?",a="Mennet Carkad finns i Rogues' Quarter i Undercity, vanligen omgiven av andra hemliga agenter, tränare och utrustning för skuggkonster.",al={"carkads plats","var finns mennet carkad"}},{q="Vem ger uppdraget att söka upp Mennet Carkad?",a="Uppdraget tilldelas av Marion Call på Gallows' End Tavern i Brill. Hon lägger märke till dina växande färdigheter och varnar dig för att Carkad förväntar sig snabb lydnad.",al={"vem startar det här uppdraget","marion call uppdrag"}},{q="Vad händer efter att jag rapporterat till Mennet Carkad?",a="När du rapporterar till Mennet Carkad börjar du genast tjäna Deathstalkers, med uppgifter som ska bevisa din list och lojalitet mot Forsakens sak.",al={"nästa uppdrag efter carkad","vad vill carkad"}}},fx={f971228d={q="Varför skickar Marion Call dig till Mennet Carkad?",a="Marion Call säger att Mennet Carkad har lagt märke till dig och väntar sig att träffa dig. Hon uppmanar dig att hörsamma hans kallelse och varnar olycksbådande för dem som ignorerade den, utan att förklara vad som hände dem.",al={"varför vill marion call ha det gjort","varför gå till mennet carkad","marion calls motiv"}}},fp="13,166,26.308.0,25.316.0,21.180.0,56.138.0,26.262.0,31.123.0,46.161.0,44.162.0"}
P.entries["quest:1886"] = {n="The Deathstalkers",s="Det här uppdraget är ett prov för aspiranter som vill ansluta sig till Deathstalkers, den hemliga och dödliga styrka som lyder under Lord Varimathras i Undercity. Mennet Carkad i Rogues' Quarter ger dig uppdraget, där du måste agera hänsynslöst och självständigt för att genskjuta en budbärare på resa. Klarar du provet får du tillgång till djupare konspirationer i Forsaken-riket.",h="Det här uppdraget är ett prov för aspiranter som vill ansluta sig till Deathstalkers, den hemliga och dödliga...",kw={"astor hadren","deathstalkers","mennet carkad","rogues' quarter","silverpine","undercity","varimathras"},ang={["class:Rogue"]="För Forsaken-skurkar är det den högsta formen av statstjänst att gå med i Deathstalkers. De blir svurna redskap åt Varimathras och den Mörka Damen.",["faction:Horde"]="Deathstalkers verkar i djupaste hemlighet. De ser till att Forsaken behåller viktiga underrättelsenätverk, samtidigt som Hordens allierade i söder förblir ovetande om mycket av deras skumraskaffärer på hemmaplan.",["race:Undead"]="Deathstalkers står för den järnhårda inre säkerheten i Lordaeron och håller ett vaksamt, misstänksamt öga på både yttre fiender och möjliga förrädare bland Forsaken."},sec={{t="Ett prov i skuggorna",b="Deathstalkers släpper inte in vem som helst i sina led. Den här hemliga orden lyder direkt under dreadlord Varimathras och fungerar både som Forsakens hemliga polis och elitstyrka för lönnmord. För att väcka deras intresse måste en aspirant visa list, diskretion och en obeveklig vilja att röja mål ur vägen. I de skuggiga hörnen av Rogues' Quarter utformar kontaktmannen Mennet Carkad ett inträdesprov som ska sålla bort de svaga och alltför samvetsgranna."},{t="Genskjutandet",b="Aspirantens mål är Astor Hadren, en kurir som färdas mellan Undercity och Silverpine Forest. Carkad ger inga taktiska råd, utan låter agenten själv välja hur Hadren ska förmås att lämna ifrån sig sin introduktionsskrivelse. Uppdraget går ut på att genskjuta Astor, ta hans dokument och se till att Deathstalkers rekryt kan utge sig för att vara det väntade sändebudet hos en agent vid namn Andron."}},faq={{q="Vilka är Deathstalkers?",a="Deathstalkers är Forsakens elitstyrka för smygande och lönnmord. De har sitt högkvarter i Undercitys Rogues' Quarter och ägnar sig åt spionage, hemliga avrättningar och informationsinsamling. De rapporterar direkt till Lord Varimathras.",al={"deathstalkers bakgrund","vad är deathstalkers","odöda skurkar"}},{q="Vem är Mennet Carkad?",a="Mennet Carkad är en kontaktman för Deathstalkers som verkar från Rogues' Quarter i Undercity. Han leder de första proven och prövar rekryter som hoppas ansluta sig till deras hemliga styrka.",al={"mennet carkads roll","vem ger uppdraget"}},{q="Varför behöver Mennet Astor Hadrens brev?",a="Astor Hadren är en kurir som färdas mellan Silverpine Forest och Undercity. Om Deathstalkers får tag i hans introduktionsbrev kan deras nya agent ta Hadrens plats och lura en medarbetare vid namn Andron.",al={"astor hadrens brev","varför genskjuta budbäraren","astor hadrens introduktionsbrev"}},{q="Vart reser Astor Hadren?",a="Astor Hadren färdas längs vägen mellan Undercity och Silverpine Forest och transporterar korrespondens mellan områdena åt sina kontakter.",al={"astor hadrens färdväg","var astor hadren finns","var är astor"}},{q="Vem är Lord Varimathras?",a="Varimathras är en Nathrezim-dreadlord som allierade sig med drottning Sylvanas Windrunner för att rädda sitt eget liv. Från Royal Quarter övervakar han Undercitys säkerhet, försvar och skurkverksamhet.",al={"varimathras roll","dreadlord i undercity"}},{q="Vad händer efter provet?",a="Den som klarar provet visar sin kompetens och får gå vidare till ett hemligt uppdrag: att utge sig för att vara Astor, leverera hans dokument och infiltrera Androns förehavanden.",al={"what comes next","fortsättning på deathstalkers uppdragskedja"}}},fx={["1398690a"]={q="Varför vill Mennet Carkad att det här ska göras?",a="Mennet Carkad leder en infiltrationsoperation som bygger på att fånga upp ett meddelande till en kontakt vid namn Andron. Genom att stjäla Astor Hadrens brev får Mennet de uppgifter som behövs för att obemärkt föra in en agent i Androns förtroende.",al={"varför behöver mennet det här","mennet carkads motiv","varför stjäla brevet"}},["763d70d5"]={q="Vem är Astor Hadren?",a="Astor Hadren är en kurir som färdas mellan Silverpine Forest och Undercity. Han bär på ett introduktionsbrev till en kontakt vid namn Andron. Han vet inte att The Deathstalkers har siktat in sig på hans korrespondens för sina egna hemliga planer.",al={"vem är hadren","astor hadren","mål astor hadren"}},f8c6b26b={q="Varför skickar Mennet Carkad dig i stället för en erfaren agent?",a="Du försöker visa att du förtjänar att gå med i The Deathstalkers, de elitrogues som tjänar Lord Varimathras. Mennet använder medvetet blivande rekryter i farliga fältprov där de kan offras, för att se om de har den list och dödlighet som orden kräver.",al={"varför jag för the deathstalkers","varför skickar mennet mig","varför inte använda en befintlig agent från the deathstalkers"}}},fp="17,203,21.365.0,16.305.1,26.236.0,21.152.0,43.122.0,31.116.0,24.207.0,30.155.1"}
P.entries["quest:189"] = {n="Bloodscalp Ears",s="Kebok i Booty Bay förlorar vakter och agenter i strider mot Bloodscalp-stammen i djungeln. Han oroar sig över de växande kostnaderna och över att behöva stå till svars inför Baron Revilgaz. Därför erbjuder han mynt till alla äventyrare som är villiga att jaga trollen och återvända med bevis på att de dödats.",h="Kebok i Booty Bay förlorar vakter och agenter i strider mot Bloodscalp-stammen i djungeln.",kw={"bloodscalp","booty bay","öron","kebok","revilgaz","stranglethorn","troll"},sec={{t="Växande kostnader",b="I den livliga hamnen Booty Bay står Kebok inför ett allvarligt problem med verksamheten. De lokala trollen i Stranglethorn Vale har dödat hans agenter i djungeln, och han har förlorat många av sina bästa vakter i skärmytslingar med dem. Förlusterna växer, och det gör även kostnaderna, så han är förtvivlad över hur han ska förklara dem för Baron Revilgaz."},{t="En begränsad belöning",b="I stället för att låta förlusterna fortsätta vända sig Kebok till hjälp utifrån. Han erbjuder betalning till resenärer som ger sig in i djungeln, rensar ut Bloodscalp-trollen och tar tillbaka femton av deras avhuggna öron som obestridligt bevis på att de dödats."}},faq={{q="Vem är Kebok?",a="Kebok är en goblin i Booty Bay med agenter och vakter ute i djungeln, och han måste stå till svars inför Baron Revilgaz för vad de kostar.",al={"kebok","vem är kebok","vem ger bloodscalp-öron"}},{q="Varför vill Kebok ha Bloodscalp-öron?",a="Bloodscalp-trollen har dödat hans agenter i djungeln och kostat honom många av hans bästa vakter i skärmytslingar. Kostnaderna hopar sig, och han har inget bra sätt att förklara dem för Baron Revilgaz.",al={"varför öron","varför bloodscalp-öron","varför samla öron"}},{q="Hur många öron behövs?",a="Kebok kräver femton Bloodscalp-öron innan han betalar dig.",al={"hur många öron","antal öron"}},{q="Vart leder den här belöningen härnäst?",a="När Kebok har betalat dig för Bloodscalp-öronen riktar han uppmärksamheten mot ett annat lokalt hot: Skullsplitter Tusks.",al={"what comes next","fortsättning på bloodscalp-öron","nästa uppdrag"}}},fp="15,256,14.341.0,16.271.0,13.134.0,36.197.0,27.77.0,33.123.1"}
P.entries["quest:1898"] = {n="The Deathstalkers",s="Det här hemliga uppdraget skickar en agent under täckmantel till Undercitys mörka undre värld för att förhöra en ovetande medbrottsling. På order av Lord Varimathras utger du dig för att vara en väntad budbärare och avslöjar förräderi i Forsakens egen huvudstad.",h="Det här hemliga uppdraget skickar en agent under täckmantel till Undercitys mörka undre värld för att förhöra...",kw={"andron gant","apothecarium","astor hadren","deathstalkers","spioneri","forsaken","mennet carkad","undercity","varimathras"},ang={["class:Rogue"]="Att infiltrera en spionring med en död mans identitet för att locka fram en oförsiktig medbrottsling är spionkonst direkt ur Deathstalkers handbok.",["faction:Horde"]="Under Undercitys yta finns ett näste av politiska intriger. Det visar att förtroende är en bristvara även inom Hordens gränser.",["race:Undead"]="För Forsaken är vaksamhet en fråga om överlevnad. Varje medborgare som ertappas med att hjälpa yttre fraktioner riskerar att genast rensas ut av den mörka damens hemliga polis."},sec={{t="Ett nät av svek",b="Deathstalkers nöjer sig inte med att undanröja yttre hot mot Forsaken. De håller också sina egna medborgare under hård uppsikt. Lord Varimathras misstankar får Deathstalker Mennet Carkad att sätta en infiltrationsplan i verket. Du får ett förfalskat eller införskaffat introduktionsbrev som tillhör Astor Hadren och ska smita förbi den lokala köpmannen Andron Gants misstankar."},{t="Butiken nära Apothecarium",b="Andron Gant driver en butik nära de vidriga ångorna och bubblande kittlarna i Apothecarium. Mennet anser att butiksägaren är dum och ouppmärksam, utan vett nog att genomskåda en bedragare. När du visar brevet kan du utge dig för att vara kurir. Gant sänker genast garden och berättar ivrigt om sina affärer med en okänd tredje part."}},faq={{q="Vem är Andron Gant?",a="Andron Gant är en köpman i Undercity, nära Apothecarium. Deathstalkers och Lord Varimathras håller honom under uppsikt eftersom han påstås förmedla underrättelser och hjälp till en okänd yttre fraktion.",al={"andron gant","vem är gant","var finns andron gant"}},{q="Varför intresserar sig Lord Varimathras för den här köpmannen?",a="Varimathras misstänker att Gant samarbetar med en organisation utanför Forsaken. För att skydda staden och rensa ut möjliga förrädare kräver dreadlorden konkreta bevis på Gants kontakter och avsikter.",al={"varför varimathras bryr sig","varimathras och andron gant","varför spionera på andron"}},{q="Hur lurar spelaren Andron Gant?",a="Mennet Carkad ger dig Astor's Letter of Introduction. Gant väntar sig en kurir och Deathstalkers anser inte att han är särskilt skarpsinnig. Det räcker därför att visa honom brevet för att vinna hans förtroende.",al={"astors brev","hur lurar man andron gant","budbärard förklädnad"}},{q="Vad är Deathstalkers för grupp?",a="Deathstalkers är Forsakens elitförband av skurkar och hemliga underrättelsetjänst. De verkar i skuggorna under Queen Sylvanas och Lord Varimathras, avslöjar uppvigling, saboterar fiender och undanröjer inre hot.",al={"deathstalkers historia","vilka är deathstalkers","skurkar i undercity"}},{q="Var hittar man Andron Gant?",a="Han håller till i sin butik nära ingången till Apothecarium-kvarteret i Undercity. Där sköter han sina affärer under Royal Apothecary Society och Deathstalkers vakande blickar.",al={"andron gants plats","var ligger gants butik"}},{q="Vad händer när Gant tar emot brevet?",a="Gant tar emot brevet utan misstankar och tror att du bara är en budbärare utan bekymmer. Han antyder genast att han samarbetar med gemensamma bekanta, vilket bäddar för att du ska få fram fler bevis på hans förräderi.",al={"vad gör gant","gants reaktion"}}},fx={["6d39edb7"]={q="Varför vill Mennet Carkad att Andron Gant ska undersökas?",a="Mennet Carkad handlar direkt på order från Lord Varimathras. Nathrezimen misstänker att Andron Gant i hemlighet förmedlar hjälp och information till en okänd rivaliserande fraktion inne i Undercity. För att skydda Forsakens ledning mot inre omstörtning behöver Mennet definitiva bevis för Gants förräderi och veta vilken skuggorganisation han tjänar.",al={"varför utreda andron gant","mennet carkads motiv","varför skickar mennet mig till gant"}},["3bf738ba"]={q="Varför skickar Mennet Carkad dig i stället för att gå själv?",a="Mennet Carkad har redan träffat Andron Gant personligen, så hans egen närvaro skulle genast röja uppdraget. Gant skulle omedelbart känna igen en känd agent från The Deathstalkers. Eftersom du har Astor Hadrens introduktionsbrev har Gant ingen anledning att misstänka att du är någon annan än kuriren han väntade sig att träffa.",al={"varför behöver mennet mig","varför kan mennet inte tala med gant","varför använda en äventyrare"}}},fp="17,224,15.340.0,30.260.1,19.183.0,52.178.0,40.163.0,33.233.0,31.181.0,43.203.1"}
P.entries["quest:1899"] = {n="The Deathstalkers",s="Det här ärendet fortsätter Deathstalkers bedrägeri mot informatören Andron Gant i Undercity. Gant tror fortfarande att du är budbäraren han väntade på och lämnar över en liggare avsedd för hans hemliga kontakter. Operatören överlämnar den i stället till Mennet Carkad i Rogues' Quarter. Överlämningen markerar övergången från enkla förfrågningar till djupare och mer hemliga uppdrag för Forsaken-staten.",h="Det här ärendet fortsätter Deathstalkers bedrägeri mot informatören Andron Gant i Undercity.",kw={"andron gant","lönnmördare","deathstalkers","spioneri","liggare","mennet carkad","rogues' quarter","undercity"},ang={["class:Rogue"]="För en blivande skurk i Undercity är känsliga kuriruppdrag åt Mennet Carkad ett grundläggande prov på diskretion. De visar att en operatör kan hantera hemliga tillgångar utan att väcka onödig uppmärksamhet.",["race:Undead"]="Inre säkerhet är en fråga om liv och död i Undercity. Genom att hjälpa Deathstalkers stärker du direkt Mörka damens grepp om huvudstaden mot både levande infiltratörer och rivaliserande odöda."},sec={{t="En budbärare i skuggorna",b="Deathstalkers förlitar sig inte enbart på råstyrka eller skuggmagi. Deras operationer bygger i hög grad på vanliga liggare, nedtecknade namn och noggrann övervakning. Andron Gant, som verkar från Undercity, lämnar över en personlig liggare fullproppad med underrättelser. Han tror att den är på väg till de gåtfulla uppdragsgivare han tjänar i hemlighet. Gant går på operatörens förklädnad och ber till och med att samma budbärare ska skickas i framtiden. Han anar aldrig att liggaren är på väg rakt till Deathstalkers."},{t="Underrättelser i Rogues' Quarter",b="När liggaren lämnas över till Mennet Carkad i Rogues' Quarter visar den sig vara betydligt mer avslöjande än Deathstalkers hade väntat sig. I stället för knapphändiga anteckningar innehåller Gants skrifter användbara ledtrådar som låter Carkad utvidga utredningarna. I Forsaken-riket, där paranoia och splittring råder, är verifierade dokumentkedjor avgörande för att avslöja inre omstörtande verksamhet och hålla uppsikt över yttre hot innan de slår till mot huvudstaden."}},faq={{q="Vad finns i Andron's Ledger?",a="Liggaren innehåller känslig information och uppgifter som Andron Gant har samlat in. Det exakta innehållet läses inte upp, men Mennet Carkad konstaterar att den innehåller betydligt fler detaljer och mer värdefulla underrättelser än Deathstalkers först väntade sig att få från honom.",al={"innehållet i androns liggare","vad står det i liggaren","deathstalkers liggare"}},{q="Vilka är Deathstalkers?",a="Deathstalkers är Forsakens främsta hemliga organisation och lönnmördargille. De har sitt högkvarter i Rogues' Quarter i Undercity och fungerar som Lady Sylvanas Windrunners ögon, öron och dolda dolkar. De hanterar spioneri, underrättelser och riktade mord i hela Lordaeron.",al={"deathstalkers historia","vilka är deathstalkers","rogues i undercity"}},{q="Varför vill Gant att samma budbärare ska anlitas i framtiden?",a="I Undercitys grumliga och misstänksamma atmosfär är det ovanligt att hitta en operatör som kan transportera känsliga dokument utan att stjäla eller manipulera dem. Gant ber uttryckligen om att framtida affärer ska skötas av samma kurir för att minska riskerna och bevara den etablerade arbetsrelationen.",al={"varför gillar gant dig","andron gant förtroende","gant budbärare"}},{q="Vem är Mennet Carkad?",a="Mennet Carkad är en erfaren operatör för Deathstalkers, stationerad i Rogues' Quarter. Han samordnar lokala agenter, samlar in fältunderrättelser från informatörer som Andron Gant och leder hemliga uppdrag i huvudstaden och de omgivande områdena.",al={"mennet carkads historia","vem är carkad"}},{q="Var ligger Rogues' Quarter?",a="Rogues' Quarter är den södra stadsdelen i Undercity. Den fungerar som huvudbas för Forsakens smygande operatörer, tjuvar och lönnmördare. Där finns träningsplatser och mörka gömställen långt från de övre ruinernas offentliga torg.",al={"rogues quarters plats","var ligger rogues quarter","undercitys rogues quarter"}},{q="Varför behöver Forsaken en intern underrättelsetjänst?",a="Den unga Forsaken-nationen är omringad av Scourge, Scarlet Crusade och misstänksamma rester av Alliansen, och står inför ständiga hot om infiltration och uppror. Deathstalkers avslöjar omstörtande verksamhet inom Lordaerons gränser för att säkra den spirande regimens överlevnad.",al={"varför finns deathstalkers","forsakens spioner","undercitys underrättelsetjänst"}}},fx={["63e535f7"]={q="Varför vill Andron Gant att liggaren ska levereras?",a="Andron Gant tror att du är budbäraren som skickats av de hemliga kontakterna han har försett med information. Han lämnar över liggaren till dem och ber att du skickas igen om de vill fortsätta samarbetet. Han anar inte att den går raka vägen till The Deathstalkers.",al={"varför leverera liggaren","andron gants motiv","varför samarbetar andron"}}},fp="17,289,24.307.0,35.332.1,27.170.0,26.269.0,55.187.0,21.252.0,37.231.0,57.245.0"}
P.entries["quest:19"] = {n="Tharil'zun",s="Marshal Marris sätter en belöning på Tharil'zun, den listige ledaren för Blackrock-framryckarna som härjar på vägarna nära Stonewatch Keep. Att fälla honom är ett avgörande steg för att bryta Blackrock-klanens grepp om norra Redridge. När hans avhuggna huvud förs tillbaka till Lakeshire markerar det en hårt vunnen seger för den hårt ansatta stadsvakten.",h="Marshal Marris sätter en belöning på Tharil'zun, den listige ledaren för Blackrock-framryckarna som härjar på...",kw={"blackrock","lakeshire","marshal marris","framryckare","redridge","stonewatch","stonewatch keep","tharil'zun","tharilzun"},ang={["faction:Alliance"]="Lakeshire är till stor del isolerat utan direkta förstärkningar från Stormwind. Därför är belöningen för Tharil'zun en viktig lokal åtgärd för att hindra staden från att belägras.",["race:Human"]="Blackrocks närvaro i Redridge är en smärtsam påminnelse om det första och andra kriget, och när Tharil'zun fälls återtas mark som stulits från kungariket.",["race:Orc"]="Tharil'zun tillhör den mörka kvarlevan av den gamla Horden under Blackrocks fana och tjänar herrar som förkastar Thralls nya ordning på andra sidan havet."},sec={{t="Vägen till Stonewatch",b="Det slingrande passet mellan Lakeshire och Stonewatch Keep har blivit en fälla full av plötsliga bakhåll. Blackrock-framryckare och avfällingar stryker omkring på de klippiga höjderna, skär av spanare och hotar alla förstärkningar som försöker ta sig mot fästningen. Marshal Marris pekar ut Tharil'zun som befälhavaren bakom de samordnade anfallen och slår fast att han måste undanröjas för att Lakeshire inte ska bli helt instängt."},{t="Halshuggning av framryckarna",b="Tharil'zun är en farlig typ av fältbefäl: grym, listig och kapabel att samordna de splittrade orkrövarna till en effektiv plundringsstyrka. Att ta hans huvud i skuggan av Stonewatch kräver att du kämpar dig igenom Blackrocks befästa utposter. Hans död bryter sammanhållningen i framryckarnas patruller och röjer väg för Alliansen att möta garnisonen som håller själva borgen."}},faq={{q="Vem är Tharil'zun?",a="Tharil'zun är en mäktig Blackrock-orkbefälhavare som leder framryckarna och avfällingarna bakom bakhållen längs stigarna mellan Lakeshire och Stonewatch Keep.",al={"vem är tharilzun","tharil'zuns bakgrund","tharilzun-boss"}},{q="Var hittar man Tharil'zun?",a="Tharil'zun håller till nära Stonewatch Keep i nordöstra Redridge och leder framryckarna som patrullerar passen och utposterna i området.",al={"var finns tharil'zun","tharilzuns plats","hitta tharil'zun"}},{q="Varför vill Marshal Marris ha hans huvud?",a="Marris ser Tharil'zun som den listige taktiker som leder bakhållen som plågar Redridge. Hans huvud visar att ledarskapet bland framryckarna har slagits ut och ger obestridligt bevis på att hotet har undanröjts.",al={"varför döda tharil'zun","varför belöning på tharil'zun"}},{q="Vad händer efter att Tharil'zun besegrats?",a="När Tharil'zun undanröjs försvagas framryckarnas samordning, så att Lakeshires försvarare och äventyrare kan tränga djupare in i Stonewatch Keep och möta Blackrocks huvudgarnison.",al={"uppdrag efter tharil'zun","vad händer efter tharil'zun"}},{q="Varför finns Blackrock-orker i Redridge Mountains?",a="Rester av Blackrock-klanen trängde söderut från Burning Steppes in i Redridge och befäste gamla mänskliga utposter som Stonewatch Keep. De vill hota Eastern Kingdoms medan Stormwinds militär är hårt ansatt.",al={"varför finns blackrock-orker i redridge","bakgrund om orkerna i stonewatch"}},{q="Vilket krav måste uppfyllas innan jakten på Tharil'zun?",a="Marshal Marris kräver att äventyrarna först visar sitt värde genom att decimera invasionsstyrkorna i uppdraget 'Blackrock Menace' innan han skickar dem efter Tharil'zun själv.",al={"krav för tharil'zun","låsa upp uppdraget om tharil'zun"}}},fx={["3b83e264"]={q="Varför behöver Marshal Marris Tharil'zun's Head?",a="Marshal Marris kräver Tharil'zun's Head som slutgiltigt bevis på krigsherrens död. Tharil'zun är en listig och grym ledare som styr överfall mot Lakeshire's försvarare. Marris kan inte förlita sig på rykten eller felaktiga rapporter när hela regionens säkerhet hänger på en skör tråd.",al={"vad ska tharil'zun's head användas till","syftet med tharil'zun's head","varför ta tharil'zun's head"}},["66abe4be"]={q="Varför skickar Marshal Marris dig i stället för stadsvakten?",a="Lakeshire's lokala garnison är pressad till bristningsgränsen. Stormwind håller inne med förstärkningar och orkernas bakhåll hotar staden. Marshal Marris har inte råd att avvara soldater för att tränga djupt in på Stonewatchs område. Han måste förlita sig på erfarna, självständiga äventyrare för att fälla fiendens viktigaste befälhavare.",al={"varför skicka en äventyrare","varför inte använda redridge-vakter","varför behöver marris mig"}}},fp="10,276,22.389.0,27.350.0,18.145.0,30.130.0,38.197.0,42.184.0,45.212.0,62.141.0"}
P.entries["quest:190"] = {n="Panther Mastery",s="Sir S. J. Erlgadin från Nesingwary's Expedition erbjuder ett prov för dem som vill bevisa sin skicklighet som storviltsjägare i Stranglethorn Vale. För att ansluta sig till Hemets jaktlag måste äventyrarna först visa att de kan spåra genom att fälla tio unga pantrar.",h="Sir S.",kw={"hemet","nesingwary","pantermästerskap","sir s. j. erlgadin","stranglethorn vale","unga pantrar"},sec={{t="Ett skickligt jaktlag",b="I norra Stranglethorn Vales vilda vidder har Hemet Nesingwary samlat ett erfaret jaktlag för storvilt. Sir S. J. Erlgadin säger till alla som vill delta i jakten att de först måste bevisa att de är skickliga panterjägare."},{t="Spåra rovdjuren",b="Innan Erlgadin anförtror någon större villebråd ger han dem ett inträdesprov: att hitta och döda tio unga pantrar. Att bara hitta bestarna är bara halva utmaningen."}},faq={{q="Vem ger den här jaktutmaningen?",a="Sir S. J. Erlgadin ger utmaningen från Nesingwary's Expeditions läger i norra Stranglethorn Vale. Han prövar nykomlingar som vill ansluta sig till Hemets jaktlag.",al={"uppdragsgivare för pantermästerskap","vem startar pantermästerskap","erlgadin-uppdrag"}},{q="Vilket byte ska jag jaga?",a="Sir S. J. Erlgadin ber jägarna spåra upp och döda tio unga pantrar som strövar omkring i den omgivande djungelsnåren.",al={"vad ska jag döda för pantermästerskap","mål för pantermästerskap","unga pantrar"}},{q="Varför ger Sir S. J. Erlgadin det här provet?",a="Hemet Nesingwary har samlat ett erfaret jaktlag, och Erlgadin vill att nykomlingarna bevisar att de är skickliga panterjägare innan de ansluter sig till jakten.",al={"varför döda unga pantrar","syftet med pantermästerskap"}},{q="Vad händer efter den här jakten?",a="När du klarat det här första provet går du direkt vidare till Panther Mastery (2), där Sir S. J. Erlgadin höjer svårighetsgraden på bytet.",al={"nästa uppdrag i pantermästerskap","vad kommer efter pantermästerskap"}}},fp="15,276,24.247.0,21.169.0,33.170.0,27.114.0,45.151.0,43.133.0"}
P.entries["quest:191"] = {n="Panther Mastery",s="Sir S. J. Erlgadin kräver att du visar dig värdig storviltjägarna vid Nesingwary's Expedition. Efter att du först gallrat ut yngre djur utmanar han dig att spåra upp och döda tio fullvuxna pantrar i Stranglethorn Vale vildmarker.",h="Sir S.",kw={"storvilt","erlgadin","jakt","mästerskap","nesingwary","panter","stranglethorn"},sec={{t="En högre standard",b="När du har tagit hand om de unga pantrarna runt djungeln ber Sir S. J. Erlgadin dig att sikta högre. För att visa att du förtjänar att umgås med erfarna storviltjägare skickas du ut för att jaga tio fullvuxna pantrar, som är mycket starkare och farligare än deras yngre släktingar."}},faq={{q="Vem erbjuder detta prov?",a="Sir S. J. Erlgadin, en jägare stationerad vid Nesingwary's Expedition i norra Stranglethorn Vale, övervakar detta jaktmoment.",al={"vem ger panther mastery","erlgadin uppdrag","uppdragsgivare"}},{q="Vilket byte ska du jaga?",a="Du ska spåra upp och besegra tio fullvuxna pantrar i den omgivande djungeln. De är starkare än de yngre exemplar du tidigare jagade.",al={"vilka pantrar ska dödas","vilka djur","målet för panther mastery"}},{q="Vad kommer före den här utmaningen?",a="Detta följer på ett tidigare prov, också med titeln Panther Mastery, där Erlgadin prövade din styrka mot yngre djungelpantrar.",al={"föregående uppdrag","tidigare steg","förutsättning för panther mastery"}},{q="Vad är syftet med att jaga dessa pantrar?",a="Sir S. J. Erlgadin kräver att du bevisar att du har skickligheten och styrkan som krävs för att umgås och jaga tillsammans med expeditionens erfarna storviltjägare.",al={"varför döda pantrar","erlgadins motiv","nesingwarys syfte"}}},fp="15,258,17.289.0,22.130.0,34.151.0,33.129.0,46.154.0"}
P.entries["quest:1918"] = {n="The Befouled Element",s="När de besegrar de upprörda vattenelementalerna kring Mystral Lake hittar äventyrare en motbjudande, lysande glob med förorenat vatten. För att förstå vad som har förgiftat sjön och dess elementandar tar de med sig provet till Mastok Wrilehiss vid Splintertree Post.",h="När de besegrar de upprörda vattenelementalerna kring Mystral Lake hittar äventyrare en motbjudande, lysande...",kw={"ashenvale","befouled water globe","förvridna elementaler","earthen ring","mastok wrilehiss","mystral lake","splintertree post"},ang={["class:Shaman"]="Mystral Lakes förvridna andar oroar shamanerna djupt. De hör elementens smärta och förstår att Earthen Ring måste ingripa.",["faction:Horde"]="Splintertree Post har inte råd med ett kaotiskt elementhot som växer sig starkare på bakgården, medan Alliance-vaktposter och furbolger hotar Hordes försörjningsleder.",["race:Tauren"]="Tauren-resenärer känner en djup kulturell plikt att hela landets förorenade vatten, vilket gör återställandet av Mystral Lake till en angelägen andlig uppgift."},sec={{t="Förorenat vatten i Mystral Lake",b="Mystral Lake, inbäddad i södra centrala Ashenvale, är i allvarlig obalans. Vattenelementalerna som lever i det grunda vattnet har blivit våldsamt aggressiva och är synbart förvridna. När de fälls lämnar de efter sig märkliga, intensivt lysande klot av stinkande vätska i stället för ren elementaressens. Förvridningen som lagt sig över sjön är koncentrerad i dessa klot, vilket visar att störningen är mycket mer än naturlig reviraggression."},{t="Råd från Splintertree",b="Utan att förstå den onda magin som ligger bakom söker Horde-spejare råd hos garnisonen vid Splintertree Post. Mastok Wrilehiss, en av utpostens befälhavare, äcklas först av det vidriga provet som förs till honom. Som soldat snarare än lärd inser Mastok snabbt att vanligt stål inte kan bota sjukt vatten, så han hänvisar äventyraren till elementexperterna i Earthen Ring."}},faq={{q="Vad finns i Befouled Water Globe?",a="Globen innehåller ett motbjudande, koncentrerat prov av den förvridning som nu förgiftar Mystral Lake. Det bildas av resterna från besegrade elementaler och visar att deras andliga förvridning är fysisk och kraftfull.",al={"innehåll i den förorenade globen","vad finns i vattengloben","mystral lake vattenglob"}},{q="Var börjar uppdraget?",a="Uppdraget börjar med att föremålet faller när du strider mot de ursinniga eller förorenade vattenelementalerna som lever i Mystral Lake i södra centrala Ashenvale.",al={"var hittar jag vattengloben","hur startar befouled element","uppdragsstart"}},{q="Varför vill Mastok Wrilehiss inte befatta sig med det?",a="Mastok Wrilehiss är en Horde-officer som fokuserar på militär överlevnad och logistik vid Splintertree Post. Han är inte inriktad på att diagnostisera magiskt sjukt vatten, så han föreslår att du i stället söker upp Earthen Ring.",al={"vem är mastok","varför prata med mastok","mastok wrilehiss roll"}},{q="Varför intresserar sig Earthen Ring för det här?",a="Earthen Ring är en sammanslutning av shamaner som ägnar sig åt att studera, lugna och återställa harmonin mellan elementen. Förvridna elementaler som de vid Mystral Lake faller direkt inom deras andliga ansvarsområde.",al={"varför earthen ring","earthen rings koppling","vilka är earthen ring"}},{q="Vart leder undersökningen härnäst?",a="Mastok hänvisar dig till Je'neu Sancrea, en shaman från Earthen Ring som är stationerad längs Ashenvales västra kust vid Zoram'gar Strand och kan undersöka den förorenade reliken ordentligt.",al={"what comes next","nästa uppdrag efter befouled element","vart går jag härnäst"}}},fp="20,204,30.373.0,30.290.1,40.214.0,28.114.0,53.201.0,44.190.0,39.164.1"}
P.entries["quest:192"] = {n="Panther Mastery",s="Sir S. J. Erlgadin från Nesingwary's Expedition utmanar storviltsjägare att spåra upp och fälla de farligaste pantrarna i Stranglethorn Vale. Efter dina tidigare prövningar ska du nu leta upp och döda tio Shadowmaw Panthers.",h="Sir S.",kw={"storvilt","nesingwary","panther mastery","shadowmaw panther","sir s. j. erlgadin","stranglethorn vale"},ang={["class:Hunter"]="Erlgadin utmanar dig direkt att bevisa ditt rykte som storviltsjägare och förväntar sig att du ska bemästra konsten att smyga dig på och döda djungelns våldsammaste rovdjur."},sec={{t="Det farligaste bytet",b="Sir S. J. Erlgadin anser att Shadowmaw Panthers är de farligaste kattdjuren som stryker omkring i Stranglethorns djungler. För att visa att du är en sann spårare måste du krypa genom den täta snårskogen och spåra upp tio av dessa svårfunna bestar, vars våldsamhet gör dem mycket svårare att döda än att hitta."}},faq={{q="Vem erbjuder den här jakten?",a="Sir S. J. Erlgadin erbjuder den här utmaningen från Nesingwary Expedition-lägret i norra Stranglethorn Vale.",al={"vem ger panther mastery","uppdragsgivare för panther mastery","vem ger det här uppdraget"}},{q="Vilka bestar jagar du?",a="Du ska jaga tio Shadowmaw Panthers, som Erlgadin kallar de farligaste pantrarna i hela Stranglethorn.",al={"vad ska jag döda","målet för panther mastery","vilka pantrar"}},{q="Var passar det här in bland jaktprövningarna?",a="Det här är den tredje prövningen i panterjaktserien, direkt efter den andra Panther Mastery-prövningen och före den fjärde.",al={"vilket uppdrag kommer före det här","panther mastery-uppdragskedjan","förutsättningsuppdrag"}}},fp="15,229,20.303.0,21.108.0,28.113.0,42.138.0"}
P.entries["quest:193"] = {n="Panther Mastery",s="Sir S. J. Erlgadin har satt det sista provet i sin panterjakt framför dig i norra Stranglethorn Vale. Efter att ha visat din skicklighet mot traktens pantrar utmanas du att leta upp Bhag'thera, ett svårfångat rovdjur som hittills har undkommit expeditionens folk. Om du för tillbaka bestens huggtand visar du att du verkligen behärskar jakten.",h="Sir S.",kw={"bhag'thera","fang of bhag'thera","nesingwary's expedition","pantermästerskap","sir s. j. erlgadin","stranglethorn vale"},sec={{t="Den svårfångade pantern",b="Vid Nesingwary's Expedition anser Sir S. J. Erlgadin att dina prov nästan är avklarade. Ett sista byte återstår för att visa att du duger mot djungelns rovdjur: en panter vid namn Bhag'thera. Besten har hittills undkommit expeditionens eget jaktlag medan den stryker omkring i Stranglethorn Vales vildmarker. Erlgadin ber dig spåra upp denna väldiga jägare och ta Fang of Bhag'thera som bevis på din skicklighet."}},faq={{q="Vem erbjuder jakten?",a="Sir S. J. Erlgadin ger dig denna utmaning vid Nesingwary's Expedition i norra Stranglethorn Vale.",al={"uppdragsgivare","vem ger pantermästerskap","erlgadins uppdrag"}},{q="Vilket vilddjur jagar du?",a="Bytet är Bhag'thera, en väldig panter som stryker omkring i djungeln och hittills har undkommit expeditionens folk.",al={"vad är målet","vem är bhag'thera","pantermål"}},{q="Vilken trofé krävs?",a="Sir S. J. Erlgadin kräver Fang of Bhag'thera som bevis på att besten har besegrats.",al={"vilket bevis","vilket föremål","bhag'theras trofé"}},{q="Vad föregick den här jakten?",a="Den här utmaningen följer på det tredje provet i Panther Mastery-serien och bygger vidare på de tidigare panterjakterna.",al={"föregående uppdrag","förutsättning för pantermästerskap"}}},fp="15,361,19.403.0,21.98.0,27.110.0,24.85.0,27.106.0"}
P.entries["quest:1938"] = {n="Ur's Treatise on Shadow Magic",s="I Stormwind söker övermagikern Andromath den förbjudna volym som Morganth stal och förde till Tower of Ilgalar i Redridge Mountains.",h="I Stormwind söker övermagikern Andromath den förbjudna volym som Morganth stal och förde till Tower of...",kw={"andromath","ilgalar","morganth","skuggmagi","stormwind","avhandling","ur","wizards sanctum"},ang={["class:Mage"]="Som magiker ser du att magikerna i Stormwind tar den interna disciplinen på allvar. De litar på att utövare begränsar faran som lämnats efter en kamrat som vände sig till förbjuden skuggmagi.",["class:Warlock"]="Som häxmästare kanske du trånar efter krafterna inom utomdimensionell åkallan och mörk magi som förseglats i Urs avhandlingar, trots att Kirin Tor och Stormwinds magiker fruktar dem.",["faction:Alliance"]="Som medlem av Alliansen hjälper du till att skydda Redridge från Morganths växande magiska hot och Stormwind från förbjuden arkana genom att återta den stulna volymen."},sec={{t="En schism i tornet",b="Tre lovande magiker studerade en gång tillsammans i Stormwinds Wizard's Sanctum. Morganth vände sig till mörka konster och skuggmagi, trots sina kamraters desperata varningar om att överge dessa fördärvande krafter. Stadens magikerorden bannlyste honom formellt. Innan han gav sig av stal han ett farligt verk av Ur, en ökänd ärkemagiker vars studier sträckte sig bortom den ortodoxa arkanan."},{t="Den fallne magikerns håla",b="Morganth tog Tower of Ilgalar i besittning, högt uppe i Redridge Mountains och långt från Stormwinds insyn. Övermagikern Andromath anser att volymens kunskap är farlig i händerna på en utstött som utövar förbjuden trolldom. Han skickar alliansäventyrare för att ta sig in i tornet och återta den innan dess skydd faller."},{t="Skydden intakta",b="När avhandlingen har hämtats från Ilgalars bibliotek och återförts till Wizard's Sanctum känner övermagikern Andromath stor lättnad. Han fruktade att Morganth redan hade löst upp dess skyddande förtrollningar eller gömt boken utom räckhåll. De magiska sigillen på Urs avhandling höll stånd och hindrade de katastrofala hemligheterna på dess sidor från att nå den förrymde magikern."}},faq={{q="Vem skrev avhandlingen?",a="Ur skrev avhandlingen. Den legendariska magikern från Dalaran var känd för esoterisk forskning om utomdimensionella väsen och skuggmagi.",al={"vem är ur","avhandlingens författare","urs avhandlings författare"}},{q="Vem stal Ur's Treatise on Shadow Magic?",a="Morganth stal Ur's Treatise on Shadow Magic. Han var en magiker från Stormwind som föll för mörk magi och bannlystes från Wizard's Sanctum.",al={"vem stal boken","vem tog avhandlingen","morganths bok"}},{q="Var förvaras boken?",a="Boken finns i biblioteket i Tower of Ilgalar, högt uppe i Redridge Mountains, där Morganth grundade sin nya fristad.",al={"var finns avhandlingen","bokens plats i tower of ilgalar","var hittar man urs avhandling"}},{q="Lyckades Morganth läsa boken?",a="Nej. Övermagikern Andromath bekräftar att bokens skyddande sigill höll när den återlämnades, så Morganth öppnade den aldrig.",al={"öppnade morganth boken","öppnades avhandlingen","är sigillen brutna"}},{q="Varför vill magikerna i Stormwind ha tillbaka boken?",a="Volymen innehåller djupa hemligheter om skuggmagi som kan leda till fördärv för den oerfarne. Stormwinds magiker anser att det är alltför farligt att låta Morganth, en utstött som utövar förbjuden trolldom, behålla den.",al={"varför återta boken","varför är avhandlingen farlig","andromaths mål"}},{q="Vem ger uppdraget?",a="Övermagikern Andromath ger uppdraget från Wizard's Sanctum i Stormwinds Mage Quarter.",al={"uppdragsgivare","var får man uppdraget om urs avhandling","andromaths uppdrag"}}},fx={["705e1c6d"]={q="Vad är Ur's Treatise on Shadow Magic?",a="Det är en kraftfull och farlig bok som utforskar skuggmagiens mörka hemligheter. Den skrevs av Kirin Tor-magikern Ur. Dess innehåll är inte avsett för den oerfarne, eftersom fördjupning i dess förbjudna kunskap kan leda rakt mot undergång och fördärv. För att hindra missbruk förseglade Stormwinds magiker boken med magiska sigill.",al={"ur's treatise on shadow magic","vad är avhandlingen","vad gör ur's treatise"}}},fp="29,140,21.361.0,22.319.0,12.356.1,23.129.0,40.136.0,23.129.0,37.130.1,49.193.0,21.88.0"}
P.entries["quest:1939"] = {n="High Sorcerer Andromath",s="I Wizard's Sanctum i Stormwind kallar en kallelse lovande magiker från Alliansen till tornets topp. Andromath verkar bland rikets främsta ärkemagiker, långt från det förstörda Dalaran.",h="I Wizard's Sanctum i Stormwind kallar en kallelse lovande magiker från Alliansen till tornets topp.",kw={"andromath","arkana","dalaran","jennea cannon","mage quarter","stormwind","wizard's sanctum"},ang={["class:Mage"]="Som magiker går du från vanliga besvärjelseövningar med Jennea Cannon till farlig, specialiserad kunskap tillsammans med en av Stormwinds främsta ärkemagiker.",["faction:Alliance"]="Som medlem i Alliansen förlitar du dig på Stormwinds Sanctum för att utbilda magiker och bekämpa övernaturliga hot medan Dalarans överlevande magiker återuppbygger sin förstörda stad."},sec={{t="Kallelse till tornet",b="Jennea Cannon, som samordnar lärlingarna i Stormwinds Mage Quarter, skickar lovande magiker upp till toppen av Wizard's Sanctum. High Sorcerer Andromath, en av de mest erfarna aktiva utövarna av arkana konster i de södra rikena, vill träffa magiker som är redo för större ansvar."},{t="En mästare utanför Dalaran",b="Dalarans magokrati krossades under det tredje kriget, och de överlevande trollkarlarna är upptagna med återuppbyggnaden. Utan enkel tillgång till Violet Citadels bibliotek förlitar sig Alliansen på erfarna ärkemagiker i Stormwind för att studera forntida hot och vägleda forskning om dunkla, förbjudna konster."}},faq={{q="Vem är High Sorcerer Andromath?",a="High Sorcerer Andromath är en erfaren magiker högst upp i Stormwinds Wizard's Sanctum. Långt från Dalaran räknar hans jämlikar honom till världens mäktigaste och mest kunniga besvärjare.",al={"vem är andromath","andromaths bakgrund","stormwinds high sorcerer"}},{q="Var hittar jag High Sorcerer Andromath?",a="Andromath finns högst upp i Wizard's Sanctum, det spiralformade tornet i Stormwinds Mage Quarter.",al={"andromaths plats","var finns andromath","hitta high sorcerer andromath"}},{q="Varför skickar Jennea Cannon mig till honom?",a="Jennea Cannon skickar lovande magiker som vuxit ur grundutbildningen till Andromath för mer avancerad vägledning och specialiserad, farlig forskning.",al={"varför tala med andromath","jennea cannons hänvisning"}},{q="Vad behöver Andromath hjälp med?",a="Andromath kallar på dugliga magiker för att undersöka mörka arkana hemligheter, bland annat för att hämta den farliga historiska skriften Ur's Treatise on Shadow Magic.",al={"andromaths uppdragskedja","vad vill andromath"}},{q="Varför sägs Dalaran vara ”avskärmat”?",a="Jenneas ord speglar hur tillbakadragna Kirin Tor har varit sedan det tredje kriget. Efter att Scourge och Burning Legion ödelade Dalaran vände sig de överlevande trollkarlarna inåt för att återuppbygga staden, och få engagerade sig i omvärlden.",al={"varför är dalaran avskärmat","dalarans tillstånd","vad hände med dalaran"}},{q="Är det här uppdraget bara för magiker?",a="Ja. Kallelsen hör till träningsvägen för alliansmagiker som utvecklar sina färdigheter.",al={"kan icke-magiker göra detta","uppdrag bara för magiker"}}},fx={["56d3f2e8"]={q="Varför skickar Jennea Cannon mig i stället för att sköta det själv?",a="Jennea Cannon är lärare vid Wizard's Sanctum, där hon vägleder magiker som utvecklar sina färdigheter i magins konst. High Sorcerer Andromath bad särskilt om att få tala med dig, en skicklig magiker på uppgång som är redo för mer avancerade uppgifter. Då slipper akademins lärare lämna sin undervisning.",al={"varför skicka mig","varför går inte jennea själv","varför vill andromath ha mig"}}},fp="23,174,20.290.0,24.287.0,31.184.0,41.100.0,42.142.0,35.152.1,42.227.0,33.87.0"}
P.entries["quest:194"] = {n="Raptor Mastery",s="I sitt expeditionsläger i norra Stranglethorn Vale utmanar Hemet Nesingwary resenärer att bevisa sin skicklighet i vildmarken. Den berömde jägaren kräver att du fäller tio Stranglethorn Raptors för att pröva om du har verklig jaktbegåvning.",h="I sitt expeditionsläger i norra Stranglethorn Vale utmanar Hemet Nesingwary resenärer att bevisa sin...",kw={"storviltsjägare","hemet nesingwary","raptor mastery","stranglethorn raptor","stranglethorn vale"},ang={["class:Hunter"]="För den som följer jägarens väg är Hemet Nesingwarys prövningar i vildmarken ett klassiskt prov på spårning och prickskytte."},sec={{t="Ett skicklighetsprov",b="När du anlänt till djungeln efter Welcome to the Jungle erbjuder Hemet Nesingwary sig att pröva din förmåga att spåra och jaga. I stället för att ge dig kartor eller vägbeskrivningar insisterar han på att det är halva provet att själv hitta Stranglethorn Raptors. Han utmanar dig att ge dig ut i snåren och fälla tio av de våldsamma bestarna."}},faq={{q="Vem ger dig den här jaktutmaningen?",a="Hemet Nesingwary, den berömde storviltsjägaren som håller till i expeditionslägret i norra Stranglethorn Vale, ger dig den här utmaningen.",al={"vem ger raptor mastery","uppdragsgivare för raptor mastery","hemet nesingwary raptors"}},{q="Vilka bestar ska du spåra upp?",a="Du ska spåra upp och fälla tio Stranglethorn Raptors som strövar omkring i djungelns vildmark.",al={"vilka raptors","vad ska jag döda för raptor mastery","målet med raptor mastery"}},{q="Varför vägrar Hemet berätta var rovfåglarna håller till?",a="Hemet anser att det är halva provet på att bli en sann storviltsjägare att spåra upp och hitta sitt byte, så han låter dig sköta hela sökandet själv.",al={"var finns raptors","varför ingen plats för raptors","raptors platser"}},{q="Vilket steg kommer före det här provet?",a="Det här jaktprovet följer på den första hälsningen i vildmarken, Welcome to the Jungle.",al={"förutsättning för raptor mastery","föregående uppdrag till raptor mastery","början på raptor mastery-kedjan"}}},fp="14,243,15.345.0,33.134.0,40.101.0,57.151.0,34.89.0"}
P.entries["quest:1940"] = {n="Pristine Spider Silk",s="I Stormwind skickar High Sorcerer Andromath blivande magiker i Alliansen till Duskwood för att hämta Pristine Spider Silk. De tar med sig åtta prover till Wynne Larson i Mage Quarter, där hon syr en dräkt åt en adept.",h="I Stormwind skickar High Sorcerer Andromath blivande magiker i Alliansen till Duskwood för att hämta Pristine...",kw={"andromath","carrion recluse","duskwood","larson clothiers","magikerd dräkter","pristine spider silk","wizard's sanctum","wynne larson"},ang={["class:Mage"]="Som magiker går du från lärling till adept genom den här riten. Varje magiker i Stormwind bär dräkter vävda av faror som de själva har mött.",["faction:Alliance"]="Som undersåte i Alliansen lämnar du Stormwinds fristad och beger dig till det farliga Duskwood för att samla en sällsynt resurs från trakten.",["profession:Tailoring"]="Som skräddare kan du se hur Wynne Larson förvandlar högklassiga fibrer från vilda monster till ett tyg som tar upp förtrollningar bättre än vanligt ylle eller linne."},sec={{t="Adeptens skrud",b="High Sorcerer Andromath markerar en magikers övergång från lärlingstid till adept med en skrud värdig en adept. I Wizard's Sanctum motsvaras den arkaniska behärskningen av de dräkter som magikerna bär. I stället för att köpa färdigsydda kläder måste magikern visa skicklighet och gott omdöme genom att hämta felfritt, obefläckat silke från farliga spindlar."},{t="Duskwoods vävstol",b="Giftiga carrion recluse-spindlar hemsöker Duskwoods dystra skogar, och deras silke säljs inte i vanliga stånd. Du samlar åtta förstklassiga prover och bär dem genom Stormwind till Larson Clothiers i Mage Quarter. Där använder Wynne Larson de fina trådarna för att väva en dräkt med arkanisk betydelse."}},faq={{q="Vem skickar ut magikerna på det här uppdraget?",a="High Sorcerer Andromath, som leder Wizard's Sanctum i Stormwind City, skickar ut magiker som har visat sin hängivenhet.",al={"vem ger pristine spider silk","uppdragsgivare för pristine spider silk","andromaths uppdrag"}},{q="Var hämtas silket?",a="Du samlar silket från carrion recluse-spindlar i Duskwoods hemsökta skogar och nätklädda gläntor.",al={"var får jag tag på pristine silk","spindelns plats","carrion recluse-spindelns plats"}},{q="Vem väver dräkten av silket?",a="Wynne Larson, skräddare hos Larson Clothiers i Stormwinds Mage Quarter, väver och syr dräkten.",al={"vem väver silket","wynne larson","larson clothiers"}},{q="Varför använder magiker spindelsilke till kläder?",a="Pristine Spider Silk är naturligt tåligt och fint vävt, vilket ger ett lätt tyg som kan bära subtila förtrollningar utan att tynga ner en magiker.",al={"varför spindelsilke","magiska dräkter av spindelsilke"}},{q="Vad händer efter att silket har levererats?",a="När Wynne har granskat silket och arbetat vid sin vävstol ger hon magikern det färdiga Astral Knot Garment.",al={"nästa uppdrag efter pristine spider silk","vad händer sedan"}},{q="Duger vilket spindelsilke som helst från Duskwood?",a="Nej. Larson Clothiers behöver noggrant insamlade, felfria prover från carrion recluse-spindlar för sina subtila förtrollningar. Grovare nät duger inte.",al={"kan jag använda vanligt spindelsilke","pristine silk jämfört med vanligt silke"}}},fx={a495a13a={q="Varför skickar High Sorcerer Andromath dig för att samla silke?",a="High Sorcerer Andromath ser ditt orubbliga engagemang för magins konst och tycker att din klädsel bör spegla dina växande färdigheter. Wizard's Sanctum ger dig inte en färdig mantel. I stället förväntas du förtjäna den genom att trotsa farorna i Duskwood och samla de sällsynta material som behövs för en skicklig magikers dräkt.",al={"varför vill andromath ha silke","andromaths motiv","varför ger andromath det här uppdraget"}},["8d44c073"]={q="Vilka varelser måste du jaga för att få silket?",a="Du skickas för att jaga carrion recluse-spindlarna som lurar i Duskwoods mörka skogar. De giftiga spindeldjuren spinner en ovanligt slitstark tråd med stark resonans, men bara deras finaste, felfria trådar passar till att väva en förtrollad dräkt.",al={"vem ska jag jaga efter pristine spider silk","vilka spindlar ger silket","carrion recluse i duskwood"}}},fp="20,202,22.336.0,20.304.0,35.135.0,28.102.0,34.102.0,42.158.0,37.113.0,44.141.0"}
P.entries["quest:1941"] = {n="Manaweave Robe",s="I Stormwind presenterar Wynne Larson Manaweave Robe som en stolt uppvisning av familjens butik. Hon har vävt det förtrollade plagget av fina material för en beställning som nu är färdig.",h="I Stormwind presenterar Wynne Larson Manaweave Robe som en stolt uppvisning av familjens butik.",kw={"lärlingskåpa","tyghandlare","larson clothiers","mage quarter","manaweave robe","stormwind","skräddare","wynne larson"},ang={["class:Mage"]="Som magiker under utbildning i Stormwinds torn bär du en skräddarsydd Manaweave Robe som tecken på att du gått vidare till seriös fältforskning och självständig magiutövning.",["faction:Alliance"]="När du utrustar en lovande kämpe genom en lokal butik i huvudstaden hjälper du till att sprida Stormwinds anseende och självförsörjning i oroliga områden.",["profession:Tailoring"]="Wynne Larsons arbete visar den höga standarden på mänskligt skrädderi, där världsliga material vävs samman för att tämja och tygla flyktig mystisk kraft."},sec={{t="Larson Clothiers",b="Larson Clothiers betjänar magiker i Stormwinds Mage Quarter med plagg gjorda för att leda flyktiga energier. Fina magiska kåpor kräver sällsynta material, noggrant nålarbete och trådarbete som håller genom mystisk resonans. Wynne Larson är stolt över varje plagg som lämnar hennes butik, där varje kåpa som bärs ut i fältet för Larsonnamnet vidare."},{t="Vävd trolldom",b="Manaweave Robe erbjuder komfort, rörlighet och praktisk tålighet under färder genom omstridda länder. När de nödvändiga komponenterna har levererats syr Wynne Larson själv den sista sömmen och presenterar det färdiga plagget som ett fint exempel på Larsonskräddarkonst, avsett att väcka beundran och sprida butikens namn över kungariket."}},faq={{q="Vem tillverkar Manaweave Robe?",a="Wynne Larson tillverkar Manaweave Robe på Larson Clothiers i Stormwind Citys Mage Quarter.",al={"vem tillverkar manaweave robe","wynne larsons kåpa","larson clothiers"}},{q="Varför vill Wynne Larson att du ska bära kåpan med stolthet?",a="Wynne anser att kåpan är ett av hennes främsta verk och ber äventyrare sprida ordet om Larson Clothiers när andra beundrar hantverket. Deras beröm blir levande reklam för hennes butik.",al={"varför berätta om larson","larson reklam","wynnes dialog"}},{q="Var ligger Larson Clothiers?",a="Larson Clothiers ligger i Stormwind Citys Mage Quarter, nära akademierna och helgedomarna där Alliansens magiker samlas.",al={"larsons butik läge","var finns wynne larson","skräddarbutik i mage quarter"}},{q="Vad är Manaweave Robe för slags plagg?",a="Manaweave Robe är ett förtrollat tygplagg för magiutövare, skräddarsytt för att leda mystiska energier och vara praktiskt på farliga färder.",al={"manaweave robe bakgrund","vad är manaweave robe","vad gör kåpan"}},{q="Är detta en del av en längre uppdragskedja?",a="Ja. Det avslutar en magikerkedja som Jennea Cannon inledde. Efter att ha undersökt en manaspricka vid Blue Recluse samlar du linne och laddade sprickädelstenar åt Wynne Larson, så att hon kan tillverka din kåpa.",al={"manaweave uppdragskedja","kåpans uppdragskedja","uppdragskedjans slut"}},{q="Vilken fraktion kan ta sig an det här uppdraget?",a="Endast medlemmar i Alliansen kan ta sig an det. Wynne Larson arbetar helt inom Stormwind, Alliansens huvudstad.",al={"alliansen eller horden och kåpan","kan horden få manaweave robe","fraktionskrav"}}},fp="14,194,16.354.0,13.339.0,30.94.0,59.203.0,34.127.0,41.156.0,35.182.0,38.114.0"}
P.entries["quest:1942"] = {n="Astral Knot Garment",s="Wynne Larson väver fin spindelsilke till ett plagg i Stormwind City. En äventyrare kommer med sällsynt silke från vildmarken, som hon syr till ett magiskt tyg för farliga resor och förnäma tillställningar.",h="Wynne Larson väver fin spindelsilke till ett plagg i Stormwind City.",kw={"astral knot garment","tyg rustning","mage quarter","pristine spider silk","silkesrock","stormwind","skrädderi","wynne larson"},ang={["class:Mage"]="Som magiker ser du Stormwinds arkana värdighet i det här plagget, med praktiska förtrollningar för resor bortom rikets befästa murar.",["faction:Alliance"]="Som Alliansens förkämpe hittar du hantverk från Stormwind som passar lika bra i kungliga salar som vid farliga frontlinjer.",["profession:Tailoring"]="Wynne Larsons arbete visar hur Pristine Spider Silk kan förädlas till storslagen modekonst."},sec={{t="En vävares kvickhet",b="I Mage Quarter i Stormwind betjänar skräddare magiska eliter och besökande adelsmän. Wynne Larson är känd för att väva Pristine Spider Silk till tåliga, förtrollade plagg. Hennes lekfulla humor märks när hon skämtar om att spara några dyrbara trådar till sin egen garderob innan hon lämnar över sitt färdiga arbete."},{t="Mångsidig elegans",b="Trollkunniga som bär tyg uppskattar Astral Knot Garment för dess slitstyrka och elegans. Silket kommer från farliga spindlar, och väven är gjord för att tåla strid samtidigt som den behåller det välklädda utseende som förväntas vid högtidliga banketter i Stormwind Keep."}},faq={{q="Vad är Astral Knot Garment?",a="Wynne Larson tillverkar Astral Knot Garment i Stormwind City av Pristine Spider Silk. Plagget är gjort för tygklädda utövare som ger sig in i strid eller deltar i förnäma tillställningar.",al={"vad är astral knot garment","astral knot-kåpa","astral knot-skrud"}},{q="Vem tillverkar Astral Knot Garment?",a="Wynne Larson, en skräddare i Mage Quarter i Stormwind, tillverkar plagget när hon får de exotiska material som behövs.",al={"vem tillverkar astral knot","wynne larson-uppdrag","astral knot-skräddare"}},{q="Vilka material behövs för att färdigställa plagget?",a="Plagget kräver Pristine Spider Silk från dödliga spindlar i världens vilda trakter. Skrädderiet bevarar silkets naturliga styrka och förmåga att förtrollas.",al={"material till astral knot","spindelsilke som behövs","hur tillverkas den"}},{q="Varför skämtar Wynne Larson om att behålla överblivet silke?",a="Wynne skämtar om att göra plagget kort så att hon kan behålla några trådar av det sällsynta, eftertraktade spindelsilket. Hon lämnar över det färdiga arbetet i sin helhet.",al={"stal hon mitt silke","wynne larson-skämt","kort kåpa"}},{q="Var i Stormwind sker skrädderiet?",a="Skrädderiet sker i Mage Quarter i Stormwind, ett distrikt med lärda, arkanister och skräddare som är skickliga på förtrollade textilier.",al={"var finns wynne larson","astral knot-plats","var lämnar jag in astral knot"}},{q="Vem brukar bära Astral Knot Garment?",a="Magiker i Alliansen föredrar Astral Knot Garment för dess lätta, skyddande väv och värdiga utseende.",al={"vem använder astral knot","vilken klass är den till för","vem bär den"}}},fx={["96918ee1"]={q="Varför tillverkar Wynne Larson Astral Knot Garment?",a="Wynne Larson är en skicklig skräddare i Stormwind som går med på att väva dräkten som kronan på verket för dina ansträngningar. Hon har skickat dig över farliga marker för att samla sällsynta material som Pristine Spider Silk. Hon är stolt över att skapa utsökta plagg åt magiker och förena praktiskt skydd med förfinad elegans.",al={"varför gör wynne larson dräkten","wynne larsons motiv för astral knot garment","varför tillverkar wynne manteln"}}},fp="19,221,14.308.0,18.249.0,32.180.0,35.110.0,53.172.0,56.144.0,50.134.0,44.102.0"}
P.entries["quest:1943"] = {n="Speak with Deino",s="I Orgrimmar kallar Deino lovande magiker från Horde till att utveckla sina färdigheter. Trollmagikern arbetar i Valley of Spirits och söker en skicklig adept för ett viktigt uppdrag. Hennes kallelse öppnar vägen till djupare studier och uppgifter runt om i Kalimdor.",h="I Orgrimmar kallar Deino lovande magiker från Horde till att utveckla sina färdigheter.",kw={"anastasia hartwell","darkbriar lodge","deino","magikeruppdrag","orgrimmar","quithas","valley of spirits","waters of xavian"},ang={["class:Mage"]="Som magiker fördjupar du dina magistudier och träffar erfarna besvärjare i Orgrimmar.",["faction:Horde"]="Som medlem av Horde följer du en kallelse som knyter samman tränare i Lordaeron och Durotar med Orgrimmars magiska ledare.",["race:Troll"]="Som troll får du se den fokuserade magiska disciplin som utövas av några få utvalda bland Darkspear Trolls."},sec={{t="En kallelse till Orgrimmar",b="Magiker från Horde finslipar sina magiska förmågor under instruktörers ledning. När en elev är redo för svårare uppgifter visar mentorer som Anastasia Hartwell i Undercity vägen till Orgrimmar. I stadens trollkvarter väntar specialkunskaper och farliga uppdrag."},{t="Valley of Spirits och Darkbriar Lodge",b="Deino bor i Darkbriar Lodge i Orgrimmars Valley of Spirits. Bland Darkspear Trolls studerar få magi, jämfört med de många häxdoktorerna och prästerna, vilket gör Deino till en auktoritet i huvudstaden. Hennes arbete gagnar magiker från Horde även utanför närområdet, och hon söker ambitiösa besvärjare som är villiga att möta faror långt hemifrån."}},faq={{q="Vem skickar dig för att tala med Deino?",a="Magikertränare som Anastasia Hartwell i Undercitys Magic Quarter skickar blivande magiker till Orgrimmar när deras färdigheter räcker till.",al={"uppdragsgivare","vem startar det här","var får jag speak with deino"}},{q="Var hittar jag Deino?",a="Du hittar Deino inne i Darkbriar Lodge, i Valley of Spirits på västra sidan av Orgrimmar.",al={"deinos plats","var är deino","darkbriar lodges plats"}},{q="Varför behöver Deino hjälp?",a="Deino leder forskning och arbete som är viktigt för magiker från Horde. Hon skickar skickliga besvärjare till farliga länder för att hitta sällsynta magiska resurser.",al={"varför deino behöver hjälp","vad vill deino"}},{q="Vad händer när jag rapporterar till Deino?",a="När du rapporterar till Deino förklarar hon sitt arbete och skickar dig för att samla in Waters of Xavian.",al={"nästa uppdrag","vad kommer efter","fortsättningsuppdrag"}},{q="Är det här uppdraget tillgängligt för alla klasser?",a="Nej. Endast magiker från Horde får Deinos kallelse som en del av sin klassutbildning.",al={"är det här bara för magiker","kan häxmästare göra det här","klassbegränsning"}},{q="Är trollmagiker vanliga i Horde?",a="Bland Darkspear Trolls är magi mindre vanlig än schamanism, voodoo eller tjänst åt loa. Deino visar att vissa troll har bemästrat de formella studierna av magiska krafter.",al={"troll som använder magi","lore om darkspear-magiker"}}},fx={["2e9f17ef"]={q="Varför skickar magilärarna dig till Deino?",a="När du blir skickligare i magins konst inser dina mentorer i huvudstäderna att djupare mysterier väntar bortom den vanliga träningen. Trollmagikern Deino i Orgrimmar ansvarar för avancerade uppdrag som är viktiga för magikernas gemensamma samfund i Horden. Lärare som Anastasia Hartwell i Undercity hänvisar lovande magiker till henne, så att du kan bidra till sådant som är viktigt för ert gemensamma yrke.",al={"varför skicka mig till deino","hartwells motiv för uppdraget","varför skickar anastasia hartwell mig"}}},fp="16,223,22.265.0,41.332.0,34.134.0,23.96.0,31.142.0,38.93.0,39.77.0,36.175.0"}
P.entries["quest:1944"] = {n="Waters of Xavian",s="Waters of Xavian är ett magiuppdrag för Horde som Deino erbjuder i Orgrimmar. För att utforska uråldriga alviska hemligheter skickar hon sin lärling till ruinerna av Xavian i Ashenvale för att hämta ett prov från dess högsta vattenfall.",h="Waters of Xavian är ett magiuppdrag för Horde som Deino erbjuder i Orgrimmar.",kw={"ashenvale","deino","flaska","magiuppdrag","orgrimmar","satyr","splintertree","waters of xavian","xavian"},ang={["class:Mage"]="Det här uppdraget är en särskild studierit för Horde-magiker och prövar deras förmåga att ge sig ut i fientlig vildmark för att hämta otämjda arkaniska reagenser.",["faction:Horde"]="Splintertree Post fungerar som Hordes närmaste bas i östra Ashenvale för färder genom de satyrinfekterade vildmarkerna runt Xavian."},sec={{t="En magikers nyfikenhet",b="I Valley of Spirits mörka skrymslen söker trollmagikern Deino efter kvarvarande källor till uråldrig arkansk energi runt om i Kalimdor. Hennes blick vänds mot Xavian, en uråldrig Night Elf-stad gömd djupt inne i Ashenvales östra trädkronor. Enligt viskande legender bland lärda var staden fylld av magisk kunskap före Sunderingen, och dess vatten sägs fortfarande ha kraftfulla arkaniska egenskaper som nutida magiker längtar efter att undersöka."},{t="Ruinerna av Xavian",b="Att nå vattnets källa är inget enkelt ärende. Xavian tillhör inte längre fredliga alviska vise; staden har förfallit till ruiner och översvämmas nu av vilda, fördärvade satyrer som häftigt försvarar sitt område mot främlingar. Magiker som vill gräva djupare måste ta sig förbi Satyrnaar och genom farliga vattenvägar, undvika både strövande bestar och demoniska väktare och fylla Deino's Flask vid foten av stadens höga vattenfall."}},faq={{q="Vem är Deino?",a="Deino är en trollmagiker och magitränare som finns i Valley of Spirits i Orgrimmar. Hon undervisar Horde-magiker och undersöker reliker från Kalimdors uråldriga magi.",al={"vem ger waters of xavian","deino orgrimmar"}},{q="Var ligger Xavian?",a="Xavian är en uråldrig ruinstad i nordöstra Ashenvale, norr om Splintertree Post och strax nordväst om satyrernas fäste Satyrnaar.",al={"xavian plats","var ligger xavian","hitta xavian"}},{q="Varför vill Deino ha det här vattnet?",a="Enligt lärda skrifter rymde Xavian en gång enorma mängder magisk kunskap, och dess vatten tros fortfarande bära på arkanisk kraft. Deino vill ha ett färskt prov från vattenfallets källa för att analysera dess egenskaper.",al={"varför hämta vatten från xavian","syftet med xavian-vattnet"}},{q="Vilka faror vaktar ruinerna av Xavian?",a="Ruinerna kryllar av satyrer, demoniska och fördärvade varelser som avskyr inkräktare och aggressivt försvarar sitt område mot nyfikna magiker.",al={"xavians fiender","vem kontrollerar xavian"}},{q="Var samlas vattenprovet in?",a="Provet måste samlas i Deino's Flask från dammen precis nedanför det högsta vattenfallet i ruinerna av Xavian.",al={"vattenfallets plats","var fylla flaskan","xavians vattenfall"}},{q="Vad händer när man har återlämnat provet till Deino?",a="Nöjd med vattenprovet skickar Deino magikern vidare till nästa studieetapp, som handlar om dryaderna i Ashenvale, med uppdraget Laughing Sisters.",al={"fortsättning på waters of xavian","nästa uppdrag efter waters of xavian"}}},fx={["6a4223ea"]={q="Vad ska Xavian Water Sample användas till?",a="Den uråldriga staden Xavian är legendarisk bland lärda för sin bortglömda kunskap, och dess vatten sägs rymma stora magiska krafter. Deino vill ha ett oblandat prov som hämtas direkt vid foten av stadens högsta vattenfall. Där kan hon studera vattnets dolda magiska egenskaper i Orgrimmar.",al={"vad gör xavian water","varför samla xavian water","xavian water samples användning"}}},fp="16,206,18.365.0,19.301.0,13.145.0,24.105.0,31.190.0,39.119.0,44.109.0,52.78.1"}
P.entries["quest:1945"] = {n="Laughing Sisters",s="Laughing Sisters är ett Horde-uppdrag där magiker beger sig in i hjärtat av Ashenvale för att samla förtrollade hårlockar från vilda dryader. Håret ska till Kil'hala, en erfaren trollskräddare vid The Crossroads, som väver det till en kraftfull magikerdräkt. Jakten på Cenarius döttrar visar den obevekliga friktionen mellan Hordes magiker och den uråldriga skogens inhemska försvarare.",h="Laughing Sisters är ett Horde-uppdrag där magiker beger sig in i hjärtat av Ashenvale för att samla...",kw={"ashenvale","the crossroads","deino","dryad","hår","kil'hala","laughing sisters","raynewood","warlock-dräkt"},ang={["class:Mage"]="Den här övergångsriten lär blivande magiker att även Ashenvales heliga skogsandar kan skördas för material till arkan hantverk.",["faction:Horde"]="När magiker fäller Ashenvales dryader skärps konflikten mellan Hordes expansion och de heliga skogsväktare som lyder under nattalverna.",["profession:Tailoring"]="Uppdraget lyfter fram den sällsynta konsten att väva in levande magiska fibrer i tygpansar och visar den avancerade teknik som Kil'hala använder vid The Crossroads."},sec={{t="Att väva det arkana",b="Efter att ha hjälpt till att säkra vatten från Xavian får blivande magiker av Deino i Orgrimmar i uppdrag att hjälpa till att tillverka sina egna förtrollade kläder. Den här sortens arkana skrädderi kräver material som genomsyrats av rå magisk essens. Dryadernas lockar, naturligt fyllda av skogens uråldriga livskraft, har de egenskaper som krävs för att väva intrikata magiska plagg som kan skydda och stärka en magikers krafter."},{t="På jakt i Raynewood",b="För att samla in lockarna måste magiker bege sig söderut mot Raynewood Retreat i Ashenvale. De skrattande systrarna, smidiga skogsdryader i förbund med nattalverna, försvarar dessa lundar våldsamt mot både inkräktande skogshuggare och främlingar. Eftersom dessa skogsväsen aldrig frivilligt skulle ge sitt hår till Hordes magiker, sker skörden oundvikligen till priset av blod under de uråldriga trädens kronor."},{t="Vävarens rätt",b="När lockarna har samlats in bärs de söderut över gränsen till den dammiga bosättningen The Crossroads i The Barrens. Där tar trollskräddaren Kil'hala emot tribut utan ånger. Med en gnutta ironi erkänner Kil'hala att skogsvarelserna gått förlorade, men slösar ingen tid på att använda de förtrollade hårstråna praktiskt och vet att makt inom Horden ofta kräver orubblig beslutsamhet."}},faq={{q="Vem ger uppdraget att jaga Laughing Sisters?",a="Deino, en trollmagiker i Darkbriar Lodge i Orgrimmar, skickar magiker på uppdraget som belöning och förberedelse inför tillverkningen av deras klassdräkter.",al={"vem ger uppdraget laughing sisters","uppdragsgivare för laughing sisters","deino-uppdrag"}},{q="Vad är Laughing Sisters?",a="Laughing Sisters är dryader, döttrar till halvguden Cenarius. De har nattalvskvinnors överkroppar och fawnars underkroppar och skyddar Ashenvales skogar och heliga gläntor.",al={"vad är en laughing sister","laughing sister dryad","är laughing sisters dryader"}},{q="Var hittar man Laughing Sisters?",a="De strövar omkring i de skogklädda områdena nära Raynewood Retreat och Laughing Sister-gläntan i centrala Ashenvale, inte långt från handelsvägen.",al={"laughing sisters plats","var finns laughing sisters","var hittar man laughing sisters"}},{q="Varför behöver Kil'hala dryadhår?",a="Dryadhår är genomsyrat av naturlig förtrollning och passar därför utmärkt som tråd när Kil'hala väver specialiserade, magiskt laddade dräkter för arkan magi.",al={"varför dryadhår","varför hår från laughing sisters","vad används håret till"}},{q="Var lämnar jag håret när jag har samlat in det?",a="Lämna håret till Kil'hala, en skicklig skräddare i den livliga utposten The Crossroads i The Barrens.",al={"var finns kil'hala","lämna in laughing sisters","skräddare på the crossroads warlock"}},{q="Vad händer när Kil'hala har tagit emot håret?",a="När Kil'hala har tagit emot håret arbetar han en kort stund med materialet och erbjuder sedan följduppdraget Nether-lace Garment för att färdigställa dräkten.",al={"nästa uppdrag efter laughing sisters","efter laughing sisters","nether lace garment fortsättningsuppdrag"}}},fx={["6db1d5c5"]={q="Varför skickar Deino dig för att jaga Laughing Sisters?",a="Deino belönar din fortsatta tjänst åt Hordens magiker genom att ordna så att särskilda mantlar tillverkas åt dig. I stället för att bara ge dig dem kräver hon att du själv samlar in de exotiska magiska ingredienserna. Därför skickar hon dig djupt in i Ashenvale för att ta dryadhår från skogens försvarare.",al={"varför vill deino ha laughing sisters hår","deinos motiv för laughing sisters","varför samla hår från laughing sisters"}}},fp="16,223,18.319.0,18.297.0,24.309.0,51.117.0,30.188.0,40.127.0,34.161.0,49.69.0,43.89.0"}
P.entries["quest:1946"] = {n="Nether-lace Garment",s="Vid The Crossroads väver Kil'hala dryadhår till förtrollat tyg åt magiker. Plagget markerar slutet på hans specialiserade arbete i The Barrens.",h="Vid The Crossroads väver Kil'hala dryadhår till förtrollat tyg åt magiker.",kw={"ashenvale","the barrens","the crossroads","deino","kil'hala","laughing sisters","magiker","nether-lace"},ang={["class:Mage"]="Som magiker får du ett plagg som förenar vildmarksprövningar i Ashenvale med Kil'halas hantverk under Deinos vägledning.",["faction:Horde"]="Som medlem av Horde hjälper du till att utrusta dess magiker med material från Kalimdors heliga skogar, som en del av den pågående kampen mellan Horde och Ashenvales skogsförsvarare.",["profession:Tailoring"]="Som skräddare kan du se hur exotiska ingredienser som dryadhår blir till tyg med ett inneboende magiskt skydd."},sec={{t="Vävning av Nether-Lace",b="Vid The Crossroads i The Barrens väver Kil'hala nether-lace av de skrattande systrarnas lockar. Dryaderna lever i Ashenvale, och deras hår samlas in för detta arbete. Kil'hala binder skogsförtrollningen i dessa sällsynta, magiskt resonanta lockar till ett bekvämt och slitstarkt tyg."},{t="Tjänster åt Orgrimmar",b="Kil'hala vill ha mer än väl utfört arbete från sitt hantverk. Han hoppas vinna gunst hos Deino, en respekterad trollmagiker som bor i Orgrimmars Valley of Spirits. Genom att skapa utsökta kläder åt blivande magiker hoppas han vinna och behålla Deinos välvilja."}},faq={{q="Vad är nether-lace?",a="Nether-lace är ett förtrollat tyg som Kil'hala väver av de skrattande systrarnas hår. Tyget är tåligt och bär på deras skogsförtrollning.",al={"nether-lace-tyg","vad är nether-lace garment"}},{q="Vem tillverkar Nether-lace Garment?",a="Kil'hala tillverkar plagget vid sin arbetsplats i The Crossroads i The Barrens, när han väl har fått tag på det dryadhår från Ashenvale som behövs.",al={"vem tillverkar nether-lace","kil'hala nether-lace"}},{q="Varför nämner Kil'hala Deino?",a="Deino är en inflytelserik trollmagikertränare i Orgrimmars Valley of Spirits. Kil'hala hoppas behålla hennes gunst och tror att din belåtenhet med hans skrädderi kommer att göra gott intryck på henne.",al={"vem är deino","varför nämns deino"}},{q="Varifrån kom materialet till plagget?",a="Plaggets främsta material är hår som samlats in från de svårfångade skrattande systrarna, dryader som finns i Ashenvales skogar.",al={"nether-lace-material","tyg av dryadhår"}},{q="Vem är plagget gjort för?",a="Plagget är främst gjort för magiker, särskilt magiker under utbildning som behöver klädnader som kanaliserar arkana energier utan att hindra deras rörelser.",al={"vem använder nether-lace garment","nether-lace-klass"}},{q="Var finns Kil'hala?",a="Kil'hala bor vid The Crossroads, den centrala vägkorsningsbosättningen i hjärtat av The Barrens.",al={"kil'halas plats","var finns kil'hala"}}},fp="19,159,23.294.0,20.253.0,20.151.0,35.126.0,32.186.0,50.120.0,29.146.0,26.96.0"}
P.entries["quest:195"] = {n="Raptor Mastery",s="Djupt inne i Stranglethorn Vales djungel utmanar Hemet Nesingwary jägare att vässa sina färdigheter mot farligare villebråd. Efter en tidigare raptorjakt skickar han äventyrare att spåra upp och fälla tio Lashtail Raptors.",h="Djupt inne i Stranglethorn Vales djungel utmanar Hemet Nesingwary jägare att vässa sina färdigheter mot...",kw={"grom'gol base camp","hemet nesingwary","jakt","lashtail raptor","raptor mastery","stranglethorn vale"},ang={["class:Hunter"]="För spårare och rovdjursjägare prövar Hemet Nesingwarys utmaningar grundläggande jaktdisciplin mot de dödligare rovdjur som strövar omkring i Stranglethorn Vale."},sec={{t="En större utmaning",b="Efter att ha visat prov på grundläggande jaktförmåga väntar sig Hemet Nesingwary mer än att jägarna slår dank vid lägerelden. För att visa äkta fokus och skicklighet skickas jägarna in i den täta djungelvegetationen strax norr om Grom'gol Base Camp för att spåra upp och döda tio vildsinta Lashtail Raptors."},{t="Troféer vid härden",b="När jägarna återvänder med framgång från djungeln får de Nesingwarys varma uppskattning. Den erfarne jägaren anser att sådana farliga rovdjur är ett värdigt byte, väl lämpat för att bli troféer ovanför härden, och förbereder äventyraren på ännu större utmaningar."}},faq={{q="Vem ger den här jaktutmaningen?",a="Den berömde storviltsjägaren Hemet Nesingwary ger utmaningen från sitt expeditionsläger i norra Stranglethorn Vale.",al={"vem startar raptor mastery 2","uppdragsgivare för raptor mastery","var får man raptor mastery"}},{q="Vilket villebråd ska du jaga?",a="Du ska spåra upp och döda tio Lashtail Raptors i djungeln.",al={"vilka raptorer ska dödas","vilket raptoruppdrag","mål: lashtail raptor"}},{q="Var finns Lashtail Raptors?",a="Lashtail Raptors strövar bland den vilda växtligheten i norra Stranglethorn Vale, särskilt norr om Grom'gol Base Camp.",al={"var finns lashtail raptors","lashtail raptors plats","var hittar man lashtail raptors"}},{q="Var passar den här jakten in bland Nesingwarys prövningar?",a="Det här är den andra prövningen i raptorserien. Den följer på den inledande jakten Raptor Mastery och leder vidare till en tredje del av utmaningen.",al={"vad kommer före den här raptorjakten","raptor mastery fortsättning","raptoruppdragskedja"}}},fp="14,234,19.292.0,23.251.1,34.120.0,40.74.0,37.113.0,50.141.0"}
P.entries["quest:1950"] = {n="Get the Scoop",s="Magus Tirth har låst in en viktig magibok i sin magiskt förseglade kassaskrin, men minns inte längre öppningsfrasen. För att hämta boken måste du hitta hans försvunna lärling någonstans kring racerbanan i The Shimmering Flats och få honom att säga de bortglömda orden.",h="Magus Tirth har låst in en viktig magibok i sin magiskt förseglade kassaskrin, men minns inte längre...",kw={"get the scoop","johnson","magus tirth","mirage raceway","the shimmering flats","kassaskrin","thousand needles","stavuppdrag"},ang={["class:Mage"]="Mötet med Tirth ger en humoristisk men varnande inblick i farorna med förvandlingsförbannelser och den tankspriddhet som kan drabba mäktiga lärda."},sec={{t="En magus och hans minne",b="Magus Tirth är en excentrisk magiker som bor på den spruckna saltbädden i The Shimmering Flats i Thousand Needles. Han besitter den esoteriska kunskap och de böcker som blivande magiker ivrigt söker, men det krävs tålamod att ha med honom att göra. Tirth förlitar sig mycket på en assistent som sköter vardagliga detaljer, däribland de talade lösenord som skyddar hans magiska förråd. När magiker får i uppdrag att hämta en kraftfull bok upptäcker de snabbt att Tirth har låst in den bakom magiska ord som han helt har glömt bort."},{t="Fjäderfäspel",b="Att spåra upp Tirths lärling, Johnson, handlar inte bara om att ströva omkring i Mirage Raceways hagar. När man frågar runt bland de vättar och tomtar som driver banan får man veta att Johnson råkat ut för den klassiska yrkesrisken för en oberäknelig trollkarls tjänare: förvandling. Hans mästare förbannade honom och gjorde honom till en vanlig kyckling. Johnson vandrar omkring på saltstäppen och kan inte tala förrän en förbipasserande resenär kommer nära och skingrar den magiska dimman tillräckligt länge för att han ska kunna kackla fram det bortglömda lösenordet."}},faq={{q="Vem är Magus Tirth?",a="Magus Tirth är en tillbakadragen mänsklig magiker som håller till nära Mirage Raceway i The Shimmering Flats i Thousand Needles. Han besitter avancerad magisk kunskap som magiker söker för att finslipa sitt hantverk.",al={"tirths bakgrund","vem är magus tirth","tirth shimmer flats"}},{q="Varför behöver Tirth lösenordet till sin egen kista?",a="Tirth låste magiskt sitt kassaskrin med en talad fras och litade på att hans assistent skulle minnas vardagliga detaljer som lösenord. Typiskt för hans tankspridda natur glömde han orden så snart hans lärling försvann.",al={"varför glömde tirth","lösenord till tirths kassaskrin"}},{q="Vart tog lärlingen vägen?",a="Johnson flydde inte långt. Han vandrar nära racerbanan öster om Tirths läger, men det är svårt att hitta honom eftersom Tirth förvandlade honom till en kyckling.",al={"hitta tirths assistent","var är lärlingen johnson","johnsons plats"}},{q="Varför förvandlades lärlingen till en kyckling?",a="Tirth lade en förbannelse på Johnson och glömde sedan att han hade gjort det. När Tirth får veta vad som hänt hans assistent antar han vagt att lärlingen förtjänade det för att vara en otacksam elev.",al={"varför blev johnson en kyckling","tirth förvandlade lärlingen"}},{q="Vad finns i Tirths kassaskrin?",a="Den magiskt förseglade kistan innehåller en bok med ritualer och instruktioner som är viktiga för en magikers fortsatta utbildning och magiska redskap.",al={"innehållet i tirths kassaskrin","vilken bok finns i kistan"}},{q="Vem kan utföra uppdraget?",a="Det här är ett ärende inom ett särskilt prov som enbart är avsett för magiker som söker specialiserad undervisning och material för att skapa en kraftfull stav.",al={"kan icke-magiker göra get the scoop","är det här uppdraget bara för magiker"}}},fx={["25c94f6f"]={q="Varför skickar Magus Tirth dig i stället för att själv leta efter lärlingen?",a="Magus Tirth tänker inte själv genomsöka The Shimmering Flats när det är du som ber om hans kunskap. Du kom för att få hans sällsynta magiska bok. Eftersom han inte kan minnas den muntliga besvärjelsen som öppnar hans magiskt förseglade kassaskrin utan sin försvunna assistent, får du hjälpa honom i utbyte mot hans hjälp.",al={"varför skicka mig","varför hittar inte tirth johnson","varför måste jag hitta lärlingen"}}},fp="13,283,22.549.0,9.526.1,19.201.0,48.218.0,28.167.1,45.186.1,33.143.0,28.138.0"}
P.entries["quest:1959"] = {n="Report to Anastasia",s="Report to Anastasia är en kallelse till unga magiker i Horde i Kalimdor och Eastern Kingdoms. Anastasia Hartwell, en framstående arkanist i Undercitys Magic Quarter, har upptäckt en okänd magisk störning i staden och behöver skickliga besvärjare för att undersöka den.",h="Report to Anastasia är en kallelse till unga magiker i Horde i Kalimdor och Eastern Kingdoms.",kw={"anastasia hartwell","cain firesong","investigate the alchemist shop","magiker","magic quarter","report to anastasia","thurston xane","un'thuwa","undercity","uthel'nay"},ang={["class:Mage"]="Det här uppdraget är en viktig milstolpe för magiker i Horde. Det för ut utövarna från regionala träningsplatser och introducerar dem till de djupare mysterierna — och farorna — inom det arkana som pyr under Lordaerons ruiner.",["faction:Horde"]="Kallelsen visar på samarbetet mellan Forsaken och resten av Horde. Magiska talanger från alla medlemsfolk används för att skydda deras gemensamma intressen.",["race:Undead"]="Forsaken-magiker kallas hem till Undercitys Magic Quarter för att hjälpa till att skydda sitt unga rike mot osedda hot från det arkana innanför de egna murarna."},sec={{t="En kallelse till det arkana",b="Ryktet sprids snabbt bland Hordes besvärjare. Oavsett om de studerar på Thunder Bluffs höjder, i Durotars dammiga hetta eller bland Lordaerons ruiner får magiker med tillräcklig talang ett tydligt direktiv. Undercitys arkana utövare har känt en oförklarlig störning som böljar genom deras domäner, och de behöver hjälp på plats."},{t="Magikern i Undercity",b="Anastasia Hartwell övervakar det arkana från Undercitys Magic Quarter. När du kommer fram bekräftar hon de oroande nyheterna: avvikande energier har registrerats i den underjordiska metropolen. Eftersom magins natur fortfarande är helt okänd — den har varken visat sig vara ofarlig eller öppet fientlig — behöver hon en skicklig magiker som diskret undersöker dess källa, med början i stadens Apothecarium."}},faq={{q="Vem är Anastasia Hartwell?",a="Anastasia Hartwell är en Forsaken-magiker och arkana mentor som tjänstgör i Undercitys Magic Quarter. Hon vägleder unga utövare och håller noga uppsikt över avvikelser i det arkana som uppstår i Forsakens huvudstad.",al={"anastasia hartwell bakgrund","vem är anastasia","hartwell undercity"}},{q="Var finns Anastasia Hartwell?",a="Hon bor i Undercitys Magic Quarter, i den underjordiska stadens norra del. Du hittar henne bland de andra besvärjelselärarna och arkana forskarna.",al={"var finns anastasia","hartwells plats","anastasia undercity karta"}},{q="Varför kallas magiker från Thunder Bluff eller The Barrens till Undercity?",a="Forsaken utbildar sina egna specialister på det arkana, men ovanliga magiska avvikelser hotar hela Hordes närvaro i Lordaeron. Mentorer i Kalimdor skickar sina lovande elever till Undercity för att hjälpa till och få praktisk erfarenhet av komplexa magiska fenomen.",al={"varför resa till undercity","varför rapportera till anastasia","magikeruppdrag thunder bluff"}},{q="Vilken sorts störning undersöker Anastasia?",a="Magikerna upptäckte oförklarliga magiska svängningar i staden. När kallelsen utfärdas har Anastasia Hartwell ännu inte kunnat avgöra om energin är fientlig, oavsiktlig eller ofarlig, så hon inleder en noggrann undersökning.",al={"vilken störning","magisk störning undercity","vad är fel i undercity"}},{q="Vem ger det här uppdraget?",a="Olika magikerlärare i Horde kan utfärda kallelsen när en besvärjare har fått tillräcklig erfarenhet. Bland dem finns Uthel'nay i Orgrimmar, Thurston Xane i Thunder Bluff, Cain Firesong i Brill och Un'Thuwa i Sen'jin Village.",al={"vem startar report to anastasia","uppdragsgivare report to anastasia"}},{q="Vad händer efter att du rapporterat till Anastasia?",a="När du har talat med Anastasia och fått en genomgång skickar hon dig genast för att undersöka störningen närmare. Du börjar med att undersöka stadens Apothecarium i uppdraget Investigate the Alchemist Shop.",al={"nästa uppdrag efter report to anastasia","uppföljning till report to anastasia"}}},fx={["22ef3f4a"]={q="Varför skickar magilärarna dig till Anastasia Hartwell i stället för att sköta det själva?",a="Dina lärare behövs för att undervisa blivande magiker och utöva magisk tillsyn över bosättningarna i Kalimdor. När nyheten kom att de Fördömdas magiker behövde hjälp med att undersöka en magisk avvikelse i Undercity, sökte lärarna upp lovande magiker som kunde ta sig an fältuppdrag utan att lämna sina undervisningsplatser.",al={"varför skicka mig till anastasia","varför kan inte lärarna åka till undercity","varför ska jag rapportera till anastasia"}}},fp="19,200,20.318.0,25.289.0,26.179.0,36.144.0,80.216.0,52.200.0,21.204.0,42.178.0"}
P.entries["quest:196"] = {n="Raptor Mastery",s="Hemet Nesingwary höjer insatsen för sin jaktexpedition genom att skicka dig efter en svårfångad ras som kallas Jungle Stalkers. Spåra upp tio av dessa listiga rovraptorer för att visa att du är en sann jägare av vilda djur i Stranglethorn Vale.",h="Hemet Nesingwary höjer insatsen för sin jaktexpedition genom att skicka dig efter en svårfångad ras som...",kw={"storviltsjägare","gurubashi arena","hemet nesingwary","jungle stalkers","raptor mastery","stranglethorn vale"},ang={["class:Hunter"]="Att smyga sig på vaksamma byten som Jungle Stalkers visar prov på spårningsförmåga och skytte i vildmarken under Hemet Nesingwarys vakande öga."},sec={{t="Ett svårfångat byte",b="Efter att ha prövat ditt sikte mot mindre raptorer presenterar Hemet Nesingwary ett mer krävande byte. Jungle Stalkers är ovanligt skygga och mycket svårare att spåra och fälla än de raser du jagat tidigare. Hemet förväntar sig att du ger dig ut i djungeln, fäller tio av dessa vaksamma rovdjur och återvänder till lägret för att få ledtråden till hans främsta jakt hittills."}},faq={{q="Vem erbjuder jakten?",a="Hemet Nesingwary, den berömda storviltsjägaren som slagit läger i norra Stranglethorn Vale, ger dig den här utmaningen.",al={"uppdragsgivare","vem startar raptor mastery 3","hemet nesingwarys jakt"}},{q="Vilket vilddjur ska du spåra?",a="Du ska hitta och fälla tio Jungle Stalkers, en särskilt skygg och svårfångad sorts raptor.",al={"vilken raptor","målrappor","vilka raptorer ska fällas"}},{q="Var finns Jungle Stalkers?",a="Jungle Stalkers strövar omkring i Stranglethorn Vale, särskilt i områdena norr och väster om Gurubashi Arena.",al={"jungle stalker-plats","var strövar jungle stalkers","hitta jungle stalkers"}},{q="Vad föregår den här utmaningen?",a="Den här jakten följer direkt på det andra steget i Raptor Mastery-proven och fortsätter Hemet Nesingwarys jakt på de lokala raptorraserna.",al={"förutsättningsuppdrag","föregående raptor mastery","vilket uppdrag kommer före"}}},fp="14,245,14.349.0,21.110.0,39.112.0,32.116.0,33.148.0"}
P.entries["quest:1960"] = {n="Investigate the Alchemist Shop",s="Undersök Alchemist Shop är ett uppdrag i Undercity för Horde-magiker som ska lösa en magisk anomali i Apothecarium. Under Anastasia Hartwells ledning spårar och fångar magiker osynliga varelser av ren magisk energi som löper amok i Algernon's shop.",h="Undersök Alchemist Shop är ett uppdrag i Undercity för Horde-magiker som ska lösa en magisk anomali i...",kw={"algernon","anastasia hartwell","apothecarium","cantation of manifestation","inneslutningskista","magic quarter","rift spawn","undercity"},ang={["class:Mage"]="Uppgiften prövar en lärlings behärskning av rena magiska krafter och kräver specialiserade manifestationsbesvärjelser och inneslutningskärl i stället för ren destruktiv kraft.",["race:Undead"]="Forsaken-apotekare fokuserar mycket på alkemi och pestkonst, men det här uppdraget visar hur vaksamma Undercitys magiska lärda är när de skyddar staden från magisk infiltration."},sec={{t="En störning i Apothecarium",b="Undercity är inte främmande för onaturliga fenomen, men nyligen uppstod ett problem med rent magiskt ursprung i Apothecarium. Osynliga magiska väsen upptäcktes när de strövade omkring i Algernon's alchemy shop och tyst passerade bland bubblande kittlar och giftiga reagenser. Mageinstruktören i Undercity, Anastasia Hartwell, inser att det rör sig om ett onaturligt brott i magins flöde och skickar lovande magiska adepter för att undersöka och oskadliggöra väsendena innan katastrofala skador uppstår."},{t="Manifestation och inneslutning",b="Eftersom väsendena är osynliga och helt består av rå magisk kraft är vanliga spårningsmetoder värdelösa. Anastasia utrustar sina elever med en särskild Cantation of Manifestation som bryter väsendena osynlighet, samt tåliga inneslutningskistor. När de väl har blottlagts måste de instabila rift spawn slås ner och förseglas säkert i kistorna innan de kan fortsätta slita sönder verkligheten eller skada alkemisterna i arbete."},{t="Olycka eller magiskt angrepp?",b="När exemplaren väl är säkrade skiftar Anastasias oro till deras ursprung. En spontan reva i det omgivande magiflödet är illa nog, men ett avsiktligt brott skulle tyda på ett aktivt, samordnat magiskt angrepp mot Forsakens huvudstad. De infångade varelserna överlämnas för studier, så att man kan avgöra om Apothecarium bara drabbats av en magisk olycka eller ligger i frontlinjen för ett riktat hot."}},faq={{q="Vem ger uppdraget och var hittar jag personen?",a="Uppdraget ges av Anastasia Hartwell, magitränaren i Magic Quarter i Undercity.",al={"uppdragsgivare","var börjar jag","anastasias plats"}},{q="Var finns störningen?",a="Störningen är centrerad kring Algernon's alchemy shop, som ligger nere i Apothecarium-distriktet i Undercity.",al={"vart ska jag gå","alchemist shop plats","var är algernon"}},{q="Vad är det för varelser som strövar omkring i butiken?",a="Det är rift spawns, osynliga varelser som helt består av koncentrerad magisk energi och har dykt upp genom en anomali i det lokala magiflödet.",al={"vad är det för monster","osynliga varelser","rift spawns"}},{q="Hur fångar man varelserna?",a="Du måste läsa upp Cantation of Manifestation i butiken för att blotta rift spawns, försvaga dem med besvärjelser och sedan använda en inneslutningskista för att fånga dem.",al={"hur fångar man dem","använda inneslutningskistan","hur slutför man uppdraget"}},{q="Varför vill Anastasia fånga varelserna levande?",a="Anastasia och Undercitys lärda behöver levande exemplar för att avgöra om revan i magin var en naturlig, slumpmässig spricka eller ett avsiktligt angrepp mot staden från en yttre magisk kraft.",al={"varför fånga dem","syftet med inneslutningskistor","varför studera dem"}},{q="Kan andra klasser än magiker göra uppdraget?",a="Nej, det här uppdraget ingår specifikt i den tidiga träningslinjen som är helt begränsad till Horde-magiker.",al={"endast magiker","vem kan ta uppdraget"}}},fx={["20993eae"]={q="Vad ska Cantation of Manifestation användas till?",a="Cantation of Manifestation är en besvärjelse som står på en skriftrulle. Anastasia Hartwell ger dig den för att avslöja det osedda. Varelserna som hemsöker Algernon's shop består av ren magisk energi och är naturligt osynliga för blotta ögat. Om du läser besvärjelsen i butiken slits deras slöja av doldhet bort och de tvingas ta fysisk form, så att du kan strida mot och kuva dem.",al={"cantation of manifestations syfte","varför använda cantation of manifestation","vad gör besvärjelsen"}},["355e23e2"]={q="Vad ska Chest of Containment Coffers användas till?",a="Chest of Containment Coffers innehåller särskilt skyddade kärl som skapats för att binda vilda magiska varelser. Riftsprängningarna i Apothecarium går inte att bära med händerna. Därför måste du använda de magiska kistorna när varelserna har försvagats i strid, så att de fångas säkert därinne och kan transporteras utan att skingras.",al={"chest of containment coffers","vad är containment coffers","syftet med containment coffers"}},["01d568c5"]={q="Vad ska Filled Containment Coffer användas till?",a="Varje Filled Containment Coffer innehåller en levande riftsprängning som fångats i Algernon's shop. Anastasia Hartwell behöver få tillbaka tre sådana fångade varelser i oskadat skick, så att Undercitys främsta magiska lärda kan undersöka dem. De ska ta reda på om deras plötsliga uppenbarelse berodde på en oavsiktlig reva i magins väv eller ett avsiktligt angrepp.",al={"användning av filled containment coffer","varför ta med fyllda kistor","syftet med filled containment coffer"}}},fp="30,184,33.344.0,29.340.0,27.349.1,46.83.0,33.88.0,42.144.0,33.149.0,55.184.0,43.69.0"}
P.entries["quest:1961"] = {n="Gathering Materials",s="Gathering Materials är en övergångsrit för blivande magiker i Horde som utbildas i Undercity. Anastasia Hartwell ger lärlingarna i uppdrag att hämta arkaniska ädelstenar från Dalarans magiker i Silverpine Forest och samla det som behövs för att väva deras första riktiga magikerdräkter.",h="Gathering Materials är en övergångsrit för blivande magiker i Horde som utbildas i Undercity.",kw={"ambermill","anastasia hartwell","dalaran mana gem","gathering materials","josef gregorian","linnetyg","magic quarter","spellfire robes","undercity"},ang={["class:Mage"]="Uppdraget är en avgörande milstolpe för magiker i Horde och markerar övergången från enkla lärlingskläder till skräddarsydda dräkter vävda med infångad arkanisk kraft.",["profession:Tailoring"]="Processen visar hur vanligt linnetyg kan bindas samman med kraftfulla manaädelstenar för att skapa hållbara förtrollade plagg.",["race:Undead"]="Uppdraget visar de fördömdas skoningslösa syn på världen: tidigare samhörighet med Dalarans trollkarlar ger ingen nåd om de levande magikerna visar sig vara för svaga för att hålla Silverpine."},sec={{t="En arkanisk prövning",b="I Magic Quarters arkaniska kloster måste novismagiker visa att de behärskar mer än bara råa besvärjelser. För att få sina första riktiga dräkter, en formell mantel som visar deras ställning och personliga värde, får de av Anastasia Hartwell i uppdrag att samla råmaterial till ett förtrollat tyg: ett stycke enkelt linnetyg och en uppsättning kraftfulla Dalaran-manaädelstenar."},{t="De fördömdas pragmatism",b="Manaädelstenarna går inte att köpa eller frambringa; de måste slitas från Dalarans magiker som är posterade runtom i Silverpine Forest, särskilt nära Ambermill. Anastasia Hartwell konstaterar kallt att även om Dalarans arkaniska filosofier liknar deras egna, hör sentimental tvekan inte hemma i Undercity. Enligt de fördömda förlorar de levande magikerna både sina skatter och sina liv om de saknar styrkan att försvara sina reliker."},{t="Skräddaren i Magic Quarter",b="När tyget och ädelstenarna har samlats in lämnas de till Josef Gregorian, en skräddare som bor i Magic Quarter. Gregorian medger gärna att han saknar magisk förmåga att bedöma den förstklassiga kvaliteten hos Dalarans förtrollade stenar, men han besitter den sällsynta hantverksskicklighet som krävs för att väva in deras råa kraft direkt i dräktens tyg."}},faq={{q="Vad är syftet med Gathering Materials?",a="Uppdraget fungerar som en invigning för magiker i Horde. När du slutför det får skräddaren Josef Gregorian de komponenter han behöver, linnetyg och manaädelstenar, för att tillverka lärlingens första formella förtrollade dräkt.",al={"varför samla material","syftet med uppdraget gathering materials","magikerdräkt uppdrag undercity"}},{q="Varför skickar Anastasia Hartwell dig efter Dalarans magiker?",a="Dalarans magiker som är posterade i Silverpine Forest bär på förädlade manaädelstenar som kan kanalisera starka magiska strömmar. Hartwell ser pragmatiskt på dessa levande magiker: trots deras gemensamma intellektuella rötter innebär svaghet i fält att de förlorar både livet och sina tillgångar till de fördömda.",al={"varför döda dalarans magiker","lore om dalarans manaädelstenar","varför magiker i silverpine"}},{q="Var finns Dalarans magiker?",a="Du kan stöta på dem i Silverpine Forest, vid utposter och på områden sydost om The Sepulcher, med bosättningen Ambermill som centrum.",al={"var hittar man dalarans manaädelstenar","magikernas plats i silverpine","magiker i ambermill"}},{q="Vem är Josef Gregorian?",a="Josef Gregorian är en odöd skräddare som arbetar i Magic Quarter i Undercity. Han är hantverkare snarare än arkanisk besvärjare och specialiserar sig på att sy förtrollade plagg som Spellfire Robes.",al={"josef gregorian undercity","vem är skräddaren i magic quarter","gregorian skräddare"}},{q="Vilka dräkter tillverkas av de här materialen?",a="Josef Gregorian använder linnetyget och Dalaran-manaädelstenarna för att sy Spellfire Robes, ett klassiskt plagg som markerar lärlingens övergång till etablerad magiker.",al={"vilken dräkt får man","belöning spellfire robes","dräktbelöning gathering materials"}},{q="Varför tycker Anastasia att det känns en smula obehagligt att döda Dalarans magiker?",a="Som Hartwell medger liknar Dalarans magikers trosuppfattningar de fördömda magikernas. De delar många av samma intellektuella och magiska filosofier. Trots denna samhörighet går överlevnad och nöd före känslor.",al={"hartwells känslor inför dalaran","de fördömda magikerna jämfört med dalaran","lore om anastasia hartwell"}}},fx={e61c0dee={q="Vad ska linnetyget användas till?",a="Linnetyget är den vanliga grunden till dina Spellfire Robes. Josef Gregorian, skräddaren i Undercitys Magic Quarter, väver tyget till fina kläder och väver sedan in magiska ingredienser i trådarna för att ge dem kraft.",al={"användning av linnetyg","varför linnetyg","vad ska linne användas till"}},["8f9ef647"]={q="Vad ska Dalaran Mana Gem användas till?",a="Dalaran Mana Gems innehåller rå magisk energi som kanaliserats av Kirin Tors magiker. Josef Gregorian syr fast dem direkt i dina mantlar för att ge tyget den magiska kraft som krävs för att skapa äkta eldmantelplagg.",al={"användning av dalaran mana gem","varför dalaran mana gems","vad ska managemerna användas till"}},["608132d5"]={q="Vilka är Dalarans magiker i Silverpine Forest?",a="De är mänskliga trollkarlar som är lojala mot Dalaran och stationerade runt Ambermill i östra Silverpine Forest. Deras magiska disciplin liknar de Fördömdas magikers, men deras närvaro hotar direkt Undercitys herravälde över området. Därför är de ett givet mål för ambitiösa lärlingar.",al={"dalarans magiker i silverpine","vilka är dalarans magiker","dalarans människor i silverpine"}},["1cfe23fe"]={q="Varför skickar Anastasia Hartwell en lärling i stället för att sköta det själv?",a="Att förtjäna din första magikermantel är en övergångsrit. Anastasia Hartwell förväntar sig att du bevisar ditt värde och din ställning inom magins konst genom att ta ingredienser från rivaliserande magiker med viljestyrka och egen kraft.",al={"varför ska jag samla material","varför skicka en lärling","varför hämtar inte anastasia ädelstenarna"}}},fp="19,167,25.269.0,26.394.0,31.271.0,43.159.0,57.257.0,38.134.0,23.174.0,44.158.0,67.184.0"}
P.entries["quest:1962"] = {n="Spellfire Robes",s="Spellfire Robes är den avslutande riten i unga hordmagikers utbildning i Undercity, och den fullbordas av skräddaren Josef Gregorian. När lärlingen har samlat sällsynta komponenter från hela världen får hen skräddarsydda, förtrollade kläder som visar att hens behärskning av det mystiska växer.",h="Spellfire Robes är den avslutande riten i unga hordmagikers utbildning i Undercity, och den fullbordas av...",kw={"mystiska kläder","gathering materials","josef gregorian","magikeruppdrag","magic quarter","spellfire robes","undercity"},ang={["class:Mage"]="Att få de här kläderna är en tidig övergångsrit för hordens magiutövare. De ger dem plagg som klarar av flyktiga eldenergier och mystiska krafter.",["profession:Tailoring"]="Uppdraget visar hur vanligt tyg förstärks med exotiska reagenser för att stå emot och förstärka kraftfulla magiska flöden.",["race:Undead"]="Förfallna magiutövare i Undercity bevarar Dalarans mystiska disciplin och förenar gamla magiska traditioner med sin nya tillvaro i Lordaerons ruiner."},sec={{t="En magikers klädnad",b="För lärlingar som bemästrar de mystiska konsterna i Lordaeron räcker vanliga kappor och kläder knappast till för att kanalisera eller stå emot råa övernaturliga krafter. Josef Gregorian, en skräddare i Undercitys Magic Quarter, väver äkta magiska kläder av de specialmaterial som horderna samlar åt sina trollkarlar. Den sista sömmen i Spellfire Robes markerar lärlingens övergång från enkla besvärjelser till att bli en etablerad utövare av magins och eldens konster."},{t="Vävd kraft",b="Att skapa kläder som tryggt kan fokusera intensiv magi kräver stor noggrannhet. Det handlar om mer än vanlig sömnad: sådana kläder kräver särskilda alkemiska och mystiska komponenter som säkrats genom farliga prövningar. När förråden har samlats in och överlämnats i Gregorians arbetsrum väver skräddaren genast ihop dem och ger den blivande magikern ett påtagligt tecken på status och skydd."}},faq={{q="Vad är syftet med uppdraget Spellfire Robes?",a="Det är det sista steget i en tidig klassrit för hordmagiker. De belönas med särskilt förtrollade kläder efter att ha samlat skräddarmaterial åt skräddaren Josef Gregorian.",al={"syftet med spellfire robes","vad gör spellfire robes","varför göra uppdraget"}},{q="Vem är Josef Gregorian?",a="Josef Gregorian är en förfallen skräddare som arbetar i skrädderiet i Magic Quarter i Undercity. Han syr de första riktiga klasskläderna åt nyblivna magiker som Anastasia Hartwell skickar till honom.",al={"vem är josef","vem tillverkar klädnaden","josef gregorian undercity"}},{q="Var äger uppdraget rum?",a="Hela mötet äger rum i Undercitys Magic Quarter, direkt i Josef Gregorians skrädderi.",al={"spellfire robes plats","var lämnar man in spellfire robes"}},{q="Varför behöver du inte gå iväg och göra en annan uppgift under det här uppdraget?",a="Allt arbete utfördes i det föregående uppdraget, Gathering Materials. När du lämnar över reagenserna till Josef tar han sig bara en stund att väva plagget och räcker genast över de färdiga kläderna.",al={"varför går det direkt","hur slutför man spellfire robes","automatisk klädnadsbelöning"}},{q="Kan andra klasser än magiker få de här kläderna?",a="Nej. Hela uppdragskedjan och de förtrollade kläderna är exklusiva för magiker som är allierade med Horden.",al={"bara för magiker","kan häxmästare få den här","vem kan göra spellfire robes"}},{q="Vilka material behövdes för att tillverka kläderna?",a="Klädnaden är sydd av de sällsynta förråden som samlades in under det föregående uppdraget. Där ingår linnetyg och Dalaran-manaädelstenar som tagits från Kirin Tor-magiker i Silverpine Forest.",al={"vad ingår i klädnaden","klädnadens material","lämna in gathering materials"}}},fx={c778cc7d={q="Varför syr Josef Gregorian Spellfire Robes åt dig?",a="Josef Gregorian är mentor åt lovande Forsaken- och Horde-magiker i Magic Quarter. Genom att väva in de insamlade reagenserna i passande förtrollade kläder ser han till att du är rätt utrustad för att kanalisera och uthärda de magiska krafter som ditt växande hantverk kräver.",al={"varför tillverkar josef kläderna","josef gregorians motiv","varför hjälper josef dig"}}},fp="15,191,17.365.0,11.305.0,49.165.0,23.172.0,33.95.0,62.164.0,48.74.0,49.142.0"}
P.entries["quest:1963"] = {n="The Shattered Hand",s="Therzok prövar skurkar i Orgrimmar som vill gå med i det hemlighetsfulla Shattered Hand. Deras prov går ut på att ge sig efter Tazan, en trollsmugglare, och hans låsta väska.",h="Therzok prövar skurkar i Orgrimmar som vill gå med i det hemlighetsfulla Shattered Hand.",kw={"cleft of shadow","orgrimmar","ratchet","skurk","väska","shattered hand","tazan","therzok"},ang={["class:Rogue"]="Som skurk i Horden går du med i Shattered Hand genom en rit som värdesätter hänsynslös effektivitet, lönnmord och användbarhet framför öppen strid.",["faction:Horde"]="Som medlem av Horden ser du hur Shattered Hand i tysthet utmanar Thralls försiktiga vision för den unga Horden."},sec={{t="Skuggor i Cleft",b="Shattered Hand verkar från Cleft of Shadow under Orgrimmar. Mördarnas och tjuvarnas orden följer gamla orciska traditioner. Høvding Thrall styr den unga Horden med heder, diplomati och försiktighet, men ledarna i Shattered Hand anser att återhållsamhet försvagar deras folk. De vill återupprätta militär överlägsenhet genom dolt våld och använder knivar och gift när ett anfall på slagfältet kan misslyckas."},{t="En smugglares öde",b="Therzok prövar skurkar med ett uppdrag att döda Tazan, en troll som håller till nära Ratchet i The Barrens. Tazan handlar med kustpirater och bär på underrättelser som gillet vill åt. Att återta hans låsta väska visar att en skurk kan spåra byte utanför stadsmurarna, men att öppna den kräver ytterligare skicklighet."}},faq={{q="Vad är Shattered Hand i Orgrimmar?",a="Shattered Hand är ett hemligt Horde-gille av skurkar, spejare och mördare med bas i Orgrimmars Cleft of Shadow. Det var en gång en gammal orcisk klan känd för brutal självstympning, men samlar nu underrättelser och utför mord. Det föredrar hänsynslös pragmatism framför Thralls försiktiga diplomati.",al={"vilka är shattered hand","skurkar i shattered hand","shattered hands syfte"}},{q="Vem är Therzok?",a="Therzok är en kontaktperson för Shattered Hand i Cleft of Shadow. Han prövar blivande skurkar på den list och dödlighet som gillet kräver, och tvivlar öppet på Thralls återhållsamhet.",al={"therzoks roll","vem ger uppdraget","therzok orgrimmar"}},{q="Varför vill Therzok att Tazan ska dö?",a="Tazan är en trollsmugglare som handlar med Southsea-piraterna nära Ratchet. Han bär på information i en väska som Shattered Hand vill åt för sitt hemliga arbete.",al={"varför döda tazan","tazans bakgrund","vad gjorde tazan"}},{q="Var finns Tazan?",a="Tazan håller till i The Barrens, nära kusten och piraternas tillhåll söder om Ratchet.",al={"tazans plats","var finns tazan","hitta tazan"}},{q="Vad händer när du hämtat Tazans väska?",a="Therzok upptäcker att väskan är låst när den återlämnas. Han är nöjd med att Tazan är död, men behöver informationen inuti och gör det till ytterligare ett prov på skurkens förmåga att dyrka upp lås.",al={"nästa uppdrag","låst väska","vad gör man med väskan"}},{q="Känner Thrall till Shattered Hands metoder?",a="Shattered Hand tjänar formellt Horden, men dess medlemmar verkar i skuggorna och föraktar Thralls försiktiga ledarskap. De bygger i tysthet upp underrättelsenätverk och försöker undanröja hot innan hövdingens diplomati kan fördröja handling.",al={"thrall och shattered hand","godkänner krigshövdingen","thrall och skurkar"}}},fx={["6c6760e5"]={q="Vad finns i Tazans väska?",a="Therzok vill ha väskan eftersom den innehåller värdefull information. Tazan har direktkontakt med Southsea Freebooters som håller till nära Ratchet, och eventuell korrespondens eller dokument han bär på kan ge Shattered Hand ett övertag över piraternas rörelser längs kusten. Tyvärr är väskan ordentligt låst, så den är värdelös tills du hittar ett sätt att få upp den.",al={"tazans väska","vad är tazans väska","syftet med tazans väska"}},fc6df596={q="Vem är Tazan?",a="Tazan är en ohederlig troll som bedriver olaglig handel med piraterna som är stationerade söder om Ratchet. Han verkar ute i The Barrens, utom räckhåll för Orgrimmars lagar, och handlar med hemligheter och smuggling som väckt Shattered Hands intresse. Hans kontakter med laglösa gör honom till ett självklart mål för likvidering.",al={"vem är tazan","tazans mål","varför döda tazan"}},beb36990={q="Varför skickar Therzok dig i stället för att ta hand om Tazan själv?",a="Shattered Hand verkar i strikt hemlighet från djupet av Cleft of Shadow och döljer sina hänsynslösa metoder för Warchief Thralls vaksamma blick. Therzok kan inte skicka officiella Horde-vakter eller riskera att avslöja högt uppsatta medlemmar i gillet på obetydliga fältuppdrag. I stället använder han kontraktet som ett inträdesprov och prövar om du har den dödliga list som krävs för att tjäna deras underjordiska brödraskap.",al={"varför skicka mig","varför vill therzok ha dig","varför dödar han inte tazan själv"}}},fp="18,159,20.405.0,17.303.1,40.288.0,15.174.0,33.160.0,23.83.0,46.187.1,52.240.0"}
P.entries["quest:197"] = {n="Raptor Mastery",s="Djupt inne i Stranglethorn Vale utmanar Hemet Nesingwary erfarna spårare att fälla ett svårfångat rovdjur som till och med han har missat. Efter att ha visat vad du går för mot mindre bestar får du i uppdrag att spåra den listiga raptorn Tethis och säkra dess klo.",h="Djupt inne i Stranglethorn Vale utmanar Hemet Nesingwary erfarna spårare att fälla ett svårfångat rovdjur som...",kw={"ajeck rouack","gurubashi arena","hemet nesingwary","raptoruppdraget","stranglethorn vale","tethis klo","tethis"},sec={{t="Den listiga besten i dalen",b="Efter dina tidigare prövningar i djungeln berättar Hemet Nesingwary om en ovanligt våldsam raptor vid namn Tethis. Medan mindre jägare har jagat byten genom lövverket har Tethis helt undgått att fångas och trotsat till och med expeditionens ledare. Ajeck Rouack gav besten dess namn och gjorde den till det främsta bytet bland Stranglethorns fjälliga fasor."},{t="Ta klon",b="För att bli erkänd som en av de främsta storviltsjägarna får du order att smyga runt norr om Gurubashi Arena, där Tethis brukar hålla till. Om du återvänder med en klo från den dödade besten blir du mästare på att fälla raptorer, en bedrift som ingen annan storviltsjägare har lyckats med."}},faq={{q="Vem skickar dig att jaga Tethis?",a="Hemet Nesingwary leder jakten från sitt expeditionsläger i norra Stranglethorn Vale, efter att du visat att du kan spåra vanliga djungelraptorer.",al={"vem ger raptoruppdraget","raptoruppdragets uppdragsgivare","vem vill döda tethis"}},{q="Var hittar man Tethis?",a="Den våldsamma besten strövar omkring i vildmarken kring Gurubashi Arena. Den ses oftast genom snåren norr om kolosseet.",al={"tethis plats","var finns tethis","var hittar man tethis"}},{q="Vilket bevis på bytet kräver Hemet?",a="Hemet kräver Tethis klo som obestridligt bevis på att den listiga varelsen till slut har fällts.",al={"vad ska jag ta med till hemet","bevis på att tethis fällts","föremål att lämna in för raptoruppdraget"}},{q="Vem gav raptorn namnet Tethis?",a="Ajeck Rouack, en av jägarna vid Nesingwarys expeditionsläger, gav det svårfångade rovdjuret namnet Tethis.",al={"vem namngav tethis","ursprunget till namnet tethis"}}},fp="14,271,29.389.0,18.290.0,29.171.0,26.154.0,42.111.0,39.117.0"}
P.entries["quest:1978"] = {n="The Deathstalkers",s="Det här uppdraget markerar den formella invigningen av en skicklig agent i Deathstalkers, Forsakens orden av lönnmördare och spioner. Kuriren ska överlämna Andron's Ledger direkt till dreadlorden Varimathras och för därmed bevis på Syndicates hemliga verksamhet till Undercitys högsta ledning.",h="Det här uppdraget markerar den formella invigningen av en skicklig agent i Deathstalkers, Forsakens orden av...",kw={"alterac","andron's ledger","deathstalkers","hall of the dark lady","mennet carkad","syndicate","undercity","varimathras"},ang={["class:Rogue"]="Den här invigningen innebär officiellt inträde i Forsakens särskilda skurkförband och gör enkla ficktjuvar till statligt anställda underrättelseagenter.",["faction:Horde"]="Även om övervakningen gäller Forsakens egen säkerhet skyddar bevakningen av Alteracs mänskliga kvarlevor Hordeområdena i norr från omstörtande sabotage.",["race:Undead"]="För Forsaken innebär invigningen i Deathstalkers ett direkt löfte att värna Lorderaons bräckliga självständighet mot mänskliga överlevare och förrädare som lurar i skuggorna."},sec={{t="Invigd i skuggorna",b="Efter att ha grävt fram komprometterande handlingar från Andron Gant välkomnar Mennet Carkad officiellt agenten till Deathstalkers. Organisationen tjänar Lady Sylvanas som ögon, öron och dolkar i hela Lordaeron. Den förlitar sig på underrättelsenätverk, skoningslös effektivitet och smygande för att undanröja hot innan de visar sig. Att bli formellt erkänd av orden är en viktig milstolpe för alla blivande skurkar eller spejare i Undercity."},{t="Syndicates koppling",b="Belöningen för den hemliga utredningen är Andron's Ledger, som avslöjar olagliga band mellan lokala agenter och Syndicate. Syndicate var en gång den fallna mänskliga kungariket Alteracs adliga aristokrati, men övergick till banditverksamhet och omstörtande verksamhet efter att riket föll under det andra kriget. Carkad uttrycker förvåning och förakt över hur lågt Alteracs fallna lorder har sjunkit och hur de tar till småskurna konspirationer för att återta makten."},{t="Möte med dreadlorden",b="På grund av underrättelsernas känsliga natur levereras boken direkt till Varimathras i Undercitys Royal Quarter. Nathrezim-befälhavaren övervakar Forsakens taktiska underrättelseverksamhet under Sylvanas Windrunner. Varimathras uppskattar Deathstalkers initiativ och välkomnar agentens bevisade förmåga. Han påpekar att hans underrättelseavdelning alltid kan ha nytta av någon som levererar resultat."}},faq={{q="Vad är Deathstalkers?",a="Deathstalkers är Forsakens främsta orden för spionage, spaning och lönnmord. De har sitt högkvarter i Undercitys Rogues' Quarter och verkar i hela Lordaeron för att oskadliggöra politiska rivaler, infiltrera fientliga fraktioner och skydda Forsakens rike från yttre och inre omstörtande verksamhet.",al={"vilka är deathstalkers","deathstalkers i berättelsen","forsakens lönnmördare"}},{q="Varför är Syndicate inblandat?",a="Den beslagtagna boken avslöjar hemliga kopplingar till Syndicate, Alteracs fördrivna aristokrati som övergick till organiserad banditverksamhet. Forsaken håller noggrann uppsikt över Alteracs kvarlevor som verkar på deras territorium, eftersom Syndicates agenter ständigt söker tillfällen att återta förlorad mark och plundra resurser i norra Lordaeron.",al={"varför syndicate","kopplingen till alterac","syndicates bok"}},{q="Varför rapportera direkt till Varimathras?",a="Varimathras är drottning Sylvanas taktiska rådgivare och övervakar Undercitys säkerhets- och underrättelseverksamhet. Viktiga upptäckter om utländska konspirationer, som Syndicates hemliga operationer, måste granskas på högsta ledningsnivå för att samordna bredare militära och diplomatiska motåtgärder.",al={"varför varimathras","vem är varimathras","dreadlordens roll"}},{q="Vem var Mennet Carkad?",a="Mennet Carkad är en erfaren kontaktperson och övervakare för Deathstalkers i Undercity. Han leder fältagenter, bedömer nya rekryter och går igenom insamlade underrättelser innan han skickar viktiga fynd vidare i befälskedjan.",al={"mennet carkads roll","questgivaren carkad"}},{q="Var äger mötet rum?",a="Mötet äger rum i Hall of the Dark Lady, som ligger i Royal Quarter djupt inne i Undercity. Varimathras står bredvid drottning Sylvanas Windrunner i hjärtat av Forsakens maktsäte.",al={"var finns varimathras","var ligger hall of the dark lady"}},{q="Vad händer efter att man gått med i Deathstalkers?",a="När dina meriter är fastställda och du har bevisat din pålitlighet för både Mennet Carkad och Varimathras erkänns du som en betrodd fältagent för Forsaken. Det banar väg för framtida spanings- och elimineringsuppdrag i Lorderaons omstridda områden.",al={"fortsättningen på deathstalkers uppdrag","vad händer sedan"}}},fx={["123798f3"]={q="Varför vill Mennet Carkad att Andron's Ledger levereras till Varimathras?",a="Boken avslöjar att Syndicate, de fallna adelsmännen från Alterac, konspirerar mot Forsaken. Att avslöja deras förräderi är en viktig underrättelseframgång för Deathstalkers, och Mennet vet att så brådskande nyheter om Lordaerons säkerhet måste lämnas direkt till Lord Varimathras, som övervakar ordens verksamhet.",al={"varför leverera boken","mennet carkads motiv","varför rapportera syndicate till varimathras"}},b0e675df={q="Varför skickar Mennet dig i stället för att själv rapportera till Varimathras?",a="Det var du som spårade upp konspiratörerna och säkrade Andron's Ledger ute på fältet. Mennet tycker därför att det är passande att du själv överlämnar informationen och får erkännande inför Lord Varimathras, samtidigt som du formellt tas upp i Deathstalkers led.",al={"varför jag hos deathstalkers","varför skickar mennet mig","varför leverera boken själv"}}},fp="17,157,26.352.0,24.318.1,27.344.0,27.287.0,30.283.0,35.234.0,22.216.0,36.180.0,45.258.0"}
P.entries["quest:198"] = {n="Supplies to Private Thorsen",s="Krazek i Booty Bay anlitar en kurir för att frakta diverse goblinförnödenheter norrut till Lieutenant Dorens läger. Lokala trollattacker har stoppat de vanliga leveranserna, så någon utomstående måste se till att varorna når Private Thorsen nära den norra gränsen.",h="Krazek i Booty Bay anlitar en kurir för att frakta diverse goblinförnödenheter norrut till Lieutenant Dorens...",kw={"booty bay","duskwood","goblinförnödenheter","krazek","kurzen","lieutenant doren","private thorsen","stranglethorn vale"},ang={["faction:Alliance"]="Lieutenant Dorens soldater vaktar den norra infarten från Duskwood till Stranglethorn Vale och förlitar sig på förnödenheter från gobliner för att hålla sin position."},sec={{t="En störd färdväg",b="Lieutenant Doren och hans styrka, som är stationerade nära gränsen mellan Stranglethorn Vale och Duskwood, är beroende av regelbundna leveranser som ordnas genom Krazek. Ihållande attacker från lokala troll har gjort vanliga leveranser farliga, så goblinköpmannen har anlitat en fristående kurir. Paketet måste färdas hela vägen längs djungelvägen. Private Thorsen ska ta emot det antingen i lägret nordväst om vägen eller längs sin patrullrutt söderut."},{t="Leveransens verkliga innehåll",b="Trots att leveransen bara anges innehålla diverse goblinförnödenheter består den av landminor. Private Thorsen avslöjar att sprängämnena ska hjälpa till att försvara deras post mot Colonel Kurzen och hans män."}},faq={{q="Vem skickar förnödenheterna?",a="Krazek, en goblinköpman som bedriver handel i Booty Bay, ordnar leveransen och tillhandahåller förnödenheterna.",al={"vem ger thorsen förnödenheter","krazeks leverans","vem startar uppdraget supplies to private thorsen"}},{q="Varför har förnödenheterna blivit försenade?",a="Aggressiva lokala troll i Stranglethorn Vale störde de vanliga leveranserna, så Lieutenant Dorens män fick vänta på sina planerade varor.",al={"varför försenad","trollattacker mot leveransen","varför levererades den inte"}},{q="Var finns Private Thorsen?",a="Han finns i Lieutenant Dorens läger, nordväst om huvudvägen nära infarten till Stranglethorn från Duskwood, eller patrullerar stigen precis söder om lägret.",al={"var finns thorsen","thorsens plats","hitta private thorsen"}},{q="Vad händer om förnödenheterna går förlorade?",a="Krazek varnar för att den som inte levererar försändelsen blir ekonomiskt ansvarig och skyldig honom ersättning.",al={"vad händer om jag tappar bort förnödenheterna","krazeks ersättning","misslyckas med krazek"}}},fp="27,254,17.475.0,28.206.1,30.108.0,35.155.0,35.188.0,38.120.0"}
P.entries["quest:199"] = {n="A Dark Threat Looms",s="Det här uppdraget markerar ögonblicket då en utredning av sabotage vid Stonewrought Dam avslöjar konkreta bevis på illdåd. Efter att ha hittat en misstänkt tunna gömd nära den väldiga dvärgbyggnaden hämtar äventyrare ett prov av märkligt luktande pulver för att visa det för Chief Engineer Hinderweir VII.",h="Det här uppdraget markerar ögonblicket då en utredning av sabotage vid Stonewrought Dam avslöjar konkreta...",kw={"ett mörkt hot tornar upp sig","hinderweir","loch modan","sabotage","stonewrought dam","strange smelling powder","misstänkt tunna"},ang={["profession:Engineering"]="En ingenjör anar genast fara när hen undersöker flyktiga pulver som med avsikt placerats vid en stor dams konstruktionsmässiga svagpunkter.",["race:Dwarf"]="Stonewrought Dam är en av Ironforge-dvärgarnas främsta arkitektoniska bedrifter. Varje hot mot dess hållfasthet drabbar Khaz Modans trygghet och stolthet direkt.",["race:Gnome"]="Gnomiska sinnen uppskattar precisionen bakom dvärgarnas byggnadskonst, vilket gör den kemiska naturen hos detta råa sabotage särskilt oroande."},sec={{t="Ett misstänkt fynd",b="Stonewrought Dam är ett monumentalt bevis på dvärgarnas ingenjörskonst och håller tillbaka sjöns väldiga vattenmassor. Men rykten om sabotage har riktat blickarna mot den omgivande stranden. Undangömd nära vattenbrynet finns en malplacerad tunna med ett olycksbådande innehåll: ett märkligt, fränt pulver som uppenbart inte hör hemma bland dammens vanliga underhållsförnödenheter."},{t="Larm vid dammen",b="När ett prov av det okända pulvret visas för Chief Engineer Hinderweir VII bekräftas Loch Modans myndigheters värsta farhågor. Ingenjören inser genast att en yttre makt smider planer mot dammen, och utredningen går från ren misstanke till en akut fråga om regionens försvar."}},faq={{q="Vad är det märkligt luktande pulvret?",a="Det märkligt luktande pulver som hittades i tunnan är ett sprängämne eller alkemiskt ämne som placerats nära Stonewrought Dams bas. Det är ett direkt bevis på att en fiende planerar att förstöra eller skada den väldiga barriären.",al={"märkligt pulver","vad finns i tunnan","pulver i misstänkt tunna"}},{q="Vem är Chief Engineer Hinderweir VII?",a="Chief Engineer Hinderweir VII är dvärgarnas mästeringenjör och ansvarar för underhållet, hållfastheten och säkerheten vid Stonewrought Dam i Loch Modan.",al={"vem är hinderweir","chief engineer hinderweir","damingenjör"}},{q="Var hittades den misstänkta tunnan?",a="Den misstänkta tunnan är undangömd längs stranden nära Stonewrought Dams grund i norra Loch Modan.",al={"tunnans plats","var är tunnan","tunna i loch modan"}},{q="Varför är Stonewrought Dam ett mål?",a="Stonewrought Dam håller tillbaka Loch Modans väldiga vattenmagasin. Om dammen brister skulle katastrofala översvämningar svepa genom Wetlands nedanför, slå ut Alliansens handelsvägar och ödelägga dvärgarnas besittningar i hela Khaz Modan.",al={"varför förstöra dammen","sabotage vid dammen","hot mot loch modan"}},{q="Vem lämnade den misstänkta tunnan här?",a="Tunnan placerades ut av agenter som försöker destabilisera dvärgarnas länder. Det får Chief Engineer Hinderweir att inleda en större utredning för att ta reda på vem som ligger bakom planen.",al={"vem placerade tunnan","sabotörer","vem lade dit pulvret"}},{q="Vad ska jag göra när jag har samlat in pulvret?",a="Ta provet direkt till Chief Engineer Hinderweir VII högst upp på Stonewrought Dam, så att han kan undersöka ämnet och förbereda ett svar.",al={"vad händer härnäst","lämna in pulvret","vem ska jag prata med"}}},fp="19,193,22.219.0,16.227.1,36.205.0,37.144.0,37.119.0,43.226.0,36.160.0,45.130.0"}
P.entries["quest:1998"] = {n="Fenwick Thatros",s="Mennet Carkad ger lovande skurkar i Undercity i uppdrag att spåra upp Fenwick Thatros på direkt order från Lord Varimathras. Thatros misstänks organisera självständiga odöda styrkor längs Silverpine Forests kust. Att döda honom visar Deathstalkers vad en agent går för och öppnar vägen till mer avancerad handelsutbildning.",h="Mennet Carkad ger lovande skurkar i Undercity i uppdrag att spåra upp Fenwick Thatros på direkt order från...",kw={"deathstalkers","fenwick thatros","lake lordamere","mennet carkad","rogues' quarter","silverpine forest","undercity","varimathras"},ang={["class:Rogue"]="Det här kontraktet sätter Forsakens skurkar på prov och bekräftar deras smygförmåga och dödlighet innan de anförtros Deathstalkers yrkes djupare verktyg.",["race:Undead"]="Forsaken kan inte tolerera att rivaliserande fraktioner av odöda hävdar självstyre så nära Capital City. Därför är Thatros huvud en politisk nödvändighet."},sec={{t="En order från skräckherren",b="I Rogues' Quarters mörka korridorer sköter Mennet Carkad interna kontrakt och utbildning för Deathstalkers, Forsakens hemlighetsfulla underrättelsegren. När Lord Varimathras skickar ner ett prioriterat mål är det inget uppdrag som lättvindigt lämnas till noviser. Fenwick Thatros har väckt skräckherrens uppmärksamhet genom att skaffa sig ett fäste bland de avfälliga odöda i Silverpine Forest. Om de lämnas åt sig själva kan självständiga ledare bland de odöda hota Forsakens konsolidering av Lordaerons gamla territorier."},{t="Den förfallna kajen vid Lordamere",b="Enligt Deathstalkers spaning gömmer sig Thatros inte i djupa fästningar eller kryptor. I stället lokaliserade spejare honom nära en förfallen kaj vid Lake Lordameres vatten i Silverpine Forest. För att slå till där måste man ta sig genom omstridd vildmark där vildsinta bestar, Rot Hide-gnollerna och rester av Scourge härjar. Att återvända med hans avhuggna huvud ger Varimathras det konkreta bevis han kräver innan en agent får invigas i djupare hemliga operationer."}},faq={{q="Vem är Fenwick Thatros?",a="Fenwick Thatros är en ledare bland de odöda som verkar längs Lake Lordameres utkanter i Silverpine Forest. Till skillnad från Forsaken som tjänar Lady Sylvanas leder Thatros grupper av odöda som förblir obundna eller fientliga mot Undercity, vilket får Lord Varimathras att utse honom till avrättning.",al={"fenwick historia","vem är thatros","fenwick thatros bakgrund"}},{q="Varför vill Varimathras se Fenwick Thatros död?",a="Varimathras ser Thatros som ett växande hot som kan samla kringströvande odöda i Silverpine mot Forsaken. För att säkra gränserna runt Undercity måste alla rivaliserande ledare som hotar Sylvanas absoluta kontroll över regionen snabbt undanröjas.",al={"varimathras thatros","varför döda fenwick"}},{q="Vilka är Deathstalkers?",a="Deathstalkers är Forsakens främsta organ för spionage, lönnmord och spaning. De har sin bas i Rogues' Quarter i Undercity och verkar över hela Lordaeron för att undanröja interna hot, spionera på rivaliserande fraktioner och säkra territorier åt Dark Lady.",al={"deathstalkers historia","vad är deathstalkers","fraktion med odöda skurkar"}},{q="Var finns Fenwick Thatros?",a="Rapporter från Deathstalkers placerar Thatros nära en förstörd, förfallen kaj vid Lake Lordameres strand i nordöstra Silverpine Forest.",al={"var finns fenwick","fenwicks kaj plats","thatros lake lordamere"}},{q="Vad får man hos Deathstalkers när man slutför uppdraget?",a="Att avrätta Thatros visar Mennet Carkad och Deathstalkers att en agent är kapabel och lojal. När du har bevisat din pålitlighet erbjuder Carkad dig vidareutbildning i skuggkonsterna genom specialiserade yrkesinstruktioner.",al={"fenwicks belöning historia","vad händer efter fenwick"}},{q="Vem är Mennet Carkad?",a="Mennet Carkad är skurkarnas tränare och Deathstalkers kontaktperson i Rogues' Quarter i Undercity. Han övervakar fältagenter och tilldelar uppdrag med direkt koppling till Forsakens rikes säkerhet.",al={"mennet carkad","vem ger fenwick-uppdraget"}}},fx={eac48585={q="Varför behöver Mennet Carkad Fenwick's Head?",a="Fenwick Thatros utgör ett organiserat hot alldeles intill Silverpine Forests gränser. Mennet Carkad kräver hans avhuggna huvud som obestridligt bevis på att den förrymda odöda befälhavaren har dödats. I Deathstalkers och Lord Varimathras hemliga operationer räcker en mördares ord aldrig utan ett fysiskt bevis på att målet är dött.",al={"vad är fenwick's head till för","varför ta fenwick's head","syftet med fenwicks huvud"}},bc8ca6fa={q="Varför väljer Mennet Carkad dig till det här uppdraget?",a="Mennet Carkad fungerar som handledare och tränare för Deathstalkers i Rogues' Quarter. När Lord Varimathras beordrar ett riktat mord är vanliga stadsvakter dåligt lämpade för spaning i det fria. Mennet väljer just dig eftersom du visat anlag för skuggkonsterna. Med det här viktiga kontraktet prövar han om du är redo för avancerad träning bland Forsakens främsta agenter.",al={"varför skicka mig","varför väljer mennet mig","varför skicka deathstalker-vakter"}}},fp="15,309,28.452.0,30.345.0,23.240.0,47.226.0,26.249.0,33.122.0,62.201.0,21.174.0"}
P.entries["quest:1999"] = {n="Tools of the Trade",s="Tools of the Trade är ett initieringsuppdrag för hordens lönnmördare, utdelat av Mennet Carkad i Undercity. På Lord Varimathras order måste agenter skaffa dyrkarutrustning och infiltrera Ambermill för att hämta känsliga rapporter från Kirin Tor som beskriver Dalarans nuvarande tillstånd.",h="Tools of the Trade är ett initieringsuppdrag för hordens lönnmördare, utdelat av Mennet Carkad i Undercity.",kw={"ambermill","dalaran","deathstalkers","estelle gendry","kirin tor","dyrkning","mennet carkad","rogues' quarter","undercity","varimathras"},ang={["class:Rogue"]="Uppdraget är ett övergångsprov för hordens lönnmördare. Du måste skaffa riktiga dyrkarverktyg och använda smygande och finess i stället för råstyrka.",["faction:Horde"]="Att säkra mänsklig underrättelse i Silverpine stärker hordens fäste i norra Lordaeron mot alliansens kvarlevor.",["race:Undead"]="Genom att infiltrera Ambermill kan Forsaken överlista just de magiker från Kirin Tor som försöker återta Lordaeron från de döda."},sec={{t="Ögon på Ambermill",b="Efter att ha förhört en av sina fångar fick Deathstalkers veta att viktig information om Dalarans ruiner låg gömd i Ambermill. Silverpine Forest är fortfarande en osäker frontlinje, och de mänskliga magikerna som vaktar byn bevakar sina meddelanden noga. På Lord Varimathras order leder Deathstalkers kontaktperson Mennet Carkad lovande agenter förbi Kirin Tor-vakterna och ser till att de hämtar Dalaran Status Report."},{t="Konsten att bryta sig in",b="Till skillnad från enkla lönnmord fungerar det här uppdraget som ett praktiskt prov i infiltration och dyrkning. Agenterna utrustas med särskilda tjuvverktyg av Estelle Gendry innan de ger sig in på fientligt territorium som tillhör Kirin Tor. Att dyrka upp den låsta kistan i Ambermill visar att en agent har lämnat rå gatubrutalitet bakom sig och blivit en oumbärlig spion åt Forsaken."}},faq={{q="Vem ger order om uppdraget?",a="Mennet Carkad, en mästerskurk bland Deathstalkers som är stationerad i Rogues' Quarter i Undercity, delar ut uppgiften. Det övergripande uppdraget kommer direkt från Lord Varimathras, som övervakar Forsakens underrättelseinhämtning.",al={"vem ger tools of the trade","uppdragsgivare","mennet carkad uppdrag"}},{q="Vad är Dalaran Status Report?",a="Det är ett förseglat meddelande från Kirin Tor som beskriver förhållandena i Dalaran. Deathstalkers förhörsledare fick reda på var det fanns genom att förhöra en av sina fångar, och därmed fick Undercity veta att viktig information om deras grannar i söder var sårbar.",al={"vad är dokumenten","dokument från kirin tor","lägesrapport"}},{q="Var förvaras rapporten?",a="Rapporten ligger i en låst kista vid Kirin Tors utpost Ambermill, i södra Silverpine Forest.",al={"var hittar jag dokumenten","var finns kistan i ambermill","var finns lägesrapporten"}},{q="Vem tillhandahåller dyrkarverktygen?",a="Estelle Gendry, en utrustningshandlare i Rogues' Quarter i Undercity, tillhandahåller de tjuvverktyg som behövs för att öppna Kirin Tors låsta kista.",al={"var får jag verktyg","estelle gendrys roll","verktyg från utrustningshandlaren"}},{q="Varför är Dalaran viktigt för Forsaken just nu?",a="Dalarans överlevande trollkarlar återuppbygger sin stad på andra sidan Lordamere Lake från Silverpine Forest. Forsaken håller uppsikt över Kirin Tor för att skydda sina egna besittningar i Lordaeron.",al={"varför bry sig om dalaran","forsaken mot dalaran","hotet från kirin tor"}},{q="Vilket förkunskapskrav måste uppfyllas innan du kan ta uppdraget?",a="Agenterna måste först slutföra lönnmordskontraktet Fenwick Thatros och jaga ett mål i Silverpine Forest innan Mennet Carkad anförtror dem ett känsligt infiltrationsuppdrag.",al={"förkunskapskrav","vilket uppdrag kommer före","fenwick thatros-uppdraget"}}},fx={["77cf7ea8"]={q="Varför vill Mennet Carkad att det här ska göras?",a="Lord Varimathras gav Deathstalkers i uppdrag att hämta rapporten efter att ha fått reda på var den fanns från en fånge. Som agent i Rogues' Quarter utför Mennet Carkad dreadlordens order och prövar samtidigt dina växande färdigheter i infiltration och spionage.",al={"varför vill mennet carkad ha detta","mennet carkads motiv","varför hämta dalaran status report"}},["9b719de0"]={q="Vilka skickas du mot i Ambermill?",a="Ditt mål är Kirin Tor, som är stationerade i Ambermill i Silverpine Forest. De här mänskliga magikerna håller till i en enklav nära den återuppbyggda staden Dalaran och skyddar hemlig information om den förstörda stadens nuvarande tillstånd från Forsaken.",al={"vem har rapporten","målet för tools of the trade","vem är målet"}},["6507a470"]={q="Varför behöver Mennet Carkad dig till det här uppdraget?",a="Uppdraget är ett övergångsprov. Efter att du visat grundläggande fallenhet genom att döda Fenwick Thatros valde Mennet dig för att bevisa att du kan hantera Deathstalkers mer subtila metoder, med smygande, låsdyrkning och infiltration i stället för råstyrka.",al={"varför skicka mig","varför jag för mennet carkad","varför kan deathstalkers inte hämta rapporten"}}},fp="18,192,17.367.0,21.308.0,24.170.0,34.241.0,25.104.0,35.129.0,51.176.0,63.178.0"}
P.entries["quest:2"] = {n="Sharptalon's Claw",s="Sharptalon's Claw är ett troféuppdrag som markerar att du besegrat den våldsamma hippogryfen Sharptalon i Ashenvale. När du tar varelsens avhuggna klo tillbaka till Senani Thunderheart vid Splintertree Post visar du din skicklighet och skyddar Hordens försörjningsvägar genom den uråldriga skogen.",h="Sharptalon's Claw är ett troféuppdrag som markerar att du besegrat den våldsamma hippogryfen Sharptalon i...",kw={"ashenvale","ashenvale hunt","hippogryf","peoner","senani thunderheart","sharptalon","splintertree post","warsong"},ang={["class:Hunter"]="Att överlista en legendarisk luftburen best som Sharptalon är det ultimata provet på spårning och skytte under Ashenvales täta trädkronor.",["faction:Horde"]="När du besegrar Sharptalon säkrar du viktiga stigar för Warsongs timmerverksamhet och skyddar utsatta peoner som går mellan de främre utposterna och Splintertree Post.",["race:Orc"]="När luftens skräck rensas bort från skogen minskar bördan för Warsong-klanens hårda timmerarbete.",["race:Tauren"]="Genom att följa jaktens riter under Senani Thunderheart visar du taurenfolkets traditionella vördnad för att pröva sig mot naturens grymmaste bestar."},sec={{t="En plåga längs skogsstigarna",b="När Horden försöker lägga beslag på resurser i Ashenvale visar sig den inhemska faunan vara lika farlig som nattalvernas väktare. Sharptalon, en ökänt aggressiv hippogryf, höll till bland trädkronorna och längs stigarna mot Splintertree Post. Odjuret anföll sårbara peoner och kurirer på vägen mellan de främre timmerlägren och utposten, vilket allvarligt hämmade Hordens verksamhet i området."},{t="Bevis på jakten",b="Under ledning av taurenjägaren Senani Thunderheart får Hordens spejare i uppdrag att rensa bort de farligaste rovdjuren som lurar under Ashenvales trädkronor. När den väldiga klon skärs loss från Sharptalon blir den ett obestridligt bevis på att luftens skräck har fallit. Om du lämnar trofén vid Splintertree Post vinner du försvararnas aktning och skänker lättnad åt de skräckslagna arbetare som måste färdas genom skogen."}},faq={{q="Vad är Sharptalon?",a="Sharptalon är en namngiven, rovlysten hippogryf som håller till i Ashenvale. Den är känd för sin grymhet och överfaller utan uppehåll resenärer i de uråldriga skogarna.",al={"vem är sharptalon","sharptalon fiende","vilket slags best är sharptalon"}},{q="Varför vill Senani Thunderheart ha klon?",a="Senani Thunderheart samordnar jakten i Ashenvale från Splintertree Post. Klon är ett fysiskt bevis på att ett stort rovdjur som hotade Hordens arbetare och försörjningsvägar har dödats.",al={"varför lämna in klon","senani thunderheart trofé","syftet med sharptalon's claw"}},{q="Var lämnar jag in Sharptalon's Claw?",a="Du lämnar klon till Senani Thunderheart, en tauren vid Splintertree Post i östra Ashenvale.",al={"var lämna in","vem tar emot klon","plats för att lämna in klon"}},{q="Hur hjälper det Horden att döda Sharptalon?",a="Sharptalon angrep ofta peoner som färdades mellan de avlägsna timmerbruken och Splintertree Post. När odjuret dödas blir färdvägarna säkrare för förnödenheter, timmer och budbärare.",al={"varför döda sharptalon i berättelsen","hordens intresse för sharptalon"}},{q="Ingår uppdraget i en större kedja?",a="Ja. Det ingår i 'The Ashenvale Hunt', en serie prövningar där Senani Thunderheart låter dig spåra och jaga odjur. Kedjan avslutas med 'The Hunt Completed'.",al={"ashenvale hunt uppdragskedja","uppdragskedja sharptalon"}},{q="Vem är Senani Thunderheart?",a="Senani Thunderheart är en taurenjägare stationerad vid Splintertree Post. Hon vakar över skogens balans och prövar Hordens jägares mod mot Ashenvales farligaste varelser.",al={"senani bakgrund","vem är senani"}}},fp="17,202,30.325.0,17.298.0,19.118.0,43.133.0,37.80.0,43.153.0,37.119.0,27.165.0"}
P.entries["quest:20"] = {n="Blackrock Menace",s="Marshal Marris i Lakeshire ger äventyrare i uppdrag att slå tillbaka de aggressiva Blackrock-orcher som tränger in i Redridge. Genom att beslagta deras Battleworn Axe hoppas stadens försvarare kunna bryta belägringen som sluter sig kring samhället.",h="Marshal Marris i Lakeshire ger äventyrare i uppdrag att slå tillbaka de aggressiva Blackrock-orcher som...",kw={"yxor","blackrock","burning steppes","lakeshire","marris","orcher","redridge","stonewatch","tharil'zun"},ang={["class:Warrior"]="Att drabba samman sköld mot sköld med härdade Blackrock-plundrare är ett brutalt prov på stridsdisciplin och uthållighet vid fronten.",["faction:Alliance"]="Det är avgörande att försvara Lakeshire för att hålla Stormwind-rikets södra gräns mot fiender från den gamla världen.",["race:Human"]="Blackrock-klanen förstörde Stormwinds ursprungliga kungarike under det första kriget. Att möta dem igen i Redridge väcker bitter sorg över historien."},sec={{t="En stad under belägring",b="Lakeshire är omringat från flera håll, men inget hot är lika allvarligt som Blackrock-orcherna som strömmar in från det eldfängda Burning Steppes. Dessa veteranplundrare har trängt söderut in i Redridge, intagit fästen och strövar omkring i de klippiga passen. Deras närvaro håller invånarna instängda i samhället och stänger av handel, födosök och resor längs de norra vägarna."},{t="Slå mot förtruppen",b="Marshal Marris, befälhavare för det hårt ansatta Lakeshire-gardet, kan inte avvara någon styrka för att anfalla deras ställningar direkt. I stället tar han hjälp av kringvandrande äventyrare för att decimera inkräktarnas förtrupper och fotsoldater. Genom att kräva deras grova, slitna Battleworn Axe som bevis på dödsfall vill Marris minska fiendens antal både kring Stonewatch i norr och i de oländiga delarna av sydöstra Redridge."}},faq={{q="Varifrån kommer dessa Blackrock-orcher?",a="De marscherade söderut genom de karga bergspassen från Burning Steppes, där deras uråldriga fäste ligger kring Blackrock Mountain.",al={"var kommer orcherna ifrån","blackrock-invasionen i redridge","varför finns orcher i redridge"}},{q="Vem ger det här uppdraget?",a="Marshal Marris, den högsta militära befälhavaren med uppgift att försvara Lakeshire och upprätthålla ordningen medan staden omringas allt mer.",al={"vem ger blackrock menace","uppdragsgivare för blackrock menace","marshal marris uppdrag"}},{q="Var hittar man Blackrock-inkräktarna?",a="De håller till i det nordliga höglandet kring Stonewatch Keep och har också etablerat fästen i den sydöstra delen av Redridge Mountains.",al={"var finns blackrock-orcher","platser för battleworn axe","orchläger i redridge"}},{q="Varför ber Marshal Marris om Battleworn Axe?",a="Battleworn Axe är ett obestridligt, fysiskt bevis på att en äventyrare har stridit mot och dödat Blackrock-plundrare som hotar dalen.",al={"varför yxor","bevis på dödsfall","syftet med battleworn axe"}},{q="Vad händer när spejarna har besegrats?",a="När förtruppen har decimerats beordrar Marshal Marris ett anfall mot den lokala Blackrock-ledaren Tharil'zun, som har förskansat sig i bergen.",al={"vad händer efter blackrock menace","nästa uppdrag efter blackrock menace","vem leder orcherna"}},{q="Tillhör orcherna Thralls Horde?",a="Nej. Blackrock-klanen här består av rester från Old Horde, som fortfarande är våldsamt fientliga mot Alliance och verkar oberoende av Thralls nya Horde i Kalimdor.",al={"är de här orcherna med i horde","tillhör blackrock-klanen thralls horde","vänligt sinnade orcher i redridge"}}},fx={ded9bd4b={q="Varför vill Marshal Marris att Blackrock-orcherna dödas?",a="Blackrock-klanen har trängt ner från Burning Steppes, intagit Stonewatch Keep och härjat i områdena norr om Lakeshire. Deras ständiga räder har i praktiken stängt in stadens invånare bakom gränserna, som boskap i en fålla. Marshal Marris vill bryta den kvävande belägringen, säkra regionens norra gränser och slå ut spaningsstyrkor innan Lakeshire blir helt översvämmat av fiender.",al={"marris motiv","varför döda blackrock-orcherna","varför blackrock menace"}},["29f2a399"]={q="Vilka är Blackrock-inkräktarna som hotar Lakeshire?",a="Du skickas mot Blackrock-orcherna, rester av den gamla Horden som kommit ner från Burning Steppes. De har tagit Stonewatch Keep i norr och härjar aktivt i vildmarken. De har även börjat upprätta utposter i Redridges sydöstra utkanter för att strypa Lakeshire och utöka sitt herravälde över bergen.",al={"vilka är blackrock-orcherna","vem är målet","orcherna vid stonewatch"}},e27bf976={q="Varför behöver Marshal Marris äventyrare i stället för Lakeshires vakter?",a="Lakeshires lokala garnison är hårt ansträngd. Stormwinds armé är borta och skickar inga förstärkningar, så Marris och hans få kvarvarande vakter har inte råd att ge sig ut i vildmarken utan att lämna staden helt försvarslös. För att hejda inkräktarna som rycker fram förlitar han sig på dugliga fristående legosoldater och äventyrare.",al={"varför slåss inte vakterna","varför jag för marris","varför behövs äventyrare"}}},fp="16,189,18.358.0,21.361.0,41.144.0,21.168.0,42.148.0,48.129.0,45.137.1,44.168.0"}
P.entries["quest:200"] = {n="Bookie Herod",s="Lieutenant Doren fruktar att en spion finns bland hans egna män efter att Kurzen upptäckte Thorsens hemlighet. För att ta reda på hur hemligheten läckte ut måste en utredare infiltrera Kurzen's Compound och hämta handlingarna som Kurzen's logistikofficer förvarar.",h="Lieutenant Doren fruktar att en spion finns bland hans egna män efter att Kurzen upptäckte Thorsens hemlighet.",kw={"bookie herod","colonel kurzen","kurzen's compound","lieutenant doren","stranglethorn vale","thorsen"},ang={["faction:Alliance"]="Lieutenant Doren och hans män stod en gång på Colonel Kurzans sida innan de bröt sig loss. Nu letar de efter en spion i de egna leden."},sec={{t="En läcka i leden",b="Efter att Thorsens hemlighet avslöjats misstänker Lieutenant Doren att en förrädare verkar mitt ibland dem. Underrättelseläckan hotar deras verksamhet, och det har blivit brådskande att hitta förrädaren. Thorsen hade en direkt kommunikationslinje in till Kurzen's Compound via Bookie Herod, överstens logistikofficer. Eftersom Herod vet hur Kurzen's Compound sköts från dag till dag tror Doren att officerens skriftliga handlingar avslöjar hur operationen röjdes."},{t="Logistikkontoret",b="För att komma åt Bookie Herods papper måste du ta dig in i Kurzen's Compound. När Doren tjänstgjorde under Kurzen hade Herod sitt kontor på översta våningen i områdets enda tvåvåningshus. Där, bland leveransbeställningar och meddelanden från Colonel Kurzen själv, finns handlingarna som kan visa hur hemligheten förråddes."}},faq={{q="Vem är Bookie Herod?",a="Bookie Herod är logistikofficer för Colonel Kurzens män. Han ansvarar för förnödenheter och lägerverksamhet vid Kurzen's Compound, och tjänstgjorde tidigare som Thorsens kontakt inne i lägret.",al={"herods roll","vem är bookie","bookie herods bakgrund"}},{q="Varför vill Lieutenant Doren ha Herods handlingar?",a="Lieutenant Doren tror att en spion har förrått deras läger eftersom Colonel Kurzen fick reda på Thorsens hemlighet. Doren hoppas att Herods logistikjournaler och korrespondens ska förklara hur informationen läckte ut.",al={"varför hämta herods handlingar","doren och spionen","hur avslöjades thorsen"}},{q="Var finns Bookie Herods handlingar?",a="Herods kontor ligger på översta våningen i det enda tvåvåningshuset inne i Kurzen's Compound. Doren tror att hans handlingar fortfarande förvaras där.",al={"var finns handlingarna","herods kontor","tvåvåningshus i kurzen"}},{q="Vad föregår den här utredningen?",a="Den här utredningen följer direkt efter Jungle Secrets, där Lieutenant Doren drar slutsatsen att någon måste ha förrått Thorsens hemlighet till Kurzuns män.",al={"föregående uppdrag","förutsättning för bookie herod"}}},fp="12,237,19.511.0,20.336.0,20.192.0,47.207.0,41.148.0,37.150.0"}
P.entries["quest:201"] = {n="Investigate the Camp",s="Investigate the Camp är ett expeditionsuppdrag från Booty Bay för att spana in ett nyetablerat jägar läger i Stranglethorn Vale. Krazek ger dig i uppdrag att ta reda på om ryktet stämmer: den legendariske dvärgskytten Hemet Nesingwary har anlänt nära Lake Nazferiti.",h="Investigate the Camp är ett expeditionsuppdrag från Booty Bay för att spana in ett nyetablerat jägar läger i...",kw={"booty bay","hemet nesingwary","jägarläger","undersök lägret","krazek","lake nazferiti","stranglethorn vale","venture company"},ang={["class:Hunter"]="Ett ryktat följe av storviltsjägare under den berömde Hemet Nesingwary lockar naturligt till sig spårnings- och skytteentusiaster som vill pröva sin skicklighet i djungeln.",["race:Dwarf"]="Hemet Nesingwary är en av de mest berömda dvärgiska skyttarna och äventyrarna. Därför väcker hans närvaro i Stranglethorn Vales avlägsna sydliga vildmarker både stolthet och nyfikenhet."},sec={{t="Rykten i djungeln",b="Rykten som sprids bland Booty Bays hamnarbetare talar om en expedition med storviltsjägare i Stranglethorn Vales norra djungel. Krazek har hört att lägret ligger längs floden, strax förbi Venture Companys livliga gruvområde nära Lake Nazferiti. I en laglös djungel full av faror och konkurrerande intressen kräver oförklarliga beväpnade läger alltid vaksamhet."},{t="En berömd skytt",b="Det som gör den här expeditionen särskilt anmärkningsvärd är ryktet om att Hemet Nesingwary själv är där. Den berömde dvärgskytten är vida känd som en skicklig utforskare med inflytelserika kontakter. Krazek tar inga risker med mäktiga personer som verkar i avlägsna trakter och skickar därför spejare uppför floden för att bekräfta om den legendariske jägaren verkligen har anlänt."}},faq={{q="Vem ger uppdraget att undersöka lägret?",a="Krazek, en agent stationerad i den neutrala goblinhamnen Booty Bay, ger resande i uppdrag att hitta lägret och rapportera dess exakta läge.",al={"vem vill få lägret undersökt","vem gav uppdraget","krazek booty bay"}},{q="Vem är Hemet Nesingwary?",a="Hemet Nesingwary är en berömd dvärgisk storviltsjägare och utforskare. Booty Bay har nåtts av rykten om att han är bland jägarna som slagit läger nära Lake Nazferiti, vilket väcker intresse på grund av hans stora anseende och många kontakter.",al={"hemet nesingwary stranglethorn","vem är hemet nesingwary","berömd dvärgjägare stranglethorn"}},{q="Var ligger jägarnas läger?",a="Jägarna har slagit läger uppför floden från Venture Companys gruvverksamhet vid Lake Nazferiti i norra Stranglethorn Vale.",al={"jägarlägrets plats","var ligger nesingwarys läger","var ligger lägret uppför floden"}},{q="Varför är Krazek intresserad av jaktlägret?",a="Ett avlägset jaktläger skulle normalt inte väcka större intresse i Booty Bay, men rapporterna om att en så inflytelserik och välansluten person som Hemet Nesingwary är där väckte både försiktighet och nyfikenhet.",al={"varför bryr sig krazek","varför undersöka jägare","krazeks motiv"}},{q="Vilken relation har jägarna till Venture Company?",a="Jägarna tillhör inte Venture Company. Deras läger ligger bara uppför floden från goblinsyndikatets gruvverksamhet nära Lake Nazferiti, som fungerar som ett geografiskt riktmärke.",al={"koppling till venture company","är jägarna med i venture company","venture company lake nazferiti"}},{q="Vem rapporterar du till efter att ha hittat lägret?",a="När du har hittat och spanat in lägret vid floden återvänder du söderut till Booty Bay för att rapportera direkt till Krazek.",al={"vad gör man efter att ha hittat lägret","vem ska man rapportera till","var lämnar man in investigate the camp"}}},fp="20,289,21.405.0,19.370.0,43.159.0,24.220.0,35.149.0,46.196.0,57.180.0,45.135.0"}
P.entries["quest:202"] = {n="Colonel Kurzen",s="Lieutenant Doren kallar på dig för att utdela det sista slaget mot Colonel Kurzen och hans närmaste vakter. Du skickas till Stockpile för att döda den förrädiske befälhavaren och hans återstående ledare och säkra Rebel Camps överlevnad.",h="Lieutenant Doren kallar på dig för att utdela det sista slaget mot Colonel Kurzen och hans närmaste vakter.",kw={"colonel kurzen","kurzen","lieutenant doren","rebel camp","stockpile","stranglethorn vale"},ang={["faction:Alliance"]="När du eliminerar Kurzen bryter du en förrädisk Stormwind-officers grepp om norra Stranglethorn Vale."},sec={{t="Stockpiles hjärta",b="Lieutenant Doren och hans skara avhoppare har nått kulmen i sin kamp mot sin tidigare befälhavare. Efter att ha kuvad Kurzens elitspecialister inser Doren att rebellstyrkorna aldrig kommer att vara helt trygga så länge Kurzen har kontroll över sitt djungelfäste. Han skickar dig in i grottan Stockpile, där Kurzen leder sina styrkor tillsammans med sina underchefer och elitsoldater."},{t="Slå mot ormens huvud",b="För att få slut på hotet för gott ber Doren om ett avgörande bevis på Kurzens fall: den förrädiske överstens huvud, och att du besegrar hans elitsoldater och underchefer. Att gå in i grottan och möta Kurzens ledning är rebellernas enda utsikt till lättnad från farorna i norra Stranglethorn."}},faq={{q="Vem ger dig uppdraget?",a="Lieutenant Doren skickar dig efter Kurzen från Rebel Camp i norra Stranglethorn Vale, direkt efter att du slutfört Special Forces.",al={"vem ger uppdraget","uppdragsgivare","var hämtar man colonel kurzen"}},{q="Var finns Colonel Kurzen?",a="Kurzen leder sina trupper långt inne i grottsystemet Stockpile, som ligger i Kurzen-anläggningen i norra Stranglethorn Vale.",al={"var finns kurzen","kurzens plats","hur hittar man colonel kurzen"}},{q="Vilket bevis kräver Lieutenant Doren?",a="Lieutenant Doren ber dig ta med Kurzens huvud tillbaka som slutgiltigt bevis på att den förrädiske befälhavaren har fallit, och besegra hans elitsoldater och underchefer.",al={"vilket bevis behövs","kurzens bevis","föremål att lämna in"}},{q="Vad hände före den här konfrontationen?",a="Den här konfrontationen följer direkt på Special Forces, där du försvagade Kurzens specialiserade stridsoperatörer innan du gav dig på hans centrala befälsstruktur.",al={"förutsättningsuppdrag","vilket är föregående uppdrag","uppdragskedjan före kurzen"}}},fp="14,231,26.397.0,27.320.0,22.156.0,32.149.0,41.153.0,36.162.0"}
P.entries["quest:203"] = {n="The Second Rebellion",s="Vid Rebel Camp i norra Stranglethorn Vale söker Sergeant Yohwa hjälp mot Colonel Kurzons övermäktiga styrkor. Rebellerna är tio gånger färre än den listige taktikerens styrkor och måste förlita sig på snabba, hemliga räder för att överleva. Att slå ut Kurzons djungelkrigare är första steget mot att lätta det obevekliga trycket på deras tillflykt.",h="Vid Rebel Camp i norra Stranglethorn Vale söker Sergeant Yohwa hjälp mot Colonel Kurzons övermäktiga styrkor.",kw={"colonel kurzen","djungelkrigare","kurzen","rebel camp","sergeant yohwa","special forces","stranglethorn vale","yohwa"},sec={{t="En hopplös strid",b="Soldaterna vid Rebel Camp står inför ett svårt läge mot Colonel Kurzen. Yohwa förklarar att översten är en lysande militär taktiker vars styrkor är minst tio gånger större än rebellernas. Eftersom de inte kan föra ett öppet utnötningskrig har rebellerna inget val än att använda överstens egna hemliga metoder. De gör snabba räder mot hans läger för att minska hans styrkor och fly innan stora förstärkningar hinner slå tillbaka."},{t="Anfall mot lägret",b="För att vända utvecklingen ber Yohwa dig rycka österut in i Kurzons fäste och slå ut en stor grupp av hans djungelkrigare. När dessa fotsoldater blir färre minskar trycket mot Rebel Camp."}},faq={{q="Vem är Sergeant Yohwa?",a="Sergeant Yohwa är en officer vid Rebel Camp i norra Stranglethorn Vale som samordnar hemliga räder mot hären under Colonel Kurzen.",al={"yohwa","vem ger uppdraget the second rebellion","sergeant yohwa"}},{q="Var ligger Colonel Kurzons läger?",a="Colonel Kurzons läger ligger öster om Rebel Camp, i den täta vildmarken i norra Stranglethorn Vale.",al={"kurzons lägerplats","var finns djungelkrigarna","kurzons plats"}},{q="Varför använder rebellerna hemliga metoder i stället för att strida öppet?",a="Rebellerna är minst tio gånger färre än Colonel Kurzons styrkor. Han är en lysande militärstrateg. Med ett så stort numerärt underläge är ett direkt anfall omöjligt, så rebellerna tvingas förlita sig på snabba gerillaräder.",al={"varför hemliga metoder","varför inte strida öppet mot kurzen","rebellernas taktik"}},{q="Vad kommer efter The Second Rebellion?",a="När du har slagit ut Kurzons djungelkrigare erbjuder Sergeant Yohwa nästa steg, med titeln Special Forces.",al={"nästa uppdrag","vad kommer efter the second rebellion","uppföljning till the second rebellion"}}},fp="20,345,15.431.0,21.213.0,22.156.0,39.116.0,60.211.0,38.108.0"}
P.entries["quest:2038"] = {n="Bingles' Missing Supplies",s="Efter att ha störtat med sin gyrokopter i Lochs vatten blev den excentriske gnomingenjören Bingles Blastenheimer överfallen av lokala troggar, som tog hans viktiga utrustning. Han är strandsatt på sjöns sydöstra strand och behöver få tillbaka sin stulna skiftnyckel, skruvmejsel, hammare och specialanpassade sprängämnen, så att han kan reparera sitt fordon och åter ansluta sig till kampen för Gnomeregan.",h="Efter att ha störtat med sin gyrokopter i Lochs vatten blev den excentriske gnomingenjören Bingles...",kw={"bingles","blastencapper","blastenheimer","gnomeregan","gyrokopter","hammare","loch modan","skruvmejsel","the loch","trogg","skiftnyckel"},ang={["faction:Alliance"]="Att hjälpa en allianspilot mitt i Loch Modan säkrar farlederna och bidrar till den större strategiska krigsinsatsen för att återta Khaz Modans förlorade områden.",["profession:Engineering"]="Att låta troggar lägga beslag på specialverktyg och explosiva vapen som Blastenheimer Blastencapper är en skymf mot hantverket och bäddar för en katastrofal olycka.",["race:Dwarf"]="Troggutbrottet på Lochs öar hotar handel och resor i området. Därför är varje angrepp mot deras läger en välkommen tjänst åt Bergsvärnet.",["race:Gnome"]="Varje återfunnet verktyg för gnomerna ett steg närmare en flygande motoffensiv mot troggarna och spetälskegnometarna som kväver Gnomeregan."},sec={{t="En våt landning",b="Bingles Blastenheimer flög sin gyrokopter över Loch Modan när en oväntad krasch fick honom att störta rakt ner i Lochs kalla vatten. Att överleva kraschen var redan en bedrift, men att ta sig upp på stranden var bara halva prövningen. Troggarna som härjar på sjöns centrala öar utnyttjade genast situationen, svärmade över den omtumlade piloten och plundrade hans värdefullaste ägodelar."},{t="Gnomisk uppfinningsrikedom under belägring",b="De härjande troggarna spred ut Bingles viktiga utrustning i sina öläger. Bland det som saknas finns hans vanliga fältverktyg: en skiftnyckel, en skruvmejsel och en hammare. Där finns också hans stolta uppfinning, Blastenheimer Blastencapper. Det är nog besvärligt att bli av med vanlig utrustning, men att förlora högexplosiva sprängladdningar i ett område som redan kryllar av troggar utgör en omedelbar fara för alla som färdas genom Loch Modan."},{t="För Gnomeregan",b="Bingles nöjesflyger inte bara omkring bland Khaz Modans skyar. Han ser sig själv som en flygande förtrupp i befrielsen av sitt fallna hemland. Gnomeregan är för närvarande översvämmat av underjordiska troggar och bestrålade spetälskegnometar, och Bingles drömmer om ett avgörande flyganfall som bryter fiendens grepp. Men utan sina verktyg och Blastencappers kan han inte bygga upp sin flygmaskin, och hans storslagna luftkampanj står kvar på fast mark bland vassen."}},faq={{q="Varför är Bingles Blastenheimer strandsatt i Loch Modan?",a="Bingles kraschade med sin gyrokopter rakt ner i Loch. När han försökte ta sig upp på den sydöstra stranden efter kraschen blev han överfallen av troggar från närliggande öar, som stal hans verktyg och experimentella vapen.",al={"varför är bingles här","hur kraschade bingles","bingles krasch"}},{q="Vilka förnödenheter stal troggarna?",a="Troggarna kom undan med fyra viktiga föremål: Bingles' Wrench, en skruvmejsel, en hammare och en specialladdning kallad Blastenheimer Blastencapper.",al={"vad stal troggarna","bingles förnödenheter","vilka föremål har bingles"}},{q="Vart tog troggarna Bingles utrustning?",a="Troggarna bar den stulna utrustningen tillbaka till sina läger på öarna i Lochs norra del och spred ut verktygshinkar och sprängämnen längs de klippiga stränderna.",al={"var är bingles verktyg","troggöarnas plats","var är blastencapper"}},{q="Vad är Blastencapper?",a="Blastencapper är en egenutvecklad sprängladdning konstruerad av Bingles Blastenheimer. Den är avsedd för flyganfall mot fienderna som ockuperar Gnomeregan.",al={"vad är blastencapper","blastenheimer blastencapper","bingles sprängämne"}},{q="Vilken rörelse syftar Bingles på?",a="Bingles har vigt sig åt att återta Gnomeregan. Han vill organisera en flygbombningskampanj för att rensa bort de underjordiska troggarna och spetälskegnometarna som håller den gnomiska huvudstaden gisslan.",al={"vilken rörelse","för gnomeregan","bingles motiv"}},{q="Varför kan inte Bingles hämta förnödenheterna själv?",a="Bingles är isolerad, genomblöt och helt obeväpnad efter att ha överlevt en katastrofal krasch. Att ensam möta ett befäst troggläger på andra sidan öppet vatten, utan vapen eller flygplan, vore självmord för en ingenjör.",al={"varför hämtar inte bingles dem","varför väntar bingles"}}},fx={["008fc445"]={q="Varför vill Bingles Blastenheimer få tillbaka sina förnödenheter?",a="Bingles kraschade sin flygmaskin i The Loch under ett test, men förlusten av utrustningen äventyrar mer än bara hans bärgning. Han tillverkade specialverktyg och sina egna Blastenheimer Blastencapper-sprängämnen särskilt för gnomernas luftoffensiv för att återta Gnomeregan. Utan verktyg att bygga med och ammunition att leverera kan insatsen mot troggarna och de spetälska gnomerna som ockuperar hans hemland inte fortsätta.",al={"bingles motiv","varför behöver bingles sina verktyg","varför hjälpa bingles"}},["0d3e655b"]={q="Vem tog Bingles förnödenheter och varför är de här?",a="Troggar som härjar på öarna i Loch Modan överföll Bingles kort efter kraschen och plundrade hans utrustning. De här primitiva underjordiska bestarna grävdes upp under dvärgarnas utgrävningar runt Khaz Modan. De drivs av våldsamma revirinstinkter och har en förkärlek för glänsande mekaniska märkligheter. De släpade Bingles verktygslåda och explosiva sprängämnen tillbaka till sina läger vid sjön.",al={"vem stal bingles verktyg","troggar i loch modan och bingles","varför finns troggar på öarna"}}},fp="25,210,14.218.0,29.324.0,14.322.0,52.185.0,40.114.0,40.149.0,26.129.0,38.163.0,48.201.0"}
P.entries["quest:2039"] = {n="Find Bingles",s="Find Bingles är ett kort introduktionsuppdrag för Alliansen som börjar i Ironforge hos gnomen Gnoarn. Han oroar sig för en flygare som försvann för över en vecka sedan under en spaningsflygning mot det fallna Gnomeregan och ber äventyrare söka av Loch Modans stränder. Sökandet leder till Bingles Blastenheimer, som är vid liv men i desperat behov av mekaniska reservdelar.",h="Find Bingles är ett kort introduktionsuppdrag för Alliansen som börjar i Ironforge hos gnomen Gnoarn.",kw={"bingles","blastenheimer","flygmaskin","gnoarn","gnomeregan","ironforge","loch modan","spaning","tinker town"},ang={["faction:Alliance"]="Alliansens spanare överbryggar ofta kommunikationsklyftan mellan Ironforges salar och fältoperationerna i Loch Modan.",["profession:Engineering"]="Ingenjörer kan förstå riskerna med gnomisk flygning, där en tappad vingmutter eller en motor som exploderar bara är ännu en vanlig dag i fält.",["race:Gnome"]="För gnomerna handlar det om att återfinna Bingles och hålla hoppet om att återta Gnomeregan vid liv, där varje spanare och flygmaskin räknas."},sec={{t="En försvunnen pilot",b="I det livliga gnomkvarteret Tinker Town i Ironforge är oron stor över försvunna släktingar och förlorade maskiner. Gnomflygaren Bingles Blastenheimer skickades ut på ett spaningsuppdrag över Gnomeregans radioaktiva ruiner. När över en vecka gick utan ett livstecken befarade Gnoarn det värsta och misstänkte att Bingles råkat ut för gnomernas ingenjörskonsts yrkesrisk: att spränga sig ur himlen. Den senaste rapporten placerade den excentriske flygaren någonstans ovanför sjön."},{t="Nere vid sjön",b="I stället för en tragisk hög med rykande vrakdelar hittar spanarna Bingles vid liv längs Loch Modans strand. Han verkar inte bekymrad över sin långa frånvaro och är en aning förolämpad över att någon tvivlat på hans flygförmåga. Den strandsatte uppfinnaren är helt upptagen av sitt större uppdrag. I stället för att genast återvända och rapportera till Gnoarn ber Bingles sin räddare hjälpa honom att hitta verktygen och Blastencapper-sprängladdningarna som troggs stulit, så att han kan återuppta sina uppgifter för gnomernas rörelse."}},faq={{q="Vem är Bingles Blastenheimer?",a="Bingles Blastenheimer är en excentrisk gnomisk flygare och mekaniker. Han skickades upp för att spana från luften över den fallna staden Gnomeregan, men kraschade med sin flygmaskin nära Loch Modan.",al={"vem är bingles","bingles blastenheimer historia","vem är piloten"}},{q="Varför flög Bingles över Gnomeregan?",a="Gnomernas ledare och uppfinnare håller ständig uppsikt över Gnomeregan efter stadens tragiska fall till troggs och strålning. Bingles gav sig upp i luften för att spana på fiendens positioner och förhållandena på marken, som en del av de större ansträngningarna att återta deras hem.",al={"bingles uppdrag","varför flög bingles","spaning över gnomeregan"}},{q="Var finns Bingles?",a="Bingles befinner sig vid Lochs stränder i Loch Modan, på den sydöstra stranden, där han försöker få ordning på sin kraschade flygmaskin.",al={"var är bingles","bingles plats","var hittar man bingles"}},{q="Vem är Gnoarn?",a="Gnoarn är en gnomisk samordnare i Tinker Town i Ironforge. Han håller koll på gnomernas personal och uppdrag, och inleder sökandet när Bingles inte återvänder i tid.",al={"vem är gnoarn","uppdragsgivaren gnoarn"}},{q="Vad händer när man hittar Bingles?",a="När du hittar Bingles låses fortsättningsuppdraget Bingles' Missing Supplies upp. Där hämtar äventyrare hans skiftnyckel, skruvmejsel, hammare och Blastencapper-sprängladdningar från troggs på öarna i sjön.",al={"vad händer efter find bingles","vingmutteruppdrag","bingles fortsättningsuppdrag"}},{q="Skadades Bingles i kraschen?",a="Bingles är helt oskadd, även om hans stolthet fått sig en liten törn när Gnoarn tvivlade på hans flygförmåga. Det han verkligen bryr sig om är att få tillbaka verktygen och sprängladdningarna som troggs stulit.",al={"är bingles skadad","dog bingles"}}},fx={b67b7bf8={q="Varför vill Gnoarn att Bingles ska hittas?",a="Bingles skickades ut på en viktig spaningsflygning över det fallna Gnomeregan och har inte rapporterat tillbaka på över en vecka. Med tanke på gnomisk maskintekniks oberäkneliga natur och Bingles fallenhet för katastrofer är Gnoarn rädd att piloten sprängt sig själv någonstans i vildmarken. Han behöver någon som söker igenom området nära Loch Modan, där Bingles senast sågs, för att ta reda på vad som hänt honom.",al={"varför hitta bingles","gnoarns motiv","varför skicka någon att leta efter bingles"}}},fp="12,273,15.367.0,16.398.0,29.162.0,39.209.0,25.95.0,14.162.0,35.182.0,31.170.0"}
P.entries["quest:204"] = {n="Bad Medicine",s="Vid Rebel Camp i norra Stranglethorn Vale vill Sergeant Yohwa minska Colonel Kurzens militära övertag genom att slå mot hans sjukvård. Renegaterna förlitar sig på kraftfulla läkemedel och gifter, tillverkade av deras medicinkunniga, så motståndskämparna är desperata att använda samma blandningar till sin fördel.",h="Vid Rebel Camp i norra Stranglethorn Vale vill Sergeant Yohwa minska Colonel Kurzens militära övertag genom...",kw={"jungle remedy","kurzen","kurzen compound","medicinkunniga","rebel camp","sergeant yohwa","stranglethorn","venom fern extract"},ang={["faction:Alliance"]="Om Kurzens läkarstöd slås ut överlever fler kämpar från Rebel Camp striderna mot hans styrkor."},sec={{t="Slå ut lägermedarbetet",b="Colonel Kurzen har stärkt sina djungelstyrkor med många medicinkunniga som läker hans soldater och förgiftar Yohwas kämpar med Venom Fern Extract. För att vända stridens gång skickar Sergeant Yohwa äventyrare till Kurzen Compound för att samla in de viktiga förnödenheterna. Om de säkrar djungelmedicinerna kan de behandla sårade kämpar vid Rebel Camp. Ett prov av deras Venom Fern Extract gör det möjligt för motståndet att studera giftet och tillverka egna motmedel."}},faq={{q="Vem ger det här uppdraget?",a="Sergeant Yohwa, som håller till vid Rebel Camp i norra Stranglethorn Vale, ber dig hämta de här sjukvårdsförnödenheterna.",al={"vem ger bad medicine","bad medicine uppdragsgivare","yohwas uppdrag"}},{q="Varför vill Sergeant Yohwa ha Jungle Remedies?",a="Kurzens medicinkunniga använder läkemedlen för att läka sina egna soldater. Motståndskämparna behöver samma förnödenheter för att behandla och hålla sina sårade kamrater vid liv.",al={"varför behövs jungle remedies","syftet med jungle remedy"}},{q="Vad används Venom Fern Extract till?",a="Kurzens styrkor använder Venom Fern Extract för att förgifta Yohwas kämpar. Sergeant Yohwa behöver ett prov så att lägret kan studera ämnet och brygga egna motmedel.",al={"varför venom fern extract","användning av extrakt"}},{q="Var finns sjukvårdsförnödenheterna?",a="Båda finns i Kurzen Compound. De medicinkunniga bär läkemedlen på sig, medan Venom Fern Extract förvaras i försörjningslådor runt lägret.",al={"var hittar man jungle remedies","var finns extraktet"}}},fp="12,331,32.489.0,27.120.0,45.164.0,40.175.0,38.171.0"}
P.entries["quest:2040"] = {n="Underground Assault",s="Underground Assault är ett Alliance-uppdrag som Shoni the Shilent ger i Dwarven District i Stormwind City. För att hjälpa de fördrivna gnomerna beger sig äventyrare in i The Deadmines för att bärga en intakt kraftkärna från en goblinstrimlare. Den stulna komponenten ska driva borrmaskiner som ska bana väg för befrielsen av Gnomeregan.",h="Underground Assault är ett Alliance-uppdrag som Shoni the Shilent ger i Dwarven District i Stormwind City.",kw={"the deadmines","gnoam sprecklesprocket","gnomeregan","goblinstrimlare","gyrodrillmatic","shoni the shilent","troggs","underground assault"},ang={["faction:Alliance"]="Att hjälpa de fördrivna gnomerna i Dwarven District stärker banden mellan Stormwind och dess allierade i exil, samtidigt som ett slag riktas mot Defias försörjningslinje.",["profession:Engineering"]="Uppfinnare lär uppskatta den djärva ingenjörskonsten bakom att återanvända en brutal goblinstrimlares kraftkärna för att driva precisionsmaskiner för gnomisk utgrävning.",["race:Gnome"]="För gnomiska äventyrare i exil är bärgningen av den här kraftkärnan ett personligt steg mot att borra sig genom det klippiga skalet kring deras fallna hem och driva ut troggsen ur Gnomeregan."},sec={{t="Desperat uppfinningsrikedom",b="Efter Gnomeregan föll för de primitiva troggsen tvingades överlevande gnomiska uppfinnare i exil i Khaz Modan och Stormwind. I stället för att älta nederlaget planerar ingenjörer som Shoni the Shilent redan mekaniska operationer för att ta sig in i sitt förlorade hem. Det största hindret är den täta berggrunden under jorden kring den teknokratiska staden. För att forcera den krävs enorma tunnelborrmaskiner som kallas gyrodrillmatic excavationators. Eftersom de saknar de lokala elnäten som behövs i människornas områden har gnomerna riktat blicken mot ett oväntat och oberäkneligt alternativ: gobliners tunga maskiner i den kriminella undre världen."},{t="Plundring av Defias gjuterier",b="Djupt inne i de vindlande schakten i The Deadmines i Westfall låter Edwin VanCleefs Defias Brotherhood gobliningenjörer tillverka krigsmaskiner, däribland en fullt fungerande goblinstrimlare. Shoni skickar Alliance-agenter att infiltrera gjuteriet, förstöra eller plocka isär den klumpiga automaten och bärga dess specialbyggda hjärta, Gnoam Sprecklesprocket. Genom att lägga beslag på goblinernas kraftfulla kraftkälla får de fördrivna gnomerna den råa mekaniska kraft som behövs för att borra genom den underjordiska gränsen och inleda en motoffensiv för att återta Gnomeregan."}},faq={{q="Vem ger uppdraget Underground Assault?",a="Uppdraget ges av Shoni the Shilent, en gnomisk ingenjör i Dwarven District i Stormwind City. Äventyrare blir ofta hänvisade till henne efter att ha talat med andra gnomer som nämner hennes ambitiösa planer.",al={"uppdragsgivare underground assault","vem ger underground assault","shonis uppdrag"}},{q="Var hittar jag Gnoam Sprecklesprocket?",a="Gnoam Sprecklesprocket kan bärgas från en fungerande goblinstrimlare djupt inne i gjuteriets tunnlar i The Deadmines i Westfall.",al={"sprecklesprockets plats","var finns sprecklesprocket","del till shredder i deadmines"}},{q="Varför behöver Shoni delar från en goblinstrimlare?",a="Gnomernas gyrodrillmatic excavationators behöver en enorm, portabel kraftkälla för att forcera de förstärkta underjordiska gränserna kring Gnomeregan. Den kraftiga kraftkärnan som driver Defias Brotherhoods goblinstrimlare ger precis den mekaniska kraft borrarna behöver.",al={"varför goblindelar","varför shredderns kraftkälla","sprecklesprockets syfte"}},{q="Vad är uppdragets övergripande mål?",a="Uppdraget bidrar till den framtida befrielsen av Gnomeregan. Genom att driva kraftiga grävmaskiner tänker de fördrivna gnomerna borra rakt genom den klippiga gränsen kring sin ockuperade stad och överraska troggsen med ett anfall.",al={"varför göra underground assault","uppdrag för att återta gnomeregan","gnomernas anfallsplan"}},{q="Vad hände med Gnomeregan som fick dem att planera anfallet?",a="Gnomeregan övermannades av en invasion av troggs som kom upp ur djupet under staden. Under det kaotiska försvaret förorenades staden av giftig strålning, så den överlevande gnomiska befolkningen tvingades fly som flyktingar till Ironforge och Stormwind.",al={"varför föll gnomeregan","vad hände med gnomeregan","trogginvasion"}},{q="Är Defias Brotherhood och troggsen allierade?",a="Nej, de har ingen koppling till varandra. Defias Brotherhood anlitade bara goblinuppfinnare för att bygga krigsmaskiner i Westfall. Shoni utnyttjar helt enkelt Defias närvaro i The Deadmines som en praktisk källa till kraftfull goblinteknik.",al={"defias och troggs","är troggsen med defias"}}},fx={["41842bc5"]={q="Vad är Gnoam Sprecklesprocket?",a="Gnoam Sprecklesprocket är en intakt och mycket effektiv kraftkälla från gobliner, inbyggd i rivaren som arbetar djupt inne i The Deadmines. Shoni the Shilent tänker montera kraftkärnan direkt i gnomernas gyrodrillmatiska grävmaskiner. De här tunga borrmaskinerna behöver enorm energi för att borra genom den täta, steniga underjordiska barriären runt Gnomeregan och bana väg för gnomernas anfallsstyrkor som väntar på att återta sitt hem.",al={"vad är gnoam sprecklesprocket","syftet med sprecklesprocket","vad gör rivarens kraftkälla"}},["37ad24fa"]={q="Varför skickar Shoni dig efter goblinrivaren i The Deadmines?",a="Defias Brotherhood använder avancerad goblinteknik, däribland en fullt fungerande timmer- och gruvröjare, för att gräva och bygga sina hemliga anläggningar under Moonbrook. Eftersom dessa krigsmaskiner har ovanligt kraftfulla kärnor identifierade Shoni maskinen som ett utmärkt bärgningsmål. Du skickas för att plocka isär eller förstöra rivaren djupt inne i anläggningen och ta ut dess intakta kraftenhet innan Brotherhood hinner använda den igen.",al={"vem är målet i deadmines","varför förstöra rivaren","varför finns det en rivare i deadmines"}}},fp="19,205,21.440.0,28.474.0,40.168.0,43.120.0,49.242.0,41.178.0,67.215.0,49.229.0"}
P.entries["quest:2041"] = {n="Speak with Shoni",s="Det här vägvisaruppdraget leder Alliansens äventyrare från Ironforges salar till Shoni the Shilent i Stormwind City. Shoni leder en underjordisk anfallsstyrka som ska stödja den pågående återerövringen av Gnomeregan.",h="Det här vägvisaruppdraget leder Alliansens äventyrare från Ironforges salar till Shoni the Shilent i...",kw={"deeprun tram","dwarven district","gnomeregan","gyrodrillmatic excavationator","ironforge","shoni the shilent","stormwind","tinkertown","underground assault"},ang={["faction:Alliance"]="Uppdraget visar hur nära huvudstäderna i Alliansen samarbetar logistiskt och använder Deeprun Tram för att flytta personal mellan Ironforge och Stormwind.",["profession:Engineering"]="Shonis projekt omfattar gyrodrillmatic excavationators, ett avancerat verk inom gnomisk maskinteknik som är konstruerade för att borra djupt under marken.",["race:Gnome"]="Alla gnomer i Ironforge drömmer om att återta sitt radioaktiva hem. Genom att följa Shonis order bidrar du aktivt till den tekniska satsningen på att återta Gnomeregan."},sec={{t="En kallelse från Tinkertown",b="Efter Gnomeregans radioaktiva fall upprättade de överlevande gnomerna ett exilkvarter i Ironforge. Deras ingenjörer, uppfinnare och strateger smider ständigt planer på att ta sig in i sitt förlorade hem. Den centrala planeringen har sin bas i Tinkertown, men förberedelserna vid fronten sträcker sig långt bortom Khaz Modan. Driftiga äventyrare i bergsstaden skickas söderut till Stormwind, där särskild militär utrustning för underjordisk krigföring förbereds."},{t="Underjordiska ambitioner",b="Shoni the Shilent leder en elitstyrka för underjordiska anfall, stationerad bland städ och smedjor i Stormwinds Dwarven District. För att gräva sig djupt in i områden som kryllar av troggs behöver hennes sappers specialmaskiner som kallas gyrodrillmatic excavationators. Det är enkelt att ta sig till Shoni tack vare den nyöppnade Deeprun Tram, som förbinder Ironforge och Stormwind direkt under bergen."}},faq={{q="Vem är Shoni the Shilent?",a="Shoni the Shilent är en gnomisk officer stationerad i Stormwind City. Trots sitt tystlåtna tillnamn leder hon en underjordisk anfallsstyrka som ska bygga och använda tung grävutrustning för att hjälpa till att återta Gnomeregan.",al={"vem är shoni","shoni the shilent","vem är npc:n"}},{q="Var hittar jag Shoni the Shilent?",a="Shoni finns i Stormwind Citys Dwarven District, nära smidestränarna och smedjorna, bara några steg från Deeprun Trams station.",al={"var finns shoni","shonis plats","shonis koordinater"}},{q="Hur tar jag mig från Ironforge till Stormwind?",a="Den snabbaste vägen är Deeprun Tram, ett tekniskt underverk på Tinkertowns nordöstra sida i Ironforge. Den tar resenärer raka vägen till Stormwinds Dwarven District, utan att de behöver färdas genom vildmarken.",al={"resa till stormwind","ironforge till stormwind","hur tar man sig till stormwind"}},{q="Vad behöver Shoni hjälp med?",a="Shoni utrustar en underjordisk anfallsstyrka och behöver viktiga delar till sina gyrodrillmatic excavationators. Det leder så småningom äventyrare till Westfall och The Deadmines.",al={"shonis uppdragsmål","vad vill shoni"}},{q="Måste jag göra det här uppdraget för att få Underground Assault?",a="Nej, det är ett valfritt vägvisaruppdrag. Du kan själv ta dig direkt till Dwarven District i Stormwind och prata med Shoni för att få Underground Assault.",al={"är speak with shoni obligatoriskt","kan jag hoppa direkt till shoni"}},{q="Hur hänger det här ihop med Gnomeregan?",a="Gnomernas ledare samlar styrkor och grävteknik för att tränga igenom Gnomeregans försvar. Shonis team utvecklar den underjordiska borrutrustning som behövs för att ta sig in i den förorenade staden.",al={"varför gnomeregan","gnomernas koppling"}}},fx={["3fdd7df6"]={q="Varför skickar uppdragsgivaren dig till Shoni the Shilent?",a="Gnomerna kämpar i motvind för att återta sitt fallna hem, Gnomeregan. Shoni the Shilent leder en underjordisk anfallsgrupp som förbereder särskilda gyrodrillmatiska grävmaskiner för krigsinsatsen, men hennes verksamhet i Stormwind saknar folk. Högkvarteret i Ironforge behöver dugliga äventyrare som kan resa söderut och stärka hennes viktiga ingenjörsprojekt innan offensiven kan gå vidare.",al={"varför tala med shoni","varför skicka mig till shoni","varför besöka shoni"}}},fp="16,179,22.407.0,22.338.0,25.170.0,35.133.0,41.189.0,31.179.0,50.145.0,36.189.0"}
P.entries["quest:205"] = {n="Troll Witchery",s="Brother Nimetz söker förståelse för Colonel Kurzենս fördärv genom att undersöka mörka trollbesvärjelser. Efter Kurzen's Mystery ber han dig bege dig söderut till Skullsplitter-territorium och hämta fetischer från deras besvärjare.",h="Brother Nimetz söker förståelse för Colonel Kurzենս fördärv genom att undersöka mörka trollbesvärjelser.",kw={"brother nimetz","colonel kurzen","mystic","rebel camp","skullsplitter","stranglethorn vale","troll witchery","witch doctor"},ang={["faction:Alliance"]="Brother Nimetz håller till vid Rebel Camp och värvar Alliansens resenärer för att ta reda på vad som fördärvade Colonel Kurzen."},sec={{t="Att nysta upp fördärvet",b="Medan Brother Nimetz går igenom legenderna som hämtats från djungeln riktar han uppmärksamheten mot den andra trollstammen längre söderut. Han misstänker att mörk trollmagi kan ligga bakom Colonel Kurzենս fall i ondska. För att pröva sin teori ber han dig bege dig in i Skullsplitter-land och ta fetischer direkt från deras Witch Doctors och Mystics, så att han kan studera deras magi vid Rebel Camp."}},faq={{q="Vem ger uppdraget Troll Witchery?",a="Brother Nimetz ger det vid Rebel Camp i norra Stranglethorn Vale.",al={"uppdragsgivare för troll witchery","vem startar troll witchery","var får man troll witchery"}},{q="Varför vill Brother Nimetz ha Skullsplitter-fetischer?",a="Brother Nimetz tänker studera de mörka magiska föremålen för att se om trollhäxkonst förklarar Colonel Kurzենս fall i ondska.",al={"varför brother nimetz behöver fetischer","syftet med troll witchery","kurzens fördärv och fetischer"}},{q="Vilka fiender bär på fetischerna?",a="Fetischerna bärs av Skullsplitter Witch Doctors och Skullsplitter Mystics i Skullsplitter-territorium.",al={"vem släpper skullsplitter-fetischer","vilka troll har fetischer","källa till troll witchery-fetischer"}},{q="Vilket uppdrag kommer före Troll Witchery?",a="Det här uppdraget följer på Kurzen's Mystery och fortsätter Brother Nimetz undersökning av överstens vansinne.",al={"troll witchery-uppdragskedja","vad kommer före troll witchery","förutsättning för troll witchery"}}},fp="14,235,25.415.0,35.73.0,52.128.0,33.113.0,35.111.0"}
P.entries["quest:206"] = {n="Mai'Zoth",s="Brother Nimetz tror att Colonel Kurzen drevs till ondska av en dold kraft som fortfarande lever. En ogremagiker vid namn Mai'Zoth håller till i de östra bergen och bär på en artefakt som sägs kunna förvrida och styra sinnen. Genom att döda honom och återta reliken ska man se till att ingen annan befälhavare drabbas av samma fördärv.",h="Brother Nimetz tror att Colonel Kurzen drevs till ondska av en dold kraft som fortfarande lever.",kw={"brother nimetz","kurzen","mai'zoth","maizoth","mind's eye","ogreboplats","rebel camp","stranglethorn"},ang={["faction:Alliance"]="Brother Nimetz håller till i Rebel Camp i norra Stranglethorn Vale och söker allianshjältar som kan sätta stopp för den dolda ondska som fördärvade Kurzen."},sec={{t="Fördärvets källa",b="Trots att Kurzen har fallit insisterar Brother Nimetz på att den främsta orsaken bakom upproret finns kvar. Hans efterforskningar pekar på Mai'Zoth, en ogremagiker som bor i en ogreboplats djupt inne i de östra höjderna i Stranglethorn Vale. Nimetz är säker på att Mai'Zoth använde sinnesförändrande trolldom för att förvrida Kurzens tankar. Han varnar för att om ogren får leva kan ännu en befälhavare falla offer för samma lömska inflytande."},{t="Säkra reliken",b="För att undanröja hotet för gott ombeds du döda Mai'Zoth, ta Mind's Eye från honom och föra tillbaka den fördärvande artefakten till Rebel Camp."},{t="Efter överlämningen",b="Nimetz välsignar den som kommer med Mind's Eye och tänker studera artefakten för att ta reda på om dess kraft kan användas till något gott. Om det inte går, säger han att den måste förstöras."}},faq={{q="Vem är Mai'Zoth?",a="Mai'Zoth är en ogremagiker som bor i en ogreboplats i de östra bergen i Stranglethorn Vale. Brother Nimetz håller honom ansvarig för att ha fördärvat Colonel Kurzens sinne med lömska förtrollningar.",al={"vem är maizoth","maizoths bakgrund","ogremagikern maizoth"}},{q="Vad är Mind's Eye?",a="Mind's Eye är en artefakt som Mai'Zoth bär på. Den sägs ha magi som kan styra sinnen, och ogremagikern använder den för att fördärva och påverka andra.",al={"mind's eyes bakgrund","vad är artefakten","mind's eye"}},{q="Varför vill Brother Nimetz att Mai'Zoth ska dö?",a="Brother Nimetz fruktar att så länge Mai'Zoth lever kan hans fördärv förvandla någon annan till en ny Kurzen.",al={"nimetz motiv","varför döda maizoth","skäl att jaga maizoth"}}},fp="8,325,24.437.0,18.164.0,18.181.1,16.208.0,23.146.0,44.112.0"}
P.entries["quest:207"] = {n="Kurzen's Mystery",s="Brother Nimetz i Rebel Camp vill veta vad som fick Colonel Kurzen att förfalla. Nimetz misstänker att trollmagi har fått grepp om honom och skickar dig till trollruinerna i Stranglethorn för att kopiera legenderna på fyra tavlor.",h="Brother Nimetz i Rebel Camp vill veta vad som fick Colonel Kurzen att förfalla.",kw={"bal'lal ruins","brother nimetz","colonel kurzen","rebel camp","stranglethorn vale","trolllegend","the vile reef","zul'kunda"},sec={{t="På jakt efter svar",b="Colonel Kurzen var en gång en stor och ädel man, och Brother Nimetz vill ta reda på vad som fick honom att förfalla. Nimetz misstänker att trollmagi har fått grepp om översten. För att pröva den teorin måste de gamla trolllegenderna läsas. De är inhuggna på fyra tavlor som gömts bland trollruinerna i Stranglethorn. Du får i uppdrag att kopiera ristningarna från varje tavla och ta med kopiorna tillbaka."},{t="Där tavlorna finns",b="En tavla står i Bal'lal Ruins. En annan ligger djupt under vattnet utanför kusten, i The Vile Reef, nära en sjunken stad som kontrolleras av Saltscale murlocs. De två sista finns i Ruins of Zul'Kunda."}},faq={{q="Vem inleder sökandet efter trolltavlorna?",a="Brother Nimetz ger uppdraget i Rebel Camp.",al={"vem ger kurzens mysterium","var börjar jag kurzens mysterium","brother nimetz uppdrag"}},{q="Varför vill Brother Nimetz ha kopior av trolllegenderna?",a="Brother Nimetz vill veta varför Colonel Kurzen, som en gång var en stor och ädel man, sjönk ner i förfall. Trollmagi kan ligga bakom, och legenderna på tavlorna kan bekräfta det.",al={"varför behövs trolltavlorna","syftet med kurzens mysterium","varför nimetz vill ha legenderna"}},{q="Var finns de fyra trolltavlorna?",a="En finns i Bal'lal Ruins. En annan ligger djupt under vattnet i The Vile Reef, väster om Grom'gol. Ytterligare två finns i Ruins of Zul'Kunda.",al={"tavlornas platser","var finns tavlorna","kurzens tavlor karta"}},{q="Vad händer när de fyra tavlorna har lämnats tillbaka?",a="Brother Nimetz studerar legenderna för att hitta ett samband mellan trollen och Colonel Kurzens fall, och berättelsen fortsätter med Troll Witchery.",al={"vad händer efter kurzens mysterium","fortsättning på kurzens mysterium","uppdragskedja efter tavlorna"}}},fp="16,224,21.384.0,21.191.0,44.43.0,53.175.0,41.126.0,51.133.0"}
P.entries["quest:2078"] = {n="Gyromast's Revenge",s="Gelkak Gyromast söker hämnd på de lokala murlocerna som plundrade hans förlista skepp utanför Darkshores kust. För att genomföra sin vendetta skickar den excentriske kaptenen äventyrare för att återaktivera sin mekaniska styrman, Threshwackonator 4100.",h="Gelkak Gyromast söker hämnd på de lokala murlocerna som plundrade hans förlista skepp utanför Darkshores kust.",kw={"darkshore","gelkak","golem","gyromast","nyckel","murloc","threshwackonator","threshwackonator 4100"},ang={["faction:Alliance"]="När du röjer undan felande maskiner och aggressiva murlocer blir kustlinjen tryggare för Alliansens resor mellan Auberdine och länderna söderut.",["profession:Engineering"]="Gelkaks mekaniska styrman visar hur beroende en strandsatt kapten är av sin ingenjörsutrustning.",["race:Gnome"]="Gnomer kan känna igen uppdragsnyckeln som ett välbekant sätt att aktivera en mekanisk automat."},sec={{t="En kaptens vendetta",b="Strandsatt på Darkshores dimhöljda stränder vägrar Gelkak Gyromast att acceptera nederlag mot de kustlevande murlocerna. Efter att ha bärgat delarna som behövs för hans planer siktar den excentriske kaptenen på total hämnd mot stammen och dess hövding. I stället för att vada ut i bränningarna med huggaren i hand förlitar sig Gelkak på tung ingenjörskonst för att utkräva sin hämnd och ger en uppdragsnyckel till varje landkrabba som vågar hantera hans mekaniska underordnade."},{t="Styrmannens myteri",b="Gelkaks betrodda styrman är ingen saltstänkt dvärg eller sjöman, utan Threshwackonator 4100, en skramlande mekanisk golem som övergavs i det grunda vattnet söder om vraket. Den uppvridbara automatens löfte om en enkel slakt av murlocer visar sig bedrägligt. När den har dragits upp och letts tillbaka till kaptenen drabbas konstruktionen av ett katastrofalt fel, misstar sin räddare och skapare för fiender och tvingar fram en strid på stranden."}},faq={{q="Vem är Gelkaks styrman?",a="Gelkaks styrman är Threshwackonator 4100, en automatiserad mekanisk golem som står vid kusten söder om den strandsatte kaptenens läger.",al={"styrman","gelkaks styrman","vem är styrmannen"}},{q="Varför vill Gelkak hämnas?",a="Gelkaks skepp förliste utanför Darkshore, och de inhemska Greymist-murlocer rotade igenom vraket och kom undan med en del av hans styrmans nyckel. Gelkak tänker använda sin golem för att krossa stammen och dess hövding.",al={"varför hämnd","murloc-hämnd","gelkaks motiv"}},{q="Vad händer när du för tillbaka Threshwackonator?",a="Aktivera styrmannen med hans nyckel och led honom tillbaka till Gelkak. Vad som händer när den når kaptenen upptäcker du under eskortuppdraget.",al={"threshwackonator anfaller","robotfel","varför anfaller golemen"}},{q="Vad ska jag göra med Gyromast's Key efter uppdraget?",a="Nyckeln aktiverar Threshwackonator. När uppdraget är slutfört har den inget annat syfte.",al={"gyromast's key användning","behålla gyromast's key","kan jag kasta nyckeln"}},{q="Var fick Gelkak tag på Threshwackonator?",a="Golemen är en del av lasten och utrustningen som bärgades från Gelkaks olycksaliga resa längs norra Kalimdor. Den konstruerades som tung mekanisk muskelkraft åt hans besättning.",al={"vem byggde threshwackonator","threshwackonators ursprung"}},{q="Ger Gelkak upp efter att golemen förstörts?",a="Gelkaks planer och hans reaktion på ditt arbete avslöjas när du för tillbaka hans styrman.",al={"vad händer med gelkak","efter gyromast's revenge"}}},fx={a39a7119={q="Varför ber Gelkak dig hämta sin styrman i stället för att gå själv?",a="Gelkak är strandsatt på Darkshores strand efter ett katastrofalt skeppsbrott och helt besatt av att bärga lasten från sitt sjunkna skepp och hämnas på de lokala Greymist-murlocerna. Han har redan bett dig dyka efter de viktiga delarna till sin mekaniska styrman. Nu väntar han vid sin bärgade utrustning och befaller dig, som anställd besättningsman – eller landkrabba, som han kallar dig – att starta apparaten och föra den säkert tillbaka till honom.",al={"varför jag gyromast","varför behöver gelkak hjälp","varför kan gelkak inte hämta golem själv"}}},fp="18,176,20.387.0,23.373.1,27.120.0,29.202.0,54.148.1,59.101.1,42.180.0,49.76.1"}
P.entries["quest:208"] = {n="Big Game Hunter",s="Efter att ha visat sin skicklighet genom att jaga Stranglethorn Vales farligaste rovdjur erbjuder Hemet Nesingwary en sista, överlägsen utmaning. Den berömde prickskytten vill ha huvudet av King Bangalash, en stor vit tiger och själva anledningen till att Hemet över huvud taget befinner sig i djungeln.",h="Efter att ha visat sin skicklighet genom att jaga Stranglethorn Vales farligaste rovdjur erbjuder Hemet...",kw={"bangalash","bhag'thera","big game hunter","hemet nesingwary","sin'dall","stranglethorn vale","tethis","vit tiger"},ang={["class:Hunter"]="Hemet Nesingwary anser att fällandet av King Bangalash är det yttersta beviset på spårnings- och jaktmästerskap."},sec={{t="Mästarens byte",b="När du har klarat expeditionens jägares prövningar och fällt Sin'Dall, Bhag'thera och Tethis erkänner Hemet Nesingwary din stridsförmåga. Veteranen bland prickskyttar, som jämför din skicklighet med de främsta insatserna han sett från Lordaerons slagfält till djungelns djup, säger att bara en jakt återstår för att bevisa att ingen kan mäta sig med dig: att fälla King Bangalash, den väldiga vita tiger som expeditionens ledare egentligen är ute efter."},{t="Ett omtalat odjur",b="Hemet avslöjar att King Bangalash är anledningen till att han befinner sig i Stranglethorn Vale. Det stora odjuret har gång på gång drivit expeditionens ledare själv tillbaka till lägret i nederlag. Om du visar upp odjurets huvud bevisar du att ingen kan mäta sig med din jaktförmåga."}},faq={{q="Vem ger jakten?",a="Hemet Nesingwary själv ger dig jakten i expeditionens läger i norra Stranglethorn Vale när du har slutfört alla tidigare jaktmästerskap.",al={"uppdragsgivare","vem startar big game hunter","hemet nesingwarys uppdrag"}},{q="Vilka jakter måste slutföras först?",a="Du måste slutföra hela lägrets jaktserie: fäll Sin'Dall i Tiger Mastery, Bhag'thera i Panther Mastery och Tethis i Raptor Mastery.",al={"förkunskapskrav","vilka uppdrag kommer före big game hunter","krav för bangalash"}},{q="Varför vill Hemet Nesingwary ha King Bangalash?",a="King Bangalash är hela anledningen till att Hemet reste till Stranglethorn Vale. Den stora vita tigern har gång på gång gäckat honom och drivit veteranen bland prickskyttar tillbaka till lägret.",al={"varför king bangalash","varför jaga bangalash","bangalashs historia"}},{q="Vilket bevis kräver Hemet?",a="Hemet kräver huvudet av King Bangalash för att bekräfta att den stora vita tigern verkligen har fällts.",al={"vilket föremål behöver jag","bangalashs mål","bevis på fällning"}},{q="Var säger Hemet att han har sett strid?",a="Hemet berättar inte om sina egna strider. Han jämför bara din vapenskicklighet med det han har sett på Lordaerons slagfält och djupt inne i djungeln, och säger att han sällan har sett någon bättre.",al={"hemets krigshistoria","hemets förflutna","lordaerons jägare"}}},fp="15,268,19.451.0,15.243.0,20.146.0,47.153.0,46.187.0,30.101.0,47.192.0"}
P.entries["quest:209"] = {n="Skullsplitter Tusks",s="Kebok i Booty Bay behöver material för att möta exportefterfrågan på tigerhuggtänder till South Seas. Eftersom det är för dyrt att jaga riktiga rovdjur i djungeln har han tagit fram en omöjlig att upptäcka förfalskningsmetod med betar från Skullsplitter-trollen.",h="Kebok i Booty Bay behöver material för att möta exportefterfrågan på tigerhuggtänder till South Seas.",kw={"booty bay","förfalskning","kebok","skullsplitter","south seas","stranglethorn","tigerhuggtänder","betar"},sec={{t="Ett lönsamt substitut",b="Det har blivit alltför dyrt och svårt att jaga tigerhuggtänder för försäljning till avlägsna ököpare runt South Seas. I stället för att överge handeln tog Kebok fram en omöjlig att upptäcka förfalskningsmetod som förvandlar vanliga hornliknande föremål till övertygande kopior. De bästa fysiska motsvarigheterna till dessa huggtänder kommer direkt från käkarna på de lokala Skullsplitter-trollen. Därför anlitar Kebok äventyrare som är villiga att ta arton betar från djungelstammen för att fylla hans kommande exportleverans."}},faq={{q="Varför behöver Kebok betar från Skullsplitter?",a="Det har visat sig vara alldeles för dyrt och svårt att jaga tillräckligt många riktiga tigrar för att försörja köpare i South Seas. Kebok upptäckte att trollbetar kan förfalskas till omöjliga att upptäcka kopior av tigerhuggtänder, så att hans handelsverksamhet kan fylla sina månatliga exportorder.",al={"varför skullsplitter-betar","keboks betplan","varför falska tigerhuggtänder"}},{q="Vem köper huggtänderna?",a="De färdiga förfalskade huggtänderna skeppas till handelspartner på olika öar runt South Seas.",al={"vem köper betarna","köpare i south seas","vart skickas huggtänderna"}},{q="Var i Keboks uppdragskedja kommer den här uppgiften?",a="Det här uppdraget följer på Keboks tidigare begäran om Bloodscalp Ears.",al={"vad kommer före skullsplitter-betar","förkunskapskrav för skullsplitter-betar","keboks uppdragsordning"}}},fp="19,262,22.504.0,40.260.0,24.120.0,43.68.0"}
P.entries["quest:2098"] = {n="Gyromast's Retrieval",s="Efter ett skeppsbrott vid Darkshores dimmiga kust söker den excentriske gnompiraten Gelkak Gyromast hjälp med att återställa sin mekaniska styrman. Den viktiga vevnyckeln krossades mot klipporna och plockades upp av traktens djur och murlocer. Att återfinna de tre delarna är första steget mot att få hans besättning i fungerande skick igen.",h="Efter ett skeppsbrott vid Darkshores dimmiga kust söker den excentriske gnompiraten Gelkak Gyromast hjälp med...",kw={"darkshore","styrman","foreststrider","gelkak gyromast","greymist","gyromasts hämtning","pirat","reef crawler","threshadon"},ang={["profession:Engineering"]="Ingenjörer kan uppskatta utmaningen i att hålla urverkskonstruktioner fungerande efter ett våldsamt skeppsbrott i saltvatten.",["race:Gnome"]="Gnomer känner genast igen Gelkaks förkärlek för urverksmaskiner framför besättningsmän av kött och blod, även om piratlivet är ganska ovanligt bland hans folk."},sec={{t="Strandad vid Darkshore",b="Gelkak Gyromast är en märklig syn längs Darkshores dystra stränder: en gnompirat som strandat långt från South Seas vanliga sjövägar. Enligt Gelkak gick hans skepp ett olyckligt öde till mötes strax utanför kusten, efter att ha attackerats och sänkts av aggressiva threshadoner. Han spolades i land bland vrakspillrorna och blev helt strandsatt, skild från sin trogna besättning."},{t="Den bärgade nyckeln",b="Gelkaks mest akuta bekymmer gäller varken proviant eller guld, utan hans styrman. För att aktivera och styra följeslagaren krävs en specialnyckel, som splittrades i tre tydliga delar när Gelkak slog i de klippiga grundbankarna. Innan han hann samla ihop delarna snappade den lokala faunan åt sig dem: skuttande reef crawlers på stranden, resliga foreststriders nära skogen och asätare från den lokala murlocstammen Greymist."},{t="En säregen följeslagare",b="Gelkak talar om sin styrman med en sjökaptens hängivna lojalitet, men hans tal om att behöva få följeslagaren ”i fungerande skick” antyder en ovanlig besättningsmedlem. En gnomisk sjöfarare som strandat på främmande stränder förlitar sig naturligt på mekanisk uppfinningsrikedom, och att sätta ihop den trasiga nyckeln är avgörande för att starta om det urverksunderverk Gelkak släpade upp ur djupet."}},faq={{q="Vem är Gelkak Gyromast?",a="Gelkak Gyromast är en excentrisk gnompirat vars skepp förliste utanför Darkshores kust när rovgiriga threshadoner attackerade och sänkte det.",al={"gelkak gyromast","vem är gnompiraten","gnompirat vid darkshore"}},{q="Vad används nyckeln till?",a="Nyckeln behövs för att återaktivera och dra upp Gelkaks styrman, en mekanisk skapelse som stängdes av under deras katastrofala skeppsbrott.",al={"varför behöver gelkak nyckeln","gelkaks nyckels syfte","styrmannens nyckel"}},{q="Vart tog nyckelns tre delar vägen?",a="När nyckeln gick sönder vid stranden plockades delarna upp av lokala varelser: den översta delen togs av foreststriders, den mittersta av murlocer från Greymist och den nedersta av kustens reef crawlers.",al={"var finns nyckeldelarna","vem stal nyckeln","trasig nyckel darkshore"}},{q="Varför seglade en gnompirat nära Darkshore?",a="Gelkak färdades på vattnen utanför norra Kalimdor i jakt på byte, men fientliga threshadoner satte abrupt stopp för hans resa.",al={"varför är gelkak vid darkshore","pirater vid darkshore"}},{q="Vad händer när nyckeln satts ihop igen?",a="När Gelkak fått alla tre delarna av sin nyckel kan han börja dra upp sin följeslagare, vilket leder direkt vidare till uppdraget ”Gyromast's Revenge”.",al={"vad händer efter nyckeln","fortsättning på gyromasts hämtning"}},{q="Vilka murlocer har nyckeldelen?",a="Den mittersta delen har plockats upp av murlocstammen Greymist, som har bosatt sig bland vraken av sjunkna skepp på grundbankarna utanför Darkshore.",al={"murlocer vid darkshore","greymist murlocnyckel","skeppsbrott murlocer"}}},fx={["460afe34"]={q="Varför vill Gelkak Gyromast få sin nyckel återställd?",a="Gelkak Gyromast led skeppsbrott utanför Darkshores kust när threshadoner sänkte hans skepp. Han blev strandsatt, omgiven av fientliga varelser och är i desperat behov av att få sin mekaniska styrman i fungerande skick igen, så att den kan försvara honom och hjälpa honom hämnas på varelserna som satte stopp för hans resa. Utan de tre splittrade delarna av uppdragningsnyckeln är hans urverkskamrat helt livlös.",al={"varför vill gelkak ha nyckeln","gelkak gyromasts motiv","varför hjälpa gelkak"}},["234cb20d"]={q="Varför behöver Gelkak Gyromast din hjälp?",a="Gelkak är en skeppsbruten pirat utan besättning och utan vänner bland de lokala nattalverna. Han överlevde nätt och jämnt när skeppet sjönk och han spolades iland, mörbultad på stranden. Han är inte i skick att slåss mot de grymma revkryparna, foreststriders och murlocerna som kom över de trasiga nyckelfragmenten.",al={"varför behöver gelkak mig","varför kan gelkak inte hämta nyckeln","varför jag gyromast"}}},fp="20,243,21.244.0,17.361.0,20.176.1,23.108.0,25.113.0,41.151.0,46.104.0,42.104.1,42.122.0"}
P.entries["quest:21"] = {n="Skirmish at Echo Ridge",s="I Northshire Valley går rekryter till angrepp mot kobolder i Echo Ridge Mine. Marshal McBride beordrade anfallet efter att spanare fann gruvan översvämmad av kobolder.",h="I Northshire Valley går rekryter till angrepp mot kobolder i Echo Ridge Mine.",kw={"echo ridge","echo ridge mine","elwynn","kobold","arbetare","marshal mcbride","mcbride","northshire","skärmytsling","stormwind-armén"},ang={["class:Warrior"]="Som krigare möter du svärmar av koboldarbetare på nära håll, bland de första fienderna du möter som håller marken.",["faction:Alliance"]="Som medlem av Alliansen hjälper du till att återta gruvor med sten och malm för att återuppbygga och befästa mänskliga bosättningar efter kriget.",["profession:Mining"]="Som gruvarbetare bidrar du till att det blir möjligt att säkert bryta och smälta värdefulla mineralådror i Northshire Valley.",["race:Human"]="Som människa är rensningen av Echo Ridge ditt första riktiga vapentest i försvaret av ditt förfäders kungarike. Du bevisar ditt mod för Stormwinds officerare."},sec={{t="Rensa gruvan",b="Marshal McBride skickar rekryter mot kobolderna i Echo Ridge Mine. Spanare fann gruvan översvämmad, och garnisonen fruktar att varelserna stärker sitt grepp om de lämnas ifred. Kobolderna gräver genom tunnlarna, samlar stulna resurser och förökar sig. Rekryterna måste minska deras antal för att skydda Northshire Valley, med dess gårdar och andliga tillflyktsort."},{t="Ett tunt försvar",b="Nya rekryter skickas in i gruvan eftersom Stormwind-armén är hårt ansträngd. Garnisonens styrkor bevakar de södra gränserna, medan rykten säger att oroligheter råder i Elwynn. Officerare som McBride måste kalla in frivilliga. En rekryt som visar sig pålitlig vid Echo Ridge vinner arméns respekt och är redo för svårare uppgifter på andra håll i kungariket."}},faq={{q="Varför härjar kobolder i Echo Ridge Mine?",a="Kobolder dras till tunnlar rika på mineraler och övergivna stenbrott. När Stormwinds styrkor är hårt ansträngda kan de ta sig in på obevakade platser som Echo Ridge, gräva hålor, samla guld på hög och ta underjordiska skydd i besittning.",al={"varför kobolder i gruvan","kobolder i echo ridge","vad gör kobolder"}},{q="Vem beordrar skärmytslingen?",a="Marshal McBride beordrar skärmytslingen. Han för befäl över Stormwind-arméns styrkor vid Northshire Abbey och leder dalens försvar med begränsade trupper.",al={"vem ger skärmytslingsuppdraget","marshal mcbride beordrar"}},{q="Vilken strategisk betydelse har Echo Ridge Mine?",a="Echo Ridge Mine innehåller sten och malm som behövs för att underhålla Northshire och hjälpa till att återuppbygga Stormwind. Kobolder vid Northshires norra gräns hotar klostret och vingårdarna i närheten.",al={"varför echo ridge är viktigt","echo ridge mines betydelse"}},{q="Vart leder uppdraget härnäst?",a="När de första koboldarbetarna har rensats ut ur gruvan skickar Marshal McBride dig mot Goldshire för att hjälpa till med områdets försvar.",al={"vilket uppdrag efter skärmytslingen","nästa steg efter echo ridge"}},{q="Varför rensar inte Stormwind-armén gruvan själv?",a="Stormwinds styrkor har ont om soldater. De försvarar avlägsna gränser och svarar på banditangrepp i hela Elwynn. McBride förlitar sig på nya rekryter mot lokala hot, medan erfarna vakter håller försvarslinjerna.",al={"varför rekryter","var finns stormwinds soldater"}},{q="Är kobolder tillräckligt intelligenta för att utgöra ett organiserat militärt hot?",a="Koboldarbetare är fega och trögtänkta på egen hand, men revirhävdande och aggressiva i stora grupper. Om de lämnas ifred gräver de slingrande tunnlar, gillrar fällor i grottor och lockar till sig större ohyra med bättre vapen.",al={"är kobolder smarta","hur farliga är kobolder"}}},fx={a391cdc3={q="Varför vill Marshal McBride att kobolderna i Echo Ridge Mine ska utrotas?",a="Marshal McBride vet att kobolderna får allt starkare fäste i Northshire ju längre de lämnas ifred i Echo Ridge Mine. Om de lämnas ostörda kan de befästa sina positioner ytterligare och hota dalen. Då blir det mycket blodigare att driva bort dem senare, och säkerheten vid Northshire Abbey kan också äventyras.",al={"varför döda kobolder i echo ridge","mcbrides motiv i echo ridge","varför rensa echo ridge mine"}}},fp="22,140,16.357.0,14.348.0,46.214.0,24.153.0,52.176.0,34.132.0,57.206.0,66.198.0"}
P.entries["quest:210"] = {n="Krazek's Cookery",s="Corporal Kalebs mekaniska kokkärl, köpt av en goblinhandlare i Booty Bay, var ett underverk tills det gick sönder. Kaleb ber dig ta det tillbaka till goblinen Krazek för reparation.",h="Corporal Kalebs mekaniska kokkärl, köpt av en goblinhandlare i Booty Bay, var ett underverk tills det gick...",kw={"booty bay","corporal kaleb","kokkärl","krazek","stranglethorn vale"},sec={{t="Ett trasigt kokkärl",b="Corporal Kaleb sköter det mesta av matlagningen i lägret. Det var ett tungt arbete tills Kaleb köpte ett mekaniskt kokkärl av en goblinhandlare i Booty Bay, och kokkärlet sparade Kaleb timme efter timme. Sedan gick det sönder. Krazek's Crock Pot måste tillbaka till goblinen Krazek för att lagas, och Kaleb hoppas att du bär dit det."},{t="Krazek undersöker det",b="Krazek kallar kokkärlet ett genialiskt hantverk, även om det ibland har en tendens att skjuta ut en fjäder eller få ett kugghjul att slira. När Krazek undersöker det upptäcker hen att ångladdaren är genomrostad, knogpackningen har spruckit och fobulatorn saknar tänder. Krazek kan laga det, men det kostar, som det alltid gör."}},faq={{q="Vem skickar dig till Krazek?",a="Corporal Kaleb, som sköter det mesta av matlagningen i lägret, skickar dig. Det mekaniska kokkärl som Kaleb köpte har gått sönder.",al={"vem ger krazek's cookery","vem startar krazek cookery","uppdrag från corporal kaleb"}},{q="Var hittar man Krazek?",a="Krazek är goblinhandlaren i Booty Bay som sålde kokkärlet till Kaleb.",al={"var finns krazek","krazeks plats","krazek booty bay"}},{q="Vad vill Corporal Kaleb att du bär till Krazek?",a="Ett mekaniskt kokkärl som heter Krazek's Crock Pot, som gick sönder efter att ha besparat Kaleb mycket arbete.",al={"vad är krazek's crock pot","vad ska jag ta med till krazek"}},{q="Varför köpte Kaleb ett kokkärl av Krazek?",a="Kaleb sköter det mesta av matlagningen i lägret, och kokkärlet sparade Kaleb många timmar tills det gick sönder.",al={"varför mekaniskt kokkärl","kalebs kokkärl"}}},fp="16,175,12.312.0,19.293.1,24.116.0,26.67.0,48.104.0,44.101.0"}
P.entries["quest:2118"] = {n="Plagued Lands",s="Plagued Lands är ett Alliance-uppdrag som ges av Tharnariun Treetender i Darkshore. För att hejda den spridande korruptionen som drabbar traktens djurliv ber Tharnariun äventyrare att fånga en rabiessmittad taggbjörn levande med hjälp av en förtrollad relik, i ett försök att bota den.",h="Plagued Lands är ett Alliance-uppdrag som ges av Tharnariun Treetender i Darkshore.",kw={"cleansing of the infected","darkshore","plagued lands","rabiessmittad taggbjörn","tharnariun treetender","tharnariun's hope","taggbjörn"},ang={["class:Druid"]="Druiderna delar Tharnariuns sorg när de ser naturen korrumperas, och björnens tragiska död visar hur lömsk och djup landets spridande sjukdom är.",["faction:Alliance"]="Alliance-resenärer som färdas genom norra Kalimdor måste hantera en otämjd korruption som tränger ända fram till gränsen för de bebodda områdena.",["race:NightElf"]="För Kaldorei är det en skymf mot Cenarius och naturens balans, som de svurit att skydda, att se Darkshores inhemska växter och djur förfalla till rabiessmittat vansinne."},sec={{t="En farsot i vildmarken",b="En ondskefull åkomma sprider sig genom Darkshores skogar och förvandlar bestarna till vansinniga, aggressiva skuggor av sitt forna jag. Traktens taggbjörnar har drabbats värst och fallit offer för ett rabiessmittat raseri som hotar både förbipasserande resenärer och kustens sköra ekologiska balans. Där nattalvernas vaktposter ofta svarar med stål söker druiderna förstå och läka grundorsaken."},{t="Tharnariun's Hope",b="Tharnariun Treetender vägrar slakta de korrumperade bestarna utan att försöka rädda dem och har skapat en specialfälla som kallas Tharnariun's Hope. Äventyrare placerar anordningen på skogsmarken och använder dess lugnande ljus för att tillfälligt stilla en rasande taggbjörns sinne. När björnen väl lugnat sig följer den fogligt med resenären tillbaka till Tharnariuns utpost för undersökning."},{t="Tragisk medicin",b="När en äventyrare lyckas leda en smittad björn till lägret försöker Tharnariun genast driva ut sjukdomen med läkande magi. Tyvärr får hans första försök katastrofala följder: de virvlande renande krafterna överväldigar det försvagade djuret, som faller ihop och dör på fläcken. Misslyckandet visar hur djupt den mörka farsoten har fått fäste."}},faq={{q="Vem ger uppdraget Plagued Lands?",a="Uppdraget ges av Tharnariun Treetender, en nattalvdruid i Auberdine i Darkshore som vill bota det drabbade djurlivet.",al={"uppdragsgivare plagued lands","tharnariun darkshore uppdrag","vem startar plagued lands"}},{q="Vad går Plagued Lands ut på?",a="Du måste använda föremålet Tharnariun's Hope för att fånga och lugna en rabiessmittad taggbjörn i Darkshore och sedan leda den lugnade björnen tillbaka till Tharnariun levande.",al={"målet med plagued lands","vad gör man i plagued lands","hur fångar man björn i darkshore"}},{q="Vad händer med björnen när du tar tillbaka den?",a="Tharnariun försöker rena djuret med läkande magi, men sjukdomen har gått för långt. Ansträngningen blir för mycket för björnen, som dör direkt efter behandlingen.",al={"dör björnen","resultat av tharnariuns björnbot","björnens död plagued lands"}},{q="Vilket föremål använder du för att fånga björnen?",a="Tharnariun ger dig en förtrollad fälla som heter Tharnariun's Hope. Den avger ett lugnande ljus som stillar den rasande björnen, så att den följer efter dig.",al={"fälla plagued lands","föremålet tharnariun's hope","björnbur darkshore"}},{q="Vilket uppdrag följer efter Plagued Lands?",a="Plagued Lands är den första delen i en kedja med tre uppdrag. När du slutför det låses uppföljningsuppdraget Cleansing of the Infected upp, vilket så småningom leder till det sista uppdraget, Tharnariun's Hope.",al={"nästa uppdrag efter plagued lands","uppdragskedjan plagued lands","tharnariuns uppföljning"}},{q="Varför är taggbjörnarna rabiessmittade?",a="En krypande, korrumperande farsot sprider sig över Darkshore, förgiftar de lokala djurens sinnen och kroppar och driver ädla taggbjörnar till tanklös aggression.",al={"varför är björnar sjuka i darkshore","darkshores farsot bland björnar","korruption i darkshore"}}},fx={bbb593c2={q="Varför vill Tharnariun Treetender att du fångar en rabiat tistelfläderbjörn?",a="En mörk sjukdom sprider sig genom Darkshore och tar kontroll över det lokala djurlivets sinnen och kroppar. Tistelfläderbjörnarna har drabbats hårdast och förvandlats från ädla skogsdjur till vansinniga förstörelsemaskiner. Tharnariun Treetender tror att han kan ha kommit på ett botemedel, men behöver få ett levande, rabiat exemplar till sig för att pröva sin kur och hejda fördärvet innan det drabbar alla skogens varelser.",al={"varför fånga en tistelfläderbjörn","tharnariuns motiv i plagued lands","varför vill tharnariun ha en björn"}},["1b7f183c"]={q="Vad är rabiata tistelfläderbjörnar, och varför jagar du dem?",a="Tistelfläderbjörnar är rovdjur som hör hemma i Darkshores skogar och vanligtvis vördas som ståndaktiga och ädla bestar. Men en onaturlig smitta har nyligen drabbat dem och drivit dem till vansinne och förvridit deras sinnen. Du skickas efter dem för att inte döda dem direkt, utan för att locka fram och lugna ett sjukt exemplar med Tharnariuns fälla, så att det kan undersökas i hopp om att hitta ett motgift.",al={"vad är rabiata tistelfläderbjörnar","varför jaga rabiata tistelfläderbjörnar","rabiat tistelfläderbjörn i darkshore"}}},fp="13,204,26.310.0,17.299.0,15.272.1,34.125.0,39.114.0,48.154.1,41.127.0,33.85.0,32.130.0"}
P.entries["quest:213"] = {n="Hostile Takeover",s="Gelriz har trängt undan de magnater som handelsfurstarna utsett och ger sig nu på den mest ökända piraten av alla. Baron Revilgaz tänker inte tolerera det. Som svar skickar Kebok i Booty Bay äventyrare för att stjäla märkliga blå kristaller som geologer från Venture Company hittat nära Lake Nazferiti.",h="Gelriz har trängt undan de magnater som handelsfurstarna utsett och ger sig nu på den mest ökända piraten av...",kw={"booty bay","gelriz","gigglefont","kebok","lake nazferiti","revilgaz","trumlad kristall","venture company"},sec={{t="En affärsangelägenhet",b="Gelriz har gått över gränsen genom att köra undan magnater som handelsfurstarna utsett och ge sig på den mest ökända piraten av alla. Baron Revilgaz tänker inte tolerera sådan fräckhet och säger åt Kebok att hantera intrånget som han finner lämpligt. Kebok väljer att stjäla rakt av och siktar in sig på de märkliga blå stenar som Venture Companys gruvlag grävt fram."},{t="Geologernas gömma",b="Geologer från Venture Company som arbetar kring Lake Nazferiti har blivit mycket intresserade av de här ovanliga kristallerna. Kebok vill att du hämtar tillbaka åtta prover till Booty Bay. Han bryr sig inte om hur du får tag på dem, bara de hamnar i hans händer."},{t="Ett omvälvande fynd",b="När proverna undersöks visar det sig att de har trumlats, vilket tyder på att Venture Company tänker använda dem som bränsle eller industriell katalysator. Kebok tänker skicka prover till Head Chemist Gigglefont för en mer ingående undersökning."}},faq={{q="Vem ger uppdraget Hostile Takeover?",a="Kebok, som håller till i piratnästet Booty Bay i Stranglethorn Vale, ger det här uppdraget på uppdrag av Baron Revilgaz.",al={"uppdragsgivare för hostile takeover","vem startar hostile takeover","kebok-uppdrag"}},{q="Varför är Baron Revilgaz arg på Gelriz?",a="Gelriz körde undan magnater som handelsfurstarna hade utsett och har nu gett sig på den mest ökända piraten, något Revilgaz inte tänker tolerera.",al={"varför är revilgaz arg","konflikten mellan gelriz och revilgaz","varför vill kebok ha kristaller"}},{q="Var finns kristallerna?",a="Kristallerna bärs av geologer från Venture Company som arbetar kring Lake Nazferiti.",al={"var hittar man trumlade kristaller","plats för trumlad kristall","kristaller vid lake nazferiti"}}},fp="16,324,20.384.0,21.241.0,20.261.1,37.127.0,40.158.0,31.85.0"}
P.entries["quest:2138"] = {n="Cleansing of the Infected",s="Cleansing of the Infected är ett Alliance-uppdrag i Darkshore som ges av Tharnariun Treetender i Auberdine. När hans försök att bota skogens sjukdom misslyckas beordrar vårdaren motvilligt att de rabiata tistelsbjörnarna som strövar omkring i den dimmiga vildmarken ska avlivas. Det markerar en bitter vändpunkt där bevarandet får ge vika för begränsning.",h="Cleansing of the Infected är ett Alliance-uppdrag i Darkshore som ges av Tharnariun Treetender i Auberdine.",kw={"auberdine","rening","darkshore","smittad","rabid thistle bear","tharnariun","treetender"},ang={["class:Druid"]="Druider som vördar vildmarkens björnandar finner Tharnariuns befallning särskilt gripande: det är en barmhärtig handling och en nödåtgärd för skogen, inte vanlig jakt.",["class:Hunter"]="Jägare förstår att det ibland är nödvändigt att gallra bland sjuka rovdjur för att skydda det större ekosystemet, även när den bakomliggande orsaken förblir olöst.",["race:NightElf"]="För kaldorei är det en tung börda att beordra slakten av fördärvade bestar, vilket visar hur djupt efterkrigstidens korruption har trängt in i deras förfäders hemland."},sec={{t="En bitter nödvändighet",b="Tharnariun Treetender har ägnat långa timmar åt att söka efter ett botemedel mot den smygande sjukdom som fördärvar Darkshores djurliv. Trots sitt försök att rena en tillfångatagen björn är tistelsbjörnarna fortfarande svårt sjuka och våldsamma. Efter att ha uttömt sina mildare alternativ drar nattalvsvårdaren slutsatsen att det enda omedelbara sättet att hindra bestarna från att slita andra varelser i stycken och sprida sjukdomen vidare i de uråldriga skogarna är att avliva dem."},{t="Att hålla vildmarken i schack",b="Att avliva tjugo rabiata björnar är en plågsam plikt för varje naturens tjänare. Tharnariun medger öppet att dödandet inte botar den underliggande pesten, men det köper värdefull tid åt Auberdines försvarare. Tills den främsta källan till skogens fördärv kan identifieras och undanröjas är det enda skyddet för bosättningen att minska de aggressiva hjordarna."}},faq={{q="Varför vill Tharnariun att tistelsbjörnarna dödas i stället för att botas?",a="Tharnariun försökte tidigare rena en tillfångatagen björn, men botemedlet misslyckades och besten dog. Eftersom de sjuka björnarna blir våldsamma och hotar andra varelser är dödandet en sista utväg för att bromsa sjukdomens spridning.",al={"varför döda björnarna","varför inte bota björnarna","tharnariuns björnuppdrag"}},{q="Vem är Tharnariun Treetender?",a="Tharnariun är en nattalvsvårdare som är stationerad i Auberdine. Han studerar de sjukdomar som drabbar Darkshores växt- och djurliv och strävar efter att bevara naturens balans mot den spridande korruptionen.",al={"tharnariuns roll","vem ger cleansing of the infected"}},{q="Gör det någon skillnad för pesten att döda de rabiata björnarna?",a="Nej. Tharnariun varnar uttryckligen för att dödandet av de rabiata björnarna inte stoppar pesten. Det ger bara skogen och Auberdines invånare dyrbar tid genom att bromsa smittan och våldet.",al={"löser detta problemet i darkshore","är pesten botad"}},{q="Vad händer efter Cleansing of the Infected?",a="När du återrapporterar till Tharnariun ber han dig att förbereda din själ på mer blodsutgjutelse och erbjuder uppföljningsuppdraget Tharnariun's Hope för att fortsätta bekämpa det fördärvade djurlivet.",al={"nästa uppdrag efter cleansing","vad följer efter cleansing of the infected"}},{q="Var finns de rabiata tistelsbjörnarna?",a="Rabiata tistelsbjörnar strövar omkring i kust- och inlandsskogarna i centrala Darkshore. De hittas ofta bland de dimmiga tallarna söder och öster om Auberdine.",al={"plats för rabiata tistelsbjörnar","var finns björnar i darkshore"}},{q="Vad fick tistelsbjörnarna att bli rabiata?",a="Björnarna har drabbats av en mystisk smitta som sveper genom skogarna i norra Kalimdor och förvandlar fredligt djurliv till ursinniga, aggressiva bestar som står emot Tharnariuns försök att bota dem.",al={"varför är björnarna sjuka","björnsjuka i darkshore"}}},fx={acd0862d={q="Vad är rabiata tistelfläderbjörnar, och varför måste de dödas?",a="Tistelfläderbjörnar är rovdjur som hör hemma i skogarna och vanligtvis lever i harmoni med Darkshores vildmark. Men en krypande, onaturlig pest sprider sig genom skogen och har gjort många av dem rabiata och våldsamt förvirrade. I sitt förgiftade vansinne angriper de andra djur, hotar resande nära Auberdine och ödelägger skogens ekologi. Försöken att bota dem har misslyckats, så det enda sättet att hejda förödelsen är att avliva dem.",al={"rabiata tistelfläderbjörnar","vilka är de rabiata tistelfläderbjörnarna","varför döda rabiata tistelfläderbjörnar"}}},fp="25,222,18.324.0,20.303.1,67.199.0,29.187.0,53.174.0,43.165.0,40.128.0,42.195.0"}
P.entries["quest:2139"] = {n="Tharnariun's Hope",s="Tharnariun's Hope är den dystra avslutningen på Tharnariun Treetenders försök att hejda djursjukdomen i Darkshore. Efter att ha avlivat många smittade bestar i skogarna får en Alliance-hjälte i uppdrag att döda den rabiata Den Mother nordost om Auberdine.",h="Tharnariun's Hope är den dystra avslutningen på Tharnariun Treetenders försök att hejda djursjukdomen i...",kw={"auberdine","bashal'aran","cleansing of the infected","darkshore","den mother","rabid thistle bear","tharnariun treetender","tharnariun's hope"},ang={["class:Druid"]="Druider hyser stor andlig vördnad för björnar genom Ursocs lära. Att döda en fördärvad Den Mother är en allvarlig påminnelse om naturens sköra balans och de tragedier som följer av fördärv.",["class:Hunter"]="Jägare förstår tragedin i att ett topprovdjur drivs till vansinne av sjukdom. De vet när avlivning av ett smittat djur är den sannaste handlingen av barmhärtighet.",["faction:Alliance"]="Genom att skydda Auberdine stärker Alliance sitt fotfäste längs norra Kalimdors kust och visar sig berett att försvara nattalvernas marker mot allt större hot från vildmarken.",["race:NightElf"]="För nattalver går det emot deras grundläggande vördnad för naturen att döda skogens djur, särskilt en björnmatriark. Därför är plikten en bitter och sorglig nödvändighet."},sec={{t="En tragisk nödvändighet",b="Efter tredje kriget började Darkshores vilda djur falla offer för en onaturlig, rabiat sjukdom. Tharnariun Treetender, stationerad i Auberdine, ägnade dagar åt att ge resenärer i uppdrag att avliva smittade bestar och därmed lindra skogens plåga. Men att gallra bland rabiata tistelsbjörnar behandlade bara symptomen. För att hejda spridningen insåg han att källan bland traktens björnar måste undanröjas: matriarken som kallades Den Mother."},{t="Den Mother",b="Den Mother höll till i en grotta nordost om Auberdine, nära de uråldriga ruinerna i Bashal'Aran, och var en gång en viktig väktare för skogens djurliv. Den vansinnesframkallande åkomman som spred sig över norra Kalimdor hade tagit henne i sitt grepp, och hon födde och fostrade ständigt kullar av rabiata ungar. Genom att jaga matriarken i hennes lya satte Alliance-hjältar stopp för hennes lidande och hejdade strömmen av ursinniga björnar som strök omkring längs kustvägen."},{t="Kalimdors bistra verklighet",b="När Den Mother dör uttrycker Tharnariun djup tacksamhet, men den grumlas av vemod. För kaldorei är det en plågsam plikt att höja vapen mot skogens djur. Men medan mörka krafter hotar deras nya hem och många misströstar eller söker skydd visar sådana handlingar att Auberdines försvarare är villiga att bära den tunga moraliska börda som krävs för att skydda vildmarken."}},faq={{q="Vem är Tharnariun Treetender?",a="Tharnariun Treetender är en nattalvsvårdare stationerad i Auberdine. Han är förtvivlad över den farsot och det vansinne som förvrider Darkshores djurliv och leder arbetet med att studera, spåra upp och till sist befria lidande djur från deras plågor.",al={"tharnariun","vem ger tharnariun's hope","treetender auberdine"}},{q="Var finns Den Mother?",a="Hon håller till i en grotta bland kullarna nordost om Auberdine, strax öster om ruinerna i Bashal'Aran.",al={"var finns den mother","den mothers grotta","hitta den mother"}},{q="Varför måste Den Mother dödas i stället för att botas?",a="Åkomman som härjar bland Darkshores djur sitter djupt och driver aktivt bestarna till våldsamma vansinnesutbrott. Eftersom det inte finns något botemedel och Den Mother fortsätter att föda upp rabiata ungar insåg Tharnariun att det enda sättet att stoppa sjukdomens fortsatta spridning var att avliva henne.",al={"kan den mother räddas","varför döda den mother","bota den mother"}},{q="Vilka uppdrag leder fram till Tharnariun's Hope?",a="Det här uppdraget är det sista steget i en kedja med tre delar. Den börjar med 'Plagued Lands', fortsätter med 'Cleansing of the Infected' och avslutas med 'Tharnariun's Hope'.",al={"förkunskapskrav för tharnariun's hope","tharnariuns uppdragskedja"}},{q="Vad gör djuren i Darkshore sjuka?",a="Tharnariun nämner ingen källa. Han vet bara att en sjukdom sprider sig över Darkshore och griper tag i både kropp och sinne hos alla den drabbar. Tistelsbjörnarna har drabbats hårdast.",al={"varför är björnar rabiata i darkshore","orsaken till djurplågan i darkshore","vad fördärvade björnarna"}},{q="Varför nämner Tharnariun att folk flyr till befästa områden?",a="Auberdine är en utsatt kustutpost som plågas av spöken, förvildade djur och fientliga varelser. Nattalvernas samhälle kämpar med att återuppbyggas efter den brinnande legionens invasion, och en del invånare känner sig överväldigade och väljer att gömma sig eller dra sig tillbaka mot tryggare Alliance-fästen.",al={"fly från auberdine","befästa alliance-marker"}}},fx={f873ab28={q="Vem är Den Mother?",a="Den Mother är en enorm, fördärvad björn som har sitt bo i en grotta nordost om ruinerna av Bashal'Aran. Hon är källan till de rabiata tistelfläderbjörnar som hemsöker området, antingen genom att föda dem eller hysa dem. Om du dödar henne stoppas tillströmningen av sjuka bestar som hotar Auberdine.",al={"vad är den mother","vem är den mother","den mother i darkshore"}}},fp="17,246,18.389.0,14.412.1,28.341.0,29.234.0,32.107.0,51.266.0,41.140.0,45.185.0,63.267.0"}
P.entries["quest:214"] = {n="Red Silk Bandanas",s="Red Silk Bandanas är ett uppdrag från Scout Riell på Folkets milis vägnar. Det skickar alliansens äventyrare till The Deadmines för att jaga högt uppsatta Defias-agenter och ta med deras karakteristiska röda sidenmasker som bevis.",h="Red Silk Bandanas är ett uppdrag från Scout Riell på Folkets milis vägnar.",kw={"the deadmines","defias brotherhood","moonbrook","folkets milis","röda sidenbandanas","scout riell","vancleef","westfall"},ang={["class:Rogue"]="Defias röda sidenmasker står för en ökänd tradition inom den undre världens hantverk och utmärker erfarna strupskärare och hemliga konspiratörer.",["faction:Alliance"]="Varje officer som fälls i The Deadmines försvagar Brotherhoods järngrepp om Konungariket Stormwinds kornbod.",["profession:Tailoring"]="Fint rött siden är en dyr lyx för vanliga banditer, vilket understryker hur överdådigt utrustat och finansierat Brotherhoods ledarskap verkligen är."},sec={{t="En hierarki i tyg",b="Medan vanliga ficktjuvar och stråtrövare i hela Westfall knyter grovt rött tyg runt ansiktet, upprätthåller Defias Brotherhood en strikt intern hierarki som visas genom tyget. Scout Riell och Folkets milis har upptäckt att vanliga banditer bär grov väv, medan högt uppsatta konspiratörer och agenter i den innersta kretsen utmärks av fint rött siden. Att ta deras bandanas riktar sig direkt mot de erfarna officerare som samordnar Edwin VanCleefs uppror."},{t="Slå mot kärnan",b="Eftersom siden visar rang samlas flest av dessa högt uppsatta laglösa djupt inne i The Deadmines under Moonbrook. Vaktposter och spejare vid Sentinel Hill förlitar sig på frilansande hjältar för att tränga in i de omstridda underjordiska tunnlarna. Varje sidenbandana som återtas innebär en löjtnant mindre som organiserar bakhåll, försvarar vapengömmor eller upprätthåller VanCleefs styre i hela Westfall."}},faq={{q="Varför bär Defias röda bandanas?",a="Den röda bandanan är Defias Brotherhoods gemensamma emblem och kännetecken i Stormwinds områden. Den döljer deras identiteter och visar samtidigt deras trohet till Edwin VanCleefs upprorsrörelse.",al={"vad betyder defiasmasken","varför röda masker","defiasuniform"}},{q="Vad gör de röda sidenbandanorna speciella jämfört med vanliga bandanor?",a="Enligt Scout Riell visar tyget vilken status man har inom Brotherhood. Vanliga gatubusar bär grovt, billigt material, medan veteraner, officerare och betrodda löjtnanter tilldelas rött siden.",al={"varför rött siden","defias siden jämfört med tyg","skillnad på sidenbandana"}},{q="Vem är Scout Riell?",a="Scout Riell är en agent som tjänar Folkets milis i Westfall. Hon har i uppgift att spåra Defias rörelser och leda äventyrare till anfall mot deras fästen kring The Deadmines.",al={"scout riell westfall","vem ger uppdraget med röda sidenbandanas"}},{q="Var finns Defias som bär sidenbandanas?",a="De är samlade i och kring The Deadmines under staden Moonbrook, där Edwin VanCleefs högt uppsatta styrkor leder verksamheten under jord.",al={"var hittar man sidenbandanas","sidenbandanas plats i deadmines"}},{q="Vad är Folkets milis?",a="Folkets milis är en frivillig försvarsstyrka som bildats av Gryan Stoutmantle och Westfalls hårt ansatta bönder för att skydda sina marker efter att Stormwinds armé misslyckats med att tillhandahålla tillräckligt många garnisoner.",al={"vilka är folkets milis","folkets milis westfall"}},{q="Har de här bandanorna någon annan användning än som bevis på en dödad fiende?",a="För Folkets milis fungerar de bara som obestridliga bevis på att högt uppsatta laglösa har eliminerats, vilket försvagar Brotherhoods befälsstruktur.",al={"kan man bära röd sidenbandana","vad används bandanorna till"}}},fx={["09c03d28"]={q="Varför vill Scout Riell att Defias-bandelier samlas in?",a="Scout Riell vill utdela ett avgörande slag mot Defias Brotherhoods ledning på Folkets milis vägnar. Milisen vet att silkebandelierna tillhör högt uppsatta officerare, inte vanliga busar. Genom att undanröja dessa nyckelpersoner och kräva deras bandelier som bevis hoppas Riell slå sönder brödraskapets befälsstruktur och äntligen återta Westfall åt dess folk.",al={"varför vill scout riell ha bandelier","scout riells motiv","varför samla röda silkebandelier"}},["762e9a74"]={q="Vilka ska du ge dig på?",a="Du jagar Defias Brotherhoods elitofficerare och veteraner, som är stationerade i och kring Edwin VanCleefs fäste i The Deadmines. Till skillnad från de råbarkade stråtrövarna som härjar på Westfalls gårdar vaktar dessa högt uppsatta medlemmar brödraskapets bas, övervakar de dolda arbetena djupt under Moonbrook och styr syndikatets verksamhet i hela regionen.",al={"vem jagar vi","mål för röda silkebandelier","vem tappar silkebandelier"}},["966e78fe"]={q="Varför ber Scout Riell dig i stället för Stormwinds vakter?",a="Stormwind har i stort sett övergett Westfall och ger nästan inget militärt stöd, medan adelsrådet ignorerar den växande krisen. Folkets lokala milis är hårt pressad och saknar manskap, träning och resurser för att genomföra ett frontalangrepp mot befästa brottsnästen. Riell och hennes spejare måste förlita sig på dugliga äventyrare för att ta sig in i de förrädiska The Deadmines och konfrontera brödraskapets ledning direkt.",al={"varför inte stormwinds armé","varför skicka en äventyrare","varför behöver de mig"}}},fp="17,159,20.358.0,17.317.0,36.169.0,70.169.0,19.162.0,51.151.0,29.197.0,57.146.0"}
P.entries["quest:215"] = {n="Jungle Secrets",s="Efter att ha räddats från ett bakhåll i norra Stranglethorn Vale berättar Private Thorsen varför han åter tog värvning bland Kurzen's män. Han skickar dig tillbaka till Rebel Camp så att hans befälhavare kan bekräfta hans hemliga avsikter.",h="Efter att ha räddats från ett bakhåll i norra Stranglethorn Vale berättar Private Thorsen varför han åter tog...",kw={"doren","kurzen","rebel camp","stranglethorn","thorsen","förrädare","yohwa"},ang={["faction:Alliance"]="Rebel Camp är beroende av de välbehövliga underrättelser som Private Thorsen hoppas kunna hämta från Kurzen's män."},sec={{t="Ett hemligt uppdrag",b="Efter räddningen medger Private Thorsen att situationen ser illa ut och ber om att få förklara. Han hävdar att Lieutenant Doren beordrade honom att åter ta värvning bland Colonel Kurzen's män för att samla in underrättelser som upproret desperat behöver. Det som verkade vara en chans att infiltrera Kurzen's Compound gick snabbt åt skogen, så Thorsen hänvisar dig direkt till Doren i Rebel Camp för en officiell bekräftelse och ber dig samtidigt att hålla saken helt hemlig."},{t="Misstankar i lägret",b="Lieutenant Doren bekräftar att Thorsen verkligen handlade på hans order. Rebellerna var en gång fanatiskt lojala mot Kurzen, tills Kurzens korruption förvandlade lojaliteten till vrede. Om Thorsens kontakter avslöjades skulle hans egna kamrater skära halsen av honom. Eftersom bara Doren, Sergeant Yohwa och Thorsen skulle känna till planen tyder det misslyckade bakhållet på en oroande sanning: en okänd förrädare finns bland dem."}},faq={{q="Varför träffade Private Thorsen Kurzen's styrkor?",a="Han följde Lieutenant Dorens order att åter ta värvning bland Colonel Kurzen's män som spion och samla in viktiga militära underrättelser åt rebellerna.",al={"varför träffade thorsen kurzen","är thorsen en förrädare","varför var thorsen utanför lägret"}},{q="Vart skickar Private Thorsen dig?",a="Han ber dig tala med Lieutenant Doren vid Rebel Camp i norra Stranglethorn Vale, så att befälhavaren kan bekräfta hans berättelse.",al={"vart ska jag gå","lämna in thorsen-uppdraget","var finns doren"}},{q="Varför insisterar Thorsen på att hålla det hemligt?",a="Rebellerna var en gång fanatiskt lojala mot Colonel Kurzen. Om det kom ut att Thorsen hade haft kontakt med Kurzen's män kunde han dödas i nattens mörker.",al={"varför hålla det hemligt","varför ett hemligt uppdrag"}},{q="Vad händer efter att du rapporterat till Lieutenant Doren?",a="Efter samtalet med Lieutenant Doren leder ditt sökande vidare till nästa steg, Bookie Herod.",al={"nästa uppdrag","vad följer efter jungle secrets"}}},fp="14,218,20.446.0,18.442.1,53.152.0,36.134.0,35.152.0,47.102.0"}
P.entries["quest:2158"] = {n="Rest and Relaxation",s="Rest and Relaxation är ett introduktionsuppdrag för Alliansen som leder nyutbildade äventyrare från Northshire söderut längs vägen till Lion's Pride Inn. Den livliga tavernan i Goldshire drivs av Innkeeper Farley och erbjuder mat, dryck och en varm härd åt den som söker vila från vägen.",h="Rest and Relaxation är ett introduktionsuppdrag för Alliansen som leder nyutbildade äventyrare från...",kw={"taverna för alliansen","elwynn forest","goldshire","innkeeper farley","lion's pride inn","northshire","rest and relaxation"},ang={["faction:Alliance"]="Lion's Pride Inn är den främsta fristaden och samlingsplatsen för Alliansens resenärer som ger sig ut i Elwynn Forest.",["race:Human"]="Nya rekryter som lämnar Northshire Valley följer naturligt vägen söderut mot Goldshire, där Innkeeper Farley erbjuder välbekant gästfrihet nära Stormwind."},sec={{t="En fristad längs vägen",b="Efter sina första prövningar i Northshire hänvisas trötta resenärer söderut mot Lion's Pride Inn i Goldshire. Vägen söderut leder direkt till den omtyckta tavernan, som drivs av Innkeeper Farley. För nya äventyrare som ger sig ut i den större skogen är den den första större utposten med härd, skydd och varma måltider bortom klostret."},{t="Farleys härd och gästfrihet",b="Innkeeper Farley är stolt över gästfriheten på sitt värdshus och följer mottot att erbjuda vila och avkoppling åt de trötta och frusna. Äventyrare som nämner sin rekommendation kan dra nytta av Farleys välvilja och slå sig ner vid den öppna elden för att njuta av en varm måltid, gott öl och en välbehövlig paus innan de fortsätter genom Elwynn Forest."}},faq={{q="Var hittar jag Lion's Pride Inn?",a="Lion's Pride Inn ligger söderut längs huvudvägen från Northshire Valley, mitt i staden Goldshire. Resenärer på väg söderut kan inte missa den välkomnande tavernan.",al={"var ligger lion's pride inn","hur tar jag mig till lion's pride inn","hitta lion's pride inn"}},{q="Vem är Innkeeper Farley?",a="Innkeeper Farley är den gästfria ägaren till Lion's Pride Inn i Goldshire. Som nära vän till lokala kontakter i Northshire välkomnar han trötta äventyrare med mat, dryck och en varm härd.",al={"vem är innkeeper farley","farley på lion's pride inn"}},{q="Vad är syftet med Rest and Relaxation?",a="Rest and Relaxation leder nybörjaräventyrare som lämnar Northshire till Goldshires centrala knutpunkt och introducerar dem till servicen, förfriskningarna och logiet som Innkeeper Farley erbjuder på Lion's Pride Inn.",al={"vad är syftet med uppdraget","varför gå till lion's pride inn"}},{q="Erbjuder Innkeeper Farley verkligen mat och dryck till rabatterat pris?",a="Om du nämner din rekommendation för Innkeeper Farley kan du fråga om särskilda rabatter på värdshusets fina mat och dryck medan du återhämtar dig efter resan.",al={"rabatt på lion's pride inn","får jag billigare mat hos farley"}},{q="Varför är vila viktig för äventyrare på resa?",a="Att färdas genom Elwynn Forest är ansträngande och fullt av faror. Värdshus erbjuder en trygg plats att ta skydd från vildmarken, värma sig vid elden, återhämta sig och fylla på förråden innan man tar sig an nya uppgifter.",al={"varför behöver äventyrare vila","lore om rest and relaxation"}},{q="Vad är mottot för Lion's Pride Inn?",a="Enligt Innkeeper Farley är värdshusets motto ”Vila och avkoppling åt de trötta och frusna.” Han gör sitt bästa för att varje utmattad gäst ska finna tröst och gästfrihet vid hans härd.",al={"vad är mottot för lion's pride inn","lion's pride inns slogan"}}},fp="19,288,19.349.0,31.355.0,38.197.0,24.198.0,43.211.0,61.173.0,48.230.0,42.179.0"}
P.entries["quest:2159"] = {n="Dolanaar Delivery",s="Dolanaar Delivery är ett ärende som anförtros unga Night Elf när de lämnar Shadowglens skyddade grenar för Teldrassils vidsträckta skogar. Porthannius, som är upptagen med angelägenheter bland de lokala druiderna, ber resenärer bära ett paket örter söderut till Innkeeper Keldamyr. Den enkla resan markerar en novis övergång till Dolanaars livliga centrum.",h="Dolanaar Delivery är ett ärende som anförtros unga Night Elf när de lämnar Shadowglens skyddade grenar för...",kw={"leverans","dolanaar","dolanaar delivery","örter","innkeeper keldamyr","night elf","porthannius","shadowglen","teldrassil"},ang={["class:Druid"]="Porthannius upptagenhet med Shadowglens druider antyder de djupare andliga plikter och rubbade naturbalanser som upptar Cenarion Circle bland grenarna.",["profession:Herbalism"]="Leveransen visar hur viktiga de råa örterna från Shadowglens frodiga jordar är för helarna, kockarna och omsorgsgivarna i Dolanaar.",["race:NightElf"]="Att ta sig an uppdraget markerar en Night Elfs avfärd från Aldrassils skyddade vagga och början på de större plikterna att värna Teldrassil."},sec={{t="En budbärare för Shadowglen",b="Innan nya äventyrare lämnar Shadowglens träningsplatser söker Porthannius efter någon som ska följa vägen mot resten av Teldrassil. Han är upptagen med brådskande ärenden hos druiderna som vårdar gläntan och kan inte själv komma ifrån för att uträtta vanliga ärenden. I stället lägger han en bunt nyskördade örter i händerna på en blivande hjälte, så att viktiga förnödenheter kommer söderut längs skogsstigen."},{t="Vägen till Dolanaar",b="Följer du den södra vägen ut ur den avskilda dalen kommer du till Dolanaar, en av de främsta bosättningarna för Night Elf i Teldrassils mäktiga grenar. Där ansvarar Innkeeper Keldamyr för gästfrihet, vila och förnödenheter åt vandrare, väktare och druider. När Keldamyr tar emot örterna på Porthannius vägnar passar han på att uppmana unga äventyrare att vila både sinne och själ innan de möter den växande korruptionen i världsträdet."}},faq={{q="Vem är Porthannius?",a="Porthannius är en Night Elf som bor i Shadowglen, Teldrassils startglänta. Han arbetar nära de lokala druiderna och ber resenärer som lämnar gläntan att föra förnödenheter söderut åt honom.",al={"porthannius","vem ger dolanaar delivery","uppdragsgivare porthannius"}},{q="Varför kan inte Porthannius leverera örterna själv?",a="Porthannius har brådskande, oavslutade ärenden med Shadowglens druider. Hans plikter håller honom upptagen i den skyddade dalen, så han måste förlita sig på äventyrare som passerar för att göra resan söderut.",al={"varför behöver porthannius hjälp","varför kan porthannius inte gå"}},{q="Vad finns i paketet?",a="Paketet innehåller örter som samlats i Shadowglen och ska användas på värdshuset i Dolanaar.",al={"innehållet i dolanaar delivery-paketet","vad är örterna"}},{q="Vem är Innkeeper Keldamyr?",a="Innkeeper Keldamyr sköter värdshuset i Dolanaar. Förutom att erbjuda gästfrihet, logi och härdstenar åt resenärer samordnar han ofta handel och utbyte av förnödenheter med andra bosättningar runt om i Teldrassil.",al={"keldamyr","värdshusvärd i dolanaar","vem tar emot örterna"}},{q="Var ligger Dolanaar?",a="Dolanaar ligger söder om Shadowglen. Följer du huvudvägen från gläntans utgång kommer du rakt in i stadens centrum.",al={"var ligger dolanaar","dolanaars läge","vägbeskrivning till dolanaar"}},{q="Varför är den här leveransen viktig för unga äventyrare?",a="Den introducerar världen utanför Shadowglen och uppmuntrar noviser att lämna träningsplatserna och upptäcka Dolanaars värdshus, tränare och tjänsteleverantörer.",al={"leveransens betydelse","varför leverera örter"}}},fx={e1815add={q="Varför behöver Porthannius få paketet levererat till Dolanaar?",a="Porthannius har förberett ett viktigt knippe färska örter från Shadowglen, som Innkeeper Keldamyr väntar på nere i Dolanaar. Men brådskande uppgifter håller Porthannius sysselsatt med de lokala druiderna, så han kan inte själv ge sig av längs vägen. För att värdshusvärden ska få de nödvändiga förnödenheterna utan dröjsmål förlitar han sig på en resande som är på väg ut i Teldrassil.",al={"porthannius leveransmotiv","varför skicka örter till dolanaar","syftet med dolanaar delivery"}}},fp="17,193,26.367.0,20.385.0,19.181.0,48.152.0,27.78.0,26.190.0,26.118.0,53.169.0"}
P.entries["quest:2160"] = {n="Supplies to Tannok",s="Supplies to Tannok är ett ärende som anförtrotts åt oerfarna äventyrare på väg från Coldridge Valley genom det farliga bergspasset in i större Dun Morogh. Gnommekanikern Hands Springsprocket skickar en låda med nödvändiga förnödenheter till Tannok Frosthammer på värdshuset Thunderbrew Distillery i Kharanos. Därmed undviker han de troggfyllda stigarna som har brutit den vanliga handeln.",h="Supplies to Tannok är ett ärende som anförtrotts åt oerfarna äventyrare på väg från Coldridge Valley genom...",kw={"anvilmar","coldridge pass","hands springsprocket","kharanos","supplies to tannok","tannok frosthammer","thunderbrew","troggar"},ang={["faction:Alliance"]="När handeln mellan isolerade utposter återupprättas hålls Ironforges försörjningsleder inåt landet öppna trots troggarnas vilda anfall.",["race:Dwarf"]="Att bära förnödenheter från Anvilmar till Kharanos markerar din övergång från den skyddade dalen till tjänst för det större kungariket Ironforge.",["race:Gnome"]="När du hjälper Hands Springsprocket visar du det pålitliga samarbetet mellan Gnomeregan Exiles och deras dvärgvärdar i Dun Morogh."},sec={{t="En avspärrad dal",b="Coldridge Valley är traditionellt en prövningsplats och fristad för unga dvärgar från Ironforge och landsflyktiga överlevare från Gnomeregan, men de senaste händelserna har försvagat dess förbindelse med resten av Dun Morogh. Troggarnas anfall har översvämmat Coldridge Pass och gjort bergsklyftan farlig att ta sig igenom. Bergsvakterna är utspridda och har fullt upp med att skydda bosättningar och försvarslinjer, vilket försenar planerade eskorter med förnödenheter i flera dagar."},{t="Hands och värdshusbiträdet",b="Hands Springsprocket, en gnom som väntar vid mynningen till Coldridge Pass, har fått en låda med viktiga värdshusförnödenheter avsedda för Kharanos, men saknar ett säkert sätt att själv leverera den. Han inser att modiga äventyrare redan förbereder sig för att trotsa det farliga passet och ber resenärer på väg ut att bära lasten till Tannok Frosthammer, biträdet på det livliga värdshuset Thunderbrew."},{t="En välkomnande härd i Kharanos",b="När äventyraren når Kharanos kliver hen ut i den större världen i Dun Morogh. Tannok Frosthammer tar ivrigt emot leveransen och berättar att det har kommit få nyheter från Anvilmar ända sedan troggarna störde resandet genom passet. Leveransen återupprättar en skör förbindelse och handel mellan de två isolerade dvärgsamhällena."}},faq={{q="Vem är Hands Springsprocket?",a="Hands Springsprocket är en företagsam gnom som är posterad vid mynningen till Coldridge Pass i Coldridge Valley. Eftersom han inte kan ta sig igenom det farliga bergspasset ensam förlitar han sig på dugliga resenärer för att transportera varor till Kharanos.",al={"hands springsprocket","uppdragsgivare","vem ger förnödenheter till tannok"}},{q="Vem är Tannok Frosthammer?",a="Tannok Frosthammer är värdshusbiträde på Thunderbrew Distillery i Kharanos. Han hjälper till att sköta den lokala värdshusverksamheten och tar emot förnödenheter från utposter som Anvilmar.",al={"tannok","tannok frosthammer","värdshusbiträde i kharanos"}},{q="Varför kan inte Hands leverera förnödenheterna själv?",a="Passet mellan Coldridge Valley och Kharanos har översvämmats av fientliga troggar. Hands är inte rustad att ensam kämpa sig igenom, och de officiella eskorterna från bergsvakterna är kraftigt försenade.",al={"varför kan inte hands leverera den","varför behövs en äventyrare","varför är passet farligt"}},{q="Var ligger värdshuset i Kharanos?",a="Tannok Frosthammer finns inne på Thunderbrew Distillery, det stora värdshuset mitt i Kharanos längs huvudvägen österut mot Ironforge.",al={"var finns tannok","var ligger thunderbrew distillery","var ligger värdshuset i kharanos"}},{q="Vad finns i Crate of Inn Supplies?",a="Lådan innehåller viktiga förnödenheter och småsaker för värdshuset, insamlade i Anvilmar för att fylla på lagren på värdshuset Thunderbrew i Kharanos.",al={"vad finns i lådan","crate of inn supplies"}},{q="Varför har kommunikationen mellan Anvilmar och Kharanos brutits?",a="Troggar som kommit upp ur underjordiska tunnlar har översvämmat Coldridge Pass. Deras aggressiva närvaro har gjort det svårt att färdas till fots och brutit de regelbundna budförbindelserna mellan Coldridge Valley och resten av Dun Morogh.",al={"varför kommer få nyheter från anvilmar","troggproblem i passet"}}},fx={["6d15a4f4"]={q="Varför vill Hands Springsprocket att förnödenheterna levereras till Kharanos?",a="Hands Springsprocket lovade att leverera viktiga förnödenheter till Tannok Frosthammer, assistenten på värdshuset i Kharanos, men troggangrepp har stängt passet ut ur Coldridge Valley. De vanliga leveranserna har fastnat, och bergsvakterna är flera dagar bort. Tannok får vänta oroligt medan förråden sinar. Hands vill hålla sitt löfte och se till att både det livliga Thunderbrew Distillery och värdshuset har tillräckligt med varor för trötta resenärer.",al={"varför skicka förnödenheter till tannok","hands springsprockets motiv","varför leverera crate of inn supplies"}}},fp="18,251,18.360.0,35.286.0,30.302.0,28.192.0,26.136.0,45.193.0,37.129.0,41.104.0,59.178.0"}
P.entries["quest:2161"] = {n="A Peon's Burden",s="Ukor väntar på stigen utanför Valley of Trials med en last han inte kan bära hem. Rekryterna i den röda ravinen tackade nej till hans förnödenheter, och nu ber han resande att ta dem tillbaka till Razor Hill.",h="Ukor väntar på stigen utanför Valley of Trials med en last han inte kan bära hem.",kw={"durotar","mat","innkeeper grosk","peon","razor hill","förnödenheter","ukor","valley of trials"},ang={["faction:Horde"]="Du lämnar prövningsmarkerna och beger dig till Razor Hill, navet för Hordens försvar och logistik i södra Durotar.",["race:Orc"]="Den orciska kulturen sätter värde på fysisk styrka och mod, vilket lämnar peoner som Ukor längst ned i samhällshierarkin. Genom att hjälpa honom med leveransen visar du hur enkelt arbete håller den unga nationen Durotar igång."},sec={{t="En leverans på villovägar",b="Ukor gav sig av från Razor Hill med förnödenheter åt de nya rekryterna som tränar i den röda ravinen. Han trodde att de behövde maten, men instruktörerna skickade bort honom. De håller förråden små eftersom de tror att knappa ransoner lär unga Horde-krigare disciplin och uthållighet. Innkeeper Grosk förklarar senare att den här prövningen är en del av deras träning."},{t="Faror i den röda ödemarken",b="Ukor nådde passet, men fruktar återresan över Durotar. Scorpider, giftiga spindlar och strövande vildsvin hemsöker den steniga stigen. Han har varken vapen eller rustning och saknar stridsviljan som förväntas av en orcisk fotsoldat. Han väntar längs vägen och ber resande som lämnar prövningsmarkerna att bära hans tunga förnödenheter tillbaka till värdshuset i Razor Hill."}},faq={{q="Vem är Ukor?",a="Ukor är en välmenande men försagd orcisk arbetare som väntar längs vägen ut från Valley of Trials. Han gav sig av från Razor Hill för att leverera förnödenheter, men insåg sedan att han var alltför rädd för traktens djurliv för att ensam klara återresan.",al={"ukor","vem är peonen på vägen","peon nära valley of trials"}},{q="Varför ville tränarna i Valley of Trials inte ha maten?",a="Uppsyningsmännen anser att disciplin är viktig för nya rekryter. Innkeeper Grosk förklarar att instruktörerna håller de tränande hungriga för att pröva deras mod och stärka deras kampvilja, så Ukors leverans var inte välkommen.",al={"varför tacka nej till maten","varför bar ukor mat","innkeeper grosk svält"}},{q="Vart ska leveransen?",a="Bär förnödenheterna norrut längs Durotars huvudväg till Razor Hill och lämna dem sedan till Innkeeper Grosk på värdshuset i bosättningen.",al={"var ligger razor hill","vem ska jag ge maten till","vart ska ukors börda levereras"}},{q="Vad gör resan farlig för en peon?",a="Revirhävdande scorpider, giftiga spindlar och vildsvin strövar omkring i Durotars steniga ödemarker. Ukor är en obepansrad arbetare utan träning, medan erfarna rekryter kan ta hand om sådant ohyra.",al={"varför är ukor rädd","faror längs vägarna i durotar"}},{q="Vilken roll har peonerna i Horde?",a="Peoner står längst ned i det orciska samhället och utför enkla arbeten, som att bära förråd, hugga timmer och bygga befästningar. Fotsoldater och mästare får beröm och ära, medan peoner ofta glöms bort trots att de ser till att bosättningarna får mat och hålls i skick.",al={"orcers peonhistoria","peonernas status","vad är peoner"}},{q="Vem är Innkeeper Grosk?",a="Innkeeper Grosk driver värdshuset i Razor Hill och sköter stadens logi och förråd. Han erbjuder mat, dryck och en härd åt resande krigare och påminner rekryterna om att vila innan de möter den större världen.",al={"innkeeper grosk","grosk razor hill","värdshusvärd razor hill"}}},fx={["777a74e1"]={q="Varför vill Ukor att maten levereras tillbaka till Razor Hill?",a="Ukor ville verkligen väl när han bar förnödenheter från Razor Hill och hoppades hjälpa de unga rekryter som tränar under den skoningslösa solen i Valley of Trials. När tränarna avvisade ransonerna insåg han att han inte bara kunde överge maten eller låta den förfaras längs vägen. Maten hör hemma i Innkeeper Grosks skafferi, men efter att nätt och jämnt ha överlevt färden förbi områdets skorpider och spindlar är Ukor livrädd för att ensam ge sig tillbaka.",al={"varför lämna tillbaka maten","ukors motiv","varför ge mat till grosk"}},fe82ef3c={q="Varför ber Ukor dig bära bördan i stället för att göra det själv?",a="Ukor är en vanlig arbetare, ovan vid våld och obeväpnad mot vildmarken. Han lyckades ta sig förbi skorpionerna och spindlarna på vägen från Razor Hill, men skräcken inför att möta de vilda rovdjuren igen har fått honom att stelna till. När han ser dig komma segrande från Valley of Trials ser han en duglig hjälte som inte fruktar något, och hoppas att du gärna bär bördan på din väg till Razor Hill.",al={"varför kan ukor inte bära den","varför jag i a peon's burden","varför ber ukor mig"}}},fp="15,197,20.356.0,23.352.0,12.235.0,62.210.0,36.141.0,44.180.0,39.273.0,23.207.0"}
P.entries["quest:217"] = {n="In Defense of the King's Lands",s="In Defense of the King's Lands kulminerar i ett direkt angrepp mot ledarna för trogginvasionen i Loch Modan. Dvärgspanare spårar den våldsamma plågan till Chieftain Grawmug och hans brutala livvakter djupt inne i Stonesplinter Valley. Captain Rugelfuss ger modiga äventyrare från Alliansen i uppdrag att döda hövdingen, knäcka troggernas stridsmoral och återta rikets södra gränser.",h="In Defense of the King's Lands kulminerar i ett direkt angrepp mot ledarna för trogginvasionen i Loch Modan.",kw={"brawler","gnasher","grawmug","king's lands","loch modan","rugelfuss","stonesplinter","trogg"},ang={["faction:Alliance"]="Att försvara Loch Modan bevarar den viktiga landförbindelsen mellan Ironforge och de östra gränstrakterna och håller försörjningslinjerna säkra för alla styrkor i Alliansen.",["race:Dwarf"]="För dvärgarna handlar det om att försvara hembygden och äran att driva bort troggerna från Khaz Modans uråldriga jord, så att deras bergsfästen förblir fria från underjordiska plågor."},sec={{t="Svärmen mister sitt huvud",b="Det ihärdiga hotet från trogger i södra Loch Modan har visat sig vara mer än ett slumpmässigt krypande under jord. Captain Rugelfuss spanare upptäckte att troggerna i Stonesplinter leds av en hövding vid namn Grawmug. Till skillnad från vanliga kringströvande plundrare anfaller den här gruppen samordnat och aggressivt, och hotar att översvämma King's Lands om den inte hejdas. Genom att ta striden till deras lya och döda Grawmug tillsammans med hans personliga slagskämpar hoppas dvärgens försvarare kunna bryta gruppens sammanhållning och hejda floden."},{t="In i Stonesplinter Lair",b="Grawmug håller stånd i en skuggig grotta inbäddad i de sydöstra klipporna i Stonesplinter Valley. Omgiven av sina mest betrodda bestar, Gnasher och Brawler, är hövdingen en farlig motståndare för ensamma soldater. När den inre kretsen faller kastas de återstående troggerna in i oordning. Det ger de hårt ansatta Mountaineers den chans de så desperat behöver för att befästa vägarna och driva bestarna tillbaka ner i mörkret."}},faq={{q="Vem är Grawmug?",a="Grawmug är den våldsamma trogg-hövding som samlar troggerna i Stonesplinter i södra Loch Modan. Dvärgspanare identifierade honom som hjärnan bakom de organiserade anfallen som plågar dalen. Han har alltid två mäktiga livvakter, Gnasher och Brawler, vid sin sida.",al={"grawmugs historia","vem är troggernas ledare","hövding grawmug"}},{q="Var finns Grawmug och hans vakter?",a="Grawmug, Gnasher och Brawler har förskansat sig i en grotta vid den sydöstra kanten av Stonesplinter Valley i Loch Modan. De håller till tillsammans långt inne i grottan.",al={"grawmugs plats","var finns grawmug","var hittar man grawmug"}},{q="Vem är Captain Rugelfuss?",a="Captain Rugelfuss är en dvärgofficer stationerad vid Southern Guard Tower i Loch Modan. Han leder försvaret mot de framryckande troggerna och ger order om att skydda King's Lands gränser.",al={"rugelfuss","captain rugelfuss roll","vem ger uppdraget in defense of the king's lands"}},{q="Varför måste Grawmugs vakter också dödas?",a="Gnasher och Brawler är Grawmugs personliga hantlangare och lämnar aldrig hans sida. För att döda hövdingen och definitivt slå sönder ledningen för troggernas anfall måste båda hans tungt bepansrade beskyddare besegras tillsammans med honom.",al={"varför döda gnasher och brawler","gnasher och brawler","grawmugs livvakter"}},{q="Vad händer när Grawmug har dödats?",a="När Grawmug dödas får Loch Modan ett välbehövligt andrum. Utan sin hövding som samordnar räderna tappar troggerna i Stonesplinter sin organisation. Då får den lokala dvärgmilisen en rimlig chans att hålla gränserna och driva bestarna under jord.",al={"följderna av att döda grawmug","troggerna efter grawmugs död","räddade vi loch modan"}},{q="Varför invaderar trogger Loch Modan?",a="Trogger har länge frodats djupt nere i underjordiska kammare under Khaz Modan. Utgrävningar och grottor som öppnats har låtit dem välla upp till ytan, där de aggressivt tränger undan bosättningar och anfaller resande på King's vägar.",al={"varför är trogger här","trogginvasionen i loch modan","troggers ursprung i stonesplinter"}}},fx={["440a3b53"]={q="Varför vill Captain Rugelfuss att Grawmug dödas?",a="Captain Rugelfuss ser Grawmug som hjärnan bakom troggarnas intrång, som hotar Loch Modan. Dvärgarnas garnisoner kämpar för att hålla de underjordiska svärmarna stången. Rugelfuss tror att ett slag mot ledningen – genom att undanröja Grawmug och hans elitsoldater – kan bryta deras framryckning och ge dvärgarna en chans att driva dem tillbaka under jorden.",al={"rugelfuss motiv","varför döda grawmug","syftet med in defense of the kings lands"}}},fp="30,246,22.310.0,23.338.0,15.209.0,41.140.0,25.194.0,43.148.0,41.246.1,35.209.0"}
P.entries["quest:2178"] = {n="Easy Strider Living",s="Easy Strider Living är en lokal matlagningsuppgift som Alanndarian Nightsong erbjuder i Auberdine. Hon vill gärna dela med sig av sitt uppskattade recept på stridergryta, om en äventyrare är villig att jaga de vilda foreststriders som strövar omkring i Darkshore och hämta deras kött.",h="Easy Strider Living är en lokal matlagningsuppgift som Alanndarian Nightsong erbjuder i Auberdine.",kw={"alanndarian nightsong","auberdine","matlagning","darkshore","easy strider living","foreststrider","strider meat","strider stew"},ang={["class:Hunter"]="Foreststriders är både snabba villebråd och möjliga djurföljeslagare. De ger övning i att spåra och jaga längs Darkshores dimmiga stigar.",["profession:Cooking"]="Uppgiften är viktig för kockar som reser genom Darkshore. Som belöning får du receptet på närande Strider Stew, tillagad av det lokala djurlivet.",["race:NightElf"]="Att leva i harmoni med Kalimdor innebär ofta att leva av det landet ger, och mustig stridergryta har blivit en kustfavorit bland nattalverna i Auberdine."},sec={{t="En smak av vildmarken",b="Auberdine må vara en stillsam hamnby, men för att överleva längs kusten måste man ta vara på det lokala djurlivet. Alanndarian Nightsong har tagit fram ett hemligt recept på mustig stridergryta, en smakrik rätt gjord på de höga, snabbfotade foreststriders som jagar genom Darkshores skuggiga skogar. I stället för att bara lämna ut sina matlagningshemligheter ber hon blivande kockar och jägare att ge sig ut och fälla fåglarna själva."},{t="Jakt på foreststriders",b="Foreststriders är snabba fågelrovdjur med vassa näbbar. De strövar omkring i de dimhöljda skogarna och på stränderna norr och söder om Auberdine. De kan vara lynniga och aggressiva när de provoceras, men deras saftiga kött passar utmärkt som bas i en mustig gryta. Färskt kött fyller Alanndarians hungriga gryta och ger jägaren hennes uppskattade recept."}},faq={{q="Vem är Alanndarian Nightsong?",a="Alanndarian Nightsong är en Night Elf som bor i Auberdine i Darkshore. Hon är känd för sin puttrande gryta med striderkött och lär ut sin matlagningskonst till resande som bevisar sin skicklighet som jägare.",al={"alanndarian","vem är alanndarian nightsong","gryta kock auberdine"}},{q="Var hittar jag striderköttet?",a="Striderkött får du genom att jaga foreststriders i Darkshore. De här stora, flygoförmögna fåglarna strövar både längs de sandiga stränderna och i skogsdungarna utanför Auberdine.",al={"var finns striderkött","var finns foreststriders","hur får man striderkött"}},{q="Vad är syftet med det här uppdraget?",a="Uppdraget går ut på att jaga foreststriders och hämta fem köttbitar åt Alanndarian Nightsong, i utbyte mot att få lära dig laga Strider Stew.",al={"varför göra easy strider living","uppdragets syfte","easy strider living mål"}},{q="Är foreststriders farliga att jaga?",a="Foreststriders är revirhävdande fåglar med vassa näbbar och snabba ben, och de blir aggressiva när man närmar sig. En någorlunda välutrustad äventyrare kan dock jaga dem utan större fara.",al={"är striders svåra att döda","foreststrider fara"}},{q="Låser uppdraget upp ett matlagningsrecept?",a="Ja. När du har hämtat köttet Alanndarian bad om delar hon med sig av sina matlagningshemligheter och lär äventyrare receptet på Strider Stew.",al={"får jag ett recept","recept på stridergryta","matlagningsbelöning"}},{q="Var utspelar sig det här uppdraget?",a="Uppdraget börjar och slutar i bosättningen Auberdine, medan jakten sker i vildmarken i Darkshore.",al={"uppdragszon","var finns easy strider living"}}},fx={["64984ff6"]={q="Varför vill Alanndarian Nightsong att detta görs?",a="Alanndarian Nightsong har en tom gryta och är sugen på färsk stridergryta. Innan hon delar med sig av sitt hemliga recept vill hon se om du har mod nog att själv jaga de långbenta fåglarna och hämta färska köttbitar till elden.",al={"alanndarians motiv","varför vill alanndarian ha strider meat","varför strider stew"}},["624f04e5"]={q="Vad används Strider Meat till?",a="Det saftiga köttet är huvudingrediensen i Alanndarians smakrika stridergryta. Om du hämtar fem köttbitar fyller du hennes tomma kittel och visar att du förtjänar att få lära dig hennes hemliga vildmarksrecept.",al={"vad används strider meat till","varför strider meat","användning av strider meat"}}},fp="19,122,19.279.0,26.253.0,29.143.0,33.137.0,34.129.0,41.105.0,40.94.0,33.72.0"}
P.entries["quest:218"] = {n="The Stolen Journal",s="The Stolen Journal är ett tidigt Alliance-uppdrag i Dun Morogh där Grelin Whitebeard skickar äventyrare in i trollgrottan i Coldridge Valley för att återta sin stulna anteckningsbok. För att få tillbaka den måste du besegra den mäktige trollhövdingen Grik'nir the Cold. När Grelin får tillbaka dagboken kan han slutföra sin bedömning av trollhotet i Coldridge Valley.",h="The Stolen Journal är ett tidigt Alliance-uppdrag i Dun Morogh där Grelin Whitebeard skickar äventyrare in i...",kw={"coldridge valley","dun morogh","frostmane hold","frostmane-troll","grelin whitebeard","grik'nir the cold","senir whitebeard","stulen dagbok"},ang={["faction:Alliance"]="Genom att hejda den aggressiva Frostmane-stammen hålls Dun Moroghs startdalar säkra från inre oroligheter.",["race:Dwarf"]="När ledarskapet bland Frostmane-trollen i Coldridge Valley röjs undan skyddas unga dvärgrekryter som tar sina första steg utanför Anvilmar.",["race:Gnome"]="Gnomiska flyktingar som tar skydd i Anvilmar är beroende av att passen i Coldridge Valley är säkra medan de samlar sig på nytt i dvärgarnas land."},sec={{t="En forskares förlorade anteckningar",b="Grelin Whitebeard har hållit uppsikt över Frostmane-trollen som tränger in i Coldridge Valley och noggrant antecknat deras vanor och plötsliga aggression. Under oroligheterna stal en ovanligt reslig troll hans personliga dagbok och flydde in i deras lya. För Grelin är förlusten mer än bara sentimental; anteckningsboken innehåller merparten av hans spaningsuppgifter, och hans officiella bedömning kan inte slutföras förrän den hämtas från grottan."},{t="Konfrontera Grik'nir the Cold",b="Den skyldige är Grik'nir the Cold, ett mäktigt Frostmane-troll med särskiljande kropps- och ansiktsmålningar som håller hov i trollgrottans hjärta. När Grik'nir dödas bryts trollens lokala ledarskap och Grelin får tillbaka sin dagbok. När ledaren är undanröjd känner sig Grelin trygg nog att rapportera att trollen i dalen går att hålla i schack, och skickar sina färdiga rön till sin bror Senir."}},faq={{q="Vem tog Grelin Whitebeard's Journal?",a="Dagboken togs av Grik'nir the Cold, ett stort Frostmane-troll med märkliga märken på huden och i ansiktet, som håller sig gömd djupt inne i trollgrottan.",al={"vem stal dagboken","vem har grelins dagbok","dagbokstjuven"}},{q="Var finns Grik'nir the Cold?",a="Grik'nir the Cold finns inne i trollgrottan i de södra delarna av Coldridge Valley.",al={"var finns griknir","grik'nirs plats","hur hittar man grik'nir"}},{q="Varför är dagboken viktig för Grelin?",a="Dagboken innehåller Grelin Whitebeards anteckningar och rön om trollens aktiviteter i Coldridge Valley. Han behöver få tillbaka den för att sammanställa en fullständig rapport till sin bror Senir.",al={"varför vill grelin ha sin dagbok","vad finns i grelins dagbok"}},{q="Vad händer när du lämnar tillbaka dagboken?",a="När dagboken har återfunnits färdigställer Grelin sin rapport om trollens situation i Coldridge Valley och ber dig överlämna sina iakttagelser till sin bror Senir Whitebeard i Kharanos.",al={"vad händer efter the stolen journal","nästa uppdrag efter stulen dagbok"}},{q="Drivs Frostmane-trollen bort från Coldridge Valley efter det här?",a="Grelin anser att trollen i Coldridge Valley är under kontroll efter Grik'nirs nederlag, men Frostmane-trollen utgör fortfarande ett långvarigt hot i Dun Moroghs större bergspass.",al={"är trollen besegrade i coldridge","är coldridge säkert från troll"}},{q="Vem är Senir Whitebeard?",a="Senir Whitebeard är Grelin's bror, en Alliance-spejare stationerad utanför Coldridge Valley nära Kharanos, som samlar underrättelser om hot mot kungariket.",al={"vem är senir","grelin's bror senir"}}},fx={["78f0c4e3"]={q="Varför vill Grelin Whitebeard att detta görs?",a="Grelin sammanställer en officiell rapport om hotet från Frostmane i Coldridge Valley åt sin bror Senir. Utan sin dagbok kan han inte slutföra sina anteckningar eller bedöma hur säker dalen är, och de lokala ledarna går därmed miste om viktig information om trollens verksamhet.",al={"varför vill grelin ha sin dagbok","grelin whitebeards motiv","varför hämta g relins dagbok"}},beb6a987={q="Varför behöver Grelin att du hämtar hans dagbok?",a="Grelin är observatör, inte frontsoldat, och en mäktig trollbest tog dagboken djupt in i trollgrottan i Coldridge Valley. Han har redan sett dig slå tillbaka trollen i dalen och vänder sig därför till dig för att du ska ta dig in i grottan och hantera faran.",al={"varför behöver grelin mig","varför skicka en äventyrare efter dagboken","varför kan grelin inte hämta sin egen dagbok"}}},fp="18,221,22.407.0,29.423.0,37.154.0,37.87.0,39.145.0,42.180.1,67.172.0,24.160.0"}
P.entries["quest:219"] = {n="Missing In Action",s="Missing In Action är ett eskortuppdrag för Alliansen i Redridge Mountains där Corporal Keeshan ska räddas ur Blackrock-orcernas fångenskap. Efter att hans regemente utplånats i bergen slogs Keeshan medvetslös och släpades till en grottfästning. När den sårade soldaten eskorteras tryggt tillbaka till Lakeshire kan garnisonen bekräfta det dystra ödet för sina försvunna män.",h="Missing In Action är ett eskortuppdrag för Alliansen i Redridge Mountains där Corporal Keeshan ska räddas ur...",kw={"blackrock-orcer","corporal keeshan","eskort","keeshan","lakeshire","marshal marris","missing in action","redridge"},ang={["class:Warrior"]="Att frita Keeshan från ett beväpnat orcläger kräver att du håller frontlinjen mot våg efter våg av skoningslösa Blackrock-angripare och skyddar en omtöcknad kamrat.",["faction:Alliance"]="Lakeshires garnison är pressad till bristningsgränsen, så varje räddad soldat är viktig för kungarikets försvar mot Blackrock-klanen."},sec={{t="Ett regemente övermannat",b="Redridge Mountains har blivit allt farligare när Blackrock-orcerna kommer ned från de nordliga topparna. Stadsvaktens patruller hamnar ofta i bakhåll, och Corporal Keeshans enhet drabbades hårdast. De flesta soldaterna i hans regemente höggs ned på plats när de var i underläge och övermannades. Keeshan överlevde bara för att ett kraftigt slag gjorde honom medvetslös innan han kunde avrättas, så orcerna kunde släpa honom till sin grotta som fånge."},{t="Flykten från grottorna",b="Misshandlad, omtöcknad och fången djupt inne på fiendens område kunde Keeshan inte ta sig nedför berget på egen hand. När du eskorterar honom till tryggheten i Lakeshire måste ni passera oräkneliga orciska krigarskaror som håller till på bergskammarna. Att nå Lakeshire levande blir en välbehövlig lättnad för Marshal Marris, som försöker ta reda på vad som hände med det försvunna regementet samtidigt som han förbereder Lakeshire på fler angrepp."}},faq={{q="Vem är Corporal Keeshan?",a="Corporal Keeshan är en infanterist i Alliansen stationerad i Redridge Mountains. Under en patrull i de klippiga bergen övermannades hans regemente av Blackrock-orcer, och han var den enda kända överlevande innan han släpades bort i fångenskap.",al={"corporal keeshan","vem är keeshan","keeshans historia"}},{q="Var tillfångatogs Corporal Keeshan?",a="Han hålls fången djupt inne i en orcbefängd grotta i Redridges nordliga berg, omgiven av fientliga Blackrock-krigare.",al={"var finns keeshan","keeshans plats","keeshans grotta"}},{q="Vad hände med resten av Keeshans enhet?",a="Enligt Keeshan överföll och övermannade Blackrock-orcerna hans regemente och dödade nästan alla männen under den första skärmytslingen.",al={"keeshans grupp","vad hände med regementet","keeshans män"}},{q="Vem skickar spelare för att rädda Keeshan?",a="Uppdraget börjar direkt hos Corporal Keeshan i hans fängelsegrotta, där äventyrare från Alliansen hittar och befriar honom.",al={"vem startar missing in action","uppdragsgivare","var hämtar man missing in action"}},{q="Vart beger sig Keeshan efter att ha befriats?",a="Han måste eskorteras nedför bergssidan till staden Lakeshire, där han rapporterar till Marshal Marris nära stadens bro.",al={"var lämnar man in missing in action","vart springer keeshan","keeshans destination"}},{q="Varför finns Blackrock-orcerna i Redridge?",a="Blackrock-klanen tränger söderut från sina fästen i Burning Steppes och in i Redridge. De hotar den dåligt befästa bosättningen Lakeshire och överfaller kungarikets patruller.",al={"blackrock-orcer i redridge","varför orcer i lakeshire","blackrock-invasionen"}}},fx={["64cb6fe2"]={q="Varför behöver Corporal Keeshan din hjälp för att fly?",a="Corporal Keeshan är fångad djupt inne på fientligt område efter att hela hans regemente överfölls och slaktades av Blackrock-klanen. Han fick ett hårt slag mot huvudet under striden och är svårt skadad, omtöcknad och i behov av eskort. Utan någon som leder honom förbi de kringströvande orcherna riskerar han att avrättas eller svälta ihjäl i grottan.",al={"varför hjälpa keeshan","keeshans motiv","varför behöver keeshan räddas"}},["1d637b84"]={q="Varför kan Keeshan inte fly på egen hand eller vänta på vakterna från Lakeshire?",a="Keeshan är svårt skadad och behöver hjälp för att kämpa sig förbi Blackrock-rövarna. Samtidigt har Lakeshires försvarare fullt upp med att hålla staden mot gnoller och orcher, så de har inga styrkor att avvara för ett omfattande räddningsuppdrag. När du hittar hans cell är du bokstavligen hans enda hopp om att ta sig levande tillbaka.",al={"varför kan keeshan inte fly själv","varför behöver keeshan mig","varför finns inga stadsvakter"}}},fp="17,266,18.422.0,21.374.0,24.210.0,36.129.0,44.106.0,36.101.0,40.132.0,39.178.0"}
P.entries["quest:22"] = {n="Goretusk Liver Pie",s="På Saldean Farm i Westfall lagar Salma Saldean en paj i svåra tider. Banditer har härjat rikets kornbod, och lokala nybyggare jagar aggressiva vildsvin för att föda sina familjer.",h="På Saldean Farm i Westfall lagar Salma Saldean en paj i svåra tider.",kw={"vildsvin","matlagning","goretusk","leverpaj","saldean farm","salma saldean","westfall"},ang={["faction:Alliance"]="Genom att hjälpa lantliga nybyggare som familjen Saldean stöder du lojala människofamiljer som kämpar för att hålla rikets gränsland utan Stormwinds armé.",["profession:Cooking"]="Salmas rätt speglar lantlig matlagning bland människor. Trädgårdsörter som vitlök, rosmarin och dill förvandlar inälvor från vilt till en vardagsmåltid."},sec={{t="Gästfrihet i gränslandet",b="Westfall var en gång Stormwinds bördiga kornbod, men svåra tider har drabbat landet. Försummade vägar, kringströvande laglösa och igenväxta åkrar gör vardagen till en kamp för de få nybyggare som är kvar. På Saldean Farm arbetar Salma Saldean för att bevara känslan av ett hem trots farorna omkring henne. En traditionell köttpaj är en av få enkla glädjeämnen för nybyggare som försöker bevara sitt sätt att leva."},{t="Westfalls vilda bestar",b="Goretusks strövar omkring på Westfalls slätter i stora skaror. Deras sega hudar och vassa betar gör dem farliga. De hotar ensamma lantarbetare, men ger samtidigt livsviktigt kött åt familjer som saknar regelbunden handel. Salmas recept kräver krossad rosmarin, finhackad vitlök, hackad dill och sjudande sås. Med varsam tillagning blir de härdiga bestarnas fräna inälvor en mustig, smakrik måltid."}},faq={{q="Vem är Salma Saldean?",a="Salma Saldean är en tålig nybyggare som bor med sin make, Farmer Saldean, på deras gård i centrala Westfall. Hennes hemlagade måltider håller humöret uppe trots farorna från banditer och vilda bestar.",al={"salma saldean","vem är salma","saldeans hustru"}},{q="Varför vill Salma ha goretusklever?",a="Salma vill ha goretusklever till sin berömda, smakrika köttpaj, som hon håller på att laga för att dela med sin make. Pajskalet är gräddat och kryddorna är redo; bara levern behövs för att sjuda klart fyllningen.",al={"varför goretusklever","vad innehåller pajen","syftet med leverpajen"}},{q="Var brukar goretusks finnas i Westfall?",a="Goretusks strövar vida omkring på Westfalls gyllene slätter och obrukade åkrar. De bökar i övergivna fält och vandrar längs grusvägarna.",al={"goretusks platser","var hittar man vildsvin","jaga goretusklever"}},{q="Är goretusks farliga för de lokala bönderna?",a="Ja. Goretusks är aggressiva, revirhävdande vildsvin med vassa betar. De hotar boskapen och utgör en betydande fara för oskyddade resenärer på slätterna.",al={"är goretusks fientliga","vildsvinsfara i westfall"}},{q="Varför råder det så stor brist på mat i Westfall just nu?",a="Det råder matbrist eftersom Stormwind ger lite stöd och organiserade banditer plundrar gårdarna. Många bönder har drivits bort från sin mark, och rikets forna kornbod har blivit ett fattigt gränsland.",al={"svält i westfall","varför finns det ingen mat i westfall","svåra tider i westfall"}},{q="Hjälper det Saldean Farm att överleva om man slutför uppgiften?",a="Att samla färskt kött löser inte Westfalls större kriser, men det försörjer familjen Saldean och ger resenärer mättande färdkost inför vägen som ligger framför dem.",al={"spelar pajen någon roll","saldeans matförråd"}}},fx={["3baa4b09"]={q="Vad används Goretusk Liver till?",a="Salma Saldean behöver färsk Goretusk Liver som den sista, avgörande ingrediensen i sin berömda köttpaj från Westfall. Hon har redan gjort den kryddade pajdegen, hackat dill, vitlök och rosmarin och låtit såsen puttra, men saknar själva köttet för att färdigställa familjemåltiden.",al={"vad används goretusk liver till","varför goretusk liver","recept på goretusk liver-paj"}},ad043644={q="Varför ber Salma en äventyrare om hjälp i stället för att själv jaga goretuskerna?",a="Salma har fullt upp med att sköta gården och köket medan familjen Saldean kämpar för att klara de hårda tiderna i Westfall. Vildsvin stryker aggressivt omkring utanför det trygga staketet och den lokala milisen är fåtalig, så hon förlitar sig på dugliga resenärer för att skaffa färskt kött.",al={"varför jag ska hämta goretusk liver","varför behöver salma mig","varför jagar inte salma själv"}}},fp="18,200,20.417.0,23.390.0,21.212.0,36.218.0,48.146.0,45.169.0,44.210.0,56.160.0"}
P.entries["quest:220"] = {n="Call of Water",s="Brines vatten når Islen Waterseer vid The Barrens östra kust, där nästa del av shamanprövningen börjar. Flaskan innehåller vatten som Brine har berett och välsignat, grunden till en sapta som låter en novis se vattenandar i Silverpine Forest.",h="Brines vatten når Islen Waterseer vid The Barrens östra kust, där nästa del av shamanprövningen börjar.",kw={"brine","call of water","islen waterseer","sapta","silverpine forest","the barrens","vial of purest water","water sapta","water totem"},ang={["class:Shaman"]="Som shaman i Horden utför du Call of Water-riterna för att möta andarna och förtjäna Water Totem, som styr läkande och återhämtning.",["faction:Horde"]="Som medlem av Horden reser du från The Barrens i Kalimdor till Silverpine i Lordaeron och korsar länder som hålls av Forsaken under prövningen."},sec={{t="Åter till kusten",b="Efter prövningarna i södra The Barrens ger Brine en shamanlärling en Vial of Purest Water. Vattnet kommer från rena källor och har helgats genom Brines riter. Lärlingen bär det tillbaka till den östra kusten, där Islen Waterseer håller vakt. Vattnet förbinder Brines läror med totemets riter."},{t="Sapta-brygdens syfte",b="Islen förklarar att dödliga inte lätt kan se vattenandar. För att möta dem dricker en lärling en brygd som kallas sapta. Vattnet från Brine blir grunden till den drycken och öppnar shamanens sinnen för det som vanlig syn inte kan urskilja. Att se andarna är bara en del av färden; de kommer att pröva lärlingen."},{t="Överfart till Lordaeron",b="Islen skickar shamanen bortom Kalimdor, över havet till Silverpine Forest, söder om Undercity. Vid en avskild helgedom måste lärlingen dricka sapta och möta elementarerna direkt. Först då kan shamanen förtjäna rätten att framkalla Water Totem."}},faq={{q="Vad finns i Vial of Purest Water?",a="Vial of Purest Water innehåller vatten som samlats från rena källor och helgats genom Brines riter. Det är den nödvändiga grunden för att brygga en sapta, som låter en shaman kommunicera med vattenandar.",al={"vial of purest water","brines vatten","vad gav brine mig"}},{q="Vem är Islen Waterseer?",a="Islen Waterseer är en äldre shaman som bor på The Barrens avskilda sydöstra kust, söder om Ratchet. Hon vägleder hordens shamaner som söker gemenskap med vatten och Water Totem.",al={"islen","vem är islen waterseer","islen waterseers bakgrund"}},{q="Vad är sapta?",a="En sapta är en ceremoniell dryck som shamaniska läromästare bereder. Den förändrar shamanens sinnesintryck och låter hen se och möta elementarandar som är dolda för dödliga.",al={"vad betyder sapta","water sapta","vad gör sapta"}},{q="Varför måste jag åka till Silverpine Forest nu?",a="Helgedomen för denna gemenskap ligger i Silverpine Forests kustvatten, söder om Undercity i Eastern Kingdoms. Andarna där kräver att en shaman möter dem och genomgår en sista prövning innan hen får makt över vattnet.",al={"varför silverpine","silverpine water totem","altare i silverpine"}},{q="Var bor Brine?",a="Brine bor i en avskild hydda i södra The Barrens, högt uppe i kullarna väster om vägen mot The Great Lift och Thousand Needles.",al={"var brine finns","var ligger brine","hitta brine"}},{q="Kan en schaman hoppa över att brygga sapta?",a="Nej. Gemenskapsriterna kräver att shamanens ande är i samklang med den osynliga världen. Utan en sapta som öppnar vägen går det inte att möta eller utmana vattenandarna vid helgedomen.",al={"hoppa över sapta","måste man ha sapta","schamanens synprövning"}}},fx={["5a67c999"]={q="Varför skickar Brine dig tillbaka till Islen Waterseer?",a="Brine har gjort sin del genom att rena vattnet du samlade in på olika platser i Kalimdor och försegla det i en välsignad flaska. Hon vet att hon bara vägleder dig på din väg, inte är siaren som inviger dig i de djupare mysterierna. Islen Waterseer skickade dig till Brine för att pröva din uthållighet, och nu när det renaste vattnet är färdigt är det bara Islen som har visdomen att brygga din sapta och leda den sista prövningen av din gemenskap med andarna.",al={"varför skickar brine dig vidare","brines motiv i call of water","varför återvända till islen"}},["51ede7cd"]={q="Varför behöver Brine att du bär flaskan i stället för att själv lämna den?",a="Den här pilgrimsfärden är din prövning som schaman, inte ett bekvämlighetsärende. Flaskan innehåller vatten som du själv hämtade från vattenhålet nedanför Brines hydda i The Barrens, brunnen vid Tarren Mill och The Ruins of Stardust i Ashenvale, välsignat genom ditt eget arbete. När du bär tillbaka den över slätterna till Islen fullbordar du din personliga förbindelse med elementet innan du försöker tala med andarna.",al={"varför måste jag lämna flaskan","varför jag i call of water för brine","varför kan inte brine ta med den"}}},fp="13,249,19.323.0,24.318.0,23.264.1,40.195.0,23.183.0,16.167.0,46.227.0,22.133.0,39.179.0"}
P.entries["quest:2205"] = {n="Seek out SI: 7",s="I Goldshire skickar Keryn Sylvius nya skurkar till SI: 7. Ett förseglat paket som förs till Stormwind City tar dem inför Master Mathias Shaw, som leder kronans hemliga underrättelsenätverk.",h="I Goldshire skickar Keryn Sylvius nya skurkar till SI: 7.",kw={"goldshire","keryn sylvius","mathias shaw","old town","skurk","seek out si: 7","si:7","stormwind"},ang={["class:Rogue"]="Som skurk tar du dig in i Stormwinds främsta spionagebyrå och går från grändtrick till kunglig spaning.",["faction:Alliance"]="Som medlem av Alliansen förlitar du dig på SI: 7 för att skydda riket mot hot innanför och bortom dess gränser medan kung Varian Wrynn fortfarande är försvunnen."},sec={{t="Ett kurirprov",b="På Lion's Pride Inn i Goldshire slösar skurkarnas tränare Keryn Sylvius ingen tid på att berömma nykomlingar. Hon tycker att nya rekryter ser mer ut som ostbud än hemliga agenter, men ger dem ändå ett förseglat paket att leverera till huvudstaden. Resan prövar deras pålitlighet som kurirer och granskar i tysthet spejare för tjänst i rikets större tjänst."},{t="Bakom stängda dörrar i Old Town",b="SI: 7 verkar från det sydöstra hörnet av Old Town i Stormwind City. Den slitna stadsdelen rymmer högkvarteret för Stormwind Intelligence, Section 7, där Master Mathias Shaw övervakar kungadömets hemliga operationer. Shaw tar emot paketet med torr skepsis och bedömer om resenären har den tuffhet som krävs för verkligt spionage."}},faq={{q="Vad är SI:7?",a="SI: 7 står för Stormwind Intelligence, Section 7. Organisationen leds av Master Mathias Shaw från sitt högkvarter i Old Town och sköter kungariket Stormwinds hemliga underrättelsearbete och operationer.",al={"vad betyder si 7","vad är si7","si:7-lore"}},{q="Vem är Keryn Sylvius?",a="Keryn Sylvius tränar skurkar på Lion's Pride Inn i Goldshire. Hon arbetar med SI: 7, bedömer lokala rekryter och skickar lovande spejare till Master Mathias Shaw i Stormwind City.",al={"keryn sylvius","skurkarnas tränare i goldshire"}},{q="Var befinner sig Mathias Shaw i Stormwind?",a="Master Mathias Shaw befinner sig på övervåningen i SI: 7:s högkvarter, i det sydöstra hörnet av Old Town i Stormwind City, förbi stadens skurktränare.",al={"var är shaw","hitta mathias shaw","var finns mathias shaw"}},{q="Vad händer efter att paketet levererats till Shaw?",a="När du har rapporterat till Mathias Shaw prövar han dina färdigheter som skurk genom att skicka dig till Jerod's Landing för att stjäla ett fraktschema från en Defias-dockmästare.",al={"nästa uppdrag efter seek out si 7","vad vill shaw"}},{q="Varför hånar Keryn spelaren innan hon lämnar över leveransen?",a="SI: 7:s agenter värdesätter skicklighet och skarpa instinkter. Keryn Sylvius behandlar nya rekryter hårt för att bedöma deras temperament och se om de har beslutsamheten att närma sig Master Shaw.",al={"varför förolämpar keryn mig","förolämpningen om ostbud"}}},fx={["5aa3ad9f"]={q="Varför vill Keryn Sylvius att paketet ska levereras till Mathias Shaw?",a="Keryn har formellt åtagit sig att leverera paketet till Master Mathias Shaw som del av ett officiellt uppdrag. Hon verkar tydligt förakta vanliga budärenden, men genom att skicka dig uppfyller hon sin skyldighet gentemot organisationen och prövar samtidigt dina spirande färdigheter som skurk inför sina överordnade i Stormwind.",al={"varför leverera till mathias","keryn sylvius motiv","varför skicka paket till si7"}},["6bd14f9c"]={q="Varför skickar Keryn en oprövad skurk i stället för att själv leverera paketet?",a="Keryn är stationerad i Goldshire för att spana och handleda nya talanger, och har föga lust att själv gå med små leveranser till Old Town. Genom att lämna uppgiften till en ivrig nybörjare som dig slipper hon besväret och får samtidigt pröva om du är skärpt nog att hitta Stormwinds hemliga underrättelsetjänsts högkvarter.",al={"varför skickar keryn mig","varför jag ska söka upp si7","varför levererar hon det inte själv"}}},fp="14,192,16.335.0,31.331.0,13.186.0,21.184.0,43.154.0,50.149.1,64.186.0"}
